// @izdvojeno-iz index.html (cijeli glavni inline blok, sinhrono na istom mjestu)


let _isOfflineMode = false;

// ─── MJERENJE KVALITETA VEZE (pasivno, bez ijednog dodatnog zahtjeva) ────────
// navigator.onLine na terenu LAŽE 'true' na mrtvoj vezi (OS-S4, dokumentovano
// kroz više terenskih prijava) — zato se stanje linka ne POGAĐA iz njega nego
// MJERI iz saobraćaja koji app ionako pravi. reliableFetch je jedini transport
// kroz koji prolazi SVAKI Supabase poziv, pa je mjerenje besplatno i opisuje
// baš ono što korisnik stvarno čeka.
// Tri stanja se razlikuju NAMJERNO, jer traže različitu reakciju korisnika:
//   nema  — ništa ne prolazi (radi se lokalno, sync čeka)
//   slaba — prolazi, ali sporo/sa ispadima (upisi stižu, ali sa zadrškom)
//   dobra — online značajke rade normalno
const _NET_UZORAKA = 12;
const _NET_SVJEZE_MS = 10 * 60 * 1000;  // stariji uzorci ne opisuju trenutni teren
const _NET_SPORO_MS = 2500;             // iznad ovoga je "slaba" i kad uspije
let _netUzorci = [];

function _netZabiljezi(ishod) {
  if (!ishod) return;
  let prije = null;
  try { prije = _netKvalitet(); } catch(e) {}
  // Odziv linka je vrijeme do zaglavlja (ttfb); ukupno trajanje uključuje i
  // veličinu odgovora, pa bi velik uredan odgovor vezu lažno proglasio slabom.
  const ms = ishod.ttfb != null ? ishod.ttfb : ishod.ms;
  _netUzorci.push({ ok:!!ishod.ok, ms:Number(ms) || 0, vrsta:ishod.vrsta || 'ok', t:Date.now() });
  // Neuspjela proba zatvara kratki prolaz odmah. Inače svi zahtjevi iz
  // narednih 20 s koriste već dokazano mrtvu vezu.
  if (!ishod.ok) _netSilaDo = 0;
  if (_netUzorci.length > _NET_UZORAKA) _netUzorci.shift();
  try { _netBadgeSync(); } catch(e) {}
  if ((prije === 'nema' || prije === 'slaba') && ishod.ok && Number(ms) <= _NET_SPORO_MS) {
    // Kvarovi iz mrtvog perioda opisuju vezu koje više nema — da ostanu, stanje
    // bi još do 10 min bilo "slaba" i teški upisi (fotografije) bi čekali bez razloga.
    _netUzorci = _netUzorci.filter(u => u.ok && u.ms <= _NET_SPORO_MS);
    try { _netBadgeSync(); } catch(e) {}
    try { _netVezaVracena(); } catch(e) {}
  }
  try { _netPrimijeniRezim(); } catch(e) {}
}
function _netSvjezi() {
  const sad = Date.now();
  return _netUzorci.filter(u => sad - u.t <= _NET_SVJEZE_MS);
}
function _netMedijanMs() {
  const uspjeli = _netSvjezi().filter(u => u.ok).map(u => u.ms).sort((a, b) => a - b);
  return uspjeli.length ? uspjeli[Math.floor(uspjeli.length / 2)] : null;
}
function _netKvalitet() {
  // Kad OS KAŽE da nema veze, to je pouzdano (laže samo u drugom smjeru).
  if (typeof navigator !== 'undefined' && navigator.onLine === false) return 'nema';
  const u = _netSvjezi();
  if (!u.length) return 'nepoznato';
  const palo = u.filter(x => !x.ok).length;
  if (u.length >= 2 && !u[u.length - 1].ok && !u[u.length - 2].ok) return 'nema';
  // Sve palo, a OS tvrdi da veze ima — to je upravo OS-S4 laž.
  if (palo === u.length) return 'nema';
  const med = _netMedijanMs();
  if (palo > 0 || (med != null && med > _NET_SPORO_MS)) return 'slaba';
  return 'dobra';
}

// ─── ODLUKA: VRIJEDI LI SAD POKUŠATI ONLINE (v1.8.8) ─────────────────────────
// Do sada su online radnje pitale SAMO navigator.onLine, a on na terenu laže
// 'true' na mrtvoj vezi — pa je app i uz izmjereno "nema" slao zahtjev za
// zahtjevom: svaki je visio do roka, pozadinski poslovi su se gomilali, a
// korisnička radnja (novi projekat, ruta, profil terena) je stajala sekundama
// prije nego pređe na lokalni put koji je ionako postojao.
// Pravilo: neobavezna online radnja se radi kad veza to dopušta.
//   'nema'   → ne pokušavaj; ali jednom u _NET_PROBA_MS pusti JEDAN pokušaj —
//              on je proba (bez sintetičkog pinga), a uspjeh vraća sve na staro
//              preko _netVezaVracena;
//   'slaba'  → lokalni rad; mreža samo na izričit zahtjev ili kratku probu
//              (fotografije, preuzimanje terena, korisnik koji čeka odgovor);
//   'dobra' / 'nepoznato' → da.
// Lokalni rad NIKAD ne zavisi od ovoga — ovo samo odlučuje da li se čeka mreža.
const _NET_PROBA_MS = 30 * 1000;
const _NET_PROZOR_MS = 20 * 1000;   // koliko dugo dodijeljena proba smije slati zahtjeve
let _netProbaDo = 0, _netSilaDo = 0;
function _mrezaProbaj(traziDobru, proba = false) {
  if (typeof navigator !== 'undefined' && navigator.onLine === false) return false;
  const k = _netKvalitet();
  const sad = Date.now();
  if (sad < _netSilaDo && !traziDobru) return true;
  // Slab signal: lokalni rad odmah; samo periodična proba ili ručna radnja
  // otvara mrežu. Povratak u panel/GPS fiks ne pokreću čekanje na server.
  if (k === 'slaba' && !proba) return false;
  if (k === 'nema' || k === 'slaba') {
    if (traziDobru) return false;
    const zadnji = _netUzorci.length ? _netUzorci[_netUzorci.length - 1].t : 0;
    if (sad - zadnji < _NET_PROBA_MS || sad < _netProbaDo) return false;
    _netProbaDo = sad + _NET_PROBA_MS;   // samo JEDNA proba po prozoru, ne svi pozivaoci odjednom
    _netSilaDo = sad + _NET_PROZOR_MS;
    return true;
  }
  return true;
}
// Korisnik je IZRIČITO tražio mrežnu radnju ("Sync sad", odjava, preuzimanje):
// pusti zahtjeve kratko bez obzira na izmjereno stanje — možda zna da je signal
// upravo došao, a jedan pravi pokušaj je i najbrža proba.
function _mrezaSila(ms) { _netSilaDo = Math.max(_netSilaDo, Date.now() + (ms || _NET_PROZOR_MS)); }
// Vrata transporta (reliableFetch): na izmjereno mrtvoj vezi Supabase poziv pada
// ODMAH umjesto poslije 15 s — keš/red krenu odmah. Van 'nema' uvijek propušta.
function _netDozvoliZahtjev() {
  // OS kaže offline (to ne laže): browser bi i sam pao odmah, ALI supabase-js
  // takav neuspjeh ponavlja 3 puta (1+2+4 s) — izmjereno: oporavak prekinutog
  // snimanja bez signala se zato pojavljivao tek poslije ~16 s. Odbijanje na
  // vratima ide bez ponavljanja. Izričita radnja korisnika (_mrezaSila) prolazi.
  if (typeof navigator !== 'undefined' && navigator.onLine === false) return Date.now() < _netSilaDo;
  return _mrezaProbaj();
}
try { if (typeof setNetGate === 'function') setNetGate(_netDozvoliZahtjev); } catch(e) {}
// Samo ČITA stanje (za poruke korisniku) — za razliku od _mrezaProbaj ne troši probu.
function _mrezaStanje() {
  if (typeof navigator !== 'undefined' && navigator.onLine === false) return 'nema';
  return _netKvalitet();
}
// Veliko preuzimanje koje je korisnik SAM tražio: bez veze se ne počinje (ne
// ostavljati ga pred progress barom koji ne mrdne), a na slaboj vezi se pita —
// korisnik zna je li mu to sad vrijedno trošiti, app ne zna.
async function _mrezaZaPreuzimanje(sta) {
  if (navigator.onLine === false) { showToast('📴 ' + sta + ' traži internet — sad nema veze'); return false; }
  if (_mrezaStanje() === 'slaba' && !await _dlgConfirm(sta + ' na slabom signalu može trajati dugo i trošiti mobilne podatke. Pokušati ipak?',
    { title: '📶 Slab signal', okLabel: 'Pokušaj' })) return false;
  _mrezaSila(60000);
  return true;
}
let _netRealtimePauziran = false;
function _netPrimijeniRezim() {
  if (typeof sb === 'undefined' || !sb?.realtime) return;
  const k = _mrezaStanje();
  const pauza = k === 'slaba' || k === 'nema';
  if (pauza === _netRealtimePauziran) return;
  _netRealtimePauziran = pauza;
  if (pauza) sb.realtime.disconnect();
  else sb.realtime.connect();
}
// OS je javio da je veza TEK SAD uspostavljena — kvarovi izmjereni prije toga
// opisuju vezu koje više nema, pa ne smiju blokirati prvi pokušaj.
function _netZaboraviKvarove() {
  _netUzorci = [];
  _netProbaDo = 0; _netSilaDo = 0;
  try { _netBadgeSync(); } catch(e) {}
  try { _netPrimijeniRezim(); } catch(e) {}
  _netPonoviPlocice();
}
// Pločice koje su ostale prazne/zamućene dok veze nije bilo — ponovi dohvat.
function _netPonoviPlocice() {
  try {
    if (typeof map === 'undefined' || !map) return;
    map.eachLayer(l => { if (typeof l._retryEmpty === 'function') l._retryEmpty(); });
  } catch(e) {}
}
// Veza se vratila BEZ 'online' eventa (tipično: signal oslabio pa ojačao, a OS
// cijelo vrijeme tvrdio da je online) — pokreni isto što i 'online' event, inače
// bi red za sync čekao sljedeći periodični otkucaj ili povratak u prvi plan.
let _netVracenaT = null, _netVracenaZadnji = 0;
function _netVezaVracena() {
  if (_netVracenaT || Date.now() - _netVracenaZadnji < 60000) return;
  _netVracenaT = setTimeout(() => {
    _netVracenaT = null;
    _netVracenaZadnji = Date.now();
    _netPonoviPlocice();
    if (typeof sbUser === 'undefined' || !sbUser) return;
    _serverPodsjetnik();
    try { if (typeof _processOfflineQueue === 'function') _processOfflineQueue(true); } catch(e) {}
    try { if (typeof _reloadCoreData === 'function') _reloadCoreData(); } catch(e) {}
  }, 800);
}

// Jedno mjesto koje odlučuje izgled tačkice — inače bi _setOfflineMode i
// mjerenje pisali po istom elementu i gazili se.
function _netBadgeSync() {
  const el = document.getElementById('offline-badge');
  if (!el) return;
  const k = _netKvalitet();
  if (_isOfflineMode || k === 'nema') {
    el.style.display = 'inline-block';
    el.style.background = '#dc2626';
    el.style.boxShadow = '0 0 0 2px rgba(220,38,38,0.3)';
    el.title = 'Nema signala — radi lokalno, sinkronizacija čeka';
  } else if (k === 'slaba') {
    el.style.display = 'inline-block';
    el.style.background = '#f59e0b';
    el.style.boxShadow = '0 0 0 2px rgba(245,158,11,0.3)';
    el.title = 'Slab signal — radi offline iz lokalnih podataka; slanje je ručno';
  } else {
    el.style.display = 'none';
  }
}
try { if (typeof setNetObserver === 'function') setNetObserver(_netZabiljezi); } catch(e) {}

function _setOfflineMode(offline) {
  _isOfflineMode = offline;
  try { _netPrimijeniRezim(); } catch(e) {}
  try { _netBadgeSync(); } catch(e) {
    const el = document.getElementById('offline-badge');
    if (el) el.style.display = offline ? 'inline-block' : 'none';
  }
}

// ─── LOKALNI UPIS NEPOVRATNIH TERENSKIH PODATAKA ────────────────────────────
// Snimak sa terena se NE MOŽE ponoviti — trag se ne može ponovo prehodati.
// Zato upis koji ne uspije (najčešće popunjena localStorage kvota) NE SMIJE
// proći tiho: `_tragRegSave` i `_msrRegSave` su imali goli `catch(e) {}`, pa
// bi cijeli terenski dan ostao nesačuvan BEZ IJEDNOG ZNAKA — a proces koji OEM
// battery manager ubije (dokumentovano, često) odnio bi ga sa sobom.
function _lsZauzetoKB() {
  // localStorage ima SVOJU kvotu (~5 MB), potpuno odvojenu od one koju
  // prijavljuje navigator.storage.estimate() (origin kvota, red veličine GB —
  // to je ono što mjeri pregled offline karata). Zato se mjeri direktno; inače
  // bi pregled tvrdio "2 GB slobodno" dok je localStorage do vrha pun.
  try {
    let n = 0;
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      n += k.length + (localStorage.getItem(k) || '').length;
    }
    return Math.round(n * 2 / 1024);   // UTF-16: 2 bajta po znaku
  } catch(e) { return null; }
}

function _localSetKriticno(key, vrijednost, opis) {
  try { localStorage.setItem(key, vrijednost); return true; }
  catch(e) {
    const puna = !!(e && (e.name === 'QuotaExceededError' || e.name === 'NS_ERROR_DOM_QUOTA_REACHED'
      || /quota|exceeded/i.test(e.message || '')));
    try {
      showToast(puna
        ? '⚠ NEMA MJESTA — ' + opis + ' NIJE sačuvano! Sinkronizuj pa obriši stare snimke.'
        : '⚠ ' + opis + ' nije sačuvano lokalno.');
    } catch(e2) {}
    // Zapis ostaje u DEBUG-u i poslije nestanka toasta — na jakom terenskom
    // suncu se poruka lako previdi, a ovo je gubitak podataka.
    try {
      _debugUpsert('local-quota', 'Lokalni upis nije uspio',
        opis + ' NIJE sačuvano.\nRazlog: ' + (puna ? 'popunjena localStorage kvota (~5 MB)' : (e?.message || e)) +
        '\nZauzeto sada: ' + _lsZauzetoKB() + ' KB', 'aktivno');
    } catch(e2) {}
    return false;
  }
}

// ─── SERVER: terenski podaci na zahtjev; novi projekti automatski ────────────
// Terenski podaci šalju se dugmetom "Pošalji na server"; novi projekat odmah.
// (Meni → Server), ne sami od sebe (periodični otkucaj na 60 s, povratak u prvi
// plan, vraćena veza, svaka GPS tačka doznake...). Sve se i dalje ČUVA odmah
// lokalno i u redu za sync — mijenja se samo KO odlučuje kad ide na server.
// _serverSlanjeDozvoljeno() otvara ručno slanje terenskih podataka. Izuzetak
// 2.8.7: novi projekti vlaka/doznake šalju se automatski, prije članstva.
// Automatski prolaz ne šalje vlake, zone, status ni GPS bafer.
// v1.9.5: kapija je otvorena TAČNO dok traje serverPosalji() (zatvara se u
// finally), a ne fiksne 3 min — na slaboj vezi pun terenski dan (~1,2 MB)
// traje duže, pa je rok zatvarao kapiju usred slanja i ostatak je tiho čekao
// sljedeći pritisak. Zaglavljeno slanje nije moguće: svaki zahtjev ima rok u
// transportu (reliableFetch), a prolaz reda završava sa zadnjom stavkom.
let _serverSaljem = false;
// v1.9.6 (izbor korisnika): na server idu SAMO vlake projekta i doznaka (pojas,
// zone, odjeli, status) + odjeli šumarije i projekti koji vlake nose. Tragovi,
// dnevnik rada, tekstualne oznake i fotografije ostaju na telefonu — server ih
// ionako nije koristio (tragove aplikacija nikad ne čita nazad). Fotografija
// ide kolegama samo kroz izričito "Podijeli".
const _SERVER_SAMO_LOKALNO = new Set(['upsert_trag', 'delete_trag', 'upsert_log', 'upsert_labels']);
const _SERVER_ZADNJE_KEY = 'tvlake_server_zadnje_slanje';
function _serverSlanjeDozvoljeno() { return _serverSaljem; }
// Brojač se crta pri svakom upisu u red, svakih 5 s na Terenu i tokom doznake,
// a red bez slanja naraste na cijeli terenski dan (izmjereno: 20 tragova + 40
// vlaka = 1,2 MB, ~14 ms po parsiranju na desktopu, ~55 ms na srednjem
// telefonu). Čitanje stringa je jeftino, parsiranje nije — parsira se samo kad
// se sadržaj stvarno promijenio, bez obzira KO je pisao (poređenje stringova).
// Vraćena vrijednost je dijeljena: samo za čitanje.
const _lsMemo = {};
function _lsJsonMemo(key) {
  let raw = null;
  try { raw = localStorage.getItem(key); } catch(e) {}
  const m = _lsMemo[key];
  if (m && m.raw === raw) return m.v;
  let v = null;
  try { v = raw ? JSON.parse(raw) : null; } catch(e) { v = null; }
  _lsMemo[key] = { raw, v };
  return v;
}
// Direktan upis koji nije dozvoljen ide u red (isti put kao bez signala) —
// vraća true kad je operacija stavljena u red i pozivalac ne treba ništa dalje.
function _serverURed(op) {
  if (_serverSlanjeDozvoljeno()) return false;
  _OL.enqueue(op);
  return true;
}
// Ukloni iz reda operacije koje više ne smiju otići (npr. neposlana vlaka koja
// je u međuvremenu obrisana). Red se pregleda iznova prije svake stavke, pa i
// prolaz koji je u toku preskoči uklonjeno.
function _redUkloni(pred) {
  try {
    const q = _OL.loadQueue(true);
    const ost = q.filter(o => !pred(o));
    if (ost.length === q.length) return 0;
    localStorage.setItem(_OL.QUEUE, JSON.stringify(ost));
    _updSyncBadge();
    return q.length - ost.length;
  } catch(e) { return 0; }
}
// Podsjetnik kad se signal vrati: slanje je ručno, a na terenu je baš taj
// trenutak (izlazak iz šume, vozilo) prilika koju je lako propustiti. Najviše
// jednom u 30 min — inače bi slab signal koji dolazi i odlazi stalno zvonio.
let _serverPodsjetnikZadnji = 0;
function _serverPodsjetnik() {
  try {
    if (_serverSaljem || typeof sbUser === 'undefined' || !sbUser) return;
    if (Date.now() - _serverPodsjetnikZadnji < 30 * 60000) return;
    const n = _serverNaCekanju().stavki;
    if (!n) return;
    _serverPodsjetnikZadnji = Date.now();
    showToast('📶 Signal je tu — čeka slanje: ' + n + ' (Meni → Server)');
  } catch(e) {}
}
// Šta čeka slanje. Doznaka pojas je JEDNA stavka (stotine tačaka su jedan hod),
// fotografija bez punog snimka nigdje se ne broji — nikad se ne bi mogla poslati.
// qZadan: red koji pozivalac već ima u ruci (_OL.enqueue ga je upravo upisao) —
// bez njega bi se isti red odmah parsirao još jednom.
// GPS tačke pojasa za odjel koji na serveru više ne postoji (obrisan, a nema
// ni upisa u redu koji bi ga napravio). Nikad ne mogu proći — ostaju sačuvane
// na telefonu, ali se ne šalju i ne broje u "čeka slanje" (inače "Sve
// poslano" ne bi došlo nikad). Ključ je po korisniku.
function _dozSirocadKljuc() { return 'tvlake_doz_sirocad_' + (typeof sbUser !== 'undefined' && sbUser?.id || ''); }
function _dozSirocad() {
  try { const a = JSON.parse(localStorage.getItem(_dozSirocadKljuc()) || '[]'); return new Set(Array.isArray(a) ? a : []); }
  catch(e) { return new Set(); }
}
function _dozSirocadDodaj(pid) {
  const s = _dozSirocad(); s.add(pid);
  try { localStorage.setItem(_dozSirocadKljuc(), JSON.stringify([...s])); } catch(e) {}
}
function _serverNaCekanju(qZadan) {
  const uid = typeof sbUser !== 'undefined' ? sbUser?.id : null;
  const r = { red: 0, blok: 0, doz: 0, siroce: 0, stavki: 0 };
  let q = null;
  try { q = Array.isArray(qZadan) ? qZadan : _lsJsonMemo(_OL.QUEUE); } catch(e) {}
  if (!Array.isArray(q)) q = [];
  const moji = q.filter(op => (!op._uid || op._uid === uid) && !_SERVER_SAMO_LOKALNO.has(op.type));
  r.red = moji.length; r.blok = moji.filter(op => op._blocked).length;
  try {
    const sir = typeof _dozSirocad === 'function' ? _dozSirocad() : new Set();
    if(typeof FieldStore !== 'undefined' && FieldStore.ready) {
      r.doz=FieldStore.count(uid);
      for (const pid of sir) r.siroce += FieldStore.view(uid, pid).length;
    } else {
      const b=_lsJsonMemo(_DOZ_TRACK_BUF_KEY);
      const moje = Array.isArray(b) ? b.filter(p=>p.user_id===uid) : [];
      r.doz = moje.length; r.siroce = moje.filter(p => sir.has(p.project_id)).length;
    }
    r.doz = Math.max(0, r.doz - r.siroce);
  } catch(e) {}
  r.stavki = r.red + (r.doz ? 1 : 0);
  return r;
}

function _updSyncBadge(qZadan) {
  const cnt = _serverNaCekanju(qZadan).stavki;
  const badge = document.getElementById('sync-badge');
  const cntEl = document.getElementById('sync-badge-cnt');
  if (badge) {
    if (cnt > 0) {
      badge.style.display = 'inline-block';
      if (cntEl) cntEl.textContent = cnt;
    } else {
      badge.style.display = 'none';
    }
  }
  const mc = document.getElementById('mdrop-server-cnt');
  if (mc) { if (mc.firstElementChild) mc.firstElementChild.textContent = String(cnt); mc.style.display = cnt > 0 ? '' : 'none'; }
}
// Doznaka zove red na SVAKU GPS tačku — bez slanja to je samo osvježavanje
// brojača, a brojanje čita cijeli bafer, pa najviše jednom u 5 s.
let _updSyncBadgeT = null;
function _updSyncBadgeUskoro() {
  if (_updSyncBadgeT) return;
  _updSyncBadgeT = setTimeout(() => { _updSyncBadgeT = null; try { _updSyncBadge(); } catch(e) {} }, 5000);
}

const _OP_LABELS = {
  upsert_vlaka:       '↑ Snimaj vlaku',
  delete_vlaka:       '✕ Briši vlaku',
  delete_projekt:     '✕ Briši projekat',
  upsert_log:         '↑ Dnevni log',
  insert_projekt:     '+ Novi projekat',
  upsert_odjel:       '↑ Odjel',
  insert_doz_project: '+ Novi doznaka odjel',
  insert_doz_marking: '+ Doznaka oznaka',
  delete_doz_marking: '✕ Briši doznaka oznaku',
  upsert_doz_status:  '↑ Status odjela',
  upsert_trag:        '↑ Snimaj trag',
  delete_trag:        '✕ Briši trag',
  upsert_labels:      '↑ Tekstualne oznake',
};

function openSyncQueuePanel() {
  let q    = _OL.loadQueue().filter(op => !op._uid || op._uid === sbUser?.id);
  const list = document.getElementById('syncq-list');
  const bg   = document.getElementById('syncq-bg');
  const pan  = document.getElementById('syncq-panel');
  if (!list || !pan) return;

  if(typeof FieldStore!=='undefined' && !FieldStore.ready && !openSyncQueuePanel._journalLoading) {
    const owner=sbUser?.id;
    openSyncQueuePanel._journalLoading=true;
    FieldStore.init().then(()=>{if(sbUser?.id===owner && pan.style.display==='flex')openSyncQueuePanel();})
      .catch(()=>showToast('⚠ Lokalni GPS dnevnik nije učitan; provjeri memoriju telefona'))
      .finally(()=>{openSyncQueuePanel._journalLoading=false;});
  }

  _serverSazetakRender();
  _serverPrimljenoIzKesa();
  _serverPrimljenoRender();
  if (typeof _tabServerPrepare === 'function') q = _tabServerPrepare(q);
  if (!q.length) {
    list.innerHTML = '';
  } else {
    list.innerHTML = q.map((op, i) => {
      const lbl   = _OP_LABELS[op.type] || op.type;
      const nm    = op.payload?.nm || op.payload?.datum || op.payload?.naziv || '';
      const ret   = op._retries ? `<span style="color:#f87171;font-size:10px"> (${_escHtml(String(op._retries))} pokušaja)</span>` : '';
      const age   = op.ts ? _fmtAgo(op.ts) : '';
      const odg   = op._blocked ? '<div style="font-size:10px;color:#fbbf24">⏸ više puta odbijeno — šalje se ponovo tek na "Pošalji na server"</div>' : '';
      const errTxt = op._lastErr ? `${op._lastErr.message || ''}${op._lastErr.code ? ' [' + op._lastErr.code + ']' : ''}` : '';
      return `<div style="display:flex;align-items:center;gap:10px;padding:10px 16px;border-bottom:1px solid #1e293b;">
        <div style="flex:1;min-width:0;">
          <div style="font-size:13px;color:#e2e8f0;font-weight:600;">${_escHtml(lbl)}${ret}</div>
          ${nm ? `<div style="font-size:11px;color:#64748b;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${_escHtml(String(nm))}</div>` : ''}
          ${typeof _serverOpContext === 'function' ? _serverOpContext(op) : ''}
          ${errTxt ? `<div style="font-size:12px;color:#f87171;margin-top:4px;white-space:normal;overflow-wrap:anywhere" title="${_escHtml(errTxt)}">⚠ ${_escHtml(errTxt)}</div>` : ''}
          ${odg}
          ${age ? `<div style="font-size:10px;color:#475569">${age}</div>` : ''}
        </div>
        <button data-key="${_escHtml(String(op._qid ?? op.ts))}" onclick="_syncQueueDiscard(this.dataset.key)"
          style="border:none;background:none;color:#64748b;font-size:16px;cursor:pointer;flex-shrink:0;padding:4px 6px;"
          title="Odbaci operaciju"><svg class="ic"><use href="#ic-zatvori"/></svg></button>
      </div>`;
    }).join('');
  }

  if (typeof _serverPanelRender === 'function') _serverPanelRender();
  if (bg)  bg.style.display  = 'block';
  pan.style.display = 'flex';
}

function closeSyncQueuePanel() {
  const bg  = document.getElementById('syncq-bg');
  const pan = document.getElementById('syncq-panel');
  if (bg)  bg.style.display  = 'none';
  if (pan) pan.style.display = 'none';
}

async function _syncQueueDiscard(ts) {
  const owner=sbUser?.id;
  const op = _OL.loadQueue(true).find(o => String(o._qid ?? o.ts) === String(ts));
  if (!op || (op._uid && op._uid !== owner)) return;
  const question = op.type === 'upsert_doz_status'
    ? 'Ukloniti ovaj neposlani zahtjev za promjenu statusa odjela? Snimljeni pojasevi, zone i vlake se ne brišu.'
    : 'Trajno odbaciti ovu neposlanu izmjenu? Prvo izvezi podatke.';
  if (!await _dlgConfirm(question, { danger: true }) || sbUser?.id !== owner) return;
  _OL.removeFromQueue(ts);
  _updSyncBadge();
  openSyncQueuePanel(); // re-render
}

async function _syncQueueClearAll() {
  if (!await _dlgConfirm('Obrisati sve neposlane izmjene iz reda? Ovo ih trajno briše sa telefona.', { danger: true })) return;
  try { localStorage.setItem(_OL.QUEUE, JSON.stringify(_OL.loadQueue(true).filter(op => op._uid && op._uid !== sbUser?.id))); } catch {}
  _updSyncBadge();
  openSyncQueuePanel();
}

// Stari naziv ("Sync sada") — sad je to isto što i "Pošalji na server".
function _syncQueueFlushNow() { return serverPosalji(); }

function _serverZadnje() {
  try { return Number(localStorage.getItem(_SERVER_ZADNJE_KEY)) || 0; } catch(e) { return 0; }
}
// Sažetak na vrhu panela Server: šta čeka, stanje veze, kad je zadnji put poslano.
function _serverSazetakRender() {
  const el = document.getElementById('syncq-sum');
  if (!el) return;
  const n = _serverNaCekanju();
  const st = _mrezaStanje();
  const veza = st === 'nema' ? '<span style="color:#f87171">nema veze</span>'
    : st === 'slaba' ? '<span style="color:#fbbf24">slaba veza</span>'
    : '<span style="color:#4ade80">' + (st === 'dobra' ? 'veza u redu' : 'veza nije izmjerena') + '</span>';
  const z = _serverZadnje();
  const red = (ikona, txt, br) => br ? '<div style="display:flex;justify-content:space-between;gap:8px;padding:3px 0"><span>' + ikona + ' ' + txt + '</span><b style="white-space:nowrap;flex-shrink:0">' + br + '</b></div>' : '';
  const stavke = red('↑', 'Vlake, projekti i doznaka', n.red) + red('📍', 'Doznaka — GPS tačke pojasa', n.doz);
  el.innerHTML =
    '<div style="font-size:12px;color:#94a3b8;margin-bottom:8px">' + veza + ' · zadnje slanje: ' + (z ? _escHtml(_fmtAgo(z).toLowerCase()) : 'nikad') + '</div>' +
    (n.stavki
      ? '<div style="font-size:13px;color:#e2e8f0">' + stavke + '</div>' +
        '<div style="font-size:11px;color:#64748b;margin-top:6px">Sačuvano je na telefonu. Kolege ovo vide tek kad pošalješ.</div>' +
        '<div style="font-size:11px;color:#64748b;margin-top:2px">Tragovi, dnevnik, oznake i fotografije ostaju samo na telefonu.</div>'
      : '<div style="font-size:13px;color:#4ade80">✓ Red za slanje je prazan.</div>') +
    (n.blok ? '<div style="font-size:11px;color:#fbbf24;margin-top:6px">⚠ ' + n.blok + ' stavk' + (n.blok === 1 ? 'a' : 'e') + ' server odbija — pogledaj Problemi.</div>' : '') +
    (_serverSaljem ? '<div style="font-size:12px;color:#60a5fa;margin-top:8px">⏳ Šaljem…</div>' : '');
  if(typeof _serverPanelSazetak==='function') el.innerHTML=_serverPanelSazetak(n,st,z);
  if (n.siroce) el.innerHTML += '<div style="font-size:11px;color:#94a3b8;margin-top:6px">📍 ' + n.siroce +
    ' GPS tačaka pripada odjelu koji je obrisan sa servera — ostaju na telefonu (izvoz pojasa), ne šalju se.</div>';
  const b = document.getElementById('syncq-posalji');
  if (b) { b.disabled = _serverSaljem || !!serverPosalji._priprema || _serverPrimljenoBusy || (typeof _serverRazmjena==='function' && !!_serverRazmjena.busy); b.style.opacity = b.disabled ? '0.5' : '1'; }
}

function _serverPrimljenoKljuc() { return 'tvlake_server_primljeno_v1_' + (sbUser?.id || ''); }
function _serverPrimljenoUcitaj() {
  try { const data = JSON.parse(localStorage.getItem(_serverPrimljenoKljuc()) || '[]'); return Array.isArray(data) ? data : []; }
  catch(e) { return []; }
}
function _serverPrimljenoIzKesa() {
  if (_serverPrimljenoUcitaj().length || !sbUser) return;
  try {
    const all = JSON.parse(localStorage.getItem(_KVC_KEY) || '{}');
    for (const p of _projekti) {
      if (p.korisnik_id === sbUser.id || (p.clanovi || []).some(c=>c.korisnik_id===sbUser.id)) {
        _serverPrimljenoZapamti(p.id,Object.values(all[p.id] || {}));
      }
    }
  } catch(e) {}
}
// Samo sažeci: geometrija ostaje u postojećem kešu vlaka, bez druge velike kopije.
function _serverPrimljenoZapamti(projektId, rows) {
  const uid = sbUser?.id;
  const p = _projekti.find(x => x.id === projektId);
  if (!uid || !p || !(p.korisnik_id === uid || (p.clanovi || []).some(c => c.korisnik_id === uid))) return;
  const feed = _serverPrimljenoUcitaj();
  for (const row of rows) {
    if (!row.korisnik_id || row.korisnik_id === uid) continue;
    const key = projektId + '::' + (row.id || row.korisnik_id + '::' + row.nm);
    const previous = feed.find(x => x.key === key);
    const revision = String(row.updated_at || row.rev || '') + ':' + (row.pts?.length || 0);
    if (previous && previous.revision === revision) continue;
    const item = { key, projektId, nm:row.nm || 'Vlaka', uid:row.korisnik_id,
      ime:row.ime || kolegeMap[row.korisnik_id]?.ime || 'Projektant',
      revision, ts:Date.now(), updatedAt:row.updated_at || null, novo:true,
      vrsta:previous ? 'Ažurirano' : 'Dodano', points:row.pts?.length || 0 };
    if (previous) feed.splice(feed.indexOf(previous), 1);
    feed.unshift(item);
  }
  try { localStorage.setItem(_serverPrimljenoKljuc(), JSON.stringify(feed.slice(0,200))); }
  catch(e) { showToast('⚠ Pregled primljenih podataka nije sačuvan; vlake ostaju u lokalnom kešu'); }
  _serverPrimljenoRender();
}
function _serverPrimljenoRender() {
  const el = document.getElementById('syncq-primljeno');
  if (!el) return;
  const uid = sbUser?.id;
  const projects = new Map(_projekti.filter(p => p.korisnik_id === uid ||
    (p.clanovi || []).some(c => c.korisnik_id === uid)).map(p => [p.id,p]));
  const rows = _serverPrimljenoUcitaj().filter(x => projects.has(x.projektId));
  const count = rows.filter(x => x.novo).length;
  el.innerHTML = '<div style="font-size:13px;font-weight:700;color:#e2e8f0;margin-bottom:6px">↓ Primljeno iz dijeljenih projekata' +
    (count ? ' · ' + count + ' novih' : '') + '</div>' +
    '<div style="font-size:11px;color:#94a3b8;margin-bottom:8px">Vlake kolega u projektima čiji si vlasnik ili član. Zadnji preuzeti podaci dostupni su i offline.</div>' +
    (rows.length ? rows.slice(0,50).map(x => {
      const p = projects.get(x.projektId);
      return '<div style="padding:8px 0;border-top:1px solid #1e293b;font-size:12px;color:#cbd5e1">' +
        (x.novo ? '<span style="color:#4ade80">● Novo na ovom telefonu · </span>' : '') + _escHtml(x.vrsta) + ': <b>' + _escHtml(x.nm) + '</b>' +
        '<div style="font-size:11px;color:#94a3b8">' + _escHtml(p.gj || '') + ' · ' + _escHtml(p.odjel || 'Projekat') +
        ' · ' + _escHtml(x.ime) + ' · ' + x.points + ' tačaka</div>' +
        '<button data-projekt="' + _escHtml(x.projektId) + '" onclick="_serverPrimljenoOtvori(this.dataset.projekt)" style="margin-top:5px;padding:6px 10px;background:#1e293b;border:1px solid #334155;border-radius:6px;color:#7dd3fc">Pogledaj projekat</button></div>';
    }).join('') : '<div style="font-size:12px;color:#94a3b8">Još nema preuzetih podataka. Osvježi kad imaš vezu.</div>');
  const b = document.getElementById('syncq-preuzmi');
  if (b) b.disabled = _serverPrimljenoBusy;
  if (typeof _tabServerCounts === 'function') _tabServerCounts();
}
async function _serverPrimljenoOtvori(id) {
  const p = _projekti.find(x => x.id === id);
  if (!p || !(p.korisnik_id === sbUser?.id || (p.clanovi || []).some(c => c.korisnik_id === sbUser?.id))) return;
  const feed = _serverPrimljenoUcitaj();
  feed.forEach(x => { if (x.projektId === id) x.novo = false; });
  try { localStorage.setItem(_serverPrimljenoKljuc(), JSON.stringify(feed)); } catch(e) {}
  closeSyncQueuePanel();
  await aktivirajProjekt(id);
  switchTab('karta');
}
let _serverPrimljenoBusy = false;
let _serverPrimljenoRtTimer = null;
const _serverPrimljenoRtRows = new Map();
function _serverPrimljenoRealtime(row) {
  const uid=sbUser?.id;
  const p=_projekti.find(p=>p.id===row.projekt_id);
  if (!uid || !p || !(p.korisnik_id===uid || (p.clanovi || []).some(c=>c.korisnik_id===uid))) return;
  _serverPrimljenoRtRows.set(row.id || row.projekt_id+'::'+row.korisnik_id+'::'+row.nm,{row,uid});
  if (_serverPrimljenoRtTimer) return;
  _serverPrimljenoRtTimer=setTimeout(()=>{
    _serverPrimljenoRtTimer=null;
    const groups=new Map();
    for (const item of _serverPrimljenoRtRows.values()) {
      if (item.uid!==sbUser?.id) continue;
      if (!groups.has(item.row.projekt_id)) groups.set(item.row.projekt_id,[]);
      groups.get(item.row.projekt_id).push(item.row);
    }
    _serverPrimljenoRtRows.clear();
    for (const [id,rows] of groups) _kvcSave(id,rows);
    if (typeof _serverPanelRender==='function' && document.getElementById('syncq-panel')?.style.display==='flex') _serverPanelRender();
  },1000);
}
// Primijeni odgovor tek nakon svih stranica i provjere naloga. RLS ostaje
// autoritet za pristup; lokalni spisak članova može kasniti za serverom.
async function _vlakePreuzmiStranice(upit, owner) {
  const rows = [];
  for (let offset = 0, n = 0; n < 5000; n++) {
    const page = await upit().order('id').range(offset, offset + 99);
    if (sbUser?.id !== owner) throw { code:'OWNER_CHANGED', message:'Promijenjen nalog' };
    if (page.error) throw page.error;
    if (!page.data?.length) return rows;
    rows.push(...page.data);
    offset += page.data.length;
  }
  throw new Error('Previše stranica podataka; prethodna lokalna kopija je sačuvana');
}
// Preuzimanje vlastitog rada s drugog uređaja ne smije prepisati živu
// lokalnu izmjenu koja čeka debounce, slanje ili završetak GPS snimanja.
function _serverPrimijeniMojeVlake(rows,owner) {
  const pending=_OL.loadQueue().filter(o=>o.type==='upsert_vlaka' && (!o._uid || o._uid===owner));
  _applyVlakeRows(rows.filter(row=>{
    if(row.korisnik_id!==owner)return false;
    const i=vlake.findIndex(v=>v.sbId===row.id || v.nm===row.nm && v.projektId===row.projekt_id);
    if(i<0)return true;
    const busy=typeof _vlakaSaveTimers!=='undefined' && _vlakaSaveTimers[i] || typeof recOn!=='undefined' && recOn && actI===i;
    return !busy && !pending.some(o=>o.payload?.id===row.id || o.payload?.nm===row.nm && o.payload?.projekt_id===row.projekt_id);
  }));
}
async function serverPreuzmiDijeljeno(projektId) {
  if (_serverPrimljenoBusy || !sbUser || !sbProfile) return {ok:false};
  if (navigator.onLine === false) { showToast('📴 Nema veze — prikazujem zadnje preuzete podatke'); return {ok:false}; }
  const owner = sbUser.id;
  _serverPrimljenoBusy = true;
  _serverPrimljenoRender();
  try {
    _mrezaSila(60000);
    const membership = await sb.from('projekt_clanovi').select('projekt_id').eq('korisnik_id',owner);
    if (membership.error) throw membership.error;
    if (sbUser?.id !== owner) return {ok:false,ownerChanged:true};
    const owned = await sb.from('projekti').select('*').eq('korisnik_id',owner);
    if (owned.error) throw owned.error;
    if (sbUser?.id !== owner) return {ok:false,ownerChanged:true};
    const ids = [...new Set((membership.data || []).map(x => x.projekt_id))];
    const result = ids.length ? await sb.from('projekti').select('*').in('id',ids) : {data:[]};
    if (result.error) throw result.error;
    if (sbUser?.id !== owner) return {ok:false,ownerChanged:true};
    const projects = [...new Map([...(owned.data || []), ...(result.data || [])].map(p=>[p.id,p])).values()].filter(p=>!projektId || p.id===projektId);
    if (!projects.length) {
      for (const p of _projekti) if (p.korisnik_id!==owner && (!projektId || p.id===projektId) && !ids.includes(p.id)) p.clanovi=(p.clanovi || []).filter(c=>c.korisnik_id!==owner);
      _OL.save(_OL.PROJEKTI,_projekti);
      showToast('Nema projekata u kojima si vlasnik ili član'); return {ok:true,count:0};
    }
    const rows = await _vlakePreuzmiStranice(() => {
      _mrezaSila(60000);
      return sb.from('vlake').select('*').in('projekt_id',projects.map(p=>p.id));
    }, owner);
    for (const p of _projekti) {
      if (p.korisnik_id!==owner && !ids.includes(p.id)) p.clanovi=(p.clanovi || []).filter(c=>c.korisnik_id!==owner);
    }
    for (const p of projects) {
      const old = _projekti.find(x=>x.id===p.id);
      const clanovi = old?.clanovi || [];
      if (p.korisnik_id!==owner && !clanovi.some(c=>c.korisnik_id===owner)) clanovi.push({korisnik_id:owner});
      const value = {...p,clanovi};
      if (old) _projekti[_projekti.indexOf(old)] = value; else _projekti.push(value);
    }
    _OL.save(_OL.PROJEKTI,_projekti);
    // Istom nalogu na drugom uređaju trebaju i njegove serverske vlake.
    if (typeof _applyVlakeRows === 'function') _serverPrimijeniMojeVlake(rows,owner);
    for (const p of projects) {
      const projektRows=rows.filter(r=>r.projekt_id===p.id);
      if (_kvcSave(p.id,projektRows) === false) throw new Error('Primljene vlake nisu sačuvane na telefonu');
      if (typeof _serverProjektPreuzeto === 'function' && _serverProjektPreuzeto(p.id,projektRows) === false) throw new Error('Pregled projekta nije sačuvan');
      // Prepusti glavnu nit između projekata — veći keš ne blokira dodir/GPS.
      await new Promise(r=>setTimeout(r,0));
      if (sbUser?.id !== owner) return {ok:false,ownerChanged:true};
    }
    // Preuzimanje mora osvježiti i aktivnu kartu, bez drugog mrežnog upita.
    if (projects.some(p=>p.id===_aktivniProjektId)) {
      await sbLoadKolegeVlake(rows.filter(r=>r.projekt_id===_aktivniProjektId));
      if (sbUser?.id !== owner) return {ok:false,ownerChanged:true};
    }
    rndProjektiList();
    showToast('✓ Preuzeto ' + rows.length + ' vlaka projekta');
    return {ok:true,count:rows.length,projects:projects.length};
  } catch(e) { showToast('⚠ Preuzimanje nije uspjelo — zadnji lokalni podaci ostaju dostupni'); return {ok:false,error:e}; }
  finally { _serverPrimljenoBusy=false; _serverPrimljenoRender(); if (typeof _serverPanelRender==='function') _serverPanelRender(); }
}

// Ručno slanje svega što čeka. Otvara kapiju samo dok slanje traje: svi
// automatski pozivi reda (GPS tačka, povratak u prvi plan...) i dalje ne šalju.
async function serverPosalji() {
  if (_serverSaljem || serverPosalji._priprema) return {ok:false};
  if (!sbUser || !sbProfile) { showToast('⚠ Prijavi se da bi slao na server'); return {ok:false}; }
  if (typeof navigator !== 'undefined' && navigator.onLine === false) {
    showToast('📴 Nema veze — sve ostaje sačuvano na telefonu, pošalji kad bude signala');
    return {ok:false};
  }
  const pripremaOwner = sbUser.id;
  serverPosalji._priprema = true;
  _serverSazetakRender();
  try {
    // Brojač GPS tačaka mora biti spreman i odmah nakon pokretanja aplikacije.
    // Prazan memorijski brojač prije učitavanja IDB-a nije potvrda slanja.
    if (typeof FieldStore !== 'undefined') await FieldStore.init();
    if (sbUser?.id !== pripremaOwner) { showToast('⚠ Slanje je prekinuto jer je promijenjen nalog'); return {ok:false,ownerChanged:true}; }
    await _flushAllPendingVlake();
    if (sbUser?.id !== pripremaOwner) { showToast('⚠ Slanje je prekinuto jer je promijenjen nalog'); return {ok:false,ownerChanged:true}; }
    await _retryOrphanVlake();
    if (sbUser?.id !== pripremaOwner) { showToast('⚠ Slanje je prekinuto jer je promijenjen nalog'); return {ok:false,ownerChanged:true}; }
    _OL.loadQueue(true); // oštećen red se ne smije proglasiti praznim/poslanim
  } catch(e) {
    showToast('⚠ Priprema slanja nije uspjela — lokalni podaci ostaju sačuvani');
    return {ok:false,error:e};
  } finally { serverPosalji._priprema = false; _serverSazetakRender(); }
  const prije = _serverNaCekanju();
  if (!prije.stavki) { showToast('✓ Sve je već poslano'); _serverSazetakRender(); return {ok:true,pending:0}; }
  _serverSaljem = true;
  const syncOwner = sbUser.id;
  let ownerChanged = false;
  _mrezaSila(60000);
  _serverSazetakRender();
  showToast('⬆ Šaljem na server…');
  // Na slaboj vezi slanje traje minutama — brojke u panelu i na traci moraju
  // pokazivati da napreduje, inače izgleda kao da je zaglavilo.
  const napredak = setInterval(() => { try { _updSyncBadge(); _serverSazetakRender(); } catch(e) {} }, 1500);
  try {
    // Izričit zahtjev — i ono što je ranije odbijeno ili čeka razmak ide ODMAH.
    try {
      const q = _OL.loadQueue(true).filter(op => !_SERVER_SAMO_LOKALNO.has(op.type));
      q.forEach(op => { if (!op._uid || op._uid === sbUser?.id) { op._blocked = false; op._retries = 0; op._odgode = 0; delete op._retryAt; } });
      localStorage.setItem(_OL.QUEUE, JSON.stringify(q));
    } catch(e) {}
    // Uspješan upis projekta dodaje u red vlake sa pravim ID-jem projekta — njih
    // šalje sljedeći prolaz. Novi prolaz ima smisla SAMO za stavke koje ovaj
    // pritisak još nije pokušao; ono što je upravo palo ne gađa se ponovo, a
    // poslije pada mreže se staje.
    for (let k = 0; k < 3; k++) {
      for (let c = 0; _syncInProgress && c < 600; c++) await new Promise(r => setTimeout(r, 100));
      _mrezaSila(60000);
      const t0 = Date.now();
      await _processOfflineQueue(true);
      if (sbUser?.id !== syncOwner) { ownerChanged = true; break; }
      if (_syncMrezaPalaU >= t0) break;
      let neprobane = 0;
      try {
        neprobane = _OL.loadQueue(true).filter(op => (!op._uid || op._uid === sbUser?.id) &&
          !op._blocked && !op._retries && !op._odgode).length;
      } catch(e) {}
      if (!neprobane) break;
    }
  } catch(e) {
  } finally {
    clearInterval(napredak);
    _serverSaljem = false;
  }
  if (ownerChanged) {
    showToast('⚠ Slanje je prekinuto jer je promijenjen nalog');
    _updSyncBadge();
    return {ok:false};
  }
  const poslije = _serverNaCekanju();
  if (!poslije.stavki) {
    try { localStorage.setItem(_SERVER_ZADNJE_KEY, String(Date.now())); } catch(e) {}
    showToast('✅ Sve poslano na server');
  } else if (poslije.stavki < prije.stavki || poslije.red < prije.red || poslije.doz < prije.doz) {
    try { localStorage.setItem(_SERVER_ZADNJE_KEY, String(Date.now())); } catch(e) {}
    showToast('⚠ Poslano djelimično — ' + poslije.stavki + ' čeka. Pokušaj ponovo.');
  } else {
    showToast('❌ Slanje nije uspjelo — sve ostaje sačuvano na telefonu. Provjeri signal.');
  }
  _updSyncBadge();
  const pan = document.getElementById('syncq-panel');
  if (pan && pan.style.display !== 'none') openSyncQueuePanel(); else _serverSazetakRender();
  const sendError=_OL.loadQueue().find(o=>(!o._uid||o._uid===syncOwner)&&o._lastErr)?._lastErr || _processOfflineQueue._gpsError || null;
  try{_dozLocalStatusRender();}catch(e){}
  return {ok:!poslije.stavki,error:sendError,pending:poslije.stavki,partial:poslije.stavki<prije.stavki || poslije.red<prije.red || poslije.doz<prije.doz};
}

function _fmtAgo(ts) {
  const s = Math.floor((Date.now() - ts) / 1000);
  if (s < 60) return 'Maloprije';
  if (s < 3600) return `Prije ${Math.floor(s/60)} min`;
  if (s < 86400) return `Prije ${Math.floor(s/3600)} h`;
  return `Prije ${Math.floor(s/86400)} d`;
}

window.addEventListener('online', () => {
  try { _netZaboraviKvarove(); } catch(e) {}
  _setOfflineMode(false);
  showToast('🌐 Veza uspostavljena');
  setTimeout(_serverPodsjetnik, 3500);   // poslije ove poruke, ne preko nje
  // Write strana (red čekanja) + read strana (projekti/vlake/dnevnik — oporavak
  // ako je initial fetch pri prijavi pao dok nije bilo veze)
  setTimeout(() => { _processOfflineQueue(true); _reloadCoreData(); }, 1000);
});
window.addEventListener('offline', () => {
  _setOfflineMode(true);
  showToast('📴 Offline — podaci se čuvaju lokalno');
});

// Razlikuje mrežnu grešku (fetch/timeout) od DB/RLS greške (ima Postgres .code)
function _isNetworkErr(err) {
  if (!err) return false;
  if (err.code && /^\d|^PGRST|^2\d|^4\d/.test(String(err.code))) return false; // Postgres/PostgREST kod → nije mreža
  const m = (err.message || '').toLowerCase();
  return m.includes('fetch') || m.includes('network') || m.includes('failed') || m.includes('timeout') || !err.code;
}

// Prolazna greška SERVERA (v1.9.2) — veza radi, ali baza/PostgREST trenutno ne
// može: 'server' = cijeli server (restart, nema konekcije, preopterećen) — nema
// smisla slati ostatak reda; 'upit' = samo ovaj upit (istekao rok, zaključavanje,
// serijalizacija) — ostale stavke mogu proći. Obje su ispravne operacije koje
// će proći kasnije, pa NE smiju trošiti pokušaje (vidi _OL.odgodi).
function _serverPrivremeno(err) {
  if (!err) return null;
  const st = err.status || err.statusCode;
  const c = String(err.code || '');
  if (/^PGRST00[0-3]$/.test(c) || /^08/.test(c) || /^53/.test(c) || /^57P/.test(c)) return 'server';
  if (c === '57014' || c === '40001' || c === '40P01' || c === '55P03') return 'upit';
  if (typeof st === 'number' && st >= 500 && st !== 501) return 'server';
  return null;
}

// D2-D: istek tokena (NE RLS/403). Na ovu grešku osvježimo sesiju i pokušamo ponovo,
// umjesto da se operacija odbaci nakon 5 pokušaja (gubitak snimljene vlake/loga).
function _isAuthErr(err) {
  if (!err) return false;
  const st = err.status || err.statusCode;
  const code = String(err.code || '');
  const m = (err.message || '').toLowerCase();
  if (st === 403 || code === '42501') return false;   // RLS zabrana — legitimno, ne refresh
  return st === 401 || code === 'PGRST301' || /jwt.*expir|token.*expir|unauthor/.test(m);
}

// D2-I: isti refresh-i-pokušaj-ponovo tretman za LIVE (ne-queued) upise — bez ovoga
// istekao token na live putu (npr. sbFlushVlaka) samo tiho pada u offline
// red i čeka SLJEDEĆI prolaz _processOfflineQueue-a da osvježi sesiju.
async function _tryRefreshSession() {
  try {
    const { data } = await sb.auth.refreshSession();
    return !!data?.session;
  } catch(e) { return false; }
}

let _syncInProgress = false, _syncRerun = false;
// v1.8.8: poslije prolaza koji je stao na MREŽNOJ grešci, sljedeći ne kreće
// prije _SYNC_PAUZA_MS. Ranije je svaki poziv (na doznaci je to SVAKA GPS tačka)
// odmah pokretao novi prolaz, pa je mrtva/slaba veza gađana u petlji — prvi
// upis u redu visi do roka, pada, rerun za 50 ms, i tako dok traje snimanje.
// `sila` (ručni "Sync sad", vraćena veza) preskače pauzu.
const _SYNC_PAUZA_MS = 20 * 1000;
let _syncMrezaPalaU = 0, _syncOdgodaT = null;
async function _processOfflineQueue(sila) {
  if (!sbUser || !sbProfile) return;
  // Novi projekat je roditelj članstva/terenskih podataka. Automatski ide
  // samo insert roditelja; ostale operacije i GPS bafer ostaju iza ručne kapije.
  const projektiSamo = !_serverSlanjeDozvoljeno();
  if (projektiSamo) {
    _updSyncBadgeUskoro();
    const pending = typeof _lsJsonMemo === 'function' ? _lsJsonMemo(_OL.QUEUE) : _OL.loadQueue();
    if (!Array.isArray(pending) || !pending.some(op =>
      ['insert_projekt','insert_doz_project'].includes(op.type) &&
      (!op._uid || op._uid === sbUser.id) && !op._blocked)) return;
    if (!sb || sbUser._cachedStub || !_mrezaProbaj()) return;
  }
  // Drugi pozivalac čeka isti prolaz, bez paralelnog inserta. Novi zapis
  // nastao tokom prolaza obrađuje se u rerun-u; poziv za članstvo može čekati.
  if (_syncInProgress) {
    _syncRerun = true;
    return new Promise(resolve => (_processOfflineQueue._waiters ||= []).push(resolve));
  }
  if (sila !== true) {
    const ceka = _SYNC_PAUZA_MS - (Date.now() - _syncMrezaPalaU);
    if (ceka > 0) {
      // Ne gubi poziv — jedan odgođen prolaz kad pauza istekne.
      if (!_syncOdgodaT) _syncOdgodaT = setTimeout(() => { _syncOdgodaT = null; _processOfflineQueue(); }, ceka);
      return;
    }
    if (!_mrezaProbaj()) return;
  }
  _syncInProgress = true;
  let _mrezaPala = false;
  try {
  const syncOwner = sbUser.id;
  const q = _OL.loadQueue(true);
  // OS-V1: NEMA ranog izlaza na prazan red — flush doznaka GPS bafera (i foto) ispod
  // mora se izvršiti i kad korisnik nije imao drugih izmjena (petlja nad [] je no-op).
  let synced = 0;
  let _authRefreshed = false;   // D2-D: osvježi sesiju najviše jednom po prolazu
  let _deleteAuthConfirmed = false;
  // "Nema reda na serveru" smije značiti "već obrisano" samo uz potvrđenu
  // prijavu — anonimni RLS SELECT također vraća prazno.
  const potvrdiPrijavu = async () => {
    if (_deleteAuthConfirmed) return null;
    const a = await sb.auth.getUser();
    const e = a.error || (a.data?.user?.id === syncOwner ? null : {
      code:'AUTH_REQUIRED', status:401, message:'Prijava nije potvrđena; brisanje čeka ponovni pokušaj' });
    _deleteAuthConfirmed = !e;
    return e;
  };
  for (const op of [...q]) {
    if (sbUser?.id !== syncOwner) break;
    // OS-K1: operacija pripada DRUGOM korisniku (red preživljava promjenu naloga na
    // uređaju) — ne šalji je pod tuđom prijavom (RLS bi je odbio pa bi bila tiho
    // odbačena). Preskoči; wipe pri promjeni korisnika ih čisti.
    if (op._uid && sbUser?.id && op._uid !== sbUser.id) continue;
    // v1.9.6: tragovi, dnevnik i tekstualne oznake ostaju samo na telefonu —
    // zaostala stavka iz starije verzije se odbacuje, ne šalje (podatak je u
    // svom lokalnom registru, u redu je bila samo kopija za slanje).
    if (projektiSamo && !['insert_projekt','insert_doz_project'].includes(op.type)) continue;
    if (_SERVER_SAMO_LOKALNO.has(op.type)) { _OL.removeFromQueue(op._qid ?? op.ts); continue; }
    if (op._blocked) continue;
    // Stavka koja je nedavno pala čeka svoj razmak — ručni "Sync sad" ide odmah.
    if ((projektiSamo || sila !== true) && op._retryAt && op._retryAt > Date.now()) continue;
    // Stavka je mogla nestati ili se promijeniti dok je prethodna išla na mrežu.
    // JEDNO čitanje reda po stavci (ranije dva): kad se šalje ručno, red nosi
    // cijeli terenski dan pa je svako parsiranje ~55 ms na srednjem telefonu.
    const _tren = _OL.loadQueue(true).find(current => String(current._qid ?? current.ts) === String(op._qid ?? op.ts));
    if (!_tren) continue;
    try {
      Object.assign(op, _tren);
      if (!op._pokusano && (op.type === 'insert_doz_marking' || op.type === 'insert_projekt' ||
          (op.type === 'upsert_vlaka' && !op.payload?.id))) {
        op._pokusano = true; _OL.oznaciPokusano?.(op._qid ?? op.ts);
      }
      let err = null, vecCisto = false;
      if (op.type === 'delete_vlaka' && !op.payload?.id) {
        // Vlaka obrisana prije nego je dobila ID, a njen upis je možda stigao
        // (izgubljen odgovor) — pronađi je po ključu; nema je = već čisto.
        let look = sb.from('vlake').select('id').eq('korisnik_id', syncOwner).eq('nm', op.payload?.nm ?? '');
        look = op.payload?.projekt_id ? look.eq('projekt_id', op.payload.projekt_id) : look.is('projekt_id', null);
        const found = await look.maybeSingle();
        if (sbUser?.id !== syncOwner) break;
        if (found.error) err = found.error;
        else if (found.data?.id) op.payload.id = found.data.id;
        else { err = await potvrdiPrijavu(); vecCisto = !err; }
      }
      if (err || vecCisto) { /* greška ide kroz zajedničku obradu niže, vecCisto kao uspjeh */ }
      else if (op.type === 'delete_projekt') {
        // Projekat obrisan lokalno dok je njegov upis bio u letu (v3.0.1) —
        // upis je možda stigao. Nema reda na serveru = već čisto.
        const pid = op.payload?.id;
        if (!pid) err = {code:'INVALID_OPERATION',message:'Brisanje nema ID projekta; stavka je sačuvana za pregled'};
        else {
          const cl = await sb.from('projekt_clanovi').delete().eq('projekt_id', pid);
          if (sbUser?.id !== syncOwner) break;
          err = cl.error;
          if (!err) {
            const { data, error } = await sb.from('projekti').delete().eq('id', pid).eq('korisnik_id', syncOwner).select('id');
            if (sbUser?.id !== syncOwner) break;
            err = error;
            if (!err && !(data || []).some(r => String(r.id) === String(pid))) {
              const check = await sb.from('projekti').select('id').eq('id', pid).maybeSingle();
              if (sbUser?.id !== syncOwner) break;
              err = check.error || (check.data === null ? await potvrdiPrijavu() : {code:'NO_CONFIRMATION',message:'Projekat je i dalje na serveru; brisanje čeka ponovni pokušaj'});
            }
          }
        }
      }
      else if (op.type === 'upsert_vlaka') {
        err = await _syncVlakaOperation(op);
      } else if (op.type === 'delete_vlaka') {
        if (!op.payload?.id) err = {code:'INVALID_OPERATION',message:'Brisanje nema ID vlake; stavka je sačuvana za pregled'};
        else {
          const { data, error } = await sb.from('vlake').delete().eq('id', op.payload.id).eq('korisnik_id', syncOwner).select('id');
          err = error;
          if (sbUser?.id !== syncOwner) break;
          if (!err && !(data || []).some(r=>String(r.id)===String(op.payload.id))) {
            // Izgubljen odgovor ili drugo brisanje istog ID-ja: DELETE vraća [].
            // Potvrdi odsustvo čitanjem; prazan odgovor mutacije sam nije dokaz.
            // Keširani profil nije potvrđena prijava. Anonimni RLS SELECT []
            // ne smije biti proglašen uspješnim brisanjem vlastite vlake.
            if (!_deleteAuthConfirmed) {
              const auth = await sb.auth.getUser();
              if (sbUser?.id !== syncOwner) break;
              err = auth.error || (auth.data?.user?.id === syncOwner ? null : {
                code:'AUTH_REQUIRED',status:401,message:'Prijava nije potvrđena; brisanje je sačuvano za ponovni pokušaj'
              });
              _deleteAuthConfirmed = !err;
            }
            if (!err) {
              const check = await sb.from('vlake').select('id,korisnik_id').eq('id',op.payload.id).maybeSingle();
              if (sbUser?.id !== syncOwner) break;
              err = check.error || (check.data === null ? null : {
                code:check.data?.korisnik_id && check.data.korisnik_id !== syncOwner ? 'WRITE_FORBIDDEN' : 'NO_CONFIRMATION',
                message:check.data?.korisnik_id && check.data.korisnik_id !== syncOwner
                  ? 'Vlaku može obrisati samo projektant koji ju je napravio; izmjena nije izvršena'
                  : 'Vlaka je i dalje na serveru ili provjera nije potpuna; brisanje čeka ponovni pokušaj'
              });
            }
          }
        }
      } else if (op.type === 'insert_doz_marking') {
        // Ponovljen ID potvrđuje se čitanjem vlasnika, odjela i sadržaja zone.
        const { data, error } = await _dozUpisiZonu(op.payload);
        err = error;
        const newMkId = data?.id || op.payload.id;
        if(!err && newMkId)op.payload.id=newMkId;
        if (!err && newMkId && op._localId) {
          // D4-B: zamijeni privremeni 'local_' ID stvarnim server ID-jem da kasnije
          // brisanje ove markice može pogoditi pravi red (inače ghost-resurrection).
          const dm = _dozMarkings.find(m => m.id === op._localId);
          if (dm) { dm.id = newMkId; _dozCacheLayers(dm.project_id); }
        }
      } else if (op.type === 'upsert_odjel') {
        const { error } = await sb.from('odjeli').upsert(op.payload, { onConflict: 'sumarija,naziv', ignoreDuplicates: true });
        err = error;
      } else if (op.type === 'insert_projekt') {
        const { _tempId, ...insertPayload } = op.payload;
        let { data: pd, error } = await _serverInsertPotvrdjeno('projekti',insertPayload);
        if (sbUser?.id !== syncOwner) break;
        err = error;
        if (!err && pd) {
          const realId = pd.id;
          // Swap tempId → realId in remaining queue entries (both in-memory copy and localStorage)
          q.forEach(qOp => {
            if (qOp.payload?.projekt_id === _tempId) qOp.payload.projekt_id = realId;
          });
          const lq = _OL.loadQueue();
          lq.forEach(qOp => { if (qOp.payload?.projekt_id === _tempId) qOp.payload.projekt_id = realId; });
          localStorage.setItem(_OL.QUEUE, JSON.stringify(lq));
          // Update in-memory vlake + re-flush na server s ispravnim projekt_id
          const migratedVlakeIdxs = [];
          vlake.forEach((v, vi) => { if (v.projektId === _tempId) { v.projektId = realId; migratedVlakeIdxs.push(vi); } });
          migratedVlakeIdxs.forEach(vi => sbFlushVlaka(vi));
          // Update vlake cache
          const cv = _OL.load(_OL.VLAKE) || [];
          cv.forEach(r => { if (r.projekt_id === _tempId) r.projekt_id = realId; });
          _OL.save(_OL.VLAKE, cv);
          // Update _projekti
          const pi = _projekti.findIndex(p => p.id === _tempId);
          if (pi >= 0) _projekti[pi] = { ..._projekti[pi], id: realId, _pendingSync: false };
          if (_aktivniProjektId === _tempId) {
            _aktivniProjektId = realId;
            localStorage.setItem('tvlake_akt_proj', realId);
          }
          if (_OL.save(_OL.PROJEKTI, _projekti) === false) {
            if (pi >= 0) _projekti[pi]._pendingSync = true;
            err = {code:'LOCAL_CACHE_FAILED',message:'Projekat je na serveru, ali lokalni keš nije sačuvan. Oslobodi prostor; zapis ostaje u redu.'};
          }
          _updVlakeMapVisibility();
          rndProjektiList();
        }
      } else if (op.type === 'insert_doz_project') {
        const { _tempId, ...insertPayload } = op.payload;
        let { data: dp, error } = await _serverInsertPotvrdjeno('doz_projects',insertPayload);
        if (sbUser?.id !== syncOwner) break;
        err = error;
        if (!err && dp) {
          const realId = dp.id;
          // Swap tempId → realId u preostalim redovima čekanja (npr. zona nacrtana
          // na ovom odjelu prije nego što je sam odjel stigao na server) — isti
          // obrazac kao insert_projekt za vlake.
          q.forEach(qOp => { if (qOp.payload?.project_id === _tempId) qOp.payload.project_id = realId; });
          q.forEach(qOp => { if (qOp.type === 'upsert_doz_status' && qOp.payload?.id === _tempId) qOp.payload.id = realId; });
          const lq = _OL.loadQueue();
          lq.forEach(qOp => { if (qOp.payload?.project_id === _tempId) qOp.payload.project_id = realId; });
          lq.forEach(qOp => { if (qOp.type === 'upsert_doz_status' && qOp.payload?.id === _tempId) qOp.payload.id = realId; });
          localStorage.setItem(_OL.QUEUE, JSON.stringify(lq));
          // Update in-memory zone (_dozMarkings) + keš ako je ovaj odjel trenutno otvoren
          (_dozMarkings || []).forEach(m => { if (m.project_id === _tempId) m.project_id = realId; });
          const oi = _dozOdjeli.findIndex(o => o.id === _tempId);
          if (oi >= 0) _dozOdjeli[oi] = { ..._dozOdjeli[oi], id: realId, _pendingSync: false };
          if (_dozSelId === _tempId) {
            _dozSelId = realId;
            _OL.save(_OL.DOZ_SEL_ID, realId);
          }
          if (_OL.save(_OL.DOZ_ODJELI, _dozOdjeli) === false) {
            if (oi >= 0) _dozOdjeli[oi]._pendingSync = true;
            err = {code:'LOCAL_CACHE_FAILED',message:'Odjel je na serveru, ali lokalni keš nije sačuvan. Oslobodi prostor; zapis ostaje u redu.'};
          }
          // Migriraj i keš stabala (tvlake_doz_trees_data) — ključan po ID-u
          // odjela. Bez ovoga stabla učitana dok je odjel bio offline (tempId)
          // "nestanu" poslije sync-a: restore traži pod realId, a zapis ostaje
          // zauvijek orphaned pod starim temp ključem.
          try {
            const tk = JSON.parse(localStorage.getItem(_DOZ_TREES_DATA_KEY) || '{}');
            if (tk[_tempId] && realId !== _tempId) {
              tk[realId] = tk[_tempId]; delete tk[_tempId];
              localStorage.setItem(_DOZ_TREES_DATA_KEY, JSON.stringify(tk));
            }
          } catch(e) {}
          // Kreator kao manager-član — best effort, ne blokira (created_by RLS ionako
          // već daje kreatoru pun pristup i bez ovog reda; vidi dozSaveOdjel).
          try {
            await sb.from('doz_project_members').insert({
              project_id: realId, user_id: sbUser.id, role: 'manager',
              track_color: DOZ_ENG_COLORS[0], order_index: 0, is_active: true
            });
          } catch(e) {}
          if (typeof dozRenderOdjeli === 'function') dozRenderOdjeli();
          if (typeof _dozRenderOverview === 'function') _dozRenderOverview();
        }
      } else if (op.type === 'delete_doz_marking') {
        const { data, error } = await sb.from('doz_area_markings').update({ is_visible: false }).eq('id', op.payload.id).select('id');
        err = error;
        if (!err && !(data || []).some(r => String(r.id) === String(op.payload.id))) {
          // Zona čiji upis nikad nije stigao, ili je cijeli odjel u međuvremenu
          // obrisan (atomarno brisanje odjela briše i zone): cilja nema, a to je
          // upravo ono što brisanje traži. Ranije je takva stavka zauvijek
          // stajala u "čeka slanje" uz NO_CONFIRMATION.
          const check = await sb.from('doz_area_markings').select('id,is_visible').eq('id', op.payload.id).maybeSingle();
          if (sbUser?.id !== syncOwner) break;
          err = check.error || (check.data?.is_visible === false ? null
            : check.data === null ? await potvrdiPrijavu()
            : { code:'NO_CONFIRMATION', message:'Server nije potvrdio ciljanu zonu' });
        }
      } else if (op.type === 'upsert_doz_status') {
        if (!op.payload?.id || !['active','paused','completed'].includes(op.payload.status)) {
          err = {code:'INVALID_OPERATION',message:'Neispravan ID ili status odjela; stavka je sačuvana za pregled'};
        } else {
          const { data, error } = await sb.from('doz_projects').update({ status: op.payload.status }).eq('id', op.payload.id).eq('created_by',syncOwner).select('id,status');
          err = error;
          if (sbUser?.id !== syncOwner) break;
          if (!err && !(data || []).some(r => String(r.id) === String(op.payload.id) && r.status === op.payload.status)) {
            const check = await sb.from('doz_projects').select('id,status,created_by').eq('id',op.payload.id).maybeSingle();
            if (sbUser?.id !== syncOwner) break;
            if (check.error) err = check.error;
            else if (check.data?.id === op.payload.id && check.data.status === op.payload.status) err = null;
            else if (check.data === null && !_OL.loadQueue(true).some(o => o.type === 'insert_doz_project' && o.payload?.id === op.payload.id)) {
              // Odjel je obrisan (ili nikad neće stići): status nečega što ne
              // postoji nema šta promijeniti — ranije je stajao u "čeka slanje"
              // zauvijek i "Sve poslano" se nikad nije pojavilo.
              err = await potvrdiPrijavu();
            }
            else if (check.data === null) err = {code:'TARGET_NOT_FOUND',message:'Odjel nije dostupan na serveru. Pošalji novi odjel ili provjeri članstvo; status je sačuvan'};
            else if (check.data?.created_by && check.data.created_by !== syncOwner) err = {code:'WRITE_FORBIDDEN',message:'Status odjela može mijenjati samo njegov kreator; snimljeni pojasevi šalju se zasebno'};
            else err = {code:'NO_CONFIRMATION',message:'Status odjela nije promijenjen na serveru; provjeri pravo upisa i pokušaj ponovo'};
          }
        }
      } else if (op.type === 'insert_pozari_arhiva') {
        // Dijeljena arhiva požara (v1.1.1) — ignoreDuplicates jer isti
        // (godina,dan,la,lo) zapis sasvim OČEKIVANO stiže sa VIŠE uređaja
        // (svako viđenje istog vrelog piksela istog dana) — ON CONFLICT DO
        // NOTHING, ne update (append-only istorijski zapis, vidi migraciju).
        const { error } = await sb.from('pozari_arhiva').upsert(op.payload, { onConflict: 'godina,dan,la,lo', ignoreDuplicates: true });
        err = error;
      } else {
        err = { code:'UNSUPPORTED_OPERATION', message:'Nepoznat tip operacije: ' + String(op.type || '') };
      }
      if (sbUser?.id !== syncOwner) break;
      if (!err) {
        if(typeof _serverTransferConfirmed==='function') _serverTransferConfirmed(op,syncOwner);
        _OL.removeFromQueue(op._qid ?? op.ts); synced++;
      }
      else if (_isAuthErr(err)) {
        // D2-D: istekao token → osvježi sesiju (jednom) i re-okini prolaz s NOVIM tokenom.
        // Op ostaje u redu (ne bumpRetry/odbacivanje). Re-okini SAMO ako je refresh dao
        // važeću sesiju — inače (stvarno odjavljen) prekini bez rerun-a da nema petlje.
        if (!_authRefreshed) {
          _authRefreshed = true;
          let ok = false;
          try { const { data } = await sb.auth.refreshSession(); ok = !!data?.session; } catch(e) {}
          if (ok) _syncRerun = true;
        }
        break;   // prekini prolaz; ostatak reda ide u rerun (ako je refresh uspio) ili kasnije
      }
      else if (_serverPrivremeno(err)) {
        _OL.odgodi(op._qid ?? op.ts, { code: err?.code || '', message: err?.message || String(err) });
        if (_serverPrivremeno(err) === 'server') { _mrezaPala = true; break; }
      }
      else if (_isNetworkErr(err)) {
        // Mrežna greška vraćena kao {error} (ne bačena): ranije je petlja išla na
        // SLJEDEĆU operaciju, pa je na mrtvoj vezi svaka čekala svoj rok od 15 s,
        // jedna za drugom. Veza je ista za sve — prekini prolaz, ostatak čeka.
        _mrezaPala = true;
        break;
      }
      else {
        // Ne-mrežna greška (RLS, istekao token, privremeni 4xx/5xx). Ne odbacuj
        // odmah — daj 5 pokušaja prije nego se operacija proglasi trajno
        // neispravnom. Sprečava tihi gubitak snimljenih vlaka.
        const dropped = _OL.bumpRetry(op._qid ?? op.ts, 5, { code: err?.code || '', message: err?.message || String(err) });
        if (dropped) {
          console.warn('Offline queue: operacija sačuvana za ručni pokušaj', op.type);
          // OS-N1: tihi drop = tihi gubitak podataka — korisnik MORA vidjeti da je izmjena odbačena.
          // Kod greške ide u poruku (ne samo konzolu) — bez toga se ne može dijagnosticirati na terenu.
          const errCode = err?.code ? (' [' + err.code + ']') : '';
          showToast('⚠ Jedna offline izmjena (' + op.type.replace(/_/g, ' ') + ') čeka ručni pokušaj; podaci su sačuvani' + errCode);
        }
      }
    } catch(e) {
      if (_isNetworkErr(e)) { _mrezaPala = true; break; }
      _OL.bumpRetry(op._qid ?? op.ts, 5, { code: e.code || '', message: e.message || String(e) });
    }
  }
  if (sbUser?.id !== syncOwner) return;
  // ID dodijeli i trajno upiši PRIJE slanja, uključujući legacy bafer.
  if (!projektiSamo) try {
    if (sbUser?.id !== syncOwner) return;
    if (_mrezaPala) throw new Error('veza pala u ovom prolazu');   // GPS tačke čekaju sljedeći
    const all = typeof FieldStore !== 'undefined' ? await FieldStore.read(syncOwner) : JSON.parse(localStorage.getItem(_DOZ_TRACK_BUF_KEY) || '[]');
    all.forEach(pt => { if (!pt._qid) pt._qid = _genUUID(); });
    if (typeof FieldStore === 'undefined') localStorage.setItem(_DOZ_TRACK_BUF_KEY, JSON.stringify(all));
    // v1.9.2: u SERIJAMA po odjelu (vidi _dozPosaljiKomad), ne tačka po tačka.
    const grupe = {};
    const sirocad = typeof _dozSirocad === 'function' ? _dozSirocad() : new Set();
    all.filter(p => p.user_id === syncOwner && !sirocad.has(p.project_id)).forEach(p => { (grupe[p.project_id] = grupe[p.project_id] || []).push(p); });
    _processOfflineQueue._gpsError=null;
    vanjska: for (const g of Object.values(grupe)) {
      g.sort((a, b) => Date.parse(a.recorded_at) - Date.parse(b.recorded_at));
      for (let i = 0; i < g.length; i += _DOZ_KOMAD) {
        if (sbUser?.id !== syncOwner) break vanjska;
        const komad = g.slice(i, i + _DOZ_KOMAD);
        let r = await _dozPosaljiKomad(komad);
        // Jedna loša tačka (FK/RLS) ne smije držati cijelu seriju — ta serija ide
        // pojedinačno, pa dobre prođu, a loša ostaje sačuvana.
        if (r.error && !_isNetworkErr(r.error) && !_isAuthErr(r.error) && !_serverPrivremeno(r.error)) {
          r = await _dozPosaljiPojedinacno(komad);
          // Nijedna tačka nije prošla na stranom ključu: postoji li odjel uopšte?
          // Ako ne (i ne čeka upis u redu), grupa se više ne šalje.
          if (!r.ok.length && String(r.error?.code) === '23503') {
            const pid = komad[0].project_id;
            const ch = await sb.from('doz_projects').select('id').eq('id', pid).maybeSingle();
            if (sbUser?.id !== syncOwner) break vanjska;
            const ceka = _OL.loadQueue(true).some(o => o.type === 'insert_doz_project' && o.payload?.id === pid);
            if (!ch.error && ch.data === null && !ceka && !(await potvrdiPrijavu())) {
              _dozSirocadDodaj(pid);
              continue vanjska;
            }
          }
        }
        if(r.error)_processOfflineQueue._gpsError=r.error;
        if (r.ok.length) {
          const ok = new Set(r.ok);
          if (typeof FieldStore !== 'undefined') await FieldStore.acknowledge(syncOwner,[...ok]);
          else {
            const current = JSON.parse(localStorage.getItem(_DOZ_TRACK_BUF_KEY) || '[]');
            localStorage.setItem(_DOZ_TRACK_BUF_KEY, JSON.stringify(current.filter(p => !ok.has(p._qid))));
          }
          if(typeof _serverTransferConfirmed==='function') _serverTransferConfirmed({type:'doz_track_points',payload:komad.find(p=>ok.has(p._qid)),_count:r.ok.length},syncOwner);
          synced += r.ok.length;
        }
        if (r.error && (_isNetworkErr(r.error) || _serverPrivremeno(r.error))) { _mrezaPala = true; break vanjska; }
        if (r.error && _isAuthErr(r.error)) break vanjska;
      }
    }
  } catch(e) { /* Lokalni bafer ostaje; pokušaj ponovo nakon povratka veze. */ }
  // Ručno slanje javlja ishod SAMO (serverPosalji) — dvije poruke jedna preko druge su šum.
  if (synced && projektiSamo) {
    try { localStorage.setItem(_SERVER_ZADNJE_KEY,String(Date.now())); } catch(e) {}
    if (typeof _serverSazetakRender === 'function') _serverSazetakRender();
  }
  if (synced && !_serverSaljem) showToast(projektiSamo ? '✅ Novi projekat potvrđen na serveru' : `✅ Poslano na server: ${synced}`);
  if (typeof _updSyncBadge === 'function') _updSyncBadge();
  } finally {
    _syncInProgress = false;
    const waiters = _processOfflineQueue._waiters || [];
    _processOfflineQueue._waiters = [];
    waiters.forEach(resolve => resolve());
    if (_mrezaPala) _syncMrezaPalaU = Date.now();
    // Rerun ide kroz isti ulaz, pa poslije mrežnog pada poštuje pauzu (ne petlja).
    if (_syncRerun) { _syncRerun = false; setTimeout(_processOfflineQueue, 50); }   // obradi preskočeno/dodano
  }
}


// Bez otvaranja ručne kapije za vlake/pojaseve. Pozivi na startu, nakon
// povratka veze/na svakih 60 s ponavljaju samo trajno sačuvane nove projekte.
function _autoPosaljiNoveProjekte() {
  return _processOfflineQueue().catch(() => {});
}

async function _projektServerSpreman(kind, id, owner) {
  const table = kind === 'doznaka' ? 'doz_projects' : 'projekti';
  const ownerKey = kind === 'doznaka' ? 'created_by' : 'korisnik_id';
  const lookup = () => (kind === 'doznaka' ? _dozOdjeli : _projekti).find(p => p.id === id);
  const valid = () => sbUser?.id === owner && lookup()?.[ownerKey] === owner;
  if (!valid()) return false;
  if (!sb || sbUser._cachedStub || !_mrezaProbaj()) {
    showToast('Dodavanje projektanta traži internet. Projekat je sačuvan i šalje se automatski kad se veza vrati.');
    return false;
  }
  try {
    // Ako drugi prolaz već traje, sačekaj ga. Zapis dodan poslije njegovog
    // snapshot-a treba još jedan prolaz; bez ponavljanja upravo palog zahtjeva.
    for (let n = 0; lookup()?._pendingSync && n < 2; n++) {
      await _processOfflineQueue();
      if (!valid()) return false;
    }
    if (lookup()?._pendingSync) {
      showToast('Projekat još nije potvrđen na serveru. Sačuvan je za ponovno slanje; provjeri vezu ili Detalji i greške slanja.');
      return false;
    }
    const r = await sb.from(table).select('id,' + ownerKey).eq('id',id).eq(ownerKey,owner).maybeSingle();
    if (!valid()) return false;
    if (r.error) throw r.error;
    if (!r.data || r.data.id !== id || r.data[ownerKey] !== owner) {
      showToast('Projekat nije dostupan na serveru. Osvježi projekte prije dodavanja projektanta.');
      return false;
    }
    return true;
  } catch(e) {
    if (sbUser?.id === owner) showToast(_isNetworkErr(e)
      ? 'Veza nije potvrdila projekat. Članstvo nije slano; pokušaj kad se signal popravi.'
      : 'Projekat nije potvrđen: ' + (e.message || String(e)));
    return false;
  }
}

function _showAuthScreen() {
  document.getElementById('auth-screen').style.display = 'flex';
  authShowLogin();
  _authStatusSync();
}

// Ulazak u aplikaciju na KEŠIRANOM profilu (v3.117.0). Jedno mjesto za sve
// putanje koje moraju pustiti korisnika unutra bez mreže — ranije je svaka
// ponavljala isti niz koraka (stub korisnik, profil, offline oznaka, showApp) i
// lako su se razilazile: jedna bi zaboravila _cachedStub, druga _setOfflineMode.
// Vraća true ako je korisnik ušao (ili je već bio unutra), false ako se nemamo
// na šta osloniti — TEK tada je login ekran ispravan ishod.
// Namjerno čita keš SVAKI put umjesto da prima zapamćenu vrijednost: pozivaoci
// su razmaknuti sekundama (sigurnosna mreža na 6 s), a profil je u međuvremenu
// mogao biti osvježen.
function _ulazNaKesu() {
  if (_appEntered) return true;              // već unutra — ne diraj ekran
  let cached = null;
  try { cached = (typeof _OL !== 'undefined' && _OL && _OL.load) ? _profileLoad(sbUser && !sbUser._cachedStub ? sbUser.id : null) : null; } catch(e) {}
  if (!cached || !cached.id) return false;
  // _cachedStub: ovo NIJE prava Supabase sesija. Svaka provjera "imamo li
  // sesiju" mora glasiti `sbUser && !sbUser._cachedStub` (vidi CLAUDE.md).
  sbUser = { id: cached.id, email: cached.email || '', _cachedStub: true };
  sbProfile = cached;
  try { _setOfflineMode(true); } catch(e) {}
  showApp();
  showToast('📴 Offline pristup — lokalni podaci');
  return true;
}

// Je li showApp() već pozvan u ovoj sesiji stranice. Sprječava DRUGI poziv
// showApp()-a (koji bi ponovo pokrenuo sve restore-e: slojeve karte, tačke,
// fotose, SQLite karte — dupli slojevi) kad kasnija online nadogradnja stigne
// poslije offline-first ulaska.
let _appEntered = false;

// Prelazak sa keširanog (offline-first) ulaska na PUNU online sesiju. Poziva se
// tek kad Supabase STVARNO potvrdi sesiju. Namjerno NE zove showApp() ponovo —
// korisnik je već u app-u i radi; ovdje se dovršava samo ono što offline ulazak
// nije mogao: skida se OFFLINE oznaka, povlače svježi podaci sa servera i gura
// se red čekanja. _reloadCoreData je po dizajnu idempotentan (svaki njegov
// poziv ima vlastite keš guardove), pa je ponovni poziv jeftin i siguran.
// Otkriva app (skida login ekran, prikazuje glavni prozor). Idempotentno —
// showApp() ga zove dvaput: rano (čim se zna da gate odobrenja ne blokira, da
// korisnik ne gleda logo dok traju provjere) i na starom mjestu, poslije njih.
// Ovdje je JEDINO mjesto gdje se postavlja _appEntered: tek tu je korisnik
// stvarno u app-u, pa kasnije auth putanje po tome znaju da ne smiju dizati
// login preko njega niti ponovo zvati showApp() (dupli restore slojeva).
function _revealApp() {
  document.getElementById('auth-screen').style.display = 'none';
  document.getElementById('wrapper').style.display = 'flex';
  _appEntered = true;
}

async function _upgradeToOnlineSession() {
  _setOfflineMode(!navigator.onLine);
  try { await sbLoadProfile(); } catch(e) {}
  // Prvi put kad opet imamo pravu sesiju saznajemo i je li pristup u
  // međuvremenu OPOZVAN (dok se radilo offline na keširanom profilu). Isti
  // tretman kao _provjeriOpozivOdobrenja — bez ovoga bi opozvan korisnik ostao
  // u app-u do sljedećeg vraćanja iz pozadine.
  if (sbProfile && sbProfile.odobren === false && !sbProfile.is_admin && !(typeof AccessPolicy!=='undefined' && AccessPolicy.canUse(sbProfile))) {
    _showAuthScreen();
    authShowPending();
    return;
  }
  try { sbStartRealtime(); } catch(e) {}
  try { _reloadCoreData(); } catch(e) {}
  try { _processOfflineQueue(); } catch(e) {}
}

async function initAuth() {
  // getSession čita lokalno sačuvanu Supabase sesiju i radi i bez interneta.
  // Njegov uid je autoritativan: stari profil drugog naloga se ne smije otvoriti.
  let startupSessionUser = null;
  try {
    if (sb?.auth?.getSession) {
      const s = await Promise.race([
        sb.auth.getSession(), new Promise(resolve => setTimeout(() => resolve(null), 350))
      ]);
      startupSessionUser = s?.data?.session?.user || null;
    }
  } catch(e) {}
  const cached = _profileLoad(startupSessionUser?.id || null);
  const saved = _loadSavedUser();

  // BUG (prijavljeno s terena, popravljeno u v3.92.1): offline ulazak je ranije
  // zahtijevao I keširani profil I zapamćen PIN (checkbox "Zapamti me" na login
  // formi) — `hasLocalData = cached && saved`. To je pogrešno spajalo dvije
  // odvojene stvari: `cached` je dokaz da je OVAJ uređaj već bio uspješno
  // prijavljen (dovoljno za offline nastavak), dok je `saved` samo opcioni PIN
  // za TIHI re-login kad istekne Supabase sesija — ako korisnik nije čekirao
  // "Zapamti me" (ili ga je isčekirao), `saved` je null i korisnik je ranije
  // bio izbačen na login ekran ČIM bi zaista bio offline, iako je uredno
  // prijavljen i ima keširan profil. Sad je keširani profil SAM PO SEBI
  // dovoljan za offline pristup na sva tri mjesta ispod; `saved` PIN se i
  // dalje koristi samo za pokušaj TIHOG re-logina (dobija svježu sesiju, pa
  // sync ponovo radi), ne kao uslov za offline ulazak.

  // OFFLINE-FIRST ULAZAK (v3.100.0): keširani profil = ODMAH u app, BEZ ikakvog
  // čekanja na mrežu. Ranije se ulazilo odmah samo ako je navigator.onLine već
  // javljao false ili Supabase klijent nije postojao — a na terenu navigator
  // .onLine notorno laže 'true' na mrtvoj/slaboj vezi (OS-S4), pa se ulazilo u
  // sporiji "prvo probaj online" put: korisnik čeka 1.5-4.5s (ili duže, jer
  // spor poziv VISI umjesto da padne) prije nego uopšte vidi kartu, a znao je
  // završiti i na login ekranu iako je uredno prijavljen.
  //
  // Sad je redoslijed obrnut i odgovara stvarnoj upotrebi u šumi: karta,
  // lokacija i lokalni podaci rade UVIJEK i odmah, a puna online sesija se
  // dohvaća TIHO U POZADINI (_upgradeToOnlineSession ispod). Ako je stvarno
  // ima — sve online mogućnosti se uključe same; ako nema — sve ostaje u
  // lokalnom redu čekanja i ode na server kad se veza stvarno pojavi
  // (postojeći 'online' event → _processOfflineQueue + _reloadCoreData).
  if (cached) {
    // _cachedStub: označava da je ovo profil iz keša, a NE stvarna Supabase
    // sesija — po tome niže znamo da online nadogradnju treba još pokušati.
    sbUser = startupSessionUser || { id: cached.id, email: cached.email || '', _cachedStub: true };
    sbProfile = cached;
    _setOfflineMode(!navigator.onLine);
    showApp();
    if (!navigator.onLine || !sb) {
      showToast('📴 Offline pristup — lokalni podaci');
      return;   // stvarno nema šta pokušati online
    }
    // Ima (navodno) mreže — nastavi ISPOD na tihu online nadogradnju. Korisnik
    // je već u app-u; ništa ispod ne smije vratiti login ekran preko njega.
  } else {
    // Nema keširanog profila — nema se na šta osloniti, mora login
    _showAuthScreen();
  }

  // 1. Pokušaj Supabase sesiju
  if(!sb){ if(!_appEntered) _showAuthScreen(); return; }
  sb.auth.onAuthStateChange(async (event, session) => {
    // Uslov uključuje _cachedStub: kod offline-first ulaska sbUser JEST postavljen
    // (iz keša), ali to nije prava sesija — kad Supabase potvrdi stvarnu, ovdje se
    // radi tiha nadogradnja umjesto da se događaj preskoči.
    if (event === 'INITIAL_SESSION' && session && (!sbUser || sbUser._cachedStub)) {
      try {
        sbUser = session.user;
        if (_appEntered) { await _upgradeToOnlineSession(); }
        else { await sbLoadProfile(); showApp(); }
        return;
      } catch(e) {
        console.error('Auth init error:', e);
      }
    }
    // D2-J: proaktivno re-subscribe realtime kanala nakon token refresh-a, umjesto da se
    // oslanjamo samo na reaktivni _onRtStatus fallback (koji čeka da kanal prvo pukne).
    if (event === 'TOKEN_REFRESHED' && sbUser) {
      try { sbStartRealtime(); } catch(e) {}
    }
  });

  // Sesija je pronađena lokalno prije auth callbacka. Ne čekaj mrežu niti
  // INITIAL_SESSION događaj da potvrdi identitet profila.
  if (startupSessionUser) {
    sbUser = startupSessionUser;
    if (_appEntered) await _upgradeToOnlineSession();
    else { await sbLoadProfile(); if (sbProfile) await showApp(); }
    return;
  }

  // Pomoćnik: bilo kakav neuspjeh online logina kad IMAMO keširani profil
  // NIKAD ne smije izbaciti korisnika na login ni obrisati kredencijale —
  // na terenu navigator.onLine zna lažno biti true, a Supabase tiho vrati null.
  const goOfflineOrLogin = () => {
    if (_appEntered) {
      // Offline-first ulazak je već pustio korisnika u app — online nadogradnja
      // nije uspjela. NE diramo ekran (nikakav login preko korisnika koji radi),
      // samo označimo stvarno stanje: radi se lokalno, red čekanja ide na server
      // kad se veza stvarno pojavi ('online' event → _processOfflineQueue).
      if (!_isOfflineMode) {
        _setOfflineMode(true);
        showToast('📴 Offline pristup — lokalni podaci');
      }
      return;
    }
    // Isti helper koji koristi i sigurnosna mreža — jedan put unutra, jedno
    // ponašanje. Login TEK ako nema keširanog profila.
    if (!_ulazNaKesu()) _showAuthScreen();
  };

  // 2. Fallback: auto-login sa zapamćenim kredencijalima (ako PIN nije
  //    zapamćen, nemamo šta pokušati online — odmah offline-ili-login)
  setTimeout(async () => {
    if (sbUser && !sbUser._cachedStub) return;   // već imamo PRAVU sesiju
    if (!saved) { goOfflineOrLogin(); return; }
    try {
      // OS-S4: navigator.onLine na terenu zna lagati 'true' na mrtvoj vezi — RPC bi
      // tada visio do Supabase timeouta i korisnik bi čekao 4500ms fallback. Kad
      // postoji keširani profil, utrkuj prvi mrežni korak s 1500ms — na timeout
      // odmah offline ulaz (auto-login se ionako ponovi pri sljedećem pokretanju).
      const _tmo = cached
        ? new Promise((_, rej) => setTimeout(() => rej(new Error('_autologin_timeout')), 1500))
        : null;
      const emailPromise = sb.rpc('get_login_email', { p_ime: saved.ime, p_prezime: saved.prezime });
      const { data: email } = await (_tmo ? Promise.race([emailPromise, _tmo]) : emailPromise);
      if (!email) { goOfflineOrLogin(); return; }
      const { error } = await sb.auth.signInWithPassword({ email, password: saved.pin.padEnd(6, '0') });
      if (error) { goOfflineOrLogin(); return; }
      sbUser = (await sb.auth.getUser()).data.user;
      if (_appEntered) { await _upgradeToOnlineSession(); }
      else { await sbLoadProfile(); showApp(); }
    } catch(e) {
      if (e?.message !== '_autologin_timeout') console.error('Auto-login error:', e);
      if (!sbUser || sbUser._cachedStub) goOfflineOrLogin();
    }
  }, 800);

  // 3. Offline fallback — ako mreža nije dala pravu sesiju do sada
  setTimeout(async () => {
    if (sbUser && !sbUser._cachedStub) return;
    goOfflineOrLogin();
  }, 4500);
}

function _loadSavedUser() {
  try { return JSON.parse(localStorage.getItem(_SAVED_USER_KEY)); } catch { return null; }
}
function _clearSavedUser() {
  localStorage.removeItem(_SAVED_USER_KEY);
}

// ─── Offline prijava poslije ODJAVE (v3.1.4) ─────────────────────────────────
// _clearSavedUser() pri odjavi briše ime/PIN iz `tvlake_saved_user` (da se PIN ne
// pre-popunjava na dijeljenom telefonu), a offline prijava je provjeravala baš taj
// zapis — pa je korisnik koji se odjavi NA TERENU bez signala ostajao zaključan
// ("ponovna prijava nakon odjave traži internet") iako mu je profil i sav lokalni
// rad bio na telefonu. Zato se pri svakoj uspješnoj prijavi čuva i odvojen zapis za
// PROVJERU (ne za prikaz): SHA-256 sa solju umjesto otvorenog PIN-a, ključ je
// ime+prezime. Odjava ga NE briše; polja za prijavu se i dalje ne pre-popunjavaju.
const _OFFCRED_KEY = 'tvlake_offline_cred_v1';
function _offCredKljuc(ime, prezime) {
  return (String(ime||'').trim() + '|' + String(prezime||'').trim()).toLowerCase();
}
async function _offCredHash(kljuc, pin) {
  const tekst = 'dm1|' + kljuc + '|' + pin;
  try {
    if (crypto && crypto.subtle) {
      const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(tekst));
      return 's:' + Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('');
    }
  } catch(e) {}
  return 'p:' + btoa(unescape(encodeURIComponent(tekst)));   // WebView bez crypto.subtle
}
function _offCredLoad() {
  try { const o = JSON.parse(localStorage.getItem(_OFFCRED_KEY)); return o && typeof o === 'object' && !Array.isArray(o) ? o : {}; }
  catch(e) { return {}; }
}
async function _offCredSpremi(ime, prezime, pin, uid) {
  if (!ime || !pin || !uid) return false;
  try {
    const m = _offCredLoad(), k = _offCredKljuc(ime, prezime);
    m[k] = { uid, h: await _offCredHash(k, pin) };
    localStorage.setItem(_OFFCRED_KEY, JSON.stringify(m));
    return true;
  } catch(e) { return false; }
}
// Uređaji prijavljeni PRIJE v3.2.0 imaju samo `saved` zapis: prepiši ga u trajni
// oblik odmah pri učitavanju, da se i oni mogu offline vratiti poslije odjave.
(function _offCredMigracija() {
  try {
    const sv = _loadSavedUser(), pr = _OL.load(_OL.PROFILE);
    if (sv && sv.ime && sv.pin && pr && pr.id) _offCredSpremi(sv.ime, sv.prezime, sv.pin, pr.id);
  } catch(e) {}
})();
// Vraća uid korisnika čiji ime+PIN odgovaraju, inače null.
async function _offCredProvjeri(ime, prezime, pin) {
  try {
    const k = _offCredKljuc(ime, prezime), z = _offCredLoad()[k];
    if (z && z.uid && z.h && z.h === await _offCredHash(k, pin)) return z.uid;
  } catch(e) {}
  return null;
}

async function sbLoadProfile() {
  let data = null;
  try {
    const { data: d, error } = await sb.from('korisnici').select('*').eq('id', sbUser.id).single();
    if (!error && d && d.id === sbUser.id) { data = d; _profileSave(d); }
  } catch(e) {}
  if (!data) data = _profileLoad(sbUser?.id); // samo keš OVOG korisnika
  sbProfile = data;
  if (typeof _menuIdentityRender === 'function') _menuIdentityRender();
  if(typeof _accessTrialArm==='function'&&typeof _appEntered!=='undefined'&&_appEntered)_accessTrialArm();
  if (!data) return;
  const fullName = ((data.ime || '') + ' ' + (data.prezime || '')).trim();
  document.getElementById('p-ime').value = fullName;
  if (data.sumarija) document.getElementById('p-sumarija').value = data.sumarija;
  _primijeniUlogeUI(data);
}

// Vidljivost tabova/stavki menija po ulozi. Izdvojeno iz sbLoadProfile: offline-first
// ulaz na keširanom profilu (_ulazNaKesu, auto-login fallback) NE zove sbLoadProfile,
// pa admin na slabom signalu nikad nije dobio tab Korisnici (display:none po zadanom).
// Idempotentno — showApp() je zove za svaki ulaz, bez obzira kojim putem je došao.
function _primijeniUlogeUI(data) {
  if (!data) return;
  // Ime/šumarija i identitet u meniju: ista klasa propusta kao tabovi — offline ulaz
  // na kešu ih nikad nije punio (autor vlake/izvještaja ostajao prazan).
  const imeEl = document.getElementById('p-ime');
  if (imeEl) imeEl.value = ((data.ime || '') + ' ' + (data.prezime || '')).trim();
  const sumEl = document.getElementById('p-sumarija');
  if (sumEl && data.sumarija) sumEl.value = data.sumarija;
  if (typeof _menuIdentityRender === 'function') { try { _menuIdentityRender(); } catch(e) {} }
  const vodeciBadge = document.getElementById('vodeci-badge');
  if (vodeciBadge) vodeciBadge.style.display = 'none';
  // ── Vidljivost UI po ulozi — DETERMINISTIČKI za sve uloge ──────────────────
  // SPA: odjava → prijava drugog korisnika ide BEZ reload-a stranice, pa svaki
  // element MORA biti eksplicitno postavljen u OBA smjera. Jednosmjerno sakrivanje
  // (samo if-grana bez else) preživi iz prethodne prijave → projektant poslije
  // ŠPD-terenskog naloga na istom uređaju ostane bez Projekat/Vlake/Doznaka tabova.
  const isAdm = !!data.is_admin;   // admin: nadzor i lokalni alati Terena
  const isFld = isSpdField();      // ŠPD terenski: samo navigacija/orijentacija
  const isVod = isVodeci();        // projektant + zaseban izvještaj svoje šumarije

  // Tabovi
  const adminTabBtn    = document.getElementById('admin-tab-btn');
  const postavkeTabBtn = document.getElementById('postavke-tab-btn');
  const terenBtn    = document.getElementById('teren-tab-btn');
  const projBtn = document.querySelector(`button[onclick="switchTab('projekat')"]`);
  const vlkBtn  = document.querySelector(`button[onclick="switchTab('vlake')"]`);
  const dozTab  = document.querySelector(`button[onclick="switchTab('doznaka')"]`);
  if (adminTabBtn)    adminTabBtn.style.display    = isAdm ? '' : 'none';
  if (postavkeTabBtn) postavkeTabBtn.style.display = isAdm ? '' : 'none';
  if (terenBtn)    terenBtn.style.display    = (isFld || isAdm) ? '' : 'none';
  const terenMenu=document.getElementById('menu-field-work');if(terenMenu)terenMenu.hidden=isFld||isAdm;
  // Vodeći radi svoje i dijeljene projekte kroz iste tabove kao projektant.
  if (projBtn)     projBtn.style.display     = isFld ? 'none' : '';
  if (vlkBtn)      vlkBtn.style.display      = isFld ? 'none' : '';
  if (dozTab)      dozTab.style.display      = (isAdm || isFld) ? 'none' : '';

  // Meni stavke
  const adminItem = document.getElementById('menu-admin-item');
  if (adminItem) adminItem.style.display = isAdm ? 'block' : 'none';
  const postavkeItem = document.getElementById('menu-postavke-item');
  if (postavkeItem) postavkeItem.style.display = isAdm ? 'block' : 'none';
  const apkItem = document.getElementById('menu-apk-download');
  if (apkItem) apkItem.hidden = !isAdm;
  const debugItem = document.getElementById('menu-debug-item');
  if (debugItem) debugItem.style.display = isAdm ? 'block' : 'none';
  // Izvještaji (sedmični/mjesečni po projektantu): nadzorni prikaz — admin + vodeći
  const izvItem = document.getElementById('mdrop-izvjestaji');
  if (izvItem) izvItem.style.display = isAdm ? 'block' : 'none';
  const schoolReport = document.getElementById('menu-school-report');
  if (schoolReport) {
    schoolReport.hidden = !isVod;
    const scope = schoolReport.querySelector('small');
    if (scope) scope.textContent = data.sumarija || 'Šumarija nije navedena';
  }

  // Projektantski alati (admin nadzorni nalog ih nema)
  const noviBtn = document.querySelector('#proj-list-sec .btn.b[onclick="showNovProjektForm()"]');
  if (noviBtn) noviBtn.style.display = isAdm ? 'none' : '';
  const impBtn = document.querySelector('#proj-list-sec .btn[onclick="impVlakaOpen()"]');
  if (impBtn) impBtn.style.display = isAdm ? 'none' : '';
  const routeBtn = document.getElementById('route-suggest-btn');
  if (routeBtn) routeBtn.parentElement.style.display = isAdm ? 'none' : '';
  const fotoCam = document.getElementById('loc-photo-cam');
  if (fotoCam) fotoCam.disabled = false; // lična terenska fotografija dostupna i adminu

  _updFabVisibility();
}

async function showApp() {
  // Prije gate-a: ako keširani profil kaže "nije odobren", probaj JEDAN svjež upit.
  // initAuth() ima nekoliko putanja (auto-login fallback, offline fast-path) koje
  // koriste STARI keširani profil direktno bez svježeg fetch-a — pa korisnik ostaje
  // zaglavljen na "Čeka se odobrenje" i poslije što ga je admin odobrio na serveru.
  // Ne oslanjamo se na navigator.onLine (zna lagati na terenu — vidi OS-S4 komentar
  // niže) nego pokušamo sa kratkim timeout-om; na neuspjeh/offline gate ispod radi
  // kao prije (bez regresije za stvarno neodobrene ili stvarno offline korisnike).
  // Login ekran (sa velikim logom) se sklanja ČIM se zna da gate odobrenja ne
  // može blokirati — ne tek poslije provjera ispod. Bez ovoga korisnik poslije
  // uspješne prijave još gleda logo dok traju _checkDeviceUserSwitch i (kad je
  // profil neodobren) 3s recheck; na sporijem telefonu/vezi to su sekunde i
  // izgleda kao da se "slika zaglavila" preko app-a. Uslov !_appEntered znači
  // "prva prijava u ovom učitavanju stranice" — tada u app-u još ništa nije
  // restaurirano, pa rano otkrivanje ne može pokazati podatke prethodnog
  // korisnika prije nego _checkDeviceUserSwitch odradi brisanje.
  const _gateMozeBlokirati = !!(sbProfile && sbProfile.odobren === false && !sbProfile.is_admin && !(typeof AccessPolicy!=='undefined' && AccessPolicy.canUse(sbProfile)));
  if (!_gateMozeBlokirati && !_appEntered) _revealApp();

  if (sbProfile && sbProfile.odobren === false && !sbProfile.is_admin && !(typeof AccessPolicy!=='undefined' && AccessPolicy.canUse(sbProfile)) && sbUser && sb) {
    try {
      const _tmo = new Promise((_, rej) => setTimeout(() => rej(new Error('_recheck_timeout')), 3000));
      const { data, error } = await Promise.race([
        sb.from('korisnici').select('*').eq('id', sbUser.id).single(), _tmo
      ]);
      if (!error && data && data.id === sbUser.id) { sbProfile = data; _profileSave(data); }
    } catch(e) {}
  }
  // Gate odobrenja: neodobren korisnik NE ulazi u app. FAIL-SAFE — blokira samo kad je
  // odobren EKSPLICITNO false (prije primjene migracije kolona je undefined → ne blokira,
  // niko se ne zaključa). Admin uvijek prolazi.
  if (sbProfile && sbProfile.odobren === false && !sbProfile.is_admin && !(typeof AccessPolicy!=='undefined' && AccessPolicy.canUse(sbProfile))) {
    _showAuthScreen();
    authShowPending();
    return;
  }
  // Ako se na ovom uređaju prijavio DRUGI korisnik od posljednjeg puta — obriši prethodni
  // privatni lokalni sadržaj (KML, granice, tačke...) PRIJE restore poziva ispod,
  // da ne dođe do curenja podataka između korisnika na dijeljenom uređaju.
  try { if (sbUser) await _checkDeviceUserSwitch(sbUser.id); }
  catch(e) { _showAuthScreen(); showAuthErr('Promjena naloga zaustavljena radi zaštite lokalnih podataka: ' + e.message); return; }
  try { _primijeniUlogeUI(sbProfile); } catch(e) { console.warn('uloge UI', e); }
  _revealApp();   // idempotentno — ako je gore već otkriveno, ovo ne mijenja ništa
  _setOfflineMode(!navigator.onLine);
  _startupRestore();
  if(typeof _accessTrialArm==='function')_accessTrialArm();
}

// Sve što obnavlja podatke i dira DOM pri pokretanju. Izdvojeno iz showApp() iz
// dva razloga:
//
// 1. ČEKA DA DOKUMENT BUDE ISPARSIRAN. Offline-first ulaz (v3.100.0) zove
//    showApp() ODMAH, dok se tijelo dokumenta još parsira — dio elemenata tada
//    ne postoji. Ranije je switchTab('karta') na tome bacao TypeError i sve
//    ispod (offline karte, KML, tačke, fotografije, tragovi) se NIJE izvršilo.
//    To je bio pravi uzrok prijave "ponekad ne mogu aktivirati učitane karte":
//    karte su bile uredno na uređaju, samo ih sqlmapRestoreAll() nikad nije
//    pokupio jer se do te linije nikad nije ni stiglo.
//
// 2. SVAKI KORAK JE ZASEBNO OSIGURAN. Jedan pad (nedostajući element, prazan
//    keš, izuzetak u biblioteci) više ne smije oboriti sve ostale obnove.
// Mjerenje pokretanja (izdvajanje inline JS-a, 2026-10): domInteractive = svi
// sinhroni skripti parsirani i izvršeni; dcl = + defer skripti; restore = početak
// _startupRestore (karta/projekti se crtaju). Zapis ide u konzolu (emulator ga čita
// iz logcata kao [DENDRO-START]) i u admin Debug "Terenski rad". Samo čita vrijeme.
// main = vrijeme između oznaka _tMainA/_tMainB (mikro skripte neposredno prije i
// poslije glavnog inline bloka): parse + compile + izvršavanje top-levela bloka.
function _startupMjeri() {
  try {
    const n = performance.getEntriesByType('navigation')[0];
    if (!n) return;
    const r = v => (typeof v === 'number' && v > 0) ? Math.round(v) : null;
    const m = { ver: APP_VER, di: r(n.domInteractive), dcl: r(n.domContentLoadedEventEnd), load: r(n.loadEventEnd),
      restore: r(_startupRestore._t), restoreSync: r(_startupRestore._tSync),
      main: r(window._tMainB - window._tMainA),
      // Raščlamba di: HTML stigao (rs prvi bajt, re zadnji), prvi inline skript u
      // <head>, sinhrono od <head> do glavnog bloka, glavni blok, ostatak poslije.
      rs: r(n.responseStart), re: r(n.responseEnd), head: r(window._tHead),
      doMain: r(window._tMainA - window._tHead), poslije: r(n.domInteractive - window._tMainB), ts: Date.now() };
    // Skripte do domInteractive (Resource Timing): broj, pokriveno vrijeme i najduži dohvat — u
    // APK-u svaki prolazi kroz shouldInterceptRequest (Java), pa ovo mjeri tu cijenu.
    const scr = performance.getEntriesByType('resource').filter(e => e.initiatorType === 'script' && e.startTime < n.domInteractive);
    m.scr = scr.length;
    // Unija intervala, ne zbir: dohvati idu paralelno pa bi zbir brojao isto vrijeme više puta.
    let pokr = 0, kraj = -1;
    for (const e of scr.map(e => [e.startTime, e.responseEnd || e.startTime + e.duration]).sort((x, y) => x[0] - y[0])) {
      if (e[0] > kraj) { pokr += e[1] - e[0]; kraj = e[1]; } else if (e[1] > kraj) { pokr += e[1] - kraj; kraj = e[1]; }
    }
    m.scrMs = Math.round(pokr);
    m.scrMax = Math.round(scr.reduce((a, e) => Math.max(a, e.duration), 0));
    // Prvi skript u <head>: kada je ZATRAŽEN i kada je STIGAO. Zatražen tek pri kraju
    // HTML-a = WebView čeka cijeli dokument prije parsiranja; zatražen rano a stigao
    // kasno = zahtjevi čekaju u redu iza HTML-a.
    const fd = scr.find(e => /field-design\.js/.test(e.name));
    if (fd) { m.fdStart = Math.round(fd.startTime); m.fdEnd = Math.round(fd.responseEnd); }
    window._startupTiming = m;
    try { localStorage.setItem('tvlake_startup_zadnje', JSON.stringify(m)); } catch (e) {}
    console.info('[DENDRO-START] ' + JSON.stringify(m));
  } catch (e) {}
}
window.addEventListener('load', () => setTimeout(_startupMjeri, 0), { once: true });

function _startupRestore() {
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', _startupRestore, { once: true });
    return;
  }
  if (_startupRestore._done) return;   // idempotentno (showApp može doći dvaput)
  _startupRestore._done = true;
  _startupRestore._t = performance.now();   // samo mjerenje (_startupMjeri), bez uticaja na tok
  const owner = sbUser?.id;
  const generation = (_startupRestore._generation || 0) + 1;
  _startupRestore._generation = generation;
  const alive = () => !!owner && sbUser?.id === owner && _startupRestore._generation === generation;

  const korak = (ime, fn) => { if (!alive()) return; try { Promise.resolve(fn()).catch(e => console.warn('startup:' + ime, e)); } catch(e) { console.warn('startup:' + ime, e); } };

  korak('bufferStyle', () => { if(typeof _bufRestorePrefs==='function')_bufRestorePrefs(); });
  korak('visibility', () => { if(typeof _tvVisibilityRestore==='function')_tvVisibilityRestore(); });
  korak('switchTab',   () => switchTab('karta'));
  korak('sqlmapRestore', async () => { await sqlmapRestoreAll(); if(alive() && window.MapDownloads?.available()){await MapDownloads.resume();if(alive())await MapDownloads.openFromNotification();} });
  korak('projectPolygon',()=>{if(typeof ProjectTerrain!=='undefined')ProjectTerrain.refresh();});
  korak('loadProj',    () => loadProj());        // lokalni podaci odmah (sinhrono, brzo)
  if (typeof FieldStore !== 'undefined') korak('fieldStore', async () => { await FieldStore.init(); if(alive())_updSyncBadge(); });
  korak('sbInitData',  () => Promise.resolve(sbInitData()).catch(e => console.warn('sbInitData:', e)));   // Supabase podaci u pozadini
  korak('queue', () => _processOfflineQueue());   // red sam odlučuje o vezi
  _startupRestore._tSync = performance.now();
  // Ostali restore koraci ne blokiraju početak čitanja aktivne karte.

  // Ostali nekritični restores iza prvog painta
  setTimeout(() => {
    if (!alive()) return;
    korak('geojsonOdjeli', () => geojsonOdjeliRestore());
    korak('tragReg',       () => _tragRegLoad());
    // Flush tragova koji nisu dospjeli na server (offline pri snimanju)
    if (_mrezaProbaj() && sbUser && sbProfile) {
  // v1.9.6: stavke koje više ne idu na server (tragovi, dnevnik, oznake) izbaci
  // iz reda odmah — inače bi ih brojač/panel prikazivali dok se red ne pošalje.
  korak('syncBadge', () => { _redUkloni(op => _SERVER_SAMO_LOKALNO.has(op.type)); _updSyncBadge(); });
    }
    korak('msrReg',    () => _msrRegLoad());
    korak('refRepo',   () => _refRepoLoad());
    korak('tacke',     () => _restoreTacke());
    korak('fotos',     () => _restoreFotos());
    korak('localKml',  () => _localKmlRestore());
    korak('departmentReport', () => window.DepartmentReport?.restore());
    korak('kmlcInit',  async () => { await _kmlcInit(); if(alive())await _serverKmlRestore(); });   // lista IDB ključeva za offline bedž
    korak('visibility', () => { if(typeof _tvVisibilityRestore==='function')_tvVisibilityRestore(); });
    korak('temRestore',() => _temRestore()); // tematska .gpkg karta iz IDB (async)
    // Trajna pohrana: bez persist() browser pod pritiskom diska smije obrisati
    // CIJELI Cache Storage/IDB (sve offline pločice i karte odjednom). Uz persist()
    // pregledano/preuzeto ostaje dok korisnik sam ne obriše.
    korak('persist', () => {
      if (navigator.storage && navigator.storage.persist) {
        navigator.storage.persisted().then(p => { if (!p) navigator.storage.persist(); });
      }
    });
    // Vodeći projektant: nalog služi isključivo nadzoru — odmah otvori pregled
  }, 80);
}

// --- Auth form helpers ---
function _authHidePending() {
  const p = document.getElementById('auth-pending-form');
  if (p) p.style.display = 'none';
}
function authShowPending() {
  document.getElementById('auth-login-form').style.display = 'none';
  document.getElementById('auth-reg-form').style.display = 'none';
  const err = document.getElementById('auth-err'); if (err) err.style.display = 'none';
  const p = document.getElementById('auth-pending-form');
  if (p) p.style.display = 'block';
  _authNaslov('Status pristupa');
}
// Nakon što admin odobri — korisnik klikne "Provjeri ponovo" i uđe bez ponovne prijave.
// Ne oslanja se na navigator.onLine (zna lagati — vidi OS-S4 komentar u initAuth) i
// PRIKAZUJE stvarnu grešku (umjesto tihog gutanja) — ako i poslije ovoga korisnik
// ostane na "Čeka se odobrenje", toast otkriva PRAVI uzrok (mrežna greška, RLS
// odbijanje pristupa, ili server stvarno još vraća odobren:false).
async function _authRecheck() {
  if (!sbUser) { authShowLogin(); return; }
  if (sb) {

    try {
      const _tmo = new Promise((_, rej) => setTimeout(() => rej(new Error('nema odgovora servera (5s)')), 5000));
      const { data, error } = await Promise.race([
        sb.from('korisnici').select('*').eq('id', sbUser.id).single(), _tmo
      ]);
      if (error) throw error;
      if (data && data.id === sbUser.id) { sbProfile = data; _profileSave(data); }
    } catch(e) {
      showToast('⚠ Provjera nije uspjela: ' + (e.message || e.code || 'nepoznata greška'));
    }
  }
  showApp();  // gate ponovo provjerava sbProfile.odobren
}

// Probni rok ograničava korištenje; ne briše zahtjev, sesiju ili lokalne podatke.
let _accessTrialStop=null;
function _accessTrialArm(){
  if(_accessTrialStop)_accessTrialStop();_accessTrialStop=null;
  if(typeof AccessPolicy==='undefined')return;
  _accessTrialStop=AccessPolicy.watch(()=>sbProfile,()=>{
    if(typeof SpdProfile!=='undefined')SpdProfile.close(false);
    // Pauza čuva aktivni rad i crash snapshot; korisnik nastavlja nakon odobrenja.
    try{if(recOn&&!recPaused)toggleRecPause();}catch(e){}
    try{if(_tragOn&&!_tragPaused)togTragPause();}catch(e){}
    try{if(_dozGpsOn&&!_dozGpsPaused)dozPauseGPS();}catch(e){}
    try{stopTackaNav();}catch(e){}
    _showAuthScreen();authShowPending();
  });
}
async function _registracijaIstekla(){_showAuthScreen();authShowPending();}
// Zaboravljen PIN — neautentifikovan korisnik se ne može dokazati, pa upućujemo na admina.
function _zaboravljenPin(e) {
  if (e) e.preventDefault();
  _dlgConfirm('Za reset PIN-a obratite se administratoru — recite mu svoje ime i prezime, pa će Vam postaviti novi PIN.',
    { title: '🔑 Zaboravljen PIN', okLabel: 'U redu' });
}
// Tokom MREŽNOG dijela prijave sakrij logo. Bez ovoga korisnik, poslije što je
// pritisnuo "Prijavi se", još sekundama gleda veliku sliku — između tog klika i
// otvaranja app-a idu ČETIRI uzastopna mrežna poziva (get_login_email,
// signInWithPassword, getUser, sbLoadProfile), pa tek onda showApp(). Forma i
// statusna poruka ("Povezivanje sa serverom...") ostaju vidljive — nestaje samo
// slika, tačno kako je traženo. Vraća se ako prijava ne uspije, da ekran ne
// ostane osakaćen za sljedeći pokušaj.
function _authBusy(on) {
  const box = document.querySelector('.auth-logo-box');
  if (box) box.style.display = on ? 'none' : '';
}
// Enter na polju prelazi na sljedeće polje (tastatura pokazuje "Dalje"), a tek
// poslije PIN-a "Idi" prijavljuje — korisnik ne mora tražiti polje dodirom.
function _authEnter(e, sljedece) {
  if (e.key !== 'Enter') return;
  e.preventDefault();
  const el = document.getElementById(sljedece);
  if (el) el.focus();
}
// Prikaži/sakrij PIN — na terenu se PIN često pogrešno otkuca, a tačkice ne
// pokazuju gdje je greška. Tip se vraća na password čim se polje napusti.
function _authPinPrikazi() {
  const el = document.getElementById('auth-pin'), b = document.getElementById('auth-pin-eye');
  if (!el || !b) return;
  const prikazi = el.classList.contains('pin-maska');
  el.classList.toggle('pin-maska', !prikazi);
  b.textContent = prikazi ? 'SAKRIJ' : 'PRIKAŽI';
  b.setAttribute('aria-label', prikazi ? 'Sakrij PIN' : 'Prikaži PIN');
  el.focus();
}
function authShowLogin() {
  _authBusy(false);
  document.getElementById('auth-login-form').style.display = 'block';
  document.getElementById('auth-reg-form').style.display = 'none';
  document.getElementById('auth-err').style.display = 'none';
  _authHidePending();
  _authNaslov('Prijava u sistem');
  // Popuni ime/prezime ako su zapamćeni (čist tekst, lako se primijeti i ispravi
  // ako je pogrešno). PIN se NAMJERNO ne pre-popunjava — ovaj ekran za ručnu
  // prijavu se pokazuje baš kad auto-login NIJE uspio (istekla sesija, drugi
  // uređaj/korisnik...), pa tihо popunjavanje PIN-a nekog PRETHODNOG korisnika
  // na dijeljenom telefonu znači da bi trenutni korisnik mogao pritisnuti
  // "Prijavi se" i nesvjesno se ulogovati POD TUĐIM nalogom ako ne primijeti
  // da ime/prezime nisu njegovi. Bez PIN-a je prijava uvijek eksplicitna.
  const saved = _loadSavedUser();
  if (saved) {
    document.getElementById('auth-ime').value = saved.ime || '';
    document.getElementById('auth-prezime').value = saved.prezime || '';
    document.getElementById('auth-zapamti').checked = true;
    const cbxEl = document.getElementById('auth-cbx-el');
    if (cbxEl) cbxEl.classList.add('checked');
  }
}

// Izbor profila pri registraciji (v2.9.6): kartice pune skriveni #reg-sumarija,
// koji doRegister() i dalje čita — jedan izvor vrijednosti.
function _regProfil(v) {
  const sel = document.getElementById('reg-sumarija');
  if (sel) sel.value = v || '';
}
// Uloga određuje ŠTA se šalje: terenski = fiksno 'ŠPD US ŠUME' (isSpd() poredi
// tačno), projektant = šumarija iz padajuće liste. Promjena uloge briše raniji
// izbor, pa terenac ne može ostati "upisan" u šumariju koju je dodirnuo usput.
function _regUloga(u) {
  document.querySelectorAll('#auth-reg-form .reg-prof').forEach(b => {
    const on = b.dataset.uloga === u;
    b.classList.toggle('on', on);
    b.setAttribute('aria-checked', on ? 'true' : 'false');
  });
  const wrap = document.getElementById('reg-sum-wrap');
  const izbor = document.getElementById('reg-sum-izbor');
  if (wrap) wrap.hidden = u !== 'proj';
  if (u === 'teren') { if (izbor) izbor.value = ''; _regProfil('ŠPD US ŠUME'); }
  else { _regProfil(izbor ? izbor.value : ''); }
}

function authShowReg() {
  document.getElementById('auth-login-form').style.display = 'none';
  document.getElementById('auth-reg-form').style.display = 'block';
  document.getElementById('reg-err').style.display = 'none';
  _authHidePending();
  _authNaslov('Registracija');
}

// Natpis iznad forme mora pratiti formu koja je STVARNO prikazana — ranije je
// na sva tri ekrana (prijava, registracija, čekanje odobrenja) pisalo
// "Prijava u sistem", pa je registracija izgledala kao da je korisnik zalutao.
function _authNaslov(txt) {
  const el = document.getElementById('auth-divlabel');
  if (el) el.textContent = txt;
}

function showAuthErr(msg, isReg) {
  const el = document.getElementById(isReg ? 'reg-err' : 'auth-err');
  el.textContent = msg;
  el.style.display = 'block';
}

// --- Login ---
// `var` je namjeran: funkcija doLogin je dostupna iz inline onclick-a čak i
// ako se raniji, nekritični startup korak sruši. `let` bi u tom rijetkom
// slučaju ostao u temporalnoj zoni i klik bi izgledao potpuno neaktivan.
var _authInFlight = false;
async function doLogin() {
  if (_authInFlight) return;  // spriječi dupli tap bez otključavanja prvog poziva
  try {
  _authInFlight = true;
  const ime     = document.getElementById('auth-ime').value.trim();
  const prezime = document.getElementById('auth-prezime').value.trim();
  const pin     = document.getElementById('auth-pin').value.trim();

  document.getElementById('auth-err').style.display = 'none';
  if (!ime || !pin) { showAuthErr('Popunite ime i PIN'); return; }

  // Offline login: keširani profil postoji i isti korisnik se prijavljuje —
  // pusti u app bez servera. Vraća false ako se nema na šta osloniti.
  const prijavaIzKesa = async () => {
    // Provjera ime+PIN: odvojen zapis koji PREŽIVLJAVA odjavu (_offCredProvjeri),
    // a stari `saved` zapis ostaje kao rezerva za uređaje prijavljene prije v3.1.4.
    const uid = await _offCredProvjeri(ime, prezime, pin);
    const saved = _loadSavedUser();
    const staro = !!(saved && saved.ime === ime && saved.pin === pin);
    const cached = _profileLoad(uid || undefined);
    if (!(cached && cached.id && (uid || staro))) return false;
    sbUser = { id: cached.id, email: cached.email || '', _cachedStub: true };
    sbProfile = cached;
    if (document.getElementById('auth-zapamti')?.checked !== false) localStorage.setItem(_SAVED_USER_KEY, JSON.stringify({ ime, prezime, pin }));
    _offCredSpremi(ime, prezime, pin, cached.id);
    _setOfflineMode(true);
    showApp();
    showToast('📴 Offline prijava — lokalni podaci');
    return true;
  };
  // v1.8.8: i IZMJERENO mrtva veza (navigator.onLine laže 'true') ide odmah na
  // keš — ranije je čekala rok RPC-a pa javila "Server nedostupan" korisniku
  // čiji je profil sve vrijeme bio na telefonu.
  if (!sb || !_mrezaProbaj()) {
    if (await prijavaIzKesa()) return;
    if (!sb) { showAuthErr('Nema internet konekcije — server nedostupan'); return; }
    if (navigator.onLine === false) { showAuthErr('Nema internet veze, a na ovom telefonu nema sačuvane prijave za ove podatke. Provjeri ime i PIN ili se prijavi kad budeš imao internet.'); return; }
  }

  showAuthErr('Povezivanje sa serverom...');
  _authBusy(true);   // sakrij logo — slijede 4 mrežna poziva prije showApp()
  // Ručni pokušaj prijave smije provjeriti vezu i kad je ranije izmjeren slab signal.
  if(typeof _mrezaSila==='function'&&navigator.onLine!==false){
    // Izričit pokušaj prijave sa mrežom: uzorci 'nema' sa terena (do 10 min stari)
    // opisuju PRIJE, ne sad — brišu se da vrata/značka ne drže "server nedostupan".
    try{ if(_netKvalitet()==='nema'||_netKvalitet()==='slaba')_netUzorci=[]; }catch(e){}
    _mrezaSila(60000);
  }

  // Look up internal email by name (prezime može biti prazan za org naloge)
  let email, lookupErr;
  try {
    const r = await sb.rpc('get_login_email', { p_ime: ime, p_prezime: prezime });
    email = r.data; lookupErr = r.error;
  } catch(e) {
    // Mreža pala usred prijave — isti korisnik sa keširanim profilom ulazi offline.
    if (await prijavaIzKesa()) return;
    showAuthErr(_isNetworkErr(e)?'Veza sa serverom je prekinuta. Provjeri internet i ponovi prijavu.':'Server nedostupan: '+e.message); return;
  }
  if(lookupErr){
    if(_isNetworkErr(lookupErr)){if(await prijavaIzKesa())return;showAuthErr('Veza sa serverom je prekinuta. Provjeri internet i ponovi prijavu.');}
    else showAuthErr('Server nije mogao provjeriti nalog: '+lookupErr.message);
    return;
  }
  if(!email){showAuthErr('Korisnik nije pronađen. Provjeri ime i prezime.');return;}

  const { error } = await sb.auth.signInWithPassword({ email, password: pin.padEnd(6, '0') });
  if (error) {
    // D2-K: ne prikazuj "Pogrešan PIN" za mrežnu/server grešku — samo za stvarno
    // pogrešne kredencijale (Supabase invalid_grant, status 400).
    const wrongPin = error.status === 400 || /invalid.*(login|credential|grant)/i.test(error.message || '');
    showAuthErr(wrongPin?'Pogrešan PIN: '+error.message:_isNetworkErr(error)?'Veza sa serverom je prekinuta. Provjeri internet i ponovi prijavu.':'Greška prijave: '+error.message);
    return;
  }

  // Zapamti korisnika ako je checkbox čekiran
  await _offCredSpremi(ime, prezime, pin, (await sb.auth.getUser().catch(()=>({data:{}}))).data?.user?.id);
  if (document.getElementById('auth-zapamti').checked) {
    localStorage.setItem(_SAVED_USER_KEY, JSON.stringify({ ime, prezime, pin }));
  } else {
    _clearSavedUser();
  }

  sbUser = (await sb.auth.getUser()).data.user;
  await sbLoadProfile();
  showApp();
  } catch(e) { showAuthErr('Greška: ' + e.message); }
  finally {
    _authInFlight = false;
    // Ako prijava nije uspjela (nismo ušli u app), vrati logo da ekran ostane
    // normalan za sljedeći pokušaj.
    if (!_appEntered) _authBusy(false);
  }
}

// --- Register ---
async function doRegister() {
  if (_authInFlight) return;  // D2-K: spriječi dupli tap na "Registruj se"
  _authInFlight = true;
  try {
  const ime      = document.getElementById('reg-ime').value.trim();
  const prezime  = document.getElementById('reg-prezime').value.trim();
  const sumarija = document.getElementById('reg-sumarija').value.trim();
  const pin      = document.getElementById('reg-pin').value.trim();
  const pin2     = document.getElementById('reg-pin2').value.trim();

  document.getElementById('reg-err').style.display = 'none';
  if (!sumarija) {
    const proj = document.querySelector('#auth-reg-form .reg-prof-proj.on');
    showAuthErr(proj ? 'Odaberite šumariju iz liste' : 'Odaberite ulogu: Terenski radnik ili Projektant', true); return;
  }
  if (!ime || !prezime || !pin) { showAuthErr('Popunite sva obavezna polja', true); return; }
  if (!/^\d+$/.test(pin))  { showAuthErr('PIN smije sadržavati samo cifre', true); return; }
  // 6 cifara umjesto dosadašnje 4: prijava ide preko IMENA (get_login_email je
  // namjerno dostupan i neprijavljenima jer je preduslov logina), pa je jedina
  // stvarna odbrana od pogađanja dužina PIN-a — 4 cifre je svega 10 000
  // kombinacija. Postojeći kraći PIN-ovi i dalje rade (padEnd(6,'0') se ne
  // mijenja); strože važi samo za nove registracije.
  if (pin.length < 6)      { showAuthErr('PIN mora imati najmanje 6 cifara', true); return; }
  if (pin !== pin2)        { showAuthErr('PIN-ovi se ne poklapaju', true); return; }

  // Je li ime već zauzeto? Ovo se izvršava PRIJE sb.auth.signUp(), dakle kao
  // NEPRIJAVLJEN korisnik. Ranije je to bio direktan `select` na tabelu
  // korisnici, što je zahtijevalo politiku koja svima dozvoljava čitanje —
  // a ona je otvarala CIJELI imenik (imena, login_email, is_admin, odobren)
  // bilo kome s javnim ključem. Od 20260728_pristup_dovrsetak.sql to radi uska
  // RPC koja vraća samo true/false, bez ijednog podatka.
  const { data: imeZauzeto, error: eIme } = await sb.rpc('ime_zauzeto', {
    p_ime: ime, p_prezime: prezime
  });
  // Ako RPC još ne postoji (migracija nije primijenjena), preskoči provjeru —
  // jedinstvenost svejedno brani upis u koraku ispod, uz manje jasnu poruku.
  if (!eIme && imeZauzeto) { showAuthErr(`Korisnik "${ime} ${prezime}" već postoji`, true); return; }

  // Generate unique internal email (never shown to user)
  const slug = `${ime.toLowerCase().replace(/[^a-z]/g,'')}.${prezime.toLowerCase().replace(/[^a-z]/g,'')}`;
  const loginEmail = `${slug}.${Date.now()}@tvlake.ba`;

  const { data, error } = await sb.auth.signUp({ email: loginEmail, password: pin.padEnd(6, '0') });
  if (error) { showAuthErr('Greška: ' + error.message, true); return; }

  // Boja se računa DETERMINISTIČKI iz novog korisničkog id-a. Ranije se brojalo
  // koliko korisnika već ima u šumariji — ali taj upit se izvršava prije nego
  // vlastiti red u `korisnici` postoji, pa `moja_sumarija()` još vraća NULL i
  // od 20260728_pristup_dovrsetak.sql (kad je uklonjeno svima-dozvoljeno
  // čitanje) vratio bi prazno → svi novi korisnici bi dobili istu boju.
  // _bojaZaId daje stabilnu i raspršenu boju bez ijednog dodatnog upita.
  const korisnikBoja = _bojaZaId(data.user.id);

  // sb.auth.signUp() gore je VEĆ uspio — auth.users red postoji. Ako ovaj insert
  // padne (npr. prolazni prekid veze, češći na Android WebView-u nego u pravom
  // browseru), korisnik ostaje "siroče": ima nalog za login ali admin ga nikad
  // ne vidi (admin_get_all_users čita SAMO korisnici tabelu) — pa ga ne može
  // odobriti. Par pokušaja s pauzom prije odustajanja hvata baš takve blipove.
  let insertErr = null;
  for (let attempt = 0; attempt < 3; attempt++) {
    if (attempt > 0) await new Promise(r => setTimeout(r, 700 * attempt));
    const { error: e } = await sb.from('korisnici').insert({
      id: data.user.id, ime, prezime, sumarija, login_email: loginEmail, boja: korisnikBoja
    });
    insertErr = e;
    if (!insertErr) break;
    // Server (trigger korisnici_zastita iz 20260727_pristup_odobrenje.sql) sad
    // provjerava šumariju u tabeli `sumarije`. To NIJE prolazna mrežna greška —
    // ponavljanje je besmisleno, prekini odmah s jasnom porukom.
    if (/nepoznata šumarija/i.test(insertErr.message || '')) break;
    if (insertErr.code === '23505') {
      // Provjeri je li VLASTITI red (id = data.user.id) ipak upisan — raniji
      // pokušaj je mogao uspjeti na serveru dok je odgovor izgubljen, što
      // izgleda kao 23505 na retry-u. Ako reda pod NAŠIM id-jem i dalje nema,
      // konflikt je po drugom polju (npr. imenu) — stvarna greška, ne uspjeh.
      const { data: self } = await sb.from('korisnici').select('id').eq('id', data.user.id).maybeSingle();
      if (self) { insertErr = null; break; }
    }
  }
  if (insertErr) {
    if (/nepoznata šumarija/i.test(insertErr.message || '')) {
      showAuthErr('Odabrana šumarija nije dozvoljena — izaberi jednu iz liste.', true);
    } else {
      showAuthErr('Greška pri kreiranju profila (probaj ponovo): ' + insertErr.message, true);
    }
    return;
  }

  // Zapamti korisnika kao i kod običnog logina (doLogin) — bez ovoga se registrovani
  // korisnik oslanjao SAMO na Supabase sesiju, pa se login ekran znao ponovo pojaviti
  // pri sljedećem pokretanju (nema "zapamti me" na formi registracije — uvijek pamti).
  localStorage.setItem(_SAVED_USER_KEY, JSON.stringify({ ime, prezime, pin }));

  sbUser = data.user;
  await sbLoadProfile();
  // Novi korisnik NE ulazi odmah — čeka admin odobrenje (odobren=FALSE po defaultu).
  // showApp() bi ionako gate-ovao, ali eksplicitno pokazujemo pending s porukom.
  // (Ako migracija nije primijenjena, odobren je undefined → showApp gate propušta → app.)
  if (sbProfile && sbProfile.odobren === false && !sbProfile.is_admin && !(typeof AccessPolicy!=='undefined' && AccessPolicy.canUse(sbProfile))) authShowPending();
  else showApp();
  } finally {
    _authInFlight = false;
  }
}

// --- Logout ---
// --- Self-service: promijeni vlastiti PIN (ulogovan korisnik) ---
// Ne treba RPC — sesija autorizuje sb.auth.updateUser; radi i bez migracije.
async function promijeniPin() {
  if (!sbUser) { showToast('Prvo se prijavite'); return; }
  if (!navigator.onLine) { showToast('⚠ Promjena PIN-a traži internet'); return; }
  const p1 = await _dlgPrompt('Novi PIN (4–6 cifara)', '', { title: '🔑 Promijeni PIN', inputType: 'password', inputMode: 'numeric', okLabel: 'Dalje' });
  if (p1 === null) return;
  const pin = String(p1).trim();
  if (!/^\d{4,6}$/.test(pin)) { showToast('PIN mora biti 4–6 cifara'); return; }
  const p2 = await _dlgPrompt('Ponovite novi PIN', '', { title: '🔑 Potvrdi PIN', inputType: 'password', inputMode: 'numeric', okLabel: 'Sačuvaj' });
  if (p2 === null) return;
  if (String(p2).trim() !== pin) { showToast('PIN-ovi se ne poklapaju'); return; }
  const { error } = await sb.auth.updateUser({ password: pin.padEnd(6, '0') });
  if (error) { showToast('Greška: ' + error.message); return; }
  // Ako je "zapamti me" bio uključen, ažuriraj sačuvani PIN da auto-login radi
  const saved = _loadSavedUser();
  if (saved) { saved.pin = pin; localStorage.setItem(_SAVED_USER_KEY, JSON.stringify(saved)); }
  showToast('✅ PIN promijenjen');
}

async function doLogout() {
  // OBA await-a ispod moraju biti VREMENSKI OGRANIČENA. Sve čišćenje i povratak
  // na login ekran su u try/finally niže i garantovano bi se izvršili — ali samo
  // ako izvršavanje uopšte STIGNE do njih. try/catch hvata grešku, ali ne i
  // vješanje: bez mreže su oba poziva znala visjeti zauvijek, pa je odjava tiho
  // ostajala nedovršena i korisnik bi ostao u aplikaciji bez ikakve poruke
  // ("odjava ne radi offline"). Isti Promise.race obrazac koristi i showApp().

  // v1.9.5: slanje je ručno (v1.9.4), pa je raniji tihi pokušaj slanja ovdje
  // udarao u zatvorenu kapiju i odjava je ostavljala sve neposlano BEZ riječi.
  // Sad korisnik bira. Red je vezan za korisnika (_uid) i preživljava odjavu i
  // tuđu prijavu.
  if (sbUser && sbProfile) {
    let n = { stavki: 0 };
    try { n = _serverNaCekanju(); } catch(e) {}
    // Opozvan/neodobren nalog (dugme Odjava na ekranu "Čeka se odobrenje") ne
    // može slati — server odbija — pa ga ne pitamo; podaci samo ostaju sačuvani.
    const mozeSlati = sbProfile.odobren !== false || sbProfile.is_admin || (typeof AccessPolicy!=='undefined' && AccessPolicy.canUse(sbProfile));
    if (n.stavki && mozeSlati) {
      const i = await _dlgActions('☁ Neposlano: ' + n.stavki, [
        { label: '⬆ Pošalji pa se odjavi' },
        { label: 'Odjavi se bez slanja<br><span style="font-size:11px;opacity:.7;">Ostaje na ovom telefonu i šalje se kad se opet prijaviš</span>' }
      ]);   // "Odustani" dijalog ima sam (vraća null)
      if (i == null) return;
      if (i === 0) {
        await serverPosalji();
        let ost = 0;
        try { ost = _serverNaCekanju().stavki; } catch(e) {}
        if (ost && !await _dlgConfirm('Nije sve poslano — ' + ost + ' čeka. Odjaviti se svejedno? Ostaje sačuvano na ovom telefonu.',
          { title: '☁ Server', okLabel: 'Odjavi se' })) return;
      }
    }
  }

  // signOut() šalje mrežni zahtjev na /auth/v1/logout i usput uzima navigator.locks
  // bravu nad auth tokenom — ako osvježavanje tokena već drži tu bravu čekajući
  // mrežu, signOut čeka nju, bez ugrađenog timeouta. Bez mreže tražimo SAMO
  // lokalno brisanje sesije (scope:'local' → nema mrežnog poziva); kad mreže ima,
  // ostaje podrazumijevani 'global' da se refresh token stvarno poništi i na
  // serveru (bitno na dijeljenom terenskom telefonu).
  // .catch() ide na SAM promise, ne samo oko await-a — promise koji izgubi trku
  // bi inače kasnije bacio unhandled rejection.
  // Vanjski try je i dalje potreban: ako inicijalizacija Supabase klijenta nije
  // uspjela, `sb` je null pa `sb.auth` baci SINHRONO — .catch() na promise-u tu
  // ne pomaže, a neuhvaćena greška bi preskočila cijelo čišćenje ispod.
  try {
    const pso = sb.auth.signOut(navigator.onLine ? undefined : { scope: 'local' })
                  .catch(() => {});
    await Promise.race([pso, new Promise(r => setTimeout(r, 2000))]);
  } catch(e) {}

  // Ako signOut nije stigao završiti, Supabase sesija ostaje zapisana u
  // localStorage — _clearSavedUser() briše samo tvlake_saved_user, pa bi pri
  // sljedećem pokretanju onAuthStateChange('INITIAL_SESSION') vratio korisnika
  // NAZAD u aplikaciju iako se odjavio. Zato ključ brišemo i sami.
  try {
    Object.keys(localStorage)
      .filter(k => /^sb-.*-auth-token$/.test(k))
      .forEach(k => localStorage.removeItem(k));
  } catch(e) {}

  try { stopTackaNav(); } catch(e) {}

  if(typeof _accessTrialStop!=='undefined'&&_accessTrialStop){_accessTrialStop();_accessTrialStop=null;}
  if(typeof closeVlakaStyle==='function')closeVlakaStyle();
  sbUser = null; sbProfile = null;
  _startupRestore._done = false;
  _startupRestore._generation = (_startupRestore._generation || 0) + 1;
  _appEntered = false;
  if(typeof SpdProfile!=='undefined')SpdProfile.sync();

  // Sve čišćenje ide u try/finally — GARANTOVANO se vraćamo na login ekran čak i ako
  // neki korak čišćenja (mapni sloj, realtime kanal, Doznaka state...) baci grešku.
  // Bez ovoga bi neuhvaćena greška tiho prekinula funkciju usred čišćenja (nema
  // window.addEventListener('unhandledrejection', ...) hendlera) i korisnik bi
  // ostao "zaglavljen" bez ikakve vidljive poruke — "odjava ne vraća login screen".
  try {

  // Očisti mapu i stanje
  vlake.forEach(v => {
    _removeVlakaMapLayers(v);
  });
  vlake = []; actI = null;

  textLabels.forEach(l => { if (l.marker) map.removeLayer(l.marker); });
  textLabels = [];

  Object.values(kolegeVlakeMap || {}).forEach(_removeVlakaMapLayers);
  kolegeVlake.forEach(p => map.removeLayer(p));
  kolegeLabels.forEach(m => map.removeLayer(m));
  kolegeVlake = []; kolegeLabels = []; kolegeVlakeMap = {};
  _kolegeActiveSince = {};
  _clearAllSharedLocMarkers();
  _sbRemoveRtChannels();
  clearInterval(window._liveBarTimer);
  _updSyncDot('off');
  _updKoleguLiveBar();

  // Očisti doznaka resurse
  _dozSubProject(null);
  clearTimeout(_dozTrackRefreshTimer); _dozTrackRefreshTimer = null;
  if (_dozGpsWatchId !== null) { navigator.geolocation.clearWatch(_dozGpsWatchId); _dozGpsWatchId = null; }
  _dozGpsOn = false;
  _dozOdjeli = []; _dozMembers = []; _dozMarkings = []; _dozTracks = [];
  _dozSelId = null; _dozInitDone = false;
  _demCache = {};

  Object.keys(_vlakaSaveTimers).forEach(k => clearTimeout(_vlakaSaveTimers[k]));
  _vlakaSaveTimers = {};

  // NAPOMENA: trajno localStorage/OPFS brisanje (offline karte, KML, granice, tačke,
  // tragovi/mjerenja/fotke, kolege keš...) se NE radi ovdje više — premješteno je u
  // _wipeAllLocalUserData(), koja se poziva SAMO kad showApp() otkrije da se na ovom
  // uređaju prijavio DRUGI korisnik (vidi _checkDeviceUserSwitch). In-memory nizovi se
  // I DALJE resetuju ovdje (bezopasno — restore funkcije ih ponovo pune iz localStorage
  // na sljedećoj prijavi, bilo istog bilo drugog korisnika; neke restore funkcije imaju
  // "već učitano" dedup provjeru BAŠ na ove nizove, pa bi bez reseta sloj ostao skinut s
  // mape a niz i dalje mislio da je "učitan" — vidi _localKmlRestore).
  Object.values(_tragLayers).forEach(l => { try { map.removeLayer(l); } catch(e) {} });
  Object.values(_tragHitLayers).forEach(l => { try { map.removeLayer(l); } catch(e) {} });
  _tragLayers = {}; _tragHitLayers = {}; _tragRegistry = [];

  _msrRegistry = [];

  _locFotos.forEach(f => { if (f.marker) { try { map.removeLayer(f.marker); } catch(e) {} } });
  _locFotos = [];

  kmlLs.forEach(k => { if (k.grp) try { map.removeLayer(k.grp); } catch(e) {} });
  kmlLs = [];
  if(typeof _serverPreviewClose==='function')_serverPreviewClose();
  if(typeof _projektVlakePreviewClose==='function')_projektVlakePreviewClose();
  if(window.DepartmentReport)DepartmentReport.reset();
  if(typeof DoznakaPlan!=='undefined')DoznakaPlan.reset();
  if(typeof ProjectTerrain!=='undefined')ProjectTerrain.reset();
  // Tematske .gpkg karte — in-memory reset (IDB + registar ostaju: isti korisnik ih
  // dobija nazad kroz _temRestore; drugi nalog dobija vlastiti arhivirani registar)
  try { _temRemoveAll(true); } catch(e) {}

  if (typeof _geojsonLayer !== 'undefined' && _geojsonLayer) { try { map.removeLayer(_geojsonLayer); } catch(e) {} }
  _geojsonLayer = null;
  graniceOdjeli = graniceOdjeli.filter(o => !o._fromGeojson);

  _tacke.forEach(t => { if (t.marker) try { map.removeLayer(t.marker); } catch(e) {} });
  _tacke = [];

  dnevniLog = []; kolege = [];
  // SPA nema reload-a pri promjeni korisnika — bez ovoga _projekti ostaje u memoriji
  // popunjen projektima prethodnog korisnika do prve sbLoadProjekti() osvježenja za sljedećeg.
  _projekti = [];

  } catch(e) { console.error('doLogout cleanup greška:', e); }
  finally {
    document.getElementById('wrapper').style.display = 'none';
    closeAdminModal();
    _clearSavedUser();
    _showAuthScreen();
    document.getElementById('auth-ime').value = '';
    document.getElementById('auth-prezime').value = '';
    document.getElementById('auth-pin').value = '';
    // "Ostani prijavljen" ostaje UKLJUČEN po defaultu i poslije odjave — sljedeća prijava
    // opet pamti korisnika (login se traži samo jednom, do sljedeće ručne odjave).
    document.getElementById('auth-zapamti').checked = true;
    const _cbx = document.getElementById('auth-cbx-el');
    if (_cbx) _cbx.classList.add('checked');
  }
}

// Trajno briše privatne lokalno pohranjene per-korisnik podatke (KML, granice,
// tačke, tragovi/mjerenja/fotke, kolege keš...). Poziva se SAMO iz _checkDeviceUserSwitch
// kad se otkrije da se na uređaju prijavio DRUGI korisnik — NIKAD na običnu odjavu (vidi
// napomenu u doLogout).
async function _wipeAllLocalUserData() {
  // Raster offline karte pripadaju uređaju, ne nalogu. Ne briši OPFS/IDB/native
  // katalog pri promjeni korisnika; eksplicitno brisanje karte ostaje dostupno.
  localStorage.removeItem(LOCAL_VLAKE_KEY);
  localStorage.removeItem('tvlake_local_vlake_uid');
  // _OL.PROFILE se NAMJERNO ne briše — showApp() ovo zove NAKON sbLoadProfile(), koji je već
  // upisao svjež profil TRENUTNOG (novog) korisnika; brisanje bi obrisalo baš taj zapis.
  // _OL.VLAKE/PROJEKTI/LOG/LABELS/KOLEGE/ODJELI i _OL.DOZ_* se NAMJERNO ne brišu — to su
  // write-through offline-keš zrcala servera (fetch → _OL.save na uspjeh, _OL.load SAMO u
  // catch-u kad je offline/greška), filtrirana po sbUser.id na svakom mjestu učitavanja.
  // Brisanje ne sprječava ništa (sljedeći online fetch ionako prepisuje keš prije prikaza),
  // ali kad je vraćajući korisnik OFFLINE, gasi mu vlastiti Projekat/Vlake/Doznaka prikaz dok
  // se veza ne vrati — upravo prijavljena regresija.
  localStorage.removeItem(_TRAG_REG_KEY);
  localStorage.removeItem(_MSR_REG_KEY);
  localStorage.removeItem(_FOTO_KEY);
  // Javni preuzeti GitHub slojevi pripadaju uređaju. Privatni slojevi su u arhivi naloga.
  const deviceKml=_deviceKmlEntries();
  localStorage.setItem(_LOCAL_KML_KEY,JSON.stringify(deviceKml));
  localStorage.removeItem(_GEOJSON_LS_KEY);
  localStorage.removeItem(_TACKE_KEY);
  localStorage.removeItem(_KVC_KEY);
  localStorage.removeItem('tvlake_kolege');
  // Vremenska prognoza je UKLONJENA iz aplikacije (v3.85.0), ali telefoni koji su
  // je koristili i dalje nose njene ključeve u localStorage-u. Zato se ovdje i
  // dalje brišu — doslovnim imenima, jer konstante (_WX_*) više ne postoje.
  // Ovo se može ukloniti kad prođe dovoljno vremena da su svi uređaji očišćeni.
  try {
    (JSON.parse(localStorage.getItem('tvlake_wx_places') || '[]') || [])
      .forEach(p => { try { localStorage.removeItem('tvlake_wx_cache_' + p.id); } catch(e) {} });
  } catch(e) {}
  localStorage.removeItem('tvlake_wx_places');
  localStorage.removeItem('tvlake_weather_cache');
  localStorage.removeItem(_GUIDE_ROUTES_KEY);  // sačuvane rute "Vodi me do odjela/lokacije"
  // Sadržaj .gpkg ostaje u IDB; potvrđena arhiva čuva njegov registar i stilove.
  localStorage.removeItem(_TEM_REG_KEY);
  localStorage.removeItem(_TEM_NAME_KEY);
  localStorage.removeItem(_TEM_THEME_KEY);
  // Tuđe operacije ostaju za sljedeću prijavu vlasnika. Procesor ih preskače.
  if (typeof _updSyncBadge === 'function') _updSyncBadge();

}

const _DEVICE_LAST_USER_KEY = 'tvlake_device_last_user';
// Detektuje promjenu korisnika NA OVOM UREĐAJU. Prvi login ikad (ili isti korisnik kao
// prošli put) → ne dira ništa. Drugačiji korisnik → puno brisanje PRIJE nego showApp()
// pokrene restore pozive (sprječava trku brisanje-vs-čitanje istih podataka).
async function _checkDeviceUserSwitch(uid) {
  if (!uid) return;
  const last = localStorage.getItem(_DEVICE_LAST_USER_KEY);
  if (last && last !== uid) {
    if (document.readyState === 'loading') await new Promise(resolve => document.addEventListener('DOMContentLoaded', resolve, {once:true}));
    // Arhiva se mora potvrditi PRIJE brisanja. Neuspjeh prekida promjenu naloga.
    await _archiveFieldData(last);
    const q = _OL.loadQueue(true);
    q.forEach(op => { if (!op._uid) op._uid = last; });
    localStorage.setItem(_OL.QUEUE, JSON.stringify(q));
    await _wipeAllLocalUserData();
    await _restoreFieldData(uid);
    _aktivniProjektId=localStorage.getItem('tvlake_akt_proj')||null;
    showToast('🔄 Lokalni snimci prethodnog naloga sačuvani u njegovoj arhivi');
  }
  localStorage.setItem(_DEVICE_LAST_USER_KEY, uid);
}

function _fieldArchiveKeys() {
  return [LOCAL_VLAKE_KEY, 'tvlake_local_vlake_uid', _TRAG_REG_KEY, _MSR_REG_KEY,
    _LOCAL_KML_KEY, _GEOJSON_LS_KEY, _GUIDE_ROUTES_KEY, _TEM_REG_KEY, _TEM_NAME_KEY, _TEM_THEME_KEY,
    'tvlake_akt_proj', 'tvlake_proj', 'tvlake_log', 'tvlake_kolege',
    _FOTO_KEY, _TACKE_KEY, _CRASH_VLAKA_KEY, _CRASH_TRAG_KEY, _DOZ_LIVE_KEY,
    'tvlake_native_journal', 'tvlake_native_damaged', _DOZ_TRACK_BUF_KEY,
    ...Object.values(_OL).filter(k => typeof k === 'string' && k !== _OL.PROFILE && k !== _OL.QUEUE)];
}
function _deviceKmlEntries() {
  const stored=JSON.parse(localStorage.getItem(_LOCAL_KML_KEY)||'{}');
  return Object.fromEntries(Object.entries(stored).filter(([,data])=>String(data?._driveSource?.id||'').startsWith('github-kml-')));
}
function _fieldArchiveDb() {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open('tvlake-field-archives', 1);
    req.onupgradeneeded = () => req.result.createObjectStore('owners');
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}
async function _archiveFieldData(uid) {
  const values = {};
  for (const key of _fieldArchiveKeys()) values[key] = localStorage.getItem(key);
  // Sadržaj javnih slojeva i njihov prikaz dijele se na uređaju, bez dupliranja arhiva.
  if(values[_LOCAL_KML_KEY])values[_LOCAL_KML_KEY]=JSON.stringify(Object.fromEntries(Object.entries(JSON.parse(values[_LOCAL_KML_KEY])).filter(([,data])=>!String(data?._driveSource?.id||'').startsWith('github-kml-'))));
  const db = await _fieldArchiveDb();
  try {
    await new Promise((resolve,reject) => {
      const tx = db.transaction('owners', 'readwrite');
      tx.objectStore('owners').put(values, uid);
      tx.oncomplete = resolve; tx.onabort = tx.onerror = () => reject(tx.error || new Error('Arhiva nije sačuvana'));
    });
  } finally { db.close(); }
}
async function _restoreFieldData(uid) {
  const db = await _fieldArchiveDb();
  try {
    const values = await new Promise((resolve,reject) => {
      const req = db.transaction('owners','readonly').objectStore('owners').get(uid);
      req.onsuccess = () => resolve(req.result || {}); req.onerror = () => reject(req.error);
    });
    // GPS outbox pripada svojim user_id vlasnicima; kombinuj, ne prepisuj tuđi.
    const points = JSON.parse(localStorage.getItem(_DOZ_TRACK_BUF_KEY) || '[]');
    const archivedPoints = JSON.parse(values[_DOZ_TRACK_BUF_KEY] || '[]');
    const own = points.filter(pt => pt.user_id !== uid).concat(archivedPoints.filter(pt => pt.user_id === uid));
    for (const key of _fieldArchiveKeys()) {
      if (key === _DOZ_TRACK_BUF_KEY) continue;
      if(key===_LOCAL_KML_KEY){
        const device=_deviceKmlEntries(),privateKml=JSON.parse(values[key]||'{}');
        // Ne vraćaj stare kopije javnih slojeva preko novijeg prikaza na uređaju.
        const own=Object.fromEntries(Object.entries(privateKml).filter(([,data])=>!String(data?._driveSource?.id||'').startsWith('github-kml-')));
        const merged={...device};
        for(const [name,data] of Object.entries(own)){let unique=name,n=2;while(Object.hasOwn(merged,unique))unique=name+' (lično '+(n++)+')';Object.defineProperty(merged,unique,{value:data,enumerable:true,configurable:true,writable:true});}
        localStorage.setItem(key,JSON.stringify(merged));continue;
      }
      if (values[key] != null) localStorage.setItem(key, values[key]);
      else localStorage.removeItem(key);
    }
    localStorage.setItem(_DOZ_TRACK_BUF_KEY, JSON.stringify(own));
  } finally { db.close(); }
}

async function _exportFieldRecovery() {
  const exportOwner=sbUser?.id;
  const values = {};
  for (const key of _fieldArchiveKeys()) values[key] = localStorage.getItem(key);
  values[_OL.QUEUE] = JSON.stringify(_OL.loadQueue(true).filter(op => !op._uid || op._uid === exportOwner));
  values.liveVlake = vlake.map(v => ({ nm:v.nm, pts:v.pts, projektId:v.projektId, br:v.br, kr:v.kr }));
  if (typeof FieldStore !== 'undefined') values.fieldStore = await FieldStore.exportOwner(exportOwner).catch(e=>{
    showToast('⚠ GPS baza nije pročitana — izvoz sadrži ostale dostupne podatke');return {error:e.message};
  });
  if(sbUser?.id!==exportOwner){showToast('⚠ Nalog je promijenjen — izvoz zaustavljen');return;}
  const a = document.createElement('a');
  a.href = URL.createObjectURL(new Blob([JSON.stringify({ version:1, uid:sbUser?.id, values },null,2)], {type:'application/json'}));
  a.download = 'US-SUME-oporavak-' + new Date().toISOString().slice(0,10) + '.json';
  a.click(); setTimeout(() => URL.revokeObjectURL(a.href), 5000);
}

// --- Admin (legacy stub — tab se koristi umjesto modala) ---
function showAdminModal() { switchTab('admin'); }
function closeAdminModal() {}

// ── Centralni DEBUG (samo admin) ────────────────────────────────────────────
// Jedan ID predstavlja jedan aktivni problem. Novi pokušaj osvježi istu
// karticu, a admin je briše tek kada je problem stvarno riješen.
function _adminDebugRender() {
  // Kartica stanja veze se osvježava zajedno sa listom — inače bi pokazivala
  // stanje od prošlog otvaranja panela, što je na terenu gore od ničega.
  try { _netDebugRender(); } catch(e) {}
  const el = document.getElementById('admin-debug-list');
  if (!el) return;
  if (!sbProfile?.is_admin) { el.innerHTML = ''; return; }
  const all = Object.values(_debugRead()).sort((a,b) => (b.updatedAt || 0) - (a.updatedAt || 0));
  if (!all.length) {
    el.innerHTML = '<div style="text-align:center;color:#64748b;font-size:12px;padding:24px 8px;">✅ Nema aktivnih debug zapisa.</div>';
    return;
  }
  el.innerHTML = all.map(d => {
    const id = _escHtml(String(d.id || ''));
    const dobro = d.state === 'karta prikazana' || d.state === 'uspjeh';
    const stanje = (dobro ? '✅ ' : '⚠ ') + (d.state || 'aktivno');
    return '<div style="background:#080f1e;border:1px solid #334155;border-radius:10px;padding:11px;margin-bottom:10px;">' +
      '<div style="margin-bottom:7px;"><div style="font-size:13px;font-weight:700;color:#e2e8f0;">' + _escHtml(d.title || d.id) + '</div>' +
      '<div style="font-size:10px;color:#64748b;margin-top:2px;">' + stanje + ' · ' + new Date(d.updatedAt || 0).toLocaleString() + '</div></div>' +
      '<pre style="margin:0;white-space:pre-wrap;overflow-wrap:anywhere;color:#94a3b8;font:10.5px/1.55 ui-monospace,SFMono-Regular,Consolas,monospace;max-height:360px;overflow-y:auto;">' + _escHtml(d.text || '') + '</pre>' +
      '<div style="display:flex;gap:7px;margin-top:9px;">' +
      '<button onclick="_adminDebugCopy(\'' + id + '\')" style="flex:1;padding:7px;background:#1e3a5f;border:1px solid #3b82f6;border-radius:7px;color:#93c5fd;font-size:11px;cursor:pointer;">📋 Kopiraj</button>' +
      '<button onclick="_adminDebugResolve(\'' + id + '\')" style="flex:1;padding:7px;background:#14532d;border:1px solid #22c55e;border-radius:7px;color:#bbf7d0;font-size:11px;cursor:pointer;">✓ Obriši kao riješeno</button>' +
      '</div></div>';
  }).join('');
}
// ─── DEBUG: terenski rad (bez neta / slab signal) ───────────────────────────
// Odgovara na pitanje koje se sa terena ne može drugačije postaviti: "da li app
// uopšte ima vezu, ili samo izgleda kao da ima". navigator.onLine se ISPISUJE
// uz izmjereno stanje baš da se ta razlika VIDI kad laže.
// Konzervativno: većina Android WebView-a daje ~5 MB po originu. Prag je samo
// za UPOZORENJE (stvarna granica se ne može pročitati iz JS-a), pa je bolje
// upozoriti malo ranije nego propustiti.
const _LS_LIMIT_KB = 5120;
const _NET_STANJA = {
  dobra:     { boja:'#22c55e', znak:'✅', txt:'Dobra veza' },
  slaba:     { boja:'#f59e0b', znak:'⚠',  txt:'Slab signal' },
  nema:      { boja:'#ef4444', znak:'⛔', txt:'Nema veze' },
  nepoznato: { boja:'#64748b', znak:'…',  txt:'Još nije mjereno' },
};

function _netRedHtml(oznaka, vrijednost, boja) {
  return '<div style="display:flex;justify-content:space-between;gap:10px;padding:3px 0;">' +
    '<span style="color:#64748b;">' + _escHtml(oznaka) + '</span>' +
    '<span style="color:' + (boja || '#cbd5e1') + ';font-weight:600;text-align:right;">' + _escHtml(vrijednost) + '</span></div>';
}

function _netQueueDubina() {
  try { return _OL.loadQueue().filter(op => !op._uid || op._uid === sbUser?.id).length; }
  catch(e) { return null; }
}

function _netDebugRender() {
  const el = document.getElementById('net-debug-card');
  if (!el) return;
  if (!sbProfile?.is_admin) { el.innerHTML = ''; return; }
  const k = _netKvalitet();
  const s = _NET_STANJA[k] || _NET_STANJA.nepoznato;
  const uzorci = _netSvjezi();
  const palo = uzorci.filter(u => !u.ok).length;
  const med = _netMedijanMs();
  const osKaze = (typeof navigator !== 'undefined' && navigator.onLine !== false);
  const red = _netQueueDubina();

  // Ovo je poenta cijele kartice: OS tvrdi da ima veze, a ništa ne prolazi.
  const lazOs = osKaze && k === 'nema' && uzorci.length > 0;

  let h = '<div style="font-size:13px;font-weight:700;color:' + s.boja + ';margin-bottom:8px;">' +
    s.znak + ' ' + _escHtml(s.txt) + '</div>' +
    '<div style="font:11.5px/1.6 ui-monospace,SFMono-Regular,Consolas,monospace;">';
  h += _netRedHtml('Izmjereno iz', uzorci.length ? uzorci.length + ' zadnjih poziva' : 'nema svježih poziva');
  if (uzorci.length) {
    h += _netRedHtml('Neuspjelih', palo + ' / ' + uzorci.length, palo ? '#f59e0b' : '#22c55e');
    h += _netRedHtml('Medijan odziva', med != null ? med + ' ms' : '—',
      med != null && med > _NET_SPORO_MS ? '#f59e0b' : '#cbd5e1');
  }
  h += _netRedHtml('navigator.onLine', String(osKaze), lazOs ? '#ef4444' : '#cbd5e1');
  // v1.8.8: odluke prate IZMJERENO stanje — vidljivo je da su online radnje
  // namjerno pauzirane (a ne pokvarene) i kad dolazi sljedeći pravi pokušaj.
  if (k === 'nema' && osKaze) {
    const zadnji = _netUzorci.length ? _netUzorci[_netUzorci.length - 1].t : 0;
    const zaS = Math.max(0, Math.ceil((Math.max(zadnji + _NET_PROBA_MS, _netProbaDo) - Date.now()) / 1000));
    h += _netRedHtml('Online radnje', zaS ? 'pauzirane — proba za ' + zaS + ' s' : 'pauzirane — proba na sljedećem pozivu', '#f59e0b');
  } else if (k === 'slaba') {
    h += _netRedHtml('Online radnje', 'lokalni rad — slanje i preuzimanje na ručni zahtjev', '#f59e0b');
  }
  h += _netRedHtml('Čeka u redu za sync', red == null ? '—' : String(red), red ? '#f59e0b' : '#22c55e');
  let pok = null;
  try { pok = JSON.parse(localStorage.getItem('tvlake_startup_zadnje') || 'null'); } catch (e) {}
  if (pok && pok.dcl) h += _netRedHtml('Zadnje pokretanje', pok.dcl + ' ms do DOM spreman' + (pok.restore ? ' · karta ' + pok.restore + ' ms' : ''),
    pok.dcl > 4000 ? '#f59e0b' : '#cbd5e1');
  h += _netRedHtml('Offline karata otvoreno', String((typeof _sqlLayers !== 'undefined' && _sqlLayers) ? _sqlLayers.length : 0));
  // Ovo je jedina brojka koja pokazuje koliko još terenskog rada STANE. Pregled
  // offline karata mjeri origin kvotu (GB) i o localStorage-u ne govori ništa.
  const zauzeto = _lsZauzetoKB();
  const popunjenost = zauzeto == null ? 0 : zauzeto / _LS_LIMIT_KB;
  h += _netRedHtml('Lokalno zauzeto', zauzeto == null ? '—' : zauzeto + ' KB (~' + Math.round(popunjenost * 100) + '%)',
    popunjenost > 0.8 ? '#ef4444' : popunjenost > 0.6 ? '#f59e0b' : '#22c55e');
  h += '</div>';

  if (popunjenost > 0.8) {
    h += '<div style="margin-top:9px;padding:8px;background:#450a0a;border:1px solid #ef4444;border-radius:7px;font-size:10.5px;line-height:1.5;color:#fecaca;">' +
      'Lokalna memorija je skoro puna. Kad se napuni, NOVI snimci se ne mogu sačuvati. ' +
      'Sinkronizuj (ili izvezi) pa obriši stare tragove i mjerenja.</div>';
  }

  if (lazOs) {
    h += '<div style="margin-top:9px;padding:8px;background:#450a0a;border:1px solid #ef4444;border-radius:7px;font-size:10.5px;line-height:1.5;color:#fecaca;">' +
      'Sistem tvrdi da veza POSTOJI, a nijedan zadnji poziv nije prošao. To je poznata laž ' +
      'Androida na mrtvoj vezi — app zato radi lokalno i sve upise drži u redu.</div>';
  }

  // Šta radi bez neta — da se sa terena ne nagađa šta je pokvareno, a šta
  // jednostavno TRAŽI vezu po prirodi stvari.
  h += '<div style="margin-top:10px;font-size:10.5px;line-height:1.7;color:#94a3b8;">' +
    '<div style="color:#22c55e;font-weight:700;margin-bottom:2px;">Radi i bez veze</div>' +
    'GPS snimanje (vlaka, trag, doznaka) · preuzete offline karte · keširane pločice · ' +
    'prijava sa keširanim profilom · mjerenja · novi projekat · N.V. i profil iz preuzetog ' +
    'modela terena · sve izmjene idu u red i čekaju' +
    '<div style="color:#f59e0b;font-weight:700;margin:7px 0 2px;">Traži vezu (do tada keš ili prazno)</div>' +
    'sinkronizacija sa serverom · vlake kolega · ruta putem' +
    '<div style="color:#f59e0b;font-weight:700;margin:7px 0 2px;">Traži DOBRU vezu (na slaboj čeka)</div>' +
    'slanje fotografija · preuzimanje terena (pita) · novi projekat direktno na server' +
    '</div>';
  el.innerHTML = h;
}

// Jedini zahtjev koji ova sekcija sama napravi — i to tek na izričit klik.
// Mjeri STVARAN put kojim ide sinkronizacija (Supabase kroz reliableFetch), ne
// zaseban "ping" na tuđi server koji ne dokazuje ništa o sync-u.
async function _netTestSada() {
  if (!sbProfile?.is_admin) return;
  const btn = document.getElementById('btn-net-test');
  if (btn) { btn.disabled = true; btn.textContent = '⏳ Testiram…'; }
  const t0 = Date.now();
  let ishod;
  try {
    if (!sb) throw new Error('Supabase klijent nije napravljen');
    _mrezaSila();   // pravi test — vrata transporta ga ne smiju odbiti na osnovu starih uzoraka
    const { error } = await sb.from('korisnici').select('id').limit(1);
    const ms = Date.now() - t0;
    ishod = error
      ? '❌ Server je odgovorio greškom nakon ' + ms + ' ms: ' + (error.message || error)
      : '✅ Prošlo za ' + ms + ' ms' + (ms > _NET_SPORO_MS ? ' (sporo — slab signal)' : '');
  } catch (e) {
    const ms = Date.now() - t0;
    // reliableFetch presijeca na 15 s; istek i odbijanje su različiti problemi.
    ishod = (e && e.name === 'TimeoutError')
      ? '⛔ Nema odgovora ni nakon ' + ms + ' ms — veza visi (slab ili mrtav signal)'
      : '⛔ Odbijeno nakon ' + ms + ' ms: ' + (e?.message || e);
  }
  if (btn) { btn.disabled = false; btn.textContent = '📶 Testiraj vezu sada'; }
  _debugUpsert('net-test', 'Test veze (ručni)',
    ishod + '\nIzmjereno stanje: ' + _netKvalitet() + '\nnavigator.onLine: ' + navigator.onLine +
    '\nU redu za sync: ' + _netQueueDubina(),
    ishod.startsWith('✅') ? 'uspjeh' : 'aktivno');
  _netDebugRender();
  showToast(ishod);
}

async function _adminDebugCopy(id) {
  if (!sbProfile?.is_admin) return;
  const d = _debugRead()[id];
  if (!d) return;
  try {
    if (navigator.clipboard?.writeText) await navigator.clipboard.writeText(d.text || '');
    else { const ta=document.createElement('textarea'); ta.value=d.text || ''; ta.style.cssText='position:fixed;left:-9999px'; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); ta.remove(); }
    showToast('📋 Debug kopiran');
  } catch(e) { showToast('⚠ Kopiranje nije uspjelo'); }
}
// Obriši SVE zapise odjednom. Do sada se moglo samo jedan po jedan, a poslije
// duže dijagnostike (kapa je 12 zapisa) to je bio niz od desetak potvrda.
async function _adminDebugObrisiSve() {
  if (!sbProfile?.is_admin) return;
  const n = Object.keys(_debugRead()).length;
  if (!n) { showToast('Nema zapisa za brisanje'); return; }
  if (!await _dlgConfirm('Obrisati svih ' + n + ' debug zapisa?',
      { title:'DEBUG — obriši sve', danger:true })) return;
  try { localStorage.removeItem(_ADMIN_DEBUG_KEY); } catch(e) {}
  try { _adminDebugRender(); } catch(e) {}
  showToast('✓ Debug zapisi obrisani');
}

async function _adminDebugResolve(id) {
  if (!sbProfile?.is_admin) return;
  const all = _debugRead();
  const d = all[id];
  if (!d) return;
  if (!await _dlgConfirm('Obrisati debug "' + d.title + '" kao riješen?', { title:'DEBUG riješen', danger:true })) return;
  _debugRemove(id);
  if (id === 'map-startup') {
    _mapLoadDiag = null;
    try { localStorage.removeItem(_MAP_LOAD_DIAG_KEY); } catch(e) {}
  }
  showToast('✅ Debug uklonjen');
  _adminDebugRender();
}
// Ručna provjera "koje dugme sad stvarno može primiti klik" — radi SAMO za
// dugmad koja su TRENUTNO na ekranu (Karta/Projekat tab), _KLIK_WATCH hvatač
// (gore) pokriva slučaj kad admin nije baš na tom tabu dok se problem desi.
function _adminDebugKlikNow() {
  if (!sbProfile?.is_admin) return;
  const lines = _KLIK_WATCH.map(w => {
    let btn; try { btn = document.querySelector(w.sel); } catch(e) { btn = null; }
    if (!btn) return w.label + ': nije u DOM-u';
    const r = btn.getBoundingClientRect();
    if (r.width < 1 || r.height < 1) return w.label + ': trenutno nije na ekranu — otvori Kartu/Projekat panel gdje se nalazi pa ponovi provjeru';
    const top = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
    const ok = top === btn || btn.contains(top);
    return w.label + ': ' + (ok ? '✅ klikabilno' : '❌ BLOKIRANO — na sredini dugmeta stoji ' + _klikDijagOpis(top));
  });
  _debugUpsert('klik-provjera-rucna', 'Ručna provjera klikabilnosti', lines.join('\n'), lines.some(l => l.includes('❌')) ? 'blokirano' : 'ok');
  showToast('🖱 Provjera zapisana u DEBUG');
  _adminDebugRender();
}

// Trenutno (živo) stanje "Učitavam kartu" indikatora — dopunjuje istoriju
// koraka (_mapLoadDiagText, v1.1.6/v1.1.7) sa "da li je BAŠ SADA i dalje
// prikazan i koliko dugo", jer istorija sama po sebi ne kaže je li se
// otkucaj ikad završio.
function _adminDebugMapStuckNow() {
  if (!sbProfile?.is_admin) return;
  const el = document.getElementById('map-restore-indicator');
  const showing = !!(el && el.classList.contains('show'));
  const elapsed = (_mapRestoreIndicatorShownAt != null) ? Math.round((performance.now() - _mapRestoreIndicatorShownAt) / 1000) : null;
  const sqlAktivne = (typeof _sqlLayers !== 'undefined' ? _sqlLayers : []).filter(sl => sl.visible && map.hasLayer(sl.layer)).map(sl => sl.name);
  const tileAktivni = Object.keys(TL).filter(k => map.hasLayer(TL[k]));
  const lines = [
    'Trenutno stanje indikatora: ' + (showing ? '⚠ PRIKAZAN ("Učitavam kartu…")' : '✅ skriven'),
    'Prošlo od prikazivanja: ' + (elapsed != null ? elapsed + 's' : '— (nije prikazan u ovoj sesiji)'),
    'Aktivni SQLite slojevi: ' + (sqlAktivne.length ? sqlAktivne.join(', ') : 'nijedan'),
    'Aktivni tile slojevi: ' + (tileAktivni.length ? tileAktivni.join(', ') : 'nijedan'),
    '',
    '— Istorija ovog učitavanja —',
    _mapLoadDiagText() || '(nema zabilježenog toka)',
  ];
  _debugUpsert('mapa-zaglavljena', 'Učitavam kartu — trenutno stanje', lines.join('\n'), showing ? 'zaglavljeno' : 'ok');
  showToast(showing ? '⚠ I dalje prikazan — zapisano u DEBUG' : '✅ Trenutno skriven — zapisano u DEBUG');
  _adminDebugRender();
}

// --- Admin: učitaj listu korisnika ---
let _adminUsers = null; // zadnji fetch — render/filter bez ponovnog RPC poziva

async function adminLoadUsers() {
  if (!sbProfile?.is_admin) return;
  const el = document.getElementById('admin-panel-user-list');
  if (!el) return;
  el.innerHTML = '<p style="color:#64748b;font-size:12px;text-align:center;padding:16px 0;">⏳ Učitavam...</p>';

  // Lista šumarija se puni iz JEDNOG izvora (_SUMARIJE) — ranije je bila i u
  // markupu prepisana ručno, pa bi nova šumarija radila samo na pola mjesta.
  const selSum = document.getElementById('admin-filter-sum');
  if (selSum && selSum.options.length <= 1) {
    selSum.insertAdjacentHTML('beforeend',
      _SUMARIJE.map(s => `<option value="${_escHtml(s)}">${_escHtml(s)}</option>`).join(''));
  }

  _adminLoadStats(); // paralelno, ne blokira listu

  // Otvaranje taba / "Osvježi" je IZRIČITA radnja: vrata transporta ne smiju je
  // odbiti zbog izmjerenog 'nema' (poslije ulaza na keširanom profilu stanje je
  // često zaglavljeno na offline iako mobilni podaci rade).
  _mrezaSila(30000);
  const owner=sbUser?.id,seq=(adminLoadUsers._seq||0)+1;adminLoadUsers._seq=seq;
  const [{data,error},activity]=await Promise.all([
    _withTimeout(sb.rpc('admin_get_all_users'),8000).catch(()=>({error:{message:'Server nije odgovorio. Pokušaj ponovo.'}})),
    _withTimeout(sb.rpc('admin_get_user_activity'),8000).catch(()=>({error:true}))
  ]);
  if(sbUser?.id!==owner||!sbProfile?.is_admin||adminLoadUsers._seq!==seq)return;
  if (error) {
    el.innerHTML = `<p style="color:#f87171;font-size:12px;text-align:center;padding:16px 0;">Greška: ${_escHtml(error.message)}</p>`;
    return;
  }
  const active=new Map((activity.error?[]:activity.data||[]).map(a=>[a.user_id,a.last_active_at]));
  _adminUsers = (data || []).map(u=>({...u,last_active_at:activity.error?undefined:active.get(u.id)||null}));
  // Badge: broj neodobrenih — osvježi iz svježih podataka (bez dodatnog RPC-a)
  _notifCounts.admin = _adminUsers.filter(u => u.odobren === false).length;
  _notifRender('admin');
  _adminRenderUsers();
}

// ═══ KORISNICI (admin) — status, filter, sort, sažetak ═══════════════════
//
// Sve ispod su ČISTE funkcije (bez DOM-a i bez mreže) da se mogu testirati —
// prikaz statusa i redoslijed su ono što je na terenu prijavljeno kao
// nepregledno, pa moraju biti provjerljivi, ne "izgleda dobro na mom ekranu".

// ČEKA ODOBRENJE i OPOZVAN su se do sada prikazivali IDENTIČNO ("⏳ ČEKA
// ODOBRENJE") jer oba imaju `odobren === false`. To su suprotne stvari:
// prvi je nov zahtjev koji admin treba da riješi (i koji se SAM BRIŠE za 7
// dana), drugi je nalog kojem je admin SVJESNO oduzeo pristup i ne traži
// nikakvu akciju. Razlikuju se po `istice_at` — popunjen je SAMO za naloge
// koji čekaju PRVO odobrenje (vidi 20260730_isticanje_registracije.sql).
// Kad migracija još nije primijenjena, `istice_at` je undefined za SVE, pa se
// tada ponaša kao ranije (sve neodobreno = čeka) umjesto da tvrdi "opozvan"
// za nekog ko to nije.
function _admStatus(u) {
  if (!u) return 'nepoznat';
  if (u.is_admin) return 'admin';
  if (u.odobren === false) {
    if (u.istice_at) return 'ceka';
    return (u.istice_at === undefined) ? 'ceka' : 'opozvan';
  }
  if (u.odobren === true) return 'odobren';
  return 'odobren';   // migracija sa `odobren` još nije primijenjena
}

// Dana od zadnje zabilježene aktivnosti; null = nema zapisa, undefined = podatak
// ne postoji (starija migracija) — to dvoje se NE smije spojiti, jer "nikad"
// je stvarna informacija a "ne znam" nije.
function _admDanaNeaktivan(u, sada) {
  if (!u || u.last_active_at === undefined) return undefined;
  if (!u.last_active_at) return null;
  const t = Date.parse(u.last_active_at);
  if (!isFinite(t)) return undefined;
  return Math.floor(((sada || Date.now()) - t) / 86400000);
}
const _ADM_NEAKTIVAN_DANA = 90;

// "Neaktivan" ima smisla SAMO za nekoga ko se uopšte MOŽE prijaviti. Prvi
// pokušaj je brojao i naloge koji čekaju odobrenje — a oni se po definiciji
// nisu prijavili jer im pristup još nije ni odobren; ispadalo je "2 čekaju
// odobrenje · 4 neaktivnih" gdje su ta ista dva bila brojana dvaput, i na
// kartici je uz "⏳ ČEKA ODOBRENJE" stajalo još i "nije se prijavio".
// Uhvaćeno na slici, ne u brojkama — svi testovi su prije toga prolazili.
// Opozvani se isto izuzimaju: njima je pristup svjesno oduzet, pa "neaktivan"
// ne govori ništa o njima.
function _admMozeSePrijaviti(u) {
  const st = _admStatus(u);
  return st === 'odobren' || st === 'admin';
}
function _admJeNeaktivan(u, sada) {
  if (!_admMozeSePrijaviti(u)) return false;
  const d = _admDanaNeaktivan(u, sada);
  return d === null || (typeof d === 'number' && d >= _ADM_NEAKTIVAN_DANA);
}

function _admFiltriraj(users, f) {
  const sum = (f && f.sum) || '';
  const ime = ((f && f.ime) || '').trim().toLowerCase();
  const st  = (f && f.status) || 'sve';
  const sada = (f && f.sada) || Date.now();
  return (users || []).filter(u => {
    if (sum && u.sumarija !== sum) return false;
    if (ime && !((u.ime || '') + ' ' + (u.prezime || '')).toLowerCase().includes(ime)) return false;
    if (st === 'sve') return true;
    if (st === 'neaktivni') return _admJeNeaktivan(u, sada);
    return _admStatus(u) === st;
  });
}

// "Čeka odobrenje" ide PRVO uvijek, bez obzira na izabrani sort — ima rok
// (briše se sam) i jedini je red u ovoj listi na koji admin mora reagovati.
// Unutar čekanja: najkraći rok prvi.
function _admSortiraj(users, sort, sada) {
  const arr = (users || []).slice();
  const ime = u => ((u.ime || '') + ' ' + (u.prezime || '')).trim().toLowerCase();
  const ceka = u => _admStatus(u) === 'ceka';
  arr.sort((a, b) => {
    if (ceka(a) !== ceka(b)) return ceka(a) ? -1 : 1;
    if (ceka(a) && ceka(b)) {
      const ta = Date.parse(a.istice_at || '') || Infinity;
      const tb = Date.parse(b.istice_at || '') || Infinity;
      if (ta !== tb) return ta - tb;
    }
    if (sort === 'aktivnost') {
      // Bez aktivnosti ide na DNO ovog sorta, ne na vrh kao "0" —
      // Date.parse(null) je NaN i bez ovoga bi poredak bio nasumičan.
      const ta = Date.parse(a.last_active_at || '') || 0;
      const tb = Date.parse(b.last_active_at || '') || 0;
      if (ta !== tb) return tb - ta;
    } else if (sort === 'noviji') {
      const ta = Date.parse(a.created_at || '') || 0;
      const tb = Date.parse(b.created_at || '') || 0;
      if (ta !== tb) return tb - ta;
    }
    return ime(a).localeCompare(ime(b), 'bs');
  });
  return arr;
}

function _admSazetak(users, sada) {
  const s = { ukupno: 0, ceka: 0, odobren: 0, opozvan: 0, admin: 0, neaktivni: 0, danas: 0, sedmica: 0 };
  (users || []).forEach(u => {
    s.ukupno++;
    const st = _admStatus(u);
    if (s[st] !== undefined) s[st]++;
    if (_admJeNeaktivan(u, sada)) s.neaktivni++;
    const g = _admAktivnostGrupa(u, sada);
    if (g === 'danas') { s.danas++; s.sedmica++; } else if (g === 'sedmica') s.sedmica++;
  });
  return s;
}

// Prikaz "Po aktivnosti" (zadano): admin najčešće pita "ko je radio danas /
// ove sedmice", a grupisanje po šumariji je to razbijalo na 7 lista — isti
// dan aktivnosti je bio razbacan po cijelom ekranu. Grupe su KALENDARSKE
// ("danas" = od ponoći po lokalnom vremenu), ne "zadnja 24 h", jer tako ih
// admin i izgovara.
const _ADM_AKT_GRUPE = [
  { id: 'danas',     naziv: 'Danas' },
  { id: 'sedmica',   naziv: 'Zadnjih 7 dana' },
  { id: 'mjesec',    naziv: 'Zadnjih 30 dana' },
  { id: 'ranije',    naziv: 'Ranije' },
  { id: 'nikad',     naziv: 'Bez zabilježene aktivnosti' },
  { id: 'nepoznato', naziv: 'Aktivnost nije dostupna' },
];
function _admAktivnostGrupa(u, sada) {
  if (!u || u.last_active_at === undefined) return 'nepoznato';
  if (!u.last_active_at) return 'nikad';
  const t = Date.parse(u.last_active_at);
  if (!isFinite(t)) return 'nepoznato';
  const now = sada || Date.now();
  const ponoc = new Date(now); ponoc.setHours(0, 0, 0, 0);
  if (t >= ponoc.getTime()) return 'danas';
  const dana = (ponoc.getTime() - t) / 86400000;
  if (dana < 6) return 'sedmica';     // danas + 6 prethodnih dana = 7 dana
  if (dana < 29) return 'mjesec';
  return 'ranije';
}
// Redoslijed unutar grupe: najsvježija aktivnost prva; bez aktivnosti po imenu.
function _admGrupisiPoAktivnosti(users, sada) {
  const sorted = _admSortiraj(users, 'aktivnost', sada);
  const mapa = new Map(_ADM_AKT_GRUPE.map(g => [g.id, []]));
  sorted.forEach(u => mapa.get(_admAktivnostGrupa(u, sada)).push(u));
  return _ADM_AKT_GRUPE.map(g => ({ ...g, users: mapa.get(g.id) })).filter(g => g.users.length);
}
// "prije 12 min" čita se brže od punog datuma; pun datum ostaje pored.
function _admRelativno(iso, sada) {
  const t = Date.parse(iso || '');
  if (!isFinite(t)) return '';
  const now = sada || Date.now(), min = Math.floor((now - t) / 60000);
  if (min < 1) return 'upravo';
  if (min < 60) return 'prije ' + min + ' min';
  const h = Math.floor(min / 60);
  if (h < 24) return 'prije ' + h + ' h';
  const ponoc = new Date(now); ponoc.setHours(0, 0, 0, 0);
  const dana = Math.ceil((ponoc.getTime() - t) / 86400000);
  if (dana <= 1) return 'jučer';
  return 'prije ' + dana + ' dana';
}
// Po šumarijama: grupe po nazivu (bs), uz broj aktivnih u zadnjih 7 dana.
function _admGrupisiPoSumariji(users, sada) {
  const g = new Map();
  (users || []).forEach(u => { const k = u.sumarija || '—'; if (!g.has(k)) g.set(k, []); g.get(k).push(u); });
  return [...g.entries()]
    .sort((a, b) => a[0] === '—' ? 1 : b[0] === '—' ? -1 : a[0].localeCompare(b[0], 'bs'))
    .map(([sum, us]) => ({ sum, users: us,
      aktivni: us.filter(u => ['danas', 'sedmica'].includes(_admAktivnostGrupa(u, sada))).length }));
}

// Ime korisnika ide u onclick="...('IME')" — `_escHtml` NE escape-uje
// apostrof, pa bi ime tipa O'Brien prekinulo JS string i dugme bi tiho
// prestalo raditi (bez greške u konzoli, kao i sve u atributima). Prvo
// JS-escape (\ i '), pa tek onda HTML-escape.
function _jsAttr(s) {
  return _escHtml(String(s == null ? '' : s).replace(/\\/g, '\\\\').replace(/'/g, "\\'"));
}

// localStorage u try/catch — čitanje na nivou bloka, a u privatnom prozoru /
// sa blokiranim kolačićima sam pristup BACA i oborio bi cijeli JS blok ispod.
function _admLS(k, zadano) { try { return localStorage.getItem(k) || zadano; } catch(e) { return zadano; } }
let _admStatusFilter = _admLS('tvlake_adm_status', 'sve');
let _admSort         = _admLS('tvlake_adm_sort',   'ime');
let _admPrikaz       = _admLS('tvlake_adm_prikaz', 'aktivnost');   // 'aktivnost' | 'sumarije'
const _admSumZatvorene = new Set((() => { try { return JSON.parse(localStorage.getItem('tvlake_adm_sum_zatvorene') || '[]'); } catch(e) { return []; } })());
const _admOtvorene   = new Set();   // kartice kojima su otvorene dodatne kontrole

function _admPostaviStatus(v) {
  _admStatusFilter = v;
  try { localStorage.setItem('tvlake_adm_status', v); } catch(e) {}
  _adminRenderUsers();
}
function _admPostaviPrikaz(v) {
  _admPrikaz = v === 'sumarije' ? 'sumarije' : 'aktivnost';
  try { localStorage.setItem('tvlake_adm_prikaz', _admPrikaz); } catch(e) {}
  _adminRenderUsers();
}
// Sklapanje grupe šumarije bez ponovnog crtanja (isti razlog kao kartica).
function _admSumToggle(det) {
  const k = det.dataset.sum;
  if (det.open) _admSumZatvorene.delete(k); else _admSumZatvorene.add(k);
  try { localStorage.setItem('tvlake_adm_sum_zatvorene', JSON.stringify([..._admSumZatvorene])); } catch(e) {}
}
function _admPostaviSort(v) {
  _admSort = v;
  try { localStorage.setItem('tvlake_adm_sort', v); } catch(e) {}
  _adminRenderUsers();
}
// Toggle bez ponovnog crtanja cijele liste — inače bi se skrol vratio na vrh
// baš kad admin otvori karticu na dnu.
function _admToggleKartica(uid) {
  const box = document.getElementById('adm-ctl-' + uid);
  const car = document.getElementById('adm-car-' + uid);
  if (!box) return;
  const otvoren = box.style.display !== 'none';
  box.style.display = otvoren ? 'none' : '';
  if (car) car.textContent = otvoren ? '▾' : '▴';
  if (otvoren) _admOtvorene.delete(uid); else _admOtvorene.add(uid);
}
function _admStatsToggle() {
  const b = document.getElementById('admin-stats-box');
  if (!b) return;
  const skriven = b.dataset.skriven === '1';
  b.dataset.skriven = skriven ? '0' : '1';
  b.style.display = skriven ? '' : 'none';
  try { localStorage.setItem('tvlake_adm_stats', skriven ? '1' : '0'); } catch(e) {}
  const t = document.getElementById('admin-stats-toggle');
  if (t) t.textContent = skriven ? '📊 Sakrij statistiku' : '📊 Statistika po šumariji';
}

function _admBrojRijec(n, jed, mn) { return n + ' ' + (n === 1 ? jed : mn); }

function _adminRenderUsers() {
  if (!sbProfile?.is_admin || _adminUsers === null) return;
  const el = document.getElementById('admin-panel-user-list');
  if (!el) return;

  const filterSum  = document.getElementById('admin-filter-sum')?.value || '';
  const filterName = document.getElementById('admin-filter-name')?.value || '';
  const sve = _admFiltriraj(_adminUsers, { sum: filterSum, ime: filterName });
  const rows = _admSortiraj(
    _admFiltriraj(_adminUsers, { sum: filterSum, ime: filterName, status: _admStatusFilter }),
    _admSort);

  // Sažetak se računa nad OPSEGOM (šumarija + ime), ne nad statusnim filterom —
  // inače bi brojka "3 čekaju" nestala čim korisnik izabere traku "Odobreni",
  // a to je baš podatak zbog kojeg bi se vratio nazad.
  const s = _admSazetak(sve);
  const chip = (id, txt, boja) =>
    `<button onclick="_admPostaviStatus('${id}')" style="padding:4px 9px;border-radius:999px;font-size:11px;cursor:pointer;white-space:nowrap;
      background:${_admStatusFilter===id?boja+'22':'#0f172a'};border:1px solid ${_admStatusFilter===id?boja:'#334155'};
      color:${_admStatusFilter===id?boja:'#94a3b8'};font-weight:${_admStatusFilter===id?'700':'400'};">${txt}</button>`;

  const traka = `
    <div style="font-size:12px;color:#94a3b8;margin-bottom:8px;">
      <b style="color:#e2e8f0;">${_admBrojRijec(s.ukupno,'korisnik','korisnika')}</b>${filterSum||filterName?' <span style="color:#64748b;">(od '+_adminUsers.length+')</span>':''}
      ${s.ceka ? ` · <span style="color:#fbbf24;font-weight:700;">${s.ceka} ${s.ceka===1?'čeka':'čekaju'} odobrenje</span>` : ''}
      ${s.opozvan ? ` · <span style="color:#f87171;">${s.opozvan} opozvano</span>` : ''}
      ${s.neaktivni ? ` · <span style="color:#7f8ea3;">${s.neaktivni} neaktivnih</span>` : ''}
      <br><span style="color:#4ade80;">● ${s.danas} aktivno danas</span> · <span style="color:#93c5fd;">${s.sedmica} u zadnjih 7 dana</span>
    </div>
    <div role="tablist" style="display:flex;gap:0;margin-bottom:8px;border:1px solid #334155;border-radius:8px;overflow:hidden;">
      ${[['aktivnost','🕐 Po aktivnosti'],['sumarije','🌲 Po šumarijama']].map(([id,txt]) =>
        `<button role="tab" aria-selected="${_admPrikaz===id}" onclick="_admPostaviPrikaz('${id}')" style="flex:1;padding:7px 6px;font-size:12px;cursor:pointer;border:0;
          background:${_admPrikaz===id?'#1e3a5f':'#0f172a'};color:${_admPrikaz===id?'#e2e8f0':'#94a3b8'};font-weight:${_admPrikaz===id?'700':'400'};">${txt}</button>`).join('')}
    </div>
    <div style="display:flex;gap:5px;flex-wrap:wrap;margin-bottom:6px;">
      ${chip('sve','Svi ('+s.ukupno+')','#93c5fd')}
      ${s.ceka ? chip('ceka','⏳ Čeka ('+s.ceka+')','#fbbf24') : ''}
      ${chip('odobren','✓ Odobreni ('+s.odobren+')','#4ade80')}
      ${s.opozvan ? chip('opozvan','Opozvani ('+s.opozvan+')','#f87171') : ''}
      ${s.neaktivni ? chip('neaktivni','Neaktivni ('+s.neaktivni+')','#94a3b8') : ''}
      ${s.admin ? chip('admin','★ Admini ('+s.admin+')','#fbbf24') : ''}
    </div>
    <div style="display:${_admPrikaz==='sumarije'?'flex':'none'};gap:6px;align-items:center;margin-bottom:12px;">
      <span style="font-size:11px;color:#64748b;white-space:nowrap;">Poredaj:</span>
      <select onchange="_admPostaviSort(this.value)" style="flex:1;padding:5px 8px;background:#1e293b;border:1px solid #334155;border-radius:6px;color:#cbd5e1;font-size:12px;">
        <option value="ime"${_admSort==='ime'?' selected':''}>Po imenu</option>
        <option value="aktivnost"${_admSort==='aktivnost'?' selected':''}>Zadnja aktivnost</option>
        <option value="noviji"${_admSort==='noviji'?' selected':''}>Najnovija registracija</option>
      </select>
    </div>`;

  if (!rows.length) {
    el.innerHTML = traka + '<p style="color:#64748b;font-size:12px;text-align:center;padding:16px 0;">Nema korisnika u ovom izboru</p>';
    return;
  }

  // Čekanja se izdvajaju IZ grupisanja po šumariji: imaju rok (brišu se sami)
  // i jedini su red na koji admin mora reagovati, a ranije su bila razbacana
  // po grupama pa ih je trebalo tražiti.
  const ceka   = rows.filter(u => _admStatus(u) === 'ceka');
  const ostali = rows.filter(u => _admStatus(u) !== 'ceka');


  const blokCeka = ceka.length ? `
    <div style="margin-bottom:20px;border:1px solid #d97706;border-radius:10px;padding:10px;background:rgba(217,119,6,0.07);">
      <div style="font-size:12px;color:#fbbf24;font-weight:700;margin-bottom:8px;">
        ⏳ Čeka odobrenje (${ceka.length}) <span style="color:#a16207;font-weight:400;">· probni pristup 7 dana; zahtjev ostaje</span>
      </div>
      ${ceka.map(u => _admKarticaHtml(u, true)).join('')}
    </div>` : '';

  const zaglavlje = (naslov, desno) => `<div style="font-size:11px;color:#64748b;font-weight:600;letter-spacing:0.5px;
      padding:4px 0 6px;border-bottom:1px solid #1e3a5f;margin-bottom:8px;display:flex;justify-content:space-between;gap:8px;">
      <span>${naslov}</span><span style="color:#475569;font-weight:400;">${desno}</span></div>`;

  let lista;
  if (_admPrikaz === 'sumarije') {
    const sorted = _admSortiraj(ostali, _admSort);
    lista = _admGrupisiPoSumariji(sorted).map(g => `
      <details data-sum="${_escHtml(g.sum)}" ${_admSumZatvorene.has(g.sum) ? '' : 'open'} ontoggle="_admSumToggle(this)" style="margin-bottom:14px;">
        <summary style="cursor:pointer;list-style:none;font-size:12px;color:#cbd5e1;font-weight:700;padding:6px 0;border-bottom:1px solid #1e3a5f;margin-bottom:8px;display:flex;justify-content:space-between;gap:8px;">
          <span>🌲 ${_escHtml(g.sum)} <span style="color:#64748b;font-weight:400;">(${g.users.length})</span></span>
          <span style="color:${g.aktivni?'#4ade80':'#475569'};font-weight:400;font-size:11px;">${g.aktivni} aktivno u 7 dana</span>
        </summary>
        ${g.users.map(u => _admKarticaHtml(u, false)).join('')}
      </details>`).join('');
  } else {
    lista = _admGrupisiPoAktivnosti(ostali).map(g => `
      <div style="margin-bottom:18px;">
        ${zaglavlje(g.naziv, _admBrojRijec(g.users.length, 'korisnik', 'korisnika'))}
        ${g.users.map(u => _admKarticaHtml(u, true)).join('')}
      </div>`).join('');
  }
  el.innerHTML = traka + blokCeka + lista;
}

// Kartica jednog korisnika. Do v3.121.0 su SVE kontrole (Odobri/Opozovi,
// Reset PIN, šumarija+Prebaci, Briši, Vodeći projektant) stajale otvorene na
// svakoj kartici — šest kontrola × broj korisnika je zid dugmadi kroz koji se
// ime jedva nazire, a sve osim odobravanja se koristi jednom u par mjeseci.
// Sad je vidljivo ono zbog čega admin otvara listu (ko je, u kakvom je
// stanju, kad je zadnji put bio), a ostalo je iza prekidača po kartici.
function _admKarticaHtml(u, saSumarijom) {
  const nm     = (_escHtml(u.ime || '') + ' ' + _escHtml(u.prezime || '')).trim();
  const nmJs   = _jsAttr(((u.ime || '') + ' ' + (u.prezime || '')).trim());
  const uid    = u.id;
  const st     = _admStatus(u);
  const dana   = _admDanaNeaktivan(u);
  const otvoren = _admOtvorene.has(uid);
  const okvir  = st === 'ceka' ? '#d97706' : st === 'opozvan' ? '#7f1d1d' : '#334155';

  const rok = u.istice_at ? Math.ceil((new Date(u.istice_at) - Date.now()) / 86400000) : null;
  const rokChip = (st === 'ceka' && rok !== null)
    ? ` <span style="color:#f87171;font-size:10px;">${rok <= 0 ? '· probni pristup istekao — čeka admina' : '· probni pristup još ' + rok + ' dan' + (rok === 1 ? '' : 'a')}</span>`
    : '';
  const statusChip =
      st === 'admin'   ? ' <span style="color:#fbbf24;font-size:10px;">★ ADMIN</span>'
    : st === 'ceka'    ? ' <span style="color:#fbbf24;font-size:10px;background:rgba(217,119,6,0.18);padding:1px 6px;border-radius:4px;">⏳ ČEKA ODOBRENJE</span>' + rokChip
    // Opozvan se do sada prikazivao ISTO kao "čeka odobrenje" iako je
    // suprotno — admin mu je svjesno oduzeo pristup i ne treba ništa raditi.
    : st === 'opozvan' ? ' <span style="color:#f87171;font-size:10px;background:rgba(220,38,38,0.15);padding:1px 6px;border-radius:4px;">⛔ PRISTUP OPOZVAN</span>'
    : ' <span style="color:#4ade80;font-size:10px;">✓ odobren</span>';

  // Neaktivnost je do sada bila samo datum u nizu teksta — na 40 korisnika se
  // iz toga ne vidi ko godinu dana nije otvorio app.
  const neakt = !_admMozeSePrijaviti(u) ? ''
    : (dana === null)
    ? ' <span style="color:#7f8ea3;font-size:10px;background:rgba(100,116,139,0.18);padding:1px 6px;border-radius:4px;">nema zabilježene aktivnosti</span>'
    : (typeof dana === 'number' && dana >= _ADM_NEAKTIVAN_DANA)
    ? ` <span style="color:#94a3b8;font-size:10px;background:rgba(100,116,139,0.18);padding:1px 6px;border-radius:4px;">${dana} dana neaktivan</span>`
    : '';

  const approveBtn =
      st === 'ceka'
    ? `<button onclick="adminSetApproved('${uid}',true,'${nmJs}')"
         style="flex:1;padding:8px;background:#14532d;border:1px solid #16a34a;border-radius:6px;color:#4ade80;font-size:12px;font-weight:600;cursor:pointer;white-space:nowrap;"><svg class="ic"><use href="#ic-potvrdi"/></svg> Odobri</button>`
    : st === 'opozvan'
    ? `<button onclick="adminSetApproved('${uid}',true,'${nmJs}')"
         style="flex:1;padding:8px;background:#14532d;border:1px solid #16a34a;border-radius:6px;color:#4ade80;font-size:12px;font-weight:600;cursor:pointer;white-space:nowrap;"><svg class="ic"><use href="#ic-potvrdi"/></svg> Vrati pristup</button>`
    : st === 'odobren'
    ? `<button onclick="adminSetApproved('${uid}',false,'${nmJs}')"
         style="flex:1;padding:8px;background:#3a1e1e;border:1px solid #7f5539;border-radius:6px;color:#fbbf24;font-size:12px;cursor:pointer;white-space:nowrap;"><svg class="ic"><use href="#ic-opozovi"/></svg> Opozovi</button>`
    : '';

  const sumOpts = _SUMARIJE.map(s =>
    `<option value="${_escHtml(s)}"${s === u.sumarija ? ' selected' : ''}>${_escHtml(s)}</option>`).join('');

  return `
    <div style="background:#1e293b;border:1px solid ${okvir};border-radius:8px;padding:10px 12px;margin-bottom:8px;">
      <div style="font-size:13px;font-weight:600;color:#e2e8f0;margin-bottom:2px;">
        ${nm || '<span style="color:#64748b;">(bez imena)</span>'}${statusChip}${neakt}
      </div>
      ${saSumarijom ? `<div style="font-size:11px;color:#4ade80;margin-bottom:2px;">🌲 ${_escHtml(u.sumarija || '—')}</div>` : ''}
      <div style="font-size:11px;color:#64748b;margin-bottom:${u.is_admin ? '0' : '8px'};">
        ${u.created_at ? fmtDateShort(u.created_at) : '—'}
        ${u.login_email ? ' · ' + _escHtml(u.login_email) : ''}
        <br>🕐 Zadnja aktivnost: ${u.last_active_at ? '<b style="color:#cbd5e1;">' + _escHtml(_admRelativno(u.last_active_at)) + '</b> · ' + _escHtml(_fmtDateTime(u.last_active_at)) : (u.last_active_at === null ? 'još nije zabilježena' : 'podatak nije dostupan')}
      </div>
      ${!u.is_admin ? `
      <div style="display:flex;gap:6px;align-items:center;">
        ${approveBtn}
        <button onclick="_admToggleKartica('${uid}')" title="Reset PIN, prebacivanje, brisanje, vodeći projektant"
          style="${approveBtn ? '' : 'flex:1;'}padding:8px 11px;background:#0f172a;border:1px solid #475569;border-radius:6px;color:#94a3b8;font-size:12px;cursor:pointer;white-space:nowrap;">
          <svg class="ic"><use href="#ic-alat"/></svg> Upravljaj <span id="adm-car-${uid}">${otvoren ? '▴' : '▾'}</span>
        </button>
      </div>
      <div id="adm-ctl-${uid}" style="display:${otvoren ? '' : 'none'};margin-top:8px;padding-top:8px;border-top:1px solid #334155;">
        <div style="display:flex;gap:6px;align-items:center;margin-bottom:6px;">
          <select id="admin-sum-sel-${uid}"
            style="flex:1;min-width:0;padding:6px 8px;background:#0f172a;border:1px solid #334155;border-radius:6px;color:#e2e8f0;font-size:12px;">
            ${sumOpts}
          </select>
          <button onclick="adminTransferUser('${uid}','${nmJs}')"
            style="padding:6px 11px;background:#1e3a5f;border:1px solid #3b82f6;border-radius:6px;color:#60a5fa;font-size:12px;cursor:pointer;white-space:nowrap;">
            <svg class="ic"><use href="#ic-prebaci"/></svg> Prebaci
          </button>
        </div>
        <label style="display:flex;align-items:center;gap:7px;font-size:11px;color:#94a3b8;cursor:pointer;margin-bottom:8px;">
          <input type="checkbox" ${u.je_vodeci ? 'checked' : ''}
            onchange="adminSetVodeci('${uid}',this.checked,'${nmJs}')"
            style="width:15px;height:15px;accent-color:#a78bfa;cursor:pointer;">
          👁 Vodeći projektant — nadzorni pregled cijele šumarije
        </label>
        <div style="display:flex;gap:6px;align-items:center;">
          <button onclick="adminResetPin('${uid}','${nmJs}')"
            style="flex:1;padding:7px 11px;background:#1e3a5f;border:1px solid #475569;border-radius:6px;color:#cbd5e1;font-size:12px;cursor:pointer;white-space:nowrap;"><svg class="ic"><use href="#ic-kljuc"/></svg> Reset PIN</button>
          <button onclick="adminDeleteUser('${uid}','${nmJs}')"
            style="padding:7px 11px;background:rgba(220,38,38,0.12);border:1px solid #dc2626;border-radius:6px;color:#f87171;font-size:12px;cursor:pointer;white-space:nowrap;">
            <svg class="ic"><use href="#ic-obrisi"/></svg> Obriši
          </button>
        </div>
      </div>` : ''}
    </div>`;
}

// --- Admin: prebaci korisnika u drugu šumariju ---
async function adminTransferUser(userId, name) {
  if (!sbProfile?.is_admin) return;
  const sel = document.getElementById('admin-sum-sel-' + userId);
  if (!sel) return;
  const newSum = sel.value;
  if (!newSum) { showToast('Odaberi šumariju'); return; }
  if (!await _dlgConfirm(`Prebaciti "${name}" u šumariju "${newSum}"?`)) return;
  const { error } = await sb.rpc('admin_set_sumarija', { p_user_id: userId, p_sumarija: newSum });
  if (error) { showToast('Greška: ' + error.message); return; }
  showToast(`✅ ${name} → ${newSum}`);
  adminLoadUsers();
}

// --- Admin: obriši korisnika ---
async function adminDeleteUser(userId, name) {
  if (!sbProfile?.is_admin) return;
  if (!await _dlgConfirm(`Trajno obrisati korisnika "${name}"?\nOva radnja se ne može poništiti.`, { danger: true })) return;
  const { error } = await sb.rpc('admin_delete_user', { target_id: userId });
  if (error) {
    // Stara (ručno kreirana) verzija funkcije ne zna za tabele koje upućuju na
    // korisnika (loc_fotos...) — rješenje je migracija, ne ponovni pokušaj.
    const fk = /foreign key|23503/i.test((error.message || '') + ' ' + (error.code || ''));
    showToast('Greška pri brisanju: ' + error.message + (fk ? ' — ako migracija 20261013_admin_delete_user_fk.sql još nije pokrenuta u Supabase SQL Editoru, pokreni je' : ''));
    return;
  }
  showToast(`Korisnik "${name}" obrisan`);
  adminLoadUsers();
}

// --- Admin: odobri / opozovi pristup ---
async function adminSetApproved(userId, approved, name) {
  if (!sbProfile?.is_admin) return;
  if (!approved && !await _dlgConfirm(`Opozvati pristup korisniku "${name}"? Neće moći koristiti aplikaciju dok ga ponovo ne odobriš.`, { danger: true })) return;
  const { error } = await sb.rpc('admin_set_approved', { p_user_id: userId, p_odobren: approved });
  if (error) {
    const missing = /function .*does not exist|schema cache|PGRST202/i.test(error.message || '') || error.code === 'PGRST202';
    showToast(missing ? '⚠ Primijeni migraciju 20260701 na Supabase (funkcija ne postoji)' : 'Greška: ' + error.message);
    return;
  }
  showToast(approved ? `✅ "${name}" odobren` : `⊘ Pristup opozvan: "${name}"`);
  adminLoadUsers();
}

// --- Admin: postavi/ukini ulogu vodećeg projektanta ---
// Ranije se uloga izvodila iz REGEXA nad imenom ("Vodeći Projektant"), i to su
// poštovale i serverske SECURITY DEFINER funkcije — dovoljno je bilo
// registrovati se pod tim imenom da se dobije pregled cijele šumarije. Od
// 20260727_pristup_odobrenje.sql to je prava kolona koju postavlja samo admin.
async function adminSetVodeci(userId, vodeci, name) {
  if (!sbProfile?.is_admin) return;
  const { error } = await sb.rpc('admin_set_vodeci', { p_user_id: userId, p_vodeci: vodeci });
  if (error) {
    const missing = /function .*does not exist|schema cache|PGRST202/i.test(error.message || '') || error.code === 'PGRST202';
    showToast(missing ? '⚠ Primijeni migraciju 20260727 na Supabase (funkcija ne postoji)' : 'Greška: ' + error.message);
    adminLoadUsers();   // vrati kvačicu na stvarno stanje
    return;
  }
  showToast(vodeci ? `👁 "${name}" je sad vodeći projektant` : `"${name}" više nije vodeći`);
  adminLoadUsers();
}

// --- Admin: reset PIN-a (zaboravljen PIN) ---
async function adminResetPin(userId, name) {
  if (!sbProfile?.is_admin) return;
  const pin = await _dlgPrompt(`Novi PIN za "${name}" (4–6 cifara). Saopšti ga korisniku.`, '', { title: '🔑 Reset PIN', inputType: 'text', inputMode: 'numeric', okLabel: 'Postavi' });
  if (pin === null) return;
  const p = String(pin).trim();
  if (!/^\d{4,6}$/.test(p)) { showToast('PIN mora biti 4–6 cifara'); return; }
  const { error } = await sb.rpc('admin_reset_pin', { p_user_id: userId, p_pin: p });
  if (error) {
    const missing = /function .*does not exist|schema cache|PGRST202/i.test(error.message || '') || error.code === 'PGRST202';
    showToast(missing ? '⚠ Primijeni migraciju 20260701 na Supabase (funkcija ne postoji)' : 'Greška: ' + error.message);
    return;
  }
  await _dlgConfirm(`Novi PIN za "${name}" je: ${p}\n\nSaopšti ga korisniku — prijaviće se ovim PIN-om.`, { title: '✅ PIN resetovan', okLabel: 'U redu' });
}

// ═══ POSTAVKE — email adrese za obavještenja o novoj registraciji ═══════════
// Tabelu admin_notify_emails (RLS: samo admin) čita SQL trigger pri svakoj
// novoj registraciji i šalje mail direktno preko Resend API-ja — vidi
// supabase/migrations/20260729_obavjestenja.sql. Telegram ide istim putem.
// (Ranije je to radila Edge Funkcija notify-new-registration, koja je ukinuta.)
async function postavkeLoadEmails() {
  if (!sbProfile?.is_admin) return;
  const el = document.getElementById('postavke-email-list');
  if (!el) return;
  el.innerHTML = '<p style="color:#64748b;font-size:12px;text-align:center;padding:8px 0;">⏳ Učitavam...</p>';
  const { data, error } = await sb.from('admin_notify_emails').select('id,email').order('created_at');
  if (error) {
    const missing = /relation .* does not exist|schema cache|PGRST20[0-9]/i.test(error.message || '');
    el.innerHTML = `<p style="color:#f87171;font-size:12px;text-align:center;padding:8px 0;">${
      missing ? '⚠ Primijeni migraciju 20260704 na Supabase' : 'Greška: ' + _escHtml(error.message)
    }</p>`;
    return;
  }
  if (!data?.length) {
    el.innerHTML = '<p style="color:#64748b;font-size:12px;text-align:center;padding:8px 0;">Nema dodanih adresa — niko ne prima obavještenja.</p>';
    return;
  }
  el.innerHTML = data.map(r => `
    <div style="display:flex;justify-content:space-between;align-items:center;gap:8px;background:#0f172a;border:1px solid #1e293b;border-radius:8px;padding:8px 10px;">
      <span style="font-size:13px;color:#e2e8f0;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">📧 ${_escHtml(r.email)}</span>
      <button onclick="postavkeDeleteEmail('${r.id}','${_escHtml(r.email).replace(/'/g, "\\'")}')"
        style="padding:5px 9px;background:rgba(220,38,38,0.10);border:1px solid #7f1d1d;border-radius:6px;color:#f87171;font-size:12px;cursor:pointer;flex-shrink:0;"><svg class="ic"><use href="#ic-zatvori"/></svg></button>
    </div>`).join('');
}

async function postavkeAddEmail() {
  if (!sbProfile?.is_admin) return;
  const input = document.getElementById('postavke-email-input');
  const email = (input?.value || '').trim().toLowerCase();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { showToast('⚠ Unesi ispravnu email adresu'); return; }
  const { error } = await sb.from('admin_notify_emails').insert({ email, added_by: sbUser.id });
  if (error) {
    const dup = error.code === '23505' || /duplicate/i.test(error.message || '');
    showToast(dup ? '⚠ Ta adresa je već dodana' : 'Greška: ' + error.message);
    return;
  }
  if (input) input.value = '';
  showToast('✅ Adresa dodana');
  postavkeLoadEmails();
}

async function postavkeDeleteEmail(id, email) {
  if (!await _dlgConfirm(`Ukloniti "${email}" sa liste obavještenja?`, { danger: true })) return;
  const { error } = await sb.from('admin_notify_emails').delete().eq('id', id);
  if (error) { showToast('Greška: ' + error.message); return; }
  showToast('🗑 Adresa uklonjena');
  postavkeLoadEmails();
}

// Probno obavještenje — bez ovoga se podešavanje (Telegram token, chat id,
// Resend ključ) moglo provjeriti samo pravljenjem lažne registracije.
async function postavkeTestNotif() {
  if (!sbProfile?.is_admin) return;
  if (!navigator.onLine) { showToast('⚠ Probno obavještenje traži internet'); return; }
  showToast('📨 Šaljem probno obavještenje...');
  const { data, error } = await sb.rpc('admin_test_notifikacija');
  if (error) {
    const missing = /function .*does not exist|schema cache|PGRST202/i.test(error.message || '') || error.code === 'PGRST202';
    showToast(missing ? '⚠ Primijeni migraciju 20260729 na Supabase' : 'Greška: ' + error.message);
    return;
  }
  await _dlgConfirm(
    (data || 'Poslano.') + '\n\nAko ništa ne stigne, provjeri postavke obavještenja na serveru.',
    { title: '📨 Probno obavještenje', okLabel: 'U redu' }
  );
}

// --- Admin: statistika po šumariji (korisnici · vlake · km) ---
// Statistika je zbirni pregled, ne svakodnevni alat — podrazumijevano je
// sklopljena da ne gura listu korisnika ispod pregiba; izbor se pamti.
function _admStatsPrimijeniStanje() {
  const box = document.getElementById('admin-stats-box');
  const btn = document.getElementById('admin-stats-toggle');
  if (!box) return;
  const otvorena = _admLS('tvlake_adm_stats', '0') === '1';
  box.dataset.skriven = otvorena ? '0' : '1';
  box.style.display = otvorena ? '' : 'none';
  if (btn) {
    btn.style.display = '';
    btn.textContent = otvorena ? '📊 Sakrij statistiku' : '📊 Statistika po šumariji';
  }
}

async function _adminLoadStats() {
  if (!sbProfile?.is_admin) return;
  const box = document.getElementById('admin-stats-box');
  if (!box) return;
  const { data, error } = await sb.rpc('admin_stats');
  if (error) {
    const missing = /function .*does not exist|schema cache|PGRST202/i.test(error.message || '') || error.code === 'PGRST202';
    box.style.display = missing ? '' : 'none';
    box.innerHTML = missing
      ? '<div style="font-size:11px;color:#64748b;">📊 Statistika: primijeni migraciju 20260702 na Supabase</div>'
      : '';
    return;
  }
  const rows = (data || []).filter(r => r.sumarija);
  if (!rows.length) { box.style.display = 'none'; return; }
  _admStatsPrimijeniStanje();
  const v2 = rows[0].maticnih !== undefined; // detaljna migracija 20260703 primijenjena
  const km = m => (Number(m || 0) / 1000).toFixed(1) + ' km';
  if (!v2) {
    // v1 format (migracija 20260702)
    box.innerHTML = `
      <div style="font-size:11px;color:#64748b;font-weight:600;letter-spacing:0.5px;margin-bottom:6px;">📊 STATISTIKA PO ŠUMARIJI</div>
      ${rows.map(r => `
        <div style="display:flex;justify-content:space-between;gap:8px;font-size:12px;padding:3px 0;border-bottom:1px solid rgba(51,65,85,0.4);">
          <span style="color:#e2e8f0;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${_escHtml(r.sumarija)}</span>
          <span style="color:#94a3b8;white-space:nowrap;">👤 ${r.korisnika} · 📐 ${r.vlaka} · ${km(r.ukupno_m)}</span>
        </div>`).join('')}`;
    return;
  }
  // v2 — detaljno: aktivni/7d, projekti, matične+krakovi, zadnja aktivnost + zbir
  const tot = rows.reduce((t, r) => ({
    kor: t.kor + Number(r.korisnika || 0),  a7: t.a7 + Number(r.aktivnih_7d || 0),
    pr:  t.pr  + Number(r.projekata || 0),  ma: t.ma + Number(r.maticnih || 0),
    kr:  t.kr  + Number(r.krakova || 0),    m:  t.m  + Number(r.ukupno_m || 0)
  }), { kor: 0, a7: 0, pr: 0, ma: 0, kr: 0, m: 0 });
  box.innerHTML = `
    <div style="font-size:11px;color:#64748b;font-weight:600;letter-spacing:0.5px;margin-bottom:6px;">📊 STATISTIKA PO ŠUMARIJI</div>
    ${rows.map(r => `
      <div style="padding:5px 0;border-bottom:1px solid rgba(51,65,85,0.4);">
        <div style="display:flex;justify-content:space-between;gap:8px;font-size:12px;">
          <span style="color:#e2e8f0;font-weight:600;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${_escHtml(r.sumarija)}</span>
          <span style="color:#94a3b8;white-space:nowrap;">👤 ${r.korisnika} <span style="color:#4ade80;">(${r.aktivnih_7d}/7d)</span> · 📁 ${r.projekata}</span>
        </div>
        <div style="font-size:11px;color:#64748b;margin-top:1px;">
          📐 ${r.maticnih} vlaka + ${r.krakova} krak. · ${km(r.ukupno_m)} · 🕐 ${r.zadnja_aktivnost ? _fmtDateTime(r.zadnja_aktivnost) : '—'}
        </div>
      </div>`).join('')}
    <div style="display:flex;justify-content:space-between;gap:8px;font-size:12px;padding:6px 0 1px;">
      <span style="color:#fbbf24;font-weight:700;">UKUPNO</span>
      <span style="color:#e2e8f0;white-space:nowrap;">👤 ${tot.kor} (${tot.a7}/7d) · 📁 ${tot.pr} · 📐 ${tot.ma}+${tot.kr} · ${km(tot.m)}</span>
    </div>`;
}

// --- Admin: provjera registracija na čekanju (poslije prijave) ---
let _lastPendingCheck = 0;
// tiho=true → osvježi samo brojčanik, bez toasta (periodična provjera)
async function _adminCheckPending(tiho) {
  if (!sbProfile?.is_admin) return;
  try {
    const { data, error } = await sb.rpc('admin_get_all_users');
    if (error || !data) return;
    const n = data.filter(u => u.odobren === false).length;
    const bilo = _notifCounts.admin || 0;
    _notifCounts.admin = n;
    _notifRender('admin');
    // Pri periodičnoj provjeri javi SAMO ako je stigao neko nov — inače bi se
    // isti toast ponavljao svaki put kad se app vrati u prvi plan.
    if (n > 0 && (!tiho || n > bilo)) {
      showToast(`⏳ ${n} korisnik${n === 1 ? '' : 'a'} čeka odobrenje — tab Korisnici`);
    }
  } catch(e) {}
}

// Admin koji app drži otvorenim danima inače ne bi vidio nove registracije bez
// restarta — _adminCheckPending() se zvao samo iz sbInitData() pri pokretanju.
function _adminSchedPendingCheck() {
  if (!sbProfile?.is_admin || !_mrezaProbaj()) return;
  const now = Date.now();
  if (now - _lastPendingCheck < 60000) return;
  _lastPendingCheck = now;
  _adminCheckPending(true).catch(() => {});
}

