// D2-7 pristup (isti kao offline SQLite/MBTiles slojevi): createTile vraća <img>
// (objectURL bloba) umjesto async-crtanog <canvas>-a. Android WebView async-nacrtan
// canvas NE re-komponuje pouzdano (D1-20/29/30) i canvas nema .complete pa je Leaflet
// upravljanje pločicama bilo pogrešno — otud "nestale/mutne pločice na zoom in/out"
// uprkos svim zakrpama (placeholder, parent-cascade, _real+heal...). <img> se
// komponuje nativno, a kasno postavljanje img.src se UVIJEK prikaže (za razliku od
// canvas precrtavanja) pa je i naknadni retry praznih pločica pouzdan.
// Keš ostaje page-side Cache Storage — u APK-u service worker NE radi
// (WebViewAssetLoader bez ServiceWorkerControllerCompat) pa je ovo jedini offline put.
// _abortLoading: NE zovemo TileLayer default (img bez src ima .complete=true pa bi
// default zadržavao/uklanjao pogrešno) — kao offline GridLayer slojevi, pločice ostaju
// do prune-a, samo im prekidamo mrežne zahtjeve; oporavak radi _retryEmpty.
// baseClass (v3.103.0): opciono — L.TileLayer.WMS umjesto običnog L.TileLayer,
// za slojeve koji dolaze kao WMS (bbox GetMap zahtjev po pločici, ne prost
// {z}/{x}/{y} XYZ predložak — npr. NASA FIRMS požari, ESA WorldCover). WMS
// klasa samo drugačije gradi URL (getTileUrl), ostatak (keš/timeout/retry/
// parent-fallback ispod) je identičan i radi nepromijenjeno za oba slučaja.
function makeCachedTileLayer(cacheName, baseClass) {
  cacheName = cacheName || TILE_CACHE_NAME;
  return (baseClass || L.TileLayer).extend({
    createTile(coords, done) {
      const img = document.createElement('img');
      img.alt = '';
      const url = this.getTileUrl(coords);
      img._ctls = new Set();   // AbortController-i u letu — prekidaju se na tileunload

      // v3.111.7: PRAZAN URL (sloj napravljen bez predloška, npr. Wayback prije
      // nego korisnik izabere datum) — `fetch('')` bi dohvatio SAMU STRANICU
      // (HTML, 200 OK!), pa bi se HTML pokušao prikazati kao slika i svaka
      // pločica bi bila SLOMLJENA SLIKA. Ne dirati mrežu dok URL ne postoji.
      if (!url) { img._empty = true; done(null, img); return img; }

      // v3.111.7: server koji vrati 200 OK ali NIJE slika (klasičan WMS
      // ServiceException u XML-u kad je ime sloja/endpoint pogrešan, ili HTML
      // stranica greške) je do sada prolazio kao ispravan odgovor: pravio se
      // blob, upisivao u keš i dodjeljivao img.src — browser to ne može
      // dekodirati pa nacrta IKONU SLOMLJENE SLIKE, a njene ivice se preko
      // cijele karte vide kao siva MREŽA (tačno prijavljeni bug). Sadržaj se
      // zato provjerava po Content-Type zaglavlju prije nego postane slika.
      // Prazan Content-Type se DOPUŠTA — neki tile serveri ga ne šalju, a
      // pogrešan sadržaj u praksi UVIJEK dolazi sa text/xml ili text/html.
      const jeSlika = (r) => {
        try {
          const ct = (r.headers && r.headers.get) ? (r.headers.get('content-type') || '') : '';
          return !ct || /^image\//i.test(ct.trim());
        } catch(e) { return true; }
      };

      // v3.111.6: blob URL se NE revoke-uje odmah na onload (kao ranije) — Leaflet
      // REUSE-uje postojeće <img> tile elemente (keepBuffer, zoom in pa out), pa
      // pločica koja je već prikazana može ostati u DOM-u van ekrana. Ako browser
      // pod pritiskom memorije (mobilni GPU) odluči da ponovo dekodira tu sliku
      // (npr. poslije promocije u novi compositor layer), a blob URL je već
      // revoke-ovan, dekodiranje puca i pločica se prikaže kao SLOMLJENA slika —
      // trajno, dok se panom ne izađe iz keepBuffer opsega. Rješenje: URL se čuva
      // na `img._blobUrl` i revoke-uje se TEK kad Leaflet stvarno napusti pločicu
      // (`tileunload`, van keepBuffer opsega), preko `setSrc` ispod koji i sam
      // revoke-uje prethodni URL prije nego dodijeli novi (retry/reload istog img).
      const setSrc = (u) => {
        if (img._discarded) { try { URL.revokeObjectURL(u); } catch(e) {} return; }
        if (img._blobUrl) { try { URL.revokeObjectURL(img._blobUrl); } catch(e) {} }
        img._blobUrl = u;
        img.src = u;
      };

      if (!this._hooked) {
        this._hooked = true;
        // Zombi-zahtjevi: pri pan/zoom Leaflet odbaci pločicu → prekini njene fetch-eve
        // da ne zauzimaju pool konekcija ispred pločica finalnog zooma.
        this.on('tileunload', ev => {
          const el = ev.tile;
          if (el) el._discarded = true;
          if (el && el._ctls) { el._ctls.forEach(c => { try { c.abort(); } catch(e) {} }); el._ctls.clear(); }
          if (el && el._blobUrl) { try { URL.revokeObjectURL(el._blobUrl); } catch(e) {} el._blobUrl = null; }
        });
        // Pločice bez pravog sadržaja (mreža pala / rate-limit / prekinut zoom):
        // ponovi dohvat kad se pogled smiri. Radi i za pločice koje Leaflet REUSE-a
        // bez novog createTile poziva (zoom in pa out) — ključni scenario.
      }
      if (this._map && !this._retryMap) {
        this._retryMap = this._map;
        this._retryMapHandler = () => this._retryEmpty();
        this._retryMap.on('zoomend moveend', this._retryMapHandler);
      }

      // Dohvat s TIMEOUTOM — na terenskoj mreži zahtjev zna visiti beskonačno
      // (mrtva konekcija uz onLine=true); abort → resolve(null) → retry/fallback.
      // `options.authHeadersFn` (v3.128.0, Sentinel-2/CDSE) — opciona async funkcija
      // koja vrati SVJEŽE zaglavlje (npr. Bearer token, obnavlja se sam kad istekne)
      // TAČNO PRIJE svakog zahtjeva; SVI dosadašnji slojevi je nemaju (undefined)
      // pa im se ponašanje NE mijenja — `headers: undefined` je identično kao prije.
      // Neuspjeh (throw/reject) se guta i tretira kao "bez zaglavlja", ne kao pad
      // cijelog dohvata — server će odbiti sa 401 i to ide kroz isti fallback put
      // kao svaki drugi neuspjeh (retry/parent-fallback/prazna pločica).
      const fetchTile = (u, ms) => new Promise(resolve => {
        const ctl = new AbortController();
        img._ctls.add(ctl);
        let finished = false;
        const started = Date.now();
        const finish = (r) => { if (finished) return; finished = true; clearTimeout(t); img._ctls.delete(ctl); resolve(r); };
        // Rok obuhvata i blob(), ne samo zaglavlja. Timeout razrješava Promise
        // čak i kada transport ili service worker ne poslušaju abort odmah.
        const t = setTimeout(() => {
          if (!img._discarded && typeof _netZabiljezi === 'function') _netZabiljezi({ok:false,ms:Date.now()-started,vrsta:'istek'});
          finish(null); ctl.abort();
        }, ms);
        if (typeof ctl.signal.addEventListener === 'function') ctl.signal.addEventListener('abort', () => finish(null), {once:true});
        Promise.resolve(this.options.authHeadersFn ? this.options.authHeadersFn() : null)
          .catch(() => null)
          .then(hdrs => {
            if (img._discarded || ctl.signal.aborted) return null;
            return fetch(u, { mode: 'cors', signal: ctl.signal, headers: hdrs || undefined });
          })
          .then(async r => {
            if (!r || finished) return null;
            const ttfb = Date.now() - started;
            if (r.ok && jeSlika(r)) {
              r._tileCacheResponse = r.clone();
              r._tileBlob = await r.blob();
            }
            if (!finished && !img._discarded && typeof _netZabiljezi === 'function') _netZabiljezi({ok:true,ms:Date.now()-started,ttfb,vrsta:'ok'});
            return r;
          })
          .then(finish)
          .catch(() => finish(null));
      });

      // Zamućeni RODITELJ iz keša (offline promašaj / 404 na visokom zoomu gdje snimka
      // ne postoji) — offscreen canvas je samo rasterizator, u DOM ide <img>.
      // Ostaje _empty=true → kandidat za _retryEmpty zamjenu pravom pločicom.
      const parentFallback = async () => {
        if (!('caches' in window)) return false;
        try {
          const c = await caches.open(cacheName);
          const sz = this.getTileSize();
          for (let dz = 1; dz <= 4; dz++) {
            const pz = coords.z - dz;
            if (pz < 0) break;
            const scale = 1 << dz;
            const px = Math.floor(coords.x / scale), py = Math.floor(coords.y / scale);
            let purl;
            try { purl = this.getTileUrl({ x: px, y: py, z: pz }); } catch(e) { continue; }
            const m = await c.match(purl);
            if (!m) continue;
            const bmp = await createImageBitmap(await m.blob());
            const cv = document.createElement('canvas');
            cv.width = sz.x; cv.height = sz.y;
            const cx = cv.getContext('2d');
            cx.imageSmoothingEnabled = true;
            const sub = sz.x / scale;
            cx.drawImage(bmp, (coords.x - px * scale) * sub, (coords.y - py * scale) * sub, sub, sub, 0, 0, sz.x, sz.y);
            if (typeof bmp.close === 'function') bmp.close();
            const blob = await new Promise(res => cv.toBlob(res));
            if (!blob) continue;
            const u = URL.createObjectURL(blob);
            img.onload = () => done(null, img);
            img.onerror = () => done(null, img);
            img._empty = true;
            setSrc(u);
            return true;
          }
        } catch(e) {}
        return false;
      };

      // isRetry: naknadni pokušaj nad već završenom pločicom (_retryEmpty) —
      // done() se tada NE zove ponovo, samo se img.src zamijeni pravim sadržajem.
      const fromNet = async (isRetry) => {
        if (img._discarded) return;
        // v1.8.8: pločica koje nema u kešu je na mrtvoj vezi čekala 8 s + 1,2 s +
        // 8 s (~17 s) prije zamućenog roditelja — karta je dotle bila prazna i
        // izgledala zamrznuto. Na izmjereno lošoj vezi roditelj ide ODMAH; na
        // slaboj i mrtvoj se mreža ne dira (_retryEmpty pokušava kad se
        // dobra veza vrati).
        if (typeof _mrezaStanje === 'function') {
          const st = _mrezaStanje();
          if (st === 'nema' || st === 'slaba') {
            if (isRetry) return;
            if (await parentFallback()) return;
            img._empty = true; done(null, img); return;
          }
        }
        let r = await fetchTile(url, 8000);
        if (!r || !r.ok) {
          // Kratka pauza pa JEDAN ponovni pokušaj — burst rate-limit (Google 429/403
          // pri učitavanju cijelog ekrana) i tranzijentni prekidi konekcije.
          await new Promise(rs => setTimeout(rs, 1200));
          if (img._discarded) return;
          if (typeof _mrezaStanje !== 'function' || !['nema','slaba'].includes(_mrezaStanje())) r = await fetchTile(url, 8000);
        }
        // 200 OK koji NIJE slika (WMS ServiceException, HTML stranica greške) se
        // tretira kao NEUSPJEH — ne kešira se i ne postaje img.src (inače:
        // slomljena slika po pločici → siva mreža preko cijele karte).
        if (r && r.ok && jeSlika(r)) {
          try { const c = await caches.open(cacheName); await c.put(url, r._tileCacheResponse); } catch(e) {}
          const u = URL.createObjectURL(r._tileBlob);
          img.onload = () => { img._empty = false; if (!isRetry) done(null, img); };
          img.onerror = () => { if (!isRetry) done(null, img); };
          setSrc(u);
          return;
        }
        if (isRetry) return;                 // tihi pokušaj — bez fallbacka i bez done
        if (await parentFallback()) return;
        img._empty = true;
        done(null, img);                     // prazna providna — _retryEmpty pokušava ponovo
      };

      const load = async (isRetry) => {
        if (img._discarded || img._loadBusy) return;
        img._loadBusy = true;
        try {
          if ('caches' in window) {
            const c = await caches.open(cacheName);
            const m = await c.match(url);
            // Keš može sadržavati OTROVAN zapis upisan prije v3.111.7 (WMS XML
            // greška sa 200 OK) — takav se briše odmah, bez pokušaja prikaza,
            // inače bi se slomljena slika servirala TRAJNO i offline.
            if (m && !jeSlika(m)) { try { await c.delete(url); } catch(e) {} }
            else if (m) {
              const u = URL.createObjectURL(await m.blob());
              img.onload = () => { img._empty = false; if (!isRetry) done(null, img); };
              // Pokvaren keš zapis (odsječen download na lošoj mreži) se ne može
              // dekodirati — obriši ga pa probaj mrežu, inače bi se TRAJNO servirao.
              img.onerror = () => { try { c.delete(url); } catch(e) {} fromNet(isRetry); };
              setSrc(u);
              return;
            }
          }
          await fromNet(isRetry);
        } catch(e) { await fromNet(isRetry); }
        finally { img._loadBusy = false; }
      };
      img._load = load;   // koristi ga _retryEmpty
      load(false);
      return img;
    },

    // Pločice TEKUĆEG zooma bez pravog sadržaja (prazne / roditelj-fallback) — ponovi
    // dohvat poslije smirivanja pogleda, max 3 pokušaja po pločici (legitiman 404 na
    // visokom zoomu zadržava roditelj-fallback, bez beskonačnog gađanja servera).
    _retryEmpty() {
      if (this._retryT) clearTimeout(this._retryT);
      this._retryT = setTimeout(() => {
        if (!this._map || navigator.onLine === false) return;
        if (typeof _mrezaStanje === 'function' && ['nema','slaba'].includes(_mrezaStanje())) return;
        for (const key in this._tiles) {
          const t = this._tiles[key];
          const el = t && t.el;
          if (!el || !el._empty || !el._load || el._loadBusy || el._discarded) continue;
          if (t.coords.z !== this._tileZoom) continue;
          el._retryN = (el._retryN || 0) + 1;
          if (el._retryN > 3) continue;
          el._load(true);
        }
      }, 400);
    },

    onRemove(map) {
      clearTimeout(this._retryT);
      if (this._retryMap) this._retryMap.off('zoomend moveend', this._retryMapHandler);
      this._retryMap = this._retryMapHandler = null;
      const base = baseClass || L.TileLayer;
      return base.prototype.onRemove.call(this, map);
    },

    // NE zovemo L.TileLayer default: img bez src-a ima .complete === true pa bi
    // default zadržao pločice koje još čekaju blob, a naš async lanac im je prekinut
    // → trajno prazne. Kao offline GridLayer slojevi: pločice ostaju do prune-a,
    // samo prekini njihove mrežne zahtjeve; sadržaj ionako liječi _retryEmpty.
    _abortLoading() {
      for (const key in this._tiles) {
        const t = this._tiles[key];
        if (t && t.coords.z !== this._tileZoom && t.el && t.el._ctls) {
          t.el._ctls.forEach(c => { try { c.abort(); } catch(e) {} });
          t.el._ctls.clear();
        }
      }
    }
  });
}

const CachedTopo = makeCachedTileLayer();
const CachedOsm  = makeCachedTileLayer();
const CachedSat  = makeCachedTileLayer();

// === MAP ===
// Vrati zadnju poziciju ako postoji, inače defaultna lokacija na 1:50000
let _initMapCenter = _defCenter, _initMapZoom = _defZoom;
try {
  const _lp = JSON.parse(localStorage.getItem('tvlake_last_pos') || 'null');
  if (_lp && [_lp.la,_lp.lo,_lp.z].every(Number.isFinite) && Math.abs(_lp.la)<=85 && Math.abs(_lp.lo)<=180 && _lp.z>=0 && _lp.z<=22) { _initMapCenter = [_lp.la, _lp.lo]; _initMapZoom = _lp.z; }
} catch(e) {}
const _renderCfg = window.DendroRender?.state || {
  tileBuffer:4,overlayBuffer:2,sqlCache:160,mainTileConcurrency:8,
  workerTileConcurrency:5,animations:true
};
const map = L.map('map',{
  maxZoom:22,
  zoomControl:false,
  attributionControl:false,
  // D1-21: fadeAnimation ISKLJUČEN. S njim Leaflet postavlja INLINE opacity na pločice
  // tokom fade-a; naš `transition:none` ih ostavi zaglavljene na opacity 0 (inline
  // nadjačava CSS .leaflet-tile{opacity:1}) → "pločice sa sadržajem ali ekran prazan"
  // (potvrđeno Debug PRO-om: 12 ispravno poredanih content-pločica nevidljivih). Bez
  // fade-a pločice se prikažu odmah na punoj vidljivosti.
  fadeAnimation:false,
  zoomAnimation:_renderCfg.animations,
  zoomAnimationThreshold:4,
  markerZoomAnimation:false,
  inertia:true,
  inertiaDeceleration:3000,
  inertiaMaxSpeed:4000,
  worldCopyJump:false,
  wheelDebounceTime:20,
  wheelPxPerZoomLevel:90,
  tap:true,
  tapTolerance:15,
  preferCanvas:true
}).setView(_initMapCenter, _initMapZoom);
// Grafičko mjerilo (v2.9.8): "1:50 000" u traci je broj, a na terenu se udaljenost
// procjenjuje okom — traka "0–200 m" je za to brža. Štampa ga sakriva (ima svoje).
try { L.control.scale({ metric: true, imperial: false, position: 'bottomright', maxWidth: 110 }).addTo(map); } catch (e) {}
window.Explorer = ExplorerNavigation.create({
  map,
  getPosition: () => lastP ? {...lastP,ts:_onPLastFixTs || 0} : null,
  getCompass: () => ({value:_compassHeading == null ? null : (_compassHeading + (screen.orientation?.angle || window.orientation || 0) + 360) % 360,ts:_compassLastUpdT}),
  isGpsOn: () => gpsOn,
  onBearing: value => { _navLastBrng=value; if (_activeTab==='teren') _updateNavArrows(); },
  toast: showToast
});

map.on('moveend', () => {
  if(document.body.classList.contains('stampa-on'))return;
  try {const c=map.getCenter();localStorage.setItem('tvlake_last_pos',JSON.stringify({la:c.lat,lo:c.lng,z:map.getZoom()}));const sl=_sqlLayers.find(s=>s.visible&&map.hasLayer(s.layer));if(sl)_sqlMapSaveView(sl.name);}catch(e){}
});
// Spriječi da automatski startup fit-ovi (vlake/granice) pregaze podrazumijevani prikaz
let _appStarted = false;
setTimeout(() => { _appStarted = true; }, 4000);
// Zasebni pane za vlake — omogućava brzo sakrivanje svih vlaka + labela odjednom
map.createPane('vlakeLines');  map.getPane('vlakeLines').style.zIndex  = 400;
map.createPane('vlakeLabels'); map.getPane('vlakeLabels').style.zIndex = 401;
// Tragovi i mjerenja MORAJU biti iznad vlakeLines: vlakeLines je CANVAS (jedan
// <canvas> element preko cijelog vidljivog dijela karte — hvata klik svugdje u
// svom pravougaoniku, ne samo tačno gdje je nešto nacrtano) i bio je stackovan
// iznad default overlayPane-a (isti zIndex 400, ali kreiran kasnije = na vrhu),
// pa je gotovo svaki klik na trag/mjerenje (SVG, bez pane-a) hvatao canvas prije
// nego što stigne do njih ispod. SVG blokira klik samo tačno na svojoj liniji
// (ne cijeli pravougaonik), pa ovo ne pravi obrnut problem za vlake.
map.createPane('tragMsrLines'); map.getPane('tragMsrLines').style.zIndex = 410;
// Labele su DOM markeri — sakrij ih tokom pana/zooma radi glatkijeg skrolanja (kao AlpineQuest).
// Statične su tokom pokreta pa korisnik ne primijeti, a kompozitor ne mora repozicionirati svaki čvor.
(function(){
  let _lblHidT = null;
  const _hideLbl = () => { const p = map.getPane('vlakeLabels'); if (p) p.style.visibility = 'hidden'; };
  const _showLbl = () => { const p = map.getPane('vlakeLabels'); if (p) p.style.visibility = ''; };
  map.on('movestart zoomstart', () => { if (_lblHidT) { clearTimeout(_lblHidT); _lblHidT = null; } _hideLbl(); });
  map.on('moveend zoomend', () => { if (_lblHidT) clearTimeout(_lblHidT); _lblHidT = setTimeout(_showLbl, 80); });
  // Zastavica interakcije — pauzira pozadinsko pre-učitavanje tile-ova (_sqlPrewarm)
  let _interEndT = null;
  map.on('movestart zoomstart', () => { if (_interEndT) { clearTimeout(_interEndT); _interEndT = null; } _mapInteracting = true; });
  map.on('moveend zoomend', () => { if (_interEndT) clearTimeout(_interEndT); _interEndT = setTimeout(() => { _mapInteracting = false; }, 250); });
})();
const _vlakeRenderer = L.canvas({ pane: 'vlakeLines', padding: 0.3 });

function _hexToRgb(h){h=h.replace('#','');if(h.length===3)h=h[0]+h[0]+h[1]+h[1]+h[2]+h[2];return[parseInt(h.slice(0,2),16),parseInt(h.slice(2,4),16),parseInt(h.slice(4,6),16)];}
function _rgbToHex(r,g,b){return '#'+[r,g,b].map(c=>Math.max(0,Math.min(255,Math.round(c))).toString(16).padStart(2,'0')).join('');}
function _steepColor(base, grade) {
  const t = Math.min(1, Math.max(0, (grade - 20) / 20));
  const [r,g,b] = _hexToRgb(base);
  const tr = 255, tg = 60, tb = 40;
  return _rgbToHex(r+(tr-r)*t, g+(tg-g)*t, b+(tb-b)*t);
}

const _GRADE_STOPS = [
  [0,  '#22c55e'], [5,  '#4ade80'], [10, '#a3e635'],
  [15, '#facc15'], [20, '#f97316'], [25, '#ef4444'],
  [30, '#dc2626'], [35, '#b91c1c'], [40, '#7f1d1d']
];
function _gradeColor(grade) {
  const g = Math.max(0, grade);
  for (let i = _GRADE_STOPS.length - 1; i >= 0; i--) {
    if (g >= _GRADE_STOPS[i][0]) {
      if (i === _GRADE_STOPS.length - 1) return _GRADE_STOPS[i][1];
      const [g0, c0] = _GRADE_STOPS[i], [g1, c1] = _GRADE_STOPS[i+1];
      const t = (g - g0) / (g1 - g0);
      const [r0,g0r,b0] = _hexToRgb(c0), [r1,g1r,b1] = _hexToRgb(c1);
      return _rgbToHex(r0+(r1-r0)*t, g0r+(g1r-g0r)*t, b0+(b1-b0)*t);
    }
  }
  return _GRADE_STOPS[0][1];
}

function _segGrade(pts, i) {
  const p0 = pts[i-1], p1 = pts[i];
  const hd = dst(p0.la, p0.lo, p1.la, p1.lo);
  if (hd < 1) return -1;
  const dh = Math.abs((p1.al||0) - (p0.al||0));
  return Math.min(60, (dh / hd) * 100);
}

function _smoothedGrades(pts) {
  const raw = [];
  for (let i = 1; i < pts.length; i++) raw.push(_segGrade(pts, i));
  if (raw.length < 3) return raw;
  const out = [raw[0]];
  for (let i = 1; i < raw.length - 1; i++) {
    if (raw[i] < 0) { out.push(raw[i]); continue; }
    out.push((raw[i-1] >= 0 && raw[i+1] >= 0) ? (raw[i-1] + raw[i] * 2 + raw[i+1]) / 4 : raw[i]);
  }
  out.push(raw[raw.length - 1]);
  return out;
}

// ── Nagib vlake kao BROJ u listi (v3.118.0) ─────────────────────────────────
// Nagib se do sada mogao vidjeti samo kao BOJA na karti (preklopnik "Nagib
// vlaka" / admin "Analiza nagiba") ili otvaranjem profila JEDNE PO JEDNE
// vlake. Za odluku koju forester stvarno donosi — "je li ova vlaka uopšte
// prohodna za traktor/forvarder" — to je bilo prekasno: lista je pokazivala
// samo ↑uspon/↓pad, a to NE razlikuje blagu trasu od one sa 40% zidom u
// sredini. Vlaka sa ↑120 m može biti ravnomjernih 8% kroz 1,5 km (u redu) ili
// imati 60 m preko 30% (neprohodno) — isti brojevi u listi.
//
// _vlNagibStat je ČISTA funkcija (bez DOM-a i karte) da se može testirati, i
// računa nad ISTIM izglađenim nagibima (_smoothedGrades) koje koristi bojenje
// na karti — broj u listi i boja na karti se zato ne mogu razići.
//
// Vraća null kad nema upotrebljivih visina (nacrtana vlaka bez GPS-a) umjesto
// nule — "nije mjereno" nije isto što i "ravno"; ista logika kao _elevHtml.
function _vlNagibStat(pts, limitPct) {
  if (!pts || pts.length < 2) return null;
  if (!pts.some(p => (p.al || 0) !== 0)) return null;
  const lim = limitPct > 0 ? limitPct : 20;
  const grades = _smoothedGrades(pts);
  let max = 0, prekoM = 0, sumGD = 0, mjerenoM = 0, ukupnoM = 0;
  for (let i = 0; i < grades.length; i++) {
    const hd = dst(pts[i].la, pts[i].lo, pts[i + 1].la, pts[i + 1].lo);
    ukupnoM += hd;
    const g = grades[i];
    if (g < 0) continue;   // segment kraći od 1 m — _segGrade ga označava kao nepouzdan
    if (g > max) max = g;
    sumGD += g * hd; mjerenoM += hd;
    if (g >= lim) prekoM += hd;
  }
  if (mjerenoM <= 0) return null;
  return {
    max: Math.round(max),
    avg: Math.round((sumGD / mjerenoM) * 10) / 10,
    prekoM: Math.round(prekoM),
    ukupnoM: Math.round(ukupnoM),
    pct: ukupnoM > 0 ? (prekoM / ukupnoM) * 100 : 0,
    limit: lim
  };
}

// Limit je izbor korisnika jer ZAVISI OD MEHANIZACIJE (traktor uzbrdo podnosi
// znatno više od forvardera) — jedan zakucan broj bi za pola korisnika bio
// pogrešan, a predstavljen kao mjerodavan. Podrazumijevanih 20% je isti prag
// koji admin "Analiza nagiba" već koristi ("20-25% Jako strmo" u njenoj
// legendi), pa se dva ekrana slažu dok korisnik sam ne odluči drugačije.
const _VL_NAGIB_LIMITI = [12, 15, 18, 20, 25, 30];
function _vlNagibLimit() {
  const n = parseInt(localStorage.getItem('tvlake_vl_nagib_limit'), 10);
  return _VL_NAGIB_LIMITI.indexOf(n) >= 0 ? n : 20;
}
function _vlNagibSetLimit(v) {
  try { localStorage.setItem('tvlake_vl_nagib_limit', String(parseInt(v, 10))); } catch(e) {}
  rndList();
}

// Memoizacija je OBAVEZNA, ne optimizacija: rndList() se tokom snimanja poziva
// svake 2 s (_scheduleOvlRnd), a _smoothedGrades nad svim vlakama projekta je
// izmjereno 5.9 ms u sandboxu za 50 vlaka / 42k tačaka — na telefonu višestruko
// više, i to baš dok GPS snimanje ima prioritet (vidi CLAUDE.md upozorenje da
// se analiza nagiba ne kači na rndList/GPS hot-path).
//
// Potpis NAMJERNO prima već izračunatu dužinu `d` umjesto da zove calcL sam —
// calcL je O(n) kao i sam račun nagiba, pa bi potpis koštao koliko i posao koji
// izbjegava. _renderVlakaRow tu dužinu ionako računa za prikaz. Tokom snimanja
// se time mijenja potpis SAMO vlake koja raste (0.05 ms), ostale su pogodak u
// kešu.
function _vlNagib(v, d) {
  if (!v || !v.pts || v.pts.length < 2) return null;
  const lim = _vlNagibLimit();
  const sig = v.pts.length + ':' + Math.round(d || 0) + ':' + lim;
  if (v._ngC && v._ngC.sig === sig) return v._ngC.st;
  let pts = v.pts;
  if (!pts.some(p => (p.al || 0) !== 0)) {
    // Nacrtana vlaka nema GPS visine. Ako je korisnik već otvarao "Profil",
    // visine terena su preuzete i keširane (v._apiProfile) — iskoristi ih
    // umjesto da bedž ostane prazan. Bez novog mrežnog poziva iz liste.
    const ap = v._apiProfile;
    pts = (ap && ap.pts && ap.alts && ap.pts.length === ap.alts.length)
      ? ap.pts.map((p, i) => ({ la: p.la, lo: p.lo, al: ap.alts[i] }))
      : null;
  }
  const st = pts ? _vlNagibStat(pts, lim) : null;
  v._ngC = { sig, st };
  return st;
}

function _updateSteepOverlay(v) {
  if (v._steepPolys) { v._steepPolys.forEach(p => { try { map.removeLayer(p); } catch(e){} }); v._steepPolys = []; }
  if (!v.pts || v.pts.length < 2) return;
  v._steepPolys = [];
  const grades = _smoothedGrades(v.pts);
  let cur = null;
  for (let i = 0; i < grades.length; i++) {
    const grade = grades[i];
    if (grade < 0) { if (cur) { _addGradePoly(v, cur); cur = null; } continue; }
    const band = Math.min(40, Math.floor(grade / 5) * 5);
    const si = i + 1;
    if (cur && si === cur.end + 1 && cur.band === band) {
      cur.end = si;
      if (grade > cur.maxGrade) cur.maxGrade = grade;
    } else {
      if (cur) _addGradePoly(v, cur);
      cur = { start: si - 1, end: si, band, maxGrade: grade };
    }
  }
  if (cur) _addGradePoly(v, cur);
}

function _addGradePoly(v, seg) {
  const pts = v.pts.slice(seg.start, seg.end + 1).map(p => [p.la, p.lo]);
  if (pts.length < 2) return;
  const col = _gradeColor(seg.maxGrade);
  const poly = L.polyline(pts, { color: col, weight: 5, opacity: 1, pane: 'vlakeLines', renderer: _vlakeRenderer }).addTo(map);
  v._steepPolys.push(poly);
}

// ── Preklopnik "Nagib vlaka" na karti (v3.102.3) ────────────────────────────
// _updateSteepOverlay je do sada bio dostupan SAMO kroz "Analiza nagiba" u
// admin modalu nadzora (_pmNagibAnaliza, vidi ~21199) — koristan prikaz za
// svakodnevni rad na terenu (koja dionica je najstrmija) bio je zaključan iza
// admin ekrana i tuđe elevation-enrichment/statistike koje regularni
// projektant ne treba. Ovo je laka verzija: oboji SVE trenutno vidljive vlake
// na karti bojom po nagibu (ista skala kao Analiza nagiba), checkbox u 🗄
// Podloge i slojevi → Granice → Prikaz slojeva.
//
// NAMJERNO nije "živ" prikaz (ne prati GPS snimanje ni izmjene uživo) — isti
// obrazac kao admin verzija, koja je i sama snapshot analiza na klik, ne
// live-tracking. Prekomponovanje na svaku GPS tačku bi opteretilo bateriju i
// FPS baš tokom snimanja, gdje pouzdanost snimanja ima prioritet nad ovim
// prikazom (vidi CLAUDE.md — GPS snimanje se ne smije usporavati). Isključi/
// uključi ponovo za osvježen prikaz poslije izmjena vlake.
//
// Dijeli v._steepPolys polje sa admin analizom (_updateSteepOverlay je
// idempotentan po vlaci — zadnji poziv pobjeđuje) — u rijetkom slučaju da isti
// (admin) nalog istovremeno koristi i ovaj preklopnik i "Analiza nagiba", stop
// jedne strane će očistiti i prikaz druge. Bezopasno (nema greške, samo se
// overlay ugasi), i toliko rijedak scenario da ne traži posebnu sinhronizaciju.
let _vlNagibOn = false;
let _vlNagibHidden = [];
let _vlNagibSteep = [];

function _vlNagibToggle(on) {
  _vlNagibOn = on;
  _vlNagibHidden.forEach(p => { try { p.setStyle({ opacity: 0.9 }); } catch(e) {} });
  _vlNagibHidden = [];
  _vlNagibSteep.forEach(p => { try { map.removeLayer(p); } catch(e) {} });
  _vlNagibSteep = [];
  vlake.forEach(v => {
    if (v._steepPolys) {
      v._steepPolys.forEach(p => { try { map.removeLayer(p); } catch(e) {} });
      v._steepPolys = [];
    }
  });
  if (!on) return;
  vlake.forEach(v => {
    if (!v.poly || !map.hasLayer(v.poly) || v.pts.length < 2) return;
    if (!v.pts.some(pt => (pt.al || 0) !== 0)) return;   // nema visina — nema šta obojiti
    try { v.poly.setStyle({ opacity: 0 }); _vlNagibHidden.push(v.poly); } catch(e) {}
    _updateSteepOverlay(v);
    if (v._steepPolys) _vlNagibSteep.push(...v._steepPolys);
  });
  if (!_vlNagibSteep.length) showToast('⚠ Nijedna vidljiva vlaka nema nadmorske visine za bojenje po nagibu');
}

map.createPane('refKarte');    map.getPane('refKarte').style.zIndex    = 620;
map.createPane('putevi');      map.getPane('putevi').style.zIndex      = 390;
map.createPane('demOverlay'); map.getPane('demOverlay').style.zIndex = 250;
const _puteviRenderer = L.canvas({ pane: 'putevi', padding: 0.3 });

// v1.6.0: opšta zaštita od ZAOSTALOG canvas renderera (v1.4.8/v1.4.9 klasa).
// Leaflet sam napravi renderer po pane-u kad u njega uđe prvi canvas sloj bez
// eksplicitne `renderer:` opcije, kešira ga u map._paneRenderers i NIKAD ga ne
// vrati — čak ni kad zadnji sloj koji ga je koristio nestane sa karte. Taj
// canvas je JEDAN element preko CIJELE karte, pa i potpuno prazan guta svaki
// dodir sloju ispod (terenski prijavljeno dvaput: "izmjere površine i ostalo
// nije klikabilno"). Mehanizam koji je to čistio uklonjen je u v1.5.7 zajedno
// sa Požarima, pa je zaštita ovdje vraćena kao OPŠTA, bez veze sa tom sekcijom.
// `delete map._paneRenderers[ime]` je OBAVEZAN, ne kozmetika: bez njega
// _getPaneRenderer vrati već uklonjen renderer i sljedeći sloj crta u odvojen,
// otkačen canvas koji se više nikad ne prikaže.
function _oslobodiPaneRenderer(ime) {
  try {
    const r = map._paneRenderers && map._paneRenderers[ime];
    if (!r) return false;
    if (map.hasLayer(r)) map.removeLayer(r);
    delete map._paneRenderers[ime];
    return true;
  } catch(e) { return false; }
}

// _WC_CACHE/CachedWCover mora biti definisan PRIJE TL (referenciran unutar njega).
const _WC_CACHE    = 'tvlake-wcover-v1';
// WMS varijanta iste keš/timeout/retry logike kao CachedTopo/CachedSat (vidi
// napomenu kod makeCachedTileLayer) — bbox GetMap zahtjev umjesto XYZ predloška.
const CachedWCover = makeCachedTileLayer(_WC_CACHE, L.TileLayer.WMS);
const TL = {
  '⛰ Topo':    new CachedTopo('https://{s}.tile.opentopomap.org/{z}/{x}/{y}.png',{maxNativeZoom:17,maxZoom:22,subdomains:['a','b','c'],keepBuffer:_renderCfg.tileBuffer,updateWhenZooming:false,updateWhenIdle:true,updateInterval:150}),
  '🛰 Satelit': new CachedSat('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{maxNativeZoom:19,maxZoom:22,keepBuffer:_renderCfg.tileBuffer,updateWhenZooming:false,updateWhenIdle:true,updateInterval:150}),
  '🗺 Karta':   new CachedOsm('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxNativeZoom:19,maxZoom:22,keepBuffer:_renderCfg.tileBuffer,updateWhenZooming:false,updateWhenIdle:true,updateInterval:150}),
  '📡 Google':  new CachedSat('https://mt{s}.google.com/vt/lyrs=s&x={x}&y={y}&z={z}',{maxNativeZoom:20,maxZoom:22,subdomains:['0','1','2','3'],keepBuffer:_renderCfg.tileBuffer,updateWhenZooming:false,updateWhenIdle:true,updateInterval:150}),
  // v3.103.0: EOX Sentinel-2 true-color cloudless ZAMIJENJEN ESA WorldCover-om
  // (pokrivenost zemljišta — šuma/nije šuma/voda/naselje, 10m). Korisnik već ima
  // pravu Sentinel-2 satelitsku podlogu (ranije ovdje) i tražio je nešto DRUGAČIJE
  // umjesto nje, ne još jednu true-color varijantu. Razmatran je i Sentinel-2 NDVI
  // (vegetacijski indeks) kao zamjena, ali svaki besplatan/bez-ključa izvor kog
  // sam mogao pronaći (NASA GIBS) je datumski parametrizovan (specifičan 8-dnevni
  // kompozit, ne trajan proizvod) — ne staje u "keširaj jednom, uvijek važi" model
  // kojim rade ostale bazne podloge (offline karta bi pokazivala sve stariju
  // snimku dok se datum ručno ne osvježi u kodu). WorldCover je STATIČAN proizvod
  // (fiksna epoha, npr. 2021) kao i ostale podloge, i sam po sebi izveden iz
  // Sentinel-1/2 podataka — pravi odgovor na "nešto drugačije od trenutne
  // satelitske slike", bez tog problema. WMS servis (Terrascope/VITO, besplatno,
  // bez ključa) — endpoint NIJE bilo moguće provjeriti iz ovog sandboxa (egress
  // dozvoljava samo uzak spisak domena, vidi napomenu kod _OVL.pozari) — provjeriti
  // na terenskom uređaju prije oslanjanja.
  '🌍 Sentinel': new CachedWCover('https://services.terrascope.be/wms/v2', {
    layers: 'WORLDCOVER_2021_MAP', format: 'image/png', transparent: false,
    version: '1.1.1', maxNativeZoom: 12, maxZoom: 22, keepBuffer: _renderCfg.tileBuffer,
    updateWhenZooming: false, updateWhenIdle: true, updateInterval: 150
  })
};
const _ELEV_CACHE  = 'tvlake-elev-v1';
const _SLOPE_CACHE = 'tvlake-slope-v1';
const _TERR_CACHE  = 'tvlake-terr-v1';
const CachedElev  = makeCachedTileLayer(_ELEV_CACHE);
const CachedSlope = makeCachedTileLayer(_SLOPE_CACHE);

// ── DEM Canvas helpers ────────────────────────────────────────────────────────
function _hsl2rgb(h, s, l) {
  const f = (n, k=(n+h/30)%12) => l - s*Math.min(l,1-l)*Math.max(-1,Math.min(k-3,9-k,1));
  return [Math.round(f(0)*255), Math.round(f(8)*255), Math.round(f(4)*255)];
}
// 8 visinskih pojaseva — kontrastne boje da susjedni pojasevi budu lako razlikovani
const _NV_BANDS = [
  [   0, [ 34, 197,  94, 190]],  // 0–200 m    zelena
  [ 200, [250, 204,  21, 190]],  // 200–400 m  žuta
  [ 400, [249, 115,  22, 190]],  // 400–600 m  narančasta
  [ 600, [239,  68,  68, 190]],  // 600–800 m  crvena
  [ 800, [168,  85, 247, 190]],  // 800–1000 m ljubičasta
  [1000, [ 59, 130, 246, 192]],  // 1000–1200 m plava
  [1200, [  6, 182, 212, 192]],  // 1200–1400 m cijan
  [1400, [226, 232, 240, 200]],  // >1400 m    bijela
];
function _nvColor(e) {
  if (e < 0) return [50, 100, 200, 160];
  for (let i = _NV_BANDS.length - 1; i >= 0; i--)
    if (e >= _NV_BANDS[i][0]) return _NV_BANDS[i][1];
  return _NV_BANDS[0][1];
}
function _aspColor(deg, mag) {
  if (mag < 0.8) return [128, 128, 128, 0];
  // 4 anchor colours: N=blue, E=green, S=orange, W=purple — interpolate between them
  const stops = [
    [0,   [59,  127, 212]],  // Sjever (N)
    [90,  [76,  175,  80]],  // Istok  (E)
    [180, [232, 100,  10]],  // Jug    (S)
    [270, [156,  77, 204]],  // Zapad  (W)
    [360, [59,  127, 212]],  // wrap back to N
  ];
  let lo = stops[0], hi = stops[1];
  for (let i = 0; i < stops.length - 1; i++) {
    if (deg >= stops[i][0] && deg < stops[i+1][0]) { lo = stops[i]; hi = stops[i+1]; break; }
  }
  const t = (deg - lo[0]) / (hi[0] - lo[0]);
  const lerp = (a, b, t) => Math.round(a + (b - a) * t);
  const r = lerp(lo[1][0], hi[1][0], t);
  const g = lerp(lo[1][1], hi[1][1], t);
  const b = lerp(lo[1][2], hi[1][2], t);
  return [r, g, b, Math.min(210, Math.round(85 + mag * 30))];
}
async function _getTerrariumTile(z, x, y) {
  const url = `https://s3.amazonaws.com/elevation-tiles-prod/terrarium/${z}/${x}/${y}.png`;
  let cache=null,resp=null;
  try { if ('caches' in window) {cache=await caches.open(_TERR_CACHE);resp=await cache.match(url);} } catch(e) {}
  const decode=async r=>{
    if(!r?.ok)return null;
    const ct=r.headers?.get('Content-Type')||'';
    if(ct&&!/^image\//i.test(ct))return null;
    const blob=await r.blob();let img;
    if(typeof createImageBitmap!=='undefined')img=await createImageBitmap(blob);
    else img=await new Promise(resolve=>{const objectUrl=URL.createObjectURL(blob),image=new Image();
      const finish=value=>{URL.revokeObjectURL(objectUrl);resolve(value);};
      image.onload=()=>finish(image);image.onerror=()=>finish(null);image.src=objectUrl;});
    if(img&&(img.width!==256||img.height!==256)){if(img.close)img.close();return null;}
    return img;
  };
  if(resp){try{const img=await decode(resp);if(img)return img;}catch(e){}
    try{await cache?.delete(url);}catch(e){}
  }
  if(typeof _mrezaProbaj==='function'&&!_mrezaProbaj())return null;
  try{
    resp=await _fetchT(url,10000,{mode:'cors'});const saved=cache?resp.clone():null;
    const img=await decode(resp);if(!img)return null;
    if(cache&&saved){try{await cache.put(url,saved);}catch(e){/* Kvota ne smije blokirati online prikaz. */}}
    return img;
  }catch(e){return null;}
}
// Dekoduje jednu 256x256 Terrarium pločicu (već preuzetu/keširanu preko
// _getTerrariumTile) u Float32Array elevacija (elev = R*256 + G + B/256 -
// 32768). Izvučeno iz _makeDemCanvasLayer/DemSlopeClass (bila dva identična
// bloka) da bi ga i _demFetchGridTerrarium mogao koristiti bez treće kopije.
function _terrariumDecodeTile(bitmapOrImg) {
  const tmp = document.createElement('canvas');
  tmp.width = tmp.height = 256;
  const tc = tmp.getContext('2d', { willReadFrequently: true });
  tc.drawImage(bitmapOrImg, 0, 0, 256, 256);
  const raw = tc.getImageData(0, 0, 256, 256).data;
  const elev = new Float32Array(256 * 256);
  for (let i = 0; i < 256 * 256; i++) {
    const h=raw[i*4]*256+raw[i*4+1]+raw[i*4+2]/256-32768;
    elev[i]=raw[i*4+3]&&DemQuality.valid(h)?h:NaN;
  }
  return elev;
}
function _makeDemCanvasLayer(mode) {
  return L.GridLayer.extend({
    createTile(coords, done) {
      const canvas = document.createElement('canvas');
      canvas.width = canvas.height = 256;
      _getTerrariumTile(coords.z, coords.x, coords.y).then(src => {
        if (!src) { done(null, canvas); return; }
        const elev = (()=>{try{return _terrariumDecodeTile(src);}finally{if(src.close)src.close();}})();
        const ctx = canvas.getContext('2d');
        const out = ctx.createImageData(256, 256);
        const od  = out.data;
        for (let py=0; py<256; py++) {
          for (let px=0; px<256; px++) {
            const idx = py*256+px;
            let rgba;
            if (mode === 'nv') {
              rgba = Number.isFinite(elev[idx])?_nvColor(elev[idx]):[0,0,0,0];
            } else {
              const metres=Math.cos(_tile2lat(coords.y+(py+.5)/256,coords.z)*Math.PI/180)*156543.03392/2**coords.z;
              const g=DemQuality.gradient(elev,px,py,metres);
              rgba=Number.isFinite(g.percent)&&g.percent>.01?_aspColor(g.bearing,1.5):[0,0,0,0];
            }
            od[idx*4]=rgba[0]; od[idx*4+1]=rgba[1]; od[idx*4+2]=rgba[2]; od[idx*4+3]=rgba[3];
          }
        }
        ctx.putImageData(out, 0, 0);
        done(null, canvas);
      }).catch(() => done(null, canvas));
      return canvas;
    }
  });
}
const DemNV    = _makeDemCanvasLayer('nv');
const DemEkspo = _makeDemCanvasLayer('ekspo');

// ── Konture (izohipse) iz ISTOG Terrarium DEM-a (v3.103.0) ─────────────────
// Nema novog mrežnog izvora — koristi identičnu pločicu koju app već povlači
// za Hipsometriju/Nagib/N.V./Ekspoziciju (_getTerrariumTile + _TERR_CACHE),
// samo je crta kao linije umjesto obojenih piksela. Radi i offline čim je
// pločica jednom viđena kroz bilo koji od ta četiri sloja.
// Korak 20m (kao klasična topografska karta 1:25000); svaka peta linija
// (100m) je "indeksna" — deblja, radi lakšeg čitanja na terenu.
const _CONTOUR_STEP = 20;
function _contourColor(level) {
  return (level % 100 === 0) ? 'rgba(120,72,0,0.75)' : 'rgba(120,72,0,0.42)';
}

// Marching squares nad jednom ćelijom (4 ugla mreže), za JEDAN nivo. Umjesto
// oslanjanja na napamet zapisanu 16-slučajnu tablicu (lako pogriješiti),
// računa se GENERIČKI: za svaku od 4 ivice ćelije provjeri prelazi li nivo
// preko nje (dva kraja na različitim stranama), i interpoliraj tačku
// presjeka. 2 presjeka → jedna linija. 4 presjeka (dijagonalno "sedlo") →
// spoji parove prema prosjeku 4 ugla (standardna konvencija, sprječava da se
// linija sama sebe siječe).
function _msCellSegments(tl, tr, br, bl, level, x, y) {
  if(![tl,tr,br,bl,level].every(Number.isFinite))return null;
  const e = {};
  if ((tl >= level) !== (tr >= level)) e.T = [x + (level - tl) / (tr - tl), y];
  if ((tr >= level) !== (br >= level)) e.R = [x + 1, y + (level - tr) / (br - tr)];
  if ((bl >= level) !== (br >= level)) e.B = [x + (level - bl) / (br - bl), y + 1];
  if ((tl >= level) !== (bl >= level)) e.L = [x, y + (level - tl) / (bl - tl)];
  const n = Object.keys(e).length;
  if (n === 2) return [[e[Object.keys(e)[0]], e[Object.keys(e)[1]]]];
  if (n === 4) {
    const hi = (tl + tr + br + bl) / 4 >= level;
    return (hi === (tl >= level)) ? [[e.T, e.L], [e.R, e.B]] : [[e.T, e.R], [e.L, e.B]];
  }
  return null;
}

function _drawContours(ctx, elev, W, H, step) {
  if(!Number.isFinite(step)||step<=0)return;
  let min = Infinity, max = -Infinity;
  for (let i = 0; i < elev.length; i++) { const v = elev[i]; if(!Number.isFinite(v))continue; if (v < min) min = v; if (v > max) max = v; }
  if (!isFinite(min) || max - min < step) return;   // premali raspon — nema šta crtati
  const lo = Math.floor(min / step) * step, hi = Math.ceil(max / step) * step;
  ctx.lineJoin = 'round';
  for (let level = lo; level <= hi; level += step) {
    ctx.strokeStyle = _contourColor(level);
    ctx.lineWidth = (level % 100 === 0) ? 1.6 : 0.8;
    ctx.beginPath();
    for (let y = 0; y < H - 1; y++) {
      for (let x = 0; x < W - 1; x++) {
        const tl = elev[y*W+x], tr = elev[y*W+x+1], bl = elev[(y+1)*W+x], br = elev[(y+1)*W+x+1];
        if (level < Math.min(tl,tr,bl,br) || level > Math.max(tl,tr,bl,br)) continue;
        const segs = _msCellSegments(tl, tr, br, bl, level, x, y);
        if (!segs) continue;
        segs.forEach(([a, b]) => { ctx.moveTo(a[0], a[1]); ctx.lineTo(b[0], b[1]); });
      }
    }
    ctx.stroke();
  }
}

const DemContour = L.GridLayer.extend({
  createTile(coords, done) {
    const canvas = document.createElement('canvas');
    canvas.width = canvas.height = 256;
    _getTerrariumTile(coords.z, coords.x, coords.y).then(src => {
      if (!src) { done(null, canvas); return; }
      const elev = (()=>{try{return _terrariumDecodeTile(src);}finally{if(src.close)src.close();}})();
      _drawContours(canvas.getContext('2d'), elev, 256, 256, _CONTOUR_STEP);
      done(null, canvas);
    }).catch(() => done(null, canvas));
    return canvas;
  }
});

// ── Slope canvas layer (terrarium-based, crvene nijanse od 30%) ───────────────
function _tile2lat(y, z) {
  const n = Math.PI - 2 * Math.PI * y / Math.pow(2, z);
  return 180 / Math.PI * Math.atan(0.5 * (Math.exp(n) - Math.exp(-n)));
}
function _tile2lon(x, z) { return x / Math.pow(2, z) * 360 - 180; }
// Web Mercator lon/lat → FRAKCIONI tile x/y (isti obrazac kao _PREWARM_LL2T,
// ovdje samostalno da _demFetchGridTerrarium ne zavisi od tog nepovezanog
// prewarm mehanizma; fractional — Math.floor() daje cijeli tile broj).
function _termLon2x(lon, z) { return (lon + 180) / 360 * Math.pow(2, z); }
function _termLat2y(lat, z) {
  const r = lat * Math.PI / 180;
  return (1 - Math.log(Math.tan(r) + 1 / Math.cos(r)) / Math.PI) / 2 * Math.pow(2, z);
}
function _slopeColor(pct) {
  if (!Number.isFinite(pct) || pct <= 30) return [0, 0, 0, 0];
  const t = Math.min(1, (pct - 30) / 80); // 0 pri 30%, 1 pri 110%+
  return [
    Math.round(230 - t * 50),   // R: 230→180
    Math.round(170 - t * 160),  // G: 170→10
    Math.round(170 - t * 160),  // B: 170→10
    Math.round(110 + t * 130)   // A: 110→240
  ];
}
const DemSlopeClass = L.GridLayer.extend({
  createTile(coords, done) {
    const canvas = document.createElement('canvas');
    canvas.width = canvas.height = 256;
    _getTerrariumTile(coords.z, coords.x, coords.y).then(src => {
      if (!src) { done(null, canvas); return; }
      const elev = (()=>{try{return _terrariumDecodeTile(src);}finally{if(src.close)src.close();}})();
      // Geografska veličina piksela u metrima na ovoj geografskoj širini
      const lat  = _tile2lat(coords.y + 0.5, coords.z);
      const pixM = Math.cos(lat * Math.PI / 180) * 156543.03392 / Math.pow(2, coords.z);
      const ctx = canvas.getContext('2d');
      const out = ctx.createImageData(256, 256);
      const od  = out.data;
      for (let py = 0; py < 256; py++) {
        for (let px = 0; px < 256; px++) {
          const idx = py * 256 + px;
          const metres=Math.cos(_tile2lat(coords.y+(py+.5)/256,coords.z)*Math.PI/180)*156543.03392/2**coords.z;
          const pct=DemQuality.gradient(elev,px,py,metres).percent;
          const rgba = _slopeColor(pct);
          od[idx*4]=rgba[0]; od[idx*4+1]=rgba[1]; od[idx*4+2]=rgba[2]; od[idx*4+3]=rgba[3];
        }
      }
      ctx.putImageData(out, 0, 0);
      done(null, canvas);
    }).catch(() => done(null, canvas));
    return canvas;
  }
});

const _OVL = {
  elev:  new CachedElev('https://server.arcgisonline.com/ArcGIS/rest/services/Elevation/World_Hillshade/MapServer/tile/{z}/{y}/{x}', { pane:'demOverlay', maxZoom:18, opacity:0.7, attribution:'', keepBuffer:_renderCfg.overlayBuffer }),
  slope: new DemSlopeClass({ pane:'demOverlay', maxNativeZoom:14, maxZoom:22, opacity:1.0, attribution:'', keepBuffer:_renderCfg.overlayBuffer }),
  nv:    new DemNV(   { pane:'demOverlay', maxNativeZoom:14, maxZoom:22, opacity:0.75, attribution:'', keepBuffer:_renderCfg.overlayBuffer }),
  ekspo: new DemEkspo({ pane:'demOverlay', maxNativeZoom:14, maxZoom:22, opacity:0.80, attribution:'', keepBuffer:_renderCfg.overlayBuffer }),
  kont:  new DemContour({ pane:'demOverlay', maxNativeZoom:14, maxZoom:22, opacity:0.9, attribution:'', keepBuffer:_renderCfg.overlayBuffer }),
};
