// Indikator "Učitavam kartu…" pokazuje da worker u pozadini otvara zadnju
// SQLite kartu. Lagana osnovna podloga se prikazuje odmah, a `hide()` se zove
// poslije uspjeha ili pada preko try/finally u sqlmapRestoreAll — indikator
// nikad ne smije ostati trajno prikazan.
// v1.1.7: pamti KAD je indikator prikazan — sqlmapRestoreAll (v1.1.6) mjeri
// SAMO svoje vlastito trajanje, a taj poziv može stići tek POSLIJE nepoznatog
// razmaka (initAuth/showApp gate prije _startupRestore) koji je NEVIDLJIV
// za tu dijagnostiku. Ako korisnik vidi "Učitavam kartu" 10s a sqlmapRestoreAll
// samo javlja par stotina ms, razlika je baš u ovom razmaku.
let _mapRestoreIndicatorShownAt = null;
let _mapRestoreIndicatorTimer = null;
const _ADMIN_DEBUG_KEY = 'tvlake_admin_debug_v1';
function _debugRead() {
  try {
    const v = JSON.parse(localStorage.getItem(_ADMIN_DEBUG_KEY) || '{}');
    return v && typeof v === 'object' && !Array.isArray(v) ? v : {};
  } catch(e) { return {}; }
}
function _debugUpsert(id, title, text, state) {
  if (!id || !text) return;
  const all = _debugRead();
  all[id] = { id, title:title || id, text:String(text), state:state || 'aktivno', updatedAt:Date.now() };
  const ids = Object.keys(all).sort((a,b) => (all[b].updatedAt || 0) - (all[a].updatedAt || 0));
  ids.slice(12).forEach(k => delete all[k]);
  try { localStorage.setItem(_ADMIN_DEBUG_KEY, JSON.stringify(all)); } catch(e) {}
  try { if (typeof _adminDebugRender === 'function') _adminDebugRender(); } catch(e) {}
}
function _debugRemove(id) {
  const all = _debugRead();
  if (!Object.prototype.hasOwnProperty.call(all, id)) return;
  delete all[id];
  try { localStorage.setItem(_ADMIN_DEBUG_KEY, JSON.stringify(all)); } catch(e) {}
  try { if (typeof _adminDebugRender === 'function') _adminDebugRender(); } catch(e) {}
}

// ── Hvatač "dugme ne reaguje" (v1.3.2) ──────────────────────────────────────
// Terenska prijava: 📁 Lista oznaka/KML i ✏ Nacrtaj vlaku ručno ponekad ne
// reaguju na dodir, i restart app-a ne pomaže. Ta dugmad su vidljiva SAMO na
// Karta/Projekat tabu (nv-badge/#pd-draw-vlaka-btn se sakriju na drugim
// tabovima preko _setMapUIVisible), pa dijagnostika iz #debug-panel-a NE MOŽE
// naknadno "pogoditi" pravo mjesto klika — sandbox isto ne može reprodukovati
// stvaran render Android WebView-a (vidi CLAUDE.md "Osirotjeli #dlg-overlay").
// Zato se prati SVAKI stvaran klik u capture fazi: ako korisnik tapne TAČNO
// unutar granica ovih dugmadi a browser klik dodijeli NEKOM DRUGOM elementu,
// to je direktan dokaz da nešto (nevidljiv overlay, pogrešan z-index...)
// presreće dodir — upisuje se u ISTI centralni DEBUG (📁 admin ga vidi u
// 🛠 DEBUG tabu na ISTOM uređaju gdje se problem desio).
const _KLIK_WATCH = [
  { sel: '#oznake-btn', label: '📁 Lista oznaka/KML (srednje dugme ispod biranja mapa)' },
  { sel: '#pd-draw-vlaka-btn', label: '✏ Nacrtaj vlaku ručno' },
];
function _klikDijagOpis(el) {
  if (!el) return '(nema mete — klik nije stigao ni do jednog elementa)';
  const cs = getComputedStyle(el);
  const cls = (typeof el.className === 'string' && el.className.trim()) ? '.' + el.className.trim().replace(/\s+/g, '.') : '';
  return '<' + el.tagName.toLowerCase() + (el.id ? '#' + el.id : '') + cls + '> · z-index:' + cs.zIndex + ' · position:' + cs.position + ' · pointer-events:' + cs.pointerEvents + ' · opacity:' + cs.opacity;
}
function _klikDijagInstall() {
  document.addEventListener('click', function(e) {
    _KLIK_WATCH.forEach(w => {
      let btn; try { btn = document.querySelector(w.sel); } catch(err) { return; }
      if (!btn) return;
      const r = btn.getBoundingClientRect();
      if (r.width < 1 || r.height < 1) return; // trenutno nije na ekranu (drugi tab) - nema šta provjeriti
      const cx = e.clientX, cy = e.clientY;
      if (cx < r.left || cx > r.right || cy < r.top || cy > r.bottom) return; // klik nije bio na ovom dugmetu
      if (btn === e.target || btn.contains(e.target)) return; // klik je stigao do dugmeta - sve OK
      const lines = [
        'Dugme: ' + w.label + ' (' + w.sel + ')',
        'Vrijeme: ' + new Date().toLocaleString(),
        'Klik na (' + cx + ',' + cy + ') je stigao do: ' + _klikDijagOpis(e.target),
        'Umjesto do samog dugmeta: ' + _klikDijagOpis(btn),
      ];
      _debugUpsert('klik-blokada-' + w.sel.replace(/\W/g, ''), 'Dugme ne reaguje na dodir — ' + w.label, lines.join('\n'), 'zabilježeno');
      try { console.warn('[klik-dijagnoza] ' + lines.join(' | ')); } catch(err) {}
    });
  }, true);
}
try { _klikDijagInstall(); } catch(e) {}

const _MAP_LOAD_DIAG_KEY = 'tvlake_map_startup_diag_v1';
let _mapLoadDiag = null;
try { _mapLoadDiag = JSON.parse(localStorage.getItem(_MAP_LOAD_DIAG_KEY) || 'null'); } catch(e) {}
function _mapLoadDiagSave() {
  try { localStorage.setItem(_MAP_LOAD_DIAG_KEY, JSON.stringify(_mapLoadDiag)); } catch(e) {}
  try { _debugUpsert('map-startup', 'Učitavanje offline karte', _mapLoadDiagText(), _mapLoadDiag?.state); } catch(e) {}
  try { if (typeof _loadmapRenderStartupDiag === 'function') _loadmapRenderStartupDiag(); } catch(e) {}
}
function _mapLoadDiagStart(name) {
  _mapLoadDiag = { name:name || 'nepoznata karta', startedAt:Date.now(), perf0:performance.now(), state:'u toku', steps:[] };
  _mapLoadDiagStep('indikator prikazan', 'startup čeka offline kartu');
}
function _mapLoadDiagName(name) {
  if (_mapLoadDiag && name) { _mapLoadDiag.name = name; _mapLoadDiagSave(); }
}
function _mapLoadDiagStep(label, detail) {
  if (!_mapLoadDiag) return;
  const elapsed = Math.max(0, Math.round(performance.now() - (_mapLoadDiag.perf0 || 0)));
  _mapLoadDiag.steps.push({ ms:elapsed, label:String(label || ''), detail:String(detail || '') });
  if (_mapLoadDiag.steps.length > 14) _mapLoadDiag.steps.shift();
  _mapLoadDiagSave();
}
function _mapLoadDiagFinish(state) {
  if (!_mapLoadDiag) return;
  _mapLoadDiag.state = state || 'završeno';
  _mapLoadDiag.finishedAt = Date.now();
  _mapLoadDiagSave();
  // Brz i potpuno uspješan startup više nije aktivan problem. Ne vraćaj ga u
  // centralni DEBUG pri svakom urednom ulasku; ponovo se deponuje samo ako
  // traje >1.5 s ili neki korak prijavi grešku/neuspjeh.
  const sporo = performance.now() - (_mapLoadDiag.perf0 || 0) > 1500;
  const imaProblem = (_mapLoadDiag.steps || []).some(s => /greška|nije uspio|neuspjeh/i.test((s.label || '') + ' ' + (s.detail || '')));
  if (_mapLoadDiag.state === 'karta prikazana' && !sporo && !imaProblem) _debugRemove('map-startup');
}
function _mapLoadDiagText() {
  if (!_mapLoadDiag) return '';
  const when = _mapLoadDiag.startedAt ? new Date(_mapLoadDiag.startedAt).toLocaleString() : '—';
  const rows = ['Karta: ' + _mapLoadDiag.name, 'Početak: ' + when + ' · stanje: ' + (_mapLoadDiag.state || 'u toku')];
  (_mapLoadDiag.steps || []).forEach(s => rows.push('+' + s.ms + ' ms  ' + s.label + (s.detail ? ' — ' + s.detail : '')));
  return rows.join('\n');
}
async function _mapLoadDiagCopy(event) {
  if (event) { event.preventDefault(); event.stopPropagation(); }
  const txt = _mapLoadDiagText();
  if (!txt) return;
  try {
    if (navigator.clipboard?.writeText) await navigator.clipboard.writeText(txt);
    else { const ta=document.createElement('textarea'); ta.value=txt; ta.style.cssText='position:fixed;left:-9999px'; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); ta.remove(); }
    showToast('📋 Debug učitavanja kopiran');
  } catch(e) { showToast('⚠ Kopiranje nije uspjelo'); }
}
function _mapRestoreIndicatorShow(name) {
  _mapRestoreIndicatorShownAt = performance.now();
  _mapLoadDiagStart(name);
  const el = document.getElementById('map-restore-indicator');
  if (el) el.classList.remove('show');
  clearTimeout(_mapRestoreIndicatorTimer);
  _mapRestoreIndicatorTimer = null;
}
function _mapRestoreIndicatorHide() {
  clearTimeout(_mapRestoreIndicatorTimer);
  _mapRestoreIndicatorTimer = null;
  const el = document.getElementById('map-restore-indicator');
  if (el) el.classList.remove('show');
}

// Razlikuj stvarno ponovno učitavanje dokumenta od običnog povratka iz
// pozadine. SQLite worker/OPFS veza ne može preživjeti novi WebView dokument,
// pa je ovaj podatak presudan kad se na telefonu opet pojavi "Učitavam kartu".
function _appLifecycleDebug(eventName, persisted) {
  let broj = 1;
  try { broj = Number(sessionStorage.getItem('tvlake_page_load_count') || 0) + (eventName === 'load' ? 1 : 0); if (eventName === 'load') sessionStorage.setItem('tvlake_page_load_count', String(broj)); } catch(e) {}
  let nav = 'nepoznato';
  try { nav = performance.getEntriesByType?.('navigation')?.[0]?.type || nav; } catch(e) {}
  const txt = [
    'Događaj: ' + eventName,
    'Učitavanja u ovoj app sesiji: ' + broj,
    'Navigation tip: ' + nav,
    'Page persisted/BFCache: ' + (persisted ? 'DA' : 'NE'),
    'Vidljivost: ' + (document.visibilityState || 'nepoznato'),
    // Ručno, ne toLocaleString: prvi Intl poziv učitava podatke o lokalu, a ovo
    // se izvršava na SVAKOM pokretanju (izmjereno 33–86 ms uz CPU 4×, v1.9.3).
    'Vrijeme: ' + (d => [d.getDate(), d.getMonth() + 1, d.getFullYear()].join('.') + '. ' +
      [d.getHours(), d.getMinutes(), d.getSeconds()].map(x => String(x).padStart(2, '0')).join(':'))(new Date())
  ].join('\n');
  _debugUpsert('app-lifecycle', 'Zašto se karta ponovo učitava', txt,
    broj > 1 && eventName === 'load' ? 'ponovno učitan dokument' : 'informacija');
}
_appLifecycleDebug('load', false);
window.addEventListener('pageshow', e => { if (e.persisted) _appLifecycleDebug('pageshow', true); });
window.addEventListener('pagehide', e => _appLifecycleDebug('pagehide', !!e.persisted));
// Vrati zadnju kartu ili defaultuj na Topo
(function _restoreLastMap() {
  let restoredKey = '⛰ Topo';
  try {
    const saved = JSON.parse(localStorage.getItem('tvlake_last_map'));
    if (saved?.type === 'none') return;
    if (saved?.type === 'sqlite') {
      _mapRestoreIndicatorShow(saved.sqlId);
      // Ne ostavljaj sivu kartu 10–20 s dok se veliki OPFS/SQLite fajl otvara.
      // Topo radi online ili iz SW cache-a; worker je automatski zamijeni
      // SQLite slojem tek kada je baza spremna.
      TL[restoredKey].addTo(map);
      return;
    }
    if (saved?.type === 'tl' && saved.key === '_nagib') {
      restoredKey = '⛰ Topo';
      setTimeout(() => {
        let stillSelected=false;try{const latest=JSON.parse(localStorage.getItem('tvlake_last_map'));stillSelected=latest?.type==='tl'&&latest.key==='_nagib';}catch(e){}
        if (stillSelected && _OVL.slope && !map.hasLayer(_OVL.slope)) _OVL.slope.addTo(map);
      }, 500);
    } else if (saved?.type === 'tl' && saved.key === '_granice') restoredKey = '⛰ Topo';
    else if (saved?.type === 'tl' && TL[saved.key]) restoredKey = saved.key;
  } catch(e) {}
  TL[restoredKey].addTo(map);
  const iconSvg = {
    '⛰ Topo':    '<svg class="ic"><use href="#ic-podloga"/></svg>',
    '🛰 Satelit': '<svg class="ic"><use href="#ic-satelit"/></svg>',
    '🗺 Karta':   '<svg class="ic"><use href="#ic-karta"/></svg>',
    '📡 Google':  '<svg class="ic"><use href="#ic-globus"/></svg>',
    '🌍 Sentinel':'<svg class="ic"><use href="#ic-satelit"/></svg>'
  };
  // btn may not exist yet at this point — setLayer later handles it; update after DOM ready.
  // Koristi innerHTML (SVG), ne textContent — od v3.84.0 ikonica dugmeta je SVG element,
  // textContent bi ga izbrisao i vratio prazan/pogresan prikaz (isti bug kao ispod).
  setTimeout(() => {
    const btn = document.getElementById('layer-switch-btn');
    if (btn) btn.innerHTML = iconSvg[restoredKey] || '<svg class="ic"><use href="#ic-karta"/></svg>';
  }, 500);
})();
// Zoom i layer kontrole su sada vlastiti HTML panel (#map-ctrl-bar), ne Leaflet kontrole

// ── Omiljene karte — state & funkcije ───────────────────────────────────────
const _MAPFAV_KEY  = 'tvlake_map_favs';
const _LASTMAP_KEY = 'tvlake_last_map';
let _mapFavs = [];

function _saveLastMap(type, key, sqlId) {
  try { const sl=type==='sqlite'&&typeof _sqlLayers!=='undefined'?_sqlLayers.find(l=>l.name===sqlId):null;localStorage.setItem(_LASTMAP_KEY, JSON.stringify({ type, key:key||null, sqlId:sqlId||null, ...(sl?.opfs?{opfsName:sl.opfsName}:{}) , ...(sl?.meta?._nativeId?{nativeId:sl.meta._nativeId}:{}) })); } catch(e) {}
}

function _mapFavLoad() {
  try { _mapFavs = JSON.parse(localStorage.getItem(_MAPFAV_KEY) || '[]'); } catch(e) { _mapFavs = []; }
}
function _mapFavSave() {
  try { localStorage.setItem(_MAPFAV_KEY, JSON.stringify(_mapFavs)); } catch(e) {}
}

function _activeLayerKey() {
  // SQLite ekskluzivni prikaz
  const si = (typeof _sqlLayers !== 'undefined') ? _sqlLayers.findIndex(sl => sl.visible && map.hasLayer(sl.layer)) : -1;
  if (si >= 0) return '_sqlite_' + si;
  // Topo + Nagib
  if (map.hasLayer(TL['⛰ Topo']) && _OVL.slope && map.hasLayer(_OVL.slope)) return '_nagib';
  // Topo + Granice
  const gl = (typeof _geojsonLayer !== 'undefined') ? _geojsonLayer : null;
  if (map.hasLayer(TL['⛰ Topo']) && gl && map.hasLayer(gl)) return '_granice';
  // Normalni tile sloj
  for (const [key, layer] of Object.entries(TL)) {
    if (map.hasLayer(layer)) return key;
  }
  return null;
}

// ── Layer switcher sheet ─────────────────────────────────────────────────────
function _lsRenderSqlite() {
  if (typeof MapCatalog !== 'undefined') { MapCatalog.renderOffline(); return; }
  const grid = document.getElementById('ls-sqlite-in-grid');
  if (!grid) return;
  // Karte sačuvane na uređaju koje se nisu učitale pri pokretanju. Bez ovoga je
  // mreža bila POTPUNO PRAZNA — korisnik ima kartu na telefonu, a nema je gdje
  // ni vidjeti ni aktivirati, niti ijedan trag da postoji.
  const pale = (typeof _sqlRestoreFailed !== 'undefined' ? _sqlRestoreFailed : [])
    .filter(f => !_sqlLayers.some(sl => sl.name === f.name));
  const paleHtml = pale.map(f => `<div style="grid-column:1/-1;display:flex;align-items:center;gap:8px;
      background:#2a1616;border:1px solid #7f1d1d;border-radius:8px;padding:8px 10px;">
      <span style="flex:1;min-width:0;font-size:11px;color:#fca5a5;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">
        ${f.deferred ? '🗺' : '⚠'} ${_escHtml(f.name)} — ${f.deferred ? 'sačuvana na uređaju' : 'nije učitana'}</span>
      <button onclick="event.stopPropagation();sqlmapRetryOne('${_jsAttr(f.name)}')"
        style="flex-shrink:0;background:#1e3a5f;border:1px solid #2563eb;color:#93c5fd;border-radius:6px;
        padding:5px 10px;font-size:11px;font-weight:600;cursor:pointer;">${f.deferred ? 'Otvori' : 'Pokušaj ponovo'}</button>
    </div>`).join('');
  if (!_sqlLayers.length) { grid.innerHTML = paleHtml; return; }
  const active = _activeLayerKey();
  grid.innerHTML = paleHtml + _sqlLayers.map((sl, i) => {
    const short = sl.name.length > 13 ? sl.name.slice(0, 12) + '…' : sl.name;
    return `<div style="position:relative;">
      <button class="layer-opt" id="ls-sql-btn-${i}" style="width:100%;padding:10px 6px 12px;"
        onclick="setLayerSqlite(${i})">
        <span class="layer-ico"><svg class="ic"><use href="#ic-arhiva"/></svg></span>
        <span style="font-size:10px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:100%;display:block;">${short}</span>
      </button>
      <button onclick="event.stopPropagation();sqlmapConfirmDelete(${i})"
        style="position:absolute;top:4px;right:4px;background:rgba(15,23,42,0.85);border:1px solid #475569;color:#64748b;border-radius:4px;font-size:10px;line-height:1.5;padding:0 5px;cursor:pointer;"
        title="Trajno izbriši kartu"><svg class="ic"><use href="#ic-zatvori"/></svg></button>
    </div>`;
  }).join('');
}

function _openLayerSheet() {
  // v1.5.0: #oznake-panel i #layer-sheet se nikad nisu zatvarali jedan drugog —
  // ako je Oznake panel ostao otvoren (npr. korisnik ga otvorio pa se prebacio
  // na Slojeve karte bez X-a), oba su se prikazivala ISTOVREMENO, jedno preko
  // drugog (potvrđeno screenshot-om s terena). Zatvori ga prije otvaranja ovog.
  if (typeof closeOznakePanel === 'function') closeOznakePanel();
  document.getElementById('layer-sheet-bg').style.display = 'block';
  document.getElementById('layer-sheet').style.display   = 'block';
  let lastTab='karte';try { lastTab=localStorage.getItem('tvlake_layer_sheet_tab')||lastTab; } catch(e) {}
  _lsTab(lastTab);
  ['elev','slope','nv','ekspo','kont'].forEach(id => {
    const cb = document.getElementById('inst-' + id + '-cb');
    if (cb) cb.checked = !!_ovlState[id];
  });
  _instUpdateStats();
  // Granice odjela dugme — prikaži samo ako ima učitanih granica
  const grRow = document.getElementById('ls-granice-row');
  if (grRow) grRow.style.display = (typeof _geojsonLayer !== 'undefined' && _geojsonLayer) ? 'block' : 'none';
  // Renderuj SQLite karte u grid, pa postavi active klasu
  _lsRenderSqlite();
  const active = _activeLayerKey();
  document.querySelectorAll('.layer-opt').forEach(el => el.classList.remove('active'));
  if (active && active.startsWith('_sqlite_')) {
    const idx = parseInt(active.replace('_sqlite_', ''), 10);
    const sqlBtn = document.getElementById('ls-sql-btn-' + idx);
    if (sqlBtn) sqlBtn.classList.add('active');
  } else {
    const map2id = {'⛰ Topo':'lo-topo','🛰 Satelit':'lo-sat','🗺 Karta':'lo-osm','📡 Google':'lo-google','🌍 Sentinel':'lo-eox','_nagib':'lo-nagib','_granice':'lo-granice'};
    const el = document.getElementById(map2id[active] || '');
    if (el) el.classList.add('active');
  }
  _lsRenderGranice();
  _lsRenderCache();
}

// Prikaz zauzeća memorije online karata (keširane pločice) + brisanje — u modalu karte
async function _lsRenderCache() {
  const el = document.getElementById('ls-cache-info');
  // Bez Cache API-ja kutija ostaje skrivena — ranije je trajno pisalo "💾 …".
  if (!el || !('caches' in window)) return;
  let count = 0;
  try { const c = await caches.open(TILE_CACHE_NAME); count = (await c.keys()).length; } catch(e) {}
  let mbTxt = '';
  if (navigator.storage && navigator.storage.estimate) {
    try { const est = await navigator.storage.estimate(); mbTxt = ` · ≈ ${Math.round((est.usage || 0) / 1048576)} MB ukupno`; } catch(e) {}
  }
  el.innerHTML = `
    <div class="lsc-row"><span>💾 Sačuvano za offline: <b>${count.toLocaleString()}</b> pločica${mbTxt}</span>
      <button type="button" onclick="showCacheMgr()">Upravljaj</button></div>
    <button type="button" class="lsc-teren" onclick="nvDemPreuzmiUi()"><svg class="ic"><use href="#ic-uvezi"/></svg> Preuzmi teren za offline (N.V., nagib, konture)</button>`;
  const box = document.getElementById('ls-cache-box');
  if (box) box.hidden = false;
  _lsFillCardBadges();
}

// ── Upravljanje offline podacima po karti (AlpineQuest stil) ──────────────────
// Basemape dijele jedan keš (tvlake-tiles-v1) pa se razdvajaju po URL hostu;
// DEM/teren slojevi imaju svoje kešove pa su cijeli-keš redovi.
const _CMGR_ROWS = [
  { id: 'topo',  ico: '⛰',  name: 'Topo',            sub: 'OpenTopoMap',      cache: TILE_CACHE_NAME, host: 'tile.opentopomap.org' },
  { id: 'sat',   ico: '🛰',  name: 'Satelit',         sub: 'ArcGIS Imagery',   cache: TILE_CACHE_NAME, host: 'World_Imagery' },
  { id: 'osm',   ico: '🗺',  name: 'Karta',           sub: 'OpenStreetMap',    cache: TILE_CACHE_NAME, host: 'tile.openstreetmap.org' },
  { id: 'goog',  ico: '📡',  name: 'Google satelit',  sub: 'Google',           cache: TILE_CACHE_NAME, host: '.google.com/vt' },
  // v3.103.0: EOX Sentinel-2 (true color) zamijenjen ESA WorldCover-om (pokrivenost
  // zemljišta) — vidi TL['🌍 Sentinel'] niže. Isti dugme/slot, drugačiji izvor pa
  // i drugačiji (zaseban, ne dijeljeni) keš.
  { id: 'wcover', ico: '🌍',  name: 'Pokrivenost zemljišta', sub: 'ESA WorldCover', cache: _WC_CACHE },
  { id: 'elev',  ico: '🏔',  name: 'Sjenčenje terena', sub: 'Hillshade',       cache: 'tvlake-elev-v1' },
  { id: 'slope', ico: '📐',  name: 'Nagib terena',    sub: 'Shaded relief',    cache: 'tvlake-slope-v1' },
  { id: 'terr',  ico: '🗻',  name: 'Teren (DEM)',     sub: 'Visinski podaci · N.V. offline',  cache: 'tvlake-terr-v1' },
  { id: 'nv',    ico: '🏷',  name: 'Nadmorske visine', sub: 'Open-Meteo keš',  cache: 'tvlake-nv-v1' },
];
let _cmgrData = null;   // zadnji scan: {id: {count, bytes}}

// Procjena veličine bucketa: broj unosa × prosjek uzorka (do `sampleN` pločica).
async function _cmgrSampleSize(cache, keys, sampleN) {
  if (!keys.length) return 0;
  const step = Math.max(1, Math.floor(keys.length / sampleN));
  let tot = 0, n = 0;
  for (let i = 0; i < keys.length && n < sampleN; i += step) {
    try {
      const r = await cache.match(keys[i]);
      if (r) { tot += (await r.blob()).size; n++; }
    } catch(e) {}
  }
  return n ? Math.round((tot / n) * keys.length) : 0;
}

async function _cacheMgrScan() {
  const out = {};
  if (!('caches' in window)) return out;
  // Basemap bucketi iz zajedničkog keša
  try {
    const c = await caches.open(TILE_CACHE_NAME);
    const keys = await c.keys();
    for (const row of _CMGR_ROWS.filter(r => r.host)) {
      const bk = keys.filter(k => k.url.includes(row.host));
      out[row.id] = { count: bk.length, bytes: await _cmgrSampleSize(c, bk, 25) };
    }
  } catch(e) {}
  // Cijeli kešovi (DEM/teren/visine)
  for (const row of _CMGR_ROWS.filter(r => !r.host)) {
    try {
      const c = await caches.open(row.cache);
      const keys = await c.keys();
      out[row.id] = { count: keys.length, bytes: await _cmgrSampleSize(c, keys, 25) };
    } catch(e) { out[row.id] = { count: 0, bytes: 0 }; }
  }
  _cmgrData = out;
  return out;
}

function _cmgrFmtMb(bytes) {
  if (!bytes) return '0 MB';
  const mb = bytes / 1048576;
  return mb >= 10 ? Math.round(mb) + ' MB' : (mb >= 0.1 ? mb.toFixed(1) + ' MB' : '< 0.1 MB');
}

function showCacheMgr() {
  const m = document.getElementById('cachemgr-modal');
  if (!m) return;
  m.style.display = 'flex';
  _cacheMgrRender(true);
}
function closeCacheMgr() {
  const m = document.getElementById('cachemgr-modal');
  if (m) m.style.display = 'none';
}

async function _cacheMgrRender(rescan) {
  const body = document.getElementById('cachemgr-body');
  if (!body) return;
  if (rescan) {
    body.innerHTML = '<div style="text-align:center;color:#64748b;font-size:12px;padding:18px 0;">⏳ Računam zauzeće po karti...</div>';
    await _cacheMgrScan();
  }
  const d = _cmgrData || {};
  let totBytes = 0, totCount = 0;
  const rows = _CMGR_ROWS.map(row => {
    const e = d[row.id] || { count: 0, bytes: 0 };
    totBytes += e.bytes; totCount += e.count;
    const empty = !e.count;
    return `<div style="display:flex;align-items:center;gap:10px;background:${empty ? '#0d1526' : '#16213e'};border:1px solid ${empty ? '#152036' : '#1e3a5f'};border-radius:11px;padding:10px 12px;margin-bottom:7px;${empty ? 'opacity:0.55;' : ''}">
      <div style="font-size:20px;flex-shrink:0;width:26px;text-align:center;">${row.ico}</div>
      <div style="flex:1;min-width:0;">
        <div style="font-size:13px;font-weight:600;color:#e2e8f0;">${row.name}</div>
        <div style="font-size:10.5px;color:#64748b;">${row.sub} · ${e.count.toLocaleString('bs')} pločica</div>
      </div>
      <div style="flex-shrink:0;font-size:13px;font-weight:700;color:${empty ? '#475569' : '#4ade80'};font-variant-numeric:tabular-nums;">${_cmgrFmtMb(e.bytes)}</div>
      <button onclick="_cacheMgrDelete('${row.id}')" ${empty ? 'disabled' : ''}
        style="flex-shrink:0;background:${empty ? '#0d1526' : 'rgba(220,38,38,0.10)'};border:1px solid ${empty ? '#152036' : '#7f1d1d'};border-radius:8px;color:${empty ? '#334155' : '#f87171'};font-size:13px;padding:7px 10px;cursor:${empty ? 'default' : 'pointer'};"><svg class="ic"><use href="#ic-obrisi"/></svg></button>
    </div>`;
  }).join('');
  let estTxt = '';
  try { const est = await navigator.storage.estimate(); estTxt = ` · aplikacija ukupno ≈ ${Math.round((est.usage || 0) / 1048576)} MB`; } catch(e) {}
  body.innerHTML = `
    ${rows}
    <button onclick="nvDemPreuzmiUi()" style="width:100%;margin:2px 0 8px;padding:9px;background:#14233c;border:1px solid #1e3a5f;border-radius:9px;color:#fcd34d;font-size:12px;font-weight:600;cursor:pointer;"><svg class="ic"><use href="#ic-uvezi"/></svg> Preuzmi teren za područje (N.V., nagib, konture)</button>
    <div style="font-size:11px;color:#64748b;margin:4px 2px 10px;">Ukupno pločica: <b style="color:#94a3b8">${totCount.toLocaleString('bs')}</b> · ≈ ${_cmgrFmtMb(totBytes)}${estTxt}</div>
    <div style="display:flex;gap:7px;">
      <button onclick="closeCacheMgr();openLoadMapScreen()" style="flex:1;padding:9px;background:#14233c;border:1px solid #1e3a5f;border-radius:9px;color:#7dd3fc;font-size:12px;font-weight:600;cursor:pointer;"><svg class="ic"><use href="#ic-karta"/></svg> Offline karte (fajlovi)</button>
      <button onclick="_cacheMgrDeleteAll()" style="flex:1;padding:9px;background:rgba(220,38,38,0.10);border:1px solid #7f1d1d;border-radius:9px;color:#f87171;font-size:12px;font-weight:600;cursor:pointer;"><svg class="ic"><use href="#ic-obrisi"/></svg> Obriši sve karte</button>
    </div>
    <div style="font-size:10px;color:#475569;margin-top:8px;">Brisanje uklanja offline kopije pločica — karta i dalje radi online i ponovo ih čuva pri pregledu. Offline SQLite karte (fajlovi) upravljaju se zasebno.</div>`;
}

async function _cacheMgrDelete(id) {
  const row = _CMGR_ROWS.find(r => r.id === id);
  if (!row) return;
  const e = (_cmgrData || {})[id] || { count: 0 };
  const ok = await _dlgConfirm(`Obrisati offline pločice za "${row.name}" (${e.count.toLocaleString('bs')} pločica, ${_cmgrFmtMb(e.bytes)})?`, { danger: true });
  if (!ok) return;
  try {
    if (row.host) {
      const c = await caches.open(row.cache);
      const keys = await c.keys();
      for (const k of keys) { if (k.url.includes(row.host)) await c.delete(k); }
    } else {
      await caches.delete(row.cache);
    }
    showToast(`🗑 ${row.name}: offline pločice obrisane`);
  } catch(err) {
    showToast('⚠ Brisanje nije uspjelo: ' + (err.message || 'nepoznato'));
  }
  _cacheMgrRender(true);
  _lsRenderCache();
}

async function _cacheMgrDeleteAll() {
  const ok = await _dlgConfirm('Obrisati SVE offline pločice svih karata (topo, satelit, google, teren)?', { danger: true });
  if (!ok) return;
  try {
    const names = await caches.keys();
    for (const n of names) { if (/^tvlake-(tiles|elev|slope|terr|nv|effis|wcover)/.test(n)) await caches.delete(n); }
    showToast('🗑 Sve offline pločice obrisane');
  } catch(err) {
    showToast('⚠ Brisanje nije uspjelo: ' + (err.message || 'nepoznato'));
  }
  _cacheMgrRender(true);
  _lsRenderCache();
}

// Mali "≈MB" badge na basemap karticama u layer-sheetu (async, lagano — samo brojevi
// pločica bez uzorkovanja veličine ako scan još ne postoji).
async function _lsFillCardBadges() {
  if (!('caches' in window)) return;
  const map2row = { 'lo-topo': 'topo', 'lo-sat': 'sat', 'lo-osm': 'osm', 'lo-google': 'goog', 'lo-eox': 'wcover' };
  let d = _cmgrData;
  if (!d) { try { d = await _cacheMgrScan(); } catch(e) { return; } }
  for (const [btnId, rowId] of Object.entries(map2row)) {
    const btn = document.getElementById(btnId);
    if (!btn) continue;
    let badge = btn.querySelector('.lopt-mb');
    const e = d[rowId];
    if (!e || !e.count) { if (badge) badge.remove(); continue; }
    if (!badge) {
      badge = document.createElement('span');
      badge.className = 'lopt-mb';
      btn.appendChild(badge);
    }
    badge.textContent = _cmgrFmtMb(e.bytes);
  }
}

function closeLayerSheet() {
  const bg = document.getElementById('layer-sheet-bg');
  const sh = document.getElementById('layer-sheet');
  if (bg) bg.style.display = 'none';
  if (sh) sh.style.display = 'none';
}

// Aktivira tile sloj — isključuje SQLite i opciono granice
function setLayer(key) {
  // Ukloni sve SQLite slojeve s mape (postaju nevidljivi)
  if (typeof _sqlLayers !== 'undefined') {
    _sqlLayers.forEach(sl => { if (map.hasLayer(sl.layer)) { map.removeLayer(sl.layer); sl.visible = false; } });
  }
  // Ukloni sve tile slojeve
  Object.values(TL).forEach(l => { if (map.hasLayer(l)) map.removeLayer(l); });

  if (key === '_nagib') {
    if(typeof ProjectTerrain!=='undefined')ProjectTerrain.toggle('slope',false);
    TL['⛰ Topo'].addTo(map);
    if (!map.hasLayer(_OVL.slope)) _OVL.slope.addTo(map);
    const btn = document.getElementById('layer-switch-btn');
    if (btn) btn.innerHTML = '<svg class="ic"><use href="#ic-uglomjer"/></svg>';
    _saveLastMap('tl', '_nagib');
    closeLayerSheet();
    _lsRenderSqlite();
    return;
  }
  // Remove slope overlay if switching away from _nagib
  if (_OVL.slope && map.hasLayer(_OVL.slope) && !_ovlState.slope) map.removeLayer(_OVL.slope);

  if (key === '_granice') {
    // Topo + granice odjela zajedno
    TL['⛰ Topo'].addTo(map);
    if (typeof _geojsonLayer !== 'undefined' && _geojsonLayer && !map.hasLayer(_geojsonLayer)) {
      _geojsonLayer.addTo(map);
    }
    const btn = document.getElementById('layer-switch-btn');
    if (btn) btn.innerHTML = '<svg class="ic"><use href="#ic-slojevi"/></svg>';
    _geojsonVisible=true;localStorage.setItem('tvlake_granice_visible','1');
    _saveLastMap('tl', '_granice');
  } else {
    _geojsonVisible=false;localStorage.setItem('tvlake_granice_visible','0');
    // Sakrij granice ako su bile aktivne
    if (typeof _geojsonLayer !== 'undefined' && _geojsonLayer && map.hasLayer(_geojsonLayer)) {
      map.removeLayer(_geojsonLayer);
    }
    if (TL[key]) TL[key].addTo(map);
    const iconSvg = {
    '⛰ Topo':    '<svg class="ic"><use href="#ic-podloga"/></svg>',
    '🛰 Satelit': '<svg class="ic"><use href="#ic-satelit"/></svg>',
    '🗺 Karta':   '<svg class="ic"><use href="#ic-karta"/></svg>',
    '📡 Google':  '<svg class="ic"><use href="#ic-globus"/></svg>',
    '🌍 Sentinel':'<svg class="ic"><use href="#ic-satelit"/></svg>'
  };
    // BUG (v3.84.0-v3.90.0): ovdje je stajalo btn.textContent = icons[key], sto je
    // BRISALO SVG ikonicu i vracalo je na emoji cim korisnik izabere Topo/Satelit/
    // Karta/Google — jer se ikonica citala iz mape (icons[key]), ne iz literalnog
    // teksta, pa je ranija automatska provjera (koja je hvatala samo doslovne
    // '...' stringove) ovo mjesto preskocila. innerHTML + SVG referenca popravlja.
    const btn = document.getElementById('layer-switch-btn');
    if (btn) btn.innerHTML = iconSvg[key] || '<svg class="ic"><use href="#ic-karta"/></svg>';
    _saveLastMap('tl', key);
  }
  closeLayerSheet();
  _lsRenderSqlite();
}

// Aktivira SQLite kartu kao ekskluzivni prikaz — bez tile pozadine
function setLayerSqlite(i) {
  const sl = _sqlLayers[i];
  if (!sl) return;
  // Ukloni sve tile slojeve
  Object.values(TL).forEach(l => { if (map.hasLayer(l)) map.removeLayer(l); });
  // Sakrij granice
  if (typeof _geojsonLayer !== 'undefined' && _geojsonLayer && map.hasLayer(_geojsonLayer)) {
    map.removeLayer(_geojsonLayer);
  }
  if(typeof _geojsonVisible!=='undefined')_geojsonVisible=false;
  try { localStorage.setItem('tvlake_granice_visible','0'); } catch(e) {}
  // Prikaži samo ovu SQLite kartu, sakrij ostale
  _sqlLayers.forEach((s, j) => {
    if (j === i) { s.visible = true; if (!map.hasLayer(s.layer)) s.layer.addTo(map); }
    else         { s.visible = false; if (map.hasLayer(s.layer)) map.removeLayer(s.layer); }
  });
  _sqlmapMetaAutoZoom(sl.meta,sl.name);
  _saveLastMap('sqlite', null, sl.name);
  const btn = document.getElementById('layer-switch-btn');
  if (btn) btn.innerHTML = '<svg class="ic"><use href="#ic-arhiva"/></svg>';
  closeLayerSheet();
  _lsRenderSqlite();
}

// Pretvori tile URL template u konkretan URL za dati tile
function _tileThumbUrl(tpl, _unused, x, y, arcgis) {
  const z = 14;
  if (arcgis) return tpl.replace('{z}',z).replace('{y}',y).replace('{x}',x);
  return tpl.replace('{s}','a').replace('{z}',z).replace('{x}',x).replace('{y}',y);
}

function _mapFavThumbHtml(fav) {
  if(fav.type!=='sqlite'&&!fav.tileUrl)return '<div class="mfav-thumb-placeholder">🗺</div>';
  if (fav.type === 'sqlite') {
    const data=_loadmapThumbData(fav.sqliteId);
    return `<img class="mfav-thumb" data-map-preview="${_escHtml(fav.sqliteId)}" loading="lazy" decoding="async" src="${_escHtml(data||'static/img/map-previews/local.svg')}" alt="${_escHtml(data?'Isječak karte '+fav.name:'Ilustracija lokalne karte')}">`;
  }
  const c = map.getCenter();
  // Prikaži 2×2 grid tile-a za realističniji preview
  const z = 14;
  const x0 = Math.floor((c.lng + 180) / 360 * (1 << z));
  const rawY = Math.log(Math.tan(c.lat * Math.PI/180) + 1/Math.cos(c.lat * Math.PI/180)) / Math.PI;
  const y0 = Math.floor((1 - rawY) / 2 * (1 << z));
  const urls = [
    _tileThumbUrl(fav.tileUrl, 0, x0,   y0,   fav.arcgis),
    _tileThumbUrl(fav.tileUrl, 0, x0+1, y0,   fav.arcgis),
    _tileThumbUrl(fav.tileUrl, 0, x0,   y0+1, fav.arcgis),
    _tileThumbUrl(fav.tileUrl, 0, x0+1, y0+1, fav.arcgis),
  ];
  const imgs = urls.map(u =>
    `<img src="${u}" loading="lazy" style="width:50%;height:50%;object-fit:cover;display:block;float:left;" onerror="this.style.opacity='0'">`
  ).join('');
  return `<div style="width:100%;height:100%;overflow:hidden;">${imgs}</div>`;
}

function _mapFavRender() {
  if(typeof MapCatalog!=='undefined')return MapCatalog.renderFavorites();
  const el = document.getElementById('mapfav-grid');
  if (!el) return;
  const activeKey = _activeLayerKey();
  const activeSqlId = _sqlLayers.find(sl => sl.visible)?.name || null;

  const cards = _mapFavs.map((fav, i) => {
    const isActive = fav.type === 'tl' ? fav.tlKey === activeKey : fav.sqliteId === activeSqlId;
    return `<div class="mfav-card${isActive?' active':''}" onclick="mapFavSwitch(${i})">
      ${_mapFavThumbHtml(fav)}
      <div class="mfav-label">${_escHtml(fav.name)}</div>
      <button class="mfav-edit-btn" onclick="event.stopPropagation();_mapFavMenu(${i})" title="Uredi">⋮</button>
    </div>`;
  }).join('');

  el.innerHTML = cards + `<div class="mfav-add-card" onclick="mapFavAddCurrent()">
    <span>＋</span>
    <span>Dodaj trenutnu kartu</span>
  </div>`;
}

async function _mapFavMenu(i) {
  const fav = _mapFavs[i];
  if (!fav) return;
  const a = await _dlgActions(fav.name, [
    { label: '✏ Preimenuj', danger: false },
    { label: '✕ Obriši', danger: true }
  ]);
  if (a === 0) mapFavRename(i);
  else if (a === 1) { _mapFavs.splice(i, 1); _mapFavSave(); _mapFavRender(); }
}

function openMapFavs() {
  _mapFavRender();
  document.getElementById('mapfav-modal').classList.add('open');
}
function closeMapFavs() {
  document.getElementById('mapfav-modal').classList.remove('open');
}

async function mapFavAddCurrent() {
  const activeKey = _activeLayerKey();
  let fav;
  if (activeKey && activeKey.startsWith('_sqlite_')) {
    const sqlActive = _sqlLayers.find(sl => sl.visible);
    if (!sqlActive) { showToast('Nema aktivne offline karte'); return; }
    const name = await _dlgPrompt('Naziv ove offline karte:', sqlActive.name, { title: 'Dodaj u omiljene' });
    if (!name) return;
    fav = { id: 'fav_'+Date.now(), name: name.trim(), type: 'sqlite', sqliteId: sqlActive.name };
  } else if (['_granice','_nagib'].includes(activeKey)) {
    const name = await _dlgPrompt('Naziv:', activeKey==='_nagib'?'Topo + Nagib terena':'Topo + Granice odjela', { title: 'Dodaj u omiljene' });
    if (!name) return;
    fav = { id: 'fav_'+Date.now(), name: name.trim(), type: 'tl', tlKey: activeKey, tileUrl: '', arcgis: false };
  } else if (activeKey && TL[activeKey]) {
    const layer = TL[activeKey];
    const tileUrl = layer._url || '';
    const arcgis = tileUrl.includes('arcgisonline') || tileUrl.includes('ArcGIS');
    const defaultName = activeKey.replace(/^[^\w]+/, '').trim();
    const name = await _dlgPrompt('Naziv ove karte:', defaultName, { title: 'Dodaj u omiljene' });
    if (!name) return;
    fav = { id: 'fav_'+Date.now(), name: name.trim(), type: 'tl', tlKey: activeKey, tileUrl, arcgis };
  } else {
    showToast('Nema aktivne karte za dodavanje'); return;
  }
  _mapFavs.push(fav);
  _mapFavSave();
  _mapFavRender();
  showToast('⭐ Karta dodana u omiljene: ' + fav.name);
}

function mapFavSwitch(i) {
  const fav = _mapFavs[i];
  if (!fav) return;
  if (fav.type === 'tl') {
    if (fav.tlKey === '_granice' || TL[fav.tlKey]) {
      setLayer(fav.tlKey);
    } else {
      showToast('Sloj nije dostupan: ' + fav.tlKey); return;
    }
    showToast('🗺 ' + fav.name);
  } else if (fav.type === 'sqlite') {
    const sl = _sqlLayers.find(s => s.name === fav.sqliteId);
    if (!sl) { showToast('Offline karta nije učitana: ' + fav.sqliteId); return; }
    _sqlLayers.forEach(s => { if (s.visible) { map.removeLayer(s.layer); s.visible = false; } });
    sl.layer.addTo(map); sl.visible = true;
    _sqlmapRenderLayers();
    _saveLastMap('sqlite', null, fav.sqliteId);
    showToast('🗄 ' + fav.name);
  }
  closeMapFavs();
}

async function mapFavRename(i) {
  const fav = _mapFavs[i];
  if (!fav) return;
  const name = await _dlgPrompt('Novi naziv:', fav.name, { title: 'Preimenuj kartu' });
  if (name?.trim()) { fav.name = name.trim(); _mapFavSave(); _mapFavRender(); }
}

function mapFavDel(i) {
  _mapFavs.splice(i, 1);
  _mapFavSave();
  _mapFavRender();
}

_mapFavLoad();
_loadPutevi();

// Prevent overlay and banner from passing events to Leaflet map
['ovl','rec-banner','draw-banner','manual-draw-panel','doz-gps-modal'].forEach(id => {
  const el = document.getElementById(id);
  if (el) {
    L.DomEvent.disableClickPropagation(el);
    L.DomEvent.disableScrollPropagation(el);
  }
});

// Guard: dblclick fires 2x click first — ignore last click when dblclick follows
let _dblClickGuard = false;

map.on('click', e => {
  // Klik na mapu dok je panel otvoren — vrati se na kartu
  if (_activeTab !== 'karta') { switchTab('karta'); return; }
  if(window.DepartmentReport?.isDrawing())return;
  if(typeof ProjectTerrain!=='undefined'&&ProjectTerrain.isDrawing())return;
  if(typeof ReferenceVlake!=='undefined'&&ReferenceVlake.isMarking())return;
  if(typeof VlakaDirection!=='undefined'&&VlakaDirection.isPicking())return;
  if(typeof VlakaLager!=='undefined'&&VlakaLager.isPicking())return;
  if (_msrOn) return; // izmjera preuzima klikove
  if (typeof _vsdOn !== 'undefined' && _vsdOn) return; // studio vlaka ima vlastiti handler (_vsdClick)
  if (_dblClickGuard) return; // suppress the 2nd click of a dblclick
  // Odabir odjela iz KML-a (doznaka) — mora prije svih alata; klik do samog
  // poligona često ne stigne jer ga gornji canvas pokupi (vidi _kmlHitTest).
  if (_dozKmlSelMode) {
    const kp = _kmlHitTest(e.latlng, true);
    if (kp) { _dozKmlSelToggle(kp); return; }
  }
  if (_tackaPlaceMode) {
    const nm = _tackaPlaceNm;
    _tackaExitPlaceMode();
    _createTacka(e.latlng.lat, e.latlng.lng, nm);
    return;
  }
  if (_guideOn) { _guideOnMapClick(e.latlng); return; }
  if (_dozDrawType !== null) { if (!_dozDrawEnabled) dozAddDrawPoint(e.latlng); return; }
  if (!_vpJustOpened) closeVlakaPopup();
  if (textToolOn) { openTextDialog(e.latlng.lat, e.latlng.lng, null); return; }
  if (activeTool === 'edit' || activeTool === 'delnode') return;
  if (activeTool === 'merge') return;
  if (activeTool === 'addline' && actI !== null) {
    const target = snapTarget || null;
    const la = target ? target.la : e.latlng.lat;
    const lo = target ? target.lo : e.latlng.lng;
    drawUndoStack.push(vlake[actI].pts.map(p=>({...p})));
    addPt(actI, la, lo, 0);
    if (target) { hideSnapRing(); snapTarget = null; }
    return;
  }
  if (activeTool === 'addpoint') {
    if (actI === null) { showToast('Odaberi vlaku u listi!'); return; }
    addPt(actI, e.latlng.lat, e.latlng.lng, 0);
    const v = vlake[actI];
    const ico = L.divIcon({className:'',iconSize:[10,10],iconAnchor:[5,5],
      html:`<div style="width:10px;height:10px;border-radius:50%;background:${v.color};border:2px solid #fff;box-shadow:0 0 4px rgba(0,0,0,0.5);"></div>`});
    const m = L.marker([e.latlng.lat,e.latlng.lng],{icon:ico}).addTo(map);
    m.bindTooltip(_escHtml(`${v.nm} P${v.pts.length}`),{opacity:0.9});
    v.wpts.push(m);
    showToast(`📍 Tačka dodana — ${v.nm} (${v.pts.length} uk.)`);
    return;
  }
  // Proximity fallback: find nearest vlaka if click missed polyline SVG hit area
  if (!recOn && activeTool !== 'edit' && activeTool !== 'delnode' && activeTool !== 'merge' && activeTool !== 'addline' && activeTool !== 'addpoint') {
    const HIT_PX = 22; // touch-friendly threshold in pixels
    const clickPx = map.latLngToContainerPoint(e.latlng);
    let bestI = -1, bestD = Infinity, bestKey = null;
    vlake.forEach((v, i) => {
      if (!v.poly || !map.hasLayer(v.poly) || v.pts.length < 2) return;
      for (let j = 0; j < v.pts.length - 1; j++) {
        const a = map.latLngToContainerPoint(L.latLng(v.pts[j].la, v.pts[j].lo));
        const b = map.latLngToContainerPoint(L.latLng(v.pts[j+1].la, v.pts[j+1].lo));
        const d = _distToSegPx(clickPx, a, b);
        if (d < bestD) { bestD = d; bestI = i; }
      }
    });
    for (const [key, v] of Object.entries(kolegeVlakeMap)) {
      if (!v.poly || !map.hasLayer(v.poly) || !v.pts) continue;
      for (let j=1;j<v.pts.length;j++) {
        const a=map.latLngToContainerPoint(L.latLng(v.pts[j-1].la,v.pts[j-1].lo));
        const b=map.latLngToContainerPoint(L.latLng(v.pts[j].la,v.pts[j].lo));
        const d=_distToSegPx(clickPx,a,b);
        if(d<bestD){bestD=d;bestKey=key;}
      }
    }
    // Sačuvana mjerenja se provjeravaju PRIJE vlaka jer su i na karti IZNAD
    // njih (pane 'tragMsrLines' 410 > 'vlakeLines' 400) — kad klik stigne
    // normalno, gornji sloj pobjeđuje, pa i fallback mora poštovati isti
    // redoslijed, inače bi mjerenje nacrtano preko vlake bilo neklikabilno
    // baš u slučaju zbog kojeg fallback i postoji. Vidi _msrHitTest.
    {
      const mm = _msrHitTest(e.latlng);
      if (mm) { _msrOpenPopupNa(mm, e.latlng); return; }
    }
    // Ruta "Vodi me" — ista zamka kao mjerenja (vidi _guideHitTest).
    if (_guideHitTest(e.latlng)) { _guideOpenPopupNa(e.latlng); return; }
    if (bestKey && bestD <= HIT_PX) { showKolegeVlakaInfo(bestKey,e.latlng); return; }
    if (bestI >= 0 && bestD <= HIT_PX) {
      selI(bestI);
      showVlakaPopup(bestI, e.latlng);
      return;
    }
    if(window.DepartmentReport?.openAt(e.latlng))return;
    // Uvezeni KML/SHP — isti razlog kao proximity fallback iznad: klik do sloja
    // najčešće uopšte ne stigne jer ga gornji canvas (vlake/tragovi) pokupi.
    // Vlake imaju prednost (provjerene su gore), pa tek onda uvezeni slojevi.
    if (_activeTab !== 'teren') {
      const kl = _kmlHitTest(e.latlng);
      if (kl) { _kmlOpenPopup(kl, e.latlng); return; }
    }
  }
  // Teren: tap na kartu → prikaži info o lokaciji
  if (_activeTab === 'teren') {
    _terenQueryPoint(e.latlng.lat, e.latlng.lng);
  }
  // NOTE: GPS recording (recOn) is handled entirely by onP() — never by map clicks
});

map.on('dblclick', e => {
  if (activeTool === 'addline') {
    e.originalEvent.preventDefault();
    // Zahtijeva min. 2 tačke — sprječava slučajni prekid dvostrukim tapom
    if (actI !== null && vlake[actI].pts.length < 2) return;
    _dblClickGuard = true;
    setTimeout(() => { _dblClickGuard = false; }, 300);
    // Lančano trasiranje: umjesto izlaska, sačuvaj i odmah počni sljedeću vlaku.
    if (_chainTraceOn) _traceFinishAndNext();
    else stopAddLine();
  }
});

map.on('mousemove', e => {
  if (!_gpsAlt || _userPannedAway) debouncedUpdElev(e.latlng.lat, e.latlng.lng, 300);
  if (activeTool === 'addline' && actI !== null) drawPreviewUpdate(e.latlng);
});

// Kad korisnik povuče mapu tokom snimanja → automatski oslobodi praćenje
map.on('dragstart', () => {
  if ((recOn && !recPaused) || _tragOn) _setFreeView(true);
  // Ručno pomjeranje karte znači da korisnik gleda NEKO DRUGO mjesto, ne
  // svoju GPS poziciju — N.V. treba pratiti centar karte (vidi komentar uz
  // _userPannedAway), ne ostati zaglavljena na GPS visini.
  _userPannedAway = true;
  _updCentarBtn();
});

// Ažuriraj N.V. i GPS distancu pri pomicanju karte (throttled za performanse)
let _moveRafPending = false;
map.on('move', () => {
  if (_moveRafPending) return;
  _moveRafPending = true;
  requestAnimationFrame(() => {
    _moveRafPending = false;
    _updMcdDist();
    const c = map.getCenter();
    updMGI(c.lat, c.lng);
    // N.V. uživo dok se karta vuče — samo iz pločice već u memoriji (bez I/O u
    // frame-u); nova pločica se učita na moveend.
    if (_nvPratiCentar()) {
      const v = _nvDemSync(c.lat, c.lng);
      if (v !== undefined) { _nvZahtjev++; _nvPostavi(v != null ? Math.round(v) + ' m' : '— m'); }
    }
  });
});
map.on('moveend', () => {
  const c = map.getCenter();
  updMGI(c.lat, c.lng);
  if (_nvPratiCentar()) debouncedUpdElev(c.lat, c.lng, 250);
});

// === RAZMJERA KARTE (live) ===
function _updMapScale() {
  const el = document.getElementById('map-scale-val');
  if (!el) return;
  const zoom = map.getZoom();
  const lat  = map.getCenter().lat;
  // Broj piksela po metru na ovom zoom-u i latitudi
  const metersPerPx = 156543.03392 * Math.cos(lat * Math.PI / 180) / Math.pow(2, zoom);
  // Pretpostavljamo 96 dpi → 1px = 0.2646 mm → razmjera = metersPerPx / 0.0002646
  const scale = Math.round(metersPerPx / 0.0002646);
  // Zaokruži na "lijepu" vrijednost
  const nice = [250,500,1000,1250,2000,2500,4000,5000,7500,10000,12500,15000,20000,25000,30000,50000,75000,100000,150000,200000,250000,500000];
  const closest = nice.reduce((a,b) => Math.abs(b-scale)<Math.abs(a-scale)?b:a);
  // Ručno odvajanje tisućica: prvi toLocaleString('bs') učitava Intl podatke (33–86 ms na slabom telefonu pri pokretanju).
  el.textContent = String(closest).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  // Sakrij tekstualne labele (brojevi odjela) pri razmjeri > 1:50 000
  map.getContainer().classList.toggle('labels-hidden', closest > 50000);
  // Lager oznake vidljive samo ispod razmjere 1:17 000
  map.getContainer().classList.toggle('lager-hidden', scale > 17000);
  // Sakrij vlake (linije + labele) pri razmjeri > 1:25 000
  const hideVlake = closest > 25000;
  const pLines  = map.getPane('vlakeLines');
  const pLabels = map.getPane('vlakeLabels');
  if (pLines)  pLines.style.display  = hideVlake ? 'none' : '';
  if (pLabels) pLabels.style.display = hideVlake ? 'none' : '';
  // Sakrij foto oznake i tragove pri razmjeri > 1:25 000
  // try-catch: _tragRegistry/Layers su let-deklarirani niže u fajlu (TDZ pri init pozivu)
  try {
    const hideFT = closest > 25000;
    if (hideFT !== _prevHideFT) {
      _prevHideFT = hideFT;
      // Zoom samo privremeno sklanja oznake; nikad ne poništava korisnikov Sakrij.
      for(const [list,shared] of [[_locFotos||[],false],[_sharedFotos||[],true]])for(const f of list){
        if(!f.marker)continue;
        const visible=!hideFT&&(typeof _tvPhotoVisible!=='function'||_tvPhotoVisible(f,shared));
        if(!visible&&map.hasLayer(f.marker))map.removeLayer(f.marker);
        else if(visible&&!map.hasLayer(f.marker))map.addLayer(f.marker);
      }
      (_tragRegistry||[]).forEach(t => {
        const layer = (_tragLayers||{})[t.id];
        if (!layer) return;
        if (hideFT && map.hasLayer(layer)) map.removeLayer(layer);
        else if (!hideFT && !map.hasLayer(layer) && t.visible !== false) map.addLayer(layer);
      });
    }
  } catch(e) {}
}
let _prevHideFT = false;
map.on('zoomend', _updMapScale);

// Broj labela po vlaci/kraku zavisi od zoom nivoa (vidi _labelFracs) — kad korisnik
// pređe prag "daleko/blizu" (npr. zumira na cijeli odjel ili se približi jednoj
// vlaci), labele treba ponovo iscrtati sa novim brojem. Osvježava se samo pri
// stvarnoj promjeni "tier"-a, ne na svaki zoomend, da se ne prerenderuju labele
// za sve vlake bez potrebe.
let _labelZoomFar = null;
function _refreshLabelZoomTier() {
  const far = map.getZoom() < 15;
  if (_labelZoomFar === far) return;
  _labelZoomFar = far;
  vlake.forEach((v, i) => updateVlakaLabel(i));
}
map.on('zoomend', _refreshLabelZoomTier);
map.on('moveend zoomend', _scheduleDeclutterLabels);

// === IZBOR RAZMJERE (klik na badge) ===
function toggleScaleMenu(e) {
  if (e) e.stopPropagation();
  const m = document.getElementById('scale-menu');
  if (m) m.style.display = m.style.display === 'block' ? 'none' : 'block';
}

function setMapScale(scale) {
  const m = document.getElementById('scale-menu');
  if (m) m.style.display = 'none';
  const lat = map.getCenter().lat;
  const z = zoomForScale(scale, lat);
  // Privremeno dopusti frakcioni zoom da razmjera bude tačna
  const prevSnap = map.options.zoomSnap;
  map.options.zoomSnap = 0;
  map.setZoom(z, { animate: false });
  map.options.zoomSnap = prevSnap;
  _updMapScale();
  showToast('Razmjera 1:' + scale.toLocaleString('bs'));
}

async function setMapScaleCustom() {
  const m = document.getElementById('scale-menu');
  if (m) m.style.display = 'none';
  const raw = await _dlgPrompt('Unesi razmjeru (npr. 17000 za 1:17 000):', '', { title: 'Razmjera', inputType: 'number', inputMode: 'numeric' });
  if (raw === null) return;
  const v = parseInt(String(raw).replace(/[^\d]/g, ''), 10);
  if (isNaN(v) || v < 500 || v > 500000) { showToast('⚠ Razmjera mora biti između 500 i 500 000'); return; }
  setMapScale(v);
}

// Inicijalni fetch N.V. pri učitavanju
(function() { const c = map.getCenter(); updMGI(c.lat, c.lng); debouncedUpdElev(c.lat, c.lng, 800); _updMapScale(); })();

// Close dropdowns when clicking outside
document.addEventListener('click', e => {
  const dd = document.getElementById('menu-dropdown');
  if (dd && !dd.contains(e.target) && !e.target.closest('#menu-btn')) closeMenuDropdown();
  // mjtrg bottom sheet se zatvara preko #mjtrg-sheet-bg overlay-a
  const sm = document.getElementById('scale-menu');
  if (sm && !sm.contains(e.target) && !e.target.closest('#map-scale-click')) sm.style.display = 'none';
  const lp = document.getElementById('ab-loc-popup');
  if (lp && !lp.contains(e.target) && !e.target.closest('#ab-loc-wrap')) lp.style.display = 'none';
});

// Keyboard shortcuts
document.addEventListener('keydown', e => {
  if (e.ctrlKey && e.key === 'z') { e.preventDefault(); mtUndo(); }
  if (e.key === 'Escape') stopActiveTool();
  // Space = dodaj tačku na centru karte (dok je aktivan alat crtanja ili GPS snimanje)
  if (e.key === ' ' && !e.ctrlKey && !e.altKey) {
    const tag = document.activeElement?.tagName;
    if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;
    e.preventDefault();
    if (activeTool === 'addline' || activeTool === 'addpoint') {
      const c = map.getCenter();
      const al = lastP?.al ?? null;
      if (actI !== null) addPt(actI, c.lat, c.lng, al);
      // Brief visual flash at map center
      const dot = document.getElementById('map-center-dot');
      if (dot) { dot.style.transform = 'translate(-50%,-50%) scale(2.5)'; dot.style.opacity = '1'; setTimeout(() => { dot.style.transform=''; dot.style.opacity=''; }, 300); }
      showToast('📍 Tačka dodana na centru karte');
    } else if (recOn && actI !== null && lastP) {
      addPt(actI, lastP.la, lastP.lo, lastP.al ?? null);
      showToast('📍 GPS tačka dodana');
    }
  }
});

// === MENI DROPDOWN ===
function _menuIdentityRender() {
  if(typeof SpdProfile!=='undefined')SpdProfile.sync();
  const p = sbUser && sbProfile?.id === sbUser.id ? sbProfile : null;
  const name = document.getElementById('menu-user-label');
  if (name) name.textContent = p ? [p.ime,p.prezime].filter(Boolean).join(' ').trim() || 'Korisnik' : sbUser ? 'Profil nije dostupan' : 'Nije prijavljen';
  const role = document.getElementById('menu-user-role');
  if (role) role.textContent = p ? [p.is_admin ? 'Administrator' : typeof isVodeci === 'function' && isVodeci() ? 'Vodeći projektant' : typeof isSpdField === 'function' && isSpdField() ? 'Terenski korisnik' : 'Projektant',p.sumarija].filter(Boolean).join(' · ') : '';
  const version = document.getElementById('menu-app-ver');
  if (version) version.textContent = 'Verzija ' + APP_VER;
  if(role&&p&&typeof AccessPolicy!=='undefined'){const trial=AccessPolicy.state(p);if(trial.kind==='trial')role.textContent+=' · Probni pristup još '+Math.ceil(trial.remaining/86400000)+' dana';}
}
function toggleMenuDropdown(e) {
  if (e) { e.stopPropagation(); e.preventDefault(); }
  const dd = document.getElementById('menu-dropdown');
  if (dd.style.display === 'none') {
    _menuIdentityRender();
    const btn = document.getElementById('menu-btn');
    const r = btn.getBoundingClientRect();
    // Stvarna širina (zavisi od najduže vidljive stavke i uloge korisnika) — fiksna
    // pretpostavka je puštala širi meni da izađe preko desne ivice ekrana.
    dd.style.visibility = 'hidden';
    dd.style.left = '0px';
    dd.style.display = 'flex';
    const ddW = dd.offsetWidth;
    dd.style.display = 'none';
    dd.style.visibility = '';
    let left = r.left;
    // Ne izlazi desno
    if (left + ddW > window.innerWidth - 6) left = window.innerWidth - ddW - 6;
    // Ne izlazi lijevo
    if (left < 6) left = 6;
    dd.style.top = (r.bottom + 4) + 'px';
    dd.style.left = left + 'px';
    dd.style.right = 'auto';
    // Skrolabilno unutar stvarno dostupnog prostora do dna ekrana — na manjim
    // telefonima je lista stavki duža od visine ekrana, pa bez ovoga dno menija
    // ispada van vidljivog dijela i nema način da se dođe do njega.
    dd.style.maxHeight = Math.max(150, window.innerHeight - r.bottom - 12) + 'px';
    dd.style.pointerEvents = 'none';
    dd.style.display = 'flex';
    const scroll = dd.querySelector('.mdrop-scroll');
    if (scroll) scroll.scrollTop = 0;
    btn.setAttribute('aria-expanded','true');
    setTimeout(() => { dd.style.pointerEvents = ''; }, 400);
  } else {
    closeMenuDropdown();
  }
}
function closeMenuDropdown() {
  document.getElementById('menu-dropdown').style.display = 'none';
  document.getElementById('menu-btn')?.setAttribute('aria-expanded','false');
}
let _mjtrgReturnFocus = null;
function toggleMjtrgDropdown(e) {
  if (e) { e.stopPropagation(); e.preventDefault(); }
  const dd = document.getElementById('mjtrg-dropdown');
  const bg = document.getElementById('mjtrg-sheet-bg');
  if (!dd || !bg) return;
  if (dd.style.display !== 'none') { closeMjtrgDropdown(); return; }
  if(typeof closeMenuDropdown==='function')closeMenuDropdown();
  for(const id of ['ab-loc-popup','ab-izmjeri-menu']){const el=document.getElementById(id);if(el)el.style.display='none';}
  _mjtrgReturnFocus = document.activeElement;
  const p = typeof _projekti !== 'undefined' && typeof _aktivniProjektId !== 'undefined'
    ? _projekti.find(x => x.id === _aktivniProjektId) : null;
  document.getElementById('mjtrg-project').textContent = p
    ? [p.odjel ? 'Odjel ' + p.odjel : 'Aktivni projekat', p.gj].filter(Boolean).join(' · ')
    : 'Nema aktivnog projekta';
  document.getElementById('mjtrg-msr-count').textContent = typeof _msrRegistry !== 'undefined' ? _msrRegistry.length : 0;
  document.getElementById('mjtrg-trg-count').textContent = typeof _tragRegistry !== 'undefined' ? _tragRegistry.length : 0;
  const status = document.getElementById('mjtrg-rec-status');
  status.hidden = !(typeof _tragOn !== 'undefined' && _tragOn);
  status.textContent = typeof _tragPaused !== 'undefined' && _tragPaused ? 'Snimanje traga pauzirano' : 'Snimanje traga u toku';
  bg.style.display = 'block';
  dd.style.display = 'flex';
  dd.querySelector('.mt-body').scrollTop = 0;
  document.getElementById('mjtrg-close').focus({preventScroll:true});
}
function closeMjtrgDropdown() {
  const dd = document.getElementById('mjtrg-dropdown');
  const wasOpen = dd && dd.style.display !== 'none';
  if (dd) dd.style.display = 'none';
  const bg = document.getElementById('mjtrg-sheet-bg');
  if (bg) bg.style.display = 'none';
  if (wasOpen) {
    const target = _mjtrgReturnFocus;
    const visible = target && target.isConnected && target.getClientRects().length;
    (visible ? target : document.getElementById('menu-btn'))?.focus({preventScroll:true});
    _mjtrgReturnFocus = null;
  }
}
function _mjtrgDialogKey(e) {
  if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); closeMjtrgDropdown(); }
  if (e.key !== 'Tab') return;
  const buttons = Array.from(document.getElementById('mjtrg-dropdown').querySelectorAll('button:not([disabled])'));
  const first = buttons[0], last = buttons[buttons.length - 1];
  if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
  else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
}
function _mjtrgSaved(tab) {
  closeMjtrgDropdown();
  _tragoviSetTab(tab);
  switchTab('tragovi');
}

// Koordinate HUD — no-op (stara funkcija ovl uklonjena)

// === QGIS MAP TOOLBAR ===
function setActiveTool(tool) {
  if (typeof window !== 'undefined' && tool!=='pan') window.Explorer?.inspect();
  const prev = activeTool;
  // Stop previous tool internals without triggering setActiveTool again
  if (prev === 'addline') {
    const leavingDraw = tool !== 'addline';
    _stopAddLine(false);
    // Napuštanje crtanja mimo "✓ Završi" (drugi alat/tab) — ugasi lančano trasiranje
    // i odbaci zadnju praznu vlaku.
    if (leavingDraw && _chainTraceOn) {
      if (actI !== null && vlake[actI] && (vlake[actI].pts?.length || 0) < 2) _dropEmptyVlaka(actI);
      _chainTraceOn = false;
    }
  }
  else if (prev === 'edit' || prev === 'delnode') _stopEdit(false);
  else if (prev === 'merge' && tool !== 'merge') _cancelMergeInternal();

  activeTool = tool;

  // reset all button styles
  document.querySelectorAll('.mt-btn').forEach(b => {
    b.classList.remove('active','active-green','active-orange','active-red');
  });

  const cursors = { select:'', addline:'crosshair', addpoint:'cell', edit:'default', delnode:'pointer', merge:'default' };
  map.getContainer().style.cursor = cursors[tool] || '';

  const cls = { addline:'active-green', addpoint:'active-green', edit:'active', delnode:'active-red', merge:'active-orange', select:'active' };
  const ids = { select:'mt-select', addline:'mt-addline', addpoint:'mt-addpt', edit:'mt-edit', delnode:'mt-delnode', merge:'mt-merge' };
  if (ids[tool]) {
    const btn = document.getElementById(ids[tool]);
    if (btn) btn.classList.add(cls[tool] || 'active');
  }

  // Toolbar vidljiv samo dok se crta/edituje, ili u full-screen mapi
  const tb = document.getElementById('map-toolbar');
  if (tb) tb.style.display = (tool !== 'select' || _mapFullScreen) ? '' : 'none';
}

function mtSelect() {
  setActiveTool('select');
  document.getElementById('draw-banner').classList.remove('show');
}

function mtAddLine() {
  // Auto-kreiraj vlaku ako nema odabrane — jedan klik za početi crtanje
  if (actI === null) {
    addV().then(() => { if (actI !== null) mtAddLine(); });
    return;
  }
  setActiveTool('addline');
  map.doubleClickZoom.disable();
  drawUndoStack = [];
  // Spremi trenutno stanje kao inicijalni undo — ne smijemo slučajno obrisati
  // pre-postojeće tačke (npr. GPS snimanje) kad korisnik udari Undo do kraja
  drawUndoStack.push(vlake[actI].pts.map(p => ({...p})));
  document.getElementById('draw-banner').classList.add('show');
  document.getElementById('draw-nm').textContent = vlake[actI].nm;
  _updDrawStats();
  // Aktiviraj interaktivnu centralnu tačku
  document.getElementById('main').classList.add('drawing-active');
  document.getElementById('map-center-dot').onclick = _mcdClick;
  document.getElementById('map-center-dot').style.display = '';
  // NEMA auto-prve-tačke — korisnik pozicionira crosshair pa tapne/klikne
  _updFabVisibility();
}

function stopAddLine() { _stopAddLine(true); }

// Klik na centralnu bijelu tačku = dodaj tačku na trenutnom centru mape
function _mcdClick(e) {
  if (activeTool !== 'addline' || actI === null) return;
  e.stopPropagation();
  const c = map.getCenter();
  drawUndoStack.push(vlake[actI].pts.map(p => ({...p})));
  addPt(actI, c.lat, c.lng, 0);
}

// Draw-drag modus: tačke se dodaju automatski dok se mapa pomjera
let _drawDragOn = false;
let _drawDragLastPt = null;
const DRAW_DRAG_MIN_M = 5; // minimalna udaljenost (m) između tačaka u drag modusu

function toggleDrawDrag() {
  if (!_drawDragOn) {
    // Spremi stanje prije cijele drag sesije — jedno Undo vraća sve drag tačke odjednom
    if (actI !== null) drawUndoStack.push(vlake[actI].pts.map(p => ({...p})));
    _drawDragOn = true;
    _drawDragLastPt = null;
    const btn = document.getElementById('btn-draw-drag');
    btn.classList.add('active');
    btn.innerHTML = '<svg class="ic"><use href="#ic-crtaj"/></svg> Stop';
    document.getElementById('main').classList.add('draw-drag-on');
    map.on('drag', _onMapMoveDraw);
  } else {
    _stopDrawDrag();
  }
}

function _stopDrawDrag() {
  if (!_drawDragOn) return;
  _drawDragOn = false;
  _drawDragLastPt = null;
  map.off('drag', _onMapMoveDraw);
  const btn = document.getElementById('btn-draw-drag');
  if (btn) { btn.classList.remove('active'); btn.innerHTML = '<svg class="ic"><use href="#ic-crtaj"/></svg> Vuci'; }
  document.getElementById('main').classList.remove('draw-drag-on');
}

function _onMapMoveDraw() {
  if (!_drawDragOn || activeTool !== 'addline' || actI === null) return;
  const c = map.getCenter();
  if (_drawDragLastPt) {
    const d = dst(_drawDragLastPt.la, _drawDragLastPt.lo, c.lat, c.lng);
    if (d < DRAW_DRAG_MIN_M) return;
  }
  _drawDragLastPt = { la: c.lat, lo: c.lng };
  addPt(actI, c.lat, c.lng, 0);
}
function _stopAddLine(fromUser) {
  if (_prevMoveTimer) { clearTimeout(_prevMoveTimer); _prevMoveTimer = null; }
  map.doubleClickZoom.enable();
  if (drawPreviewLine) { map.removeLayer(drawPreviewLine); drawPreviewLine = null; }
  hideSnapRing(); snapTarget = null;
  document.getElementById('draw-banner').classList.remove('show');
  // Deaktiviraj draw-drag modus i interaktivnu centralnu tačku
  _stopDrawDrag();
  document.getElementById('main').classList.remove('drawing-active');
  document.getElementById('map-center-dot').onclick = null;
  drawUndoStack = [];
  _updFabVisibility();
  if (fromUser) {
    // Kraj lančanog trasiranja: zadnja (prazna) vlaka je auto-kreirana ali nikad
    // nije trasirana — odbaci je da ne ostane prazan zapis.
    const wasChain = _chainTraceOn;
    _chainTraceOn = false;
    if (wasChain && actI !== null && vlake[actI] && (vlake[actI].pts?.length || 0) < 2) {
      _dropEmptyVlaka(actI);
      if (bufLayers.length > 0) drawBuffers();
      setActiveTool('select');
      rndList();
      return;
    }
    if (actI !== null) { updateVlakaLabel(actI); sbFlushVlaka(actI); }
    if (bufLayers.length > 0) drawBuffers();
    // Ručno crtana vlaka ne prolazi kroz stopRec() — ako su doznaka stabla učitana
    // za trenutno otvoreni odjel, tek nacrtana vlaka može promijeniti ko je "u
    // dosegu" isto kao snimljena; osvježi bez traženja ručnog klika.
    if (typeof _dozTreePts !== 'undefined' && _dozTreePts.length && _dozSelId) dozTreesAnalyze();
    setActiveTool('select');
    if (actI !== null && vlake[actI]?.pts?.length > 0 && !vlake[actI]?.lager) _showLagerDlg(actI);
  }
}

function mtAddPoint() {
  if (actI === null) { showToast('⚠ Prvo odaberi vlaku!'); return; }
  setActiveTool('addpoint');
  showToast('📍 Klikni na kartu za tačku/waypoint');
}

// ─── Edit vlake — moderni bottom panel (Pomjeri / Obriši / Undo / Završi) ────
let _edDelMode = false;     // ✂ Obriši mod — tap na tačku je briše
let _edUndoStack = [];      // snapshoti pts[] za Undo

function _edSnapshot() {
  if (!editOn || activeTool !== 'edit' || actI === null || !vlake[actI]) return;
  _edUndoStack.push(vlake[actI].pts.map(p => ({...p})));
  if (_edUndoStack.length > 60) _edUndoStack.shift();
}

function _edpUpdStats() {
  const el = document.getElementById('edp-stats');
  if (!el || actI === null || !vlake[actI]) return;
  const pts = vlake[actI].pts;
  el.textContent = fmtL(calcL(pts)) + ' · ' + pts.length + ' tač.';
}

function edpSetMode(m) {
  _edDelMode = (m === 'del');
  document.getElementById('edp-move').classList.toggle('active', !_edDelMode);
  document.getElementById('edp-del').classList.toggle('active', _edDelMode);
  document.getElementById('map').classList.toggle('edp-del-mode', _edDelMode);
  document.getElementById('edp-hint').textContent = _edDelMode
    ? 'Tapni tačku da je obrišeš'
    : 'Povuci tačku za pomjeranje · tap između tačaka dodaje novu';
}

async function edpRename() {
  if (actI === null || !vlake[actI]) return;
  const i=actI, v = vlake[i], owner=sbUser?.id;
  const nw = await _dlgPrompt('Novi naziv vlake (T5 = vlaka, T5.1 = krak):', v.nm, { title: 'Preimenuj vlaku', vlakaKeyboard: true });
  if (!nw || sbUser?.id!==owner || actI!==i || vlake[i]!==v) return;
  const nm = _impNormalName(nw);
  if (!nm || nm === v.nm) return;
  if (vlake.some((x, xi) => xi !== actI && x.nm === nm && x.projektId === v.projektId)) {
    showToast('⚠ Naziv "' + nm + '" već postoji u projektu');
    return;
  }
  const kolegaDup = typeof _kolegaVlakaDup === 'function' ? _kolegaVlakaDup(nm) : null;
  if (kolegaDup) {
    const ok = await _dlgConfirm(
      `Vlaka "${nm}" već postoji u projektu — snimio/la ju je ${kolegaDup}.\n\nŽeliš li svejedno preimenovati?`,
      { title: '⚠ Ista vlaka već u projektu', okLabel: 'Svejedno', danger: true });
    if (!ok) return;
  }
  if (sbUser?.id!==owner || actI!==i || vlake[i]!==v || !await renameVlaka(i, nm)) return;
  document.getElementById('edp-nm').textContent = nm;
  showToast('✏ Preimenovano u ' + nm);
}

// Promjena boje vlake/kraka POSLIJE snimanja/crtanja — do sada je boja bila
// fiksna (dodijeljena samo pri kreiranju iz PAL palete po redoslijedu), bez
// ikakvog načina da se promijeni. Radi u edit modu (🔧 Uredi), pogađa istu
// vlaku/krak koja je trenutno otvorena za editovanje (actI).
function _edpColorPicked(col) {
  if (actI === null || !vlake[actI]) return;
  const v = vlake[actI];
  v.color = col;
  const dot = document.getElementById('edp-color-dot');
  if (dot) dot.style.background = col;
  try { v.poly.setStyle({ color: typeof _vlakaPrikazColor==='function'?_vlakaPrikazColor(v):col }); } catch(e) {}
  v.updatedAt = new Date().toISOString();
  rndList();       // stripe boja u listi
  sbFlushVlaka(actI);
}

function edpUndo() {
  if (actI === null || !vlake[actI] || _edUndoStack.length === 0) return;
  const snap = _edUndoStack.length > 1 ? _edUndoStack.pop() : _edUndoStack[0].map(p => ({...p}));
  const v = vlake[actI];
  v.pts = snap.map(p => ({...p}));
  syncPoly(actI);
  buildEditHandles(actI);
  updateVlakaLabel(actI);
  scheduleVlakaSave(actI);
  updOvl(); rndList();
  _edpUpdStats();
}

function mtEditLine() {
  if (actI === null) { showToast('⚠ Odaberi vlaku za editovanje!'); return; }
  if (vlake[actI].pts.length === 0) { showToast('⚠ Vlaka nema tačaka — najprije nacrtaj liniju!'); return; }
  if (_activeTab !== 'karta') { switchTab('karta'); zmV(actI); }
  setActiveTool('edit');
  editOn = true;
  _edUndoStack = [vlake[actI].pts.map(p => ({...p}))];
  map.doubleClickZoom.disable();
  document.getElementById('edit-panel').style.display = '';
  document.getElementById('edp-nm').textContent = vlake[actI].nm;
  const _edpSw = document.getElementById('edp-color-dot');
  const _edpCi = document.getElementById('edp-color-input');
  if (_edpSw) _edpSw.style.background = vlake[actI].color;
  if (_edpCi) _edpCi.value = vlake[actI].color;
  const proj = (_projekti || []).find(p => p.id === vlake[actI].projektId);
  document.getElementById('edp-proj').innerHTML = proj
    ? '📁 <b>' + (proj.odjel || '—') + '</b>' + (proj.gj ? ' · ' + proj.gj : '')
    : '<span style="color:#94a3b8;">Bez projekta</span>';
  edpSetMode('move');
  _edpUpdStats();
  buildEditHandles(actI);
  _updFabVisibility();
}

function _stopEdit(fromUser) {
  editOn = false;
  mergeMode = false; mergeFirst = null;
  _edDelMode = false;
  _edUndoStack = [];
  clearEditHandles();
  map.doubleClickZoom.enable();
  document.getElementById('edit-panel').style.display = 'none';
  document.getElementById('map').classList.remove('edp-del-mode');
  document.getElementById('draw-banner').classList.remove('show');
  document.getElementById('draw-row2').style.display = '';
  document.getElementById('merge-sec').style.display = 'none';
  if (snapRingMk) { map.removeLayer(snapRingMk); snapRingMk = null; }
  _updFabVisibility();
  if (fromUser) {
    if (actI !== null) { updateVlakaLabel(actI); sbFlushVlaka(actI); }
    if (bufLayers.length > 0) drawBuffers();
    rndList(); updOvl(); updProjStats();
  }
}

function mtDeleteNode() {
  if (actI === null) { showToast('⚠ Odaberi vlaku!'); return; }
  if (vlake[actI].pts.length === 0) { showToast('⚠ Vlaka nema tačaka!'); return; }
  setActiveTool('delnode');
  editOn = true;
  map.doubleClickZoom.disable();
  buildEditHandles(actI);
  document.getElementById('draw-banner').classList.add('show');
  document.getElementById('draw-nm').textContent = vlake[actI].nm + ' ✂';
  document.getElementById('draw-stats').textContent = 'Klikni čvor · ESC';
  document.getElementById('draw-row2').style.display = 'none';
  showToast('✂ Klikni na čvor (bijeli krug) da ga obrišeš');
}

function mtUndo() {
  if (activeTool !== 'addline') { showToast('Undo dostupan samo u crtanju linije'); return; }
  if (actI === null || drawUndoStack.length === 0) { showToast('Nema akcija za poništiti'); return; }
  const prev = drawUndoStack.pop();
  vlake[actI].pts = prev;
  syncPoly(actI);
  updateVlakaLabel(actI);
  updOvl(); rndList();
  _updDrawStats();
  showToast('↩ Poništena zadnja tačka');
  // reset preview
  if (drawPreviewLine) { map.removeLayer(drawPreviewLine); drawPreviewLine = null; }
}

function stopActiveTool() {
  const t = activeTool;
  if (t === 'addline') { _stopAddLine(true); }
  else if (t === 'edit' || t === 'delnode') { _stopEdit(true); setActiveTool('select'); }
  else if (t === 'merge') { _cancelMergeInternal(); setActiveTool('select'); }
  else if (t === 'addpoint') { setActiveTool('select'); }
  // also turn off text tool if active
  if (textToolOn) toggleTextTool();
}

// backward compat — called from rndList edit button
function togEdit() { if(actI!==null) mtEditLine(); }

// ─── POST-RECORDING UGLAČAVANJE (Douglas-Peucker za geo koordinate) ────────
let _smoothPreviewLine = null;
let _smoothOrigPts = null;

function _dpSimplifyGeo(pts, epsM) {
  if (pts.length <= 2) return pts;
  const pld = (p, a, b) => {
    const segLen = dst(a.la, a.lo, b.la, b.lo);
    if (segLen < 0.01) return dst(p.la, p.lo, a.la, a.lo);
    const t = Math.max(0, Math.min(1,
      ((p.la-a.la)*(b.la-a.la)+(p.lo-a.lo)*(b.lo-a.lo)) /
      ((b.la-a.la)**2+(b.lo-a.lo)**2)));
    const projLa = a.la + t*(b.la-a.la);
    const projLo = a.lo + t*(b.lo-a.lo);
    return dst(p.la, p.lo, projLa, projLo);
  };
  let maxD = 0, maxI = 0;
  for (let i = 1; i < pts.length - 1; i++) {
    const d = pld(pts[i], pts[0], pts[pts.length-1]);
    if (d > maxD) { maxD = d; maxI = i; }
  }
  if (maxD > epsM) {
    const L = _dpSimplifyGeo(pts.slice(0, maxI+1), epsM);
    const R = _dpSimplifyGeo(pts.slice(maxI), epsM);
    return [...L.slice(0,-1), ...R];
  }
  return [pts[0], pts[pts.length-1]];
}

// Uklanja tačke koje OKOMITO odskaču više od 15 m od linije između susjeda
// (klasičan multipath odskok u stranu). NE vidi povratak istim putem — to je
// uzdužno odstupanje, za njega postoji _zbijPetlje ispod.
function _removeOutliers(pts) {
  if (pts.length < 3) return pts;
  const result = [pts[0]];
  for (let i = 1; i < pts.length - 1; i++) {
    const dev = Math.abs(pld(pts[i], pts[i-1], pts[i+1]));
    if (dev < 15) result.push(pts[i]);
  }
  result.push(pts[pts.length-1]);
  return result;
  function pld(p, a, b) {
    const segLen = dst(a.la, a.lo, b.la, b.lo);
    if (segLen < 0.01) return dst(p.la, p.lo, a.la, a.lo);
    const t = Math.max(0, Math.min(1,
      ((p.la-a.la)*(b.la-a.la)+(p.lo-a.lo)*(b.lo-a.lo)) /
      ((b.la-a.la)**2+(b.lo-a.lo)**2)));
    return dst(p.la, p.lo, a.la+t*(b.la-a.la), a.lo+t*(b.lo-a.lo));
  }
}

// ─── SAŽIMANJE PETLJI I MIROVANJA — ono što Douglas-Peucker NE MOŽE ─────────
//
// Terenska prijava (v3.120.0), uz screenshot: "vratio sam se istim putem oko
// 5 metara a uvijek pokaže ovako cik-cak". Do sada je "Ugladi trag" bio SAMO
// Douglas-Peucker (_dpSimplifyGeo) + _removeOutliers, a oba mjere OKOMITO
// odstupanje tačke od linije kroz susjede. Povratak istim putem leži UZDUŽ te
// linije, ne okomito na nju — dakle nevidljiv je za oba, ma koliko se
// regulator "Jačina" pomjerao. To nije bio propust u podešavanju nego
// pogrešan alat za taj oblik greške.
//
// Izmjereno (izolovan repro nad STVARNIM _dpSimplifyGeo iz ovog fajla;
// krivudava vlaka od 60 m, povratak 5 m u sredini, bočni GPS šum ±1 m):
//     snimljeno              35 tač.   82.0 m   3.8 m unazad
//     DP eps=1               18 tač.   80.8 m   3.8 m unazad  ← cik-cak PREŽIVI
//     DP eps=2                6 tač.   66.2 m   0.0 m unazad  ← ubije cik-cak,
//                                                  ali desetkuje i pravu krivinu
//     zbijPetlje(5) + DP=1   14 tač.   69.4 m   0.0 m unazad  ← i jedno i drugo
// DP je imao JEDAN regulator za DVA posla koja se međusobno tuku; ovim su
// razdvojena — krug petlji čisti vraćanje/mirovanje, eps čisti sitan šum.
//
// Niz tačaka i..j se sažima u JEDNU tačku ako je istovremeno:
//   (a) ZATVOREN — svaka tačka niza je unutar `krugM` od početka niza, i
//   (b) NEPRODUKTIVAN — pređeni put je bar dvostruko veći od neto pomaka
//       (hodao puno, a pomjerio se malo).
// Uslov (b) je ono što razdvaja "vrtio se u mjestu" od "prošao kroz" —
// bez njega bi se i obično pravolinijsko hodanje prorijedilo na svakih
// `krugM` metara. Provjereno: hodanje pravo 100 m (tačka svakih 2 m) prolazi
// kroz ovo NETAKNUTO — 51 tačka prije, 51 poslije, dužina identična.
//
// GRANICA KOJU TREBA ZNATI: stvarna serpentina (špic-okret) UŽA od ~6 m se na
// krugu od 5 m poravna kao da je greška — izmjereno, okret širine 4 m gubi
// 20.5 m, dok 6 m i širi ostaju netaknuti do zadnjeg metra. Vlaka sa okretom
// užim od 6 m nije prohodna za traktor/forvarder, pa je granica u praksi van
// domašaja; ako ipak zasmeta, klizač se spusti niže ili na 0 (isključeno).
function _zbijPetljeProlaz(pts, krugM) {
  const n = pts.length, out = [];
  let i = 0;
  while (i < n) {
    let j = i;
    while (j + 1 < n && dst(pts[i].la, pts[i].lo, pts[j+1].la, pts[j+1].lo) <= krugM) j++;
    if (j > i) {
      let put = 0;
      for (let k = i; k < j; k++) put += dst(pts[k].la, pts[k].lo, pts[k+1].la, pts[k+1].lo);
      const neto = dst(pts[i].la, pts[i].lo, pts[j].la, pts[j].lo);
      if (put >= Math.max(2 * neto, krugM)) {
        // Oznaka GPS prekida (gap) se PRENOSI na sažetu tačku — inače bi
        // sažimanje tiho progutalo upozorenje "provjeri ovaj dio traga".
        // Mora se primijeniti na SVE tri grane ispod, i na sidrene: prvi
        // pokušaj je gap nosio samo u centroid-grani, pa je mirovanje na
        // samom POČETKU traga tiho gubilo upozorenje (uhvaćeno testom).
        let rep;
        if (i === 0)          rep = { ...pts[0] };          // sidro: početak
        else if (j === n - 1) rep = { ...pts[n - 1] };      // sidro: kraj
        else {
          // Krajevi vlake/traga su SIDRA — početak se veže na put ili matičnu
          // vlaku, kraj na sljedeći krak. Pomjeranje na centroid bi tiho
          // raskinulo taj spoj, pa se tu zadržava originalna tačka; unutar
          // trase centroid je bolji jer usrednji GPS šum cijelog niza.
          let sla = 0, slo = 0;
          for (let k = i; k <= j; k++) { sla += pts[k].la; slo += pts[k].lo; }
          rep = { ...pts[i], la: sla / (j - i + 1), lo: slo / (j - i + 1) };
        }
        for (let k = i; k <= j; k++) if (pts[k].gap) { rep.gap = true; break; }
        out.push(rep);
        i = j + 1;
        continue;
      }
    }
    out.push(pts[i]);
    i++;
  }
  return out;
}

// Više prolaza je NUŽNO, ne optimizacija: kad GPS u mjestu drifta više nego
// što je krug širok, prvi prolaz sažme tek podgrupe, pa tek drugi spoji ono
// što je time postalo dovoljno blizu. Izmjereno na "zaboravio pauzu" (40
// fiksova u mjestu, drift ±3 m, krug 5 m): 1 prolaz → 93.7 m, 2 prolaza →
// 68.9 m, dalje nepromijenjeno (stvarna trasa 60 m). Petlja staje sama čim
// prolaz ništa ne promijeni.
function _zbijPetlje(pts, krugM, maxProlaza) {
  if (!pts || pts.length < 3 || !(krugM > 0)) return pts;
  let cur = pts;
  const lim = maxProlaza || 4;
  for (let p = 0; p < lim; p++) {
    const next = _zbijPetljeProlaz(cur, krugM);
    if (next.length === cur.length) return next;
    cur = next;
  }
  return cur;
}

// Jedinstven redoslijed obrade za vlaku i za trag — prvo petlje (uzdužno),
// pa okomiti odskoci, pa sitan šum. Obrnut redoslijed ne bi radio: DP prvo
// izbaci tačke koje petlji trebaju da bi se uopšte prepoznala kao petlja.
function _uglObradi(pts, krugM, epsM) {
  let out = _zbijPetlje(pts, krugM);
  out = _removeOutliers(out);
  if (epsM > 0) out = _dpSimplifyGeo(out, epsM);
  return out;
}

// Tačke traga su nizovi [la, lo, alt, timestamp, tačnost], vlake su objekti
// {la, lo, ...} — algoritam radi nad objektima, pa trag ide kroz adapter.
// Sažeta tačka nosi vrijeme PRVE tačke niza (trenutak dolaska na to mjesto),
// ne zadnje — inače bi mirovanje od 4 minute izgledalo kao da je počelo tek
// na svom kraju.
function _tragPtsUObj(pts) {
  return pts.map(p => ({ la: p[0], lo: p[1], _al: p[2], _t: p[3], _ac: p[4] }));
}
function _tragPtsIzObj(objs) {
  return objs.map(o => [o.la, o.lo, o._al, o._t, o._ac]);
}

// ─── POVRATAK (jedan nivo) ─────────────────────────────────────────────────
// Uglačavanje TRAJNO briše izmjerene GPS tačke. Bez povratka bi jedan pogrešno
// postavljen klizač nepovratno pojeo snimak sa terena koji se ne može ponoviti.
let _uglUndo = null;   // { vrsta:'vlaka'|'trag', ref, pts, opis }

function _uglMoguciPovratak(vrsta, ref) {
  // try/catch zbog TDZ-a: _uglUndo je `let` (nije hoistovan), a listu tragova
  // zna iscrtati kod koji se pokrene prije nego izvršavanje bloka dođe dovde
  // (offline-first pokretanje zove showApp() dok se dokument još parsira —
  // vidi zamku "Pokretanje dira DOM koji JOŠ NE POSTOJI" u CLAUDE.md).
  try { return !!(_uglUndo && _uglUndo.vrsta === vrsta && _uglUndo.ref === ref); }
  catch (e) { return false; }
}

function _uglVrati() {
  if (!_uglUndo) return;
  const u = _uglUndo;
  _uglUndo = null;
  if (u.vrsta === 'vlaka') {
    const v = u.ref;
    if (!vlake.includes(v)) { showToast('⚠ Vlaka više ne postoji'); return; }
    v.pts = u.pts;
    v.poly.setLatLngs(u.pts.map(p => [p.la, p.lo]));
    const i = vlake.indexOf(v);
    updateVlakaLabel(i);
    scheduleVlakaSave(i);
    _saveLocalVlake();
    rndList();
  } else {
    const t = u.ref;
    if (!_tragRegistry.includes(t)) { showToast('⚠ Trag više ne postoji'); return; }
    t.pts = u.pts;
    _tragRegAddLayer(t);
    _tragRegSave();
    _tragRegRender();
  }
  showToast('↩ Uglačavanje poništeno — vraćene originalne tačke');
}

function _smoothVlakaStart() {
  if (actI === null) return;
  const v = vlake[actI];
  if (v.pts.length < 3) { showToast('⚠ Premalo tačaka za uglačavanje'); return; }
  _smoothOrigPts = v.pts.map(p => ({...p}));
  document.getElementById('edp-smooth').style.display = '';
  _smoothVlakaPreview();
}

// Sažetak izmjene MORA nositi i dužinu, ne samo broj tačaka: cik-cak i
// mirovanje NADUVAVAJU izmjerenu dužinu (u reprou 82 m umjesto stvarnih 60 m),
// a dužina vlake ulazi u gustoću mreže (m/ha) po kojoj se ocjenjuje da li je
// mreža dovoljna. Broj tačaka sam po sebi ne kaže je li išta ispravljeno.
function _uglInfoTxt(prije, poslije) {
  const dPrije = calcL(prije), dPoslije = calcL(poslije);
  const raz = dPoslije - dPrije;
  return `${prije.length} → ${poslije.length} tačaka · dužina ${dPrije.toFixed(1)} → ` +
         `${dPoslije.toFixed(1)} m (${raz >= 0 ? '+' : '−'}${Math.abs(raz).toFixed(1)} m)`;
}

function _uglVlakaParams() {
  const krugEl = document.getElementById('edp-ugl-krug');
  const epsEl  = document.getElementById('edp-smooth-eps');
  return {
    krug: krugEl ? parseFloat(krugEl.value) : 5,
    eps:  epsEl  ? parseFloat(epsEl.value)  : 2
  };
}

function _smoothVlakaPreview() {
  if (actI === null || !_smoothOrigPts) return;
  const { krug, eps } = _uglVlakaParams();
  const simplified = _uglObradi(_smoothOrigPts, krug, eps);
  if (_smoothPreviewLine) { map.removeLayer(_smoothPreviewLine); _smoothPreviewLine = null; }
  _smoothPreviewLine = L.polyline(
    simplified.map(p => [p.la, p.lo]),
    { color: '#a78bfa', weight: 3, dashArray: '6 4', opacity: 0.9 }
  ).addTo(map);
  const info = document.getElementById('edp-smooth-info');
  if (info) info.textContent = _uglInfoTxt(_smoothOrigPts, simplified);
}

function _smoothVlakaApply() {
  if (actI === null || !_smoothOrigPts) return;
  const { krug, eps } = _uglVlakaParams();
  const simplified = _uglObradi(_smoothOrigPts, krug, eps);
  if (simplified.length < 2) { showToast('⚠ Ostalo bi manje od 2 tačke — smanji jačinu'); return; }
  const v = vlake[actI];
  const removed = v.pts.length - simplified.length;
  _uglUndo = { vrsta: 'vlaka', ref: v, pts: _smoothOrigPts.map(p => ({...p})) };
  v.pts = simplified;
  v.poly.setLatLngs(simplified.map(p => [p.la, p.lo]));
  updateVlakaLabel(actI);
  scheduleVlakaSave(actI);
  _saveLocalVlake();
  _smoothVlakaCancel();
  rndList();
  const btn = document.getElementById('edp-ugl-vrati');
  if (btn) btn.style.display = '';
  showToast(`✓ Uglačano: uklonjeno ${removed} tačaka — "Vrati" ako nije dobro`);
}

function _smoothVlakaCancel() {
  if (_smoothPreviewLine) { map.removeLayer(_smoothPreviewLine); _smoothPreviewLine = null; }
  _smoothOrigPts = null;
  document.getElementById('edp-smooth').style.display = 'none';
}

// ─── UGLAČAVANJE TRAGA ─────────────────────────────────────────────────────
// Tragovi do sada NISU imali nikakvo uglačavanje (postojalo je samo za vlake),
// a korisnik na terenu snima i jedno i drugo istim hodom i istim GPS-om — pa
// je isti cik-cak jednako pogađao oba. Isti algoritam, isti klizači, samo nad
// nizovima umjesto objekata (vidi _tragPtsUObj).
let _uglTragId = null;

function _uglTragParams(id) {
  const k = document.getElementById('treg-ugl-krug-' + id);
  const e = document.getElementById('treg-ugl-eps-' + id);
  return { krug: k ? parseFloat(k.value) : 5, eps: e ? parseFloat(e.value) : 1 };
}

function _uglTragOtvori(id) {
  const t = _tragRegistry.find(x => x.id === id);
  if (!t) return;
  if (!t.pts || t.pts.length < 3) { showToast('⚠ Premalo tačaka za uglačavanje'); return; }
  if (_uglTragId && _uglTragId !== id) _uglTragOtkazi(_uglTragId);
  _uglTragId = id;
  const p = document.getElementById('treg-ugl-' + id);
  if (p) p.style.display = '';
  _uglTragPreview(id);
}

function _uglTragPreview(id) {
  const t = _tragRegistry.find(x => x.id === id);
  if (!t) return;
  const { krug, eps } = _uglTragParams(id);
  const prije = _tragPtsUObj(t.pts);
  const poslije = _uglObradi(prije, krug, eps);
  if (_smoothPreviewLine) { map.removeLayer(_smoothPreviewLine); _smoothPreviewLine = null; }
  _smoothPreviewLine = L.polyline(poslije.map(p => [p.la, p.lo]),
    { color: '#a78bfa', weight: 3, dashArray: '6 4', opacity: 0.9, pane: 'tragMsrLines' }).addTo(map);
  const info = document.getElementById('treg-ugl-info-' + id);
  if (info) info.textContent = _uglInfoTxt(prije, poslije);
}

function _uglTragPrimijeni(id) {
  const t = _tragRegistry.find(x => x.id === id);
  if (!t) return;
  const { krug, eps } = _uglTragParams(id);
  const poslije = _uglObradi(_tragPtsUObj(t.pts), krug, eps);
  if (poslije.length < 2) { showToast('⚠ Ostalo bi manje od 2 tačke — smanji jačinu'); return; }
  const uklonjeno = t.pts.length - poslije.length;
  _uglUndo = { vrsta: 'trag', ref: t, pts: t.pts.map(p => p.slice()) };
  t.pts = _tragPtsIzObj(poslije);
  _uglTragOtkazi(id);
  _tragRegAddLayer(t);          // linija, hit-sloj i oznaka dužine se grade iz t.pts
  _tragRegSave();
  _tragRegRender();
  showToast(`✓ Uglačano: uklonjeno ${uklonjeno} tačaka — "Vrati" ako nije dobro`);
}

function _uglTragOtkazi(id) {
  if (_smoothPreviewLine) { map.removeLayer(_smoothPreviewLine); _smoothPreviewLine = null; }
  const p = document.getElementById('treg-ugl-' + (id || _uglTragId));
  if (p) p.style.display = 'none';
  _uglTragId = null;
}

// === PREVIEW ===
function updPrev() {
  const br = parseInt(document.getElementById('ibr').value)||1;
  const kr = parseInt(document.getElementById('ikr').value)||0;
  let nm, ds;
  if (kr===0) { nm=`T${br}`; ds=`Vlaka ${br} — matična trasa`; }
  else {
    const st = kr%2===0?'desni':'lijevi', rd=Math.ceil(kr/2);
    nm=`T${br}.${kr}`; ds=`Vlaka ${br} — ${rd}. ${st} krak`;
  }
  document.getElementById('np').textContent = nm;
  document.getElementById('nd').textContent = ds;
  const brecNm = document.getElementById('brec-nm');
  if (brecNm && !recOn) brecNm.textContent = nm; // ne mijenjaj dok snima
  return {nm, br, kr};
}
updPrev();

// === VLAKA ===
// Segmented gumbi — wrapperi koji prebacuju na kartu
function togSnimVlaku() {
  if (recOn) { stopRec(); return; }
  _openVlakaPicker();
}

function _projQuickRec() {
  if (recOn) { switchTab('karta'); return; }
  switchTab('karta');
  setTimeout(() => _openVlakaPicker(), 200);
}

function _nextMainBr() {
  // Numeracija je PO AKTIVNOM PROJEKTU — isto kao _nextKrakNm. Inače bi u novom
  // projektu prvi predloženi broj bio npr. T7 ako drugi projekti imaju T1–T6.
  const used = new Set(
    vlake.filter(v => !v.nm.includes('.') && v.projektId === _aktivniProjektId)
         .map(v => parseInt(v.nm.slice(1)))
  );
  // I brojevi koje su KOLEGE na projektu već zauzele — inače predloženi broj
  // odmah okine dijalog o duplikatu (dva projektanta na istom odjelu).
  try {
    for (const key in kolegeVlakeMap) {
      const kv = kolegeVlakeMap[key];
      if (kv?.projektId && kv.projektId !== _aktivniProjektId) continue;
      const nm = key.slice(key.indexOf('::') + 2);
      if (nm.includes('.')) continue;
      const n = parseInt(String(nm).replace(/^T/i, ''), 10);
      if (n) used.add(n);
    }
  } catch(e) {}
  let n = 1; while (used.has(n)) n++; return n;
}

let _vpickerMode = 'rec'; // 'rec' | 'trag'

function _openVlakaPicker(mode) {
  _vpickerMode = mode || 'rec';
  const isTrag = _vpickerMode === 'trag';

  const nextBr = _nextMainBr();
  document.getElementById('ibr').value = nextBr;
  document.getElementById('ikr').value = 0;
  updPrev();

  // Naslov pickera
  const titleEl = document.getElementById('vpick-title');
  if (titleEl) titleEl.innerHTML = isTrag
    ? '<span style="font-size:15px;">🔴</span> Snimi trag'
    : '<img src="forwarder.svg" alt="" style="width:20px;height:20px;object-fit:contain;vertical-align:middle;"> Snimi vlaku';

  const list = document.getElementById('vpicker-list');
  list.innerHTML = '';

  // ── Sekcija 1: Nova vlaka ──
  const novBtn = document.createElement('button');
  novBtn.className = 'vpick-action vpick-action--new';
  novBtn.innerHTML = `<span class="vpick-action-ico"><svg class="ic" style="margin:0"><use href="#ic-dodaj"/></svg></span><div class="vpick-action-txt"><b>Nova vlaka T${nextBr}</b><span>Kreiraj i odmah pokreni snimanje</span></div>`;
  novBtn.onclick = () => {
    _closeVlakaPicker();
    if (isTrag) setTimeout(() => addV().then(() => { setTimeout(fabSnimTrag, 30); }), 260);
    else setTimeout(dodiISnimi, 260);
  };
  list.appendChild(novBtn);

  // ── Sekcija 2: Nastavi vlaku/krak (samo u rec modu, ako postoje vlake s tačkama) ──
  const nastavive = vlake.filter(v => v.pts.length > 0);
  if (!isTrag && nastavive.length > 0) {
    const nastaviBtn = document.createElement('button');
    nastaviBtn.className = 'vpick-action vpick-action--nastavi';
    nastaviBtn.innerHTML = `<span class="vpick-action-ico"><svg class="ic" style="margin:0"><use href="#ic-ponovi"/></svg></span><div class="vpick-action-txt"><b>Nastavi vlaku / krak</b><span>Odaberi tačku odakle nastavljaš</span></div>`;
    nastaviBtn.onclick = () => {
      // Prebaci listu u nastavi mod
      _vpickerMode = 'nastavi';
      const titleEl2 = document.getElementById('vpick-title');
      if (titleEl2) titleEl2.innerHTML = '↪ Nastavi vlaku';
      _renderVlakaList();
    };
    list.appendChild(nastaviBtn);
  }

  // ── Sekcija 3: Postojeće vlake ──
  if (vlake.length > 0) {
    const sep = document.createElement('div');
    sep.className = 'vpick-sep-label';
    sep.textContent = isTrag ? 'Ili snimi trag na postojećoj' : 'Postojeće vlake';
    list.appendChild(sep);
    _appendVlakaRows(list, isTrag);
  }

  const sub = document.getElementById('vpick-sub');
  if (sub) {
    const akt = _aktivniProjektId ? _projekti.find(p => p.id === _aktivniProjektId) : null;
    sub.textContent = akt ? [akt.gj, akt.odjel].filter(Boolean).join(' · ') : '';
  }
  document.getElementById('vlaka-picker').classList.add('open');
  document.getElementById('vpicker-overlay').style.display = 'block';
  const inp = document.getElementById('vpick-input');
  if (inp) { inp.value = ''; _vpickFilter(); setTimeout(() => inp.focus(), 320); }
}

function _renderVlakaList() {
  const list = document.getElementById('vpicker-list');
  list.innerHTML = '';
  const isNastavi = _vpickerMode === 'nastavi';

  if (isNastavi) {
    const backBtn = document.createElement('button');
    backBtn.className = 'vpick-action vpick-action--back';
    backBtn.innerHTML = `<span class="vpick-action-ico">‹</span><div class="vpick-action-txt"><b>Nazad</b></div>`;
    backBtn.onclick = () => { _vpickerMode = 'rec'; _openVlakaPicker('rec'); };
    list.appendChild(backBtn);

    const sep = document.createElement('div');
    sep.className = 'vpick-sep-label';
    sep.textContent = 'Odaberi vlaku za nastavak';
    list.appendChild(sep);
  }

  _appendVlakaRows(list, false);
}

function _appendVlakaRows(list, isTrag) {
  const isNastavi = _vpickerMode === 'nastavi';
  // Po stablu (krak ispod svoje vlake), ne redom nastanka — isti indeks i ostaje.
  _vlRedoslijed(vlake, _aktivniProjektId).forEach(({ i, depth }) => {
    const v = vlake[i];
    if (isNastavi && v.pts.length === 0) return;
    const row = document.createElement('div');
    row.className = 'vpick-row' + (depth ? ' krak' : '');
    row.dataset.nm = v.nm;
    const d = fmtL(calcL(v.pts));
    const elv = _elevHtml(v.pts);
    let btnHtml, clickFn;
    if (isNastavi) {
      btnHtml = `<button class="vpick-rec vpick-rec--nastavi" onclick="event.stopPropagation();_pickNastaviVlaka(${i})"><svg class="ic"><use href="#ic-ponovi"/></svg> Nastavi</button>`;
      clickFn = () => _pickNastaviVlaka(i);
    } else if (isTrag) {
      btnHtml = `<button class="vpick-rec" onclick="event.stopPropagation();_pickVlakaForTrag(${i})"><svg class="ic"><use href="#ic-snimaj"/></svg> Trag</button>`;
      clickFn = () => _pickVlakaForTrag(i);
    } else {
      btnHtml = `<button class="vpick-rec" onclick="event.stopPropagation();_pickVlaka(${i})"><svg class="ic"><use href="#ic-pocni"/></svg> Snimi</button>`;
      clickFn = () => _pickVlaka(i);
    }
    row.innerHTML = `
      <div class="vpick-color" style="background:${_escHtml(v.color || '#64748b')};"></div>
      <div class="vpick-info">
        <div class="vpick-nm">${_escHtml(v.nm)}${v.lager ? ' <span style="color:#fbbf24;font-size:11px;font-weight:600;">· ' + _escHtml(v.lager) + '</span>' : ''}</div>
        <div class="vpick-meta">${d}${elv ? ' · '+elv : ''} · ${v.pts.length} tač.</div>
      </div>
      ${btnHtml}`;
    row.onclick = clickFn;
    list.appendChild(row);
  });
}

function _closeVlakaPicker() {
  VlakaKeyboard.unmount(document.getElementById('vpick-keyboard'));
  document.getElementById('vpick-keyboard').hidden = true;
  document.getElementById('vpick-input').blur();
  document.getElementById('vlaka-picker').classList.remove('open');
  document.getElementById('vpicker-overlay').style.display = 'none';
}

function _pickVlaka(i) {
  _closeVlakaPicker();
  setTimeout(() => {
    selI(i);
    switchTab('karta');
    _showKrakIzbor(i);
  }, 260);
}

function _pickVlakaForTrag(i) {
  _closeVlakaPicker();
  setTimeout(() => {
    selI(i);
    switchTab('karta');
    fabSnimTrag();
  }, 260);
}
// ─── Krak izbor modal (prije početka snimanja) ────────────────────────────────
let _krakIzborVlakaIdx = null;

function _showKrakIzbor(i) {
  _krakIzborVlakaIdx = i;
  const v = vlake[i];
  const set = (id, txt) => { const el = document.getElementById(id); if (el) el.textContent = txt; };
  set('krak-izbor-title', v ? v.nm : '');
  const meta = v ? [fmtL(calcL(v.pts)), v.pts.length + ' tač.', v.lager ? 'lager ' + v.lager : ''].filter(Boolean).join(' · ') : '';
  set('krak-izbor-meta', meta);
  const bo = document.getElementById('krak-izbor-boja');
  if (bo) bo.style.background = (v && v.color) || '#fbbf24';
  // Ime kraka koji će nastati — ranije je pisalo samo "Lijevi krak", pa se broj
  // saznavao tek poslije starta (a krakovi se na terenu vode po broju).
  set('ki-go-nm', v ? 'Nastavi ' + v.nm : 'Nastavi vlaku');
  set('ki-l-nm', v ? _nextKrakNm(v.nm, 'L') : 'Lijevi');
  set('ki-d-nm', v ? _nextKrakNm(v.nm, 'D') : 'Desni');
  _rsList('krak-izbor', true);
}

function _krakIzborClose() {
  _rsList('krak-izbor', false);
  _krakIzborVlakaIdx = null;
}

// Donji listovi toka snimanja (v1.9.0): list + njegova pozadina (id + '-bg').
// Pozadina je obavezna — bez nje dodir "pored" okvira ide na kartu ispod.
function _rsList(id, otvori) {
  const el = document.getElementById(id);
  const bg = document.getElementById(id === 'lager-dlg' ? 'lager-bg' : id + '-bg');
  if (el) el.style.display = otvori ? 'block' : 'none';
  if (bg) bg.style.display = otvori ? 'block' : 'none';
}

function _krakIzborDirektno() {
  const i = _krakIzborVlakaIdx;
  _krakIzborClose();
  if (i === null) return;
  selI(i);
  togRec();
}

function _krakIzborStrana(strana) {
  const i = _krakIzborVlakaIdx;
  _krakIzborClose();
  if (i === null) return;
  selI(i);
  togRec();
  // Kreiraj krak čim snimanje krene (roditeljska vlaka mora imati barem jednu tačku)
  setTimeout(() => noviKrakStrana(strana), 200);
}

// ─── Picker search/number input ───────────────────────────────────────────────

// Parsiraj unos u picker inputu: "14" → {br:14,kr:0} ; "14.5" → {br:14,kr:5}
function _parseVNum(s) {
  s = s.trim().replace(/^[Tt]/, '');
  if (!s) return null;
  const parts = s.split('.');
  const br = parseInt(parts[0]);
  const kr = parts.length > 1 ? parseInt(parts[1]) : 0;
  if (isNaN(br)) return null;
  return { br, kr, nm: kr === 0 ? `T${br}` : `T${br}.${kr}` };
}

// Filtriraj listu u pickeru prema unosu
function _vpickFilter() {
  const raw = (document.getElementById('vpick-input')?.value || '').trim().replace(/^[Tt]/, '');
  const list = document.getElementById('vpicker-list');
  if (!list) return;
  // Ažuriraj dimming na svakom redu
  list.querySelectorAll('.vpick-row').forEach(row => {
    const nm = row.dataset.nm || '';
    const match = !raw || nm.toLowerCase().replace(/^t/,'').startsWith(raw.toLowerCase());
    row.style.opacity = match ? '1' : '0.28';
  });
  // Dugme kaže ŠTA će se desiti prije tapa: nova vlaka ili nastavak postojeće.
  const go = document.getElementById('vpick-go');
  if (go) go.textContent = _vpickGoTekst(raw);
}
function _vpickGoTekst(raw) {
  const p = _parseVNum(raw || '');
  if (!p) return 'Idi';
  const ima = vlake.some(v => v.nm === p.nm && v.projektId === _aktivniProjektId);
  return (ima ? '▶ ' : '+ ') + p.nm;
}

// "Idi" — navigiraj na unesenu vlaku ili kreiraj novu
async function _vpickGo() {
  const raw = document.getElementById('vpick-input')?.value || '';
  const p = _parseVNum(raw);
  if (!p) { showToast('Unesi broj npr. 14 ili 14.5'); return; }
  // Pronađi postojeću
  const existing = vlake.findIndex(v => v.nm === p.nm && v.projektId === _aktivniProjektId);
  if (existing !== -1) {
    if (_vpickerMode === 'nastavi') { _pickNastaviVlaka(existing); return; }
    _closeVlakaPicker();
    setTimeout(() => {
      if (_vpickerMode === 'trag') { selI(existing); switchTab('karta'); fabSnimTrag(); }
      else { selI(existing); switchTab('karta'); togRec(); }
    }, 260);
    return;
  }
  // Kreiraj novu
  _closeVlakaPicker();
  if (p.kr === 0) {
    // Matična vlaka
    document.getElementById('ibr').value = p.br;
    document.getElementById('ikr').value = 0;
    updPrev();
    setTimeout(async () => {
      await _doCreateVlaka(p.br, 0);
      if (_vpickerMode === 'trag') fabSnimTrag(); else togRec();
    }, 260);
  } else {
    // Krak — pronađi ili kreiraj roditelja
    const parts = p.nm.split('.');
    const parentNm = parts.slice(0, -1).join('.');
    let parIdx = vlake.findIndex(v => v.nm === parentNm && v.projektId === _aktivniProjektId);
    if (parIdx < 0) {
      const parParts = parentNm.replace(/^T/,'').split('.');
      const parBr = parseInt(parParts[0]);
      const parKr = parParts.length > 1 ? parseInt(parParts[1]) : 0;
      await _doCreateVlaka(parBr, parKr);
      parIdx = vlake.length - 1;
    }
    document.getElementById('ibr').value = p.br;
    document.getElementById('ikr').value = p.kr;
    updPrev();
    setTimeout(async () => {
      selI(parIdx);
      await _doCreateVlaka(p.br, p.kr);
      if (_vpickerMode === 'trag') fabSnimTrag(); else togRec();
    }, 260);
  }
}

// ─── Nastavi vlaku — odabir vlake i nastavak od tačke na karti ───────────────
let _nastaviMarkers = [];
let _nastaviVlakaIdx = null;

function _pickNastaviVlaka(i) {
  _closeVlakaPicker();
  const v = vlake[i];
  if (!v || v.pts.length === 0) { showToast('Vlaka nema tačaka'); return; }
  _nastaviVlakaIdx = i;
  selI(i);
  switchTab('karta');

  _clearNastaviMarkers();
  const pts = v.pts;
  map.fitBounds(v.poly.getBounds().pad(0.15));

  pts.forEach((p, pi) => {
    const isFirst = pi === 0;
    const isLast = pi === pts.length - 1;
    const radius = (isFirst || isLast) ? 8 : 5;
    const color = isLast ? '#22c55e' : (isFirst ? '#3b82f6' : v.color);
    const mk = L.circleMarker([p.la, p.lo], {
      radius, color, fillColor: color, fillOpacity: 0.85, weight: 2, className: 'nastavi-pt'
    }).addTo(map);
    mk.bindTooltip(isLast ? `${v.nm} kraj — klikni za nastavak` : (isFirst ? `${v.nm} početak` : `tač. ${pi+1}`),
      { permanent: isLast, direction: 'top', className: 'nastavi-tooltip' });
    mk.on('click', () => _nastaviOdTacke(i, pi));
    _nastaviMarkers.push(mk);
  });

  showToast('Klikni na tačku vlake odakle želiš nastaviti snimanje');
}

function _nastaviOdTacke(vIdx, ptIdx) {
  _clearNastaviMarkers();
  const v = vlake[vIdx];
  if (!v) return;

  if (ptIdx < v.pts.length - 1) {
    v.pts = v.pts.slice(0, ptIdx + 1);
    v.poly.setLatLngs(v.pts.map(p => [p.la, p.lo]));
    scheduleVlakaSave(vIdx);
  }

  selI(vIdx);
  togRec();
  showToast(`▶ Nastavljam snimanje ${v.nm} od tačke ${ptIdx + 1}`);
}

function _clearNastaviMarkers() {
  _nastaviMarkers.forEach(mk => map.removeLayer(mk));
  _nastaviMarkers = [];
  _nastaviVlakaIdx = null;
}


// Primarna akcija: kreiraj vlaku i odmah pokreni GPS snimanje
function dodiISnimi() {
  addV().then(() => {
    setTimeout(() => {
      if (actI !== null) {
        switchTab('karta');
        // Lager se na terenu imenuje ODMAH na kamionskom putu (početak snimanja), ne
        // tek na kraju vlake duboko u šumi. _pendingLagerIdx → dijalog se otvori čim
        // snimanje stvarno počne (poslije GPS stabilizacije). Ako se preskoči, stopRec
        // ga ponovo nudi (guard: v.lager).
        _pendingLagerIdx = actI;
        togRec();
      }
    }, 30);
  });
}

// Sekundarna akcija: kreiraj vlaku i aktiviraj ručno crtanje

// ── LANČANO TRASIRANJE PREKO REFERENTNE SLIKE ────────────────────────────────
// Cilj: brzo prevesti ručno ucrtane vlake sa (poravnate) slike u prave vlake bez
// izlaska iz crtanja poslije svake. Tapaš tačke duž vlake, dupli tap = kraj te
// vlake; ako je lančano uključeno, ODMAH se kreira i aktivira sljedeća vlaka.
let _chainTraceOn = false;

function _refStartTrace() {
  if (isReadOnly()) { showToast('Pregledni nalog — samo čitanje'); return; }
  if (!_aktivniProjektId) { showToast('⚠ Prvo aktiviraj projekat'); return; }
  _chainTraceOn = document.getElementById('refkarta-chain')?.checked !== false;
  switchTab('karta');
  addV().then(() => {
    if (actI === null) return;
    mtAddLine();
    showToast('✏ Tapaj tačke duž vlake · dupli tap = kraj' + (_chainTraceOn ? ' → sljedeća' : ''));
  });
}

// Tiho ukloni praznu vlaku (0–1 tačaka) — bez potvrde/servera (prazne se ni ne
// šalju na server, vidi _sbFlushVlakaImpl). Koristi se za odbacivanje zadnje
// (prazne) lančane vlake kad korisnik završi trasiranje.
function _dropEmptyVlaka(i) {
  const v = vlake[i];
  if (!v || (v.pts && v.pts.length >= 2)) return false;
  _removeVlakaMapLayers(v);
  vlake.splice(i, 1);
  if (actI === i) actI = null; else if (actI > i) actI--;
  _saveLocalVlake();
  return true;
}

function _traceFinishAndNext() {
  const prevNm = actI !== null ? (vlake[actI]?.nm || '') : '';
  if (actI !== null) { updateVlakaLabel(actI); sbFlushVlaka(actI); }
  showToast('✓ ' + prevNm + ' — sljedeća vlaka');
  addV().then(() => { if (actI !== null) mtAddLine(); });
}

let _addVBusy = false;
let _addVAfterCreate = null; // callback after vlaka is actually created

// Vrati ime kolege koji već ima vlaku istog imena u aktivnom projektu, ili null.
// kolegeVlakeMap je ključan po `korisnikId::nm` i učitan baš za aktivni projekat.
function _kolegaVlakaDup(nm) {
  try {
    for (const key in kolegeVlakeMap) {
      const kv = kolegeVlakeMap[key];
      if (kv?.projektId && kv.projektId !== _aktivniProjektId) continue;
      const i = key.indexOf('::');
      if (i >= 0 && key.slice(i + 2) === nm) {
        return kolegeVlakeMap[key]?.ime || 'drugi projektant';
      }
    }
  } catch(e) {}
  return null;
}

async function addV() {
  if (_addVBusy) return;
  _addVBusy = true;
  try {
    const {br, kr} = updPrev();
    const nm = kr === 0 ? `T${br}` : `T${br}.${kr}`;
    const existing = vlake.findIndex(v => v.nm === nm && v.projektId === _aktivniProjektId);
    if (existing !== -1) {
      // Show conflict dialog instead of silently skipping
      _vcIdx = existing;
      _vcBr = br; _vcKr = kr;
      document.getElementById('vc-title').textContent = `⚠ Vlaka "${nm}" već postoji`;
      document.getElementById('vlaka-conflict').style.display = 'block';
      return; // will be resumed by vcDelete() or vcAddNext()
    }
    // OBAVIJEST: drugi projektant na ovom projektu već ima vlaku istog imena.
    // Jedinstvenost je po projektu — rijetko jer se dogovaraju, ali upozori.
    const kolegaDup = _kolegaVlakaDup(nm);
    if (kolegaDup) {
      _addVBusy = false;  // pusti dijalog; nastavak ovisi o odgovoru
      const ok = await _dlgConfirm(
        `Vlaka "${nm}" već postoji u projektu — snimio/la ju je ${kolegaDup}.\n\nU istom projektu ne bi smjele postojati dvije iste vlake. Želiš li svejedno kreirati?`,
        { title: '⚠ Ista vlaka već u projektu', okLabel: 'Svejedno kreiraj', cancelLabel: 'Odustani', danger: true }
      );
      if (!ok) return;
      _addVBusy = true;
    }
    await _doCreateVlaka(br, kr);
  } finally {
    _addVBusy = false;
  }
}

let _vcIdx = -1, _vcBr = 1, _vcKr = 0;

function vcZoom() {
  if (_vcIdx < 0 || _vcIdx >= vlake.length) return;
  const v = vlake[_vcIdx];
  if (v.pts.length > 0) map.fitBounds(L.latLngBounds(v.pts.map(p=>[p.la,p.lo])),{padding:[40,40]});
  else showToast('Vlaka nema tačaka — nije crtana');
  selI(_vcIdx);
}
function vcDelete() {
  document.getElementById('vlaka-conflict').style.display = 'none';
  if (_vcIdx >= 0 && _vcIdx < vlake.length) {
    const v = vlake[_vcIdx];
    map.removeLayer(v.poly);
    if (v._steepPolys) v._steepPolys.forEach(p => { try { map.removeLayer(p); } catch(e){} });
    v.wpts.forEach(m=>map.removeLayer(m));
    if (v.labelMk) map.removeLayer(v.labelMk);
    if (v.lagerMk) map.removeLayer(v.lagerMk);
    (v.extraLabels||[]).forEach(m=>map.removeLayer(m));
    sbDeleteVlaka(v);
    vlake.splice(_vcIdx, 1);
    _saveLocalVlake();
    rndList();
  }
  _addVBusy = false;
  addV(); // retry with same br/kr now that the name is free
}
function vcAddNext() {
  document.getElementById('vlaka-conflict').style.display = 'none';
  // Find next free br
  const pid = _aktivniProjektId || null;
  const usedNm = new Set(vlake.filter(v => (v.projektId||null) === pid).map(v => v.nm));
  let br = _vcBr + 1;
  while (usedNm.has(_vcKr === 0 ? `T${br}` : `T${br}.${_vcKr}`)) br++;
  document.getElementById('ibr').value = br;
  document.getElementById('ikr').value = _vcKr;
  updPrev();
  _addVBusy = false;
  addV();
}
function vcCancel() {
  document.getElementById('vlaka-conflict').style.display = 'none';
  _addVBusy = false;
}

async function _doCreateVlaka(br, kr) {
  const nm = kr === 0 ? `T${br}` : `T${br}.${kr}`;
  const color = kr > 0 ? getBojaKraka() : getBojaVlake();
  const poly = L.polyline([],{color,weight:getVlakaWeight(),dashArray:getVlakaDashArray(), lineCap:typeof getVlakaLineCap==='function'?getVlakaLineCap():'round', vlakaOutline:typeof getVlakaOutline==='function'?getVlakaOutline():false,opacity:0.9,pane:'vlakeLines',renderer:_vlakeRenderer}).addTo(map);
  poly.bindTooltip(_escHtml(nm),{sticky:true,opacity:0.9});
  attachPolyClick(poly);
  vlake.push({nm,br,kr,color,lager:'',pts:[],poly,wpts:[],sbId:null,projektId:_aktivniProjektId||null,labelMk:null,lagerMk:null,extraLabels:[],updatedAt:new Date().toISOString()});
  sbFlushVlaka(vlake.length-1);
  cIdx=(cIdx+1)%PAL.length; selC=PAL[cIdx];
  document.querySelectorAll('.cdot').forEach((d,j)=>d.classList.toggle('sel',j===cIdx));
  rndList();
  selI(vlake.length-1);
  // Advance ibr to next free (within active project)
  const _pid = _aktivniProjektId || null;
  const usedBr = new Set(vlake.filter(v => (v.projektId||null) === _pid).map(v => v.br));
  let nextBr = br + 1;
  while (usedBr.has(nextBr)) nextBr++;
  document.getElementById('ibr').value = nextBr;
  document.getElementById('ikr').value = 0;
  updPrev();
}

// ─── Lager dialog ─────────────────────────────────────────────────────────────
let _lagerTargetIdx = null;

async function _showLagerDlg(vIdx, atStart) {
  if (vIdx === null || vIdx < 0 || vIdx >= vlake.length) return;
  const v = vlake[vIdx];
  // Dozvoljeno: matična trasa (kr===0) ILI krak označen "na putu" (naPutu) — oba
  // dobijaju vlastiti lager. Već dodijeljen lager preskačemo.
  if ((v.kr !== 0 && !v.naPutu) || v.lager) return;
  // atStart: poziv na POČETKU snimanja (na kamionskom putu, prije prve tačke) —
  // tad se lager na terenu i imenuje; bez flaga tražimo bar jednu tačku (kraj crtanja/snimanja)
  if (!atStart && v.pts.length === 0) return;
  _lagerTargetIdx = vIdx;
  // Prijedlog: L{br} (npr. T1 → L1, T17 → L17); ako je zauzeto, padamo na sljedeći slobodan
  const preferred = 'L' + v.br;
  const { lbl: fallback } = await nextLagerNum();
  const used = new Set(vlake.map(x => x.lager).filter(Boolean));
  const lbl = !used.has(preferred) ? preferred : fallback;
  document.getElementById('ld-title').textContent = `🏷 Broj lagera za ${v.nm}`;
  document.getElementById('ld-sub').textContent = 'Prijedlog ' + lbl + ' — možeš promijeniti ili preskočiti.';
  document.getElementById('lager-input').value = lbl;
  // Lageri u blizini — jedan lager često služi za više vlaka (blizu / preko puta).
  // Referenca: izlaz na put (kraj) za naPutu krak, inače početak vlake; fallback GPS.
  const nearEl = document.getElementById('ld-nearby');
  if (nearEl) {
    const ref = _lagerRefTacka(v) || (lastP ? { la: lastP.la, lo: lastP.lo } : null);
    let near = [], wide = [];
    if (ref) {
      const seen = new Set();
      vlake.forEach(x => {
        if (x === v || !x.lager || (x.kr !== 0 && !x.naPutu) || seen.has(x.lager)) return;
        if ((x.projektId || null) !== (v.projektId || null)) return;
        const sp = _lagerRefTacka(x);
        if (!sp) return;
        const dd = dst(ref.la, ref.lo, sp.la, sp.lo);
        if (dd > 250) return;
        seen.add(x.lager);
        const safe = String(x.lager).replace(/[^\w\s.-]/g, '');
        (dd <= 20 ? near : wide).push({ safe, nm: x.nm, dd });
      });
    }
    const btn = (o, hi) => `<button onclick="document.getElementById('lager-input').value='${o.safe}'" style="background:${hi?'#134e2b':'#1e3a5f'};border:1px solid ${hi?'#22c55e':'#334155'};border-radius:6px;color:${hi?'#86efac':'#93c5fd'};font-size:12px;font-weight:600;padding:5px 10px;margin:0 5px 5px 0;cursor:pointer;">${o.safe} · kao ${o.nm}${hi?' · <svg class="ic"><use href="#ic-potvrdi"/></svg> ≤20 m':''}</button>`;
    let html = '';
    if (near.length) html += `<div style="font-size:10px;color:#4ade80;margin-bottom:4px;">Preko puta / uz krak (≤20 m — vjerovatno isti lager):</div>${near.map(o=>btn(o,true)).join('')}`;
    if (wide.length) html += `<div style="font-size:10px;color:#64748b;margin:6px 0 4px;">U blizini (zajednički lager za više vlaka):</div>${wide.map(o=>btn(o,false)).join('')}`;
    nearEl.innerHTML = html;
    nearEl.style.display = html ? '' : 'none';
  }
  _rsList('lager-dlg', true);
  setTimeout(() => { document.getElementById('lager-input').select(); }, 80);
}
function lagerDlgOk() {
  const val = document.getElementById('lager-input').value.trim();
  _rsList('lager-dlg', false);
  if (_lagerTargetIdx === null) return;
  const v = vlake[_lagerTargetIdx];
  if (!v) return;
  v.lager = val;
  updateVlakaLabel(_lagerTargetIdx);
  sbFlushVlaka(_lagerTargetIdx);
  _lagerTargetIdx = null;
}
function lagerDlgSkip() {
  _rsList('lager-dlg', false);
  _lagerTargetIdx = null;
}
// ──────────────────────────────────────────────────────────────────────────────

// Gdje lager stoji: ručno postavljen, kraj kraka "na putu", inače početak vlake.
function _lagerRefTacka(x) {
  return x.lagerPt || (x.naPutu && x.kr > 0 ? x.pts[x.pts.length - 1] : x.pts[0]);
}

async function nextLagerNum() {
  const { used, offline } = await _lagerZauzeti();
  let n = 1;
  while (used.has('L' + n)) n++;
  return { lbl: 'L' + n, offline };
}

// Zauzeti brojevi lagera: lokalne vlake + (kad ima veze) cijela šumarija na serveru.
async function _lagerZauzeti() {
  const used = new Set(vlake.map(v => v.lager).filter(Boolean));
  let offline = false;
  if (sbProfile?.sumarija && _mrezaProbaj()) {
    try {
      const timeout = new Promise((_, rej) => setTimeout(() => rej(new Error('timeout')), 3000));
      const query = sb.from('vlake').select('lager').eq('sumarija', sbProfile.sumarija).not('lager', 'is', null);
      const { data } = await Promise.race([query, timeout]);
      if (data) data.forEach(r => { if (r.lager) used.add(r.lager); });
    } catch {
      offline = true;
    }
  } else if (!navigator.onLine) {
    offline = true;
  }
  return { used, offline };
}


function flipVlakaDir() {
  if (actI === null) return;
  const v = vlake[actI];
  if (!v || v.pts.length < 2) { showToast('Nema dovoljno tačaka za okret'); return; }
  v.pts.reverse();
  v.poly.setLatLngs(v.pts.map(p => [p.la, p.lo]));
  updateVlakaLabel(actI);
  scheduleVlakaSave(actI);
  showToast('↔ Smjer promijenjen — pts[0] sad je drugi kraj');
}

function selI(i) {
  actI = i;
  if (typeof _tabReveal === 'function') _tabReveal(i);
  // Brzo označavanje bez ponovnog crtanja liste. VAŽNO: red se traži po
  // data-vi (indeks u vlake[]), NE po poziciji u DOM-u — lista se crta
  // SORTIRANO i hijerarhijski (rootVlake sort + renderWithChildren), a vlake[]
  // je redoslijed nastanka/dolaska sa servera. Ta dva se poklapaju samo
  // slučajno; ranije poređenje `idx === i` je zato znalo označiti SUSJEDNU
  // vlaku (npr. istaknuto "T1.1" dok alati stvarno rade nad "T1") — opasno kod
  // Uredi/Briši. Sada je veza podatak↔red eksplicitna.
  const rows = document.querySelectorAll('#vl .vrow[data-vi]');
  const target = document.querySelector(`#vl .vrow[data-vi="${i}"]`);
  if (target) {
    rows.forEach(row => row.classList.toggle('act', row === target));
    target.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
  } else {
    rndList(); // red još nije nacrtan (npr. poziv iz addV prije rndList)
    // Skrol tek poslije crtanja — opet po data-vi, ne po poziciji u DOM-u.
    setTimeout(() => {
      const r = document.querySelector(`#vl .vrow[data-vi="${i}"]`);
      if (r) r.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
    }, 50);
  }
  updOvl();
  // Enable toolbar buttons that require a selected vlaka
  ['mt-addline','mt-addpt','mt-edit','mt-delnode','mt-merge'].forEach(id => {
    const b = document.getElementById(id); if (b) b.disabled = false;
  });
  _updFabVisibility();
}

function _updKrakBtns() {
  if (actI === null) return;
  const nm = vlake[actI].nm;
  const el = document.getElementById('krak-l-nm');
  const er = document.getElementById('krak-d-nm');
  if (el) el.textContent = _nextKrakNm(nm, 'L');
  if (er) er.textContent = _nextKrakNm(nm, 'D');
}

function _updBanner() {
  if (!recOn || actI === null) return;
  const v = vlake[actI];
  document.getElementById('rec-nm').textContent = v.nm;
  const recBoja = document.getElementById('rec-boja');
  if (recBoja) recBoja.style.background = v.color || '#fbbf24';
  // Prikaži naziv aktivne vlake i na brec gumbu
  const brecNm = document.getElementById('brec-nm');
  if (brecNm) brecNm.textContent = v.nm;
  const parentRow = document.getElementById('rec-parent-row');
  const btnNazad  = document.getElementById('btn-nazad');
  const hasParent = _recParentIdx !== null && vlake[_recParentIdx];
  const abNazad   = document.getElementById('ab-nazad');
  const abNazadNm = document.getElementById('ab-nazad-nm');
  if (hasParent) {
    const par = vlake[_recParentIdx];
    const strand = v.strana === 'L' ? 'Lijevi krak' : v.strana === 'D' ? 'Desni krak' : 'Krak';
    document.getElementById('rec-parent-label').textContent = strand + ' · ' + v.nm;
    document.getElementById('rec-parent-nm').textContent = par.nm;
    parentRow.style.display = 'flex';
    btnNazad.style.display = '';
    btnNazad.innerHTML = '<svg class="ic"><use href="#ic-vrati"/></svg> Vrati na ' + _escHtml(par.nm);
    if (abNazad)   abNazad.style.display = '';
    if (abNazadNm) abNazadNm.textContent = 'Vrati na '+par.nm;
  } else {
    parentRow.style.display = 'none';
    btnNazad.style.display = 'none';
    if (abNazad)   abNazad.style.display = 'none';
    if (abNazadNm) abNazadNm.textContent = '';
  }
  _updKrakBtns();
  _updRecStatusBar();
}

function _updRecStatusBar() {
  if(typeof VlakaDirection!=='undefined')VlakaDirection.refreshRecording();
  const bar = document.getElementById('rec-status-bar');
  if (!bar) return;
  if (!recOn) {
    bar.style.display = 'none';
    rndList();
    return;
  }
  bar.style.display = '';
  bar.classList.toggle('paused', recPaused);
  const v = actI !== null ? vlake[actI] : null;
  document.getElementById('rsb-nm').textContent = v ? v.nm : '';
  document.getElementById('rsb-len').textContent = v ? fmtL(calcL(v.pts)) : '';
  const pauseBtn = document.getElementById('rsb-pause');
  if (recPaused) {
    pauseBtn.textContent = '▶ Nastavi '+(v?.nm||''); pauseBtn.title = 'Nastavi snimanje na odabranoj vlaci';
  } else {
    pauseBtn.textContent = '⏸ Pauza'; pauseBtn.title = 'Pauza';
  }
  const parentDiv = document.getElementById('rsb-parent');
  if (_recParentIdx !== null && vlake[_recParentIdx]) {
    document.getElementById('rsb-parent-nm').textContent = vlake[_recParentIdx].nm;
    parentDiv.style.display = '';
  } else {
    parentDiv.style.display = 'none';
  }
  rndList();
}

// ─── WAKE LOCK — sprečava gašenje ekrana tokom snimanja ──────────────────────
let _wakeLock = null;

// ─── SILENT AUDIO — sprečava suspenziju taba kad se izađe iz browsera ────────
// Android Chrome ne suspenduje tab koji ima aktivan AudioContext s outputom.
let _bgAudioCtx = null;
let _bgAudioSrc = null;

function _startBgAudio() {
  if (_bgAudioCtx) return;
  try {
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    _bgAudioCtx = new AC();
    // 2-sekundni tihi buffer u petlji (0.001 gain = nečujno, ali ne 0 — browser bi ga optimizovao)
    const buf = _bgAudioCtx.createBuffer(1, _bgAudioCtx.sampleRate * 2, _bgAudioCtx.sampleRate);
    _bgAudioSrc = _bgAudioCtx.createBufferSource();
    _bgAudioSrc.buffer = buf;
    _bgAudioSrc.loop = true;
    const gain = _bgAudioCtx.createGain();
    gain.gain.value = 0.001;
    _bgAudioSrc.connect(gain);
    gain.connect(_bgAudioCtx.destination);
    _bgAudioSrc.start();
  } catch(e) {}
}

function _stopBgAudio() {
  try { _bgAudioSrc?.stop(); } catch(e) {}
  try { _bgAudioCtx?.close(); } catch(e) {}
  _bgAudioCtx = null; _bgAudioSrc = null;
}

async function _acquireWakeLock() {
  if (!('wakeLock' in navigator)) return;
  try {
    _wakeLock = await navigator.wakeLock.request('screen');
    _wakeLock.addEventListener('release', () => { _wakeLock = null; _updWakeLockIcon(); });
    _updWakeLockIcon();
  } catch(e) { /* odbijen — niska baterija ili nije podržano */ }
}

async function _releaseWakeLock() {
  if (_wakeLock) { try { await _wakeLock.release(); } catch(e) {} _wakeLock = null; }
  _updWakeLockIcon();
}

// Ponovo uzmi wake lock kad se korisnik vrati na stranicu
// Jednom pokaži savjet za optimizaciju baterije (samo Android)
// Zašto je ovo bitno: WebView-preživljavanje + native GPS bafer (GpsService)
// štite snimanje od Activity uništenja (swipe iz recent apps), ali NE od OEM
// "battery manager"-a (Xiaomi/Samsung/Huawei i sl.) koji agresivno UBIJAJU
// cijeli proces — foreground servis i sve — npr. baš kad stigne telefonski
// poziv, da oslobode resurse. To izbrisano potpuno prekida GPS bafer, ne samo
// stvara prazninu koju bi replay popunio. Standardni Android API lijek je
// izuzeće od Doze/App Standby (isIgnoringBatteryOptimizations) — ne rješava
// svaki OEM specifično, ali stvarno pomaže na dobrom dijelu uređaja.
async function showDeviceSettings() {
  const bridge = window.AndroidDevice;
  if (!bridge || typeof bridge.status !== 'function') {
    await _dlg({title:'Baterija i automatsko pokretanje',msg:'Ove postavke su dostupne u Android APK aplikaciji. Na telefonu otvori Postavke → Aplikacije → Dendro Map.'});
    return;
  }
  let status={}; try { status=JSON.parse(bridge.status()); } catch(e) {}
  const labels = [
    {label:'<b>🔋 Ograničenje baterije</b><small>'+ (status.batteryExempt ? 'Android izuzeće je uključeno · otvori postavke' : 'Dozvoli rad bez ograničenja baterije') +'</small>'},
    {label:'<b>↻ Automatsko pokretanje</b><small>Otvori autostart i uključi Dendro Map</small>'},
    {label:'<b>⚙ Postavke aplikacije</b><small>Xiaomi: Baterija → Bez ograničenja</small>'}
  ];
  const choice=await _dlg({title:'Baterija i automatsko pokretanje',mode:'actions',
    msg:'Za GPS i preuzimanje dok je ekran ugašen. Promjene potvrđuješ u postavkama telefona. Autostart zavisi od proizvođača; ako nema zasebnog ekrana, otvorit će se postavke aplikacije.',actions:labels});
  const method=['openBattery','openAutostart','openAppSettings'][choice];
  if(method && typeof bridge[method] === 'function')try{bridge[method]();}catch(e){showToast('Otvori Postavke → Aplikacije → Dendro Map');}
}
const _BATT_HINT_KEY = 'tvlake_batt_hint_shown';
async function _checkBatteryOptHint() {
  if (typeof AndroidGps === 'undefined' || typeof AndroidGps.hasBatteryOptExemption !== 'function') return;
  if (localStorage.getItem(_BATT_HINT_KEY)) return;
  let exempt = true;
  try { exempt = AndroidGps.hasBatteryOptExemption(); } catch(e) { return; }
  localStorage.setItem(_BATT_HINT_KEY, '1');  // pitaj samo jednom, bez obzira na odgovor
  if (exempt) return;
  const ok = await _dlgConfirm(
    'Da GPS snimanje ne prekine telefonski poziv ili druga aplikacija, dozvoli ovoj aplikaciji rad bez ograničenja baterije.',
    { title: '🔋 Pouzdano snimanje u pozadini', okLabel: 'Otvori postavke' }
  );
  if (ok) { try { AndroidGps.requestBatteryOptExemption(); } catch(e) {} }
}

// Provjera je li odobrenje u međuvremenu OPOZVANO.
// showApp() radi svježi upit SAMO kad je keširani `odobren === false` — dakle
// korisnik koji je bio odobren pa mu je admin opozvao pristup nastavlja raditi
// na zastarjelom keširanom profilu neograničeno dugo (na terenu se app danima
// ne restartuje). Od 20260727_pristup_odobrenje.sql server takvom nalogu ionako
// više ne daje podatke, ali bi UI i dalje izgledao ispravno uz tihe prazne
// odgovore — zbunjujuće. Zato pri svakom povratku u prvi plan (throttle 60 s,
// samo online) osvježimo profil i po potrebi izbacimo na ekran čekanja.
let _lastOdobrenCheck = 0;
async function _provjeriOpozivOdobrenja() {
  if (!sb || !sbUser) return;
  const owner=sbUser.id;
  const now = Date.now();
  if (now - _lastOdobrenCheck < 60000 || !_mrezaProbaj()) return;
  _lastOdobrenCheck = now;
  try {
    // ROK je obavezan: navigator.onLine na terenu laže 'true' na mrtvoj vezi, a
    // Supabase poziv nije fetch() pa nema signal — bez _withTimeout ovaj upit
    // VISI zauvijek (vidi pravilo u CLAUDE.md). Zaglavljen upit ovdje znači i da
    // se _lastOdobrenCheck nikad ne "otključa" korisno, pa provjera prestaje
    // raditi do sljedećeg pokretanja.
    const { data, error } = await _withTimeout(
      sb.from('korisnici').select('*').eq('id', owner).single(), 8000);
    if (sbUser?.id!==owner || error || !data || data.id!==owner) return;
    sbProfile = data;
    _profileSave(data);
    if (data.odobren === false && !data.is_admin && !(typeof AccessPolicy!=='undefined' && AccessPolicy.canUse(data))) {
      _showAuthScreen();
      authShowPending();
    }
  } catch(e) {}
}

document.addEventListener('visibilitychange', async () => {
  const bgWarn = document.getElementById('bg-warning');
  if (document.visibilityState === 'visible') {
    if (bgWarn) bgWarn.style.display = 'none';
    try { _dlgHealOrphanedOverlay(); } catch(e) {}
    // Ponovo uzmi wake lock (browser ga otpušta kad app ide u pozadinu)
    // Sva tri tipa snimanja (vlaka / trag / doznaka pojas) trebaju wake lock.
    // Native GPS bafer (vlaka + trag + doznaka pojas) — popuni prazninu koja
    // je nastala dok je app bio zatvoren/u pozadini (vidi _drainNativeGpsBuffer
    // i GpsService.java). Pokreće se PRIJE čekanja na wake lock: dopuna
    // sinhrono zauzme _busy, pa živi fiks pristigao tokom tog await-a čeka nju.
    const dopuna = _drainNativeGpsBuffer().catch(() => {});
    if (_anyRecOn() && !_wakeLock) await _acquireWakeLock();
    _updWakeLockIcon();
    await dopuna;
    // Je li admin u međuvremenu opozvao pristup ovom nalogu?
    _provjeriOpozivOdobrenja();
    // Ako sam ja admin — ima li novih registracija koje čekaju odobrenje?
    _adminSchedPendingCheck();
    // Povratak u prvi plan — pokušaj sync (online event zna izostati na Androidu)
    if (navigator.onLine && sbUser) {
      _processOfflineQueue();   // red sam odlučuje o vezi
      // Vlake kolega ČIM ima konekcije: realtime u pozadini često tiho padne
      // (Android suspenduje WebSocket) pa su događaji propušteni — po povratku
      // provjeri kanal i povuci svježe vlake (throttle 15s da ne spamamo).
      // Neobavezno — na izmjereno mrtvoj vezi se ne pokušava (v1.8.8).
      const now = Date.now();
      if (now - _lastVisKolegeSync > 15000 && _mrezaProbaj()) {
        _lastVisKolegeSync = now;
        try {
          if (!_rtVlakeChannel || _rtVlakeChannel.state !== 'joined') sbStartRealtime();
          else _schedKolegeFullSync(800);
          // Doznaka: obnovi kanal otvorenog odjela + povuci svježe pojaseve kolega
          _dozEnsureChannel(); _dozSchedCatchup(1000);
        } catch(e) {}
      }
    }
  } else {
    // App ide u pozadinu (kamera, drugi app, zaključavanje) — Android može
    // ubiti WebView. Spasi sve lokalno ODMAH, ne čekaj debounce timer.
    try { if (typeof _saveLocalVlake === 'function') _saveLocalVlake(); } catch(e) {}
    try { if (typeof _dozSaveLivePts === 'function') _dozSaveLivePts(); } catch(e) {}
    // I pokušaj odmah poslati na server (ne samo lokalno) — inače tek nacrtana
    // vlaka ostaje nevidljiva na drugom uređaju dok se debounce ne izvrši.
    try { if (typeof _flushAllPendingVlake === 'function') _flushAllPendingVlake().catch(() => {}); } catch(e) {}
    // Upozorenje "app u pozadini — snimanje može stati" ima smisla SAMO na
    // iOS/PWA gdje pozadinski GPS zaista ne radi. U APK-u (AndroidGps definisan)
    // foreground service drži snimanje živim, pa bi upozorenje bilo pogrešno.
    const _activelyRec = (recOn && !recPaused) || (_tragOn && !_tragPaused) || (_dozGpsOn && !_dozGpsPaused);
    if (_activelyRec && typeof AndroidGps === 'undefined') {
      if (bgWarn) bgWarn.style.display = '';
      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
    }
  }
});

// Posljednja šansa za spas podataka prije nego WebView bude ubijen
window.addEventListener('pagehide', () => {
  try { if (typeof _saveLocalVlake === 'function') _saveLocalVlake(); } catch(e) {}
  try { if (typeof _dozSaveLivePts === 'function') _dozSaveLivePts(); } catch(e) {}
  try { if (typeof _flushAllPendingVlake === 'function') _flushAllPendingVlake().catch(() => {}); } catch(e) {}
});

// Periodični sync — fallback ako 'online' event izostane (čest slučaj na Androidu)
setInterval(async () => {
  if (!navigator.onLine || !sbUser || !sbProfile) return;
  // Terenski podaci čekaju izričit zahtjev. Jedini automatski upis je
  // trajno sačuvan novi projekat, da članstvo ne prethodi roditelju.
  // Sve ispod je neobavezno održavanje (token, tragovi, realtime) — na
  // izmjereno mrtvoj vezi bi svaki od tih poziva visio do svog roka svake minute.
  const stanje = _mrezaStanje();
  const bilaMrtva = stanje === 'nema' || stanje === 'slaba';
  if (!_mrezaProbaj(false, true)) return;
  if (bilaMrtva) {
    // Dodijeljena proba MORA napraviti pravi zahtjev — token/realtime ispod
    // često ne idu na mrežu, pa bi se proba potrošila bez ijednog poziva i app
    // ne bi primijetio da se veza vratila (izmjereno: prazan red = nikad).
    // Uspjeh okida _netVezaVracena (red, osvježavanje, pločice).
    _reloadCoreData();
    return;
  }
  _autoPosaljiNoveProjekte();
  // Osvježi Supabase token da ne istekne nakon dugog offlinea. Rok — na slaboj
  // vezi navigator.onLine laže 'true' pa poziv zna VISITI umjesto pasti; bez
  // roka bi ovaj interval (60s) stao na ovoj liniji zauvijek i nikad ne bi
  // stigao do realtime samoizlječenja ispod.
  try { await _withTimeout(sb.auth.getSession(), 10000); } catch(e) {}
  // Samoizlječenje realtime kanala: ako je socket tiho pao (bez CLOSED eventa),
  // vlake kolega prestaju stizati — ponovo se pretplati (SUBSCRIBED okida catch-up).
  try {
    // 'joining' = biblioteka se upravo prijavljuje (na sporoj vezi traje) — ne
    // ruši joj pokušaj; zakazana obnova (_rtObnovaT) ima prednost.
    if (typeof _rtVlakeChannel !== 'undefined' && !_rtObnovaT &&
        (!_rtVlakeChannel || (_rtVlakeChannel.state !== 'joined' && _rtVlakeChannel.state !== 'joining'))) sbStartRealtime();
  } catch(e) {}
  // Doznaka per-projekat kanal — isti tretman (SUBSCRIBED okida catch-up pojaseva)
  try { _dozEnsureChannel(); } catch(e) {}
}, 60000);

function _updWakeLockIcon() {
  const el = document.getElementById('wakelock-icon');
  if (el) el.style.display = (recOn && _wakeLock) ? '' : 'none';
}

// iOS (Safari/PWA) ne snima GPS u pozadini — upozori korisnika JEDNOM pri prvom snimanju.
function _iosBgRecWarn() {
  if (typeof AndroidGps !== 'undefined') return;  // Android native wrapper — pozadina radi
  const isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent)
    || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
  if (!isIOS) return;
  if (localStorage.getItem('tvlake_ios_bg_warned')) return;
  localStorage.setItem('tvlake_ios_bg_warned', '1');
  _dlgConfirm(
    'Na iPhone-u iOS zaustavlja snimanje kad aplikacija ode u pozadinu. Dok snimaš vlaku, '
    + 'DRŽI aplikaciju otvorenu i ekran upaljen — ne prebacuj na druge aplikacije i ne gasi '
    + 'ekran, inače se GPS trag prekida.',
    { title: '⚠ iPhone — snimanje', okLabel: 'Razumijem' }
  );
}

let _pendingLagerIdx = null;   // dodiISnimi: lager dijalog čeka da snimanje stvarno počne (poslije stabilizacije)

function togRec() {
  if (!recOn) {
    if (actI === null) { showToast('⚠ Prvo dodaj vlaku!'); return; }
    _gpsStabilizeGate(_togRecBegin);
  } else {
    stopRec();
  }
}

// ── Vrijeme snimanja u traci (v1.9.0) — aktivno vrijeme OVE sesije, bez pauza.
// Broji se na istim mjestima gdje i _dayActiveMs (pauza, povratak na roditelja,
// stop), pa se dva broja ne mogu razići.
let _recSesijaMs = 0, _recTimeTimer = null, _recZadnja = null;
function _fmtTrajanje(ms) {
  const s = Math.max(0, Math.floor((ms || 0) / 1000));
  const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), x = s % 60;
  const p2 = n => String(n).padStart(2, '0');
  return h ? h + ':' + p2(m) + ':' + p2(x) : m + ':' + p2(x);
}
function _recTrajanjeMs() {
  return _recSesijaMs + (recOn && !recPaused && _recSegStart > 0 ? Date.now() - _recSegStart : 0);
}
function _recTimeRender() {
  const el = document.getElementById('rec-time');
  if (el) el.textContent = _fmtTrajanje(_recTrajanjeMs());
}

function _togRecBegin() {
    _clearNastaviMarkers();
    recOn = true; recPaused = false; _recParentIdx = null;
    _pauziResetuj(_recPauseWin);   // zaostala pauza prethodne sesije ne smije suditi novim tačkama
    _kfReset(); _lastRecTime = 0; _lastPtAcceptedAt = 0;
    // Timing: početak segmenta
    _initDayTiming();
    _recSegStart = Date.now();
    _recSesijaMs = 0;
    _vlRetrace = null; _vlSesijaPocetak = {};
    if (_recTimeTimer) clearInterval(_recTimeTimer);
    _recTimeTimer = setInterval(_recTimeRender, 1000);
    _recTimeRender();
    if (!_dayWorkStart) { _dayWorkStart = new Date().toISOString(); }
    _saveDayTiming(todayStr());
    const b = document.getElementById('brec');
    if (b) b.classList.add('active');
    const banner = document.getElementById('rec-banner');
    banner.classList.add('show'); banner.classList.remove('paused');
    document.getElementById('btn-pause').textContent = '⏸';
    document.getElementById('rec-stats').textContent = '0 m · 0 tač.';
    _updBanner();
    _updRecStatusBar();
    if (!gpsOn) toggleGPS();
    _bgRecStart();  // wake lock + audio + SW heartbeat + notifikacija + native servis (uklj. battery opt hint)
    _startGpsWatchdog();
    _updFabVisibility();
    _crashStartTimer();   // auto-save svakih 30s
    _crashSaveVlaka(true);
    // dodiISnimi: lager se imenuje na startu (kamionski put) — sad kad je snimanje
    // stvarno počelo (poslije stabilizacije signala), a ne na fiksni tajmer poslije klika.
    if (_pendingLagerIdx != null) {
      const li = _pendingLagerIdx; _pendingLagerIdx = null;
      setTimeout(() => { if (recOn) _showLagerDlg(li, true); }, 500);
    }
}

function stopRec() {
  if (!recOn) return;  // idempotentno — sprječava petlju ako native "Stop" odjekne nazad u JS
  _crashClearVlaka();  // normalno zaustavljanje — nema potrebe za oporavkom
  if (recOn && !recPaused && _recSegStart > 0) {
    _recSesijaMs += Date.now() - _recSegStart;
    _dayActiveMs += Date.now() - _recSegStart;
    _dayWorkEnd = new Date().toISOString();
    _saveDayTiming(todayStr());
  }
  _recSegStart = 0;
  if (_recTimeTimer) { clearInterval(_recTimeTimer); _recTimeTimer = null; }
  _recZadnja = { idx: actI, ms: _recSesijaMs };   // sažetak za "Snimanje završeno"
  _vlRetrace = null;
  recOn = false; recPaused = false; _recParentIdx = null;
  _parentReturnIdx=null;_parentReturnTrimToIdx=-1;
  _pauziZavrsi(_recPauseWin);     // stop usred pauze bi inače ostavio vječno otvoren interval
  _setFreeView(false);
  _clearRecPreview();
  _clearGpsGapMarkers();
  _kfReset(); _lastRecTime = 0;
  if (_precizActive) _precizReset();  // D3-Q: ne ostavljaj dugme zaglavljeno na "n/10"
  _stopGpsWatchdog();   // watchdog je vlaka-specifičan — uvijek stani
  // Wake lock / audio / SW heartbeat / notifikacija / native servis gase se tek ako
  // NIŠTA drugo ne snima (trag ili doznaka pojas mogu i dalje raditi u pozadini).
  _bgRecStopIfIdle();
  _crashStopIfIdle();   // trag koji i dalje snima mora zadržati svoj auto-save
  const b = document.getElementById('brec');
  if (b) b.classList.remove('active');
  const banner = document.getElementById('rec-banner');
  banner.classList.remove('show'); banner.classList.remove('paused');
  document.getElementById('rec-parent-row').style.display = 'none';
  document.getElementById('btn-nazad').style.display = 'none';
  if (actI !== null) {
    // Ukloni rezidualni GPS cik-cak (multipath) prije snimanja finalne dužine.
    const _simplV = vlake[actI];
    if (_simplV && _simplV.pts && _simplV.pts.length >= 3) {
      const _ptsBefore = _simplV.pts.length;
      _simplV.pts = _simplifyRecordedPts(_simplV.pts, _vlakaSimplifyTolM());
      if (_simplV.pts.length < _ptsBefore) {
        _simplV.poly.setLatLngs(_simplV.pts.map(p => [p.la, p.lo]));
      }
    }
    updateVlakaLabel(actI);
    clearTimeout(_vlakaSaveTimers[actI]);
    // Uhvati referencu na vlaku PRIJE async flush-a — actI/vlake se mogu promijeniti
    // tokom await-a (npr. korisnik obriše vlaku) → inače pogrešan toast.
    const _recV = vlake[actI];
    const _recNm = _recV?.nm || '';
    const _recPts = _recV?.pts?.length || 0;
    sbFlushVlaka(actI).then(() => {
      // v1.9.4: na server ide tek ručno — sbId sam znači samo da je RANIJA
      // verzija gore, ne i ova (ranije je tu pisalo "sačuvana na server").
      let ceka = true;
      try { ceka = !_recV?.sbId || _OL.loadQueue().some(o => o.type === 'upsert_vlaka' && o.payload?.id === _recV.sbId); } catch(e) {}
      if (!ceka) showToast(`☁ ${_recNm} sačuvana na server (${_recPts} tačaka)`);
      else showToast(`💾 ${_recNm} sačuvana (${_recPts} tačaka) — kolegama ide na Meni → Server`);
    });
  }
  // Spremi i sve ostale vlake s pending timerima (npr. krak koji se još nije snimio)
  Object.keys(_vlakaSaveTimers).forEach(k => {
    const ki = parseInt(k);
    if (!isNaN(ki) && ki !== actI && _vlakaSaveTimers[ki]) {
      clearTimeout(_vlakaSaveTimers[ki]);
      delete _vlakaSaveTimers[ki];
      sbFlushVlaka(ki);
    }
  });
  if (bufLayers.length > 0) drawBuffers();
  // Ako su doznaka stabla učitana za trenutno otvoreni odjel, tek snimljena vlaka
  // može promijeniti ko je "u dosegu" — ponovo izračunaj bez traženja od korisnika
  // da ručno klikne "Osvježi analizu".
  if (typeof _dozTreePts !== 'undefined' && _dozTreePts.length && _dozSelId) dozTreesAnalyze();
  _updRecStatusBar();
  _showLagerDlg(actI);
  _updFabVisibility();
}

function toggleRecPause() {
  if (!recOn) return;
  recPaused = !recPaused;
  if (recPaused) _pauziOtvoriProzor(_recPauseWin); else _pauziZatvoriProzor(_recPauseWin);
  if (recPaused) _crashSaveVlaka(true);  // tačke do pauze — periodični upis u pauzi stoji
  _kfReset(); _lastRecTime = 0; _lastPtAcceptedAt = 0;
  if (recPaused && _precizActive) _precizReset();  // D3-Q: ne ostavljaj dugme zaglavljeno na "n/10"
  if (recPaused) {
    if (_recSegStart > 0) { _recSesijaMs += Date.now() - _recSegStart; _dayActiveMs += Date.now() - _recSegStart; _recSegStart = 0; }
    _dayWorkEnd = new Date().toISOString();
    _saveDayTiming(todayStr());
  } else {
    _recSegStart = Date.now();
  }
  _recTimeRender();
  const banner = document.getElementById('rec-banner');
  const btn = document.getElementById('btn-pause');
  if (recPaused) {
    banner.classList.add('paused');
    btn.textContent = '▶'; btn.title = 'Nastavi snimanje';
    _clearRecPreview();
    showToast('⏸ Snimanje pauzirano');
  } else {
    banner.classList.remove('paused');
    btn.textContent = '⏸'; btn.title = 'Pauza';
    _updBl2();
    showToast('▶ Snimanje nastavljeno — ' + (actI !== null ? vlake[actI].nm : ''));
  }
  _updRecStatusBar();
  _updFabVisibility();
}

function _setFreeView(val) {
  _recFreeView = val;
  const btn = document.getElementById('btn-freeview');
  if (!btn) return;
  if (_recFreeView) {
    btn.innerHTML = '<svg class="ic"><use href="#ic-pozicija"/></svg><span class="rb-lbl">Prati mene</span>'; btn.style.background = '#14330a';
  } else {
    btn.innerHTML = '<svg class="ic"><use href="#ic-otkljucaj"/></svg><span class="rb-lbl">Slobodan pogled</span>'; btn.style.background = '';
  }
}
function toggleRecFreeView() {
  _setFreeView(!_recFreeView);
  if (!_recFreeView && lastP) map.panTo([lastP.la, lastP.lo], { animate: true, duration: 0.5 });
}

function _krajVlake() {
  if (!recOn) return;
  stopRec();
  _stodaljShow();
}

// Redoslijed vlaka po stablu (T1, T1.1, T1.2, T2, T10 — brojčano, ne kao tekst:
// "T10" ide iza "T2"), samo aktivni projekat. Vraća STVARNE indekse u vlake[] —
// pozicija u listi nije indeks (v3.102.0 pravilo).
function _vlNmDijelovi(nm) {
  return String(nm || '').replace(/^[^\d]*/, '').split('.').map(x => parseInt(x, 10));
}
function _vlCmpNm(a, b) {
  const x = _vlNmDijelovi(a), y = _vlNmDijelovi(b);
  for (let k = 0; k < Math.max(x.length, y.length); k++) {
    const p = x[k], q = y[k];
    if (p === undefined) return -1;
    if (q === undefined) return 1;
    const pn = isNaN(p), qn = isNaN(q);
    if (pn || qn) { if (pn && qn) continue; return pn ? 1 : -1; }
    if (p !== q) return p - q;
  }
  return String(a || '').localeCompare(String(b || ''), 'bs');
}
function _vlRedoslijed(lista, projId, filt) {
  return lista.map((v, i) => ({ v, i }))
    .filter(o => o.v && (!projId || !o.v.projektId || o.v.projektId === projId) && (!filt || filt(o.v)))
    .sort((a, b) => _vlCmpNm(a.v.nm, b.v.nm))
    .map(o => ({ i: o.i, depth: (String(o.v.nm).match(/\./g) || []).length }));
}

function _stodaljShow() {
  const zad = _recZadnja && vlake[_recZadnja.idx] ? _recZadnja : null;
  const zv = zad ? vlake[zad.idx] : null;
  const sub = document.getElementById('sdl-sub');
  // Status slanja javlja toast (lokalno / server) — ovdje samo gdje se radi.
  const akt = _aktivniProjektId ? _projekti.find(p => p.id === _aktivniProjektId) : null;
  if (sub) sub.textContent = akt ? [akt.gj, akt.odjel].filter(Boolean).join(' · ') : '';
  const saz = document.getElementById('sdl-sazetak');
  if (saz) {
    if (zv) {
      const elv = _elevHtml(zv.pts);
      saz.innerHTML = `<div class="rs-karta">
        <div style="display:flex;align-items:center;gap:10px;">
          <span class="rs-swatch" style="height:28px;background:${_escHtml(zv.color || '#fbbf24')};"></span>
          <div style="flex:1;min-width:0;">
            <div style="color:#fbbf24;font-size:17px;font-weight:800;">${_escHtml(zv.nm)}</div>
            ${elv || zv.lager ? `<div style="color:#94a3b8;font-size:12px;margin-top:2px;">${[elv, zv.lager ? 'lager ' + _escHtml(zv.lager) : ''].filter(Boolean).join(' · ')}</div>` : ''}
          </div>
        </div>
        <div class="rs-stat">
          <div><b>${fmtL(calcL(zv.pts))}</b><span>dužina</span></div>
          <div><b>${zv.pts.length}</b><span>tačaka</span></div>
          <div><b>${_fmtTrajanje(zad.ms)}</b><span>vrijeme</span></div>
        </div>
      </div>`;
    } else saz.innerHTML = '';
  }
  const el = document.getElementById('sdl-vlake-list');
  if (el) {
    const red = _vlRedoslijed(vlake, _aktivniProjektId);
    if (!red.length) {
      el.innerHTML = '<div style="color:#64748b;font-size:13px;padding:12px 0;">Nema vlaka. Dodaj vlaku pa klikni Snimi vlaku.</div>';
    } else {
      el.innerHTML = red.map(({ i, depth }) => {
        const v = vlake[i];
        const zadnja = zad && zad.idx === i;
        return `<button class="sdl-red${zadnja ? ' zadnja' : ''}" onclick="_stodaljVratiSe(${i})" style="padding-left:${12 + depth * 16}px;">
          <span class="vpick-color" style="background:${_escHtml(v.color || '#64748b')};"></span>
          <span class="sdl-nm">${depth ? '<span style="color:#64748b;font-weight:400;">↳ </span>' : ''}${_escHtml(v.nm)}</span>
          <span class="sdl-meta">${v.pts.length ? fmtL(calcL(v.pts)) : 'prazna'}</span>
          <span class="sdl-go">▶ Snimi</span>
        </button>`;
      }).join('');
    }
  }
  const sh = document.getElementById('sto-dalje-sheet'), bg = document.getElementById('sto-dalje-bg');
  if (sh) sh.style.display = 'block';
  if (bg) bg.style.display = 'block';
  try { el && el.querySelector('.sdl-red.zadnja')?.scrollIntoView({ block: 'nearest' }); } catch(e) {}
}

function _stodaljOdustani() {
  document.getElementById('sto-dalje-sheet').style.display = 'none';
  document.getElementById('sto-dalje-bg').style.display = 'none';
}

function _stodaljVratiSe(i) {
  _stodaljOdustani();
  selI(i);
  switchTab('karta');
  setTimeout(() => togRec(), 30);
}

// Generiši sljedeće ime kraka: T1.1, T1.2, T3.5, T1.2.1...
// Neparne (1,3,5...) = Lijevi ('L'), Parne (2,4,6...) = Desni ('D')
function _nextKrakNm(parentNm, strana) {
  let n = strana === 'D' ? 2 : 1; // D kreće od 2, L i bez strane od 1
  const step = strana ? 2 : 1;    // s stranom preskačemo po 2, bez slobodan redosljed
  while (vlake.find(v => v.nm === parentNm + '.' + n && v.projektId === _aktivniProjektId)) n += step;
  return parentNm + '.' + n;
}

// Pronađi indeks roditeljske vlake na osnovu imenskog prefiksa
function _parentOf(v) {
  const parts = v.nm.split('.');
  if (parts.length <= 1) return -1;
  const parentNm = parts.slice(0, -1).join('.');
  return vlake.findIndex(x => x.nm === parentNm && x.projektId === v.projektId);
}

// Krak sa ručnim izborom broja (dugi pritisak na ⊕L/⊕D) — krakovi se ne rade
// strogo redom, pa projektant mora moći odmah dodijeliti npr. 5.6 i kad 5.4 ne postoji.
async function noviKrakStranaPick(strana) {
  const drawing = activeTool === 'addline';
  if ((!recOn && !drawing) || actI === null) return;
  const parentV = vlake[actI];
  if (!parentV || parentV.pts.length === 0) { showToast('Snimi bar jednu tačku na vlaci!'); return; }
  const predlog = _nextKrakNm(parentV.nm, strana);
  const val = await _dlgPrompt(
    'Broj kraka (redoslijed ne mora biti strog — npr. ' + parentV.nm + '.6 i prije .4):',
    predlog, { title: '⊕ Krak — izbor broja', vlakaKeyboard: true });
  if (val == null) return;
  const pref = parentV.nm + '.';
  let s = val.trim();
  if (s.startsWith(pref)) s = s.slice(pref.length);   // dozvoli i puno ime i sam broj
  if (!/^\d+$/.test(s)) { showToast('⚠ Unesi broj kraka (npr. 6 → ' + pref + '6)'); return; }
  const n = parseInt(s, 10);
  if (n < 1) { showToast('⚠ Broj kraka mora biti ≥ 1'); return; }
  const fullNm = pref + n;
  if (vlake.find(v => v.nm === fullNm && v.projektId === _aktivniProjektId)) {
    showToast('⚠ Krak ' + fullNm + ' već postoji'); return;
  }
  // Strana iz parnosti (desno parni, lijevo neparni) — mjerodavnija od pritisnutog dugmeta
  noviKrakStrana(n % 2 === 0 ? 'D' : 'L', fullNm);
}

// Direktno kreiraj novi krak bez pickera
function noviKrakStrana(strana, overrideNm) {
  const drawing = activeTool === 'addline';
  if ((!recOn && !drawing) || actI === null) return;
  const parentIdx = actI;
  const parentV   = vlake[parentIdx];
  if (parentV.pts.length === 0) { showToast('Snimi bar jednu tačku na vlaci!'); return; }
  // Snap na najbliže mjesto na matičnoj vlaci — samo kad GPS snima (recOn + lastP).
  // U modu crtanja lastP može biti stali GPS fix iz ranije sesije, pa ignorišemo ga.
  let junctionPt;
  if (recOn && lastP && parentV.pts.length >= 2) {
    junctionPt = _snapToNearestPtOnLine(parentV.pts, lastP.la, lastP.lo);
  } else {
    junctionPt = parentV.pts[parentV.pts.length - 1];
  }
  if (!junctionPt) { showToast('Greška pri pronalasku spoja!'); return; }
  const snapDistM = (recOn && lastP) ? Math.round(dst(lastP.la, lastP.lo, junctionPt.la, junctionPt.lo)) : null;

  const krakNm = overrideNm || _nextKrakNm(parentV.nm, strana);
  const color  = parentV.color;
  const poly   = L.polyline([], { color, weight: getVlakaWeight(), dashArray: getVlakaDashArray(), lineCap:typeof getVlakaLineCap==='function'?getVlakaLineCap():'round', vlakaOutline:typeof getVlakaOutline==='function'?getVlakaOutline():false, opacity: 0.9, pane: 'vlakeLines', renderer: _vlakeRenderer }).addTo(map);
  poly.bindTooltip(_escHtml(krakNm), { sticky: true, opacity: 0.9 });
  attachPolyClick(poly);

  // junctionOnParent: indeks točke na roditeljskoj vlaci gdje krak nastaje.
  // Čuva se kako trim pri povratku koristio precizan indeks, ne GPS u tom trenutku.
  // U modu crtanja koristimo zadnju točku (nema pouzdanog GPS-a za snap).
  const junctionOnParent = (recOn && lastP)
    ? _findJunctionIdx(parentV.pts, { la: lastP.la, lo: lastP.lo })
    : parentV.pts.length - 1;
  // projektId MORA biti naslijeđen od roditelja — bez njega se krak snima na server bez
  // projekta (projekt_id null), _nextKrakNm/_parentOf dedup po projektu ga ne vide, a
  // sakrivanje vlaka po projektu ga preskače.
  const krak = { nm: krakNm, br: parentV.br, kr: parentV.kr + 1, strana: strana || null, color, lager: '', pts: [], poly,
                 wpts: [], sbId: null, projektId: parentV.projektId ?? (_aktivniProjektId || null),
                 projektantIme: getIme(), labelMk: null, lagerMk: null, extraLabels: [],
                 updatedAt: new Date().toISOString(), junctionOnParent };
  vlake.push(krak);
  const krakIdx = vlake.length - 1;

  addPt(krakIdx, junctionPt.la, junctionPt.lo, junctionPt.al || 0);
  updateVlakaLabel(krakIdx);

  if (recOn) {
    _recParentIdx = parentIdx;
    actI = krakIdx;
    // Kalman/medijana ostaju TOPLI dok se aktivno snima — fizička pozicija je ista
    // (stojiš na spoju), a hladni restart bi progutao prvih ~5 fixeva pa bi početak
    // kraka iza spojne tačke bio prava linija od više metara. _kfSoftReset() briše
    // samo "momentum" starog pravca (reset samo iz pauze — stanje je staro).
    _kfSoftReset();
    selI(krakIdx);
    _updBanner();
  } else {
    _stopAddLine(false);
    _recParentIdx = parentIdx;
    actI = krakIdx;
    selI(krakIdx);
    mtAddLine();
  }
  sbFlushVlaka(krakIdx);
  rndList();
  const label = strana === 'L' ? 'lijevi' : 'desni';
  const snapInfo = snapDistM != null ? ` · spojen na ${snapDistM}m od GPS` : '';
  showToast(`⊕ Novi ${label} krak ${krakNm}${snapInfo}`);
}

// Picker za nastavak postojećeg kraka
function _updBl2() {
  if (actI === null) return;
  const v = vlake[actI];
  if (!v) return;
  document.getElementById('rec-stats').textContent = `${fmtL(calcL(v.pts))} · ${v.pts.length} tač.`;
  _updSlope();
}

// ─── NAGIB U REALNOM VREMENU ─────────────────────────────────────────────────
function _calcRecentSlope(pts) {
  if (pts.length < 2) return null;
  const last = pts[pts.length - 1];
  // D3-P: zadnja tačka nakon GPS-prekida je teleport, ne stvarni teren — sačekaj
  // par novih tačaka prije nego ponovo prikažemo nagib.
  if (last.gap) return null;
  if (!last.al) return null;
  // Traži tačku ~30m unazad za stabilniji nagib (GPS alt je bučan). Zaustavi se
  // (bez rezultata) ako put nazad prelazi preko GPS-prekid segmenta.
  let i = pts.length - 2, cumDist = 0;
  while (i > 0) {
    if (pts[i + 1].gap) return null;
    cumDist += dst(pts[i].la, pts[i].lo, pts[i + 1].la, pts[i + 1].lo);
    if (cumDist >= 30) break;
    i--;
  }
  const horizDist = dst(pts[i].la, pts[i].lo, last.la, last.lo);
  if (horizDist < 8 || !pts[i].al) return null;
  return (last.al - pts[i].al) / horizDist * 100;
}

function _updSlope() {
  const el = document.getElementById('rec-slope');
  if (!el || !recOn || actI === null) { if (el) el.style.display = 'none'; return; }
  const slope = _calcRecentSlope(vlake[actI]?.pts || []);
  if (slope === null) { el.style.display = 'none'; return; }
  const abs = Math.abs(slope);
  const arrow = slope >= 0 ? '↗' : '↘';
  el.style.color = abs > 18 ? '#f87171' : abs > 12 ? '#fbbf24' : '#4ade80';
  el.textContent = `${arrow}${abs.toFixed(1)}%`;
  el.style.display = '';
}

function _updDrawStats() {
  if (activeTool !== 'addline' || actI === null) return;
  const v = vlake[actI];
  if (!v) return;
  document.getElementById('draw-stats').textContent = `${fmtL(calcL(v.pts))} · ${v.pts.length} tač.`;
}

// Index vlake na koju smo se vratili — koristi se za trim pri prvoj GPS tački
let _parentReturnIdx = null;
// Tačan indeks na roditeljskoj vlaci gdje je krak nastao (čuva se pri kreiranju kraka)
let _parentReturnTrimToIdx = -1;

function vratiSeNaRoditelja() {
  if (!recOn || _recParentIdx === null) return;
  const child=vlake[actI],target=vlake[_recParentIdx];
  if(!child || !target || target._deleted || child.projektId!==target.projektId) {showToast('Roditeljska vlaka nije dostupna u ovom projektu');return;}
  const krakIdx = actI;
  if (krakIdx !== null) {
    updateVlakaLabel(krakIdx);
    // Force-spremi krak odmah — ne čekaj debounce; briši key da stopRec ne flushra duplo
    clearTimeout(_vlakaSaveTimers[krakIdx]);
    delete _vlakaSaveTimers[krakIdx];
    sbFlushVlaka(krakIdx);
    // Preuzmi tačan indeks grananja:
    //  - ako je krak kreiran u ovoj sesiji, junctionOnParent je direktno pohranjen
    //  - ako je krak učitan iz baze (nema junctionOnParent), rekomputaj iz prve tačke kraka
    //    (krak.pts[0] je uvijek snap-točka na roditeljskoj vlaci)
    let jIdx = vlake[krakIdx]?.junctionOnParent ?? -1;
    if (jIdx < 0 && vlake[krakIdx]?.pts?.length > 0 && vlake[_recParentIdx]?.pts?.length > 0) {
      jIdx = _findJunctionIdx(vlake[_recParentIdx].pts, vlake[krakIdx].pts[0]);
    }
    _parentReturnTrimToIdx = jIdx;
  }
  const newActiveIdx = _recParentIdx;
  const parent = vlake[newActiveIdx];

  // Pronađi djeda — roditelja roditelja (za dublje gniježđenje)
  const grandparentI = _parentOf(parent);
  actI = newActiveIdx;
  _recParentIdx = grandparentI >= 0 ? grandparentI : null;
  _kfReset(); _lastRecTime = 0;
  selI(actI);

  // Postavi flag: na prvoj GPS tački po nastavku, odreži parent do tačke grananja
  _parentReturnIdx = newActiveIdx;

  // Auto-pauziraj — povratak se ne snima; obračunaj aktivno vrijeme (kao toggleRecPause)
  if (_recSegStart > 0) { _recSesijaMs += Date.now() - _recSegStart; _dayActiveMs += Date.now() - _recSegStart; _recSegStart = 0; }
  _dayWorkEnd = new Date().toISOString();
  _saveDayTiming(todayStr());
  if(!recPaused)_pauziOtvoriProzor(_recPauseWin);
  recPaused = true;
  _lastPtAcceptedAt=0;
  if(_precizActive)_precizReset();
  _clearRecPreview();
  const banner = document.getElementById('rec-banner');
  const btn = document.getElementById('btn-pause');
  banner.classList.add('paused');
  btn.textContent = '▶';
  btn.title = 'Nastavi snimanje na vlaci';

  _updBanner();
  _updFabVisibility();

  document.getElementById('rec-stats').textContent = '⏸ Povratak na '+vlake[actI].nm+' — zatim Nastavi';

  showToast('↩ ' + vlake[actI].nm + ' — GPS pauziran. Pritisni ▶ kad stigneš na vlaku.');
}

// === DRAW PREVIEW (used by addline tool) ===
let _prevMoveTimer = null;
function drawPreviewUpdate(latlng) {
  // Throttle to ~30fps max
  if (_prevMoveTimer) return;
  _prevMoveTimer = setTimeout(() => { _prevMoveTimer = null; }, 33);

  const snap = findSnapTarget(latlng);
  if (snap) { showSnapRing(snap); snapTarget = snap; }
  else { hideSnapRing(); snapTarget = null; }

  if (actI === null) return;
  const pts = vlake[actI].pts;
  if (pts.length === 0) {
    // No points yet — remove any stale preview
    if (drawPreviewLine) { map.removeLayer(drawPreviewLine); drawPreviewLine = null; }
    return;
  }
  const useLat = snap ? snap.la : latlng.lat;
  const useLng = snap ? snap.lo : latlng.lng;
  const last = pts[pts.length - 1];
  const coords = [[last.la, last.lo], [useLat, useLng]];
  if (!drawPreviewLine) {
    drawPreviewLine = L.polyline(coords, {
      color: vlake[actI].color, weight: 2,
      opacity: 0.65, dashArray: '8,6', interactive: false
    }).addTo(map);
  } else {
    drawPreviewLine.setLatLngs(coords);
  }
}

// === GPS ===
// ── Radijus krugovi ──────────────────────────────────────────────────────────
let _radiusOn = false;
let _radiusCircles = [];
const _radiusDistances = [50, 100, 200, 500, 1000];

function _togRadiusRings() {
  _radiusOn = !_radiusOn;
  if (_radiusOn) {
    if (!gpsOn) startGPS();
    _drawRadiusRings();
  } else {
    _clearRadiusRings();
  }
  _updGpsSwitch();
}

function _radiusNorthPt(la, lo, meters) {
  const R = 6371000;
  const dLat = meters / R;
  return [la + dLat * 180 / Math.PI, lo];
}

function _geodesicCirclePts(la, lo, radiusM, n) {
  const R = 6371000;
  const lat1 = la * Math.PI / 180;
  const lon1 = lo * Math.PI / 180;
  const d = radiusM / R;
  const pts = [];
  for (let i = 0; i <= n; i++) {
    const brng = (2 * Math.PI * i) / n;
    const lat2 = Math.asin(Math.sin(lat1) * Math.cos(d) + Math.cos(lat1) * Math.sin(d) * Math.cos(brng));
    const lon2 = lon1 + Math.atan2(Math.sin(brng) * Math.sin(d) * Math.cos(lat1), Math.cos(d) - Math.sin(lat1) * Math.sin(lat2));
    pts.push([lat2 * 180 / Math.PI, lon2 * 180 / Math.PI]);
  }
  return pts;
}

function _drawRadiusRings() {
  _clearRadiusRings();
  if (!_radiusOn || !lastP) return;
  const la = lastP.la, lo = lastP.lo;
  _radiusDistances.forEach(r => {
    const pts = _geodesicCirclePts(la, lo, r, 72);
    const c = L.polygon(pts, {
      color: '#3b82f6', weight: 1, opacity: 0.45,
      fillColor: '#3b82f6', fillOpacity: 0.03, dashArray: '6,4', interactive: false
    }).addTo(map);
    const lbl = L.marker(_radiusNorthPt(la, lo, r), {
      icon: L.divIcon({
        className: 'radius-label',
        html: `<span>${r >= 1000 ? (r/1000)+'km' : r+'m'}</span>`,
        iconSize: [0,0], iconAnchor: [-4, 8]
      }), interactive: false
    }).addTo(map);
    _radiusCircles.push(c, lbl);
  });
}

function _updateRadiusRings() {
  if (!_radiusOn || !lastP) return;
  const la = lastP.la, lo = lastP.lo;
  let ci = 0;
  _radiusDistances.forEach(r => {
    const circle = _radiusCircles[ci]; ci++;
    const label = _radiusCircles[ci]; ci++;
    if (circle) circle.setLatLngs(_geodesicCirclePts(la, lo, r, 72));
    if (label) label.setLatLng(_radiusNorthPt(la, lo, r));
  });
}

function _clearRadiusRings() {
  _radiusCircles.forEach(l => map.removeLayer(l));
  _radiusCircles = [];
}

function _initForestSwitch() {
  const fs = document.getElementById('forest-switch');
  if (fs) fs.classList.toggle('on', _forestMode);
}
setTimeout(_initForestSwitch, 100);

// Dugme Lokacija nosi stanje GPS-a: isključen / traži signal / fiks + preciznost.
// Zove se na SVAKI fiks, pa DOM dira samo kad se prikaz stvarno promijeni.
let _locBtnKljuc = '';
function _updLocBtn() {
  const btn = document.getElementById('ab-loc');
  if (!btn) return;
  // _lastGpsFixTime je `let` niže u istom bloku — pri ranom pozivu je u TDZ-u.
  let fixT = 0;
  try { fixT = _lastGpsFixTime || 0; } catch(e) {}
  const svjez = !!lastP && (Date.now() - fixT < 30000);
  const stanje = !gpsOn ? '' : (svjez ? 'gps-ok' : 'gps-trazi');
  const ac = (stanje === 'gps-ok' && isFinite(lastP.ac)) ? Math.round(lastP.ac) : null;
  const ton = ac == null ? '' : ac <= 10 ? '' : ac <= 25 ? 'srednji' : 'slab';
  const kljuc = stanje + '|' + ac + '|' + ton;
  if (kljuc !== _locBtnKljuc) {
    _locBtnKljuc = kljuc;
    btn.classList.toggle('gps-trazi', stanje === 'gps-trazi');
    btn.classList.toggle('gps-ok', stanje === 'gps-ok');
    const acc = document.getElementById('ab-loc-acc');
    if (acc) {
      acc.textContent = ac == null ? '' : '±' + (ac > 99 ? '99+' : ac) + 'm';
      acc.className = 'ab-acc' + (ton ? ' ' + ton : '');
    }
    btn.title = !gpsOn ? 'Moja lokacija (GPS isključen)'
      : stanje === 'gps-ok' ? 'Moja lokacija — preciznost ±' + ac + ' m'
      : 'Moja lokacija — tražim GPS signal';
  }
  _updCentarBtn();
}
function _updCentarBtn() {
  const b = document.getElementById('ab-centar');
  if (b) b.classList.toggle('odmaknuto', !!(_userPannedAway && gpsOn && lastP));
}
// Fiksovi zastanu bez greške (krošnja, tunel) — bez ovoga bi dugme i dalje
// tvrdilo "ima signala". Jeftino: DOM se dira samo na promjenu stanja.
setInterval(() => { if (gpsOn) _updLocBtn(); }, 10000);

function _updGpsSwitch() {
  const sw = document.getElementById('gps-switch');
  if (sw) sw.classList.toggle('on', gpsOn);
  const cs = document.getElementById('compass-switch');
  if (cs) cs.classList.toggle('on', _compassConeOn);
  const rs = document.getElementById('radius-switch');
  if (rs) rs.classList.toggle('on', _radiusOn);
  const fs = document.getElementById('forest-switch');
  if (fs) fs.classList.toggle('on', _forestMode);
  _updLocBtn();
  // Dugme "Snimi trag" mora pokazati STVARNO stanje kad se popup otvori —
  // trag je mogao biti započet negdje drugo (Tragovi tab), pa bi "Snimi
  // trag" ovdje TIHO drugi put pokrenulo/prekinulo snimanje da tekst laže.
  const tt = document.getElementById('ab-loc-trag-txt');
  if (tt) tt.textContent = _tragOn ? 'Završi trag' : 'Snimi trag';
  // Boje nosi CSS (.abp-trag / .on) — prate dnevni i tamni prikaz.
  const tbtn = document.getElementById('ab-loc-trag');
  if (tbtn) tbtn.classList.toggle('on', !!_tragOn);
  _locStatusRender();
}

// Status u "Moja lokacija" (v2.9.9): tačka u boji preciznosti i starost
// zadnjeg fiksa — ispod krošnje fiks zna stati minutama, a ±3 m bez starosti
// izgleda kao da je svjež. Zove se na fiks i svake sekunde dok je popup otvoren.
function _locStatusRender() {
  const p = document.getElementById('ab-loc-popup');
  if (!p) return;
  p.classList.toggle('gps-off', !gpsOn);
  const dot = document.getElementById('abp-dot');
  const age = document.getElementById('gps-age');
  let fixT = 0;
  try { fixT = _lastGpsFixTime || 0; } catch(e) {}
  const s = (gpsOn && lastP && fixT) ? Math.max(0, Math.round((Date.now() - fixT) / 1000)) : null;
  const ac = (s != null && isFinite(lastP.ac)) ? lastP.ac : null;
  const ton = !gpsOn ? 'off' : (ac == null || s > 30) ? 'trazi' : ac <= 5 ? 'dobar' : ac <= 15 ? 'srednji' : 'slab';
  if (dot) dot.className = 'abp-dot ' + ton;
  if (age) age.textContent = s == null ? '' : ' · ' + (s < 3 ? 'sada' : s < 60 ? 'prije ' + s + ' s' : 'prije ' + Math.floor(s / 60) + ' min');
}
let _locPopTimer = null;
function _locPopTimerStart() {
  if (_locPopTimer) return;
  _locPopTimer = setInterval(() => {
    const p = document.getElementById('ab-loc-popup');
    if (!p || p.style.display === 'none') { clearInterval(_locPopTimer); _locPopTimer = null; return; }
    _locStatusRender();
  }, 1000);
}
// Šumski mod nije samoobjašnjiv — dug dodir na čip kaže šta radi, a kratak
// ga uključi/isključi. Poslije dugog dodira klik se ne smije okinuti.
let _locLpT = null, _locLpBio = false;
function _locLongPress(ev) {
  _locLpBio = false;
  clearTimeout(_locLpT);
  _locLpT = setTimeout(() => {
    _locLpBio = true;
    showToast('🌲 Šumski mod: strožije filtrira GPS fiksove (odbacuje nepreciznije) — bolje pod krošnjom, ali tačke stižu rjeđe.');
  }, 550);
}
function _locLongPressStop() { clearTimeout(_locLpT); _locLpT = null; }
function _locChipSumski() {
  if (_locLpBio) { _locLpBio = false; return; }
  _togForestMode();
}

// ─── GPS SIGNAL INDIKATOR u recording banneru ──────────────────────────
function _updRecSignal(ac) {
  const el = document.getElementById('rec-signal');
  if (!el) return;
  if (!recOn) { el.style.display = 'none'; return; }
  el.style.display = '';
  let bg, col, txt;
  if (ac <= 5) { bg = '#dcfce7'; col = '#16a34a'; txt = `±${Math.round(ac)}m`; }
  else if (ac <= 10) { bg = '#fef9c3'; col = '#a16207'; txt = `±${Math.round(ac)}m`; }
  else if (ac <= 15) { bg = '#ffedd5'; col = '#c2410c'; txt = `±${Math.round(ac)}m`; }
  else { bg = '#fee2e2'; col = '#dc2626'; txt = `±${Math.round(ac)}m ✕`; }
  el.style.background = bg;
  el.style.color = col;
  el.textContent = txt;
}

// ─── STABILIZACIJA GPS SIGNALA PRIJE POČETKA SNIMANJA ────────────────────────
// Terenski GPS na startu (hladan prijem, izlazak ispod krošnje/iz džepa) "luta" —
// prvih nekoliko fikseva skače tamo-vamo. Snimanje (vlaka / doznaka pojas / trag) NE
// počinje dok se ne skupi nekoliko UZASTOPNIH fikseva koji su i dovoljno tačni i
// skupljeni oko iste tačke (malo rasipanje = nema lutanja). Uvijek postoji izlaz
// "Započni svejedno" — u gustom sastojku tražena tačnost se zna nikad ne dostići.
const GPS_STAB_ACC      = 12;    // m — tražena tačnost fiksa
const GPS_STAB_SPREAD   = 6;     // m — najveće rasipanje zadnjih fikseva oko centra
const GPS_STAB_NEED     = 4;     // koliko uzastopnih fikseva mora zadovoljiti uslov
const GPS_STAB_FORCE_MS = 9000;  // poslije koliko se nudi "Započni svejedno"

let _gpsStabActive  = false;
let _gpsStabCb      = null;   // onP zove ovo sa svakim fiksom dok čekamo stabilizaciju
let _gpsStabWasOn   = false;  // je li GPS bio uključen prije gate-a (za povratak na odustanak)
let _gpsStabBeginFn = null;

function _gpsStabilizeGate(beginFn) {
  if (_gpsStabActive) return;                          // već čekamo stabilan signal
  if (!navigator.geolocation) { beginFn(); return; }   // nema šta stabilizirati
  _gpsStabActive  = true;
  _gpsStabBeginFn = beginFn;
  _gpsStabWasOn   = gpsOn;
  if (!gpsOn) startGPS();                               // treba nam dotok fikseva za procjenu

  const buf = [];
  _buildGpsStabOverlay();

  _gpsStabCb = (la, lo, ac) => {
    buf.push({ la, lo, ac });
    while (buf.length > GPS_STAB_NEED) buf.shift();
    const cLa = buf.reduce((s, p) => s + p.la, 0) / buf.length;
    const cLo = buf.reduce((s, p) => s + p.lo, 0) / buf.length;
    const spread = buf.length >= 2 ? Math.max(...buf.map(p => dst(cLa, cLo, p.la, p.lo))) : null;
    const ready = buf.length >= GPS_STAB_NEED && ac <= GPS_STAB_ACC && spread != null && spread <= GPS_STAB_SPREAD;
    _updGpsStabOverlay(ac, spread, buf.length, ready);
    if (ready) _gpsStabFinish(true);
  };

  setTimeout(() => {
    const f = document.getElementById('gstab-force');
    if (f && _gpsStabActive) f.style.display = '';
  }, GPS_STAB_FORCE_MS);
}

function _gpsStabFinish(ok) {
  if (!_gpsStabActive) return;
  _gpsStabActive = false;
  _gpsStabCb = null;
  const ov = document.getElementById('gstab-overlay');
  if (ov) ov.remove();
  const fn = _gpsStabBeginFn;
  _gpsStabBeginFn = null;
  if (ok) { if (fn) fn(); }
  else {
    _pendingLagerIdx = null;             // odustao u "Dodaj i snimi" toku — ne nudi lager kasnije
    if (!_gpsStabWasOn) stopGPS();       // GPS je bio ugašen prije gate-a — vrati u prethodno stanje
  }
}
function _gpsStabForce()  { showToast('▶ Započeto uz nestabilan signal'); _gpsStabFinish(true); }
function _gpsStabCancel() { _gpsStabFinish(false); showToast('✕ Snimanje otkazano'); }

function _buildGpsStabOverlay() {
  if (document.getElementById('gstab-overlay')) return;
  const d = document.createElement('div');
  d.id = 'gstab-overlay';
  d.style.cssText = 'position:fixed;inset:0;z-index:99998;background:rgba(2,6,23,0.74);backdrop-filter:blur(3px);display:flex;align-items:center;justify-content:center;padding:24px;';
  d.innerHTML = `
    <div style="background:#0f172a;border:1.5px solid #1e3a5f;border-radius:16px;padding:22px 20px 16px;max-width:330px;width:100%;box-shadow:0 14px 44px rgba(0,0,0,0.6);text-align:center;">
      <div style="width:50px;height:50px;margin:2px auto 14px;border:4px solid #1e3a5f;border-top-color:#38bdf8;border-radius:50%;animation:gstabspin 0.9s linear infinite;"></div>
      <div style="font-size:15px;font-weight:bold;color:#e2e8f0;margin-bottom:4px;">📡 Stabiliziram GPS signal…</div>
      <div style="font-size:12px;color:#94a3b8;margin-bottom:14px;line-height:1.5;">Sačekaj da signal prestane lutati — snimanje počinje čim se smiri.</div>
      <div id="gstab-metrics" style="display:flex;gap:6px;justify-content:center;margin-bottom:16px;">
        <div class="gstab-m"><span>Tačnost</span><b id="gstab-acc" style="color:#475569;">—</b></div>
        <div class="gstab-m"><span>Lutanje</span><b id="gstab-spr" style="color:#475569;">—</b></div>
        <div class="gstab-m"><span>Fiksevi</span><b id="gstab-cnt" style="color:#475569;">0/${GPS_STAB_NEED}</b></div>
      </div>
      <div style="display:flex;gap:8px;">
        <button onclick="_gpsStabCancel()" style="flex:1;padding:10px;background:#1e293b;border:1px solid #334155;border-radius:9px;color:#94a3b8;font-size:13px;font-weight:600;cursor:pointer;">Odustani</button>
        <button id="gstab-force" onclick="_gpsStabForce()" style="display:none;flex:1;padding:10px;background:#422006;border:1px solid #92400e;border-radius:9px;color:#fbbf24;font-size:13px;font-weight:600;cursor:pointer;">Započni svejedno</button>
      </div>
    </div>`;
  document.body.appendChild(d);
}

function _updGpsStabOverlay(ac, spread, n, ready) {
  const accEl = document.getElementById('gstab-acc');
  const sprEl = document.getElementById('gstab-spr');
  const cntEl = document.getElementById('gstab-cnt');
  if (accEl) { accEl.textContent = `±${Math.round(ac)}m`; accEl.style.color = ac <= 8 ? '#4ade80' : ac <= GPS_STAB_ACC ? '#fbbf24' : '#f87171'; }
  if (sprEl) { sprEl.textContent = spread == null ? '—' : `${spread.toFixed(1)}m`; sprEl.style.color = spread == null ? '#475569' : spread <= GPS_STAB_SPREAD ? '#4ade80' : '#f87171'; }
  if (cntEl) { cntEl.textContent = `${Math.min(n, GPS_STAB_NEED)}/${GPS_STAB_NEED}`; cntEl.style.color = ready ? '#4ade80' : '#e2e8f0'; }
}

// ─── PRECIZNA TAČKA (accuracy-weighted prosjek N fikseva) ──────────────
let _precizActive = false;
let _precizBuf = [];  // [{la, lo, ac}]
let _precizTimer = null;
const _PRECIZ_N = 10;

function _precizReset() {
  _precizActive = false;
  _precizBuf = [];
  if (_precizTimer) { clearTimeout(_precizTimer); _precizTimer = null; }
  const btn = document.getElementById('btn-preciz');
  if (btn) { btn.innerHTML = '<svg class="ic"><use href="#ic-pozicija"/></svg><span class="rb-lbl">Precizna tačka</span>'; btn.style.background = '#1e3a5f'; btn.style.color = '#38bdf8'; }
}

function _precizTacka() {
  if (!recOn || recPaused || actI === null) { showToast('⚠ Snimanje mora biti aktivno'); return; }
  if (_precizActive) return;
  _precizActive = true;
  _precizBuf = [];
  const btn = document.getElementById('btn-preciz');
  if (btn) { btn.innerHTML = '<svg class="ic"><use href="#ic-cekanje"/></svg><span class="rb-lbl">Stoj mirno…</span>'; btn.style.background = '#14532d'; btn.style.color = '#4ade80'; }
  showToast(`📍 Stojte mirno — prikupljam ${_PRECIZ_N} fikseva...`);
  // Timeout: ako GPS ne isporuči dovoljno fikseva za 30s, oslobodi dugme (spriječi trajno zaglavljenje)
  if (_precizTimer) clearTimeout(_precizTimer);
  _precizTimer = setTimeout(() => {
    if (_precizActive) {
      if (_precizBuf.length >= 3) { _precizFinish(); }
      else { _precizReset(); showToast('⚠ Precizna tačka prekinuta — slab GPS signal'); }
    }
  }, 30000);
}

function _precizCollect(la, lo, ac) {
  if (!_precizActive) return;
  // Pauza/stop tokom prikupljanja → odustani, ne ubacuj tačku u neaktivnu vlaku
  if (!recOn || recPaused || actI === null) { _precizReset(); return; }
  _precizBuf.push({ la, lo, ac });
  const btn = document.getElementById('btn-preciz');
  if (btn) btn.innerHTML = `<b>${_precizBuf.length}/${_PRECIZ_N}</b><span class="rb-lbl">Stoj mirno…</span>`;
  if (_precizBuf.length >= _PRECIZ_N) {
    _precizFinish();
  }
}

function _precizFinish() {
  _precizActive = false;
  if (_precizTimer) { clearTimeout(_precizTimer); _precizTimer = null; }
  const btn = document.getElementById('btn-preciz');
  if (btn) { btn.innerHTML = '<svg class="ic"><use href="#ic-pozicija"/></svg><span class="rb-lbl">Precizna tačka</span>'; btn.style.background = '#1e3a5f'; btn.style.color = '#38bdf8'; }
  if (!_precizBuf.length || actI === null || !recOn || recPaused) { _precizBuf = []; return; }
  let sumW = 0, wLa = 0, wLo = 0;
  _precizBuf.forEach(p => {
    const w = 1 / (p.ac * p.ac);
    wLa += p.la * w;
    wLo += p.lo * w;
    sumW += w;
  });
  const avgLa = wLa / sumW;
  const avgLo = wLo / sumW;
  const avgAc = Math.sqrt(1 / sumW);
  addPt(actI, avgLa, avgLo, lastP ? lastP.al : 0);
  showToast(`📍 Precizna tačka: ±${avgAc.toFixed(1)}m (${_precizBuf.length} fikseva)`);
  _precizBuf = [];
}
function _togCompassSwitch() {
  togCompassCone();
  _updGpsSwitch();
}
function toggleGPS() {
  if (!gpsOn) startGPS(); else stopGPS();
}
function startGPS() {
  if (!navigator.geolocation) { showToast('⚠ Uređaj ne podržava GPS!'); return; }
  gpsOn = true;
  document.getElementById('gps-info').textContent = 'Tražim signal…';
  if (!_compassConeOn) togCompassCone();
  _updGpsSwitch();
  wid = navigator.geolocation.watchPosition(onP, onPE, {
    enableHighAccuracy: true, maximumAge: 0, timeout: 20000
  });
}
function stopGPS() {
  if (wid) navigator.geolocation.clearWatch(wid);
  gpsOn = false; wid = null; lastP = null;
  _gpsAlt = false;
  _userPannedAway = false;
  // N.V. se vraća na centar karte — inače ostaje visina zadnje GPS pozicije.
  try { const c = map.getCenter(); debouncedUpdElev(c.lat, c.lng, 100); } catch(e) {}
  if (_compassConeOn) togCompassCone();
  _clearRadiusRings(); _radiusOn = false;
  document.getElementById('gps-info').textContent = 'Isključen';
  _updGpsSwitch();
  _updMcdDist();
}

// ── KOMPAS / SMJER TELEFONA ──────────────────────────────────────────────────
let _compassConeOn = false;

// Vrati novu neomotanu rotaciju najbližu prevAccum koja odgovara targetDeg (0-360)
// — sprječava da CSS tranzicija "odmota" kroz ~350° kad ugao pređe granicu 359°→0°.
function _angContinuity(prevAccum, targetDeg) {
  const prevMod = ((prevAccum % 360) + 360) % 360;
  const diff = ((targetDeg - prevMod + 540) % 360) - 180;
  return prevAccum + diff;
}

function _updCompassOnMarker(heading) {
  if (typeof window !== 'undefined') window.Explorer?.onHeading();
  if (_activeTab === 'teren') terenUpdCompass();
  if (_tackaNavIdx !== null) _updateNavArrows();  // strelica prati okretanje telefona uživo
  if (!posMk) return;
  const el = posMk.getElement();
  if (!el) return;
  const svg = el.querySelector('#loc-svg');
  if (svg) {
    _compassRotCone = _angContinuity(_compassRotCone, heading);
    svg.style.transform = `rotate(${_compassRotCone}deg)`;
    svg.style.transformOrigin = '16px 16px';
  }
  const arrow = el.querySelector('#loc-arrow');
  if (arrow) arrow.style.opacity = _compassConeOn ? '0.85' : '0';
  const cone = el.querySelector('#loc-cone');
  if (cone) cone.style.opacity = _compassConeOn ? '1' : '0';
}

function togCompassCone() {
  _compassConeOn = !_compassConeOn;
  if (_compassConeOn && !gpsOn) startGPS();
  if (posMk) {
    const el = posMk.getElement();
    if (el) {
      const cone = el.querySelector('#loc-cone');
      if (cone) cone.style.opacity = _compassConeOn ? '1' : '0';
      const arrow = el.querySelector('#loc-arrow');
      if (arrow) arrow.style.opacity = _compassConeOn ? '0.85' : '0';
    }
  }
  if (_compassConeOn && _compassHeading != null) _updCompassOnMarker(_compassHeading);
}

function _onDeviceOrientation(e) {
  let heading = null;
  if (typeof e.webkitCompassHeading === 'number') {
    heading = e.webkitCompassHeading;
  } else if (e.alpha !== null && e.alpha !== undefined) {
    heading = (360 - e.alpha) % 360;
  }
  if (heading === null) return;

  // Blagi throttle — senzor zna slati i preko 60 događaja/s, nepotrebno za kompas UI
  const now = Date.now();
  if (now - _compassLastUpdT < 60) return;
  _compassLastUpdT = now;

  // Niskopropusni filter (eksponencijalno zaglađivanje, kružno-svjesno) — sirovi
  // magnetometar jitteruje +-nekoliko stepeni u mjestu, pa bez ovoga kupola/igla
  // vidno "trepere". Kraća put (diff) umjesto sirove razlike izbjegava lažni
  // veliki skok kad heading pređe 359°→0° granicu.
  if (_compassHeading == null) {
    _compassHeading = heading;
  } else {
    const diff = ((heading - _compassHeading + 540) % 360) - 180;
    _compassHeading = (_compassHeading + diff * 0.25 + 360) % 360;
  }
  _updCompassOnMarker(_compassHeading);
}

// Android zna slati OBA eventa istovremeno — 'deviceorientation' tamo često
// nosi RELATIVNI ugao (proizvoljna referenca od trenutka uključivanja senzora,
// ne pravi sjever), dok 'deviceorientationabsolute' nosi stvarni magnetni
// azimut. Kad bi oba hranila isti _compassHeading, kupola/strelica bi se
// "otimala" između dva različita referentna okvira — vidno trzanje i pogrešan
// smjer (prijava: "puno se kreće, ne pokazuje kako treba"). Zato je
// 'deviceorientation' fallback SAMO za iOS (webkitCompassHeading — iOS uopšte
// ne podržava deviceorientationabsolute) ili za uređaje koji apsolutni event
// uopšte ne emituju; kad je apsolutni dostupan, on je JEDINI izvor.
const _hasAbsOrientation = 'ondeviceorientationabsolute' in window;
window.addEventListener('deviceorientation', e => {
  if (typeof e.webkitCompassHeading === 'number') { _onDeviceOrientation(e); return; }
  if (!_hasAbsOrientation && typeof e.alpha === 'number') _onDeviceOrientation(e);
}, true);
// Android: deviceorientationabsolute — pravi (magnetni) sjever
window.addEventListener('deviceorientationabsolute', _onDeviceOrientation, true);

// ─── ŠUMSKI MOD ─────────────────────────────────────────────────────────────
let _forestMode = localStorage.getItem('tvlake_forest_mode') !== '0';

function _togForestMode() {
  _forestMode = !_forestMode;
  localStorage.setItem('tvlake_forest_mode', _forestMode ? '1' : '0');
  const sw = document.getElementById('forest-switch');
  if (sw) sw.classList.toggle('on', _forestMode);
  _kfReset();
  showToast(_forestMode ? '🌲 Šumski mod uključen — strožije filtriranje' : '☀ Standardni mod — brži odziv');
}

// ─── GPS FILTER PARAMETRI ────────────────────────────────────────────
const GPS_MIN_DIST  = 3;
const GPS_MAX_ACC   = 15;
const GPS_MAX_JUMP  = 25;
const GPS_MAX_SPEED = 2.5;
const GPS_STILL_SPD = 0.3;

// ─── GPS RESTART KOORDINACIJA (D3-B) ─────────────────────────────────
// Tri nezavisna trigera (onPE greška, watchdog, sw-ping) dijele jednu stvarnu
// izvedbu restarta — sprječava da blizak dvostruki/trostruki restart iznova
// briše medijan-buffer prije nego se uopće napuni (duplo duži oporavak).
let _lastGpsRestartAt     = 0;
const GPS_RESTART_COOLDOWN = 5000;

// ─── GPS GAP DETEKCIJA (D3-C) ─────────────────────────────────────────
// Pravo zidno-vrijeme zadnje DODANE tačke — namjerno odvojeno od _lastRecTime
// (kojeg restart-funkcije nule radi gašenja speed-gate-a) da preživi restart i
// tačno mjeri prekid, umjesto da se prekid tiho utopi u geometriju traga.
let _lastPtAcceptedAt   = 0;
const GPS_GAP_WARN_MS   = 60000;
// Trajna vizuelna oznaka na karti za dionicu preko prekida — prije je
// postojao samo toast (nestane za par sekundi, lako se propusti ako korisnik
// baš tad ne gleda telefon, npr. dok se vraća u app iz pozadine nakon
// prekida). Marker (NE linija preko dionice) namjerno — nezavisan je od
// v.pts/v.poly, pa ga ne diraju _simplifyRecordedPts (Douglas-Peucker pri
// stopRec) niti pomjeranje indeksa u pts nizu.
let _vlakaGapMarkers = [];
function _markGpsGapOnMap(la, lo, gapMs) {
  const gapSec = Math.round(gapMs / 1000);
  const label = gapSec >= 60 ? Math.round(gapSec / 60) + ' min' : gapSec + ' s';
  const m = L.marker([la, lo], {
    icon: L.divIcon({
      className: '', iconSize: [22, 22], iconAnchor: [11, 11],
      html: '<div style="width:22px;height:22px;border-radius:50%;background:#f59e0b;border:2px solid #fff;display:flex;align-items:center;justify-content:center;font-size:13px;box-shadow:0 1px 4px rgba(0,0,0,0.5);">⚠</div>'
    })
  }).addTo(map);
  m.bindTooltip('GPS prekid ' + label + ' — dionica prije ove tačke je ravna linija (stvarna putanja nije snimljena)', { direction: 'top' });
  _vlakaGapMarkers.push(m);
}
// Ukloni sve oznake prekida sa karte (poziva se pri stopRec — nove oznake se
// pojavljuju samo tokom SLJEDEĆEG snimanja, ne treba ih čuvati poslije).
function _clearGpsGapMarkers() {
  _vlakaGapMarkers.forEach(m => { try { map.removeLayer(m); } catch(e) {} });
  _vlakaGapMarkers = [];
}

// Adaptivno po tačnosti: odličan signal (≤6m — otvoren teren, uz put) ne treba
// medijanu-5 ni u šumskom modu — medijana od 5 prostorno KASNI ~2 fixa iza stvarne
// pozicije i siječe unutrašnju stranu krivina. Pod krošnjama je tačnost tipično
// 8–15m pa puna zaštita (5) ostaje automatski.
function _gpsMedN(ac)  { return _forestMode ? ((ac != null && ac <= 6) ? 3 : 5) : 3; }
function _gpsDistMul() { return _forestMode ? 0.5 : 0.35; }
// D3-S: krakovi vlaka skreću i pod 90°+ — prag mora biti IZNAD pravog ugla (uz GPS
// šum ~90° čita se do ~105°) da se legitiman oštar okret ne odbaci kao multipath.
// Odbacuju se samo near-reversali (>prag, tj. skoro-U-okret = multipath potpis).
function _gpsMaxTurn() { return _forestMode ? 105 : 115; }
function _gpsKfNoise() { return _forestMode ? 0.5 : 1.0; }

// ─── KALMAN FILTER ───────────────────────────────────────────────────────────────────
const KF_MIN_R     = 2.5;
// Vremenska konstanta prilagođavanja brzine/pravca (_kf.vla/_kf.vlo) novom mjerenju.
// Manje = brže "zaboravi" stari pravac kod skretanja/kraka (manje vučenja/isprekidanosti),
// veće = glađe ali sporije reaguje. Skraćeno s 3.0 na 1.2 — I dalje ublažava GPS šum, ali
// bez višesekundnog kašnjenja pri promjeni pravca.
const KF_VEL_TAU   = 1.2;
const MPDEG        = 111320; // ≈ metri po stepenu geografske širine

let _kf          = null;   // Kalman state: {la,lo,vla,vlo,Pla,Plo,t}
let _lastRecTime = 0;

// ─── DIREKTNO SNIMANJE (bez medijane/Kalmana) ────────────────────────────────
// Medijana kasni ~pola prozora iza stvarne pozicije, a Kalman dodatno vuče ka
// predikciji — zajedno prave "stoji pa povuče crtu" umjesto praćenja kretanja.
// Trag se sad upisuje iz SIROVIH fixeva; jedina anti-spike zaštita je
// dvofixna potvrda skoka: izolovan teleport-fix se zadrži JEDAN fix, i upiše
// se tek ako ga sljedeći fix potvrdi (stvaran skok, npr. GPS se vratio poslije
// prekida) — normalno kretanje prolazi bez ikakvog kašnjenja.
let _lastFixRaw     = null;  // {la, lo, t} zadnji prihvaćen sirovi fix
let _pendingJumpFix = null;  // fix odbačen kao mogući spike — čeka potvrdu

// ─── MEDIAN PRE-FILTER ──────────────────────────────────────────────────────────────────
// Čuva zadnja _gpsMedN() prihvatljiva mjerenja i vraća MEDIJANU.
let _gpsBuf = [];   // [{la, lo, ac}]

function _gpsBufReset() { _gpsBuf = []; }

function _gpsMedianPt(la, lo, ac) {
  const N = _gpsMedN(ac);
  _gpsBuf.push({ la, lo, ac });
  while (_gpsBuf.length > N) _gpsBuf.shift();
  if (_gpsBuf.length < N) return null;
  const m = Math.floor(N / 2);
  return {
    la: [..._gpsBuf].sort((a, b) => a.la - b.la)[m].la,
    lo: [..._gpsBuf].sort((a, b) => a.lo - b.lo)[m].lo,
    ac: _gpsBuf.reduce((s, p) => s + p.ac, 0) / _gpsBuf.length
  };
}

function _kfReset() { _kf = null; _gpsBuf = []; _altEma = null; _lastFixRaw = null; _pendingJumpFix = null; }

// Krak/nastavak dok se aktivno snima: ukloni SAMO "momentum" (brzinu/pravac) starog
// segmenta — pozicija/kovarijansa ostaju tople (bez cold-start gubitka prvih fixeva iz
// median-buffera). Bez ovoga Kalman-predikcija nastavlja vući u stari pravac dok se
// _kf.vla/_kf.vlo alpha-prilagode (do KF_VEL_TAU sekundi), pa početak kraka ispadne
// pomjeren, a backstop (predDistM) usput odbaci nekoliko fixeva → isprekidana linija.
function _kfSoftReset() {
  if (recPaused) _kfReset();
  else if (_kf) { _kf.vla = 0; _kf.vlo = 0; }
  _lastRecTime = 0;
}

// ─── LIVE PREVIEW TRAGA ─────────────────────────────────────────────────────
// Upisane tačke i uz direktan upis blago kasne (min-razmak od ~3m čeka pomak prije
// upisa). Isprekidani segment od zadnje upisane tačke do trenutne pozicije markera
// ažurira se na SVAKI fix — trag vidljivo prati korisnika bez ikakvog čekanja.
let _recPrevLine = null;
function _updRecPreview(la, lo) {
  const v = (recOn && !recPaused && actI !== null) ? vlake[actI] : null;
  if (!v || !v.pts.length) { _clearRecPreview(); return; }
  const last = v.pts[v.pts.length - 1];
  const pth = [[last.la, last.lo], [la, lo]];
  if (!_recPrevLine) {
    _recPrevLine = L.polyline(pth, { color: v.color || '#4ade80', weight: 3, opacity: 0.55,
      dashArray: '6 8', interactive: false, pane: 'vlakeLines', renderer: _vlakeRenderer }).addTo(map);
  } else {
    _recPrevLine.setLatLngs(pth);
    if (_recPrevLine.options.color !== (v.color || '#4ade80')) _recPrevLine.setStyle({ color: v.color || '#4ade80' });
  }
}
function _clearRecPreview() {
  if (_recPrevLine) { try { map.removeLayer(_recPrevLine); } catch(e) {} _recPrevLine = null; }
}

function _kfStep(la, lo, ac, tMs) {
  const R     = Math.max(KF_MIN_R, ac);
  const mpdLo = MPDEG * Math.cos(la * Math.PI / 180);

  // Inicijalizacija — medijana daje pouzdan polazni položaj
  if (!_kf) {
    _kf = { la, lo, vla: 0, vlo: 0,
            Pla: (R / MPDEG)  ** 2,
            Plo: (R / mpdLo)  ** 2,
            t: tMs };
    return { la, lo };  // prva snimljena tačka = prva medijana
  }

  const dt = Math.min(10, Math.max(0.05, (tMs - _kf.t) / 1000));
  _kf.t = tMs;

  // Predict
  const predLa = _kf.la + _kf.vla * dt;
  const predLo = _kf.lo + _kf.vlo * dt;
  const qPos   = (_gpsKfNoise() * dt * dt * 0.5) ** 2;
  const Pla    = _kf.Pla + qPos / (MPDEG  * MPDEG);
  const Plo    = _kf.Plo + qPos / (mpdLo  * mpdLo);

  // Ostatni multipath backstop — median nije uhvatio 2+ uzastopna spikea
  const predDistM = dst(predLa, predLo, la, lo);
  if (predDistM > Math.max(GPS_MAX_JUMP * 0.5, ac * 2.0)) {
    _kf.Pla = Math.min(_kf.Pla * 2, (15 / MPDEG) ** 2);
    _kf.Plo = Math.min(_kf.Plo * 2, (15 / mpdLo) ** 2);
    return null;
  }

  // Update
  const Rla = (R / MPDEG)  ** 2;
  const Rlo = (R / mpdLo)  ** 2;
  const Kla = Pla / (Pla + Rla);
  const Klo = Plo / (Plo + Rlo);

  const newLa = predLa + Kla * (la - predLa);
  const newLo = predLo + Klo * (lo - predLo);

  const alpha = Math.min(1, dt / KF_VEL_TAU);
  _kf.vla = (1 - alpha) * _kf.vla + alpha * (newLa - _kf.la) / dt;
  _kf.vlo = (1 - alpha) * _kf.vlo + alpha * (newLo - _kf.lo) / dt;

  const vMs = Math.sqrt((_kf.vla * MPDEG) ** 2 + (_kf.vlo * mpdLo) ** 2);
  if (vMs > GPS_MAX_SPEED) {
    const sc = GPS_MAX_SPEED / vMs;
    _kf.vla *= sc;  _kf.vlo *= sc;
  } else if (vMs < GPS_STILL_SPD) {
    // Hodač je stao — nuliraj inerciju da ne nastane luk kad krene u drugu stranu
    _kf.vla = 0;  _kf.vlo = 0;
  }

  _kf.la  = newLa;  _kf.lo  = newLo;
  _kf.Pla = (1 - Kla) * Pla;
  _kf.Plo = (1 - Klo) * Plo;

  return { la: _kf.la, lo: _kf.lo };
}

// ─── EMA FILTAR ZA NADMORSKU VISINU ──────────────────────────────────────────────
let _altEma = null;
const ALT_EMA_ALPHA = 0.25;
function _filteredAlt(al) {
  if (al == null) return null;
  if (_altEma === null) { _altEma = al; return al; }
  _altEma = ALT_EMA_ALPHA * al + (1 - ALT_EMA_ALPHA) * _altEma;
  return Math.round(_altEma * 10) / 10;
}

// Bearing (smjer) između dvije GPS tačke u stepenima (0–360)
function _gpsBearing(la1, lo1, la2, lo2) {
  const dLo = (lo2 - lo1) * Math.PI / 180;
  const lat1 = la1 * Math.PI / 180;
  const lat2 = la2 * Math.PI / 180;
  const y = Math.sin(dLo) * Math.cos(lat2);
  const x = Math.cos(lat1) * Math.sin(lat2) - Math.sin(lat1) * Math.cos(lat2) * Math.cos(dLo);
  return ((Math.atan2(y, x) * 180 / Math.PI) + 360) % 360;
}

// ─── POST-SNIMANJE IZGLAĐIVANJE (Douglas-Peucker) ──────────────────────────────
// Kalman/medijan filter tokom snimanja uklanja pojedinačne spike-ove, ali rezidualni
// "cik-cak" od multipatha (odbijanje signala od zgrada/krošnji) i dalje prolazi jer
// svaki fix pojedinačno izgleda validan. RDP nakon snimanja briše tačke koje su unutar
// tolerancije od prave linije susjeda — pravi zavoji trase (desetine metara) ostaju
// netaknuti, a mikro-talasanje se uklanja. Ovo popravlja i izmjerenu dužinu vlake,
// jer talasanje vještački produžuje zbir segmenata.
function _vlakaSimplifyTolM() { return _forestMode ? 3.5 : 2.5; }

function _simplifyRecordedPts(pts, toleranceM) {
  if (!pts || pts.length < 3 || typeof turf === 'undefined' || !turf.simplify) return pts;
  try {
    const line = turf.lineString(pts.map(p => [p.lo, p.la]));
    const toleranceDeg = toleranceM / MPDEG;
    const simplified = turf.simplify(line, { tolerance: toleranceDeg, highQuality: true, mutate: false });
    const keep = new Set(simplified.geometry.coordinates.map(c => c[0] + ',' + c[1]));
    // Gap-markirane tačke (D3-C) uvijek čuvamo — signaliziraju stvarni prekid GPS-a.
    const out = pts.filter(p => p.gap || keep.has(p.lo + ',' + p.la));
    return out.length >= 2 ? out : pts;
  } catch (e) { return pts; }
}

function onP(p) {
  // Dok dopuna iz native bafera traje (ima predahe — await), živi fiks čeka da
  // ona završi. Inače bi pomjerio _onPLastFixTs na "sada", pa bi dopuna ostatak
  // pozadinskog perioda preskočila kao "već viđen" i potvrdila (obrisala)
  // journal — a i ono što prođe ušlo bi IZA novije žive tačke (cik-cak).
  if (_drainNativeGpsBuffer._busy) { _drainLiveQ.push({ fn: onP, arg: p }); return; }
  const { latitude: la, longitude: lo, altitude: al, accuracy: ac,
          speed: gpsSpeed, heading: gpsHeading } = p.coords;
  // Zabilježi SIROVI fix ODMAH (prije filtriranja) — _drainNativeGpsBuffer po
  // ovome zna koje je tačke iz native bafera glavni watch VEĆ vidio uživo, pa
  // ih pri replay-u preskače (GpsService puni bafer kontinuirano cijelo
  // vrijeme snimanja, i dok je app u prvom planu — bez ovoga bi se svaka
  // uživo obrađena tačka procesirala i drugi put pri povratku u app).
  _onPLastFixTs = p.timestamp || Date.now();
  const filtAl = _filteredAlt(al);
  lastP = { la, lo, al: filtAl ?? 0, ac };
  _lastGpsFixTime = Date.now();
  _gpsRestartCount = 0;
  _updLocBtn();
  if (_gpsStabCb) { try { _gpsStabCb(la, lo, ac); } catch(e) {} }
  _addTragPoint(la, lo, ac, al, gpsSpeed);
  _updMcdDist();
  if (_activeTab === 'teren') terenRender();

  // Prikaz uvijek — pokaži brzinu ako je dostupna
  const speedKmh = (gpsSpeed != null && gpsSpeed >= 0) ? ` · ${Math.round(gpsSpeed * 3.6)} km/h` : '';
  const warmTxt  = (recOn && !recPaused && _gpsBuf.length > 0 && _gpsBuf.length < _gpsMedN())
    ? ` (GPS ${_gpsBuf.length}/${_gpsMedN()})` : '';
  document.getElementById('gps-info').textContent = `±${Math.round(ac)} m${speedKmh}${warmTxt}`;
  _locStatusRender();
  document.getElementById('oacc').textContent = `±${Math.round(ac)}m`;
  _updRecSignal(ac);
  _precizCollect(la, lo, ac);
  // N.V. prati tvoju poziciju dok karta nije svjesno odmaknuta — DEM na tvojoj
  // tački, GPS visina (📡) samo kao rezerva (vidi _nvZaPoziciju). _gpsAlt znači
  // "N.V. prati poziciju", pa važi i kad GPS ne šalje visinu.
  if (!_userPannedAway && !_recFreeView) {
    _gpsAlt = true;
    clearTimeout(_elevTimer);
    _nvZaPoziciju(la, lo, filtAl ?? al);
  }

  // Marker pozicije (SVG s kompasom)
  if (!posMk) {
    const ico = L.divIcon({className:'', iconSize:[32,32], iconAnchor:[16,16],
      html:`<svg id="loc-svg" xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="-16 -16 32 32" style="overflow:visible;transform-origin:16px 16px;transition:transform 0.18s linear;">
        <defs>
          <radialGradient id="loc-cone-grad" cx="50%" cy="100%" r="100%">
            <stop offset="0%" stop-color="#3b82f6" stop-opacity="0.65"/>
            <stop offset="100%" stop-color="#3b82f6" stop-opacity="0.12"/>
          </radialGradient>
        </defs>
        <path id="loc-cone" d="M0,0 L-76,-90 A118,118 0 0,1 76,-90 Z" fill="url(#loc-cone-grad)" opacity="0" style="transition:opacity 0.3s;"/>
        <polygon id="loc-arrow" points="0,-18 -6,-6 6,-6" fill="#3b82f6" opacity="0" style="transition:opacity 0.3s;"/>
        <circle cx="0" cy="0" r="8" fill="#3b82f6" stroke="#fff" stroke-width="2.5" style="filter:drop-shadow(0 0 5px #3b82f6);"/>
        <circle cx="0" cy="0" r="3" fill="#fff"/>
      </svg>`});
    posMk = L.marker([la,lo], {icon:ico, zIndexOffset:999}).addTo(map);
    posCr = L.circle([la,lo], {radius:ac, color:'#3b82f6', fillColor:'#3b82f6', fillOpacity:0.12, weight:1}).addTo(map);
    map.setView([la,lo], 17);
    if (_compassHeading !== null) _updCompassOnMarker(_compassHeading);
    _drawRadiusRings();
  } else {
    posMk.setLatLng([la, lo]);
    posCr.setLatLng([la, lo]).setRadius(ac);
    _updateRadiusRings();
  }

  // Terenski profil: detekcija trenutnog odjela (jeftino — bounds pre-check po granici)
  if (typeof isSpdField === 'function' && isSpdField()) _trnUpdOdjel(la, lo);

  // Prati lokaciju kad se snima vlaka ili trag (osim u slobodnom pogledu)
  if (((recOn && !recPaused) || _tragOn) && !_recFreeView && !(typeof window !== 'undefined' && (window.Explorer?.active && _activeTab === 'karta'))) {
    map.panTo([la, lo], { animate: true, duration: 0.5 });
  }

  // Navigacija do tačke — ažuriraj panel i liniju
  if (typeof window !== 'undefined') window.Explorer?.onFix({la,lo,ac,al:filtAl ?? al,speed:gpsSpeed,heading:gpsHeading,ts:p.timestamp || Date.now()});
  if (_tackaNavIdx !== null) _updateNavPanel(la, lo);

  // Live preview segment prati SVAKI fix (isto kao marker pozicije) — vidi _updRecPreview
  _updRecPreview(la, lo);

  _vlakaProcessGpsPoint(la, lo, ac, filtAl ?? al ?? 0, gpsSpeed);
}

// Prihvat jedne GPS tačke u aktivnu vlaku — dijeljeno između uživo onP()
// callbacka (bez tsMs) i _drainNativeGpsBuffer replay-a (sa tsMs = stvarno
// historijsko vrijeme fiksa iz native bafera). Timestamp se provlači kroz SVE
// vremenske kapije (spike dtS, speed-gate elapsed, gap detekcija) — replay sa
// Date.now() bi svaku historijsku tačku vidio kao "sad", pa bi speed-gate
// odbacio cijeli niz (prividno ogromna brzina), a poslije replay-a bi prvi
// živi fix izgledao kao nula proteklog vremena.
// ── Hod po već snimljenom dijelu vlake (v1.9.1) ─────────────────────────────
// Terenska prijava (screenshot): okrenuo se sa kolicima, vratio par metara istim
// putem pa opet naprijed — na liniji je ostala PETLJA/kuka od ~5 m. GPS tačke
// povratka padaju par metara u stranu od puta naprijed, pa povratak izgleda kao
// novi, paralelan komad trase, a tačka na samom mjestu okreta daje bočnu kuku.
// Vlaka je GEOMETRIJA puta, ne historija hoda: ponovni prolaz istom trasom joj
// ne dodaje ništa. Zato se tačka koja leži IZA vrha linije, unutar koridora
// širine w od već snimljenog dijela, ne upisuje — linija čeka dok se ne prođe
// njen vrh, pa nastavlja odatle.
// Namjerno se ne gleda UGAO zaokreta (odbijeno ranije — pogađa i pravu vratnju),
// nego položaj u odnosu na već snimljenu liniju: prava serpentina čiji su
// krakovi razmaknuti više od w ostaje netaknuta. w = 2 × tačnost, ograničeno
// na 6–9 m: izmjereno simulacijom (100 GPS šumova, povratak 5 m u stranu kao na
// terenskom snimku) je koridor od 6 m ostavljao petlju u 10 % slučajeva jer dio
// tačaka povratka padne van njega. Serpentina sa krakovima 12 m razmaka ostaje
// cijela; okret uži od ~9 m se na vlaci ionako ne vozi.
const _VL_RETRACE_MIN_W = 6, _VL_RETRACE_MAX_W = 9;
// Tačka vlake je objekat {la, lo}, tačka traga niz [la, lo, alt, ts, acc] —
// ista geometrija povratka služi oba (v1.9.2), pa se koordinata čita kroz ovo.
function _rtLa(p) { return p.la ?? p[0]; }
function _rtLo(p) { return p.lo ?? p[1]; }
function _vlRetraceSirina(ac) {
  return Math.max(_VL_RETRACE_MIN_W, Math.min(_VL_RETRACE_MAX_W, (ac > 0 ? ac : 4) * 2));
}
// Projekcija tačke na snimljenu liniju. Vraća {la, lo, d, iza} kad tačka leži
// najmanje 2 m IZA vrha (mjereno duž linije) i unutar w od nje; inače null
// (tačka je ispred vrha — normalno snimanje). Prva verzija je izuzimala zadnji
// segment (da bočni odskok na vrhu ne proglasi sljedeći korak naprijed
// povratkom) — ali je tada povratak unutar tog segmenta prolazio neprepoznat, a
// provjera šiljka pri izlasku je skidala i ispravne tačke (uhvaćeno simulacijom
// kroz 40 GPS šumova). Bočni odskok sad rješava _vlRetraceSkiniSiljak.
// `minIza` je histereza: ULAZ u povratak traži ≥ 2 m iza vrha (jedan GPS
// odskok nije povratak), a kad povratak već traje, traje dok se vrh ne prođe
