// Snimanje zaustavljeno DOK JE PAUZIRANO ostavlja interval sa `end:null`, a
// takav interval _uPauziIntervalu smatra "traje i dalje" za SVAKO buduće
// vrijeme. _pauziOcistiZatvorene ga namjerno ne briše (čuva tekuću pauzu), pa
// bi zaostao zauvijek i u SLJEDEĆEM snimanju native replay tiho odbacio SVAKU
// tačku (a _nativeReplayLast bi napredovao, dakle bez ponovnog pokušaja) —
// tačno onaj trajni gubitak zbog kojeg su prozori pauze v1.5.8 i uvedeni.
// Zato svaki stop zatvara tekući interval (_pauziZavrsi), a svaki start
// odbacuje sve zaostalo iz prethodne sesije (_pauziResetuj): tačke nove sesije
// po definiciji ne mogu pripadati pauzi one prethodne.
function _pauziZavrsi(win) { _pauziZatvoriProzor(win); }
function _pauziResetuj(win) { win.length = 0; _pauziSnimi(); }
function _bgRecStart(label) {
  const now = Date.now();
  if (recOn && !_nativeSessionSince.vlaka) _nativeSessionSince.vlaka = now;
  if (_tragOn && !_nativeSessionSince.trag) _nativeSessionSince.trag = now;
  if (_dozGpsOn && !_nativeSessionSince.doznaka) _nativeSessionSince.doznaka = now;
  _iosBgRecWarn();          // iPhone: jednom upozori da pozadina ne radi na iOS-u
  _acquireWakeLock();
  _startBgAudio();
  _startSWHeartbeat();
  const nm = label || (actI !== null ? vlake[actI]?.nm : null) || 'GPS Snimanje';
  if (typeof AndroidGps !== 'undefined') {
    try { AndroidGps.startRecording(nm); } catch(e) {}
  }
  if (label) _startRecNotification(label, '');
  else _startRecNotification();  // vlaka — čita ime + trenutnu dužinu iz vlake[actI]
  _checkBatteryOptHint();  // sva tri tipa snimanja pate od istog OEM battery-killer problema
}

// ── Traka snimanja na svim panelima (v3.116.0) ────────────────────────────
// Koje snimanje traka pokazuje: prioritet vlaka → trag → doznaka pojas. Ako ih
// ima više istovremeno, ostali se BROJE u natpisu — ne smiju tiho nestati, jer
// bi korisnik mislio da je završio sve kad završi ono što traka pokazuje.
function _recBarStanje() {
  const aktivni = [];
  if (typeof recOn     !== 'undefined' && recOn)     aktivni.push('vlaka');
  if (typeof _tragOn   !== 'undefined' && _tragOn)   aktivni.push('trag');
  if (typeof _dozGpsOn !== 'undefined' && _dozGpsOn) aktivni.push('doznaka');
  if (!aktivni.length) return null;
  // Na Karti #action-bar već nosi vlaku i trag — doznaka je tamo jedina bez
  // kontrola, pa ona ide naprijed. Inače bi uz istovremenu vlaku traka bila
  // sakrivena kao "duplikat" i pojas ne bi imao ni oznaku ni Završi.
  if (_activeTab === 'karta' && aktivni.length > 1 && aktivni.includes('doznaka')) {
    aktivni.splice(aktivni.indexOf('doznaka'), 1); aktivni.unshift('doznaka');
  }
  const ostalih = aktivni.length - 1;
  const tip = aktivni[0];
  if (tip === 'vlaka') {
    const v = (typeof actI !== 'undefined' && actI !== null) ? vlake[actI] : null;
    return { tip, ostalih, tab: 'karta', naziv: (v && v.nm) || 'Vlaka',
             info: v ? fmtL(calcL(v.pts)) : '', pauziran: !!recPaused };
  }
  if (tip === 'trag') {
    return { tip, ostalih, tab: 'karta', naziv: 'Trag',
             info: _tragPts.length + ' tač. · ' + _tragFmtLen(_tragCalcLen(_tragPts)),
             pauziran: !!_tragPaused };
  }
  return { tip, ostalih, tab: 'doznaka', naziv: 'Pojas doznake',
           info: _dozGpsLen ? _tragFmtLen(_dozGpsLen) : '',
           pauziran: !!_dozGpsPaused };
}

function _recBarUpdate() {
  const s = _recBarStanje();
  if (!s) return;
  const g = id => document.getElementById(id);
  const bar = g('rec-bar');
  const tip = g('rb-tip'), info = g('rb-info'), ptxt = g('rb-pauza-txt'), pico = g('rb-pauza-ico');
  if (tip)  tip.textContent  = s.naziv + (s.ostalih ? ' (+' + s.ostalih + ')' : '');
  if (info) info.textContent = (s.pauziran ? '⏸ pauzirano · ' : '') + (s.info || '');
  if (ptxt) ptxt.textContent = s.pauziran ? 'Nastavi' : 'Pauza';
  // "Nastavi" je znak ▶, ne sprite ikonica — u sprite-u nema #ic-play, a
  // #action-bar (ab-pauza-ico) već koristi baš taj znak za isti smisao.
  if (pico) pico.innerHTML = s.pauziran ? '▶' : '<svg class="ic"><use href="#ic-pauza"/></svg>';
  if (bar) bar.classList.toggle('pauzirano', s.pauziran);
}

let _recBarTimer = null;
function _recBarSync() {
  const bar = document.getElementById('rec-bar');
  if (!bar) return;
  const s = _recBarStanje();
  // Na Karti donja traka (#action-bar) već nosi kontrole za vlaku i trag, pa bi
  // druga traka bila duplikat. Doznaka pojas je IZUZETAK: nju #action-bar ne
  // pokriva ni na Karti, pa tamo traka ostaje jedini način da se vidi i zaustavi.
  const dozControls = document.getElementById('doz-gps-modal');
  const dupliraSe = _activeTab === 'karta' && s && (s.tip !== 'doznaka' || (dozControls && !dozControls.hidden));
  const vidljiv = !!s && !dupliraSe;
  bar.style.display = vidljiv ? 'flex' : 'none';
  document.body.classList.toggle('recbar-on', vidljiv);
  if (vidljiv) {
    _recBarUpdate();
    if (!_recBarTimer) _recBarTimer = setInterval(_recBarUpdate, 1000);
  } else if (_recBarTimer) {
    clearInterval(_recBarTimer); _recBarTimer = null;
  }
}

function _recBarGo() {
  const s = _recBarStanje();
  if (s?.tip === 'doznaka' && typeof dozOpenGPSControls === 'function') dozOpenGPSControls();
  else if (s) switchTab(s.tab);
}
function _recBarPauza() {
  const s = _recBarStanje();
  if (!s) return;
  if (s.tip === 'vlaka')      toggleRecPause();
  else if (s.tip === 'trag')  togTragPause();
  else                        dozPauseGPS();
  _recBarUpdate();
}
function _recBarKraj() {
  const s = _recBarStanje();
  if (!s) return;
  // Završetak se NE izvršava na tuđem panelu — svaki tip ima svoje potvrde i
  // dijaloge (ime vlake, spašavanje traga, sync pojasa) koji pripadaju svom
  // ekranu. Zato prvo prebaci tamo, pa onda pozovi.
  switchTab(s.tab);
  setTimeout(() => {
    if (s.tip === 'vlaka')      _krajVlake();
    else if (s.tip === 'trag')  fabSnimTrag();
    else if (_dozGpsOn)      dozStopGPS();
  }, 80);
}

function _bgRecStopIfIdle() {
  if (!recOn) _nativeSessionSince.vlaka = 0;
  if (!_tragOn) _nativeSessionSince.trag = 0;
  if (!_dozGpsOn) _nativeSessionSince.doznaka = 0;
  if (_anyRecOn()) return;   // još nešto snima — drži servis/lock živim
  _releaseWakeLock();
  _stopBgAudio();
  _stopSWHeartbeat();
  _stopRecNotification();
  if (typeof AndroidGps !== 'undefined') {
    try { AndroidGps.stopRecording(); } catch(e) {}
  }
}

// ── PRIJEM AKCIJA IZ NOTIFIKACIJE ────────────────────────────────────────────
if ('serviceWorker' in navigator) {
  navigator.serviceWorker.addEventListener('message', evt => {
    if (evt.data?.type === 'rec-action') {
      _nativeRecAction(evt.data.action);   // route na tip koji trenutno snima
    }
    // Klik na share-loc notifikaciju — centriraj mapu na dijeljenu lokaciju
    if (evt.data?.type === 'pan-to' && evt.data.la && evt.data.lo) {
      if (_activeTab !== 'karta') switchTab('karta');
      map.setView([evt.data.la, evt.data.lo], 17);
    }
    // SW šalje ping svakih 20s tokom snimanja — restartuj GPS ako se ugasio
    if (evt.data?.type === 'sw-ping' && recOn && gpsOn && !wid) {
      _restartGpsWatch('sw-ping');
    }
  });
}
// Android native notification actions (pause/stop from Foreground Service).
// Jedan foreground service opslužuje sva tri tipa snimanja — Stop/Pauza iz
// notifikacije se rutira na ono što je trenutno aktivno.
async function _nativeRecAction(action) {
  if (action === 'stop') {
    // Ispuni native bafer PRIJE finalizacije — bez ovoga bi tačke snimljene
    // dok je WebView bio u pozadini (i još nisu stigle preko redovnog
    // visibilitychange puta) bile trajno izgubljene: stopRec()/fabSnimTrag()/
    // dozStopGPS() zatvaraju snimanje i briše se prilika da se bafer iskoristi.
    try { await _drainNativeGpsBuffer(); } catch(e) {}
    if (recOn)          stopRec();
    else if (_tragOn)   fabSnimTrag();
    else if (_dozGpsOn) await dozStopGPS();
    // GpsService se na "stop" iz notifikacije sam ugasi (native GPS + wake
    // lock), a ovdje se završava samo JEDNO snimanje. Ako drugo i dalje traje,
    // bez ponovnog starta bi ono do kraja išlo bez pozadinske zaštite.
    if (_anyRecOn() && typeof AndroidGps !== 'undefined') {
      const nm = recOn ? (vlake[actI]?.nm || 'GPS Snimanje') : _tragOn ? 'trag' : 'pojas doznake';
      try { AndroidGps.startRecording(nm); } catch(e) {}
    }
  } else if (action === 'pause') {
    if (recOn)          toggleRecPause();
    else if (_tragOn)   togTragPause();
    else if (_dozGpsOn) dozPauseGPS();
  }
}

function centerMap() {
  if (lastP) map.setView([lastP.la,lastP.lo],18);
  else startGPS();
}

// ── GPS FAB ───────────────────────────────────────────────────────────────────
let _fabOpen = false;
let _tragOn     = false;
let _tragPaused = false;
let _tragLine   = null;
let _tragPts    = [];

// ── Registar tragova ────────────────────────────────────────────────────────
const _TRAG_REG_KEY = 'tvlake_tragovi';
let _tragRegistry   = [];  // [{id, name, date, pts, color, visible}]
let _tragLayers     = {};  // id → L.polyline (vizualni)
let _tragHitLayers  = {};  // id → L.polyline (nevidljivi, širi, za klik)

const _TRAG_COLORS = ['#f97316','#38bdf8','#4ade80','#a78bfa','#fb7185','#facc15','#e879f9','#34d399'];

function _tragRegLoad() {
  try {
    const raw = localStorage.getItem(_TRAG_REG_KEY);
    if (raw) _tragRegistry = JSON.parse(raw);
  } catch(e) { _tragRegistry = []; }
  // Re-add map layers for all saved tragovi
  _tragRegistry.forEach(t => _tragRegAddLayer(t));
}

function _tragRegSave() {
  // Snimljen trag je nepovratan — tiho progutan neuspjeh znači izgubljen
  // terenski dan bez ijednog znaka korisniku (vidi _localSetKriticno).
  return _localSetKriticno(_TRAG_REG_KEY, JSON.stringify(_tragRegistry), 'Snimljeni tragovi');
}

// ── Quick meta prompt po završetku snimanja traga ──────────────────

function _pointInRing(lat, lng, ring) {
  if (!ring || ring.length < 3) return false;
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const [yi, xi] = Array.isArray(ring[i]) ? ring[i] : [ring[i].lat, ring[i].lng];
    const [yj, xj] = Array.isArray(ring[j]) ? ring[j] : [ring[j].lat, ring[j].lng];
    if (((yi > lat) !== (yj > lat)) && (lng < (xj - xi) * (lat - yi) / (yj - yi) + xi))
      inside = !inside;
  }
  return inside;
}

function _findOdjelAtPoint(lat, lng) {
  for (const o of graniceOdjeli) {
    if (!o.bounds || !o.bounds.contains([lat, lng])) continue;
    if (o.ring && o.ring.length >= 3) {
      if (_pointInRing(lat, lng, o.ring)) return o.name;
    } else {
      return o.name;
    }
  }
  return null;
}

function _findGjForOdjel(odjelName) {
  if (!odjelName) return '';
  const p = _projekti.find(pr => pr.odjel === odjelName);
  if (p?.gj) return p.gj;
  const low = odjelName.toLowerCase();
  const p2 = _projekti.find(pr => pr.odjel?.toLowerCase() === low);
  return p2?.gj || '';
}

let _tqmId = null;
function _tqmOpen(id) {
  _tqmId = id;
  const sel = document.getElementById('tqm-gj-sel');
  if (sel && !sel.options.length) {
    sel.innerHTML = ['', ..._GJ_OPTIONS, 'CUSTOM'].map(v =>
      `<option value="${_escHtml(v)}">${v || '— odaberi GJ —'}</option>`
    ).join('');
  }

  // Auto-detect odjel i GJ po lokaciji traga
  const t = _tragRegistry.find(x => x.id === id);
  let detectedOdjel = '';
  let detectedGj = '';

  if (t?.pts?.length) {
    const mid = t.pts[Math.floor(t.pts.length / 2)];
    const lat = mid[0], lng = mid[1];
    detectedOdjel = _findOdjelAtPoint(lat, lng) || '';
    if (detectedOdjel) {
      detectedGj = _findGjForOdjel(detectedOdjel);
    }
  }

  // Fallback na aktivni projekat
  const aktP = _aktivniProjektId ? _projekti.find(p => p.id === _aktivniProjektId) : null;
  const gjV = detectedGj || aktP?.gj || '';
  const odjV = detectedOdjel || aktP?.odjel || '';

  if (sel) {
    sel.value = (_GJ_OPTIONS.includes(gjV) ? gjV : (gjV ? 'CUSTOM' : ''));
    const cust = document.getElementById('tqm-gj-cust');
    if (cust) { cust.style.display = sel.value==='CUSTOM' ? '' : 'none'; cust.value = sel.value==='CUSTOM' ? gjV : ''; }
  }
  const odj = document.getElementById('tqm-odjel');
  if (odj) odj.value = odjV;
  document.getElementById('trag-quick-meta').classList.add('show');
}
function _tqmSave() {
  const t = _tqmId && _tragRegistry.find(x => x.id === _tqmId);
  if (t) {
    t.gj    = _gjGetValue('tqm');
    t.odjel = (document.getElementById('tqm-odjel')?.value || '').trim();
    _tragRegSave();
  }
  _tqmClose();
}
function _tqmClose() {
  document.getElementById('trag-quick-meta').classList.remove('show');
  _tqmId = null;
}

// ─── STIL LINIJA — globalne postavke (Meni → 🖌 Stil linija) ─────────────────
// Defaulti za tragove/mjerenja/tačke; pojedinačne izmjene na tragu (popup) i
// dalje imaju prednost za taj trag. Čuva se lokalno po uređaju.
const _LSTYLE_DEFAULT = {
  tragW: 4, tragOp: 85, tragDash: 'solid', tragCol: '', tragLen: false,
  msrW: 4, msrFillOp: 18, msrArea: true, msrLen: false,
  tackaScale: 100, vlakaDotScale: 100, lagerScale: 100
};
const _LSTYLE_KEY = 'tvlake_stil_linija';
let _lineStyle = { ..._LSTYLE_DEFAULT };
try { Object.assign(_lineStyle, JSON.parse(localStorage.getItem(_LSTYLE_KEY) || '{}')); } catch(e) {}
function _lineStyleSave() { try { localStorage.setItem(_LSTYLE_KEY, JSON.stringify(_lineStyle)); } catch(e) {} }

// v1.8.1: panel je preuređen — pregled uživo na vrhu (vidi se TAČNO šta klizač
// radi, bez zatvaranja panela i traženja traga na karti), kartice po temi i
// "Vrati zadano". Markup se gradi iz JS-a da kontrole i stanje ne bi mogli
// razići (ranije su se vrijednosti ručno prepisivale u 12 polja pri otvaranju).
const _STIL_BOJE = ['#f97316', '#ef4444', '#eab308', '#22c55e', '#06b6d4', '#3b82f6', '#a855f7', '#ffffff'];
const _STIL_DASH = { solid: null, dash: '8 4', dot: '2 6' };
var _stilTabAkt = 'trag';

// Pregled je ČISTA funkcija stila (bez DOM-a) — iste formule kao na karti:
// debljina u px, dash nizovi kao u _tragRegAddLayer, veličine tačke/lagera/
// krajeva vlake po istim baznim mjerama (24×32, 28×13, 6 px).
function _stilPregledSvg(ls) {
  const tc = ls.tragCol || '#f97316';
  const dash = _STIL_DASH[ls.tragDash] ? ` stroke-dasharray="${_STIL_DASH[ls.tragDash]}"` : '';
  const halo = 'paint-order="stroke" stroke="#000" stroke-width="3" stroke-linejoin="round"';
  const lbl = (x, y, t) => `<text x="${x}" y="${y}" font-size="11" font-weight="700" fill="#fff" text-anchor="middle" ${halo}>${t}</text>`;
  const ts = (ls.tackaScale || 100) / 100, W = 24 * ts, H = 32 * ts;
  const ds = 6 * (ls.vlakaDotScale || 100) / 100;
  const lg = (ls.lagerScale || 100) / 100, LW = 28 * lg, LH = 13 * lg;
  const bv = (typeof getBojaVlake === 'function') ? getBojaVlake() : '#60a5fa';
  const dot = (x, y, c) => `<circle cx="${x}" cy="${y}" r="${ds / 2 + 0.75}" fill="${c}" stroke="#fff" stroke-width="1.5"/>`;
  return `<svg viewBox="0 0 340 150" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Pregled stila">
    <rect width="340" height="150" fill="#e7eddc"/>
    <path d="M-10 40 Q 80 10 170 35 T 350 30 M-10 85 Q 90 55 180 80 T 350 70 M-10 130 Q 100 100 190 125 T 350 115" fill="none" stroke="#b9a37a" stroke-width="1" opacity=".55"/>
    <polygon points="232,22 322,36 312,118 226,104" fill="#fbbf24" fill-opacity="${(ls.msrFillOp ?? 18) / 100}" stroke="#fbbf24" stroke-opacity=".9" stroke-width="${ls.msrW || 4}" stroke-linejoin="round"/>
    ${ls.msrArea ? lbl(273, 74, '0,82 ha') : ''}${ls.msrLen ? lbl(318, 80, '86 m') : ''}
    <path d="M14 136 C 60 114, 72 66, 122 74 S 190 44, 206 18" fill="none" stroke="${tc}" stroke-opacity="${(ls.tragOp || 85) / 100}" stroke-width="${ls.tragW || 4}" stroke-linecap="round"${dash}/>
    ${ls.tragLen ? lbl(120, 66, '248 m') : ''}
    <polyline points="22,40 96,56 142,30" fill="none" stroke="${bv}" stroke-width="4" stroke-linejoin="round" stroke-linecap="round"/>
    <g transform="translate(${22 - LW / 2},${40 - LH / 2})"><rect width="${LW}" height="${LH}" fill="#fff"/><polygon points="0,0 ${LW},0 ${LW},${LH}" fill="#000"/><line x1="0" y1="0" x2="${LW}" y2="${LH}" stroke="#fff" stroke-width="1.5"/></g>
    ${dot(22, 40, '#4ade80')}${dot(142, 30, '#f87171')}
    <g transform="translate(${170 - W / 2},${140 - H}) scale(${ts})"><path d="M12 0C5.37 0 0 5.37 0 12c0 9 12 20 12 20S24 21 24 12C24 5.37 18.63 0 12 0z" fill="#fbbf24" stroke="#92400e" stroke-width="1.4"/><circle cx="12" cy="12" r="5.5" fill="#fff"/><text x="12" y="16" text-anchor="middle" font-size="8" font-weight="700" fill="#92400e">1</text></g>
  </svg>`;
}

function _stilKlizac(key, lbl, min, max, step, suf) {
  const v = _lineStyle[key];
  return `<div class="stl-red"><span class="stl-lbl">${lbl}</span>
    <input type="range" min="${min}" max="${max}" step="${step}" value="${v}" oninput="_stilSet('${key}',+this.value,this)" data-suf="${suf}">
    <b class="stl-val">${v}${suf}</b></div>`;
}
function _stilPrekidac(key, lbl) {
  return `<label class="stl-red stl-prek"><span class="stl-lbl">${lbl}</span>
    <input type="checkbox" ${_lineStyle[key] ? 'checked' : ''} onchange="_stilSet('${key}',this.checked)"><i></i></label>`;
}

function _stilRender() {
  const box = document.getElementById('stil-sadrzaj');
  if (!box) return;
  const ls = _lineStyle, tab = _stilTabAkt;
  const dashBtn = (d, t) => `<button class="stl-seg${ls.tragDash === d ? ' on' : ''}" onclick="_stilSet('tragDash','${d}')">
      <svg viewBox="0 0 40 8" width="40" height="8"><line x1="2" y1="4" x2="38" y2="4" stroke="currentColor" stroke-width="3" stroke-linecap="round"${_STIL_DASH[d] ? ` stroke-dasharray="${_STIL_DASH[d]}"` : ''}/></svg>${t}</button>`;
  const boje = `<button class="stl-boja vlastita${!ls.tragCol ? ' on' : ''}" onclick="_stilSet('tragCol','')" title="Svaki trag svojom bojom">Svoja</button>`
    + _STIL_BOJE.map(c => `<button class="stl-boja${ls.tragCol === c ? ' on' : ''}" style="background:${c};" onclick="_stilSet('tragCol','${c}')" aria-label="Boja ${c}"></button>`).join('')
    + `<label class="stl-boja stl-boja-izbor${ls.tragCol && !_STIL_BOJE.includes(ls.tragCol) ? ' on' : ''}" title="Druga boja" style="${ls.tragCol && !_STIL_BOJE.includes(ls.tragCol) ? 'background:' + ls.tragCol : ''}">＋<input type="color" value="${ls.tragCol || '#f97316'}" onchange="_stilSet('tragCol',this.value)"></label>`;
  const sekcije = {
    trag: `${_stilKlizac('tragW', 'Debljina', 1, 10, 1, ' px')}
      ${_stilKlizac('tragOp', 'Prozirnost', 20, 100, 5, '%')}
      <div class="stl-red"><span class="stl-lbl">Linija</span><div class="stl-segs">${dashBtn('solid', 'Puna')}${dashBtn('dash', 'Crtice')}${dashBtn('dot', 'Tačke')}</div></div>
      <div class="stl-red stl-kol"><span class="stl-lbl">Boja svih tragova</span><div class="stl-boje">${boje}</div></div>
      ${_stilPrekidac('tragLen', 'Dužina na tragu')}`,
    msr: `${_stilKlizac('msrW', 'Debljina', 1, 10, 1, ' px')}
      ${_stilKlizac('msrFillOp', 'Ispuna poligona', 0, 100, 5, '%')}
      ${_stilPrekidac('msrArea', 'Površina u poligonu')}
      ${_stilPrekidac('msrLen', 'Dužina na liniji')}`,
    tacke: `${_stilKlizac('tackaScale', 'Oznaka tačke', 50, 200, 10, '%')}
      ${_stilKlizac('vlakaDotScale', 'Početak/kraj vlake', 50, 200, 10, '%')}
      ${_stilKlizac('lagerScale', 'Lager', 50, 200, 10, '%')}`,
  };
  const tabBtn = (id, t) => `<button class="stl-tab${tab === id ? ' on' : ''}" onclick="_stilTab('${id}')">${t}</button>`;
  box.innerHTML = `
    <div class="stl-tabs">${tabBtn('trag', 'Tragovi')}${tabBtn('msr', 'Mjerenja')}${tabBtn('tacke', 'Tačke i vlake')}</div>
    <div class="stl-kartica">${sekcije[tab] || ''}</div>
    <div class="stl-napomena">${tab === 'trag' ? 'Trag kojem je boja/debljina/linija posebno podešena (u njegovom popupu) zadržava svoju.' : 'Vrijedi za sve na ovom uređaju — mijenja se odmah i na karti.'}</div>`;
  _stilPregled();
}
function _stilPregled() {
  const el = document.getElementById('stil-pregled');
  if (el) el.innerHTML = _stilPregledSvg(_lineStyle);
}
function _stilTab(id) { _stilTabAkt = id; _stilRender(); }

function openStilLinija() {
  if(typeof closeVlakaStyle==='function')closeVlakaStyle();
  _stilRender();
  document.getElementById('stil-modal').style.display = '';
}
function closeStilLinija() { document.getElementById('stil-modal').style.display = 'none'; }

async function _stilVratiZadano() {
  if (!await _dlgConfirm('Vratiti sve postavke stila na zadane vrijednosti?', { title: 'Vrati zadano', okLabel: 'Vrati' })) return;
  Object.assign(_lineStyle, _LSTYLE_DEFAULT);
  _lineStyleSave();
  _stilApply();
  _stilRender();
}

function _stilSet(key, val, el) {
  _lineStyle[key] = val;
  _lineStyleSave();
  if (el && el.type === 'range') {
    // Klizač: samo broj pored njega + pregled — ponovno crtanje panela bi
    // prekinulo povlačenje prsta.
    const b = el.parentElement && el.parentElement.querySelector('.stl-val');
    if (b) b.textContent = val + (el.dataset.suf || '');
    _stilPregled();
  } else {
    _stilRender();
  }
  _stilApply();
}

// Primijeni globalni stil na SVE postojeće slojeve odmah (live)
function _stilApply() {
  try { (_tragRegistry || []).forEach(t => _tragRegAddLayer(t)); } catch(e) {}
  try { if (typeof _msrDrawAllSaved === 'function') _msrDrawAllSaved(); } catch(e) {}
  try { (_tacke || []).forEach((t, i) => { if (t.marker) t.marker.setIcon(_tačkaIcon(i + 1, t.nm)); }); } catch(e) {}
  try { (vlake || []).forEach((v, i) => updateVlakaLabel(i)); } catch(e) {}
}

let _tragLenMk = {};  // id → L.marker s tekstom dužine na sredini traga

function _tragRegAddLayer(t) {
  if (_tragLayers[t.id]) { try { map.removeLayer(_tragLayers[t.id]); } catch(e) {} }
  if (_tragHitLayers[t.id]) { try { map.removeLayer(_tragHitLayers[t.id]); } catch(e) {} }
  if (_tragLenMk[t.id]) { try { map.removeLayer(_tragLenMk[t.id]); } catch(e) {} delete _tragLenMk[t.id]; }
  const dash = t.dashStyle || _lineStyle.tragDash;
  const dashArray = dash==='dot' ? '2 6' : (dash==='dash' ? '8 4' : null);
  const lls = t.pts.map(p => [p[0], p[1]]);
  const line = L.polyline(lls, {
    color: (t.colorRucno && t.color) || _lineStyle.tragCol || t.color || '#f97316',
    weight: t.weight || _lineStyle.tragW,
    opacity: (_lineStyle.tragOp || 85) / 100, dashArray, interactive: false,
    pane: 'tragMsrLines'
  });
  const hit = L.polyline(lls, { weight: 24, opacity: 0.001, color: '#000', interactive: true, pane: 'tragMsrLines' });
  const lenM = _tragCalcLen(t.pts);
  line.bindPopup(() => _tragPopupHtml(t, lenM), { maxWidth: 260 });
  hit.on('click', e => {
    L.DomEvent.stopPropagation(e);
    // Bez ovoga map-level click handler (zatvaranje popupa + proximity-fallback na
    // vlake) opali ODMAH poslije i ubije tek otvoreni popup — trag "nije klikabilan".
    if (e.originalEvent) e.originalEvent.stopPropagation();
    line.openPopup(e.latlng);
  });
  const visible=typeof _tvTrackVisible==='function'?_tvTrackVisible(t):t.visible!==false;
  if (visible) { line.addTo(map); hit.addTo(map); }
  // Dužina na sredini traga (globalna opcija) — .vlaka-lbl klasa je uključuje u declutter
  if (_lineStyle.tragLen && visible && t.pts.length >= 2) {
    const mid = t.pts[Math.floor(t.pts.length / 2)];
    _tragLenMk[t.id] = L.marker([mid[0], mid[1]], {
      icon: L.divIcon({ className: '', iconSize: [0,0], iconAnchor: [0,0],
        html: `<div class="vlaka-lbl" style="color:#fff;font-size:11px;font-weight:bold;pointer-events:none;white-space:nowrap;text-shadow:0 0 3px #000,1px 1px 0 #000,-1px -1px 0 #000;">${_tragFmtLen(lenM)}</div>` }),
      interactive: false, pane: 'vlakeLabels'
    }).addTo(map);
  }
  _tragLayers[t.id] = line;
  _tragHitLayers[t.id] = hit;
}

function _tragCalcLen(pts) {
  let d = 0;
  for (let i = 1; i < pts.length; i++) {
    const a = pts[i-1], b = pts[i];
    const dlat = (b[0]-a[0]) * Math.PI/180;
    const dlon = (b[1]-a[1]) * Math.PI/180;
    const x = Math.sin(dlat/2)**2 + Math.cos(a[0]*Math.PI/180)*Math.cos(b[0]*Math.PI/180)*Math.sin(dlon/2)**2;
    d += 6371000 * 2 * Math.atan2(Math.sqrt(x), Math.sqrt(1-x));
  }
  return d;
}

function _tragFmtLen(m) {
  return m >= 1000 ? (m/1000).toFixed(2)+' km' : Math.round(m)+' m';
}

function _tragPopupHtml(t, lenM) {
  const dt = new Date(t.date).toLocaleString('bs-BA', {day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'});
  const w = t.weight || 3;
  const style = t.dashStyle || 'solid';
  return `<div class="trag-popup">
    <b>${_escHtml(_tragIme(t))}</b>
    <div class="trag-popup-meta">${dt}<br>${_tragFmtLen(lenM)} · ${t.pts.length} tačaka</div>
    <div class="trag-popup-btns">
      <button type="button" data-id="${_escHtml(String(t.id))}" onclick="_tragRegVodi(this.dataset.id)"><svg class="ic"><use href="#ic-kompas"/></svg> Vodi me</button>
      <button onclick="_tragRegRename('${t.id}')"><svg class="ic"><use href="#ic-crtaj"/></svg> Preimenuj</button>
      <button onclick="_tragKmlMeni('${t.id}')"><svg class="ic"><use href="#ic-posalji"/></svg> KML / Podijeli</button>
      <button onclick="_tragRegToggle('${t.id}');_tragPopupRefresh('${t.id}')" id="tvis-${t.id}">${t.visible!==false?'<svg class="ic"><use href="#ic-sakrij"/></svg> Sakrij':'<svg class="ic"><use href="#ic-prikazi"/></svg> Prikaži'}</button>
      <button onclick="_tragPopupObrisi('${t.id}')" style="color:#f87171;border-color:#7f1d1d;"><svg class="ic"><use href="#ic-zatvori"/></svg> Briši</button>
    </div>
    <div style="margin-top:8px;border-top:1px solid #334155;padding-top:8px;">
      <div style="display:flex;gap:8px;align-items:center;margin-bottom:6px;">
        <span style="font-size:11px;color:#94a3b8;">Boja</span>
        <input type="color" value="${t.color}" onchange="_tragoviSetColor('${t.id}',this.value)" style="width:28px;height:22px;border:none;background:none;cursor:pointer;">
        <span style="font-size:11px;color:#94a3b8;margin-left:8px;">Debljina</span>
        <input type="range" min="1" max="10" value="${w}" style="width:70px;" oninput="_tragoviSetWeight('${t.id}',+this.value)">
      </div>
      <div style="display:flex;gap:4px;">
        <button onclick="_tragoviSetStyle('${t.id}','solid');_tragPopupRefresh('${t.id}')" style="${style==='solid'?'border-color:#4ade80;color:#4ade80;':''}"><svg class="ic"><use href="#ic-puna"/></svg> Puna</button>
        <button onclick="_tragoviSetStyle('${t.id}','dash');_tragPopupRefresh('${t.id}')" style="${style==='dash'?'border-color:#4ade80;color:#4ade80;':''}"><svg class="ic"><use href="#ic-crtkana"/></svg> Iscrtkana</button>
        <button onclick="_tragoviSetStyle('${t.id}','dot');_tragPopupRefresh('${t.id}')" style="${style==='dot'?'border-color:#4ade80;color:#4ade80;':''}">· Tačkasta</button>
      </div>
    </div>
  </div>`;
}

// Native confirm() je u WebView-u ružan i blokira nit — isti _dlgConfirm kao svuda.
async function _tragPopupObrisi(id) {
  try { map.closePopup(); } catch (e) {}
  if (await _dlgConfirm('Obrisati trag?', { danger: true })) _tragRegDelete(id);
}

function _tragPopupRefresh(id) {
  const t = _tragRegistry.find(x => x.id === id);
  const line = _tragLayers[id];
  if (!t || !line) return;
  const lenM = _tragCalcLen(t.pts);
  line.setPopupContent(_tragPopupHtml(t, lenM));
}

function _escHtml(s) { return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }

function _tragRegAdd(pts, meta) {
  const id = 'trag_' + Date.now();
  const color = _TRAG_COLORS[_tragRegistry.length % _TRAG_COLORS.length];
  const aktP = _aktivniProjektId ? _projekti.find(p => p.id === _aktivniProjektId) : null;
  const t = {
    id, color, pts, visible: true,
    projektId:_aktivniProjektId || null,
    date: new Date().toISOString(),
    name: 'Trag ' + fmtDateShort(new Date().toISOString()),
    gj: aktP?.gj || '',
    odjel: aktP?.odjel || '',
    sbId: null,
    // Pouzdan dedup ključ za offline queue — ime je samo datum (bez vremena), pa bi
    // dva traga snimljena istog dana imala IDENTIČNO ime i pre-lookup po imenu bi
    // drugi trag tiho prepisao preko prvog (vidi upsert_trag u _processOfflineQueue).
    uuid: _genUUID()
  };
  // Naziv/boja/stil uređeni DOK je trag sniman (_tragLiveMeta) prelaze na sačuvani trag.
  if (meta) {
    if (String(meta.name || '').trim()) t.name = String(meta.name).trim();
    if (meta.color) { t.color = meta.color; t.colorRucno = true; }
    if (meta.weight) t.weight = meta.weight;
    if (meta.dashStyle) t.dashStyle = meta.dashStyle;
  }
  _tragRegistry.unshift(t);
  if (!_tragRegSave()) { _tragRegistry.shift(); return null; }
  _tragRegAddLayer(t);
  _tragRegRender();
  return t;
}

function openTragRegistry() {
  switchTab('mjtrg');
}
function closeTragRegistry() {
  switchTab('karta');
}

let _trgGrpBy = 'date';
let _msrGrpBy = 'date';

const _GJ_OPTIONS = ['RISOVAC KRUPA','GRMEČ JASENICA','VOJSKOVA','BAŠTRA ĆORKOVAČA','GOMILA'];
const _SUMARIJE   = ['ŠPD US ŠUME','ŠUMARIJA BOS.KRUPA','ŠUMARIJA BOS.PETROVAC','ŠUMARIJA SANSKI MOST','ŠUMARIJA BIHAĆ','ŠUMARIJA CAZIN','ŠUMARIJA KLJUČ'];

function _gjFieldHtml(pfx, val) {
  const isCustom = !!val && !_GJ_OPTIONS.includes(val);
  const sel = isCustom ? 'CUSTOM' : (val || '');
  const opts = ['', ..._GJ_OPTIONS, 'CUSTOM'].map(v =>
    `<option value="${_escHtml(v)}"${sel===v?' selected':''}>${v || '— odaberi GJ —'}</option>`
  ).join('');
  return `<select id="${pfx}-gj-sel" onchange="_gjSelChange('${pfx}')">${opts}</select>`
       + `<input id="${pfx}-gj-cust" style="display:${isCustom?'':'none'};margin-top:3px;" value="${isCustom?_escHtml(val):''}" placeholder="Unesi naziv GJ">`;
}
function _gjSelChange(pfx) {
  const cust = document.getElementById(pfx+'-gj-cust');
  const isC  = document.getElementById(pfx+'-gj-sel')?.value === 'CUSTOM';
  if (cust) { cust.style.display = isC ? '' : 'none'; if (isC) cust.focus(); }
}
function _gjGetValue(pfx) {
  const sel = document.getElementById(pfx+'-gj-sel');
  if (!sel) return '';
  if (sel.value === 'CUSTOM') return (document.getElementById(pfx+'-gj-cust')?.value || '').trim();
  return sel.value;
}

// ── Grouping helpers ──────────────────────────────────────────────────
function _grpKey(item, by) {
  if (by === 'date') {
    const d = new Date(item.date || Date.now());
    return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;
  }
  if (by === 'gj')    return item.gj    && item.gj.trim()    ? item.gj.trim()    : '—';
  if (by === 'odjel') return item.odjel && item.odjel.trim() ? item.odjel.trim() : '—';
  return null;
}
function _grpDateLabel(key) {
  const [y, m] = key.split('-');
  const months = ['Januar','Februar','Mart','April','Maj','Juni','Juli','August','Septembar','Oktobar','Novembar','Decembar'];
  return `${months[parseInt(m)-1]} ${y}`;
}
function _renderGrouped(items, by, rowFn) {
  if (by === 'none' || !by) return items.map(rowFn).join('');
  const groups = new Map();
  for (const item of items) {
    const key = _grpKey(item, by);
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(item);
  }
  const keys = [...groups.keys()].sort((a, b) =>
    by === 'date' ? b.localeCompare(a) : a.localeCompare(b)
  );
  let html = '';
  for (const key of keys) {
    const label = by === 'date' ? _grpDateLabel(key) : key;
    html += `<div class="mjtrg-grp-hdr">${_escHtml(label)}<span class="mjtrg-grp-cnt">${groups.get(key).length}</span></div>`;
    html += groups.get(key).map(rowFn).join('');
  }
  return html;
}
// ── Trag meta inline editor ─────────────────────────────────────────
function _tragRegEditMeta(id) {
  const el = document.getElementById('treg-edit-' + id);
  if (!el) return;
  el.style.display = el.style.display === 'none' ? '' : 'none';
}
function _tragRegSetMeta(id) {
  const t = _tragRegistry.find(x => x.id === id);
  if (!t) return;
  t.name  = (document.getElementById('treg-ei-name-'+id)?.value || t.name).trim();
  t.gj    = _gjGetValue('treg-'+id);
  t.odjel = (document.getElementById('treg-ei-odjel-'+id)?.value || '').trim();
  _tragRegSave();
  _tragRegRender();
}

function _tragRegRender() {
  if (typeof _tragoviRender === 'function') _tragoviRender();
  if (typeof _tragoviUpdBtn === 'function') _tragoviUpdBtn();
  const el = document.getElementById('trag-reg-list');
  const cnt = document.getElementById('trag-reg-count');
  if (!el) return;
  if (cnt) cnt.textContent = _tragRegistry.length ? `(${_tragRegistry.length})` : '';
  if (!_tragRegistry.length) {
    el.innerHTML = '<div class="treg-empty">Nema sačuvanih tragova.<br>Klikni <b>Snimi trag</b> u panelu za snimanje.</div>';
    return;
  }
  el.innerHTML = _renderGrouped(_tragRegistry, _trgGrpBy, t => {
    const lenM = _tragCalcLen(t.pts);
    const dt = fmtDateShort(t.date);
    const vis = typeof _tvTrackVisible==='function'?_tvTrackVisible(t):t.visible!==false;
    const meta = [dt, _tragFmtLen(lenM), t.pts.length+' tač.', t.gj?'GJ: <b>'+_escHtml(t.gj)+'</b>':'', t.odjel?'Odj: <b>'+_escHtml(t.odjel)+'</b>':''].filter(Boolean).join(' · ');
    return `<div class="treg-row">
      <div class="treg-name" onclick="_tragRegZoom('${t.id}')" style="border-left:3px solid ${_tvBoja(t.color)};padding-left:8px;">${_escHtml(_tragIme(t))}</div>
      <div class="treg-meta">${meta}</div>
      <div id="treg-edit-${t.id}" style="display:none;" class="treg-meta-edit">
        <div class="mf-col"><label>Naziv</label><input id="treg-ei-name-${t.id}" value="${_escHtml(t.name)}"></div>
        <div class="mf-col"><label>GJ</label>${_gjFieldHtml('treg-'+t.id, t.gj||'')}</div>
        <div class="mf-col"><label>Odjel</label><input id="treg-ei-odjel-${t.id}" value="${_escHtml(t.odjel||'')}" placeholder="npr. 14a"></div>
        <button class="mf-save" onclick="_tragRegSetMeta('${t.id}')"><svg class="ic"><use href="#ic-potvrdi"/></svg> Spremi</button>
      </div>
      <div id="treg-ugl-${t.id}" style="display:none;" class="treg-meta-edit">
        <div style="display:flex;align-items:center;gap:6px;margin-bottom:4px;">
          <span style="font-size:11px;white-space:nowrap;">Vraćanje/stajanje do:</span>
          <input type="range" id="treg-ugl-krug-${t.id}" min="0" max="15" value="5" step="1" style="flex:1;"
                 oninput="document.getElementById('treg-ugl-krug-v-${t.id}').textContent=(this.value==='0'?'isklj.':this.value+'m');_uglTragPreview('${t.id}')">
          <span id="treg-ugl-krug-v-${t.id}" style="font-size:11px;min-width:34px;">5m</span>
        </div>
        <div style="display:flex;align-items:center;gap:6px;margin-bottom:4px;">
          <span style="font-size:11px;white-space:nowrap;">Sitan šum:</span>
          <input type="range" id="treg-ugl-eps-${t.id}" min="0" max="5" value="1" step="0.5" style="flex:1;"
                 oninput="document.getElementById('treg-ugl-eps-v-${t.id}').textContent=(this.value==='0'?'isklj.':this.value+'m');_uglTragPreview('${t.id}')">
          <span id="treg-ugl-eps-v-${t.id}" style="font-size:11px;min-width:34px;">1m</span>
        </div>
        <div id="treg-ugl-info-${t.id}" style="font-size:10px;color:#94a3b8;margin-bottom:4px;"></div>
        <div style="display:flex;gap:4px;">
          <button class="mf-save" onclick="_uglTragPrimijeni('${t.id}')"><svg class="ic"><use href="#ic-potvrdi"/></svg> Primijeni</button>
          <button class="mf-save" onclick="_uglTragOtkazi('${t.id}')"><svg class="ic"><use href="#ic-zatvori"/></svg> Otkaži</button>
        </div>
      </div>
      <div class="treg-btns">
        <button onclick="_tragRegZoom('${t.id}')"><svg class="ic"><use href="#ic-karta"/></svg> Zoom</button>
        <button type="button" data-id="${_escHtml(String(t.id))}" onclick="_tragRegVodi(this.dataset.id)"><svg class="ic"><use href="#ic-kompas"/></svg> Vodi me</button>
        <button onclick="_tragRegToggle('${t.id}')">${vis?'<svg class="ic"><use href="#ic-sakrij"/></svg> Sakrij':'<svg class="ic"><use href="#ic-prikazi"/></svg> Prikaži'}</button>
        <button onclick="_uglTragOtvori('${t.id}')" title="Poravna vraćanje istim putem i mirovanje u mjestu"><svg class="ic"><use href="#ic-alat"/></svg> Ugladi</button>
        ${_uglMoguciPovratak('trag', t) ? `<button onclick="_uglVrati();_tragRegRender();"><svg class="ic"><use href="#ic-nazad"/></svg> Vrati</button>` : ''}
        <button onclick="_tragRegEditMeta('${t.id}')"><svg class="ic"><use href="#ic-crtaj"/></svg> Meta</button>
        <button onclick="_tragKmlMeni('${t.id}')"><svg class="ic"><use href="#ic-posalji"/></svg> KML</button>
        <button class="del-btn" onclick="_tragRegDelete('${t.id}')"><svg class="ic"><use href="#ic-zatvori"/></svg> Briši</button>
      </div>
    </div>`;
  });
}

// Vodi me do najbliže snimljene tačke traga; cilj je snapshot, trag se ne mijenja.
function _tragRegVodi(id) {
  const t=_tragRegistry.find(x=>x.id===id);
  const pts=(t?.pts||[]).map(p=>Array.isArray(p)?{la:p[0],lo:p[1]}:p)
    .filter(p=>p&&Number.isFinite(p.la)&&Number.isFinite(p.lo)&&Math.abs(p.la)<=90&&Math.abs(p.lo)<=180);
  if(!pts.length){showToast('Trag nema dostupne tačke za navigaciju');return;}
  const pos=lastP&&Number.isFinite(lastP.la)&&Number.isFinite(lastP.lo)?lastP:null;
  let goal=pts[0],best=Infinity;
  if(pos)for(const p of pts){const d=_haversine(pos.la,pos.lo,p.la,p.lo);if(d<best){best=d;goal=p;}}
  if(typeof closeMenuDropdown==='function')closeMenuDropdown();
  if(typeof closeMjtrgDropdown==='function')closeMjtrgDropdown();
  if(_guideOn)_guideCancel(true);_guideSession++;
  stopTackaNav();switchTab('karta');map.closePopup();
  if(!gpsOn)startGPS();
  window.Explorer?.start({la:goal.la,lo:goal.lo,name:(pos?'Tačka traga · ':'Početak traga · ')+_tragIme(t)});
  window.Explorer?.requestCompass();
}

function _tragRegZoom(id) {
  const t = _tragRegistry.find(x => x.id === id);
  if (!t || !t.pts.length) return;
  const line = _tragLayers[id];
  if (line) { map.fitBounds(line.getBounds(), {padding:[30,30]}); switchTab('karta'); closeTragRegistry(); }
}

function _tragRegToggle(id) {
  const t = _tragRegistry.find(x => x.id === id);
  if (!t) return;
  const on=typeof _tvTrackVisible==='function'?!_tvTrackVisible(t):t.visible===false;
  if(typeof _tvTrackSet==='function')_tvTrackSet(t,on);else t.visible=on;
  // Re-kreiraj slojeve kroz jedinstvenu putanju — rukuje i oznakom dužine (tragLen)
  _tragRegAddLayer(t);
  const line = _tragLayers[id];
  if (line) line.setPopupContent(_tragPopupHtml(t, _tragCalcLen(t.pts)));
  _tragRegSave();
  _tragRegRender();
}

function _tragRegDelete(id) {
  const t = _tragRegistry.find(x => x.id === id);
  if (!t) return;
  const line = _tragLayers[id];
  if (line) { try { map.removeLayer(line); } catch(e) {} delete _tragLayers[id]; }
  const hit = _tragHitLayers[id];
  if (hit) { try { map.removeLayer(hit); } catch(e) {} delete _tragHitLayers[id]; }
  if (_tragLenMk[id]) { try { map.removeLayer(_tragLenMk[id]); } catch(e) {} delete _tragLenMk[id]; }
  _tragRegistry = _tragRegistry.filter(x => x.id !== id);
  _tragRegSave();
  _tragRegRender();
  _tragoviRender();
}

// ── Tragovi panel (bottom tab) ────────────────────────────────────────────────
let _tragoviGrpBy = 'date'; // 'date' | 'gj' | 'none'

function _tragoviUpdBtn() {
  const btn = document.getElementById('btrag-panel');
  const ico = document.getElementById('btrag-panel-ico');
  const txt = document.getElementById('btrag-panel-txt');
  if (!btn) return;
  btn.classList.toggle('on', !!_tragOn);
  // SVG, ne emoji (🔴/⏹ se na Androidu crtaju različito po uređaju).
  if (ico) ico.innerHTML = '<svg class="ic"><use href="#' + (_tragOn ? 'ic-stop' : 'ic-snimaj') + '"/></svg>';
  if (txt) txt.textContent = _tragOn ? 'Zaustavi' : 'Snimi trag';
}

// Koji tab (Tragovi/Mjerenja) je otvoren — pamti se po uređaju.
var _TV_TAB_KEY = 'tvlake_tragovi_tab';
var _tragoviTab = 'trg';
try { if (localStorage.getItem(_TV_TAB_KEY) === 'msr') _tragoviTab = 'msr'; } catch(e) {}
function _tragoviSetTab(t) {
  _tragoviTab = t === 'msr' ? 'msr' : 'trg';
  try { localStorage.setItem(_TV_TAB_KEY, _tragoviTab); } catch(e) {}
  _tragoviRender();
}

var _TV_GRP_LBL = { date: 'Po datumu', gj: 'Po GJ', none: 'Bez grupa' };
function _tragoviGrpToggle() {
  const opts = ['date','gj','none'];
  _tragoviGrpBy = opts[(opts.indexOf(_tragoviGrpBy)+1) % opts.length];
  _tragoviRender();
}

// Glavna vrijednost mjerenja za karticu: površina (ha), nagib (%) ili dužina.
function _tvMsrVrijednost(m) {
  const mode = m.mode || 'dist';
  const pts = m.pts || [];
  const lenM = _msrPts2Len(pts);
  if (mode === 'area') {
    if (pts.length < 3) return { v: '—', sub: pts.length + ' tač.' };
    return { v: fmtHa(_msrPoligonPovrsina(pts) / 10000), sub: 'obim ' + _msrFmt(lenM) };
  }
  if (mode === 'nagib') {
    const a = pts[0], z = pts[pts.length - 1];
    if (!a || !z || pts.length < 2) return { v: '—', sub: '' };
    const d = _msrHaversine(a.lat, a.lng, z.lat, z.lng);
    const dh = (a.elev != null && z.elev != null) ? z.elev - a.elev : null;
    if (dh == null || !(d > 0)) return { v: '—', sub: 'dužina ' + _msrFmt(d) };
    const pct = dh / d * 100;
    return { v: (pct > 0 ? '+' : '') + pct.toFixed(1) + ' %', sub: 'dužina ' + _msrFmt(d) };
  }
  return { v: _msrFmt(lenM), sub: pts.length + ' tač.' };
}
var _TV_MSR_MOD = {
  dist:  { lbl: 'Distanca', ico: 'ic-uglomjer', cls: 'dist' },
  area:  { lbl: 'Površina', ico: 'ic-kvadrat',  cls: 'area' },
  nagib: { lbl: 'Nagib',    ico: 'ic-visina',   cls: 'nagib' },
};
function _tragoviMsrRowHtml(m) {
  const mod = _TV_MSR_MOD[m.mode] || _TV_MSR_MOD.dist;
  const val = _tvMsrVrijednost(m);
  const meta = [fmtDateShort(m.date), val.sub, m.odjel ? 'Odj. ' + _escHtml(m.odjel) : ''].filter(Boolean).join(' · ');
  return `<div class="tv-card" style="--tv-c:${m.color || '#fbbf24'};">
    <div class="tv-card-top" onclick="_msrRegZoom('${m.id}')">
      <span class="tv-mod ${mod.cls}"><svg class="ic"><use href="#${mod.ico}"/></svg></span>
      <div class="tv-card-info">
        <div class="tv-card-name">${_escHtml(m.name)}</div>
        <div class="tv-card-meta">${mod.lbl} · ${meta}</div>
      </div>
      <div class="tv-card-val">${val.v}</div>
    </div>
    <div class="tv-card-btns">
      <button onclick="_msrRegZoom('${m.id}')"><svg class="ic"><use href="#ic-crtaj"/></svg> Prikaži i uredi</button>
      <button class="del" onclick="_msrAskDelete('${m.id}')" aria-label="Obriši"><svg class="ic"><use href="#ic-obrisi"/></svg></button>
    </div>
  </div>`;
}

function _tragoviRender() {
  if(typeof _tvVisibilityRender==='function')_tvVisibilityRender();
  const el = document.getElementById('tragovi-list');
  const cnt = document.getElementById('tragovi-count');
  const notif = document.getElementById('notif-tragovi');
  if (!el) return;
  const n = _tragRegistry.length;
  const mn = _msrRegistry.length;
  if (cnt) cnt.textContent = n ? n : '';
  if (notif) notif.textContent = n || '';
  const msrCnt = document.getElementById('tragovi-msr-count');
  if (msrCnt) msrCnt.textContent = mn ? mn : '';

  const sum = document.getElementById('tv-sum');
  if (sum) {
    const ukupno = _tragRegistry.reduce((s, t) => s + _tragCalcLen(t.pts), 0);
    // 1 trag / 2–4 traga / 5+ tragova (ranije "5 traga")
    const d = n % 10, dd = n % 100;
    const rijec = (d === 1 && dd !== 11) ? ' trag' : (d >= 2 && d <= 4 && (dd < 12 || dd > 14)) ? ' traga' : ' tragova';
    sum.textContent = (n ? n + rijec + ' · ' + _tragFmtLen(ukupno) : 'Nema tragova')
      + ' · ' + (mn ? mn + (mn === 1 ? ' mjerenje' : ' mjerenja') : 'nema mjerenja');
  }
  const isMsr = _tragoviTab === 'msr';
  const segT = document.getElementById('tv-seg-trg'), segM = document.getElementById('tv-seg-msr');
  if (segT) segT.classList.toggle('on', !isMsr);
  if (segM) segM.classList.toggle('on', isMsr);
  const paneT = document.getElementById('tv-pane-trg'), paneM = document.getElementById('tv-pane-msr');
  if (paneT) paneT.style.display = isMsr ? 'none' : '';
  if (paneM) paneM.style.display = isMsr ? '' : 'none';
  const grpBtn = document.getElementById('tv-grp-btn');
  if (grpBtn) grpBtn.textContent = _TV_GRP_LBL[_tragoviGrpBy] || 'Po datumu';

  // Mjerenja se crtaju UVIJEK — ranije je rani izlaz za "nema tragova"
  // preskakao ovu sekciju, pa se mjerenja nisu vidjela dok ne postoji trag.
  const msrEl = document.getElementById('tragovi-msr-list');
  if (msrEl) {
    msrEl.innerHTML = mn
      ? _msrRegistry.map(_tragoviMsrRowHtml).join('')
      : `<div class="tv-empty"><svg class="ic"><use href="#ic-uglomjer"/></svg>
           <div>Nema sačuvanih mjerenja.</div>
           <button class="tv-chip" onclick="switchTab('karta');setTimeout(()=>_izmjeriPick('dist'),50);">Počni mjerenje</button></div>`;
  }

  if (!n) {
    el.innerHTML = `<div class="tv-empty"><svg class="ic"><use href="#ic-trag"/></svg>
      <div>Nema sačuvanih tragova.</div>
      <button class="tv-chip" onclick="fabSnimTrag()">Snimi prvi trag</button></div>`;
    return;
  }
  const trWrap = document.getElementById('tv-trazi-wrap');
  if (trWrap) trWrap.style.display = (n > 5 || _tvTrazi) ? '' : 'none';
  const q = String(_tvTrazi || '').trim().toLowerCase();
  const izvor = q ? _tragRegistry.filter(t => [_tragIme(t), t.odjel, t.gj].some(x => String(x || '').toLowerCase().includes(q))) : _tragRegistry;
  if (q && !izvor.length) {
    el.innerHTML = `<div class="tv-empty"><div>Nijedan trag ne odgovara „${_escHtml(_tvTrazi.trim())}".</div></div>`;
    return;
  }
  let groups = [];
  if (_tragoviGrpBy === 'none') {
    groups = [{ label: null, items: izvor }];
  } else {
    const map2 = new Map(), now = new Date();
    // Po datumu: najnovije prvo, bez obzira kojim redom su tragovi sačuvani.
    const red = _tragoviGrpBy === 'date' ? [...izvor].sort((a, b) => _tvTragMs(b) - _tvTragMs(a)) : izvor;
    red.forEach(t => {
      const k = _tragoviGrpBy === 'gj' ? (t.gj ? 'GJ ' + t.gj : 'Bez GJ') : _tvPeriod(_tvTragMs(t), now);
      if (!map2.has(k)) map2.set(k, []);
      map2.get(k).push(t);
    });
    groups = [...map2.entries()].map(([k, v]) => ({ label: k, items: v }));
  }
  // Zaglavlje grupe nosi i ukupnu dužinu — "koliko sam prešao ove sedmice"
  // bez sabiranja kartica napamet.
  el.innerHTML = groups.map(g => `
    ${g.label ? `<div class="tv-grp"><span>${_escHtml(g.label)}</span><span class="tv-grp-n">${g.items.length} · ${_tragFmtLen(g.items.reduce((s, t) => s + _tragCalcLen(t.pts), 0))}</span></div>` : ''}
    ${g.items.map(t => _tragoviRowHtml(t)).join('')}
  `).join('');
}

// Grupisanje po PERIODU (v2.9.5): ranije je svaki dan bio svoja grupa, pa je
// sedmica sa po jednim tragom dnevno davala 7 zaglavlja za 7 kartica — duplo
// duža lista. Sad: Danas / Jučer / Ova sedmica (zadnjih 7 dana) / mjesec.
var _TV_MJESECI = ['Januar','Februar','Mart','April','Maj','Juni','Juli','August','Septembar','Oktobar','Novembar','Decembar'];
function _tvTragMs(t) {
  const p0 = t && t.pts && t.pts[0] && t.pts[0][3];
  if (isFinite(p0) && p0 > 0) return +p0;
  const d = Date.parse(t && t.date);
  return isFinite(d) ? d : 0;
}
function _tvPeriod(ms, now) {
  if (!ms) return 'Bez datuma';
  const d = new Date(ms), n = now || new Date();
  const dan = x => new Date(x.getFullYear(), x.getMonth(), x.getDate()).getTime();
  const razlika = Math.round((dan(n) - dan(d)) / 86400000);
  if (razlika <= 0) return 'Danas';
  if (razlika === 1) return 'Jučer';
  if (razlika < 7) return 'Ova sedmica';
  return _TV_MJESECI[d.getMonth()] + ' ' + d.getFullYear();
}

// ─── Tragovi — kartice (v1.7.7) ─────────────────────────────────────────────
// Odabrana kartica (tap) otvara radnje; drugi tap na odabranu vodi na kartu —
// isti obrazac kao lista vlaka. Ranije je SVAKA kartica stalno nosila red od 5
// dugmadi (~210 px po tragu). Oko (prikaži/sakrij) ostaje uvijek vidljivo jer
// se koristi najčešće.
var _tvOtvoren = null;
var _tvTrazi = '';
// Naziv za prikaz: trag sačuvan bez imena je imao PRAZAN naslov kartice.
function _tragIme(t) {
  if (t && String(t.name || '').trim()) return String(t.name).trim();
  const ms = t && t.pts && t.pts[0] && t.pts[0][3];
  const d = new Date(isFinite(ms) && ms ? ms : (t && t.date) || Date.now());
  return 'Trag ' + fmtDateShort(d.toISOString()) + ' ' + String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');
}
// Početak i trajanje snimanja iz vremena tačaka ([la, lo, alt, ts, acc]).
function _tragVrijeme(t) {
  const pts = (t && t.pts) || [];
  const t0 = pts.length ? pts[0][3] : null, t1 = pts.length ? pts[pts.length - 1][3] : null;
  if (!isFinite(t0) || !isFinite(t1) || !t0 || !t1 || t1 < t0) return '';
  const d0 = new Date(t0);
  const poc = String(d0.getHours()).padStart(2, '0') + ':' + String(d0.getMinutes()).padStart(2, '0');
  const min = Math.round((t1 - t0) / 60000);
  const traj = min < 1 ? '' : min < 60 ? min + ' min' : Math.floor(min / 60) + ' h' + (min % 60 ? ' ' + (min % 60) + ' min' : '');
  return traj ? poc + ' · ' + traj : poc;
}
function _tvBoja(c) { return /^#[0-9a-fA-F]{3,8}$/.test(String(c || '')) ? c : '#f97316'; }
function _tvOdaberi(id) {
  if (_tvOtvoren === id) { _tragRegZoom(id); return; }
  _tvOtvoren = id;
  _tragoviRender();
}

function _tragoviRowHtml(t) {
  const lenM = _tragCalcLen(t.pts);
  const dt = fmtDateShort(t.date);
  const vis = typeof _tvTrackVisible==='function'?_tvTrackVisible(t):t.visible!==false;
  const otvoren = _tvOtvoren === t.id;
  const bezImena = !String(t.name || '').trim();
  // Datum se izostavlja samo kad ga zaglavlje grupe već jednoznačno kaže (Danas/Jučer).
  const per = _tragoviGrpBy === 'date' ? _tvPeriod(_tvTragMs(t)) : '';
  const meta = [per === 'Danas' || per === 'Jučer' ? '' : dt, _tragVrijeme(t), t.pts.length + ' tač.', t.odjel ? 'Odj. ' + _escHtml(t.odjel) : '', t.gj && _tragoviGrpBy !== 'gj' ? 'GJ ' + _escHtml(t.gj) : ''].filter(Boolean).join(' · ');
  return `<div class="tv-card tv-trg${vis ? '' : ' skriven'}${otvoren ? ' otvoren' : ''}" style="--tv-c:${_tvBoja(t.color)};">
    <div class="tv-card-top" onclick="_tvOdaberi('${t.id}')" title="${otvoren ? 'Prikaži na karti' : 'Otvori radnje'}">
      <span class="tv-bar"></span>
      <div class="tv-card-info">
        <div class="tv-card-name${bezImena ? ' bez-imena' : ''}">${_escHtml(_tragIme(t))}</div>
        <div class="tv-card-meta">${meta}</div>
      </div>
      <div class="tv-card-val">${_tragFmtLen(lenM)}</div>
      <button class="tv-oko" onclick="event.stopPropagation();_tragRegToggle('${t.id}');_tragoviRender()" aria-label="${vis ? 'Sakrij sa karte' : 'Prikaži na karti'}" title="${vis ? 'Sakrij sa karte' : 'Prikaži na karti'}">${vis ? '<svg class="ic"><use href="#ic-prikazi"/></svg>' : '<svg class="ic"><use href="#ic-sakrij"/></svg>'}</button>
    </div>
    ${otvoren ? `<div class="tv-card-btns">
      <button onclick="_tragRegZoom('${t.id}')"><svg class="ic"><use href="#ic-karta"/></svg> Karta</button>
      <button onclick="_tragKmlMeni('${t.id}')" title="Izvezi kao KML / podijeli"><svg class="ic"><use href="#ic-posalji"/></svg> KML</button>
      <button onclick="_tragoviToggleEdit('${t.id}')" aria-label="Uredi" title="Uredi"><svg class="ic"><use href="#ic-crtaj"/></svg></button>
      <button onclick="_tragoviUgladi('${t.id}')" aria-label="Ugladi" title="Ugladi trag"><svg class="ic"><use href="#ic-alat"/></svg></button>
      <button class="del" onclick="_tragoviObrisi('${t.id}')" aria-label="Obriši" title="Obriši"><svg class="ic"><use href="#ic-obrisi"/></svg></button>
    </div>
    <div id="tred-${t.id}" style="display:none;" class="tred-row"></div>` : ''}
  </div>`;
}

// Uređivanje se gradi TEK kad se otvori. Ranije je za SVAKI trag pri SVAKOM
// crtanju liste nastajao i skriveni red za SVAKU GPS tačku — trag od 6 h ima
// ~4000 tačaka, pa su to bile hiljade DOM elemenata koje niko ne vidi.
function _tragoviEditHtml(t) {
  const w = t.weight || 3;
  const style = t.dashStyle || 'solid';
  return `
      <div>
        <label>Naziv</label>
        <input id="tred-nm-${t.id}" value="${_escHtml(t.name || '')}" placeholder="${_escHtml(_tragIme(t))}" style="width:100%;background:#1e293b;border:1px solid #334155;border-radius:6px;color:#e2e8f0;padding:5px 8px;font-size:13px;" onchange="_tragoviSetName('${t.id}',this.value)">
      </div>
      <div style="display:flex;gap:12px;align-items:center;">
        <div>
          <label>Boja</label>
          <input type="color" value="${_tvBoja(t.color)}" onchange="_tragoviSetColor('${t.id}',this.value)">
        </div>
        <div style="flex:1;">
          <label>Debljina: <span id="tred-w-lbl-${t.id}">${w}px</span></label>
          <input type="range" min="1" max="10" value="${w}" oninput="_tragoviSetWeight('${t.id}',+this.value)">
        </div>
      </div>
      <div>
        <label>Stil linije</label>
        <div class="tred-style-btns">
          <button class="${style==='solid'?'active':''}" onclick="_tragoviSetStyle('${t.id}','solid')"><svg class="ic"><use href="#ic-puna"/></svg> Puna</button>
          <button class="${style==='dash'?'active':''}" onclick="_tragoviSetStyle('${t.id}','dash')"><svg class="ic"><use href="#ic-crtkana"/></svg> Iscrtkana</button>
          <button class="${style==='dot'?'active':''}" onclick="_tragoviSetStyle('${t.id}','dot')">· Tačkasta</button>
        </div>
      </div>
      <div>
        <label style="cursor:pointer;" onclick="_tragoviTogglePts('${t.id}')">📍 Tačke (${t.pts.length}) <span style="color:#475569;">▾</span></label>
        <div id="tred-pts-${t.id}" style="display:none;" class="tred-pts-list"></div>
      </div>`;
}
// Lista tačaka: najviše 500 redova odjednom — brisanje pojedinačne tačke je
// alat za očigledan GPS odskok, ne za listanje hiljada koordinata.
var _TV_PTS_MAX = 500;
function _tragoviPtsHtml(t) {
  const n = t.pts.length, max = Math.min(n, _TV_PTS_MAX);
  let h = '';
  for (let i = 0; i < max; i++) {
    const p = t.pts[i];
    h += `<div class="tred-pt-row">
            <span class="tred-pt-idx">#${i+1}</span>
            <span>${(+p[0]).toFixed(6)}, ${(+p[1]).toFixed(6)}${p[2]?' · '+Math.round(p[2])+'m':''}</span>
            <button class="tred-pt-del" onclick="_tragoviDelPt('${t.id}',${i})" title="Obriši tačku"><svg class="ic"><use href="#ic-zatvori"/></svg></button>
          </div>`;
  }
  if (n > max) h += `<div class="tred-pt-row" style="color:#64748b;justify-content:center;">…još ${n - max} tačaka (za čišćenje koristi Ugladi)</div>`;
  return h;
}

// Ugladi živi u listi Mjerenja i tragovi (treg-ugl-*): otvori baš taj trag
// tamo umjesto da se isti alat i ID-evi dupliraju u ovom panelu.
function _tragoviUgladi(id) {
  switchTab('mjtrg');
  _mjtrgTab('trg');
  setTimeout(() => {
    const box = document.getElementById('treg-ugl-' + id);
    if (box && box.style.display === 'none' && typeof _uglTragOtvori === 'function') _uglTragOtvori(id);
    const row = box && box.closest('.treg-row');
    if (row) row.scrollIntoView({ block: 'center', behavior: 'smooth' });
  }, 120);
}

// HTML dijalog umjesto native confirm() — isti izgled kao ostatak app-a.
async function _tragoviObrisi(id) {
  const t = _tragRegistry.find(x => x.id === id);
  if (!t) return;
  const ok = await _dlgConfirm('Obrisati trag "' + _tragIme(t) + '"? Ova radnja se ne može poništiti.', { title: 'Obriši trag', danger: true });
  if (ok) _tragRegDelete(id);
}

function _tragoviToggleEdit(id) {
  const el = document.getElementById('tred-'+id);
  if (!el) return;
  const otvara = el.style.display === 'none';
  if (otvara && !el.childElementCount) {
    const t = _tragRegistry.find(x => x.id === id);
    if (t) el.innerHTML = _tragoviEditHtml(t);
  }
  el.style.display = otvara ? '' : 'none';
}
function _tragoviTogglePts(id) {
  const el = document.getElementById('tred-pts-'+id);
  if (!el) return;
  const otvara = el.style.display === 'none';
  if (otvara) { const t = _tragRegistry.find(x => x.id === id); if (t) el.innerHTML = _tragoviPtsHtml(t); }
  el.style.display = otvara ? '' : 'none';
}
function _tragoviSetName(id, val) {
  const t = _tragRegistry.find(x => x.id === id);
  if (!t) return;
  t.name = val.trim() || t.name;
  _tragRegSave();
}
function _tragoviSetColor(id, col) {
  const t = _tragRegistry.find(x => x.id === id);
  if (!t) return;
  t.color = col;
  t.colorRucno = true;
  const line = _tragLayers[id];
  if (line) line.setStyle({ color: col });
  _tragRegSave();
}
function _tragoviSetWeight(id, w) {
  const t = _tragRegistry.find(x => x.id === id);
  if (!t) return;
  t.weight = w;
  const lbl = document.getElementById('tred-w-lbl-'+id);
  if (lbl) lbl.textContent = w+'px';
  const line = _tragLayers[id];
  if (line) line.setStyle({ weight: w });
  _tragRegSave();
}
function _tragoviSetStyle(id, s) {
  const t = _tragRegistry.find(x => x.id === id);
  if (!t) return;
  t.dashStyle = s;
  const dashArray = s==='solid' ? null : s==='dot' ? '2 6' : '8 5';
  const line = _tragLayers[id];
  if (line) line.setStyle({ dashArray });
  _tragRegSave();
  // Refresh edit panel da ažurira active stanje dugmadi
  const ed = document.getElementById('tred-'+id);
  if (ed && ed.style.display !== 'none') {
    _tragoviRender();
    // Novi red je prazan (editor se gradi tek pri otvaranju) — napuni ga prije
    // prikaza, inače bi se panel sklopio u praznu kutiju.
    const edNew = document.getElementById('tred-'+id);
    if (edNew) { edNew.innerHTML = _tragoviEditHtml(t); edNew.style.display = ''; }
  }
}
function _tragoviDelPt(id, idx) {
  const t = _tragRegistry.find(x => x.id === id);
  if (!t || t.pts.length <= 2) { showToast('⚠ Trag mora imati min. 2 tačke'); return; }
  t.pts.splice(idx, 1);
  // Cijeli sloj iznova (linija, nevidljivi sloj za klik, oznaka dužine, popup)
  // — samo setLatLngs je ostavljao klikabilan uklonjeni skok i staru dužinu.
  _tragRegAddLayer(t);
  _tragRegSave();
  _tragoviRender();
  // Ponovo otvori edit panel sa listom tačaka
  setTimeout(() => {
    const ed = document.getElementById('tred-'+id);
    if (ed) { ed.innerHTML = _tragoviEditHtml(t); ed.style.display = ''; _tragoviTogglePts(id); }
  }, 0);
}

async function _tragRegRename(id) {
  const t = _tragRegistry.find(x => x.id === id);
  if (!t) return;
  const name = await _dlgPrompt('Novo ime traga:', t.name, { title: 'Preimenuj trag' });
  if (name && name.trim()) {
    t.name = name.trim();
    const line = _tragLayers[id];
    if (line) line.setPopupContent(_tragPopupHtml(t, _tragCalcLen(t.pts)));
    _tragRegSave();
    _tragRegRender();
  }
}

function _tragToKml(t) {
  const coords = t.pts.map(p => `${p[1]},${p[0]},0`).join('\n              ');
  return `<?xml version="1.0" encoding="UTF-8"?>
<kml xmlns="http://www.opengis.net/kml/2.2">
<Document><name>${_escXml(_tragIme(t))}</name>
  <Placemark>
    <name>${_escXml(_tragIme(t))}</name>
    <Style><LineStyle><color>${_hexToKmlColor(t.color||'#f97316')}</color><width>3</width></LineStyle><PolyStyle><fill>0</fill></PolyStyle></Style>
    <LineString><tessellate>1</tessellate><coordinates>${coords}</coordinates></LineString>
  </Placemark>
</Document></kml>`;
}

// Dijeljenje traga kao KML preko native share sheet-a (Bluetooth/mail/mreže...).
// U APK-u navigator.share() NE otvara sistemski birač za fajlove (Android
// WebView, za razliku od Chrome-a, ne podržava Web Share Target za priloge —
// canShare({files}) tiho vrati false), pa se prvo pokuša native AndroidShare
// most (pravi Intent.ACTION_SEND chooser sa Viber/Messenger/Bluetooth/mail...).
// Web Share API i obično preuzimanje ostaju fallback za webapp (Pages)/desktop.
async function _tragRegShare(id) {
  const t = _tragRegistry.find(x => x.id === id);
  if (!t) return;
  const ime = _tragIme(t);
  await _shareKmlOrDownload(_tragKmlIme(t), _tragToKml(t), ime, 'Trag: ' + ime, () => _tragKmlSacuvaj(id));
}

// Ime fajla iz naziva traga — dijakritika ostaje (Android je podržava), a
// izbacuju se samo znakovi koje sistem fajlova ne dozvoljava. Ranije je
// `t.name.replace(...)` za trag bez imena davalo fajl ".kml".
function _tragKmlIme(t) {
  const osnova = String(_tragIme(t) || 'trag').replace(/[\\/:*?"<>|]+/g, '').replace(/\s+/g, '_').slice(0, 60);
  return (osnova || 'trag') + '.kml';
}

// Sačuvaj na uređaj: u APK-u <a download> presreće AndroidDownload most
// (blob → Downloads), u browseru je obično preuzimanje.
function _tragKmlSacuvaj(id) {
  const t = _tragRegistry.find(x => x.id === id);
  if (!t) return;
  const a = document.createElement('a');
  a.href = URL.createObjectURL(new Blob([_tragToKml(t)], { type: 'application/vnd.google-earth.kml+xml' }));
  a.download = _tragKmlIme(t);
  a.click();
  setTimeout(() => URL.revokeObjectURL(a.href), 4000);
  showToast('💾 Sačuvano: ' + a.download);
}

// Jedan ulaz za izvoz traga (v1.8.1) — kartica traga, popup na karti i Teren.
// Zamjenjuje meni "KML izvoz" (izvozio je samo vlake, nikad tragove).
async function _tragKmlMeni(id) {
  const t = _tragRegistry.find(x => x.id === id);
  if (!t) return;
  try { map.closePopup(); } catch (e) {}
  const i = await _dlgActions('📄 ' + _tragIme(t) + ' — KML', [
    { label: '<svg class="ic"><use href="#ic-posalji"/></svg> Podijeli (Viber, WhatsApp, e-mail…)' },
    { label: '<svg class="ic"><use href="#ic-uvezi"/></svg> Sačuvaj .kml na telefon' },
  ]);
  if (i === 0) _tragRegShare(id);
  else if (i === 1) _tragKmlSacuvaj(id);
}

function _toggleLocPopup() {
  const p = document.getElementById('ab-loc-popup');
  const opening = p.style.display === 'none';
  p.style.display = opening ? 'block' : 'none';
  if (opening) {
    _updGpsSwitch();
    _locPopTimerStart();
    const im = document.getElementById('ab-izmjeri-menu'); if (im) im.style.display = 'none';
  }
}
function _locPopupCentriraj() {
  document.getElementById('ab-loc-popup').style.display = 'none';
  fabLokacija();
}
// Prečica za snimanje traga direktno iz "Moja lokacija" popupa (v3.126.0) —
// bez ovoga korisnik koji je već otvorio ovaj popup radi GPS/kompasa mora
// zatvoriti ga i tražiti Tragovi tab da bi počeo snimati. fabSnimTrag() je
// već TOGGLE (start kad ne snima, spremi/završi kad snima), pa se poziva
// direktno — nema duple logike ovdje.
function _locPopupSnimiTrag() {
  document.getElementById('ab-loc-popup').style.display = 'none';
  fabSnimTrag();
}
function fabLokacija() {
  // Vraćanje na svoju poziciju znači "opet prati moju GPS visinu" — vidi
  // komentar uz _userPannedAway.
  _userPannedAway = false;
  _updCentarBtn();
  if (lastP) {
    map.setView([lastP.la, lastP.lo], Math.max(map.getZoom(), 16));
  } else {
    showToast('⏳ Pokretanje GPS-a...');
    startGPS();
    const wait = setInterval(() => {
      if (lastP) { clearInterval(wait); map.setView([lastP.la, lastP.lo], 16); }
    }, 500);
    setTimeout(() => clearInterval(wait), 15000);
  }
  // Vizualna potvrda — kratki pulse na gumbu
  const btn = document.getElementById('loc-fixed-btn');
  if (btn) {
    btn.style.borderColor = '#3b82f6';
    setTimeout(() => { btn.style.borderColor = ''; }, 600);
  }
}

function fabSnimTrag() {
  if (_tragOn) {
    if (_tragPts.length > 1) {
      const pts3d = _tragPts.map(([la, lo, al, t, ac]) => ({la, lo, al, t, ac}));
      // Blaga tolerancija (0.8 m) — čuva vrhove zavoja da se vijugav put ne
      // izravna; i dalje briše najsitniji jitter na ravnim dionicama.
      // try/catch: _rdpSimplify je REKURZIVAN (O(n) dubina na degenerisanom
      // ulazu — duga glatka serpentina). Ako pukne stack, bez ovoga bi se
      // izgubio CIJELI trag (i _bgRecStopIfIdle se ne bi pozvao → servis/
      // wake lock cure). Vlaka ekvivalent (_simplifyRecordedPts) već ima guard.
      let simp;
      try { simp = _rdpSimplify(pts3d, 0.8); } catch(e) { simp = pts3d; }
      // Vrijeme i tačnost ostaju: bez njih kartica traga ne zna početak ni trajanje.
      const final = (simp.length >= 2 ? simp : pts3d).map(p => [p.la, p.lo, p.al, p.t, p.ac]);
      const saved = _tragRegAdd(final, _tragLiveMeta);
      if (!saved) { showToast('⚠ Trag nije sačuvan — oslobodi prostor i pokušaj ponovo'); return; }
      if (_activeTab === 'teren') {
        terenRenderTragovi();
        showToast('✅ Trag sačuvan (' + _tragFmtLen(_tragCalcLen(final)) + ')');
      } else {
        _tqmOpen(saved.id);
      }
    } else {
      showToast('⚠ Trag nije snimljen — premalo GPS tačaka (GPS signal slab?)');
    }
    _tragOn = false;
    _tragPaused = false;
    _pauziZavrsi(_tragPauseWin);   // stop usred pauze bi inače ostavio vječno otvoren interval
    if (_tragLine) { map.removeLayer(_tragLine); _tragLine = null; }
    _tragLiveClear();
    const bt = document.getElementById('btrag');
    if (bt) bt.classList.remove('active');
    _updFabVisibility();
    if (typeof _terenUpdTragUI === 'function') _terenUpdTragUI();
    _tragPts = [];
    _tragBuf = [];
    _tragLastT = 0;
    _tragRetraceReset(0);
    _tragLiveMeta = null;
    _tragUrediZatvori();
    _crashClearTrag();  // normalno sačuvan
    _bgRecStopIfIdle(); // otpusti pozadinski servis ako ništa drugo ne snima
    _crashStopIfIdle(); // vlaka koja i dalje snima mora zadržati svoj auto-save
  } else {
    _gpsStabilizeGate(_fabSnimTragBegin);
  }
}

function _fabSnimTragBegin() {
    if (!gpsOn) startGPS();
    _setFreeView(false);
    _tragOn     = true;
    _tragPaused = false;
    _pauziResetuj(_tragPauseWin);  // zaostala pauza prethodne sesije ne smije suditi novim tačkama
    _tragPts = [];
    _tragBuf = [];
    _tragLastT = 0;
    _tragRetraceReset(0);
    if (_tragLine) { map.removeLayer(_tragLine); _tragLine = null; }
    _tragLiveClear();
    _tragLiveMeta = {};
    _tragLine = L.polyline([], _tragLiveStil()).addTo(map);
    const bt = document.getElementById('btrag');
    if (bt) bt.classList.add('active');
    // Ako je snimanje pokrenuto iz Tragovi panela, prebaci na kartu da se vidi trag uživo
    if (_activeTab === 'tragovi') switchTab('karta');
    _updFabVisibility();
    if (typeof _terenUpdTragUI === 'function') _terenUpdTragUI();
    _updTragStats();
    _crashStartTimer();   // auto-save svakih 30s
    _crashSaveTrag(true);
    _bgRecStart('trag');  // pozadinsko snimanje — nastavi i kad app ode u pozadinu
}

function togTragPause() {
  if (!_tragOn) return;
  _tragPaused = !_tragPaused;
  if (_tragPaused) _pauziOtvoriProzor(_tragPauseWin); else _pauziZatvoriProzor(_tragPauseWin);
  if (_tragPaused) _crashSaveTrag(true);  // tačke do pauze — periodični upis u pauzi stoji
  const ico = document.getElementById('ab-trag-pauza-ico');
  const txt = document.getElementById('ab-trag-pauza-txt');
  const btn = document.getElementById('ab-trag-pauza');
  if (_tragPaused) {
    // Očisti živi vrh i resetuj filtere — bez artefakt-linije preko pauze
    _tragLiveClear();
    _tragBuf = [];
    _tragLastT = 0;
    _tragRetrace = null;
    if (ico) ico.innerHTML = '<svg class="ic"><use href="#ic-pocni"/></svg>';
    if (txt) txt.textContent = 'Nastavi';
    if (btn) btn.classList.add('resuming');
    showToast('⏸ Snimanje traga pauzirano');
  } else {
    // Baza za speed-gate mora biti "sada", ne 0 — inače prva tačka poslije
    // pauze računa dtS kao lažnih 1s (umjesto stvarnog trajanja pauze), pa
    // je odbija kao "nemoguć skok" ako se korisnik u međuvremenu pomjerio.
    // Bez ovoga se ta i SVAKA naredna tačka trajno odbijaju (razdaljina od
    // "zaleđene" zadnje tačke samo raste) — snimanje izgleda aktivno ali
    // ništa se ne upisuje dok se ručno ne pauzira/nastavi ponovo.
    _tragLastT = Date.now();
    _tragLastMoveT = Date.now();
    if (ico) ico.innerHTML = '<svg class="ic"><use href="#ic-pauza"/></svg>';
    if (txt) txt.textContent = 'Pauza';
    if (btn) btn.classList.remove('resuming');
    showToast('🔴 Snimanje traga nastavljeno');
  }
  if (typeof _terenUpdTragUI === 'function') _terenUpdTragUI();
}

function _updTragStats() {
  const el = document.getElementById('ab-trag-info');
  if (!el) return;
  const n = _tragPts.length;
  const d = _tragCalcLen(_tragPts);
  el.textContent = `${n} tač. · ${_tragFmtLen(d)}`;
}

// ─── Povratak istim putem tokom snimanja traga (v1.9.2) ─────────────────────
const _TRAG_RETRACE_MAX_M = 30;
let _tragRetrace = null;     // { zadnja, sidro: tačke NA liniji, br } dok se hoda po snimljenom
let _tragRetraceBaza = 0;    // tačke prije ovog indeksa se ne gledaju (i ne skidaju)
// ─── Uređivanje traga TOKOM snimanja (v3.0.0) ────────────────────────────────
// Snimani trag još nije u registru (upisuje ga tek "Završi"), pa naziv/boja/
// stil čekaju u _tragLiveMeta i prelaze na sačuvani trag. Uklanjanje zadnjih
// tačaka služi za pogrešan skretaj ili GPS odskok koji se vidi odmah na karti.
let _tragLiveMeta = null;
function _tragDashArr(d) { return d === 'dot' ? '2 6' : (d === 'dash' ? '8 4' : null); }
function _tragLiveStil() {
  const m = _tragLiveMeta || {};
  // Ista pravila kao sačuvani trag (_tragRegAddLayer) — inače bi linija na
  // "Završi" promijenila izgled.
  return { color: m.color || _lineStyle.tragCol || '#f97316', weight: m.weight || _lineStyle.tragW,
           opacity: (_lineStyle.tragOp || 85) / 100,
           dashArray: _tragDashArr(m.dashStyle || _lineStyle.tragDash), pane: 'tragMsrLines' };
}
function _tragUrediOtvori() {
  if (!_tragOn) return;
  if (!_tragLiveMeta) _tragLiveMeta = {};
  const m = _tragLiveMeta;
  const el = document.getElementById('trag-ured-body');
  if (el) {
    const boja = m.color || '#f97316', stil = m.dashStyle || 'solid';
    const boje = ['#f97316', ..._TRAG_COLORS.filter(c => c !== '#f97316')].slice(0, 8);
    el.innerHTML = `
      <label class="tu-lbl" for="tu-naziv">Naziv</label>
      <input id="tu-naziv" type="text" value="${_escHtml(m.name || '')}" placeholder="Trag ${_escHtml(fmtDateShort(new Date().toISOString()))}" autocomplete="off" oninput="_tragUrediSet('name', this.value)">
      <div class="tu-lbl">Boja</div>
      <div class="tu-boje">${boje.map(c => `<button class="tu-boja${c === boja ? ' on' : ''}" style="background:${c}" onclick="_tragUrediSet('color','${c}')" aria-label="Boja ${c}"></button>`).join('')}</div>
      <div class="tu-lbl">Stil linije</div>
      <div class="tu-stil">${[['solid','Puna'],['dash','Iscrtkana'],['dot','Tačkasta']].map(([k, n]) => `<button class="${k === stil ? 'on' : ''}" onclick="_tragUrediSet('dashStyle','${k}')">${n}</button>`).join('')}</div>
      <div class="tu-lbl">Ukloni zadnji dio <span class="tu-info" id="tu-info"></span></div>
      <div class="tu-stil">
        <button onclick="_tragUkloniZadnje(0)">Zadnju tačku</button>
        <button onclick="_tragUkloniZadnje(20)">Zadnjih 20 m</button>
        <button onclick="_tragUkloniZadnje(50)">Zadnjih 50 m</button>
      </div>`;
    _tragUrediInfo();
  }
  _rsList('trag-ured', true);
}
function _tragUrediZatvori() { try { _rsList('trag-ured', false); } catch(e) {} }
function _tragUrediInfo() {
  const i = document.getElementById('tu-info');
  if (i) i.textContent = '· ' + _tragPts.length + ' tač. · ' + _tragFmtLen(_tragCalcLen(_tragPts));
}
function _tragUrediSet(k, v) {
  if (!_tragOn) return;
  if (!_tragLiveMeta) _tragLiveMeta = {};
  _tragLiveMeta[k] = v;
  if (_tragLine) _tragLine.setStyle(_tragLiveStil());
  if (k !== 'name') _tragUrediOtvori();   // osvježi označeni izbor (naziv ne — fokus polja)
}
// Skida tačke s kraja: metri=0 → tačno jednu, inače dok se ne skine bar toliko
// metara. Prva tačka ostaje uvijek (trag ne smije nestati ispod korisnika).
function _tragUkloniZadnje(metri) {
  if (!_tragOn || _tragPts.length < 2) { showToast('Nema šta ukloniti'); return 0; }
  let skinuto = 0, n = 0;
  while (_tragPts.length > 1) {
    const a = _tragPts[_tragPts.length - 1], b = _tragPts[_tragPts.length - 2];
    skinuto += dst(a[0], a[1], b[0], b[1]);
    _tragPts.pop(); n++;
    if (!metri || skinuto >= metri) break;
  }
  const last = _tragPts[_tragPts.length - 1];
  // Brzinska kapija mjeri od nove zadnje tačke — sa njenim STVARNIM vremenom,
  // inače bi sljedeći fiks izgledao kao nemoguć skok i trag bi stao.
  _tragLastT = (last && last[3]) || 0;
  _tragBuf = [];
  _tragRetraceReset(Math.min(_tragRetraceBaza, _tragPts.length - 1));
  _tragLiveClear();
  _tragLineSync();
  _updTragStats();
  if (_activeTab === 'teren' && typeof terenUpdTragStats === 'function') terenUpdTragStats();
  // I u pauzi i sa jednom tačkom: snimak ne smije vratiti ono što je korisnik uklonio.
  try { _crashSaveTrag(true); } catch(e) {}
  _tragUrediInfo();
  showToast('↶ Uklonjeno ' + n + ' tač. (' + _tragFmtLen(skinuto) + ')');
  return n;
}
function _tragRetraceReset(baza) { _tragRetrace = null; _tragRetraceBaza = baza > 0 ? baza : 0; }
function _tragLineSync() { if (_tragLine) _tragLine.setLatLngs(_tragPts.map(p => [p[0], p[1]])); }
// Vraća true kad se tačka upisuje normalno, false kad je hod po snimljenom.
function _tragRetraceKorak(la, lo, ac, al, now) {
  const w = _vlRetraceSirina(ac), baza = _tragRetraceBaza, uToku = !!_tragRetrace;
  const osnova = !uToku && _vlVrhSumnjiv(_tragPts, w, baza) ? _tragPts.slice(0, -1) : _tragPts;
  const proj = _vlRetraceTest(osnova, la, lo, w, uToku ? 0.3 : 2, baza);
  const naLiniji = proj ? [proj.la, proj.lo, al, now, Math.round(ac)] : null;
  if (proj && proj.iza > _TRAG_RETRACE_MAX_M) {
    // Dug povratak: od ovog mjesta je to nov dio hoda. Prva tačka ide NA liniju
    // (tetiva od vrha leži preko već snimljenog, ne preko šume), a stari dio
    // se više ne gleda — inače bi svaki korak nazad opet bio "povratak".
    if (uToku) { _tragPts.push(naLiniji); if (_tragLine) _tragLine.addLatLng([proj.la, proj.lo]); }
    _tragRetraceReset(_tragPts.length - 1);
    return true;
  }
  if (proj) {
    if (!uToku) {
      _tragRetrace = { zadnja: null, sidro: null, br: 0 };
      if (_vlRetraceObreziVrh(_tragPts, w, baza)) { _tragLineSync(); _updTragStats(); }
    }
    if (++_tragRetrace.br === 3) showToast('↩ Hodaš po već snimljenom dijelu traga — ne upisuje se dvaput');
    // Hod nazad JESTE kretanje (auto-pauza ne smije okinuti), ali stajanje
    // iza vrha nije. Pomak se mjeri od SIDRA koje se pomjera tek kad je pređeno
    // 2 m — od prethodnog fiksa bi spor hod (1 m po fiksu) izgledao kao mirovanje.
    const s = _tragRetrace.sidro;
    if (!s || dst(s[0], s[1], proj.la, proj.lo) >= 2) { _tragLastMoveT = now; _tragRetrace.sidro = naLiniji; }
    _tragRetrace.zadnja = naLiniji;
    return false;
  }
  if (uToku) {
    const z = _tragRetrace.zadnja, tip = _tragPts[_tragPts.length - 1];
    _tragRetrace = null;
    if (z && tip && dst(tip[0], tip[1], la, lo) > 2 * w) {
      // Sišao sa linije daleko od vrha — linija se vraća do mjesta silaska.
      _tragPts.push(z);
      if (_tragLine) _tragLine.addLatLng([z[0], z[1]]);
    } else if (_vlRetraceSkiniSiljak(_tragPts, [la, lo], w, baza)) {
      _tragLineSync();
    }
  }
  return true;
}

let _tragBuf = [];      // kružni buffer zadnja 3 raw GPS fixa za median filtar
let _tragLastT = 0;     // timestamp zadnje commit tačke (za speed-gate)
let _tragLiveSeg = null;// živi "rubber-band" segment do trenutne pozicije
let _tragLastMoveT = 0; // timestamp zadnjeg stvarnog pomaka (za auto-pauzu)
const _TRAG_AUTOPAUSE_MS = 120000; // 2 min mirovanja → auto-pauza

function _addTragPoint(la, lo, ac, al, sp, nowOverride, bypassPauzu) {
  if (!_tragOn || (_tragPaused && !bypassPauzu)) return;

  // 1. Odbaci samo katastrofalno loše fikseve
  if (ac > 50) return;

  // nowOverride: koristi se pri "replay-u" tačaka iz native GPS bafera
  // (_drainNativeGpsBuffer) — te tačke su prikupljene RANIJE (dok je WebView
  // bio bez prozora), pa moraju nositi svoj STVARNI historijski timestamp da
  // bi speed-gate (korak 3) i auto-pauza (korak 4a) računali stvaran razmak
  // između fiksova, a ne razmak "sad minus prije 10 minuta" kao da je jedan
  // ogroman skok u trenutku vraćanja u app.
  const now = nowOverride || Date.now();

  // 2. Median filtar od 3 fiksa — biramo STVARNI fix najbliži centroidu
  //    (median po odvojenim osama bi mogao stvoriti tačku koja ne postoji → artefakt)
  _tragBuf.push({ la, lo });
  if (_tragBuf.length > 3) _tragBuf.shift();
  let mla = la, mlo = lo;
  if (_tragBuf.length === 3) {
    const cla = (_tragBuf[0].la + _tragBuf[1].la + _tragBuf[2].la) / 3;
    const clo = (_tragBuf[0].lo + _tragBuf[1].lo + _tragBuf[2].lo) / 3;
    let best = _tragBuf[0], bd = Infinity;
    for (const p of _tragBuf) {
      const dd = (p.la - cla) ** 2 + (p.lo - clo) ** 2;
      if (dd < bd) { bd = dd; best = p; }
    }
    mla = best.la; mlo = best.lo;
  }

  // 3. Odluka o commit-u tačke u trajni trag
  let commit = true;
  if (_tragPts.length > 0) {
    const last = _tragPts[_tragPts.length - 1];
    const d    = dst(last[0], last[1], mla, mlo);
    // Adaptivan prag zavisi od KRETANJA: dok se korisnik stvarno kreće
    // (GPS speed > 0.4 m/s) prag je ~2 m — hvata tijesne zavoje vjerno.
    // Dok STOJI (ili speed nije dostupan) prag je 4 m kao ranije — GPS
    // multipath pod krošnjom drifta 2-5 m i bez ovoga bi pravio lažne
    // commitove koji resetuju _tragLastMoveT (auto-pauza nikad ne okine)
    // i naduvavaju dužinu traga dok korisnik npr. doznačava stabla u mjestu.
    const moving = (typeof sp === 'number' && isFinite(sp) && sp > 0.4);
    const minD = Math.max(moving ? 2 : 4, (ac || 10) * 0.15);
    if (d < minD) {
      commit = false;                       // premalo kretanja — ne dodaji novu tačku
    } else {
      // SPEED-GATE umjesto fiksne udaljenosti: dozvoli brzo kretanje vozila,
      // odbaci samo nemoguće skokove (GPS spike). 35 m/s ≈ 126 km/h.
      // Namjerno BEZ bearing/near-reversal provjere — filtriranje po uglu
      // zaokreta neizbježno pogađa i pravu vratnju, ne samo GPS multipath.
      // Kratak povratak istim putem (v1.9.2) se prepoznaje po POLOŽAJU u
      // odnosu na već snimljeni trag (korak 3b), a dug povratak ostaje
      // snimljen kao stvarno kretanje.
      const dtS = _tragLastT ? Math.max(0.5, (now - _tragLastT) / 1000) : 1;
      if (d / dtS > 35) commit = false;
    }
  }

  // 3b. HOD PO VEĆ SNIMLJENOM DIJELU (v1.9.2) — ista geometrija kao vlaka
  //     (_vlRetraceTest): okret par metara nazad pa opet naprijed ne smije
  //     ostaviti petlju. Razlika od vlake: trag je HISTORIJA hoda, ne samo
  //     geometrija puta. Povratak dalji od _TRAG_RETRACE_MAX_M (ode 500 m putem
  //     i vrati se) je stvarno kretanje i snima se — inače bi dužina traga
  //     tiho izgubila pola pređenog.
  if (commit) commit = _tragRetraceKorak(mla, mlo, ac, al, now);

  if (commit) {
    _tragPts.push([mla, mlo, al, now, Math.round(ac)]);  // [la, lo, alt, timestamp, accuracy_m]
    _tragLastT = now;
    _tragLastMoveT = now;
    if (_tragLine) _tragLine.addLatLng([mla, mlo]);  // inkrementalno (brzo i za duge tragove)
    _updTragStats();
    if (_activeTab === 'teren') terenUpdTragStats();
  }

  // 4a. AUTO-PAUZA: ako nema stvarnog pomaka >2 min, pauziraj automatski
  if (_tragLastMoveT > 0 && (now - _tragLastMoveT) > _TRAG_AUTOPAUSE_MS) {
    _tragLastMoveT = 0; // reset da ne prikazujemo toast svaki fix
    _tragPaused = true;
    // Native servis i dalje piše fiksove tokom auto-pauze — bez zabilježenog
    // prozora bi ih sljedeća dopuna (bypassPauzu) ubacila u trag kao da pauze
    // nije ni bilo. Početak je vrijeme fiksa koji je pauzu okinuo (zna biti
    // historijsko pri dopuni), ne "sada".
    _pauziOtvoriProzor(_tragPauseWin, now);
    if (!bypassPauzu) _crashSaveTrag(true);
    _tragLiveClear();
    _tragBuf = [];
    _tragLastT = 0;
    _tragRetrace = null;
    const ico = document.getElementById('ab-trag-pauza-ico');
    const txt = document.getElementById('ab-trag-pauza-txt');
    const btn = document.getElementById('ab-trag-pauza');
    if (ico) ico.innerHTML = '<svg class="ic"><use href="#ic-pocni"/></svg>';
    if (txt) txt.textContent = 'Nastavi';
    if (btn) btn.classList.add('resuming');
    showToast('⏸ Trag pauziran — dugo mirovanje (2 min)');
    if (typeof _terenUpdTragUI === 'function') _terenUpdTragUI();
  }

  // 4b. ŽIVI VRH — linija UVIJEK ide do trenutne pozicije (marker), bez zaostajanja
  if (_tragPts.length > 0) {
    const last = _tragPts[_tragPts.length - 1];
    const segLatLngs = [[last[0], last[1]], [la, lo]];
    if (!_tragLiveSeg) {
      _tragLiveSeg = L.polyline(segLatLngs,
        { color: '#f97316', weight: _lineStyle.tragW, opacity: 0.85, interactive: false, pane: 'tragMsrLines' }).addTo(map);
    } else {
      _tragLiveSeg.setLatLngs(segLatLngs);
    }
  }
}

function _tragLiveClear() {
  if (_tragLiveSeg) { map.removeLayer(_tragLiveSeg); _tragLiveSeg = null; }
}

// Povuci tačke koje je GpsService (native LocationManager, vidi GpsService.java)
// prikupio dok je WebView bio bez prozora — Chromium interno može ograničiti/
// prestati dostavljati navigator.geolocation fiksove osiroćenoj stranici bez
// obzira da li je JS kontekst preživio. Poziva se na visibilitychange('visible').
// Pokriva sva tri tipa snimanja: VLAKU, TRAG i DOZNAKA POJAS — svaki kroz
// ISTU prihvatnu logiku kao uživo fix (_vlakaProcessGpsPoint / _addTragPoint /
// _dozProcessGpsPoint), sa stvarnim historijskim vremenom svake tačke.
//
// GpsService puni bafer KONTINUIRANO cijelo vrijeme snimanja (i dok je app u
// prvom planu, ne samo u pozadini) — zato SVAKA grana ovdje mora preskočiti
// tačke koje je odgovarajući uživo watch VEĆ vidio: _onPLastFixTs za vlaku i
// trag (oba primaju fikseve kroz glavni onP watch), _dozLastLiveFixTs za
// doznaku (vlastiti watch). Bez toga bi replay duplicirao već obrađene tačke
// (za doznaku i stvarno duplirao redove u doz_track_points na serveru).
// Pročitaj native bafer JEDNOM i vrati sortirane tačke. Drain je DESTRUKTIVAN
// (Java strana obriše fajl pri čitanju), pa svaki pozivalac mora znati da je
// drugi neće više dobiti — zato je izdvojeno u helper: i _drainNativeGpsBuffer
// (povratak u app) i _crashCheck (hladan start poslije ubijenog procesa) idu
// kroz njega, a _crashCheck rezultat usmjerava u obje grane oporavka.
function _nativeBufUzmi() {
  const key = 'tvlake_native_journal';
  let batches = JSON.parse(localStorage.getItem(key) || '[]');
  if (typeof AndroidGps !== 'undefined' && typeof AndroidGps.readNativeBuffer === 'function') {
    const raw = AndroidGps.readNativeBuffer();
    if (raw) {
      const batch = JSON.parse(raw);
      if (batch.token && !batches.some(b => b.token === batch.token)) {
        batches.push(batch);
        localStorage.setItem(key, JSON.stringify(batches)); // may throw: native file stays
      }
      if (batch.token) AndroidGps.ackNativeBuffer(batch.token);
    }
  }
  const pts = [], seen = new Set();
  for (const batch of batches) {
    for (const line of batch.raw.split('\n')) {
      if (!line.trim()) continue;
      try {
        const p = JSON.parse(line);
        if (!p || !Number.isFinite(p.t) || !Number.isFinite(p.la) || !Number.isFinite(p.lo)) continue;
        const id = p.t + ':' + p.la + ':' + p.lo;
        if (!seen.has(id)) { pts.push(p); seen.add(id); }
      } catch(e) { /* damaged row retained in raw journal for export */ }
    }
  }
  return pts.sort((a,b) => a.t - b.t);
}

function _nativeBufPotvrdi() {
  // Call only after all active consumers have persisted their state.
  const key = 'tvlake_native_journal';
  const batches = JSON.parse(localStorage.getItem(key) || '[]');
  const broken = batches.filter(b => b.raw.split('\n').some(line => {
    if (!line.trim()) return false;
    try { const p = JSON.parse(line); return !p || !Number.isFinite(p.t) || !Number.isFinite(p.la) || !Number.isFinite(p.lo); }
    catch(e) { return true; }
  }));
  if (broken.length) {
    const old = JSON.parse(localStorage.getItem('tvlake_native_damaged') || '[]');
    for (const b of broken) if (!old.some(x => x.token === b.token)) old.push(b);
    localStorage.setItem('tvlake_native_damaged', JSON.stringify(old));
  }
  localStorage.removeItem(key);
}

async function _drainNativeGpsBuffer() {
  if (typeof AndroidGps === 'undefined' || typeof AndroidGps.readNativeBuffer !== 'function') return;
  if (!_tragOn && !_dozGpsOn && !recOn) return;
  if (_drainNativeGpsBuffer._busy || _crashCheck._busy) return;
  _drainNativeGpsBuffer._busy = true;
  try {
  const pts = _nativeBufUzmi();
  if (!pts.length) return;
  const sessionKey = () => JSON.stringify([sbUser?.id, recOn, actI, _tragOn, _dozGpsOn,
    _nativeSessionSince.vlaka, _nativeSessionSince.trag, _nativeSessionSince.doznaka]);
  const session = sessionKey();
  let processed = 0;
  for (const p of pts) {
    // Dopuna poslije sat vremena u pozadini ne smije zauzeti cijeli UI tok.
    // Journal ostaje dok se svi potrošači sigurno ne spreme; promjena sesije
    // tokom predaha prekida ovaj prolaz prije upisa u drugo snimanje.
    if (processed && processed % 16 === 0) {
      await new Promise(resolve => setTimeout(resolve, 0));
      if (sessionKey() !== session) throw new Error('Sesija snimanja promijenjena tokom dopune');
    }
    processed++;
    // GpsService (native) ne zna za pauzu — provjerava se ISTORIJSKI tajmstamp
    // tačke naspram zabilježenih intervala pauze za dati tip, ne trenutno
    // (ne)pauzirano stanje. Van intervala = bypassPauzu=true (uključi je iako
    // je snimanje TRENUTNO možda pauzirano); unutar intervala = tačka je
    // legitimno viđena/obrađena (napreduje _nativeReplayLast), ali se NE ubacuje.
    if (_tragOn && p.t > Math.max(_tragLastT, _onPLastFixTs, _nativeSessionSince.trag, _nativeReplayLast.trag)) {
      if (!_uPauziIntervalu(_tragPauseWin, p.t)) _addTragPoint(p.la, p.lo, p.ac, p.al, p.sp, p.t, true);
      _nativeReplayLast.trag = p.t;
    }
    if (recOn && p.t > Math.max(_onPLastFixTs, _nativeSessionSince.vlaka, _nativeReplayLast.vlaka)) {
      if (!_uPauziIntervalu(_recPauseWin, p.t)) _vlakaProcessGpsPoint(p.la, p.lo, p.ac, _filteredAlt(p.al) ?? p.al ?? 0, p.sp, p.t, true);
      _nativeReplayLast.vlaka = p.t;
    }
    if (_dozGpsOn && p.t > Math.max(_dozLastLiveFixTs, _nativeSessionSince.doznaka, _nativeReplayLast.doznaka)) {
      if (!_uPauziIntervalu(_dozPauseWin, p.t)) await _dozProcessGpsPoint(p.la, p.lo, p.al, p.ac, p.sp, p.t, true);
      _nativeReplayLast.doznaka = p.t;
    }
  }
  if (recOn && !_saveLocalVlake()) throw new Error('GPS lokalni upis nije uspio');
  if (_tragOn) localStorage.setItem(_CRASH_TRAG_KEY, _crashTragTekst());
  _nativeBufPotvrdi();
  // Zatvoreni intervali pauze su svoj posao obavili (odlučili sudbinu svih
  // tačaka do sada drenairanih) — brišu se da niz ne raste neograničeno kroz
  // dug terenski dan sa više pauza.
  _pauziOcistiZatvorene(_tragPauseWin);
  _pauziOcistiZatvorene(_recPauseWin);
  _pauziOcistiZatvorene(_dozPauseWin);
  } catch(e) { showToast('⚠ GPS dopuna čeka sigurno spremanje: ' + e.message); }
  finally {
    _drainNativeGpsBuffer._busy = false;
    // Zadržani živi fiksovi tek sad, POSLIJE starijih tačaka iz bafera.
    const q = _drainLiveQ.splice(0);
    for (const x of q) { try { x.fn(x.arg); } catch(e) { console.warn('Živi fiks poslije dopune', e); } }
  }

}


// === POINTS ===
let _ovlRndTimer = 0;
function _scheduleOvlRnd() {
  if (_ovlRndTimer) return;
  // Ovo je GPS vrući put — kuca svake 2 s cijelo snimanje. rndList() puni #vl
  // unutar #vlake-panel, a tokom snimanja je korisnik gotovo uvijek na Karti
  // (tamo je #action-bar sa kontrolama snimanja), pa se cijela lista sastavi i
  // upiše u DOM koji niko ne gleda. Izmjereno u Chromium-u: 1.86 ms po ciklusu
  // za projekat od 24 vlake, 8.05 ms za 50 vlaka × 800 tačaka. Preskače se SAMO
  // ovdje, ne u samoj rndList — ostalih 40-ak pozivalaca (selI, brisanje,
  // preimenovanje...) mora proći bez obzira na tab. Svježina pri povratku je
  // pokrivena: switchTab('vlake') sada zove rndList().
  _ovlRndTimer = setTimeout(() => {
    _ovlRndTimer = 0;
    updOvl();
    if (_activeTab === 'vlake') rndList();
  }, 2000);
}
function addPt(i, la, lo, al, gap) {
  const v = vlake[i];
  if (v.pts.length > 0) {
    const last = v.pts[v.pts.length - 1];
    // For manual drawing: reject if < 0.5m (accidental double-click)
    // For GPS: distance is already filtered in onP(), just guard against exact duplicates
    const minDist = recOn ? 0.1 : 0.5;
    if (dst(last.la, last.lo, la, lo) < minDist) return;
  }
  v.pts.push({la, lo, al, ...(gap ? { gap: true } : {})});
  v.poly.addLatLng([la, lo]);
  scheduleVlakaSave(i);
  if (v.pts.length === 2 || (v.kr > 0 && v.pts.length === 1)) updateVlakaLabel(i);
  updBan();
  if (!recOn) { updOvl(); rndList(); }
  else { _scheduleOvlRnd(); }
  // Only redraw buffers when not actively drawing (expensive per-point)
  if (bufLayers.length > 0 && activeTool !== 'addline' && activeTool !== 'addpoint' && !recOn) {
    drawBuffers();
  }
}
function addWP() {
  if (actI===null||!lastP) { showToast('⚠ GPS signal + odabrana vlaka!'); return; }
  if (recOn && recPaused) { showToast('⏸ Snimanje je pauzirano'); return; }
  const v=vlake[actI];
  addPt(actI,lastP.la,lastP.lo,lastP.al);
  const ico=L.divIcon({className:'',iconSize:[12,12],iconAnchor:[6,6],
    html:`<div style="width:12px;height:12px;border-radius:50%;background:${v.color};border:2px solid #fff;"></div>`});
  const m=L.marker([lastP.la,lastP.lo],{icon:ico}).addTo(map);
  m.bindTooltip(_escHtml(`${v.nm} WP${v.wpts.length+1}`),{opacity:0.9}); v.wpts.push(m);
}
function updBan() {
  if(typeof VlakaDirection!=='undefined')VlakaDirection.refreshRecording();
  if (actI === null) return;
  const v = vlake[actI];
  if (recOn) {
    document.getElementById('rec-nm').textContent = v.nm;
    document.getElementById('rec-stats').textContent = `${fmtL(calcL(v.pts))} · ${v.pts.length} tač.`;
    const lenEl = document.getElementById('rsb-len');
    if (lenEl) lenEl.textContent = fmtL(calcL(v.pts));
    _updSlope();  // D3-N: "nagib u realnom vremenu" se ranije osvježavao samo na pauzi/nastavku
    // D3-R: notifikacija se ranije osvježavala samo svakih 10 PRIHVAĆENIH tačaka —
    // u rijetkom terenu (filteri odbace većinu fikseva) tekst je znao kasniti minutama.
    // Dodatni vremenski prag garantuje osvježenje bar svakih ~20s.
    if (v.pts.length % 10 === 0 || Date.now() - _lastRecNotifAt > 20000) {
      _startRecNotification();
      _lastRecNotifAt = Date.now();
    }
  }
  if (activeTool === 'addline') _updDrawStats();
}
function updOvl() {
  const el = document.getElementById('ovl-lines');
  if (!el) return;
  // Ovaj element je u markupu TRAJNO display:none (blok "Sakriveni elementi koje
  // JS još koristi") i NIŠTA ga nikad ne prikaže — provjereno grep-om, postoje
  // samo dvije pojave tog id-a: sam element i ova funkcija. Bez ovog izlaza se
  // svake 2 s tokom snimanja prođe calcL kroz SVE tačke SVIH vlaka (bez
  // memoizacije, za razliku od rndList-ovog dMap) i sastavi HTML koji niko ne
  // vidi. Izmjereno u Chromium-u: 0.47 ms za projekat od 24 vlake, 3.79 ms za
  // 50 vlaka × 800 tačaka — na telefonu višestruko više, i to baš dok GPS
  // snimanje ima prioritet. Funkcija se NE briše (18 pozivalaca): ako se
  // element ikad ponovo prikaže, nastavlja raditi kao prije.
  if (el.style.display === 'none') return;
  if (vlake.length === 0) { el.innerHTML='<span style="color:#475569;font-size:11px;">— nema vlaka —</span>'; return; }
  el.innerHTML = vlake.map((v,i) => {
    const len = calcL(v.pts);
    const isAct = i === actI;
    const nameCol = isAct ? '#fbbf24' : '#94a3b8';
    const lenCol  = isAct ? '#4ade80' : '#475569';
    const bg      = isAct ? 'background:rgba(251,191,36,0.08);border-radius:4px;padding:1px 3px;' : '';
    return `<div style="display:flex;justify-content:space-between;gap:8px;margin-bottom:3px;${bg}">` +
      `<b style="color:${nameCol};min-width:52px;">${v.nm}</b>` +
      `<span style="color:${lenCol};">${fmtL(len)}</span>` +
      `</div>`;
  }).join('');
}

function showVlakaOnMap(i) {
  selI(i);
  switchTab('karta');
  zmV(i);
}

function _vlKrakRijec(n) {
  const d = n % 10, dd = n % 100;
  if (d === 1 && dd !== 11) return 'krak';
  if (d >= 2 && d <= 4 && (dd < 12 || dd > 14)) return 'kraka';
  return 'krakova';
}
function _renderVlakaRow(el, v, i, depth, dPre, grana) {
  const d   = (dPre != null) ? dPre : calcL(v.pts);
  const row = document.createElement('div');
  const isKrak = depth > 0;
  row.className = 'vrow' + (i === actI ? ' act' : '') + (isKrak ? ' vrow-krak' : '');
  // Veza red ↔ vlake[i]. Lista se crta sortirano/hijerarhijski pa pozicija u
  // DOM-u NIJE indeks u nizu — vidi napomenu u selI().
  row.dataset.vi = i;
  if (depth > 1) row.style.marginLeft = (depth * 14) + 'px';
  const lagerInfo    = v.lager ? ` · 🏷${_escHtml(v.lager)}` : '';
  const isRecThis    = recOn && i === actI;
  const isPausedPar  = recOn && i === _recParentIdx;
  const stranaBadge  = isKrak ? _krakStranaBadge(v.strana) : '';
  let badge = '';
  if (isRecThis && !recPaused) badge = `<span class="vrec-badge rec">🔴 snima se</span>`;
  else if (isRecThis && recPaused) badge = `<span class="vrec-badge paused">⏸ pauzirano</span>`;
  else if (isPausedPar)            badge = `<span class="vrec-badge parent">⏸ čeka</span>`;
  const nasaviBtn = isPausedPar
    ? `<button class="btn-nastavi" onclick="event.stopPropagation();vratiSeNaRoditelja()"><svg class="ic"><use href="#ic-pocni"/></svg> Nastavi ${_escHtml(v.nm)}</button>`
    : '';
  // Elev stats + distanca od puta za krakove
  const elvHtml = _elevHtml(v.pts);
  let roadDistHtml = '';
  if (isKrak && v.pts.length > 0) {
    if (v.naPutu) {
      roadDistHtml = `<span class="eroad">🛣 ${fmtL(d)} · izlaz na put</span>`;
    } else {
      const rd = _distToMainRoad(vlake, v) + d;
      roadDistHtml = `<span class="eroad">📍${fmtL(rd)} od puta</span>`;
    }
  }
  const nagHtml = _vlNagibHtml(v, d);
  const elevRow = (elvHtml || roadDistHtml || nagHtml)
    ? `<div class="vcard-elev">${elvHtml}${roadDistHtml}${nagHtml}</div>` : '';
  const displayColor=typeof _vlakaPrikazColor==='function'?_vlakaPrikazColor(v):v.color;
  const stripeStyle = isKrak ? `background:${displayColor};opacity:.6` : `background:${displayColor}`;
  const krakArrow   = isKrak ? `<span class="vcard-arrow">↳</span>` : '';
  // Dugme odabrane vlake — jedan obrazac umjesto pet kopija inline stilova.
  const act = (onclick, ico, boja, lbl) => `<button class="vact" style="--vc:${boja};" onclick="event.stopPropagation();${onclick}">
          <span class="vact-ico"><svg class="ic"><use href="#${ico}"/></svg></span><span class="vact-lbl">${lbl}</span></button>`;
  const snimIco = isRecThis && !recPaused ? 'ic-snimaj' : isRecThis && recPaused ? 'ic-pauza' : 'ic-pocni';
  const snimLbl = isRecThis && !recPaused ? 'Snima' : isRecThis && recPaused ? 'Pauza' : 'Snimi';
  row.innerHTML = `
    <div class="vcard-stripe" style="${stripeStyle}"></div>
    <div class="vcard-info">
      <div class="vcard-top">
        ${krakArrow}${stranaBadge}<span class="vcard-name">${_escHtml(v.nm)}</span>
        ${badge}
        <span class="vcard-km">${fmtL(d)}</span>
        ${sbUser ? `<span class="vsync-icon" data-vi="${i}" title="${v.sbId ? 'Sačuvano na server' : 'Čeka sync...'}" style="font-size:11px;opacity:0.7;margin-left:2px;color:${v.sbId ? '#4ade80' : '#94a3b8'};">☁</span>` : ''}
        <span class="vcard-caret"></span>
      </div>
      <div class="vcard-sub">${v.pts.length} tačaka${lagerInfo}${grana ? `<button class="vkr-tog${grana.skupljen ? ' skupljen' : ''}" onclick="event.stopPropagation();_vlKrakToggle(${i})" title="${grana.skupljen ? 'Prikaži krakove' : 'Sakrij krakove'}"><span class="vkr-ar"></span>${grana.nKrak} ${_vlKrakRijec(grana.nKrak)} · s kracima ${fmtL(grana.ukupnoM)}</button>` : ''}</div>
      ${typeof _tabRowStatus === 'function' ? _tabRowStatus(v) : ''}
      ${elevRow}
      ${isKrak && !isReadOnly() ? `<label class="vcard-naputu" onclick="event.stopPropagation();">
        <input type="checkbox" onchange="event.stopPropagation();listToggleNaPutu(${i},this.checked)" ${v.naPutu?'checked':''} style="width:16px;height:16px;flex-shrink:0;">
        🛣 Završava na putu <span style="color:#64748b;">(samo dužina kraka)</span>
      </label>` : ''}
      ${nasaviBtn}
      <div class="vcard-actions">
        ${isReadOnly() ? '' : act(`selI(${i});switchTab('karta');${recOn?'':'setTimeout(togRec,30);'}`, snimIco, '#f87171', snimLbl)}
        ${act(`showVlakaOnMap(${i})`, 'ic-karta', '#60a5fa', 'Karta')}
        ${act(`showElevProfile(${i})`, 'ic-visina', '#34d399', 'Profil')}
        ${isReadOnly() ? '' : act(`selI(${i});togEdit()`, 'ic-alat', '#fbbf24', 'Uredi')}
        ${isReadOnly() ? '' : act(`dlV(${i})`, 'ic-zatvori', '#94a3b8', 'Briši')}
      </div>
    </div>`;
  // Prvi tap odabire vlaku (otvara njena dugmad), drugi tap na VEĆ odabranu je
  // vodi na kartu. Ranije je svaki tap odmah skakao na kartu, pa odabir nije
  // imao vidljivu ulogu — a dugmad su zato morala stajati na SVAKOM redu.
  row.onclick = () => (recOn || actI !== i) ? selI(i) : showVlakaOnMap(i);
  el.appendChild(row);
}

// Bedž nagiba u redu liste. Boja je iz ISTE skale (_gradeColor) kojom se vlaka
// boji na karti, pa se "žuto u listi" i "žuto na karti" poklapaju bez učenja
// druge legende.
//
// Kad vlaka prelazi limit, uz max se ispisuje i KOLIKO METARA je preko — max
// sam po sebi ne razlikuje jednu kratku strminu (koja se rješava na licu
// mjesta) od 200 m neprohodne dionice (koja traži drugu trasu). Metri su
// otporniji i na GPS šum: jedan loš fiks daje par metara, ne dionicu.
function _vlNagibHtml(v, d) {
  const st = _vlNagib(v, d);
  if (!st) return '';
  const preko = st.prekoM > 0;
  return `<span class="vnag" style="color:${_gradeColor(st.max)}" title="Najveći nagib ${st.max}%, prosjek ${st.avg}%">⛰${st.max}%</span>` +
    (preko ? `<span class="vnag-bad">${fmtL(st.prekoM)} preko ${st.limit}%</span>` : '');
}

// Vrati badge (L/D) za krak na osnovu strana polja
function _krakStranaBadge(strana) {
  if (strana === 'L') return `<span class="vkrak-badge-l">L</span>`;
  if (strana === 'D') return `<span class="vkrak-badge-d">D</span>`;
  return '';
}

// Traka iznad liste: izbor limita nagiba + filter "samo preko limita".
// Namjerno se NE prikazuje kad nijedna vlaka nema visine (nacrtane bez GPS-a)
// — prazna kontrola koja ništa ne mijenja je samo šum na malom ekranu.
let _vlSamoStrme = false;
// Pretraga / sort / sklopljeni kraci (v1.7.2). var, ne let: rndList se može
// pozvati iz ranog startup koda prije nego izvršavanje stigne do ovog reda (TDZ).
var _VL_SORT_KEY = 'tvlake_vl_sort';
var _vlSort = (function () { try { const v = localStorage.getItem('tvlake_vl_sort'); return ['naziv', 'duzina', 'nagib'].includes(v) ? v : 'naziv'; } catch (e) { return 'naziv'; } })();
var _vlTrazi = '';
// Sklopljeni kraci se NE pamte trajno — to je gustoća trenutnog pregleda, ne
// postavka; poslije restarta se sve vidi (ništa sakriveno bez objašnjenja).
var _vlSkupljeni = new Set();
function _vlSkupKljuc(v) { return (v.projektId || '') + '|' + v.nm; }
function _vlTraziNorm() { return String(_vlTrazi || '').trim().toLowerCase(); }
function _vlOdgovara(v, q) {
  return String(v.nm || '').toLowerCase().includes(q) || String(v.lager || '').toLowerCase().includes(q);
}
function _vlTraziSet(t) { _vlTrazi = String(t || ''); if (typeof _tabChanged === 'function') _tabChanged(); rndList(); }
function _vlSortSet(s) {
  _vlSort = ['naziv', 'duzina', 'nagib'].includes(s) ? s : 'naziv';
  try { localStorage.setItem(_VL_SORT_KEY, _vlSort); } catch (e) {}
  if (typeof _tabChanged === 'function') _tabChanged();
  rndList();
}
function _vlKrakToggle(i) {
  const v = vlake[i]; if (!v) return;
  const k = _vlSkupKljuc(v);
  if (_vlSkupljeni.has(k)) _vlSkupljeni.delete(k); else _vlSkupljeni.add(k);
  rndList();
}
function _vlNagibFilterToggle(on) { _vlSamoStrme = !!on; if (typeof _tabChanged === 'function') _tabChanged(); rndList(); }
function _vlNagibTrakaRender(nVlaka, nPreko, prekoMUk, limit) {
  const el = document.getElementById('vl-nagib-traka');
  if (!el) return;
  if (!nVlaka) { el.style.display = 'none'; _vlSamoStrme = false; return; }
  const opts = _VL_NAGIB_LIMITI
    .map(n => `<option value="${n}"${n === limit ? ' selected' : ''}>preko ${n}%</option>`).join('');
  // Kad ništa ne prelazi limit, to je NAJVAŽNIJA informacija na ekranu i piše
  // se otvoreno ("sve u granici") — prazan prostor bi se čitao kao "nije
  // provjereno", što nije isto.
  const sazetak = nPreko > 0
    ? `<span class="vnt-bad">⚠ ${nPreko} ${_vlBrojVlaka(nPreko)} · ${fmtL(prekoMUk)}</span>`
    : `<span class="vnt-ok">✓ sve u granici</span>`;
  const filter = nPreko > 0
    ? `<label class="vnt-f"><input type="checkbox" onchange="_vlNagibFilterToggle(this.checked)"${_vlSamoStrme ? ' checked' : ''}> samo te</label>`
    : '';
  el.style.display = 'flex';
  el.innerHTML = `<span class="vnt-lbl">⛰ Nagib</span>
    <select class="vnt-sel" onchange="_vlNagibSetLimit(this.value)" title="Limit zavisi od mehanizacije">${opts}</select>
    ${sazetak}${filter}`;
  if (nPreko === 0) _vlSamoStrme = false;
}
// 1 vlaka / 2-4 vlake / 5+ vlaka — bosanska sklonidba.
function _vlBrojVlaka(n) {
  const d = n % 10, s = n % 100;
  if (d === 1 && s !== 11) return 'vlaka';
  if (d >= 2 && d <= 4 && (s < 12 || s > 14)) return 'vlake';
  return 'vlaka';
}

// === LIST ===
function rndList() {
  const el=document.getElementById('vl'), nv=document.getElementById('nv');
  // switchTab('vlake') je zove pri ulasku u tab, a switchTab se prvi put zove
  // iz _startupRestore dok se markup možda još parsira — čitanje .innerHTML
  // nepostojećeg elementa bi tu oborilo cijelo pokretanje (dokumentovana zamka
  // v3.102.2: "Pokretanje dira DOM koji JOŠ NE POSTOJI").
  if (!el) return;
  el.innerHTML='';
  const pendingOnly = typeof _tabListPrepare === 'function' && _tabListPrepare();

  // Filtriraj po aktivnom projektu
  const hasProj = !!_aktivniProjektId;
  const noProjects = !_projekti || _projekti.length === 0;
  // Bez aktivnog projekta ne prikazuj NIŠTA u listi (ni orphan vlake) — samo
  // poruka/dugme za čišćenje ispod (blok "noProjects && vlake.length > 0") ostaje.
  const allProjVlake = hasProj ? vlake.filter(v => v.projektId === _aktivniProjektId) : [];
  const vlIndex = new Map(vlake.map((v,i) => [v,i]));
  const poNazivu = (a, b) => {
    const ka = _stdSortKey(a.nm), kb = _stdSortKey(b.nm);
    return ka !== kb ? ka - kb : String(a.nm).localeCompare(String(b.nm));
  };
  const rootVlake    = allProjVlake.filter(v => v.kr === 0).sort(poNazivu);
  const krakCount    = allProjVlake.filter(v => v.kr !== 0).length;
  document.getElementById('vc').textContent = rootVlake.length + (krakCount ? ` · ${krakCount} ${_vlKrakRijec(krakCount)}` : '');

  // Dužina i nagib se računaju u JEDNOM prolazu i prosljeđuju redovima — calcL
  // je O(n) po vlaci, a treba i zaglavlju (ukupno/gustoća) i svakom redu.
  // Ranije je red računao svoju dužinu sam, pa bi sažetak nagiba u zaglavlju
  // značio DRUGI prolaz kroz sve tačke pri svakom crtanju liste.
  const dMap = new Map();
  let totalDist = 0, nPreko = 0, prekoMUk = 0;
  allProjVlake.forEach(v => {
    const d = calcL(v.pts);
    dMap.set(v, d);
    totalDist += d;
    const st = _vlNagib(v, d);
    if (st && st.prekoM > 0) { nPreko++; prekoMUk += st.prekoM; }
  });
  const nagLimit = _vlNagibLimit();

  // Project header chip
  const hdr = document.getElementById('vlake-proj-hdr');
  if (hdr) {
    const akt = (_projekti||[]).find(p => p.id === _aktivniProjektId);
    if (akt) {
      const lbl = [akt.odjel, akt.gj].filter(Boolean).join(' · ') || 'Projekat';
      const _pv = _projPovrsinaHa();
      const densHtml = (_pv.ha > 0 && totalDist > 0)
        ? `<span class="vph-dist" style="color:#60a5fa;" title="Gustoća mreže vlaka (${_pv.ha} ha${_pv.src==='KML'?' iz KML':''})">${Math.round(totalDist/_pv.ha)} m/ha</span>` : '';
      // v1.7.1: sažetak projekta kao tri broja (ukupno / gustoća / broj), ne
      // jedan red sitnog monospace teksta — to su pokazatelji po kojima se
      // ocjenjuje mreža vlaka, pa moraju biti čitljivi na prvi pogled.
      const densVal = (_pv.ha > 0 && totalDist > 0) ? Math.round(totalDist / _pv.ha) + ' m/ha' : '—';
      hdr.style.display = 'block';
      hdr.innerHTML = `
        <div class="vph-stats" aria-label="Mreža vlaka projekta ${_escHtml(lbl)}">
          <div class="vph-stat"><b style="color:#4ade80;">${fmtL(totalDist)}</b><span>ukupno</span></div>
          <div class="vph-stat" title="${densHtml ? 'Gustoća mreže vlaka (' + _pv.ha + ' ha' + (_pv.src==='KML' ? ' iz KML' : '') + ')' : 'Površina projekta nije poznata'}"><b style="color:#60a5fa;">${densVal}</b><span>gustoća</span></div>
          <div class="vph-stat"><b>${rootVlake.length}${krakCount ? ' + ' + krakCount : ''}</b><span>${krakCount ? 'vlake + kraci' : 'vlake'}</span></div>
        </div>`;
    } else {
      hdr.style.display = 'none';
    }
  }

  _vlNagibTrakaRender(allProjVlake.length, nPreko, prekoMUk, nagLimit);

  if (!hasProj && !noProjects) {
    nv.style.display = 'block';
    nv.innerHTML = 'Odaberite projekat za prikaz vlaka.';
  } else if (noProjects && vlake.length > 0) {
    nv.style.display = 'block';
    nv.innerHTML = `<div style="color:#f87171;margin-bottom:8px;">⚠ ${vlake.length} vlaka bez projekta</div><button onclick="_deleteAllOrphanVlake()" style="background:#7f1d1d;border:1px solid #ef4444;color:#fca5a5;border-radius:8px;padding:8px 14px;font-size:13px;font-weight:600;cursor:pointer;"><svg class="ic"><use href="#ic-zatvori"/></svg> Obriši sve</button>`;
  } else if (rootVlake.length === 0) {
    nv.style.display = 'block';
    nv.innerHTML = `Još nema vlaka za ovaj projekat.<br>Kliknite <b style="color:#ea580c;"><img src="forwarder.svg" alt="" style="width:14px;height:14px;object-fit:contain;vertical-align:middle;"> Snimi vlaku</b>.`;
  } else {
    nv.style.display = 'none';
  }

  // Indeksirana mapa djece: O(n) umjesto O(n²). SAMO vlake aktivnog projekta —
  // ranije se gradila nad CIJELIM vlake[], pa bi krak "T1.1" iz drugog
  // projekta (isto ime, drugi odjel) bio nacrtan ispod ovdašnje T1.
  const childMap = new Map();
  vlake.forEach((k, ki) => {
    if (k.projektId !== _aktivniProjektId) return;
    const pnm = k.nm.split('.').slice(0, -1).join('.');
    if (pnm) {
      if (!childMap.has(pnm)) childMap.set(pnm, []);
      childMap.get(pnm).push({v:k, i:ki});
    }
  });
  const frag = document.createDocumentFragment();
  const dataRows = [];
  const renderRow = (...args) => {
    if (typeof _tabListRender === 'function') dataRows.push(args);
    else _renderVlakaRow(frag, ...args);
  };
  const rendered = new Set();
  // Ukupna dužina podstabla (vlaka + svi njeni kraci) — za sort "Dužina" i za
  // oznaku sklopljenih krakova. Memo po imenu, jedan prolaz po crtanju.
  const subM = new Map();
  const podstablo = v => {
    if (subM.has(v.nm)) return subM.get(v.nm);
    let m = dMap.get(v) || 0, n = 0;
    (childMap.get(v.nm) || []).forEach(c => { const r = podstablo(c.v); m += r.m; n += 1 + r.n; });
    const r = { m, n }; subM.set(v.nm, r); return r;
  };
  function renderWithChildren(v, i, depth) {
    if (rendered.has(i)) return;
    rendered.add(i);
    const ch = childMap.get(v.nm);
    const skupljen = !!ch && _vlSkupljeni.has(_vlSkupKljuc(v));
    const ps = ch ? podstablo(v) : null;
    renderRow(v, i, depth, dMap.get(v), ch ? { nKrak: ps.n, ukupnoM: ps.m, skupljen } : null);
    if (ch && !skupljen) ch.forEach(c => renderWithChildren(c.v, c.i, depth + 1));
  }
  const q = _vlTraziNorm();
  const alati = document.getElementById('vl-alati');
  if (alati) {
    alati.style.display = allProjVlake.length >= 2 ? '' : 'none';
    alati.querySelectorAll('#vl-sort button').forEach(b => b.classList.toggle('on', b.dataset.s === _vlSort));
  }
  if (q || pendingOnly) {
    // Pretraga je RAVNA lista (kao filter nagiba) — krak koji odgovara mora se
    // vidjeti i kad mu matična vlaka ne odgovara. Indeks ostaje STVARNI indeks.
    let arr = allProjVlake.filter(v => _vlOdgovara(v, q));
    if (pendingOnly) arr = arr.filter(v => _tabPending(v));
    if (_vlSamoStrme && nPreko > 0) arr = arr.filter(v => { const st = _vlNagib(v, dMap.get(v)); return st && st.prekoM > 0; });
    arr.sort(poNazivu).forEach(v => renderRow(v, vlIndex.get(v), v.kr === 0 ? 0 : 1, dMap.get(v)));
    if (!arr.length && allProjVlake.length) {
      nv.style.display = 'block';
      nv.textContent = `Nijedna vlaka ne odgovara "${_vlTrazi.trim()}".`;
    }
  } else if (_vlSamoStrme && nPreko > 0) {
    // Filtrirani prikaz je RAVAN (bez hijerarhije) — krak koji prelazi limit
    // mora biti vidljiv i kad njegova matična vlaka ne prelazi. Dubina se zato
    // izvodi iz v.kr, ne iz mjesta u stablu, da krak zadrži svoju oznaku
    // (L/D, "završava na putu") i kad mu roditelj nije nacrtan.
    //
    // `i` je i ovdje STVARNI indeks u vlake[] — filtriranje ne smije pomjeriti
    // vezu red ↔ podatak (vidi selI i tests/js/vlake-list.test.js).
    allProjVlake
      .filter(v => { const st = _vlNagib(v, dMap.get(v)); return st && st.prekoM > 0; })
      .sort((a, b) => (_vlNagib(b, dMap.get(b)).max - _vlNagib(a, dMap.get(a)).max))
      .forEach(v => renderRow(v, vlIndex.get(v), v.kr === 0 ? 0 : 1, dMap.get(v)));
  } else {
    let roots = rootVlake;
    if (_vlSort === 'duzina') roots = rootVlake.slice().sort((a, b) => podstablo(b).m - podstablo(a).m || poNazivu(a, b));
    else if (_vlSort === 'nagib') {
      const mx = v => { const st = _vlNagib(v, dMap.get(v)); return st ? st.max : -1; };
      roots = rootVlake.slice().sort((a, b) => mx(b) - mx(a) || poNazivu(a, b));
    }
    roots.forEach(v => { const i = vlIndex.get(v); renderWithChildren(v, i, 0); });
  }
  if (typeof _tabListRender === 'function') _tabListRender(frag, dataRows);
  el.appendChild(frag);
  updOvl();
  // Defer project stats update to avoid blocking during rapid updates
  clearTimeout(rndList._projTimer);
  rndList._projTimer = setTimeout(()=>{ if(typeof updProjStats==='function') updProjStats(); }, 150);
}
function zmV(i) {
  const v=vlake[i];
  if (v.pts.length>0) map.fitBounds(L.latLngBounds(v.pts.map(p=>[p.la,p.lo])),{padding:[30,30]});
}
let _delPendingIdx = null;
let _delPendingRef = null;

function dlV(i) {
  if (isReadOnly()) { showToast('Pregledni nalog — samo čitanje'); return; }
  const v = vlake[i];
  if (!v) return;
  if (recOn) { showToast('Završi snimanje prije brisanja vlake'); return; }
  _delPendingIdx = i;
  _delPendingRef = {v, nm:v.nm, projektId:v.projektId, owner:sbUser?.id, activeProject:_aktivniProjektId};
  const pts = v.pts ? v.pts.length : 0;
  const dist = pts > 1 ? fmtL(Math.round(calcL(v.pts))) : null;

  document.getElementById('del-modal-title').textContent = `Obriši ${v.nm}?`;
  document.getElementById('del-modal-meta').innerHTML =
    `<b style="color:#e2e8f0;">${_escHtml(v.nm)}</b>` +
    (dist ? ` &nbsp;·&nbsp; ${dist}` : '') +
    (pts > 0 ? ` &nbsp;·&nbsp; ${pts} tačaka` : '');
  document.getElementById('del-modal-warn').textContent =
    pts > 0
      ? 'Brisanje je trajno i ne može se poništiti.'
      : 'Ova vlaka nema snimljenih tačaka.';

  // Uvijek zahtijevaj tipkanje — sprječava slučajno brisanje
  const inputRow = document.getElementById('del-input-row');
  const inp = document.getElementById('del-modal-input');
  {
    document.getElementById('del-input-label').textContent = `Upiši "${v.nm}" za potvrdu:`;
    inp.value = '';
    inp.placeholder = v.nm;
    inputRow.style.display = '';
    document.getElementById('del-confirm-btn').disabled = true;
  }

  document.getElementById('del-modal-bg').classList.add('open');
  setTimeout(() => inp.focus(), 120);
}

function _delInputCheck() {
  const ref = _delPendingRef;
  const valid = ref && vlake.includes(ref.v) && ref.v.nm === ref.nm &&
    ref.v.projektId === ref.projektId && sbUser?.id === ref.owner &&
    _aktivniProjektId === ref.activeProject && !isReadOnly() && !recOn;
  const inp = document.getElementById('del-modal-input').value.trim();
  document.getElementById('del-confirm-btn').disabled = !valid || inp !== ref.nm;
}

function _delCancel() {
  document.getElementById('del-modal-bg').classList.remove('open');
  _delPendingIdx = null;
  _delPendingRef = null;
}

function _delConfirm() {
  const ref = _delPendingRef;
  const i = ref ? vlake.indexOf(ref.v) : -1;
  if (i < 0 || ref.v.nm !== ref.nm || ref.v.projektId !== ref.projektId ||
      sbUser?.id !== ref.owner || _aktivniProjektId !== ref.activeProject || isReadOnly() || recOn) {
    _delCancel(); showToast('Stavka ili projekat su promijenjeni — ponovo otvori brisanje'); return;
  }
  // Validate inside the action too: Enter can call this while its button is disabled.
  if (document.getElementById('del-modal-input').value.trim() !== ref.nm) {
    _delInputCheck(); document.getElementById('del-modal-input').focus(); return;
  }
  _delCancel();

  _removeVlakaMapLayers(vlake[i]);
  const _delV = vlake[i];
  sbDeleteVlaka(_delV);
  clearTimeout(_vlakaSaveTimers[i]);
  vlake.splice(i,1);
  _saveLocalVlake();
  // Reindeksiraj tajmere nakon splice
  const nt = {};
  Object.keys(_vlakaSaveTimers).forEach(k => { const n=+k; if(n<i) nt[n]=_vlakaSaveTimers[n]; else if(n>i) nt[n-1]=_vlakaSaveTimers[n]; });
  Object.keys(_vlakaSaveTimers).forEach(k=>delete _vlakaSaveTimers[k]);
  Object.assign(_vlakaSaveTimers, nt);
  if (actI===i) {
    actI = vlake.length > 0 ? Math.min(i, vlake.length-1) : null;
    stopActiveTool();
  } else if (actI !== null && actI > i) {
    actI--;
  }
  stopRec();
  _saveLocalVlake();
  rndList(); updOvl();
}

// === VLAKA POPUP ===
let _vpIdx = null, _vpJustOpened = false, _vpSharedKey = null, _vpBufferId = null;

// Pixel-space distance from point p to segment p1-p2
function _distToSegPx(p, p1, p2) {
  const dx = p2.x - p1.x, dy = p2.y - p1.y;
  const lenSq = dx*dx + dy*dy;
  if (lenSq === 0) return Math.hypot(p.x - p1.x, p.y - p1.y);
  let t = ((p.x - p1.x)*dx + (p.y - p1.y)*dy) / lenSq;
  t = Math.max(0, Math.min(1, t));
  return Math.hypot(p.x - (p1.x + t*dx), p.y - (p1.y + t*dy));
}

function _activateVlakaEdit(idx) {
  _vpJustOpened = true;
  setTimeout(() => { _vpJustOpened = false; }, 80);
  selI(idx);
  switchTab('vlake');
  // Samo selektuj i prikaži u listi — toolbar se otvara samo kroz Nacrtaj vlaku
}

let _lastVlakaClickTs = 0;
function attachPolyClick(poly, colleagueKey) {
  // Nevidljivi široki sloj (24px) za lakši klik/tap po cijeloj dužini vlake
  const hit = L.polyline(poly.getLatLngs(), {
    weight: 24, opacity: 0.001, color: '#000',
    pane: poly.options.pane, renderer: poly.options.renderer, interactive: true
  });
  // Sinkroniziraj hit s vizualnim polyom kad se latlngs mijenjaju
  const _syncHit = () => { try { hit.setLatLngs(poly.getLatLngs()); } catch(e) {} };
  const _origSet = poly.setLatLngs.bind(poly);
  poly.setLatLngs = function(ll) { const r = _origSet(ll); _syncHit(); return r; };
  const _origAdd = poly.addLatLng.bind(poly);
  poly.addLatLng = function(ll) { const r = _origAdd(ll); _syncHit(); return r; };
  poly.on('add',    () => { try { hit.addTo(map); } catch(e) {} });
  poly.on('remove', () => { try { map.removeLayer(hit); } catch(e) {} });
  if (poly._map) { try { hit.addTo(poly._map); } catch(e) {} }

  function _onClick(e) {
    const now = Date.now();
    if (now - _lastVlakaClickTs < 150) return;  // spriječi dvostruki okidač
    _lastVlakaClickTs = now;
    if (recOn) return;
    if (['edit','delnode','merge','addline','addpoint'].includes(activeTool)) return;
    if (_msrOn || _guideOn || _tackaPlaceMode || textToolOn || _dozDrawType !== null || (typeof _vsdOn !== 'undefined' && _vsdOn)) return;
    L.DomEvent.stopPropagation(e);
    if (e.originalEvent) e.originalEvent.stopPropagation();
    if (colleagueKey) { showKolegeVlakaInfo(colleagueKey, e.latlng); return; }
    const idx = vlake.findIndex(vv => vv.poly === poly);
    if (idx >= 0) { selI(idx); showVlakaPopup(idx, e.latlng); }
  }
  poly.on('click', _onClick);
  hit.on('click',  _onClick);
}

function showVlakaPopup(i, latlng) {
  closeVlakaPopup();
  const v = vlake[i];
  if (!v) return;
  _vpIdx = i;
  _vpJustOpened = true;
  setTimeout(() => { _vpJustOpened = false; }, 80);
  const len = calcL(v.pts);
  const ime = v.projektantIme || getIme();
  const dat = v.updatedAt ? fmtDate(v.updatedAt.slice(0,10)) : fmtDate(todayStr());
  const tipLabel = v.kr > 0 ? ' (krak)' : '';
  const brLabel  = v.br != null ? `<span style="font-size:11px;color:#64748b;margin-left:5px;">br.${v.br}</span>` : '';
  document.getElementById('vp-nm').innerHTML =
    `<span style="color:${v.color};">${_escHtml(v.nm)}</span>${brLabel}<span style="color:#64748b;font-size:11px;">${tipLabel}</span>`;
  const proj = v.projektId ? (_projekti || []).find(p => p.id === v.projektId) : null;
  const projRow = proj
    ? `<div class="vp-row">📁 Projekat: <b>${_escHtml(proj.odjel || '—')}</b>${proj.gj ? ' · ' + _escHtml(proj.gj) : ''}</div>`
    : '';
  document.getElementById('vp-info').innerHTML = `
    ${projRow}
    <div class="vp-row">🔢 Broj vlake: <b>${v.br ?? '—'}</b>${v.kr > 0 ? `&nbsp;(krak ${v.kr})` : ''}</div>
    <div class="vp-row">📏 Dužina: <b>${fmtL(len)}</b></div>
    <div class="vp-row">📍 Tačaka GPS: <b>${v.pts.length}</b></div>
    <div class="vp-row">👤 Projektant: <b>${_escHtml(ime)}</b></div>
    <div class="vp-row">📅 Ažurirano: <b>${dat}</b></div>
    ${v.lager ? `<div class="vp-row">🪵 Lager: <b style="color:#f59e0b;">${_escHtml(v.lager)}</b></div>` : ''}
    ${v.kr > 0 && !isReadOnly() ? `<label class="vp-row" style="display:flex;align-items:center;gap:6px;cursor:pointer;margin-top:4px;padding-top:6px;border-top:1px solid rgba(255,255,255,0.08);">
      <input type="checkbox" onchange="vpToggleNaPutu(this.checked)" ${v.naPutu?'checked':''} style="width:15px;height:15px;flex-shrink:0;">
      <span style="font-size:11px;color:#7dd3fc;">🛣 Završava na putu <span style="color:#64748b;">(mjeri samo dužinu kraka)</span></span>
    </label>` : ''}
  `;
  if(typeof VlakaDirection!=='undefined')document.getElementById('vp-info').insertAdjacentHTML('beforeend',VlakaDirection.popup(v));
  _vpBufferLabel();
  _positionPopup(latlng);
}

function _positionPopup(latlng) {
  const popup = document.getElementById('vlaka-popup');
  popup.style.display = 'block';
  _vpBufferLabel();
  const cp  = map.latLngToContainerPoint(latlng);
  const mr  = document.getElementById('map').getBoundingClientRect();
  const bounds = popup.getBoundingClientRect();
  const pw = bounds.width || 270, ph = bounds.height || 220;
  let left  = mr.left + cp.x + 12;
  let top   = mr.top  + cp.y - 20;
  if (left + pw > window.innerWidth  - 8) left = mr.left + cp.x - pw - 12;
  if (top  + ph > window.innerHeight - 8) top  = window.innerHeight - ph - 8;
  if (top < 60) top = 60;
  if (left < 6) left = 6;
  popup.style.left = left + 'px';
  popup.style.top  = top  + 'px';
}

function showKolegeVlakaInfo(key, latlng) {
  const kv = kolegeVlakeMap[key];
  if (!kv) return;
  closeVlakaPopup();
  _vpSharedKey = key;
  _vpJustOpened = true;
  setTimeout(() => { _vpJustOpened = false; }, 80);
  const nm = kv.nm || key.split('::').slice(1).join('::');
  const project = (_projekti || []).find(p=>p.id===(kv.projektId || _aktivniProjektId));
  document.getElementById('vp-nm').textContent = nm + ' · vlaka kolege';
  document.getElementById('vp-info').innerHTML = `
    <div class="vp-row">📁 Projekat: <b>${_escHtml([project?.gj,project?.odjel].filter(Boolean).join(' · ') || '—')}</b></div>
    <div class="vp-row">📏 Dužina: <b>${fmtL(calcL(kv.pts))}</b></div>
    <div class="vp-row">📍 Tačaka: <b>${kv.pts.length}</b></div>
    <div class="vp-row">👤 Projektant: <b>${_escHtml(kv.ime || 'Kolega')}</b></div>
    <div class="vp-row">Preuzeto sa servera · pregled</div>`;
  if(typeof VlakaDirection!=='undefined')document.getElementById('vp-info').insertAdjacentHTML('beforeend',VlakaDirection.popup(kv));
  document.getElementById('vlaka-popup-btns').style.display = 'none';
  _vpBufferLabel();
  _positionPopup(latlng);
}

function vpBuffer() {
  const v = _vpSharedKey ? kolegeVlakeMap[_vpSharedKey] : vlake[_vpIdx];
  if (!v || v.pts.length < 2) return;
  const id = _vpSharedKey || 'my:'+_vpIdx;
  if (_vpBufferId === id && bufLayers.length) { clearBuffers(); return; }
  drawBuffers([v]);
  _vpBufferId = id;
  _vpBufferLabel();
}
function _vpBufferLabel() {
  const button=document.getElementById('vp-buffer');
  if(button)button.textContent=_vpBufferId===(_vpSharedKey||'my:'+_vpIdx)&&bufLayers.length?'Sakrij bafer':'Bafer ±'+bufRadius+' m';
}

function closeVlakaPopup() {
  document.getElementById('vlaka-popup').style.display = 'none';
  const btns = document.getElementById('vlaka-popup-btns');
  if (btns) btns.style.display = '';  // restore for next open
  _vpIdx = null; _vpSharedKey = null;
}

function vpEdit() {
  if (_vpIdx === null) return;
  const i = _vpIdx;
  closeVlakaPopup();
  selI(i);
  switchTab('vlake');
  togEdit();
}

function vpZoom() {
  if (_vpSharedKey) {const v=kolegeVlakeMap[_vpSharedKey];if(v?.poly)map.fitBounds(v.poly.getBounds(),{padding:[35,35]});return;}
  if (_vpIdx === null) return;
  zmV(_vpIdx);
}

function vpDelete() {
  if (_vpIdx === null) return;
  const i = _vpIdx;
  closeVlakaPopup();
  dlV(i);
}

function vpIzravnaj() {
  if (_vpIdx === null) return;
  izravnajVlaku(_vpIdx);
}

// ── Krak "završava na putu" ──────────────────────────────────────────────────
// Kvačica (popup na karti + Vlake lista) koja obilježava krak koji izlazi na
// kamionski put na svom kraju. Takav krak: (1) STD mjeri SAMO njegovu dužinu
// (ne + povratak glavnom vlakom), (2) dobija vlastiti lager na kraju (izlazu).
function vpToggleNaPutu(on) {
  if (_vpIdx === null) return;
  _applyNaPutu(_vpIdx, on);
}
function listToggleNaPutu(i, on) {
  _applyNaPutu(i, on);
}
function _applyNaPutu(i, on) {
  const v = vlake[i];
  if (!v || v.kr === 0) return;   // smisleno samo za krak
  v.naPutu = !!on;
  v.updatedAt = new Date().toISOString();
  updateVlakaLabel(i);            // lager marker se seli na kraj / (ne)prikazuje
  rndList();                      // "izlaz na put" / "od puta" u kartici
  sbFlushVlaka(i);                // perzistencija (localStorage + server)
  // Osvježi STD/rekap karticu (updProjStats je sam-guarded — vrati prazno bez projekta)
  if (typeof updProjStats === 'function') { try { updProjStats(); } catch(e) {} }
  if (on && !v.lager) {
    // Odmah ponudi lager na kraju kraka (+ prijedlog dijeljenja ≤20 m)
    _showLagerDlg(i);
  }
}

let _lagerPlaceIdx = null;
let _lagerPlaceBanner = null;

function vpLager() {
  if (_vpIdx === null) return;
  const i = _vpIdx;
  if(vlake[i]?.lager&&typeof VlakaLager!=='undefined'){VlakaLager.startPlace('own:'+i);return;}
  closeVlakaPopup();
  _lagerPlaceIdx = i;
  const v = vlake[i];
  if (_lagerPlaceBanner) _lagerPlaceBanner.remove();
  const ban = document.createElement('div');
  ban.id = 'lager-place-banner';
  ban.style.cssText = 'position:fixed;top:90px;left:50%;transform:translateX(-50%);z-index:9500;background:#92400eee;color:#fbbf24;padding:10px 18px;border-radius:10px;font-size:13px;font-weight:600;text-align:center;box-shadow:0 4px 16px rgba(0,0,0,0.6);pointer-events:auto;';
  ban.innerHTML = `🏷 Klikni na mapu za poziciju lagera vlake <b>${v.nm}</b><br><button onclick="_lagerPlaceCancel()" style="margin-top:6px;background:#7f1d1d;color:#fca5a5;border:none;border-radius:6px;padding:5px 14px;font-size:12px;cursor:pointer;"><svg class="ic"><use href="#ic-zatvori"/></svg> Otkaži</button>`;
  document.body.appendChild(ban);
  _lagerPlaceBanner = ban;
  map.once('click', _onLagerPlaceClick);
}

function _onLagerPlaceClick(e) {
  if (_lagerPlaceIdx === null) return;
  const v = vlake[_lagerPlaceIdx];
  if (!v) { _lagerPlaceCancel(); return; }
  v.lagerPt = { la: e.latlng.lat, lo: e.latlng.lng };
  if (_lagerPlaceBanner) { _lagerPlaceBanner.remove(); _lagerPlaceBanner = null; }
  _lagerTargetIdx = _lagerPlaceIdx;
  _lagerPlaceIdx = null;
  _showLagerDlgForPlace(v);
}

async function _showLagerDlgForPlace(v) {
  const vIdx = vlake.indexOf(v);
  if (vIdx < 0) return;
  _lagerTargetIdx = vIdx;
  const preferred = 'L' + v.br;
  const { lbl: fallback } = await nextLagerNum();
  const used = new Set(vlake.map(x => x.lager).filter(Boolean));
  const lbl = v.lager || (!used.has(preferred) ? preferred : fallback);
  document.getElementById('ld-title').textContent = `🏷 Broj lagera za ${v.nm}`;
  document.getElementById('ld-sub').textContent = 'Prijedlog: ' + lbl;
  document.getElementById('lager-input').value = lbl;
  _rsList('lager-dlg', true);
  setTimeout(() => { document.getElementById('lager-input').select(); }, 80);
}

function _lagerPlaceCancel() {
  _lagerPlaceIdx = null;
  if (_lagerPlaceBanner) { _lagerPlaceBanner.remove(); _lagerPlaceBanner = null; }
  map.off('click', _onLagerPlaceClick);
}

// Ramer-Douglas-Peucker simplifikacija — uklanja tačke unutar tolM metara od linije
function _rdpSimplify(pts, tolM) {
  if (pts.length <= 2) return pts;

  function perpDist(p, a, b) {
    const cosLat = Math.cos(p.la * Math.PI / 180);
    const dx = (b.lo - a.lo) * cosLat, dy = b.la - a.la;
    const len2 = dx*dx + dy*dy;
    if (len2 < 1e-18) return _haversine(p.la, p.lo, a.la, a.lo);
    const t = Math.max(0, Math.min(1, ((p.lo - a.lo)*cosLat*dx + (p.la - a.la)*dy) / len2));
    return _haversine(p.la, p.lo, a.la + t*dy, a.lo + t*(dx/cosLat));
  }

  function rdp(seg, eps) {
    if (seg.length <= 2) return seg;
    let maxD = 0, maxI = 0;
    for (let i = 1; i < seg.length - 1; i++) {
      const d = perpDist(seg[i], seg[0], seg[seg.length-1]);
      if (d > maxD) { maxD = d; maxI = i; }
    }
    if (maxD > eps) {
      const l = rdp(seg.slice(0, maxI+1), eps);
      const r = rdp(seg.slice(maxI), eps);
      return [...l.slice(0,-1), ...r];
    }
    return [seg[0], seg[seg.length-1]];
  }

  return rdp(pts, tolM);
}

function izravnajVlaku(idx) {
  const v = vlake[idx];
  if (!v || v.pts.length < 3) { showToast('Premalo tačaka za izravnavanje'); return; }
  const TOL = 4; // 4 metra tolerancija
  const before = v.pts.length;
  const simplified = _rdpSimplify([...v.pts], TOL);
  if (simplified.length >= before) { showToast('Vlaka je već optimalna'); return; }
  drawUndoStack.push(v.pts.map(p => ({...p})));
  v.pts = simplified;
  v.poly.setLatLngs(v.pts.map(p => [p.la, p.lo]));
  v.wpts.forEach(m => map.removeLayer(m));
  v.wpts = [];
  scheduleVlakaSave(idx);
  _saveLocalVlake();
  rndList();
  closeVlakaPopup();
  showToast(`✅ ${before - simplified.length} tačaka uklonjeno (${before} → ${simplified.length})`);
}

// === VLAKA LABELE ===
// Brojevi labela po vlaci/kraku. Krak dobije jednu labelu (dugačak dvije) — krakova ima
// puno, a svaka dodatna labela je šum; matična vlaka prati _labelFracs.
function _lblBroj(v, zoom) {
  const f = _labelFracs(v.pts, zoom).length;
  if (v.kr > 0) return f > 1 && calcL(v.pts) >= 600 ? 2 : 1;
  return f;
}
// Tačke gdje polaze krakovi ove vlake — labela ne smije na čvorište.
function _lblJunkcije(v) {
  const pre = v.nm + '.', out = [];
  for (const c of vlake) {
    if (c === v || c.projektId !== v.projektId || !c.pts || !c.pts.length) continue;
    const nm = String(c.nm);
    if (nm.startsWith(pre) && nm.indexOf('.', pre.length) < 0) out.push(c.pts[0]);
  }
  return out;
}
function _lblZauzetoOd(v) {
  const out = [];
  for (const o of vlake) if (o !== v && o._lblBox) for (const b of o._lblBox) out.push(b);
  return out;
}
// Ručno postavljena labela imena (sačuvana lokalno, po projektu+imenu vlake).
// var (ne let/const): updateVlakaLabel se može pozvati prije nego izvršavanje stigne do ove linije (TDZ).
var _lblOvrMem = null;
function _lblOvrAll() {
  if (_lblOvrMem) return _lblOvrMem;
  try { _lblOvrMem = JSON.parse(localStorage.getItem('tvlake_lbl_ovr_v1') || '{}') || {}; } catch(e) { _lblOvrMem = {}; }
  if (typeof _lblOvrMem !== 'object' || Array.isArray(_lblOvrMem)) _lblOvrMem = {};
  return _lblOvrMem;
}
function _lblKljuc(v) { return (v.projektId || '') + '|' + v.nm; }
function _lblOvrGet(v) {
  const o = _lblOvrAll()[_lblKljuc(v)];
  return o && Number.isFinite(o.la) && Number.isFinite(o.lo) ? o : null;
}
function _lblOvrSet(v, o) { _lblOvrAll()[_lblKljuc(v)] = { la: o.la, lo: o.lo, rot: Math.max(-90, Math.min(90, Math.round(o.rot || 0))) }; }
function _lblOvrDel(v) { delete _lblOvrAll()[_lblKljuc(v)]; }
function _lblOvrSnimi() {
  try { localStorage.setItem('tvlake_lbl_ovr_v1', JSON.stringify(_lblOvrAll())); return true; }
  catch(e) { showToast('⚠ Položaj labele nije sačuvan (memorija telefona)'); return false; }
}

var _lblEdit = false;      // način uređivanja: labele se mogu povući i zarotirati
var _lblSel = null;       // {v, kind:'ime'|'lager'}
function _lblNapraviPrimarni(v, pt, deg, pin) {
  const ed = _lblEdit;
  const sel = ed && _lblSel && _lblSel.v === v && _lblSel.kind === 'ime';
  const mk = L.marker([pt.la, pt.lo], {
    icon: _lblIcon(v.nm, deg, { edit: ed, sel, pin: pin || ed }),
    interactive: ed, draggable: ed, zIndexOffset: 500, pane: 'vlakeLabels', bubblingMouseEvents: false
  }).addTo(map);
  mk._lblDeg = deg;
  if (ed) {
    mk.on('click', e => { L.DomEvent.stopPropagation(e); _lblSelect(v, 'ime'); });
    mk.on('dragstart', () => _lblSelect(v, 'ime'));
    mk.on('dragend', () => setTimeout(() => _lblDragKraj(v, mk), 0));
  }
  return mk;
}

function updateVlakaLabel(i) {
  const v = vlake[i];
  if (!v) return;
  if (v.labelMk) { map.removeLayer(v.labelMk); v.labelMk = null; }
  if (v.lagerMk) { map.removeLayer(v.lagerMk); v.lagerMk = null; }
  (v.extraLabels || []).forEach(m => map.removeLayer(m));
  v.extraLabels = [];
  v._lblBox = [];
  if (!v.pts || v.pts.length < 1) return;

  // Krak s jednom tačkom — nema još pravca linije, labela odmah uz spoj s vlakom
  if (v.kr > 0 && v.pts.length === 1) {
    v.labelMk = L.marker([v.pts[0].la, v.pts[0].lo], {
      icon: _lblIcon(v.nm), interactive: false, zIndexOffset: 500, pane: 'vlakeLabels'
    }).addTo(map);
    return;
  }
  if (v.pts.length < 2) return;

  // Labela PARALELNO s linijom na idealnom mjestu (ne na čvorištu) — vidi _lblIdealno.
  const _zoom = map.getZoom();
  const ovr = _lblOvrGet(v);
  v._lblJsig = _lblJunkcije(v).map(p => p.la.toFixed(5) + ',' + p.lo.toFixed(5)).join(';');
  if (ovr) {
    v.labelMk = _lblNapraviPrimarni(v, ovr, ovr.rot || 0, true);
    v._lblBox = [{ la: ovr.la, lo: ovr.lo, r: _lblDuzinaM(v.nm) / 2 }];
  } else {
    try {
      const pl = _lblIdealno(v.pts, v.nm, _lblJunkcije(v), _lblBroj(v, _zoom), _lblZauzetoOd(v));
      pl.forEach((p, k) => {
        if (isNaN(p.la) || isNaN(p.lo)) return;
        v._lblBox.push({ la: p.la, lo: p.lo, r: p.win / 2 });
        if (k === 0) { v.labelMk = _lblNapraviPrimarni(v, p, p.deg, false); return; }
        v.extraLabels.push(L.marker([p.la, p.lo], {
          icon: _lblIcon(v.nm, p.deg), interactive: false, zIndexOffset: 498, pane: 'vlakeLabels'
        }).addTo(map));
      });
    } catch(e) { console.warn('Label err:', v.nm, e); }
  }
  // Roditelju su se možda promijenila čvorišta (novi/pomjeren krak) — preračunaj njegovu labelu.
  if (v.kr > 0) {
    const pi = _parentOf(v), pv = pi >= 0 ? vlake[pi] : null;
    if (pv && pv.pts && pv.pts.length > 1 && !_lblOvrGet(pv)) {
      const sig = _lblJunkcije(pv).map(p => p.la.toFixed(5) + ',' + p.lo.toFixed(5)).join(';');
      if (sig !== pv._lblJsig) updateVlakaLabel(pi);
    }
  }

  // Start/kraj oznake — mala zelena/crvena tačkica direktno na karti da se odmah vidi
  // gdje vlaka/krak počinje i završava. Isti obrazac (boja/stil) kao privremeni markeri
  // u _pickJunctionOnVlaka, samo trajni i manji. Guraju se u v.extraLabels (ne novo
  // polje) — tako automatski nasljeđuju sve postojeće show/hide/cleanup petlje.
  // Startna tačkica kraka je klikabilna: na spoju s roditeljskom vlakom se linije
  // preklapaju i klik zavisi od poretka slojeva na canvasu — tačkica garantovano
  // razrješava na taj krak (traži se po referenci objekta, ne po indeksu).
  // Bazna veličina je namjerno sitna (6px) — skalira se preko "Stil linija" panela
  // (Tačke vlake/krak: Veličina), da se ne gubi vlaka/krak ispod krupne tačkice.
  const _dotSz = Math.round(6 * ((_lineStyle.vlakaDotScale || 100) / 100));
  const _mkEndDot = (pt, col, onClick) => {
    const mk = L.marker([pt.la, pt.lo], {
      icon: L.divIcon({ className: '', iconSize: [_dotSz, _dotSz], iconAnchor: [_dotSz/2, _dotSz/2],
        html: `<div style="width:${_dotSz}px;height:${_dotSz}px;border-radius:50%;background:${col};border:1.5px solid #fff;box-shadow:0 0 0 1.5px ${col}55,0 1px 2px rgba(0,0,0,0.5);"></div>` }),
      interactive: !!onClick, zIndexOffset: 480, pane: 'vlakeLabels'
    }).addTo(map);
    if (onClick) mk.on('click', onClick);
    return mk;
  };
  const _junctionClick = (e) => {
    if (recOn) return;
    if (['edit','delnode','merge','addline','addpoint'].includes(activeTool)) return;
    if (_msrOn || _guideOn || _tackaPlaceMode || textToolOn || _dozDrawType !== null || (typeof _vsdOn !== 'undefined' && _vsdOn)) return;
    L.DomEvent.stopPropagation(e);
    if (e.originalEvent) e.originalEvent.stopPropagation();
    const idx = vlake.findIndex(vv => vv === v);
    if (idx >= 0) { selI(idx); showVlakaPopup(idx, e.latlng); }
  };
  v.extraLabels.push(_mkEndDot(v.pts[0], '#4ade80', v.kr > 0 ? _junctionClick : null));
  v.extraLabels.push(_mkEndDot(v.pts[v.pts.length - 1], '#f87171'));

  if ((v.kr === 0 || v.naPutu) && v.lager) {
    // Matična vlaka: lager na početku (pts[0]). Krak "na putu": lager na KRAJU
    // (zadnja tačka = izlaz na kamionski put), osim ako je ručno postavljen (lagerPt).
    const pFirst = v.lagerPt || (v.naPutu && v.kr > 0 ? v.pts[v.pts.length - 1] : v.pts[0]);
    let lagerIcon;
    if (typeof VlakaLager !== 'undefined' && VlakaLager.icon) lagerIcon = VlakaLager.icon(v);
    else {
      const dims = {width:Math.round(28*(_lineStyle.lagerScale||100)/100),height:Math.round(13*(_lineStyle.lagerScale||100)/100),font:Math.max(11,Math.round(11*(_lineStyle.lagerScale||100)/100))};
      const LW=dims.width, LH=dims.height, fontPx=dims.font;
      lagerIcon = L.divIcon({ className: 'vlaka-lager-mk', iconSize: [LW, LH + fontPx + 5], iconAnchor: [LW/2, LH/2],
        html: _stpLagerSvg(LW, LH, true) + `<div style="color:#fbbf24;font-family:ui-monospace,Roboto Mono,Courier New,monospace;font-weight:900;letter-spacing:.04em;font-size:${fontPx}px;text-align:center;line-height:1;text-shadow:0 0 3px #000,0 0 3px #000,1px 1px 0 #000,-1px -1px 0 #000;margin-top:1px;pointer-events:none;white-space:nowrap;">${_escHtml(v.lager)}</div>` });
    }
    const ed = _lblEdit;
    v.lagerMk = L.marker([pFirst.la, pFirst.lo], {
      icon: lagerIcon, interactive: ed, draggable: ed, zIndexOffset: 600, pane: 'vlakeLabels', bubblingMouseEvents: false
    }).addTo(map);
    if (ed) {
      const el = v.lagerMk.getElement();
      if (el) { el.classList.add('lbl-edit-lager'); if (_lblSel && _lblSel.v === v && _lblSel.kind === 'lager') el.classList.add('lbl-sel'); }
      v.lagerMk.on('click', e => { L.DomEvent.stopPropagation(e); _lblSelect(v, 'lager'); });
      v.lagerMk.on('dragstart', () => _lblSelect(v, 'lager'));
      v.lagerMk.on('dragend', () => setTimeout(() => _lagerDragKraj(v), 0));
    }
  }
  _scheduleDeclutterLabels();
  if(typeof VlakaDirection!=='undefined')VlakaDirection.draw(v);
}

// ─── UREĐIVANJE LABELA: povuci (pomjeri) i zarotiraj ─────────────────────────
// Labela imena vlake/kraka se pamti lokalno (_LBL_OVR_KEY); lager putuje sa vlakom
// (lagerPt {la,lo,rot,u} se šalje kao lager_pt — jsonb, bez migracije).
function _lblIdx(v) { return vlake.indexOf(v); }
function _lblClamp(d) { return Math.max(-90, Math.min(90, Math.round(Number(d) || 0))); }
function _lblTrenutniUgao(sel) {
  if (!sel) return 0;
  if (sel.kind === 'lager') return typeof VlakaLager !== 'undefined' && VlakaLager.rotOf ? VlakaLager.rotOf(sel.v) : 0;
  const o = _lblOvrGet(sel.v);
  if (o) return o.rot || 0;
  return sel.v.labelMk && Number.isFinite(sel.v.labelMk._lblDeg) ? Math.round(sel.v.labelMk._lblDeg) : 0;
}
function _lblMarkSel() {
  vlake.forEach(v => {
    const a = v.labelMk && v.labelMk.getElement && v.labelMk.getElement();
    const l = v.lagerMk && v.lagerMk.getElement && v.lagerMk.getElement();
    const lab = a && a.querySelector('.vlaka-lbl');
    const sI = _lblSel && _lblSel.v === v && _lblSel.kind === 'ime';
    const sL = _lblSel && _lblSel.v === v && _lblSel.kind === 'lager';
    if (lab) { lab.classList.toggle('lbl-sel', sI); lab.style.background = sI ? 'rgba(251,191,36,0.35)' : ''; }
    if (l) l.classList.toggle('lbl-sel', sL);
  });
}
function _lblSelect(v, kind) {
  if (!_lblEdit) return;
  _lblSel = { v, kind };
  _lblMarkSel();
  _lblBarOsvjezi();
}
function _lblDragKraj(v, mk) {
  if (!_lblEdit || !mk || vlake.indexOf(v) < 0) return;
  const ll = mk.getLatLng();
  _lblOvrSet(v, { la: ll.lat, lo: ll.lng, rot: Number.isFinite(mk._lblDeg) ? mk._lblDeg : 0 });
  _lblOvrSnimi();
  updateVlakaLabel(_lblIdx(v));
  _lblMarkSel();
  _lblBarOsvjezi();
}
function _lagerSnimi(v) {
  const i = _lblIdx(v);
  v.updatedAt = new Date().toISOString();
  _saveLocalVlake();
  if (i >= 0) sbFlushVlaka(i);
}
function _lagerDragKraj(v) {
  if (!_lblEdit || !v.lagerMk || vlake.indexOf(v) < 0) return;
  const ll = v.lagerMk.getLatLng();
  v.lagerPt = { la: ll.lat, lo: ll.lng, rot: _lblTrenutniUgao({ v, kind: 'lager' }), u: 1 };
  _lagerSnimi(v);
  updateVlakaLabel(_lblIdx(v));
  _lblMarkSel();
}
// Živa rotacija (slajder) — bez snimanja na svaki pomak, snimanje ide na `change`.
function _lblRotiraj(deg) {
  const s = _lblSel;
  if (!s || !_lblEdit) return;
  deg = _lblClamp(deg);
  if (s.kind === 'ime') {
    const mk = s.v.labelMk;
    if (!mk) return;
    const ll = mk.getLatLng();
    _lblOvrSet(s.v, { la: ll.lat, lo: ll.lng, rot: deg });
    mk._lblDeg = deg;
    mk.setIcon(_lblIcon(s.v.nm, deg, { edit: true, sel: true, pin: true }));
  } else {
    const mk = s.v.lagerMk;
    if (!mk) return;
    const ll = mk.getLatLng();
    s.v.lagerPt = { la: ll.lat, lo: ll.lng, rot: deg, u: 1 };
    mk.setIcon(VlakaLager.icon(s.v));
  }
  _lblBarOsvjezi(true);
  _scheduleDeclutterLabels();
}
function _lblSnimi() {
  const s = _lblSel;
  if (!s) return;
  if (s.kind === 'ime') _lblOvrSnimi(); else _lagerSnimi(s.v);
}
function _lblKorak(d) { _lblRotiraj(_lblTrenutniUgao(_lblSel) + d); _lblSnimi(); }
// "Auto": labela imena se vraća na idealan položaj; lager gubi rotaciju (i položaj,
// ali samo ako ga je postavilo ovo uređivanje — ručno "Pomjeri lager" ostaje).
function _lblAuto() {
  const s = _lblSel;
  if (!s) return;
  if (s.kind === 'ime') { _lblOvrDel(s.v); _lblOvrSnimi(); }
  else if (s.v.lagerPt) {
    s.v.lagerPt = s.v.lagerPt.u ? null : { la: s.v.lagerPt.la, lo: s.v.lagerPt.lo };
    _lagerSnimi(s.v);
  }
  updateVlakaLabel(_lblIdx(s.v));
  _lblMarkSel();
  _lblBarOsvjezi();
}
function _lblBarGradi() {
  let b = document.getElementById('lbl-edit-bar');
  if (b) return b;
  b = document.createElement('div');
  b.id = 'lbl-edit-bar';
  b.hidden = true;
  b.innerHTML = `
    <div class="lb-row"><b>🏷 Labele</b><span id="lb-ime" class="lb-ime"></span><button type="button" class="lb-ok" onclick="_lblEditToggle(false)">✓ Gotovo</button></div>
    <div class="lb-row" id="lb-ctl">
      <button type="button" onclick="_lblKorak(-15)" title="Zaokreni −15°" aria-label="Zaokreni ulijevo">↺</button>
      <input type="range" id="lb-rot" min="-90" max="90" step="1" value="0" oninput="_lblRotiraj(this.value)" onchange="_lblSnimi()" aria-label="Ugao labele">
      <button type="button" onclick="_lblKorak(15)" title="Zaokreni +15°" aria-label="Zaokreni udesno">↻</button>
      <span id="lb-deg" class="lb-deg">0°</span>
      <button type="button" onclick="_lblAuto()" title="Vrati na automatski položaj">Auto</button>
    </div>
    <div class="lb-hint" id="lb-hint"></div>`;
  document.body.appendChild(b);
  try { L.DomEvent.disableClickPropagation(b); L.DomEvent.disableScrollPropagation(b); } catch(e) {}
  return b;
}
function _lblBarOsvjezi(samoUgao) {
  const b = document.getElementById('lbl-edit-bar');
  if (!b) return;
  const s = _lblSel, ctl = b.querySelector('#lb-ctl');
  const ug = _lblTrenutniUgao(s);
  b.querySelector('#lb-deg').textContent = ug + '°';
  const r = b.querySelector('#lb-rot');
  if (r && String(r.value) !== String(ug)) r.value = ug;
  if (samoUgao) return;
  ctl.style.display = s ? '' : 'none';
  b.querySelector('#lb-ime').textContent = s ? (s.kind === 'lager' ? 'lager ' + (s.v.lager || '') + ' · ' + s.v.nm : s.v.nm) : '';
  b.querySelector('#lb-hint').textContent = s
    ? 'Povuci labelu da je pomjeriš, slajder je rotira.'
    : 'Dodirni labelu vlake/kraka ili lager, pa je povuci ili zarotiraj.';
}
function _lblEditToggle(on, v) {
  const nova = on === undefined ? !_lblEdit : !!on;
  if (nova === _lblEdit) return;
  if (nova && (typeof recOn !== 'undefined' && recOn)) { showToast('Završi snimanje vlake pa uređuj labele'); return; }
  _lblEdit = nova;
  if (!nova) _lblSel = null;
  document.body.classList.toggle('lbl-edit-on', nova);
  const b = _lblBarGradi();
  b.hidden = !nova;
  if (nova) _lblBarOsvjezi();
  vlake.forEach((x, i) => updateVlakaLabel(i));
  if (nova && v) _lblSelect(v, 'ime');
  else _lblMarkSel();
  if (typeof _vsdOn !== 'undefined' && _vsdOn && typeof _vsdRender === 'function') _vsdRender();
  if (nova) showToast('🏷 Uređivanje labela: povuci labelu ili lager, slajder je zaokreće');
}
function vpLabele() {
  const v = vlake[_vpIdx];
  closeVlakaPopup();
  if (_lblEdit) { if (v) _lblSelect(v, 'ime'); return; }
  _lblEditToggle(true, v);
}

// ═══════════════════════════════════════════════════════════════════════════
// === REFERENTNA KARTA (Image Overlay + Line Detection) ===
// ═══════════════════════════════════════════════════════════════════════════

// ── Šumski kamionski putevi (statički GeoJSON sloj) ──────────────────────────
let _puteviLayerBg = null;  // bijela pozadina za kontrast
let _puteviLayerFg = null;  // narandžasta linija
let _puteviVisible = localStorage.getItem('tvlake_putevi_visible') !== '0'; // default: vidljivi
let _puteviGeoJSON = null;  // raw GeoJSON za routing
let _puteviGraph   = null;  // {nodes, adj} — grade se lazy

function _loadPutevi() {
  fetch('./PUTEVI/putevi.geojson')
    .then(r => { if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
    .then(data => {
      _puteviGeoJSON = data;
      const sharedOpts = { renderer: _puteviRenderer, pane: 'putevi' };
      _puteviLayerBg = L.geoJSON(data, {
        ...sharedOpts,
        interactive: false,
        style: { color: '#fff', weight: 6, opacity: 0.7, lineCap: 'round', lineJoin: 'round' }
      }).addTo(map);
      _puteviLayerFg = L.geoJSON(data, {
        ...sharedOpts,
        style: { color: '#f97316', weight: 3, opacity: 1.0, lineCap: 'round', lineJoin: 'round' },
        onEachFeature(feature, layer) {
          if (feature.properties?.name) {
            layer.bindTooltip(feature.properties.name, { sticky: true, direction: 'top' });
          }
        }
      }).addTo(map);
      if(typeof VlakaDirection!=='undefined')VlakaDirection.refresh();
      // Primijeni sačuvano stanje vidljivosti
      if (!_puteviVisible) togglePutevi(false);
      const cb = document.getElementById('putevi-toggle');
      if (cb) cb.checked = _puteviVisible;
      if(typeof window!=='undefined')window.GithubLayers?.render();
    })
    .catch(e => console.error('Putevi GeoJSON greška:', e));
}

function togglePutevi(show) {
  _puteviVisible = show;
  [_puteviLayerBg, _puteviLayerFg].forEach(l => {
    if (!l) return;
    if (show) map.addLayer(l); else map.removeLayer(l);
  });
  const cb = document.getElementById('putevi-toggle');
  if (cb) cb.checked = show;
  try { localStorage.setItem('tvlake_putevi_visible', show ? '1' : '0'); } catch(e) {}
}

let _refVisible = true, _refLoadSeq = 0;
let _refImg = null;       // HTMLImageElement
let _refBounds = null;    // [[south,west],[north,east]]
let _refOverlay = null;   // L.imageOverlay / AffineImageOverlay (aktivna, nesačuvana)
let _refImpGroup = null;  // L.layerGroup — detektovane vlake
let _refRepoOverlays = {}; // id → overlay za sačuvane slike iz repozitorija
let _refRepoData = [];     // lokalna kopija unesenih stavki
let _refCPs = [];          // kontrolne tačke aktivne slike: [{imgX,imgY,lat,lng}]
let _refCalibOn = false;   // mod kalibracije
let _refCalibStage = 'img';// 'img' (klik na slici) | 'map' (klik gdje treba)
let _refCalibTmp = null;   // privremeni {imgX,imgY} dok se čeka ciljni klik
let _refCalibLayer = null; // L.layerGroup s markerima kontrolnih tačaka

function refKartaLoad(e) {
  const file=e.target.files[0];if(!file)return;const token=++_refLoadSeq,url=URL.createObjectURL(file),img=new Image();
  img.onload=()=>{if(token!==_refLoadSeq){URL.revokeObjectURL(url);return;}const previous=_refImg?.src;ReferenceVlake.invalidate(true);_refImg=img;_refVisible=true;_refCPs=[];if(_refCalibOn)_refCalibStop();if(_refCalibLayer)_refCalibLayer.clearLayers();document.getElementById('refkarta-ctrl').style.display='';ReferenceVlake.showQuick();refKartaFitView();if(previous?.startsWith('blob:'))URL.revokeObjectURL(previous);showToast('Karta učitana. Poravnaj je pa detektuj vlake uz oznake T + broj.');};
  img.onerror=()=>{URL.revokeObjectURL(url);if(token===_refLoadSeq)showToast('Greška pri učitavanju slike.');};img.src=url;
}

function refKartaFitView() {
  if (!_refImg) return;
  const b = map.getBounds();
  _refBounds = [[b.getSouth(), b.getWest()], [b.getNorth(), b.getEast()]];
  _placeRefOverlay();
  showToast('📐 Karta postavljena na trenutni prikaz');
}

function refKartaFitOdjel() {
  if (!_refImg) return;
  if (!graniceOdjeli.length) { showToast('⚠ Nema učitanog KML odjela'); return; }
  const b = graniceOdjeli[0].bounds;
  _refBounds = [[b.getSouth(), b.getWest()], [b.getNorth(), b.getEast()]];
  _refClipToOdjel = true;
  const cb = document.getElementById('refkarta-clip');
  if (cb) cb.checked = true;
  _placeRefOverlay();
  showToast('📐 Karta postavljena i isječena po odjelu');
}

// ─── Afina/sličnosna transformacija iz parova (imgPx → ciljni px) ─────────────
// Riješi z = p*x + q*y + r metodom najmanjih kvadrata (3 nepoznate).
function _refSolve3(rows, zs) {
  // Normalne jednačine 3x3
  let Sxx=0,Sxy=0,Sx=0,Syy=0,Sy=0,n=rows.length,Sxz=0,Syz=0,Sz=0;
  for (let i=0;i<n;i++){
    const x=rows[i][0], y=rows[i][1], z=zs[i];
    Sxx+=x*x; Sxy+=x*y; Sx+=x; Syy+=y*y; Sy+=y;
    Sxz+=x*z; Syz+=y*z; Sz+=z;
  }
  const A=[[Sxx,Sxy,Sx],[Sxy,Syy,Sy],[Sx,Sy,n]], B=[Sxz,Syz,Sz];
  return _solve3x3(A,B);
}
function _solve3x3(A,B){
  // Gaussova eliminacija s pivotiranjem
  const M=[[...A[0],B[0]],[...A[1],B[1]],[...A[2],B[2]]];
  for (let c=0;c<3;c++){
    let piv=c; for(let r=c+1;r<3;r++) if(Math.abs(M[r][c])>Math.abs(M[piv][c])) piv=r;
    [M[c],M[piv]]=[M[piv],M[c]];
    if (Math.abs(M[c][c])<1e-12) return null;
    for (let r=0;r<3;r++){ if(r===c) continue; const f=M[r][c]/M[c][c]; for(let k=c;k<4;k++) M[r][k]-=f*M[c][k]; }
  }
  return [M[0][3]/M[0][0], M[1][3]/M[1][1], M[2][3]/M[2][2]];
}
// Vrati {a,b,c,d,e,f}: X=a*x+c*y+e, Y=b*x+d*y+f   (CSS matrix konvencija)
function _refAffineFromPairs(pairs) {
  // pairs: [{x,y,X,Y}]
  if (pairs.length === 2) {
    // Sličnosna (translacija+rotacija+skala)
    const [p,q]=pairs;
    const dx=q.x-p.x, dy=q.y-p.y, dX=q.X-p.X, dY=q.Y-p.Y;
    const den=dx*dx+dy*dy || 1e-9;
    const a=(dx*dX+dy*dY)/den;
    const b=(dx*dY-dy*dX)/den;
    return { a, b, c:-b, d:a, e:p.X-a*p.x+b*p.y, f:p.Y-b*p.x-a*p.y };
  }
  // ≥3: puna afina (najmanji kvadrati)
  const rows = pairs.map(p=>[p.x,p.y]);
  const sx = _refSolve3(rows, pairs.map(p=>p.X)); // [a,c,e]
  const sy = _refSolve3(rows, pairs.map(p=>p.Y)); // [b,d,f]
  if (!sx || !sy) return null;
  return { a:sx[0], c:sx[1], e:sx[2], b:sy[0], d:sy[1], f:sy[2] };
}

// ─── Custom Leaflet layer: slika transformisana afinom (rotacija+skala+skew) ──
const AffineImageOverlay = L.Layer.extend({
  initialize(src, cps, opts) { this._src=src; this._cps=cps; this.options=opts||{}; },
  setControlPoints(cps){ this._cps=cps; if(this._img) this._reset(); },
  setOpacity(o){ this.options.opacity=o; if(this._img) this._img.style.opacity=o; },
  onAdd(map) {
    this._map = map;
    const img = this._img = L.DomUtil.create('img');
    img.src = this._src;
    img.style.position = 'absolute';
    img.style.transformOrigin = '0 0';
    img.style.opacity = this.options.opacity ?? 0.6;
    img.style.pointerEvents = 'none';
    img.style.imageRendering = 'auto';
    img.draggable = false;
    (map.getPane(this.options.pane) || map.getPanes().overlayPane).appendChild(img);
    map.on('zoom viewreset', this._reset, this);
    this._reset();
    return this;
  },
  onRemove(map) {
    if (this._img) L.DomUtil.remove(this._img);
    map.off('zoom viewreset', this._reset, this);
  },
  _reset() {
    if (!this._img || !this._cps || this._cps.length < 2) return;
    const map = this._map;
    const pairs = this._cps.map(cp => {
      const lp = map.latLngToLayerPoint([cp.lat, cp.lng]);
      return { x:cp.imgX, y:cp.imgY, X:lp.x, Y:lp.y };
    });
    const M = _refAffineFromPairs(pairs);
    if (!M) return;
    this._img.style.transform =
      `matrix(${M.a},${M.b},${M.c},${M.d},${M.e},${M.f})`;
  }
});

// Prikaži aktivnu sliku — afino ako ima ≥2 kontrolne tačke, inače bbox
function _placeRefOverlay() {
  if(typeof ReferenceVlake!=='undefined')ReferenceVlake.invalidate();
  if (_refOverlay) { map.removeLayer(_refOverlay); _refOverlay = null; }
  if (!_refImg) return;
  const opa = parseInt(document.getElementById('refkarta-opa').value) / 100;
  if (_refCPs.length >= 2) {
    _refOverlay = new AffineImageOverlay(_refImg.src, _refCPs, { opacity:opa, pane:'refKarte' }).addTo(map);
  } else if (_refBounds) {
    _refOverlay = L.imageOverlay(_refImg.src, _refBounds, {
      opacity: opa, interactive: false, crossOrigin: true, pane: 'refKarte'
    }).addTo(map);
  }
  const saveBtn = document.getElementById('refkarta-save-btn');
  if (saveBtn) saveBtn.style.display = '';
  if(!_refVisible&&_refOverlay)map.removeLayer(_refOverlay);
  _refApplyClipPath();
  if(typeof ReferenceVlake!=='undefined')ReferenceVlake.refreshQuick();
}

// ─── Clip slike po poligonu odjela ─────────────────────────────────────────
let _refClipToOdjel = false;

function _refToggleClip(on) {
  _refClipToOdjel = on;
  _refApplyClipPath();
}

function _refApplyClipPath() {
  if (!_refOverlay) return;
  const el = _refOverlay.getElement ? _refOverlay.getElement() : _refOverlay._img;
  if (!el) return;

  if (!_refClipToOdjel || !_refBounds || !graniceOdjeli.length || !graniceOdjeli[0].ring) {
    el.style.clipPath = '';
    return;
  }
  const [[south, west], [north, east]] = _refBounds;
  const ring = graniceOdjeli[0].ring;
  const pts = ring.map(([lat, lon]) => {
    const xP = ((lon - west) / (east - west) * 100).toFixed(2);
    const yP = ((north - lat) / (north - south) * 100).toFixed(2);
    return `${xP}% ${yP}%`;
  });
  el.style.clipPath = `polygon(${pts.join(',')})`;
}

// ─── Ručno fitovanje (drag handles na uglovima i stranama) ─────────────────
let _refManualFitOn = false;
let _refFitHandles = [];

function _refToggleManualFit() {
  _refManualFitOn = !_refManualFitOn;
  if (_refManualFitOn) _refShowFitHandles();
  else _refHideFitHandles();
  const btn = document.getElementById('refkarta-manfit-btn');
  if (btn) {
    btn.style.background = _refManualFitOn ? '#14532d' : '#1e293b';
    btn.style.color = _refManualFitOn ? '#4ade80' : '#94a3b8';
    btn.style.borderColor = _refManualFitOn ? '#166534' : '#334155';
  }
}

function _refShowFitHandles() {
  _refHideFitHandles();
  if (!_refBounds) { showToast('⚠ Prvo postavi sliku (Fituj)'); _refManualFitOn = false; return; }
  const [[s,w],[n,e]] = _refBounds;
  const defs = [
    { pos:[n,w], t:'nw' }, { pos:[n,e], t:'ne' },
    { pos:[s,e], t:'se' }, { pos:[s,w], t:'sw' },
    { pos:[n,(w+e)/2], t:'n' }, { pos:[s,(w+e)/2], t:'s' },
    { pos:[(n+s)/2,w], t:'w' }, { pos:[(n+s)/2,e], t:'e' }
  ];
  const cur = {nw:'nwse-resize',ne:'nesw-resize',se:'nwse-resize',sw:'nesw-resize',
               n:'ns-resize',s:'ns-resize',w:'ew-resize',e:'ew-resize'};
  defs.forEach(({pos, t}) => {
    const isCorner = t.length === 2;
    const mk = L.marker(pos, {
      draggable: true,
      icon: L.divIcon({
        className: '',
        html: `<div style="width:${isCorner?14:10}px;height:${isCorner?14:10}px;background:${isCorner?'#38bdf8':'#a78bfa'};border:2px solid #fff;border-radius:${isCorner?2:5}px;cursor:${cur[t]};box-shadow:0 1px 4px rgba(0,0,0,0.5);"></div>`,
        iconSize: [isCorner?14:10, isCorner?14:10],
        iconAnchor: [isCorner?7:5, isCorner?7:5]
      })
    }).addTo(map);
    mk._fitType = t;
    mk.on('drag', () => _refOnFitDrag(mk));
    mk.on('dragend', () => _refOnFitDragEnd());
    _refFitHandles.push(mk);
  });
}

function _refOnFitDrag(mk) {
  const ll = mk.getLatLng();
  let [[s,w],[n,e]] = _refBounds;
  switch(mk._fitType) {
    case 'nw': n=ll.lat; w=ll.lng; break;
    case 'ne': n=ll.lat; e=ll.lng; break;
    case 'se': s=ll.lat; e=ll.lng; break;
    case 'sw': s=ll.lat; w=ll.lng; break;
    case 'n': n=ll.lat; break;
    case 's': s=ll.lat; break;
    case 'w': w=ll.lng; break;
    case 'e': e=ll.lng; break;
  }
  _refBounds = [[s,w],[n,e]];
  if (_refOverlay && _refOverlay.setBounds) {
    _refOverlay.setBounds(L.latLngBounds([[s,w],[n,e]]));
  }
  _refApplyClipPath();
  const posMap = {
    nw:[n,w], ne:[n,e], se:[s,e], sw:[s,w],
    n:[n,(w+e)/2], s:[s,(w+e)/2], w:[(n+s)/2,w], e:[(n+s)/2,e]
  };
  _refFitHandles.forEach(h => {
    if (h._fitType !== mk._fitType) h.setLatLng(posMap[h._fitType]);
  });
}

function _refOnFitDragEnd() {
  _placeRefOverlay();
  if (_refManualFitOn) _refShowFitHandles();
}

function _refHideFitHandles() {
  _refFitHandles.forEach(mk => map.removeLayer(mk));
  _refFitHandles = [];
}

function refKartaSetOpacity(v) {
  if (_refOverlay) _refOverlay.setOpacity(parseInt(v) / 100);
}

function refKartaSetVisible(v) {
  _refVisible=!!v;if(!_refOverlay)return;if(v)_refOverlay.addTo(map);else map.removeLayer(_refOverlay);
  if(typeof ReferenceVlake!=='undefined'){if(v)ReferenceVlake.showQuick();else ReferenceVlake.refreshQuick();}
}

function refKartaRemove() {
  ++_refLoadSeq;const oldSrc=_refImg?.src;if(typeof ReferenceVlake!=='undefined')ReferenceVlake.invalidate(true);
  if (_refCalibOn) _refCalibStop();
  if (_refManualFitOn) { _refHideFitHandles(); _refManualFitOn = false; }
  if (_refOverlay) { map.removeLayer(_refOverlay); _refOverlay = null; }
  _refImg = null; _refBounds = null; _refCPs = [];
  if(oldSrc?.startsWith('blob:'))URL.revokeObjectURL(oldSrc);
  _refClipToOdjel = false;
  const cb = document.getElementById('refkarta-clip');
  if (cb) cb.checked = false;
  document.getElementById('refkarta-ctrl').style.display = 'none';
  document.getElementById('refkarta-file').value = '';
  const saveBtn = document.getElementById('refkarta-save-btn');
  if (saveBtn) { saveBtn.style.display = 'none'; saveBtn.disabled = false; saveBtn.innerHTML = '<svg class="ic"><use href="#ic-server"/></svg> Sačuvaj na server'; }
  refKartaClearImported();
  ReferenceVlake.refreshQuick();
}

// ─── Kalibracija preko kontrolnih tačaka ──────────────────────────────────────
// Pretvori klik na karti (latlng) → piksel slike, koristeći trenutni prikaz.
function _refLatLngToImgPx(latlng) {
  if (_refCPs.length >= 2) {
    // Invertuj afinu pixel→layerPoint
    const pairs = _refCPs.map(cp => {
      const lp = map.latLngToLayerPoint([cp.lat, cp.lng]);
      return { x:cp.imgX, y:cp.imgY, X:lp.x, Y:lp.y };
    });
    const M = _refAffineFromPairs(pairs);
    if(!M)return null;
    const lp = map.latLngToLayerPoint(latlng);
    const det = M.a*M.d - M.b*M.c;
    if (Math.abs(det) < 1e-12) return null;
    const dx = lp.x - M.e, dy = lp.y - M.f;
    return { imgX:( M.d*dx - M.c*dy)/det, imgY:(-M.b*dx + M.a*dy)/det };
  }
  if (_refBounds && _refImg) {
    const [[s,w],[n,e]] = _refBounds;
    return {
      imgX: (latlng.lng - w)/(e - w) * _refImg.width,
      imgY: (n - latlng.lat)/(n - s) * _refImg.height
    };
  }
  return null;
}

let _refCalibSnap = true;       // veži ciljni klik na centar najbližeg odjela
let _refSnapTargetLayer = null; // markeri centara odjela tokom kalibracije

function _refCalibSnapChanged(on) {
  _refCalibSnap = on;
  if (_refCalibOn) _refShowSnapTargets();
}

function _refCalibToggle() {
  if (_refCalibOn) _refCalibStop(); else _refCalibStart();
}
function _refCalibStart() {
  if (!_refImg) { showToast('⚠ Prvo učitaj sliku'); return; }
  if (!_refOverlay) { showToast('⚠ Prvo postavi sliku (Fituj u prikaz)'); return; }
  refKartaSetVisible(true);
  _refCalibOn = true;
  _refCalibStage = 'img';
  _refCalibTmp = null;
  if (!_refCalibLayer) _refCalibLayer = L.layerGroup().addTo(map);
  _refCalibRedrawMarkers();
  map.on('click', _refCalibClick);
  _refOverlay.setOpacity(0.55);
  _refShowSnapTargets();
  _refCalibUpdateUI();
}
function _refCalibStop() {
  _refCalibOn = false;
  _refCalibTmp = null;
  map.off('click', _refCalibClick);
  _refHideSnapTargets();
  // Pojas sigurnosti: markeri kalibracije su od v1.6.0 divIcon (bez canvasa),
  // ali uređaj koji je kalibrirao PRIJE ovog update-a — ili bilo koji budući
  // canvas sloj u ovom pane-u — ostavio bi renderer na z-indexu 620 koji guta
  // sve dodire. Oslobađa se ovdje jer u 'refKarte' ništa drugo ne crta u canvas
  // (slike su <img> sa pointer-events:none, ostali markeri su divIcon).
  _oslobodiPaneRenderer('refKarte');
  // Vrati providnost na vrijednost slidera
  const opaEl = document.getElementById('refkarta-opa');
  if (_refOverlay && opaEl) _refOverlay.setOpacity(parseInt(opaEl.value)/100);
  _refCalibUpdateUI();
}
function _refCalibClick(e) {
  if (!_refCalibOn) return;
  if (_refCalibStage === 'img') {
    const px = _refLatLngToImgPx(e.latlng);
    if (!px) return;
    _refCalibTmp = px;
    // Plavi marker = tačka na slici (kako je sada).
    // v1.6.0: NAMJERNO divIcon, a NE L.circleMarker. Karta radi sa
    // preferCanvas:true, pa bi circleMarker natjerao Leaflet da za pane
    // 'refKarte' (z-index 620 — IZNAD mjerenja 410, vlaka 400 i oznaka 401)
    // napravi canvas renderer preko CIJELE karte. Taj canvas guta SVAKI dodir
    // ispod sebe, a Leaflet ga NIKAD sam ne ukloni — ostajao bi i nakon
    // _refCalibLayer.clearLayers(), dakle do kraja sesije. Dokazano
    // reprodukcijom: jedna kalibraciona tačka = 0 klikova na izmjerenu
    // površinu, i poslije brisanja markera. Zeleni marker ispod je oduvijek
    // divIcon; ovim je cijeli kalibracioni tok bez canvasa.
    L.marker(e.latlng, {
      pane:'refKarte', interactive:false,
      icon: L.divIcon({ className:'', iconSize:[18,18], iconAnchor:[9,9],
        html:'<div style="width:14px;height:14px;border-radius:50%;background:#38bdf8;border:2px solid #fff;box-shadow:0 0 4px rgba(0,0,0,0.6);"></div>' })
    }).addTo(_refCalibLayer);
    _refCalibStage = 'map';
  } else {
    // Zeleni marker = gdje stvarno treba. Ako je snap uključen, veži na centar odjela.
    let lat = e.latlng.lat, lng = e.latlng.lng;
    if (_refCalibSnap) {
      const od = _refNearestOdjel(e.latlng);
      if (od) {
        lat = od.c[0]; lng = od.c[1];
        showToast(`📍 Vezano na centar odjela: ${od.name}`);
      } else {
        showToast('⚠ Nema odjela za snap — uzeta tačka klika');
      }
    }
    _refCPs.push({ imgX:_refCalibTmp.imgX, imgY:_refCalibTmp.imgY, lat, lng });
    _refCalibTmp = null;
    _refCalibStage = 'img';
    _placeRefOverlay();
    if (_refCalibOn) _refOverlay.setOpacity(0.55);
    _refCalibRedrawMarkers();
  }
  _refCalibUpdateUI();
}

// Centroid odjela (poklapa se s pozicijom broja-labela na topo karti)
function _refOdjelCentroid(od) {
  if (od.ring && od.ring.length) return _coordsCentroid(od.ring);
  if (od.bounds) { const c = od.bounds.getCenter(); return [c.lat, c.lng]; }
  return null;
}

// Ray-casting: da li je tačka unutar poligona (ring = [[lat,lng],...])
function _refPointInRing(lat, lng, ring) {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const yi = ring[i][0], xi = ring[i][1];
    const yj = ring[j][0], xj = ring[j][1];
    if (((yi > lat) !== (yj > lat)) &&
        (lng < (xj - xi) * (lat - yi) / ((yj - yi) || 1e-12) + xi)) inside = !inside;
  }
  return inside;
}

// Nađi odjel u kojem je klik (ili najbliži po centru); vrati {name, c:[lat,lng]}
function _refNearestOdjel(latlng) {
  if (!graniceOdjeli.length) return null;
  // 1) Odjel koji sadrži tačku
  for (const od of graniceOdjeli) {
    if (od.ring && od.ring.length > 2 && _refPointInRing(latlng.lat, latlng.lng, od.ring)) {
      const c = _refOdjelCentroid(od);
      if (c) return { name: od.name || '?', c };
    }
  }
  // 2) Inače najbliži centar
  let best = null, bestD = Infinity;
  for (const od of graniceOdjeli) {
    const c = _refOdjelCentroid(od);
    if (!c) continue;
    const d = (c[0]-latlng.lat)**2 + (c[1]-latlng.lng)**2;
    if (d < bestD) { bestD = d; best = { name: od.name || '?', c }; }
  }
  return best;
}

// Prikaži centre svih odjela kao snap-ciljeve tokom kalibracije
function _refShowSnapTargets() {
  _refHideSnapTargets();
  if (!_refCalibSnap || !graniceOdjeli.length) return;
  _refSnapTargetLayer = L.layerGroup().addTo(map);
  graniceOdjeli.forEach(od => {
    const c = _refOdjelCentroid(od);
    if (!c) return;
    L.marker(c, {
      pane:'refKarte', interactive:false,
      icon: L.divIcon({ className:'', iconSize:[null,null], iconAnchor:[0,0],
        html:`<div style="transform:translate(-50%,-50%);display:flex;align-items:center;gap:3px;white-space:nowrap;">
                <span style="width:8px;height:8px;border-radius:50%;background:#f59e0b;border:1.5px solid #fff;box-shadow:0 0 3px rgba(0,0,0,0.7);"></span>
                <span style="font-size:10px;font-weight:700;color:#fbbf24;text-shadow:0 0 3px #000,0 0 3px #000;">${od.name||''}</span>
              </div>` })
    }).addTo(_refSnapTargetLayer);
  });
}
function _refHideSnapTargets() {
  if (_refSnapTargetLayer) { map.removeLayer(_refSnapTargetLayer); _refSnapTargetLayer = null; }
}
function _refCalibRedrawMarkers() {
  if (!_refCalibLayer) return;
  _refCalibLayer.clearLayers();
  _refCPs.forEach((cp, i) => {
    L.marker([cp.lat, cp.lng], {
      pane:'refKarte', draggable:true,
      icon: L.divIcon({ className:'', iconSize:[20,20], iconAnchor:[10,10],
        html:`<div style="width:18px;height:18px;border-radius:50%;background:#22c55e;border:2px solid #fff;box-shadow:0 0 4px rgba(0,0,0,0.6);color:#fff;font-size:11px;font-weight:700;display:flex;align-items:center;justify-content:center;">${i+1}</div>` })
    }).on('dragend', ev => {
      const ll = ev.target.getLatLng();
      _refCPs[i].lat = ll.lat; _refCPs[i].lng = ll.lng;
      _placeRefOverlay(); if (_refCalibOn) _refOverlay.setOpacity(0.55);
    }).on('contextmenu', ev => {
      L.DomEvent.stop(ev);
      _refCPs.splice(i,1); _placeRefOverlay();
      if(_refCalibOn) _refOverlay.setOpacity(0.55);
      _refCalibRedrawMarkers(); _refCalibUpdateUI();
    }).addTo(_refCalibLayer);
  });
}
function _refCalibUpdateUI() {
  const btn = document.getElementById('refkarta-calib-btn');
  const hint = document.getElementById('refkarta-calib-hint');
  if (btn) {
    btn.textContent = _refCalibOn ? '✓ Završi kalibraciju' : '🎯 Kalibriraj (kontrolne tačke)';
    btn.style.background = _refCalibOn ? '#14532d' : '';
    btn.style.color = _refCalibOn ? '#4ade80' : '';
  }
  if (hint) {
    if (!_refCalibOn) { hint.style.display = 'none'; return; }
    hint.style.display = '';
    const n = _refCPs.length;
    if (_refCalibStage === 'img')
      hint.innerHTML = _refCalibSnap
        ? `<b style="color:#38bdf8;">Korak 1:</b> klikni <b>broj odjela na slici</b> (npr. „14"). <span style="color:#64748b;">Tačaka: ${n}</span>`
        : `<b style="color:#38bdf8;">Korak 1:</b> klikni prepoznatljivu tačku <b>na slici</b> (raskrsnica, ugao odjela…). <span style="color:#64748b;">Tačaka: ${n}</span>`;
    else
      hint.innerHTML = _refCalibSnap
        ? `<b style="color:#22c55e;">Korak 2:</b> klikni na <b>isti odjel na karti</b> — automatski se veže na njegov centar (🟠).`
        : `<b style="color:#22c55e;">Korak 2:</b> klikni gdje ta tačka <b>stvarno treba biti</b> na karti.`;
  }
}

function refKartaImportedVisible(v) {
  if (!_refImpGroup) return;
  if (v) _refImpGroup.addTo(map); else map.removeLayer(_refImpGroup);
}

function refKartaClearImported() {
  if(typeof ReferenceVlake!=='undefined'){ReferenceVlake.invalidate();return;}
  if(_refImpGroup){map.removeLayer(_refImpGroup);_refImpGroup=null;}_refDetectedLines=[];document.getElementById('refkarta-imp-ctrl').style.display='none';
}

async function refKartaImportDetected() { await ReferenceVlake.importSelected(); }

// ─── Repozitorij referentnih slika (Supabase) ─────────────────────────────────

async function _refRepoLoad() {
  const el = document.getElementById('refkarta-repo-list');
  if (!el) return;
  el.innerHTML = '<div style="font-size:11px;color:#475569;padding:6px 0;">Učitavam...</div>';
  try {
    const { data, error } = await sb.from('ref_karte')
      .select('*').order('uploaded_at', { ascending: false });
    if (error) throw error;
    _refRepoData = data || [];
    _refRepoRender();
  } catch(e) {
    el.innerHTML = `<div style="font-size:11px;color:#f87171;padding:6px 0;">⚠ Greška: ${e.message}</div>`;
  }
}

function _refRepoRender() {
  if(typeof ReferenceVlake!=='undefined')ReferenceVlake.refreshQuick();
  const el = document.getElementById('refkarta-repo-list');
  if (!el) return;
  if (!_refRepoData.length) {
    el.innerHTML = '<div style="font-size:11px;color:#475569;padding:6px 0;">Nema sačuvanih slika.</div>';
    return;
  }
  el.innerHTML = _refRepoData.map(r => {
    const isOwner = sbUser && sbUser.id === r.user_id;
    const active  = !!_refRepoOverlays[r.id];
    const opa     = Math.round((r.opacity || 0.55) * 100);
    return `<div style="background:#0f172a;border:1px solid ${active?'#38bdf8':'#1e3a5f'};border-radius:8px;padding:8px 10px;margin-bottom:6px;">
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:6px;">
        <label style="display:flex;align-items:center;gap:6px;flex:1;cursor:pointer;min-width:0;">
          <input type="checkbox" ${active?'checked':''} onchange="_refRepoToggle('${r.id}',this.checked)"
            style="width:14px;height:14px;accent-color:#38bdf8;flex-shrink:0;">
          <span style="font-size:12px;font-weight:600;color:#e2e8f0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${_escHtml(r.name)}</span>
        </label>
        ${isOwner ? `<button onclick="_refRepoDelete('${r.id}')" title="Obriši"
          style="padding:3px 7px;background:#7f1d1d;color:#f87171;border:none;border-radius:5px;font-size:12px;cursor:pointer;flex-shrink:0;"><svg class="ic"><use href="#ic-obrisi"/></svg></button>` : ''}
      </div>
      ${active ? `<div style="display:flex;align-items:center;gap:6px;">
        <span style="font-size:10px;color:#64748b;white-space:nowrap;">Providnost:</span>
        <input type="range" min="5" max="95" value="${opa}"
          style="flex:1;accent-color:#38bdf8;"
          oninput="_refRepoOpacity('${r.id}',this.value)">
        <span style="font-size:10px;color:#38bdf8;min-width:28px;text-align:right;" id="rrop-lbl-${r.id}">${opa}%</span>
      </div>` : ''}
    </div>`;
  }).join('');
}

async function _refRepoToggle(id, on) {
  const r = _refRepoData.find(x => x.id === id);
  if (!r) return;
  if (on) {
    if (!_refRepoOverlays[id]) {
      const src = `${SUPA_URL}/storage/v1/object/public/ref-karte/${r.storage_path}`;
      if (r.control_points && r.control_points.length >= 2) {
        _refRepoOverlays[id] = new AffineImageOverlay(src, r.control_points, {
          opacity: r.opacity || 0.55, pane: 'refKarte'
        }).addTo(map);
        const b = L.latLngBounds(r.control_points.map(cp => [cp.lat, cp.lng])).pad(0.5);
        map.fitBounds(b, {padding:[30,30]});
        _refRepoRender();
      } else {
        const img = new Image();
        img.crossOrigin = 'anonymous';
        img.onload = () => {
          _refRepoOverlays[id] = L.imageOverlay(img.src, r.bounds, {
            opacity: r.opacity || 0.55, interactive: false, pane: 'refKarte'
          }).addTo(map);
          map.fitBounds(r.bounds, {padding:[30,30]});
          _refRepoRender();
        };
        img.onerror = () => showToast('⚠ Greška pri učitavanju slike s servera');
        img.src = src;
      }
    }
  } else {
    if (_refRepoOverlays[id]) { map.removeLayer(_refRepoOverlays[id]); delete _refRepoOverlays[id]; }
    _refRepoRender();
  }
}

function _refRepoOpacity(id, val) {
  const opa = parseInt(val) / 100;
  const r = _refRepoData.find(x => x.id === id);
  if (r) r.opacity = opa;
  if (_refRepoOverlays[id]) _refRepoOverlays[id].setOpacity(opa);
  const lbl = document.getElementById('rrop-lbl-' + id);
  if (lbl) lbl.textContent = val + '%';
  // Debounce upis u bazu
  clearTimeout(_refRepoOpacity._t);
  _refRepoOpacity._t = setTimeout(async () => {
    if (sbUser) await sb.from('ref_karte').update({ opacity: opa }).eq('id', id);
  }, 800);
}

async function _refRepoDelete(id) {
  if (!await _dlgConfirm('Obrisati referentnu sliku s servera?', { danger: true })) return;
  const r = _refRepoData.find(x => x.id === id);
  if (!r) return;
  if (_refRepoOverlays[id]) { map.removeLayer(_refRepoOverlays[id]); delete _refRepoOverlays[id]; }
  try {
    await sb.storage.from('ref-karte').remove([r.storage_path]);
    await sb.from('ref_karte').delete().eq('id', id);
    _refRepoData = _refRepoData.filter(x => x.id !== id);
    _refRepoRender();
    showToast('🗑 Slika obrisana');
  } catch(e) { showToast('⚠ Greška brisanja: ' + e.message); }
}

async function refKartaSaveToServer() {
  if (!_refImg || !_refBounds) { showToast('⚠ Nema postavljene slike'); return; }
  if (!sbUser) { showToast('⚠ Prijavi se za čuvanje na server'); return; }
  const btn = document.getElementById('refkarta-save-btn');
  if (btn) { btn.disabled = true; btn.innerHTML = '<svg class="ic"><use href="#ic-cekanje"/></svg> Snimam...'; }
  try {
    const resp = await fetch(_refImg.src);
    const blob = await resp.blob();
    const ext  = blob.type.includes('png') ? 'png' : blob.type.includes('webp') ? 'webp' : 'jpg';
    const path = `${sbUser.id}/${Date.now()}.${ext}`;
    const { error: upErr } = await sb.storage.from('ref-karte').upload(path, blob, { contentType: blob.type, upsert: false });
    if (upErr) throw upErr;
    const name = (await _dlgPrompt('Naziv referentne slike:', 'Karta ' + new Date().toLocaleDateString('bs-BA'), { title: 'Sačuvaj ref. sliku' })) || 'Karta';
    const { error: dbErr } = await sb.from('ref_karte').insert({
      user_id: sbUser.id, name, storage_path: path,
      bounds: _refBounds, opacity: parseInt(document.getElementById('refkarta-opa').value) / 100,
      control_points: _refCPs.length >= 2 ? _refCPs : null
    });
    if (dbErr) throw dbErr;
    showToast('✓ Slika sačuvana na server');
    _refRepoLoad();
    if (btn) { btn.style.display = 'none'; }
  } catch(e) {
    showToast('⚠ Greška: ' + e.message);
    if (btn) { btn.disabled = false; btn.innerHTML = '<svg class="ic"><use href="#ic-server"/></svg> Sačuvaj na server'; }
  }
}

// ─── Precizno poravnanje na granicu odjela ────────────────────────────────────
//
// Algoritam:
//  1. Parsira binarnu sliku (isti prag tame kao za detekciju)
//  2. Sampuje KML poligon na 100 ravnomjernih tačaka
//  3. Svaku KML tačku konvertuje u piksel-koordinate (gruba aproksimacija)
//  4. Za svaku tačku traži najbliži tamni piksel unutar search radiusa
//  5. Median svih offset-a = translacijska korekcija
//  6. Least-squares slope u X i Y = korekcija razmjere
//  7. Ažurira _refBounds → precizno poravnanje

function refKartaAlign() {
  if (!_refImg) { showToast('⚠ Učitaj sliku karte!'); return; }
  const odjel = graniceOdjeli.find(o => o.ring && o.ring.length > 3)
              || graniceOdjeli[0];
  if (!odjel) { showToast('⚠ Treba učitan KML odjel s poligonom'); return; }
  if (!_refBounds) { refKartaFitOdjel(); if (!_refBounds) return; }

  const btn = document.getElementById('refkarta-align-btn');
  btn.innerHTML = '<svg class="ic"><use href="#ic-cekanje"/></svg> Poravnavam...'; btn.disabled = true;
  setTimeout(() => {
    try { _doAlign(odjel); }
    catch(e) { showToast('⚠ Greška: ' + e.message); console.error(e); }
    finally { btn.innerHTML = '<svg class="ic"><use href="#ic-meta"/></svg> Precizno poravnaj na granicu odjela'; btn.disabled = false; }
  }, 60);
}

function _doAlign(odjel) {
  // 1. Downsample + binary image
  const MAX_W = 1400;
  const sc = Math.min(1, MAX_W / _refImg.width);
  const W = Math.round(_refImg.width * sc);
  const H = Math.round(_refImg.height * sc);
  const cv = document.createElement('canvas');
  cv.width = W; cv.height = H;
  const ctx = cv.getContext('2d');
  ctx.drawImage(_refImg, 0, 0, W, H);
  const px = ctx.getImageData(0, 0, W, H).data;
  const thr = parseInt(document.getElementById('refkarta-thr').value);
  const bin = new Uint8Array(W * H);
  for (let i=0;i<W*H;i++){
    bin[i] = (0.299*px[i*4]+0.587*px[i*4+1]+0.114*px[i*4+2]) < thr ? 1 : 0;
  }

  // 2. Resample KML polygon to N evenly-spaced points
  const ring = odjel.ring || _boundsToRing(odjel.bounds);
  const N = 120;
  const sampled = _resampleRing(ring, N);

  // 3. Current transform: lat/lon → pixel
  const [[south, west], [north, east]] = _refBounds;
  const latSpan = north - south, lonSpan = east - west;
  const latToPy = (lat) => (north - lat) / latSpan * H;
  const lonToPx = (lon) => (lon - west)  / lonSpan * W;

  // 4. For each sampled KML point, find nearest dark pixel in image
  const SR = Math.max(20, Math.round(Math.min(W, H) * 0.08)); // search radius 8%
  const matches = [];
  for (const [lat, lon] of sampled) {
    const ex = lonToPx(lon), ey = latToPy(lat);
    const x0=Math.max(0,Math.round(ex-SR)), x1=Math.min(W-1,Math.round(ex+SR));
    const y0=Math.max(0,Math.round(ey-SR)), y1=Math.min(H-1,Math.round(ey+SR));
    let bDist = SR+1, bx=ex, by=ey;
    for (let y=y0;y<=y1;y++) for (let x=x0;x<=x1;x++) {
      if (!bin[y*W+x]) continue;
      const d = Math.hypot(x-ex, y-ey);
      if (d < bDist) { bDist=d; bx=x; by=y; }
    }
    if (bDist <= SR) matches.push({ ex, ey, bx, by });
  }

  if (matches.length < 8) {
    showToast(`⚠ Premalo podudaranja (${matches.length}/${N}) — smanji prag tame ili fituj ručno`);
    return;
  }

  // 5. Median translation
  const oxArr = matches.map(m => m.bx - m.ex);
  const oyArr = matches.map(m => m.by - m.ey);
  const tx = _median(oxArr);
  const ty = _median(oyArr);

  // 6. Scale correction using linear regression (offset vs position)
  //    expected_actual = scale * expected_from_bounds
  //    bx = scale_x * ex + shift_x  → solve by least squares
  const scale_x = _lsSlope(matches.map(m=>m.ex), matches.map(m=>m.bx));
  const scale_y = _lsSlope(matches.map(m=>m.ey), matches.map(m=>m.by));
  // Clamp scale to reasonable range to avoid degenerate fits
  const sx = Math.max(0.85, Math.min(1.15, scale_x));
  const sy = Math.max(0.85, Math.min(1.15, scale_y));

  // 7. Compute corrected bounds
  // New transform: pixel → geo
  //   lon(px) = west' + px / (W * sx) * lonSpan
  //   lat(py) = north' - py / (H * sy) * latSpan
  // With translation correction (tx, ty are in "scaled image" pixels):
  const new_west  = west  - tx / W * lonSpan;
  const new_east  = new_west + lonSpan / sx;
  const new_north = north + ty / H * latSpan;
  const new_south = new_north - latSpan / sy;

  _refBounds = [[new_south, new_west], [new_north, new_east]];
  _placeRefOverlay();

  const residuals = matches.map(m =>
    Math.hypot(m.bx - (m.ex*sx + tx), m.by - (m.ey*sy + ty))
  );
  const meanRes = Math.round(_mean(residuals));
  const mReal = Math.round(meanRes / sc / W * lonSpan * 111320); // approx metres
  showToast(`✓ Poravnato! ${matches.length}/${N} tač., greška ~${meanRes}px (~${mReal}m)`);
}

// Helpers
function _boundsToRing(b) {
  // Convert L.latLngBounds to [[lat,lon]] ring
  return [[b.getNorth(),b.getWest()],[b.getNorth(),b.getEast()],
          [b.getSouth(),b.getEast()],[b.getSouth(),b.getWest()]];
}
function _resampleRing(ring, n) {
  const segs = ring.map((p,i) => {
    const q = ring[(i+1)%ring.length];
    return { a:p, b:q, d:Math.hypot(q[0]-p[0], q[1]-p[1]) };
  });
  const total = segs.reduce((s,sg)=>s+sg.d, 0);
  const step = total / n;
  const result = [];
  let cumDist = 0, si = 0;
  for (let i=0;i<n;i++) {
    const target = i * step;
    while (si < segs.length-1 && cumDist + segs[si].d < target) { cumDist += segs[si].d; si++; }
    const t = segs[si].d > 1e-10 ? (target - cumDist) / segs[si].d : 0;
    const {a,b} = segs[si];
    result.push([a[0]+t*(b[0]-a[0]), a[1]+t*(b[1]-a[1])]);
  }
  return result;
}
function _median(arr) {
  const s = [...arr].sort((a,b)=>a-b);
  const m = Math.floor(s.length/2);
  return s.length%2 ? s[m] : (s[m-1]+s[m])/2;
}
function _mean(arr) { return arr.reduce((s,v)=>s+v,0)/arr.length; }
function _lsSlope(xs, ys) {
  // slope = cov(x,y) / var(x)
  const n = xs.length;
  const mx = _mean(xs), my = _mean(ys);
  let cov=0, vx=0;
  for (let i=0;i<n;i++) { cov+=(xs[i]-mx)*(ys[i]-my); vx+=(xs[i]-mx)**2; }
  return vx < 1e-10 ? 1 : cov/vx;
}

// ─── Line Detection Pipeline ───────────────────────────────────────────────

function ReferenceVlakePreset(type) {
 document.getElementById('refkarta-detect-mode').value=type==='blue'?'color':'dark';
 if(type==='blue')document.getElementById('refkarta-detect-color').value='#1e40af';
 document.getElementById('refkarta-bold').value='0';document.getElementById('refkarta-bold-val').textContent='sve';_refDetModeChanged();
}
function _refDetModeChanged() {
  const mode = document.getElementById('refkarta-detect-mode').value;
  document.getElementById('refkarta-dark-opts').style.display = mode === 'dark' ? '' : 'none';
  document.getElementById('refkarta-color-opts').style.display = mode === 'color' ? '' : 'none';
}

let _refColorPickActive = false;
function _refPickColorFromMap() {
  if (!_refImg || !_refBounds) { showToast('⚠ Postavi kartu na mapu!'); return; }
  _refColorPickActive = true;
  showToast('💧 Klikni na boju vlake na karti...');
  map.getContainer().style.cursor = 'crosshair';
  map.once('click', function(e) {
    _refColorPickActive = false;
    map.getContainer().style.cursor = '';
    const p=_refLatLngToImgPx(e.latlng);
    if(!p||p.imgX<0||p.imgY<0||p.imgX>=_refImg.width||p.imgY>=_refImg.height){showToast('Klikni unutar slike!');return;}
    const px=p.imgX,py=p.imgY;
    const c = document.createElement('canvas'); c.width = 1; c.height = 1;
    const cx = c.getContext('2d');
    cx.drawImage(_refImg, px, py, 1, 1, 0, 0, 1, 1);
    const d = cx.getImageData(0, 0, 1, 1).data;
    const hex = '#' + ((1<<24)|(d[0]<<16)|(d[1]<<8)|d[2]).toString(16).slice(1);
    document.getElementById('refkarta-detect-color').value = hex;
    showToast('✓ Boja uzeta: ' + hex);
  });
}

async function refKartaRunDetect() {
  if (!_refImg || !_refBounds) { showToast('⚠ Postavi kartu na mapu!'); return; }
  const btn = document.getElementById('refkarta-detect-btn');
  btn.innerHTML = '<svg class="ic"><use href="#ic-cekanje"/></svg> Detektujem...'; btn.disabled = true;
  const mode = document.getElementById('refkarta-detect-mode').value;
  const threshold = parseInt(document.getElementById('refkarta-thr').value);
  const minLen    = parseInt(document.getElementById('refkarta-minlen').value);
  const boldPasses = parseInt(document.getElementById('refkarta-bold').value) || 0;
  const joinPx     = parseInt(document.getElementById('refkarta-join').value) || 0;
  let targetColor = null, colorTol = 70;
  if (mode === 'color') {
    const hex = document.getElementById('refkarta-detect-color').value;
    targetColor = [parseInt(hex.slice(1,3),16), parseInt(hex.slice(3,5),16), parseInt(hex.slice(5,7),16)];
    colorTol = parseInt(document.getElementById('refkarta-color-tol').value);
  }
  setTimeout(async () => {
    try { await _refKartaDoDetect(threshold, minLen, mode, targetColor, colorTol, boldPasses, joinPx); }
    catch(err) { document.getElementById('refkarta-detect-status').textContent=err.message;showToast('Detekcija: '+err.message); }
    finally { btn.innerHTML = '<svg class="ic"><use href="#ic-trazi"/></svg> Detektuj vlake uz T + broj'; btn.disabled = false; }
  }, 60);
}

let _refDetectedLines = [];

function _colorDistRGB(r1, g1, b1, r2, g2, b2) {
  return Math.sqrt((r1-r2)**2 + (g1-g2)**2 + (b1-b2)**2);
}

async function _refKartaDoDetect(threshold,minLen,mode,targetColor,colorTol,boldPasses,joinPx) {
  await ReferenceVlake.detect({threshold,minLength:minLen,mode,color:targetColor,tolerance:colorTol,bold:boldPasses,join:joinPx});
}

// Zadrži samo DEBLJE poteze (ručno crtane vlake), izbaci tanke štampane linije.
// Erodira `passes` puta u kopiju (4-susjedstvo); komponenta u bin[] se zadrži
// samo ako ima bar jedan preživjeli ("srž") piksel — tanke linije (1-2px:
// izohipse, tekst) potpuno nestanu erozijom, deblji potezi olovke ostaju.
function _refBoldFilter(bin, W, H, passes) {
  const core = bin.slice();
  const tmp = new Uint8Array(W * H);
  for (let p = 0; p < passes; p++) {
    for (let y = 0; y < H; y++) {
      for (let x = 0; x < W; x++) {
        const i = y * W + x;
        if (!core[i]) { tmp[i] = 0; continue; }
        const up = y > 0 ? core[i - W] : 0, dn = y < H - 1 ? core[i + W] : 0;
        const lf = x > 0 ? core[i - 1] : 0, rt = x < W - 1 ? core[i + 1] : 0;
        tmp[i] = (up && dn && lf && rt) ? 1 : 0;
      }
    }
    core.set(tmp);
  }
  const labels = new Int32Array(W * H);
  let nl = 1;
  for (let s = 0; s < W * H; s++) {
    if (!bin[s] || labels[s]) continue;
    const q = [s]; labels[s] = nl; let head = 0, hasCore = false;
    const comp = [s];
    while (head < q.length) {
      const idx = q[head++];
      if (core[idx]) hasCore = true;
      const cx = idx % W, cy = (idx - cx) / W;
      for (let dy = -1; dy <= 1; dy++) {
        for (let dx = -1; dx <= 1; dx++) {
          if (!dx && !dy) continue;
          const nx = cx + dx, ny = cy + dy;
          if (nx >= 0 && nx < W && ny >= 0 && ny < H) {
            const ni = ny * W + nx;
            if (bin[ni] && !labels[ni]) { labels[ni] = nl; q.push(ni); comp.push(ni); }
          }
        }
      }
    }
    if (!hasCore) for (const ci of comp) bin[ci] = 0;
    nl++;
  }
}

// Spoji krajeve traceovanih putanja koji su blizu (< maxD px) I približno u
// istom smjeru (kut između pravaca krajeva < ~35°) — vlaka prekinuta na presjeku
// postaje jedna neprekinuta linija. Greedy: uvijek spoji najbliži validan par.
function _refJoinPaths(paths, maxD) {
  paths = paths.filter(p => p.length >= 2).map(p => p.slice());
  const _ang = (a, b) => Math.atan2(b[1] - a[1], b[0] - a[0]);
  const _angDiff = (x, y) => { let d = Math.abs(x - y) % (2 * Math.PI); if (d > Math.PI) d = 2 * Math.PI - d; return d; };
  const MAXANG = 35 * Math.PI / 180;
  let merged = true, guard = 0;
  while (merged && guard++ < 2000) {
    merged = false;
    let best = null, bestD = maxD + 1;
    for (let i = 0; i < paths.length; i++) {
      for (let j = i + 1; j < paths.length; j++) {
        const A = paths[i], B = paths[j];
        // 4 kombinacije kraj-kraj: A.start/A.end × B.start/B.end
        const ends = [
          { ai: 0, bi: 0 }, { ai: 0, bi: B.length - 1 },
          { ai: A.length - 1, bi: 0 }, { ai: A.length - 1, bi: B.length - 1 }
        ];
        for (const e of ends) {
          const pa = A[e.ai], pb = B[e.bi];
          const d = Math.hypot(pa[0] - pb[0], pa[1] - pb[1]);
          if (d >= bestD) continue;
          // Smjer A na kraju e.ai i B na kraju e.bi — moraju biti suprotni (nastavak)
          const aInner = A[e.ai === 0 ? Math.min(1, A.length - 1) : A.length - 2];
          const bInner = B[e.bi === 0 ? Math.min(1, B.length - 1) : B.length - 2];
          const angA = _ang(aInner, pa);   // ulazni smjer u spojnu tačku A
          const angB = _ang(pb, bInner);   // izlazni smjer iz spojne tačke B
          if (_angDiff(angA, angB) > MAXANG) continue;
          best = { i, j, ...e }; bestD = d;
        }
      }
    }
    if (best) {
      const A = paths[best.i], B = paths[best.j];
      const aStart = best.ai === 0, bEnd = best.bi === B.length - 1;
      let a2 = aStart ? A.slice().reverse() : A;   // spojna tačka A na kraj
      let b2 = bEnd ? B.slice().reverse() : B;      // spojna tačka B na početak
      const joined = a2.concat(b2);
      paths.splice(Math.max(best.i, best.j), 1);
      paths.splice(Math.min(best.i, best.j), 1);
      paths.push(joined);
      merged = true;
    }
  }
  return paths;
}

// Remove small connected components from binary image (filters text, numbers, kote)
function _refRemoveSmallComponents(bin, W, H, minArea) {
  const labels = new Int32Array(W * H);
  let nextLabel = 1;
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      if (!bin[y*W+x] || labels[y*W+x]) continue;
      const queue = [y*W+x];
      labels[y*W+x] = nextLabel;
      let head = 0;
      while (head < queue.length) {
        const idx = queue[head++];
        const cx = idx % W, cy = (idx - cx) / W;
        for (let dy = -1; dy <= 1; dy++) {
          for (let dx = -1; dx <= 1; dx++) {
            if (!dx && !dy) continue;
            const nx = cx+dx, ny = cy+dy;
            if (nx >= 0 && nx < W && ny >= 0 && ny < H) {
              const ni = ny*W+nx;
              if (bin[ni] && !labels[ni]) { labels[ni] = nextLabel; queue.push(ni); }
            }
          }
        }
      }
      if (queue.length < minArea) {
        for (let i = 0; i < queue.length; i++) bin[queue[i]] = 0;
      }
      nextLabel++;
    }
  }
}

// Zhang-Suen thinning algorithm (modifies bin[] in place)
function _zhangSuenThin(bin, W, H) {
  const I = (x, y) => (x>=0&&x<W&&y>=0&&y<H) ? bin[y*W+x] : 0;
  let changed = true, iter = 0;
  while (changed && iter++ < 60) {
    changed = false;
    for (let pass = 0; pass < 2; pass++) {
      const rm = [];
      for (let y = 1; y < H-1; y++) {
        for (let x = 1; x < W-1; x++) {
          if (!bin[y*W+x]) continue;
          // 8-neighbours in clockwise order: P2..P9
          const n = [I(x,y-1),I(x+1,y-1),I(x+1,y),I(x+1,y+1),
                     I(x,y+1),I(x-1,y+1),I(x-1,y),I(x-1,y-1)];
          const B = n.reduce((s,v)=>s+v, 0);
          if (B < 2 || B > 6) continue;
          // Count 0→1 transitions around the ring
          let A = 0;
          for (let k = 0; k < 8; k++) if (n[k]===0 && n[(k+1)%8]===1) A++;
          if (A !== 1) continue;
          if (pass===0 ? (n[0]*n[2]*n[4]!==0 || n[2]*n[4]*n[6]!==0)
                       : (n[0]*n[2]*n[6]!==0 || n[0]*n[4]*n[6]!==0)) continue;
          rm.push(y*W+x);
        }
      }
      if (rm.length) { rm.forEach(i => { bin[i]=0; }); changed = true; }
    }
  }
}

// Trace skeleton into ordered polylines; return array of [[x,y], ...]
function _traceSkeleton(bin, W, H, minLen) {
  const DX = [-1,0,1,-1,1,-1,0,1];
  const DY = [-1,-1,-1,0,0,1,1,1];
  const visited = new Uint8Array(W * H);
  const paths = [];

  // Count skeleton neighbours
  function nbCount(x, y) {
    let c = 0;
    for (let d=0;d<8;d++){const nx=x+DX[d],ny=y+DY[d];if(nx>=0&&nx<W&&ny>=0&&ny<H&&bin[ny*W+nx])c++;}
    return c;
  }

  // Trace one path from (sx,sy) following unvisited skeleton neighbours
  function tracePath(sx, sy) {
    const path = [];
    const stack = [[sx, sy]];
    visited[sy*W+sx] = 1;
    while (stack.length) {
      const [cx, cy] = stack.pop();
      path.push([cx, cy]);
      // Prefer to follow in order (greedy, one branch)
      for (let d=0; d<8; d++) {
        const nx = cx+DX[d], ny = cy+DY[d];
        if (nx>=0&&nx<W&&ny>=0&&ny<H&&bin[ny*W+nx]&&!visited[ny*W+nx]) {
          visited[ny*W+nx] = 1;
          stack.push([nx, ny]);
          break; // follow one branch at a time (DFS-like)
        }
      }
    }
    return path;
  }

  // Start tracing from endpoints first (degree-1 pixels), then junctions
  for (let pass=0; pass<2; pass++) {
    for (let y=1; y<H-1; y++) {
      for (let x=1; x<W-1; x++) {
        if (!bin[y*W+x] || visited[y*W+x]) continue;
        const nb = nbCount(x,y);
        if (pass===0 ? nb!==1 : nb===0) continue;
        const path = tracePath(x, y);
        if (path.length >= minLen) paths.push(_dpSimplify2D(path, 2.5));
      }
    }
  }
  return paths;
}

// Douglas-Peucker simplification for [x,y] point arrays
function _dpSimplify2D(pts, eps) {
  if (pts.length <= 2) return pts;
  const [x1,y1]=pts[0], [x2,y2]=pts[pts.length-1];
  const len = Math.hypot(x2-x1, y2-y1);
  let maxD=0, maxI=0;
  for (let i=1;i<pts.length-1;i++) {
    const [x,y]=pts[i];
    const d = len<0.001 ? Math.hypot(x-x1,y-y1)
      : Math.abs((y2-y1)*x-(x2-x1)*y+x2*y1-y2*x1)/len;
    if(d>maxD){maxD=d;maxI=i;}
  }
  if (maxD>eps) {
    const L=_dpSimplify2D(pts.slice(0,maxI+1),eps);
    const R=_dpSimplify2D(pts.slice(maxI),eps);
    return [...L.slice(0,-1),...R];
  }
  return [pts[0],pts[pts.length-1]];
}

// ═══════════════════════════════════════════════════════════════════════════
// === KML ===
function dropK(e) { e.preventDefault(); document.getElementById('kml-drop').classList.remove('over'); [...e.dataTransfer.files].filter(f=>f.name.endsWith('.kml')).forEach(ldK); }
function fileK(e) { [...e.target.files].forEach(ldK); e.target.value=''; }
function ldK(file) {
  const owner=sbUser?.id;
  return file.text().then(content=>_localLayerKml(file.name,content,owner)).catch(e=>showToast('⚠ Greška KML: '+e.message));
}
function pkml(doc, col, op) {
  op = op ?? 0.9;
  const g = L.featureGroup();
  g.on('click', _kmlGrpClick);   // tačke: jedan listener na grupi (vidi pkmlStyled)
  g.on('mouseover', _kmlGrpTip);
  const tag1 = (el, t) => el.getElementsByTagName(t)[0];
  const pms = doc.getElementsByTagName('Placemark');
  for (let pmIndex = 0; pmIndex < pms.length; pmIndex++) {
    const pm = pms[pmIndex];
    const name = tag1(pm, 'name')?.textContent?.trim() || '';
    const desc = tag1(pm, 'description')?.textContent?.trim() || '';
    const extData = pm.getElementsByTagName('ExtendedData').length ? _parseKmlExtData(pm) : {};
    pm.querySelectorAll('Polygon').forEach(pg => {
      const cs = pcs(pg.querySelector('outerBoundaryIs coordinates,coordinates')?.textContent);
      if (cs.length > 2) {
        // fill:true čuva hit-test i kad je površina potpuno prozirna.
        const holes = [...pg.querySelectorAll('innerBoundaryIs coordinates')].map(c=>pcs(c.textContent)).filter(r=>r.length>2);
        const l = L.polygon(holes.length?[cs,...holes]:cs, {color:col, weight:2, opacity:op, fill:true, fillOpacity:0});
        l._kmlIsPolygon = true;
        l._kmlPmIndex=pmIndex;l._kmlName = name; l._kmlDesc = desc; l._kmlExtData = extData;
        if (name) l.bindTooltip(_escHtml(name), {sticky:true});
        _bindKmlPopup(l);
        l.addTo(g);
      }
    });
    pm.querySelectorAll('LineString').forEach(ls => {
      const cs = pcs(ls.querySelector('coordinates')?.textContent);
      if (cs.length > 1) {
        const l = L.polyline(cs, {color:col, weight:2, dashArray:'6,4', opacity:op});
        l._kmlPmIndex=pmIndex;l._kmlName = name; l._kmlDesc = desc; l._kmlExtData = extData;
        if (name) l.bindTooltip(_escHtml(name), {sticky:true});
        _bindKmlPopup(l);
        l.addTo(g);
      }
    });
    for (const pt of pm.getElementsByTagName('Point')) {
      const cs = pcs(tag1(pt, 'coordinates')?.textContent);
      if (cs.length > 0) {
        const m = L.circleMarker(cs[0], {radius:5, color:col, fillColor:col, opacity:op, fillOpacity:op});
        m._kmlIsPoint = true;
        m._kmlPmIndex=pmIndex;m._kmlName = name; m._kmlDesc = desc; m._kmlExtData = extData;
        m.addTo(g);
      }
    }
  }
  return g;
}
function pcs(s) {
  if(!s) return [];
  return s.trim().split(/\s+/).map(c=>{const p=c.split(',');return p.length>=2?[parseFloat(p[1]),parseFloat(p[0])]:null;}).filter(Boolean);
}

function _parseKmlExtData(pm) {
  const ext = {};
  pm.querySelectorAll('ExtendedData Data, ExtendedData SimpleData').forEach(d => {
    const key = d.getAttribute('name') || d.getAttribute('key') || '';
    const val = d.querySelector('value')?.textContent?.trim() || d.textContent?.trim() || '';
    if (key) ext[key] = val;
  });
  pm.querySelectorAll('ExtendedData SchemaData SimpleData').forEach(d => {
    const key = d.getAttribute('name') || '';
    if (key) ext[key] = d.textContent?.trim() || '';
  });
  return ext;
}

// Otvara info-popup za jedan KML/SHP feature. Izdvojeno iz _bindKmlPopup jer se
// isti popup mora moći otvoriti i "izvana" — iz map.on('click') fallback-a
// (_kmlHitTest), kad DOM klik uopšte ne stigne do sloja (vidi napomenu tamo).
function _kmlOpenPopup(layer, latlng) {
  if(window.DepartmentReport?.isDrawing()){DepartmentReport.addPoint(latlng);return;}
  if(_dozDrawType==='__boundary__'){if(!_dozDrawEnabled)dozAddDrawPoint(latlng);return;}
  if (_dozKmlSelMode) { const target=window.DoznakaProjectBoundary?.allows(layer)?layer:_kmlHitTest(latlng,true);if(target)_dozKmlSelToggle(target);return; }
  if(window.DepartmentReport?.openAt(latlng))return;
  const uid = '_kp_' + Math.random().toString(36).slice(2, 8);
  layer._kmlPopupId = uid;
  L.popup({ maxWidth: 300, minWidth: 200, keepInView: true, autoPanPaddingTopLeft: [12,56], autoPanPaddingBottomRight: [12,12], className: 'kml-info-popup' })
    .setLatLng(latlng)
    .setContent(_kmlPopupHtml(layer, uid))
    .openOn(map);
}

// Jedan zajednički handler za tačke: KML sa desetinama hiljada tačaka inače pravi
// zatvaranje + dva listenera po tački (izmjereno: ~0,5 s od 1,8 s građenja za 50 000).
function _kmlPointClick(e) {
  L.DomEvent.stopPropagation(e);
  _kmlOpenPopup(e.target, e.latlng);
}
// Grupni handleri za tačke (vidi pkmlStyled). Tooltip se pravi tek pri prvom prelasku
// preko tačke — bindTooltip po svakoj od 50 000 tačaka je najskuplji pojedinačni dio.
function _kmlGrpClick(e) {
  const l = e.layer;
  if (!l || !l._kmlIsPoint) return;
  L.DomEvent.stopPropagation(e);
  _kmlOpenPopup(l, e.latlng);
}
function _kmlGrpTip(e) {
  const l = e.layer;
  if (!l || !l._kmlIsPoint || l._kmlTipDone || !l._kmlName) return;
  l._kmlTipDone = true;
  l.bindTooltip(_escHtml(l._kmlName), { sticky: true });
  l.openTooltip(e.latlng);
}

function _bindKmlPopup(layer) {
  if (layer._kmlIsPoint) { layer.on('click', _kmlPointClick); return; }
  const _onClick = function(e) {
    L.DomEvent.stopPropagation(e);
    _kmlOpenPopup(layer, e.latlng);
  };
  layer.on('click', _onClick);
  layer.on('add',()=>{if(layer._kmlIsPolygon&&layer._path)layer._path.style.pointerEvents='all';});

  // KML granice/linije su tanke i često isprekidane — bez šireg nevidljivog
  // hit-sloja tap prstom na terenu skoro nikad ne pogodi samu liniju (isti
  // problem i rješenje kao attachPolyClick za vlaka linije, 24px "duh" sloj).
  // Poligoni (fillOpacity može biti 0, ali fill hit-test i dalje radi kroz
  // cijelu unutrašnjost) i tačke (već imaju radius) to ne trebaju.
  if (!layer._kmlIsPolygon && !layer._kmlIsPoint && layer.getLatLngs) {
    const hit = L.polyline(layer.getLatLngs(), {
      weight: 20, opacity: 0.001, color: '#000',
      pane: layer.options.pane, renderer: layer.options.renderer, interactive: true
    });
    layer.on('add',    () => { try { hit.addTo(map); } catch(e) {} });
    layer.on('remove', () => { try { map.removeLayer(hit); } catch(e) {} });
    if (layer._map) { try { hit.addTo(layer._map); } catch(e) {} }
    hit.on('click', _onClick);
  }
}

// ── Zašto KML klik treba fallback preko map.on('click') ──────────────────────
// Karta radi u canvas modu (preferCanvas:true). Svaki Leaflet canvas renderer je
// JEDAN <canvas> preko CIJELE karte i sam hvata DOM klik pa tek onda traži koji
// mu je sloj ispod prsta. Uvezeni KML/SHP crta se u podrazumijevanom canvas-u
// (overlayPane, z-index 400), a vlake u svom (_vlakeRenderer, pane 'vlakeLines',
// TAKOĐE z-index 400 — ali kasnije u DOM-u, dakle iznad). Čim u projektu postoji
// makar JEDNA vlaka, taj gornji canvas prekriva cijelu kartu i pokupi SVAKI klik
// — bez obzira gdje je vlaka stvarno nacrtana. Klik onda nikad ne stigne do
// KML canvas-a, pa `layer.on('click')` iz _bindKmlPopup nikad ne opali:
// uvezeni KML izgleda "mrtav" (tooltip na hover radi, klik ne radi). Isto važi
// i za pane 'tragMsrLines' (z-index 410) kad se izmjera/tragovi jednom nacrtaju.
// Isti razlog zašto vlake već imaju svoj proximity fallback niže u map.on('click').
//
// Rješenje: kad klik ipak dođe do mape (canvas renderer uvijek proslijedi klik
// mapi kad pod prstom nema NJEGOV sloj), sami provjerimo KML slojeve. Koristi se
// Leafletov vlastiti `_containsPoint` gdje postoji — ista semantika kao da je
// canvas sam pogodio sloj — uz tolerancije za prst na telefonu.
function _kmlHitTest(latlng, onlyPolygons) {
  if (!map || !kmlLs.length) return null;
  const lp  = map.latLngToLayerPoint(latlng);
  const cp  = map.latLngToContainerPoint(latlng);
  const TOL_LINE = 20, TOL_POINT = 16, TOL_RING = 12;
  let best = null;

  // Unazad: kasnije uvezeni sloj je "iznad" i ima prednost, isto kao u canvasu.
  for (let i = kmlLs.length - 1; i >= 0; i--) {
    const k = kmlLs[i];
    if (!k || !k.grp || (k.vis === false && (typeof _dozKmlSelMode==='undefined'||!_dozKmlSelMode))) continue;
    if (!map.hasLayer(k.grp)) continue;
    // SHP slojevi su ugniježđeni (featureGroup → L.geoJSON grupa → path), pa se
    // silazi kroz grupe dok se ne dođe do samih geometrija.
    const kids = [];
    try {
      const walk = grp => grp.eachLayer(l => (l.eachLayer && l._kmlName === undefined) ? walk(l) : kids.push(l));
      walk(k.grp);
    } catch(e) { continue; }
    for (let j = kids.length - 1; j >= 0; j--) {
      const l = kids[j];
      if (l._kmlName === undefined) continue;   // labela ili nevezani sloj
      if (onlyPolygons && !l._kmlIsPolygon) continue;
      if (typeof _dozKmlSelMode!=='undefined' && _dozKmlSelMode && typeof window!=='undefined' && window.DoznakaProjectBoundary && !DoznakaProjectBoundary.allows(l)) continue;

      if (l._kmlIsPoint) {
        if (onlyPolygons) continue;
        try {
          const d = cp.distanceTo(map.latLngToContainerPoint(l.getLatLng()));
          if (d <= TOL_POINT) return l;   // tačka je najsitniji cilj — odmah uzmi
        } catch(e) {}
        continue;
      }

      if (l._kmlIsPolygon) {
        let inside = false;
        try { inside = !!(l._containsPoint && l._containsPoint(lp)); } catch(e) {}
        if (!inside && typeof turf!=='undefined' && l.getBounds?.().contains(latlng)) {
          try { inside=turf.booleanPointInPolygon(turf.point([latlng.lng,latlng.lat]),l.toGeoJSON()); } catch(e) {}
        }
        // Rezerva: prazan (nepopunjen) poligon u nekim slučajevima ne odgovara na
        // _containsPoint — provjeri i blizinu same granice.
        if (!inside) {
          try {
            if (l.getBounds().pad(0.02).contains(latlng) &&
                _kmlRingDistPx(l.getLatLngs(), cp) <= TOL_RING) inside = true;
          } catch(e) {}
        }
        if (inside && !best) best = l;      // poligon je "najslabiji" pogodak
        continue;
      }

      // Linija — tolerancija u pikselima (isti prag kao nevidljivi hit-sloj)
      try {
        if (_kmlRingDistPx(l.getLatLngs(), cp) <= TOL_LINE) return l;
      } catch(e) {}
    }
  }
  return best;
}

// Najmanja udaljenost (px) od tačke do bilo kojeg segmenta (ugniježđeni nizovi
// latlng-ova: linija, prsten poligona, multi-geometrija).
function _kmlRingDistPx(latlngs, cp) {
  if (!latlngs || !latlngs.length) return Infinity;
  if (Array.isArray(latlngs[0])) {
    let m = Infinity;
    for (const sub of latlngs) m = Math.min(m, _kmlRingDistPx(sub, cp));
    return m;
  }
  let m = Infinity, prev = null;
  for (const ll of latlngs) {
    const p = map.latLngToContainerPoint(ll);
    if (prev) m = Math.min(m, _distToSegPx(cp, prev, p));
    prev = p;
  }
  return m;
}

function _kmlPopupHtml(layer, uid) { return _layerPopupHtml(layer,uid); }

function _escAttr(s) { return (s||'').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/'/g,'&#39;').replace(/</g,'&lt;'); }

function _kmlPopFindLayer(uid) {
  let found = null;
  kmlLs.forEach(kl => {
    if (!kl.grp) return;
    const walk=g=>g.eachLayer(l=>{if(l._kmlPopupId===uid)found=l;else if(l.eachLayer)walk(l);});walk(kl.grp);
  });
  return found;
}

function _kmlPopFindIdx(uid) {
  for (let i = 0; i < kmlLs.length; i++) {
    if (!kmlLs[i].grp) continue;
    let hit = false;
    const walk=g=>g.eachLayer(l=>{if(l._kmlPopupId===uid)hit=true;else if(l.eachLayer)walk(l);});walk(kmlLs[i].grp);
    if (hit) return i;
  }
  return -1;
}

function _kmlPopEditName(uid, el) {
  _kmlPopEditStart(uid);
  setTimeout(() => document.getElementById(uid + '-name-in')?.focus(), 50);
}

function _kmlPopEditStart(uid) {
  const ed = document.getElementById(uid + '-edit');
  if (ed) {ed.style.display = '';_layerPopupLayout();}
}

function _kmlPopCancel(uid) {
  const ed = document.getElementById(uid + '-edit');
  if (ed) ed.style.display = 'none';
}

async function _kmlPopSave(uid) {
  const layer=_kmlPopFindLayer(uid),i=_kmlPopFindIdx(uid),k=kmlLs[i];
  if(!layer || !k || layer._saving)return;
  const newName=document.getElementById(uid+'-name-in')?.value?.trim()||'';
  const newDesc=document.getElementById(uid+'-desc-in')?.value?.trim()||'';
  layer._saving=true;
  try {
    if(!k._key)await _localLayerPatchFeature(k,layer._kmlPmIndex,newName,newDesc);
    const change=l=>{l._kmlName=newName;l._kmlDesc=newDesc;if(l.getTooltip?.())l.unbindTooltip();if(newName)l.bindTooltip(_escHtml(newName),{sticky:true});};
    if(!k._key){const walk=g=>g.eachLayer(l=>{if(l.eachLayer&&!l._kmlIsPolygon)walk(l);else if(l._kmlPmIndex===layer._kmlPmIndex)change(l);});walk(k.grp);}else change(layer);
    const article=document.getElementById(uid+'-nm')?.closest('.le-popup');
    if(article){const wrapper=document.createElement('div');wrapper.innerHTML=_layerPopupHtml(layer,uid);article.replaceWith(wrapper.firstElementChild);_layerPopupLayout();}
    _kmlPopCancel(uid);showToast(k._key?'Primijenjeno u ovom prikazu':'✓ Naziv i opis sačuvani u lokalnom fajlu');
  }catch(e){showToast('⚠ Izmjena nije sačuvana: '+e.message);}
  finally{layer._saving=false;}
}

function _kmlPopZoom(uid) {
  const layer = _kmlPopFindLayer(uid);
  if (!layer) return;
  if (layer.getBounds) {
    try { map.fitBounds(layer.getBounds(), { padding: [40, 40], maxZoom: 17 }); } catch(e) {}
  } else if (layer.getLatLng) {
    map.setView(layer.getLatLng(), 17);
  }
}

function _kmlPopStyleToggle(uid) {
  const el = document.getElementById(uid + '-style');
  if (!el) return;
  if (el.style.display === 'none') {
    el.style.display = '';
    const i = _kmlPopFindIdx(uid);
    if (i >= 0) el.innerHTML = _kmlPopStylePanel(uid, null, i);
    _layerPopupLayout();
  } else {
    el.style.display = 'none';
  }
}

function _kmlPopStylePanel(uid, layer, idx) { return _layerStyleControls(idx!==undefined?idx:_kmlPopFindIdx(uid)); }

function _kmlGrpHasPolygon(i) {
  let has=false;
  const walk=g=>g?.eachLayer?.(l=>{if(l._kmlIsPolygon)has=true;else if(l.eachLayer)walk(l);});
  walk(kmlLs[i]?.grp);return has;
}

function _kpSetCol(uid, i, c)    { setKmlColor(i, c);   _kpRefreshStyle(uid, i); }
function _kpSetDash(uid, i, d)   { setKmlDash(i, d);    _kpRefreshStyle(uid, i); }
function _kpSetWeight(uid, i, w) { setKmlWeight(i, parseFloat(w)); _kpRefreshStyle(uid, i); }
function _kpSetFill(uid, i, on)  {
  kmlLs[i].fill = on;
  const opts = document.getElementById(uid + '-fill-opts');
  if (opts) opts.style.display = on ? '' : 'none';
  applyKmlStyle(i); saveKmlStyles();
}
function _kpSetFillCol(uid, i, c) { kmlLs[i].fillCol = c; applyKmlStyle(i); saveKmlStyles(); _kpRefreshStyle(uid, i); }
function _kpSetFillPat(uid, i, p) { kmlLs[i].fillPattern = p; applyKmlStyle(i); saveKmlStyles(); _kpRefreshStyle(uid, i); }
function _kpSetFillOp(uid, i, v)  { kmlLs[i].fillOpacity = parseFloat(v); applyKmlStyle(i); saveKmlStyles(); }

function _kpRefreshStyle(uid, i) {
  const el = document.getElementById(uid + '-style');
  if (el && el.style.display !== 'none') el.innerHTML = _kmlPopStylePanel(uid, null, i);
}

// Centroid niza [lat,lng] koordinata (prosti prosjek — dovoljno za labele)
function _coordsCentroid(cs) {
  const n = cs.length;
  return cs.reduce((a, p) => [a[0] + p[0] / n, a[1] + p[1] / n], [0, 0]);
}

// Kreira L.marker sa permanentnom labelom na datoj poziciji
function _kmlLabelMarker(pos, text) {
  return L.marker(pos, {
    // _escHtml ovdje (ne na mjestu poziva) — text dolazi iz uvezenog KML/GeoJSON/.dbf
    // fajla, štiti oba pozivaoca odjednom (XSS preko <name>/atributa).
    icon: L.divIcon({ className: 'kml-label', html: `<div>${_escHtml(text)}</div>`, iconSize: null, iconAnchor: [0, 0] }),
    interactive: false, zIndexOffset: 100
  });
}

// Stilizovani KML parser — prima options za boju/debljinu/crtanje
function pkmlStyled(doc, opts) {
  const g = L.featureGroup();
  // Tačke dobijaju događaje JEDNIM listenerom na grupi (propagacija iz sloja), ne po
  // tački: za 50 000 tačaka to je ~0,4 s i desetine MB manje (tooltip + klik po tački).
  g.on('click', _kmlGrpClick);
  g.on('mouseover', _kmlGrpTip);
  // getElementsByTagName je višestruko brži od querySelector-a po Placemark-u.
  const tag1 = (el, t) => el.getElementsByTagName(t)[0];
  const pms = doc.getElementsByTagName('Placemark');
  for (let pi = 0; pi < pms.length; pi++) {
    const pm = pms[pi];
    const name = tag1(pm, 'name')?.textContent?.trim() || '';
    const desc = tag1(pm, 'description')?.textContent?.trim() || '';
    const extData = pm.getElementsByTagName('ExtendedData').length ? _parseKmlExtData(pm) : {};
    pm.querySelectorAll('Polygon').forEach(pg => {
      const cs = pcs(pg.querySelector('outerBoundaryIs coordinates,coordinates')?.textContent);
      if (cs.length > 2) {
        const holes=[...pg.querySelectorAll('innerBoundaryIs coordinates')].map(c=>pcs(c.textContent)).filter(r=>r.length>2);
        const polyOpts={...opts,fill:true,fillOpacity:opts.fill===false?0:(opts.fillOpacity??0)};
        const l=L.polygon(holes.length?[cs,...holes]:cs,polyOpts);
        l._kmlIsPolygon = true;
        l._kmlName = name; l._kmlDesc = desc; l._kmlExtData = extData;
        l.addTo(g);
        if (name) {
          l.bindTooltip(_escHtml(name), { sticky: true, opacity: 0.85 });
          _kmlLabelMarker(_coordsCentroid(cs), name).addTo(g);
        }
        _bindKmlPopup(l);
      }
    });
    pm.querySelectorAll('LineString').forEach(ls => {
      const cs = pcs(ls.querySelector('coordinates')?.textContent);
      if (cs.length > 1) {
        const l = L.polyline(cs, opts);
        l._kmlName = name; l._kmlDesc = desc; l._kmlExtData = extData;
        if (name) l.bindTooltip(_escHtml(name), { sticky: true, opacity: 0.85 });
        _bindKmlPopup(l);
        l.addTo(g);
      }
    });
    for (const pt of pm.getElementsByTagName('Point')) {
      const cs = pcs(tag1(pt, 'coordinates')?.textContent);
      if (cs.length > 0) {
        const m = L.circleMarker(cs[0], { radius: 4, color: opts.color, fillColor: opts.color, fillOpacity: 0.8 });
        m._kmlIsPoint = true;
        m._kmlName = name; m._kmlDesc = desc; m._kmlExtData = extData;
        m.addTo(g);
      }
    }
  }
  return g;
}

// Stilovi za odjele i odsjeke
const _ODJEL_STYLE  = { color: '#ffffff', weight: 3, opacity: 0.85, dashArray: '10 6' };
const _ODSJEK_STYLE = { color: '#fbbf24', weight: 1.5, opacity: 0.8 };


// ── KML/SHP style persistence ─────────────────────────────────────────────────
// Global styles (set by admin, stored in Supabase) — loaded on startup
let _globalKmlStyles = {};
// User overrides (personal, stored in localStorage)
const _KML_USER_STYLES_KEY = 'tvlake_kml_user_styles_v1';
const _LOCAL_KML_KEY = 'tvlake_local_kmls_v1';

async function loadGlobalKmlStyles() {
  try {
    const { data } = await sb.from('kml_styles_global').select('*');
    _globalKmlStyles = {};
    (data || []).forEach(r => { _globalKmlStyles[r.key] = r; });
  } catch(e) { console.warn('loadGlobalKmlStyles:', e); }
}

// Save admin global styles to Supabase
async function saveGlobalKmlStyles() {
  if (!sbProfile?.is_admin) return;
  const rows = kmlLs.filter(k => k._key).map(k => ({
    key: k._key, col: k.col, dash: k.dash,
    weight: k.weight, opacity: k.opacity ?? 0.9, vis: k.vis,
    updated_by: sbUser.id, updated_at: new Date().toISOString()
  }));
  if (rows.length === 0) { _graniceStatus('Nema slojeva za sačuvati.', 'warn'); return; }

  const btn = document.querySelector('#granice-list button[onclick="saveGlobalKmlStyles()"]');
  if (btn) { btn.disabled = true; btn.innerHTML = '<svg class="ic"><use href="#ic-cekanje"/></svg> Čuvam...'; }

  const { error } = await sb.from('kml_styles_global').upsert(rows, { onConflict: 'key' });

  if (btn) { btn.disabled = false; btn.innerHTML = '<svg class="ic"><use href="#ic-sacuvaj"/></svg> Sačuvaj kao default za sve'; }

  if (error) {
    console.error('saveGlobalKmlStyles error:', error);
    _graniceStatus('❌ Greška: ' + error.message, 'error');
    return;
  }
  rows.forEach(r => { _globalKmlStyles[r.key] = r; });
  localStorage.removeItem(_KML_USER_STYLES_KEY);
  _graniceStatus(`✓ Sačuvano ${rows.length} sloj${rows.length === 1 ? '' : 'a'} kao default za sve korisnike.`, 'ok');
  rndGraniceModal();
}

function _graniceStatus(msg, type) {
  const el = document.getElementById('granice-status');
  if (!el) return;
  el.textContent = msg;
  el.style.color = type === 'ok' ? '#4ade80' : type === 'error' ? '#f87171' : '#fbbf24';
  el.style.display = 'block';
  clearTimeout(el._t);
  el._t = setTimeout(() => { el.style.display = 'none'; }, 4000);
}

// Save user personal overrides to localStorage
function saveKmlStyles() {
  const stored=JSON.parse(localStorage.getItem(_KML_USER_STYLES_KEY)||'{}');
  const userMap=stored&&typeof stored==='object'&&!Array.isArray(stored)?{...stored}:{};
  kmlLs.forEach(k => {
    if (!k._key || k.grp===null || k._downloaded===false) return;
    userMap[k._key] = { col: k.col, dash: k.dash, weight: k.weight, opacity: k.opacity ?? 0.9, vis: k.vis,
      fill: k.fill || false, fillCol: k.fillCol || k.col, fillPattern: k.fillPattern || 'solid', fillOpacity: k.fillOpacity ?? 0.35,
      tag: k.tag || '', onlyPolygon: k.onlyPolygon===true };
  });
  localStorage.setItem(_KML_USER_STYLES_KEY, JSON.stringify(userMap));
  if(_localKmlSaveAll(false)===false)throw Error('Lokalni stil nije sačuvan');
}

// Reset a single layer back to admin global default
function resetLayerToGlobal(i) {
  const k = kmlLs[i];
  if (!k?._key) return;
  const g = _globalKmlStyles[k._key];
  if (!g) return;
  k.col = g.col; k.dash = g.dash; k.weight = g.weight; k.opacity = g.opacity; k.vis = g.vis !== false;
  applyKmlStyle(i);
  if (k.vis) k.grp.addTo(map); else map.removeLayer(k.grp);
  // Remove user override for this key
  try {
    const um = JSON.parse(localStorage.getItem(_KML_USER_STYLES_KEY) || '{}');
    delete um[k._key];
    localStorage.setItem(_KML_USER_STYLES_KEY, JSON.stringify(um));
  } catch {}
  rndGraniceModal();
}

function loadKmlStyleFor(key, defaults) {
  try {
    const global = _globalKmlStyles[key] || {};
    const userMap = JSON.parse(localStorage.getItem(_KML_USER_STYLES_KEY) || '{}');
    const user = userMap[key] || {};
    // Merge: defaults → global (admin) → user override
    const merged = { ...defaults, ...global, ...user };
    // Translate internal keys → Leaflet keys
    return _kmlStyleToLeaflet(merged);
  } catch { return defaults; }
}

// Prevodi interne ključeve (col/dash) u Leaflet ključeve (color/dashArray)
function _kmlStyleToLeaflet(s) {
  const out = { ...s };
  if (s.col)  { out.color = s.col; }
  if (s.dash !== undefined) { if (s.dash) out.dashArray = s.dash; else delete out.dashArray; }
  return out;
}

function applyKmlStyle(i) {
  const k = kmlLs[i];
  if (!k || !k.grp) return;
  const op = k.opacity ?? 0.9;
  const base = { color: k.col, weight: k.weight || 2, opacity: op };
  base.dashArray = k.dash || null;

  let patUrl=null,canvasPattern=null;
  if(k.fill&&(k.fillOpacity??.35)>0&&k.fillPattern&&k.fillPattern!=='solid'){
    patUrl=_ensureKmlPattern(i);canvasPattern=_kmlCanvasPattern(k);
  }

  const styleLayer = l => {
    // SHP GeoJSON i MultiGeometry sadrže dodatne grupe; stilizuj stvarne elemente.
    if (l.eachLayer && !l._kmlIsPolygon && !l._kmlIsPoint) { l.eachLayer(styleLayer); return; }
    if (!l.setStyle) return;
    const lo = {...base};
    if (l._kmlIsPolygon) {
      lo.fill = true; // hit-test cijele površine ostaje, neovisno o prozirnosti.
      lo.fillOpacity = k.fill ? (k.fillOpacity ?? 0.35) : 0;
      lo.fillColor = k.fillCol || k.col;
      if (k.fill && lo.fillOpacity > 0) {
        const pattern=l._renderer instanceof L.Canvas?canvasPattern:patUrl;
        if(pattern){lo.fillColor=pattern;lo.fillOpacity=1;}
      }
    } else {
      lo.fillColor = k.col;
      lo.fillOpacity = l._kmlIsPoint ? op : 0;
    }
    l.setStyle(lo);
    if(l._kmlIsPolygon&&l._path)l._path.style.pointerEvents='all';
  };
  k.grp?.eachLayer(styleLayer);
}

// Leaflet Canvas ne razumije SVG url(#pattern). Mali ponovljivi raster ostaje
// u postojećem rendereru, bez hiljada dodatnih SVG elemenata na terenu.
function _kmlCanvasPattern(k){
  const signature=JSON.stringify([k.fillPattern,k.fillCol||k.col,k.fillOpacity??.35]);
  if(k._canvasPatternKey===signature&&k._canvasPattern)return k._canvasPattern;
  const c=document.createElement('canvas');c.width=c.height=8;const ctx=c.getContext('2d');if(!ctx)return null;
  ctx.strokeStyle=ctx.fillStyle=k.fillCol||k.col;ctx.globalAlpha=k.fillOpacity??.35;ctx.lineWidth=k.fillPattern==='crosshatch'?1.2:1.8;
  const line=(x1,y1,x2,y2)=>{ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();};
  if(['diagonal','crosshatch'].includes(k.fillPattern)){line(0,8,8,0);line(-4,4,4,-4);line(4,12,12,4);}
  if(['diagonal-rev','crosshatch'].includes(k.fillPattern)){line(0,0,8,8);line(-4,4,4,12);line(4,-4,12,4);}
  if(k.fillPattern==='horizontal')line(0,4,8,4);
  if(k.fillPattern==='vertical')line(4,0,4,8);
  if(k.fillPattern==='dots'){ctx.beginPath();ctx.arc(4,4,1.6,0,Math.PI*2);ctx.fill();}
  k._canvasPatternKey=signature;k._canvasPattern=ctx.createPattern(c,'repeat');return k._canvasPattern;
}

function _ensureKmlPattern(i) {
  const k = kmlLs[i];
  if (!k || !k.grp) return null;
  const svg = document.querySelector('.leaflet-overlay-pane svg');
  if (!svg) return null;
  let defs = svg.querySelector('defs');
  if (!defs) { defs = document.createElementNS('http://www.w3.org/2000/svg','defs'); svg.prepend(defs); }
  const patId = k._patternId || (k._patternId = `kml-pat-${L.stamp(k.grp)}`);
  const old = defs.querySelector('#' + patId);
  if (old) old.remove();
  const col = k.fillCol || k.col;
  const pat = document.createElementNS('http://www.w3.org/2000/svg','pattern');
  pat.setAttribute('id', patId);
  pat.setAttribute('patternUnits','userSpaceOnUse');
  pat.setAttribute('width','8'); pat.setAttribute('height','8');
  pat.setAttribute('opacity',String(k.fillOpacity??.35));
  const inner = {
    'diagonal':     `<line x1="0" y1="8" x2="8" y2="0" stroke="${col}" stroke-width="1.8"/>
                     <line x1="-4" y1="4" x2="4" y2="-4" stroke="${col}" stroke-width="1.8"/>
                     <line x1="4" y1="12" x2="12" y2="4" stroke="${col}" stroke-width="1.8"/>`,
    'diagonal-rev': `<line x1="0" y1="0" x2="8" y2="8" stroke="${col}" stroke-width="1.8"/>
                     <line x1="-4" y1="4" x2="4" y2="12" stroke="${col}" stroke-width="1.8"/>
                     <line x1="4" y1="-4" x2="12" y2="4" stroke="${col}" stroke-width="1.8"/>`,
    'crosshatch':   `<line x1="0" y1="8" x2="8" y2="0" stroke="${col}" stroke-width="1.2"/>
                     <line x1="-4" y1="4" x2="4" y2="-4" stroke="${col}" stroke-width="1.2"/>
                     <line x1="4" y1="12" x2="12" y2="4" stroke="${col}" stroke-width="1.2"/>
                     <line x1="0" y1="0" x2="8" y2="8" stroke="${col}" stroke-width="1.2"/>
                     <line x1="-4" y1="4" x2="4" y2="12" stroke="${col}" stroke-width="1.2"/>
                     <line x1="4" y1="-4" x2="12" y2="4" stroke="${col}" stroke-width="1.2"/>`,
    'horizontal':   `<line x1="0" y1="4" x2="8" y2="4" stroke="${col}" stroke-width="1.8"/>`,
    'vertical':     `<line x1="4" y1="0" x2="4" y2="8" stroke="${col}" stroke-width="1.8"/>`,
    'dots':         `<circle cx="4" cy="4" r="1.6" fill="${col}"/>`,
  }[k.fillPattern] || '';
  if (!inner) return null;
  pat.innerHTML = inner;
  defs.appendChild(pat);
  return `url(#${patId})`;
}

function setKmlColor(i, col)    { kmlLs[i].col = col;               applyKmlStyle(i); saveKmlStyles(); rndGraniceModal(); }
function setKmlDash(i, dash)    { kmlLs[i].dash = dash;             applyKmlStyle(i); saveKmlStyles(); rndGraniceModal(); }
function setKmlWeight(i, w)     { kmlLs[i].weight = w;              applyKmlStyle(i); saveKmlStyles(); rndGraniceModal(); }
function setKmlOpacity(i, val)  { kmlLs[i].opacity = parseFloat(val); applyKmlStyle(i); saveKmlStyles(); rndGraniceModal(); }
function togK(i) {
  const k = kmlLs[i];
  if (!k.grp) return;   // server placeholder (nije preuzeto) — nema sloja za prikaz
  k.vis ? map.removeLayer(k.grp) : k.grp.addTo(map);
  k.vis = !k.vis;
  saveKmlStyles();
  _localKmlSaveAll(false);
  rndGraniceModal();
  if (document.getElementById('oznake-panel')?.style.display !== 'none') _rndOznakePanel();
}
function delK(i) {
  const k = kmlLs[i];
  if (!k) return false;
  if (!k._key) {
    try {
      const store=JSON.parse(localStorage.getItem(_LOCAL_KML_KEY)||'{}'),name=k._origName||k.name,cacheKey=store[name]?.cacheKey;
      delete store[name];
      localStorage.setItem(_LOCAL_KML_KEY,JSON.stringify(store));
      if(cacheKey)_kmlcDelete(cacheKey).catch(()=>{});
    } catch(e) {showToast('Sloj nije obrisan — registar nije sačuvan');return false;}
  }
  if (k.grp) map.removeLayer(k.grp);
  if(k._patternId)document.getElementById(k._patternId)?.remove();
  // Bucket fajl: sačuvaj vis:false da se ne auto-učita idući put (ostaje u panelu kao 🙈)
  if (k._key) _kmlPersistHidden(k._key);
  kmlLs.splice(i, 1);
  _kmlEditIdx = -1;
  saveKmlStyles();
  _localKmlSaveAll(false);
  rndGraniceModal();
  if (document.getElementById('oznake-panel')?.style.display !== 'none') _rndOznakePanel();
}

function _kmlPersistHidden(key) {
  try {
    const um = JSON.parse(localStorage.getItem(_KML_USER_STYLES_KEY) || '{}');
    um[key] = { ...(um[key] || {}), vis: false };
    localStorage.setItem(_KML_USER_STYLES_KEY, JSON.stringify(um));
  } catch {}
}

// ── Old rndKml (still used in panel — keep minimal) ───────────────────────────
function rndKml() {
  const el = document.getElementById('kl');
  if (el) el.innerHTML = '';
}

// ── Oznake panel ──────────────────────────────────────────────────────────────
const _ozCollapsed = new Set(['local','foto']);

function _kmlCalcLen(grp) {
  if (!grp) return 0;   // server placeholder (nije preuzeto) — nema sloja
  let d = 0;
  grp.eachLayer(l => {
    if (!l.getLatLngs) return;
    const lls = l.getLatLngs();
    const flat = Array.isArray(lls[0]) ? lls.flat(Infinity) : lls;
    for (let i = 1; i < flat.length; i++) d += flat[i-1].distanceTo(flat[i]);
  });
  return d;
}

function _kmlFeatureCount(grp) {
  if (!grp) return 0;   // server placeholder (nije preuzeto)
  let n = 0;
  grp.eachLayer(l => { if (!(l.getLatLngs && l.getLatLngs().length === 1 && !l.getLatLngs()[0].length)) n++; });
  return n || grp.getLayers().length;
}

function openOznakePanel() {
  // v1.5.0: isti razlog kao u _openLayerSheet() — zatvori Slojeve karte ako
  // su ostali otvoreni, da se dva bottom-sheet-a ne prikažu jedan preko
  // drugog (dva nezavisna modal-sistema koja se dosad nisu zatvarala međusobno).
  if (typeof closeLayerSheet === 'function') closeLayerSheet();
  document.getElementById('oznake-bg').style.display = 'block';
  document.getElementById('oznake-panel').style.display = 'block';
  _rndOznakePanel();
}

function closeOznakePanel() {
  const bg = document.getElementById('oznake-bg');
  const pn = document.getElementById('oznake-panel');
  if (bg) bg.style.display = 'none';
  if (pn) pn.style.display = 'none';
  _kmlEditIdx = -1;
}

