function _ozTogTrag(id) {
  const t = (typeof _tragRegistry !== 'undefined') ? _tragRegistry.find(x => x.id === id) : null;
  if (!t) return;
  const layer = (typeof _tragLayers !== 'undefined') ? _tragLayers[id] : null;
  const nowVis = typeof _tvTrackVisible==='function'?_tvTrackVisible(t):t.visible!==false;
  if(typeof _tvTrackSet==='function')_tvTrackSet(t,!nowVis);else t.visible=!nowVis;
  if (layer) { nowVis ? map.removeLayer(layer) : layer.addTo(map); }
  if (typeof _tragRegSave === 'function') _tragRegSave();
  _rndOznakePanel();
}

// ── Layer sheet sub-tab switcher ──────────────────────────────────────────────
function _lsTab(name) {
  const panes = ['karte','offline','inst','granice'];
  if (!panes.includes(name)) name = 'karte';
  try { localStorage.setItem('tvlake_layer_sheet_tab',name); } catch(e) {}
  panes.forEach(p => {
    const pane = document.getElementById('ls-pane-' + p);
    const btn  = document.getElementById('ls-tab-' + p);
    if (!pane || !btn) return;
    const active = p === name;
    btn.setAttribute('aria-selected',String(active));
    pane.style.display = active ? '' : 'none';
    btn.style.background  = active ? '#1e3a5f' : '#0f172a';
    btn.style.borderColor = active ? '#334155' : '#1e293b';
    btn.style.color       = active ? '#e2e8f0' : '#64748b';
  });
  if (name === 'inst') _instUpdateStats();
  if (name === 'offline') _lsRenderSqlite();
  if (name === 'granice' && typeof KmlDownloads !== 'undefined') KmlDownloads.refreshGithub();
}

function _instToggle(id, on) {
  if(on&&typeof ProjectTerrain!=='undefined'&&['slope','ekspo'].includes(id))ProjectTerrain.toggle(id==='slope'?'slope':'aspect',false);
  if (on) _OVL[id].addTo(map);
  else map.removeLayer(_OVL[id]);
  _ovlState[id] = on;
  localStorage.setItem('tvlake_ovl_state', JSON.stringify(_ovlState));
  if(id==='slope'&&!on){try{const last=JSON.parse(localStorage.getItem(_LASTMAP_KEY)||'null');if(last?.type==='tl'&&last.key==='_nagib')_saveLastMap('tl','⛰ Topo');}catch(e){}}
  _demLegendUpdate();
}

function _demLegendUpdate() {
  const el = document.getElementById('dem-legend');
  if (!el) return;
  const showEkspo = !!_ovlState.ekspo;
  const showNv    = !!_ovlState.nv;
  let html = '';
  if (showEkspo) {
    html += `<div class="leg-title">🧭 Ekspozicija padine</div>
    <div style="display:flex;flex-direction:column;gap:3px;">
      <div class="leg-dir"><div class="leg-dot" style="background:#3b7fd4;"></div>Sjeverna</div>
      <div class="leg-dir"><div class="leg-dot" style="background:#4caf50;"></div>Istočna</div>
      <div class="leg-dir"><div class="leg-dot" style="background:#e8640a;"></div>Južna</div>
      <div class="leg-dir"><div class="leg-dot" style="background:#9c4dcc;"></div>Zapadna</div>
    </div>`;
  }
  if (showNv) {
    if (showEkspo) html += '<div class="leg-sep"></div>';
    html += `<div class="leg-title">📏 Nadmorska visina</div>`;
    const bands = [
      ['#e2e8f0','> 1400 m'],
      ['#06b6d4',' 1200 m'],
      ['#3b82f6',' 1000 m'],
      ['#a855f7','  800 m'],
      ['#ef4444','  600 m'],
      ['#f97316','  400 m'],
      ['#facc15','  200 m'],
      ['#22c55e','    0 m'],
    ];
    html += bands.map(([c,l])=>`<div class="leg-nv-row"><div class="leg-nv-swatch" style="background:${c};"></div><span class="leg-nv-lbl">${l}</span></div>`).join('');
  }
  el.style.display = html ? '' : 'none';
  el.innerHTML = html;
}

async function _instClear(id) {
  if (!('caches' in window)) return;
  const cacheMap = {
    elev:  _ELEV_CACHE,
    slope: _TERR_CACHE,
    nv:    _TERR_CACHE,
    ekspo: _TERR_CACHE,
    kont:  _TERR_CACHE
  };
  const cn = cacheMap[id];
  if (!cn) return;
  const msg=cn===_TERR_CACHE?'Obrisati zajednički DEM keš? Uklanjaju se offline podaci za nagib, nadmorske visine, ekspoziciju i konture.': 'Obrisati sačuvane pločice sjenčenja reljefa?';
  if(!await _dlgConfirm(msg,{danger:true}))return;
  await caches.delete(cn);
  if (cn === _TERR_CACHE) {
    if(typeof ProjectTerrain!=='undefined')ProjectTerrain.invalidateDEM();
    if (_ovlState.slope) _OVL.slope.redraw();
    if (_ovlState.nv)    _OVL.nv.redraw();
    if (_ovlState.ekspo) _OVL.ekspo.redraw();
    if (_ovlState.kont)  _OVL.kont.redraw();
  } else if (_OVL[id] && _ovlState[id]) {
    _OVL[id].redraw();
  }
  await _instUpdateStats();
  showToast('Keš obrisan');
}

async function _instUpdateStats() {
  if(typeof MapCatalog!=='undefined')MapCatalog.renderInstalled();
  if (!('caches' in window)) return;
  const pairs = [
    ['elev',  _ELEV_CACHE],
    ['slope', _TERR_CACHE],
    ['nv',    _TERR_CACHE],
    ['ekspo', _TERR_CACHE],
    ['kont',  _TERR_CACHE]
  ];
  const counts = {};
  for (const [, cn] of pairs) {
    if (cn in counts) continue;
    try { const c = await caches.open(cn); counts[cn] = (await c.keys()).length; }
    catch { counts[cn] = -1; }
  }
  for (const [id, cn] of pairs) {
    const el = document.getElementById('inst-' + id + '-stat');
    if (!el) continue;
    const n = counts[cn];
    el.textContent = n < 0 ? '—' : n ? n + ' pločica' : 'Prazno';
  }
}

