// Collapsed folder groups (persist across re-renders, reset on modal open)
const _glCollapsed = new Set();

function togGlGroup(gk) {
  _glCollapsed.has(gk) ? _glCollapsed.delete(gk) : _glCollapsed.add(gk);
  rndGraniceModal();
}

// Show/hide all layers in a folder group
function togGlGroupVis(indices) {
  const allVis = indices.every(i => kmlLs[i].vis);
  indices.forEach(i => {
    if (!kmlLs[i] || !kmlLs[i].grp) return;
    kmlLs[i].vis = !allVis;
    allVis ? map.removeLayer(kmlLs[i].grp) : kmlLs[i].grp.addTo(map);
  });
  saveKmlStyles();
  rndGraniceModal();
}

function rndGraniceModal() {
  if(typeof window!=='undefined')window.GithubLayers?.render();
  const el = document.getElementById('granice-list');
  if (!el) return;
  const isAdmin = sbProfile?.is_admin === true;
  if (kmlLs.length === 0) {
    el.innerHTML = '<div style="color:#475569;font-size:12px;text-align:center;padding:20px;">Nema učitanih slojeva.<br>Slojevi se učitavaju automatski pri prijavi.</div>';
    return;
  }

  // Preuzete granice i putevi imaju zasebne, odmah otvorene grupe.
  const groupKey=k=>{
    const role=window.GithubLayers?.role(k);
    if(role==='boundaries')return 'Granice odjela';
    if(role==='roads')return 'Kamionski putevi';
    return (k._bucket||'Lokalni')+' / '+(k.name.includes('/')?k.name.split('/')[0]:'Ostali fajlovi');
  };
  // Admin global-save banner
  let html = isAdmin
    ? `<div style="background:rgba(251,191,36,0.1);border:1px solid #92400e;border-radius:8px;padding:8px 12px;margin-bottom:10px;display:flex;align-items:center;gap:10px;">
        <span style="font-size:11px;color:#fbbf24;flex:1;">★ Admin prikaz — tvoje izmjene su <b>privatne</b> dok ne sačuvaš kao default.</span>
        <button class="gl-btn" onclick="saveGlobalKmlStyles()" style="border-color:#fbbf24;color:#fbbf24;font-size:12px;padding:4px 12px;white-space:nowrap;"><svg class="ic"><use href="#ic-sacuvaj"/></svg> Sačuvaj kao default za sve</button>
       </div>`
    : '';

  // Grupiraj po bucketu/folderu (bez neskinutih server placeholdera — nemaju sloj za stil)
  const groups = {};
  kmlLs.forEach((k, i) => {
    if (!k.grp) return;
    const key=groupKey(k);
    if (!groups[key]) groups[key] = [];
    groups[key].push({ k, i });
  });

  html+='<div class="le-library-heading"><h3>Učitani fajlovi</h3><span>'+Object.values(groups).flat().length+' fajlova · '+kmlLs.filter(k=>k.grp&&k.vis).length+' prikazano</span></div>';

  Object.entries(groups).forEach(([groupName, items]) => {
    const collapsed = _glCollapsed.has(groupName);
    const indices = items.map(x => x.i);
    const allVis = indices.every(i => kmlLs[i].vis);
    const anyVis = indices.some(i => kmlLs[i].vis);
    const visIcon = allVis ? '👁' : anyVis ? '◑' : '🚫';
    const visTip  = allVis ? 'Sakrij cijeli folder' : 'Prikaži cijeli folder';
    const gkEsc=_escHtml(JSON.stringify(groupName));

    html += `<div class="gl-group-hdr" onclick="togGlGroup(${gkEsc})">
      <span class="gl-fold-arrow">${collapsed ? '▶' : '▼'}</span>
      <span class="gl-group-name">${_escHtml(groupName)}</span>
      <span class="gl-group-meta">${items.length} sloj${items.length===1?'':'a'}</span>
      <button class="gl-btn gl-grp-vis${allVis?' on':''}" onclick="event.stopPropagation();togGlGroupVis([${indices}])" title="${visTip}" style="margin-left:auto;font-size:13px;padding:1px 7px;">${visIcon}</button>
    </div>`;

    if (!collapsed) {
      items.forEach(({ k, i }) => {
        html+=_layerCardHtml(i);
        if(_kmlEditIdx===i)html+=_renderKmlEditor(i);

      });
    }
  });

  el.innerHTML = html;
}

// === EXPORT ===
function mkKML() {
  const pms=vlake.map(v=>{
    if(v.pts.length<2) return '';
    const cs=v.pts.map(p=>`${p.lo},${p.la},${p.al||0}`).join('\n        ');
    const kc='#ff'+v.color.slice(5,7)+v.color.slice(3,5)+v.color.slice(1,3);
    return `  <Placemark>\n    <n>${v.nm}</n>\n    <Style><LineStyle><color>${kc.toLowerCase()}</color><width>4</width></LineStyle></Style>\n    <LineString><altitudeMode>clampToGround</altitudeMode><coordinates>\n        ${cs}\n    </coordinates></LineString>\n  </Placemark>`;
  }).filter(Boolean).join('\n');
  return `<?xml version="1.0" encoding="UTF-8"?>\n<kml xmlns="http://www.opengis.net/kml/2.2">\n<Document>\n  <n>Traktorske Vlake</n>\n${pms}\n</Document>\n</kml>`;
}

