async function _loadmapInfo(i) {
  const m = _loadmapManageShown[i]; if (!m) return;
  const meta = m.meta || {};
  let t = '📦 ' + m.name + '\n\n';
  t += 'Format: ' + _mapMgrFmtLabel(m.fmt) + '\n';
  t += 'Veličina: ' + _mapMgrFmtSize(m.size) + '\n';
  t += 'Pohrana: ' + (m.meta?._nativeId?'Povezana s fajlom na telefonu — zadrži izvorni fajl':m.saved ? (m.opfs ? 'OPFS (trajno)' : 'baza (trajno)') : 'sesija (privremeno)') + '\n';
  if (meta.minzoom != null) t += 'Zoom: ' + meta.minzoom + '–' + meta.maxzoom + '\n';
  t += 'CRS: ' + (meta.crs || meta.srs || 'EPSG:3857 (pretpostavljeno)') + '\n';
  if (meta.bounds) {
    const b = String(meta.bounds).split(',').map(Number);
    if (b.length === 4) t += 'Granice: W' + b[0].toFixed(3) + ' S' + b[1].toFixed(3) + ' E' + b[2].toFixed(3) + ' N' + b[3].toFixed(3) + '\n';
  }
  if (meta.description) t += 'Opis: ' + meta.description + '\n';
  if (m.savedAt) t += 'Učitano: ' + _mapMgrFmtDate(m.savedAt) + '\n';
  await _dlgConfirm(t, { title: 'ℹ Info — ' + m.name, okLabel: 'OK' });
}

function getOfflineBounds() {
  const v = document.getElementById('offline-area').value;
  if (v.startsWith('odjel:')) {
    const o = graniceOdjeli[+v.split(':')[1]];
    if (o) return o.bounds;
  }
  return map.getBounds();
}

function updateOfflineEstimate() {
  const estEl = document.getElementById('offline-estimate');
  const btn = document.getElementById('offline-dl-btn');
  const bounds = getOfflineBounds();
  const zMin = +document.getElementById('offline-zmin').value;
  const zMax = +document.getElementById('offline-zmax').value;
  if (zMin > zMax) { estEl.textContent = 'Min zoom ne može biti veći od max!'; return; }
  const info = _dlLayerInfo();
  if (!info.layer) {
    estEl.innerHTML = `<span style="color:#fbbf24;">${info.name} — nema pločica za preuzimanje.</span><br><span style="font-size:11px;color:#475569;">Odaberi Topo / Satelit / Karta / Satelit HD kao aktivnu kartu.</span>`;
    if (btn) btn.disabled = true;
    return;
  }
  // Stvarni broj = poslije maxNativeZoom clamp-a (npr. Topo staje na z17)
  const n = buildTileUrls(bounds, zMin, zMax).length;
  const mb = (n * 25 / 1024).toFixed(1); // ~25KB po tile
  estEl.innerHTML =
    `Procjena: <b style="color:#38bdf8">${n.toLocaleString()}</b> tile-ova · ≈ <b style="color:#fbbf24">${mb} MB</b><br>` +
    `<span style="font-size:11px;color:#475569;">Zoom ${zMin}–${zMax} · sloj: <b style="color:#94a3b8">${info.name}</b></span>`;
  if (btn) btn.disabled = n > 50000 || n === 0;
  if (n > 50000) estEl.innerHTML += `<br><span style="color:#f87171;">Previše tile-ova — smanjite zoom ili područje</span>`;
  else if (n === 0) estEl.innerHTML += `<br><span style="color:#f87171;">Odabrani zoom je iznad dostupnog za ovaj sloj.</span>`;
}

const _OFFLINE_DL_INCOMPLETE_KEY = 'tvlake_offline_dl_incomplete';
async function showCacheInfo() {
  if (!('caches' in window)) return;
  const cache = await caches.open(TILE_CACHE_NAME);
  const keys = await cache.keys();
  // Ukupna zauzetost memorije aplikacije (pločice + karte + offline baze)
  let mbTxt = '';
  if (navigator.storage && navigator.storage.estimate) {
    try { const est = await navigator.storage.estimate(); mbTxt = ` · ≈ ${Math.round((est.usage || 0) / 1048576)} MB ukupno`; } catch(e) {}
  }
  let html = keys.length > 0
    ? `💾 Keširano (online prikazi): <b style="color:#4ade80">${keys.length.toLocaleString()}</b> pločica${mbTxt}<br>`
      + `<span style="font-size:11px;color:#94a3b8;">Sve što pogledaš online (satelit/topo/google) čuva se za offline.</span> `
      + `<a href="#" onclick="clearTileCache(event)" style="color:#f87171;">Obriši memoriju karata</a>`
    : `💾 Nema keširanih pločica — pregledaj karte online da se snime za offline.`;
  // D1-A: prijavi ako je prethodno preuzimanje prekinuto (aplikacija ubijena/zatvorena
  // usred download-a) — korisnik inače nema indikaciju da region nije potpun.
  if (localStorage.getItem(_OFFLINE_DL_INCOMPLETE_KEY)) {
    html += `<br><span style="color:#fbbf24;">⚠ Prethodno preuzimanje nije završeno — pokreni ponovo da dopuniš.</span>`;
  }
  document.getElementById('offline-cache-info').innerHTML = html;
}

async function clearTileCache(e) {
  if (e) e.preventDefault();
  if (!await _dlgConfirm('Obrisati sve keširane karte (satelit, topo, teren)? Offline prikaz tih područja više neće raditi dok ih ponovo ne pogledaš online.', { title: 'Obriši memoriju karata', okLabel: 'Obriši' })) return;
  // Obriši SVE mapne kešove (pločice + teren overlay), ali NE app shell / biblioteke
  const keys = await caches.keys();
  const mapCaches = keys.filter(k => /^tvlake-(tiles|elev|slope|terr|nv|effis|wcover)/.test(k));
  await Promise.all(mapCaches.map(k => caches.delete(k)));
  localStorage.removeItem(_OFFLINE_DL_INCOMPLETE_KEY);
  showToast('🗑 Memorija karata obrisana');
  if (typeof _lsRenderCache === 'function') _lsRenderCache();
  if (document.getElementById('offline-cache-info')) showCacheInfo();
}

let offlineAbort = false;
let _offlineDlInFlight = false;
async function startOfflineDownload() {
  // D1-A: spriječi konkurentno preuzimanje (dupli tap / ponovno otvoren modal) —
  // dva paralelna prolaza bi trošila mrežu/bateriju i mutirala isti progress bar.
  if (_offlineDlInFlight) { showToast('⏳ Preuzimanje je već u toku'); return; }
  if (!('caches' in window)) { showToast('⚠ Vaš browser ne podržava Cache API.'); return; }
  const bounds = getOfflineBounds();
  const zMin = +document.getElementById('offline-zmin').value;
  const zMax = +document.getElementById('offline-zmax').value;
  const urls = buildTileUrls(bounds, zMin, zMax);
  if (urls.length === 0) return;
  _offlineDlInFlight = true;

  const btn = document.getElementById('offline-dl-btn');
  btn.textContent = '⏹ Zaustavi';
  btn.onclick = () => { offlineAbort = true; };
  offlineAbort = false;

  const bar = document.getElementById('offline-progress-bar');
  const fill = document.getElementById('offline-progress-fill');
  const status = document.getElementById('offline-status');
  bar.style.display = 'block';
  localStorage.setItem(_OFFLINE_DL_INCOMPLETE_KEY, '1');

  try {
    const cache = await caches.open(TILE_CACHE_NAME);
    let done = 0, skipped = 0, failed = 0, quotaHit = false;

    for (const url of urls) {
      if (offlineAbort || quotaHit) break;
      // Provjeri da li je već u cache-u
      const existing = await cache.match(url);
      if (existing) { skipped++; done++; }
      else {
        try {
          // Rok je OBAVEZAN, ne kozmetika: petlja ide SEKVENCIJALNO kroz sve
          // pločice, pa jedna koja VISI (OS-S4 — mrtva veza koju navigator.onLine
          // prijavljuje kao 'true') zaustavi CIJELO preuzimanje offline karte na
          // neodređeno. Korisnik gleda zamrznut progress bar i jedini izlaz mu je
          // "Zaustavi". Sa rokom pločica samo padne u `failed` granu koja već
          // postoji i petlja ide dalje.
          const resp = await _fetchT(url, 15000, { mode: 'cors' });
          if (resp.ok) {
            try { await cache.put(url, resp); done++; }
            catch(qe) { if (qe && qe.name === 'QuotaExceededError') quotaHit = true; failed++; done++; }
          }
          else failed++;
        } catch { failed++; done++; }
      }
      const pct = Math.round(done / urls.length * 100);
      fill.style.width = pct + '%';
      if (done % 20 === 0 || done === urls.length) {
        status.textContent = `${done} / ${urls.length} · preskočeno: ${skipped} · greška: ${failed}`;
      }
      // Mali delay da ne opteretimo server
      if (done % 10 === 0) await new Promise(r => setTimeout(r, 50));
    }

    btn.innerHTML = '<svg class="ic"><use href="#ic-uvezi"/></svg> Preuzmi';
    btn.onclick = startOfflineDownload;
    const fullyDone = !offlineAbort && !quotaHit;
    status.textContent = quotaHit
      ? `⚠ Nema više prostora za pohranu — preuzeto ${done} tile-ova prije popune memorije.`
      : offlineAbort
      ? `Prekinuto. Preuzeto ${done} tile-ova.`
      : `✅ Gotovo! ${done - failed} tile-ova u cache-u.`;
    if (fullyDone) localStorage.removeItem(_OFFLINE_DL_INCOMPLETE_KEY);
    showCacheInfo();
  } finally {
    _offlineDlInFlight = false;
  }
}

// === PWA SERVICE WORKER ===
(function registerSW() {
  if (!('serviceWorker' in navigator)) return;
  // updateViaCache:'none' → preglednik UVIJEK dohvati svjež sw.js (zaobiđe HTTP keš s
  // max-age=600 koji je inače kasnio detekciju nove verzije do 10 min). Ovo je ključ
  // pouzdanog auto-update-a — bez njega refresh često servira STARU verziju.
  navigator.serviceWorker.register('./sw.js', { updateViaCache: 'none' }).then(reg => {
    // Ako je SW već čekao pri učitavanju stranice → auto-primijeni (app tek učitan,
    // ništa se ne snima) da korisnik pouzdano dobije najnoviju verziju.
    if (reg.waiting) {
      if (!recOn && !_tragOn && !_dozGpsOn) reg.waiting.postMessage('skipWaiting');
      else showUpdateToast();
    }

    // Provjeri update odmah i svakih 30 min
    reg.update();
    setInterval(() => reg.update(), 30 * 60 * 1000);

    // Novi SW instalira se → čekaj 'installed' stanje
    reg.addEventListener('updatefound', () => {
      const newSW = reg.installing;
      newSW.addEventListener('statechange', () => {
        if (newSW.state === 'installed' && navigator.serviceWorker.controller) {
          // Auto-primijeni update kad app miruje (nema aktivnog snimanja) — pouzdano
          // dobijanje najnovije verzije bez ručnog klika. Tokom snimanja → toast.
          if (!recOn && !_tragOn && !_dozGpsOn) newSW.postMessage('skipWaiting');
          else showUpdateToast();
        }
      });
    });
  }).catch(e => console.warn('SW registracija nije uspjela:', e));

  // Kad SW preuzme kontrolu nakon skipWaiting → reload za čistu novu verziju.
  // v3.111.4: prag je VREMENSKI (5s), ne "najviše JEDNOM ikad po tabu" kao ranije.
  // Stari obrazac je izazvao baš onaj bug koji je trebao spriječiti: kad se u istoj
  // dugo otvorenoj kartici objavi VIŠE verzija zaredom (uobičajeno u sesiji ovakvih
  // popravki — nekoliko izmjena u istom satu), prvi update je uredno reloadovao
  // stranicu, ali SVAKI SLJEDEĆI controllerchange je tiho preskočen ('sw-reloaded'
  // je već bilo '1') — SW ispod je i dalje tiho napredovao na najnoviju verziju, ali
  // stranica u memoriji (HTML/CSS/JS) je OSTAJALA zaglavljena na verziji iz PRVOG
  // reload-a, bez ikakvog vidljivog znaka da nešto nije ažurno. Korisnik je prijavio
  // isti render-bug tri puta zaredom ("opet isto") dok su popravke u međuvremenu već
  // bile na serveru i ISPRAVNE — samo mu ih niko nije ponudio drugi put. Vremenski
  // prag i dalje sprječava pravu petlju (dva reload-a unutar par sekundi bi značila
  // da nova verzija odmah nakon reload-a opet nešto instalira), ali ne blokira
  // legitiman DRUGI/TREĆI reload kad su verzije razmaknute minutama/satima.
  navigator.serviceWorker.addEventListener('controllerchange', () => {
    const now = Date.now();
    let last = 0;
    try { last = parseInt(sessionStorage.getItem('sw-reloaded-at') || '0', 10) || 0; } catch(e) {}
    if (now - last < 5000) return;
    try { sessionStorage.setItem('sw-reloaded-at', String(now)); } catch(e) {}
    window.location.reload();
  });

  // Provjeri postoji li novija objavljena verzija (nakon starta, da ne koči učitavanje).
  setTimeout(_checkLatestVersion, 6000);
})();

function showUpdateToast() {
  _updateNotice('', 'update-toast');
}
function _updateNotice(latest, id = 'ver-banner') {
  if (document.getElementById('ver-banner') || document.getElementById('update-toast')) return;
  const b = document.createElement('div'); b.id = id; b.className = 'update-notice';
  b.setAttribute('role', 'status');
  const action = document.createElement('button'); action.type = 'button'; action.className = 'update-notice-action';
  action.innerHTML = '<span class="update-notice-icon" aria-hidden="true">↻</span><span class="update-notice-copy"><strong>Dostupno ažuriranje</strong><small></small><b>Ažuriraj aplikaciju →</b></span>';
  action.querySelector('small').textContent = latest ? 'Nova verzija v' + latest : 'Nova verzija je spremna';
  action.onclick = () => { azurirajAplikaciju(); };
  const close = document.createElement('button'); close.type = 'button'; close.className = 'update-notice-close';
  close.textContent = '×'; close.setAttribute('aria-label', 'Sakrij obavijest o ažuriranju');
  close.onclick = () => { if(latest)try{localStorage.setItem('tvlake_ver_dismissed',latest);}catch(e){} b.remove(); };
  b.append(action,close); document.body.appendChild(b);
}

function applyUpdate() {
  navigator.serviceWorker.ready.then(reg => {
    if (reg.waiting) {
      reg.waiting.postMessage('skipWaiting');
    } else {
      window.location.reload();
    }
  });
}

// Ručna akcija iz menija: na webu aktivira novi Service Worker i osvježi
// aplikaciju. APK ne može sam sebe zamijeniti u letu (Android to namjerno
// blokira), ali OD v1.5.2 MOŽE preuzeti i pokrenuti instalaciju novog APK-a
// jednim tapom preko AndroidUpdate mosta (MainActivity.java) — CI
// (codex-webview.yml) poslije svakog uspješnog builda objavljuje GitHub
// Release sa APK-om kao javno dostupan asset (bez potrebe za login-om, za
// razliku od Actions artefakta koji je ranije bio jedina opcija).
// _APK_BUILD_URL ostaje SAMO kao fallback za APK koji je instaliran PRIJE
// ovog moста (kokoška-i-jaje: taj most se ne može sam dodati u već instaliran
// APK) — na takvom APK-u window.AndroidUpdate ne postoji.
const _APK_BUILD_URL = 'https://github.com/pogonboskrupa/US-SUME/actions/workflows/codex-webview.yml?query=branch%3ACODEX-US-SUME';
async function azurirajAplikaciju() {
  if (typeof _mrezaSila === 'function') _mrezaSila(60000);
  if (typeof _anyRecOn === 'function' && _anyRecOn()) {
    showToast('⚠ Prvo završi ili pauziraj GPS snimanje');
    return;
  }
  const isAPK = location.hostname === 'appassets.androidplatform.net';
  if (!isAPK) {
    showToast('🔄 Provjeravam ažuriranje…');
    try {
      const reg = await navigator.serviceWorker.getRegistration();
      if (!reg) { window.location.reload(); return; }
      await reg.update();
      if (reg.waiting) reg.waiting.postMessage('skipWaiting');
      else setTimeout(() => window.location.reload(), 900);
    } catch(e) { showToast('⚠ Ažuriranje nije dostupno bez interneta'); }
    return;
  }

  if (window.AndroidUpdate && typeof window.AndroidUpdate.checkAndInstall === 'function') {
    _azurirajNapredak({ faza:'provjera', poruka:'Provjeravam novu verziju…' });
    try { window.AndroidUpdate.checkAndInstall(); }
    catch(e) { _azurirajNapredak({ faza:'greska', poruka:'Ažuriranje nije uspjelo pokrenuti — pokušaj ponovo.' }); }
    return;
  }

  // Fallback za APK koji još nema AndroidUpdate most (vidi komentar gore).
  showToast('🔄 Provjeravam verziju…');
  let latest = null;
  try {
    // Bez roka bi ovo na mrtvoj vezi VISILO, a ne palo — korisnik bi trajno
    // ostao na toastu "Provjeravam verziju…" i catch ispod se nikad ne bi
    // izvršio (poziv koji visi ne baca ništa).
    const r = await _fetchT(_LIVE_BASE + 'sw.js?_v=' + Date.now(), 10000, { cache:'no-store' });
    const m = r.ok ? (await r.text()).match(/APP_VERSION\s*=\s*['"]([\d.]+)['"]/): null;
    latest = m ? m[1] : null;
  } catch(e) {}
  const local = APP_VER.replace(/^v/, '');
  if (!latest) {
    await _dlg({ title:'Ažuriranje aplikacije', mode:'alert', okLabel:'U redu',
      msg:'Nije moguće provjeriti novu verziju. Provjeri internet pa pokušaj ponovo.' });
  } else if (_verCmp(latest, local) <= 0) {
    await _dlg({ title:'Ažuriranje aplikacije', mode:'alert', okLabel:'U redu',
      msg:'Već koristiš najnoviju verziju: v' + local + '.' });
  } else {
    const izbor = await _dlgActions('Ažuriranje aplikacije', [
      { label:'⬇ Otvori preuzimanje APK-a' }
    ]);
    if (izbor === 0) window.location.href = _APK_BUILD_URL;
  }
}

// Poziva se iz MainActivity.UpdateBridge (native strana) sa statusom toka
// preuzimanja/instalacije ("Preuzimam verziju vX…", "Već imaš najnoviju"...).
// Zaseban toast red umjesto _dlg-a — provjera radi u pozadini (Thread na
// native strani), korisnik u međuvremenu i dalje koristi app.
function _azurirajStatus(msg) {
  if (typeof msg === 'string' && msg) showToast(msg);
}

// ─── Panel ažuriranja: provjera → preuzimanje → instalacija ────────────────
// Native UpdateBridge šalje {faza, primljeno, ukupno, verzija, poruka} kroz
// _azurirajNapredak. Ranije je cijeli tok bio par toastova, pa se ~20 MB
// preuzimanja na terenskoj vezi nije vidjelo nikako, a prekid je izgledao kao
// sirovo "SocketException".
const _UPD_KORACI = [
  { label:'Provjera', ico:'ic-trazi' },
  { label:'Preuzimanje', ico:'ic-uvezi' },
  { label:'Instalacija', ico:'ic-uredjaj' },
];
// korak: indeks aktivnog koraka; null = ostaje zadnji aktivni (greška/otkaz na tom koraku)
const _UPD_FAZE = {
  provjera:    { korak:0,    ton:'' },
  preuzimanje: { korak:1,    ton:'' },
  ponovo:      { korak:1,    ton:'warn' },
  dozvola:     { korak:2,    ton:'warn' },
  instalacija: { korak:2,    ton:'' },
  najnovija:   { korak:3,    ton:'ok' },
  greska:      { korak:null, ton:'err' },
  otkazano:    { korak:null, ton:'' },
};
const _UPD_ZAVRSNE = ['najnovija', 'greska', 'otkazano', 'instalacija', 'dozvola'];
const _updStanje = { korak:0, faza:'', ver:'', uzorci:[], prim:0, uk:0 };

function _updMB(b) {
  const mb = (Number(b) || 0) / 1048576;
  return (mb >= 100 ? mb.toFixed(0) : mb.toFixed(1)) + ' MB';
}

// Brzina iz uzoraka zadnjih ~4 s (ne od početka — poslije prekida i nastavka
// prosjek od početka bi lagao), preostalo vrijeme iz te brzine.
function _updBrzinaEta(uzorci, prim, uk) {
  if (!Array.isArray(uzorci) || uzorci.length < 2) return { brzina:'', eta:'' };
  const a = uzorci[0], z = uzorci[uzorci.length - 1];
  const dt = (z.t - a.t) / 1000;
  if (dt < 0.8 || z.b <= a.b) return { brzina:'', eta:'' };
  const bps = (z.b - a.b) / dt;
  const brzina = bps >= 1048576 ? (bps / 1048576).toFixed(1) + ' MB/s' : Math.round(bps / 1024) + ' KB/s';
  let eta = '';
  if (uk > 0 && prim < uk) {
    const s = Math.ceil((uk - prim) / bps);
    eta = s < 60 ? 'još ~' + s + ' s' : 'još ~' + Math.ceil(s / 60) + ' min';
  }
  return { brzina, eta };
}

function _updId(id) { return document.getElementById(id); }

function _updEl() {
  let bg = _updId('upd-bg');
  if (bg) return bg;
  bg = document.createElement('div');
  bg.id = 'upd-bg';
  bg.innerHTML =
    '<div id="upd-sheet" role="dialog" aria-modal="true" aria-labelledby="upd-title">' +
      '<div class="upd-head"><div class="upd-head-ico"><svg class="ic"><use href="#ic-uvezi"/></svg></div>' +
        '<div><div class="upd-title" id="upd-title">Ažuriranje aplikacije</div><div class="upd-ver" id="upd-ver"></div></div></div>' +
      '<div class="upd-steps" id="upd-steps">' +
        _UPD_KORACI.map((k, i) => '<div class="upd-step" data-i="' + i + '"><div class="upd-dot"><svg class="ic"><use href="#' + k.ico + '"/></svg></div>' + k.label + '</div>').join('') +
      '</div>' +
      '<div class="upd-prog" id="upd-prog">' +
        '<div class="upd-prog-top"><div class="upd-pct" id="upd-pct"></div><div class="upd-mb" id="upd-mb"></div></div>' +
        '<div class="upd-bar" id="upd-bar"><div class="upd-fill" id="upd-fill"></div></div>' +
        '<div class="upd-speed"><span id="upd-brzina"></span><span id="upd-eta"></span></div>' +
      '</div>' +
      '<div class="upd-msg" id="upd-msg"></div>' +
      '<div class="upd-note" id="upd-note"><svg class="ic"><use href="#ic-potvrdi"/></svg>' +
        '<span>Ažuriranje zadržava tvoje podatke — offline karte, tragove, vlake i sve što čeka sinhronizaciju.</span></div>' +
      '<div class="upd-btns" id="upd-btns"></div>' +
    '</div>';
  bg.addEventListener('click', e => {
    if (e.target === bg && _UPD_ZAVRSNE.includes(_updStanje.faza)) _updZatvori();
  });
  document.body.appendChild(bg);
  return bg;
}

function _updZatvori() {
  const bg = _updId('upd-bg');
  if (bg) bg.classList.remove('show');
}

function _updOtkazi() {
  try { if (window.AndroidUpdate && typeof window.AndroidUpdate.cancel === 'function') window.AndroidUpdate.cancel(); } catch(e) {}
  const m = _updId('upd-msg');
  if (m) { m.className = 'upd-msg'; m.textContent = 'Otkazujem…'; }
}

function _updPonovo() { azurirajAplikaciju(); }

// ─── Admin: preuzmi APK fajl (najnoviji GitHub Release) ────────────────────
// Admin dijeli APK kolegama čiji telefon nema ovu app ili ima stariju verziju bez
// "Ažuriraj aplikaciju" mosta. Isti /releases?per_page=1 kao _checkLatestVersion
// (/releases/latest isključuje prerelease, a svaki release je prerelease).
// U APK-u navigacija na vanjski URL ide kroz shouldOverrideUrlLoading → ACTION_VIEW,
// pa preuzimanje radi Android preglednik/DownloadManager — bez nove Java izmjene.
const _APK_RELEASES_API = 'https://api.github.com/repos/pogonboskrupa/US-SUME/releases?per_page=1';
const _APK_RELEASES_STR = 'https://github.com/pogonboskrupa/US-SUME/releases';

function _apkAssetIzReleasea(release) {
  if (!release || release.draft) return null;
  const a = (release.assets || []).find(x => /\.apk$/i.test(x?.name || '') && x.state === 'uploaded' && /^https:\/\//.test(x.browser_download_url || ''));
  if (!a) return null;
  return { ver: String(release.tag_name || '').replace(/^v/, ''), ime: a.name, url: a.browser_download_url, vel: Number(a.size) || 0 };
}

function _apkOtvoriUrl(url) {
  if (location.hostname === 'appassets.androidplatform.net') { window.location.href = url; return; }
  const a = document.createElement('a');
  a.href = url; a.target = '_blank'; a.rel = 'noopener';
  document.body.appendChild(a); a.click(); a.remove();
}

async function preuzmiApkAdmin() {
  if (!sbProfile?.is_admin) { showToast('⚠ Samo za admina'); return; }
  if (typeof _mrezaSila === 'function') _mrezaSila(60000);
  showToast('🔄 Tražim najnoviji APK…');
  let apk = null, greska = '';
  try {
    const r = await _fetchT(_APK_RELEASES_API, 10000, { cache: 'no-store' });
    if (r.ok) apk = _apkAssetIzReleasea((await r.json())?.[0]);
    else greska = 'GitHub je odgovorio ' + r.status + '.';
  } catch (e) { greska = 'Nema veze sa GitHub-om.'; }
  if (!apk) {
    const izbor = await _dlgActions('Preuzmi APK fajl', [
      { label: '🌐 Otvori stranicu sa verzijama' },
      { label: 'Zatvori' },
    ]);
    if (izbor === 0) _apkOtvoriUrl(_APK_RELEASES_STR);
    if (greska) showToast('⚠ ' + greska);
    return;
  }
  const lokalna = APP_VER.replace(/^v/, '');
  const vel = apk.vel ? ' · ' + _updMB(apk.vel) : '';
  const izbor = await _dlg({
    title: 'Preuzmi APK fajl', mode: 'actions',
    msg: apk.ime + ' (v' + apk.ver + vel + ') — na ovom uređaju je v' + lokalna + '.',
    actions: [{ label: '⬇ Preuzmi APK' }, { label: '📋 Kopiraj link' }, { label: 'Zatvori' }],
  });
  if (izbor === 0) _apkOtvoriUrl(apk.url);
  else if (izbor === 1) {
    try { await navigator.clipboard.writeText(apk.url); showToast('📋 Link kopiran'); }
    catch (e) { showToast(apk.url); }
  }
}

function _updDugme(tip, ico, tekst, akcija) {
  return '<button class="upd-btn' + (tip ? ' ' + tip : '') + '" onclick="' + akcija + '">' +
    (ico ? '<svg class="ic"><use href="#' + ico + '"/></svg>' : '') + tekst + '</button>';
}

function _azurirajNapredak(p) {
  if (typeof p === 'string') { try { p = JSON.parse(p); } catch(e) { return; } }
  if (!p || !_UPD_FAZE[p.faza]) return;
  let bg;
  try { bg = _updEl(); } catch(e) { if (p.poruka) showToast(p.poruka); return; }
  const f = _UPD_FAZE[p.faza], st = _updStanje;
  const prim = Number(p.primljeno) || 0, uk = Number(p.ukupno) || 0;

  if (p.faza === 'provjera') { st.uzorci = []; st.prim = 0; st.uk = 0; st.ver = ''; }
  if (p.verzija && p.faza !== 'najnovija') st.ver = p.verzija;
  if (f.korak !== null) st.korak = f.korak;
  st.faza = p.faza;
  if (p.faza === 'preuzimanje' || p.faza === 'ponovo') {
    if (prim < st.prim) st.uzorci = [];
    st.prim = prim; st.uk = uk;
  }
  if (p.faza === 'preuzimanje') {
    const sad = Date.now();
    st.uzorci.push({ t:sad, b:prim });
    st.uzorci = st.uzorci.filter(u => sad - u.t <= 4000);
  } else if (p.faza === 'ponovo') {
    st.uzorci = [];
  }
  bg.classList.add('show');

  const lok = String(typeof APP_VER === 'string' ? APP_VER : '').replace(/^v/, '');
  _updId('upd-ver').textContent = st.ver
    ? 'v' + lok + '  →  v' + st.ver
    : 'Instalirana verzija v' + (p.faza === 'najnovija' && p.verzija ? p.verzija : lok);

  bg.querySelectorAll('.upd-step').forEach(el => {
    const i = Number(el.dataset.i);
    let cls = '';
    if (i < st.korak) cls = 'done';
    else if (i === st.korak) cls = f.ton === 'err' ? 'err' : f.ton === 'warn' ? 'warn' : (p.faza === 'otkazano' ? '' : 'active');
    el.className = 'upd-step' + (cls ? ' ' + cls : '');
    const use = el.querySelector('use');
    if (use) use.setAttribute('href', '#' + (cls === 'done' ? 'ic-potvrdi' : cls === 'err' ? 'ic-zatvori' : _UPD_KORACI[i].ico));
  });

  const prog = _updId('upd-prog'), bar = _updId('upd-bar'), fill = _updId('upd-fill');
  const pct = _updId('upd-pct'), mb = _updId('upd-mb');
  const brz = _updId('upd-brzina'), eta = _updId('upd-eta');
  const bezNapretka = p.faza === 'najnovija' || ((p.faza === 'greska' || p.faza === 'otkazano') && st.korak === 0);
  prog.style.display = bezNapretka ? 'none' : '';
  bar.classList.remove('indet');
  fill.className = 'upd-fill';
  brz.textContent = ''; eta.textContent = '';
  const pUk = uk || st.uk, pPrim = prim || st.prim;
  if (p.faza === 'provjera' || ((p.faza === 'preuzimanje' || p.faza === 'ponovo') && !(pUk > 0))) {
    bar.classList.add('indet');
    fill.classList.add('moving');
    pct.innerHTML = '';
    mb.textContent = p.faza === 'provjera' ? 'Tražim najnoviju objavu…' : _updMB(pPrim);
  } else {
    const done = ['instalacija', 'dozvola'].includes(p.faza);
    const proc = done ? 100 : (pUk > 0 ? Math.min(100, Math.floor(pPrim / pUk * 100)) : 0);
    fill.style.width = proc + '%';
    pct.innerHTML = proc + '<small>%</small>';
    mb.textContent = pUk > 0 ? (done ? _updMB(pUk) : _updMB(pPrim) + ' / ' + _updMB(pUk)) : '';
    if (p.faza === 'preuzimanje') {
      fill.classList.add('moving');
      const be = _updBrzinaEta(st.uzorci, pPrim, pUk);
      brz.textContent = be.brzina; eta.textContent = be.eta;
    } else if (p.faza === 'ponovo' || p.faza === 'dozvola') fill.classList.add('warn');
    else if (p.faza === 'instalacija') fill.classList.add('ok');
    else if (p.faza === 'greska') fill.classList.add('err');
  }

  const msg = _updId('upd-msg');
  msg.className = 'upd-msg' + (f.ton ? ' ' + f.ton : '');
  msg.textContent = p.faza === 'preuzimanje'
    ? 'Preuzimam novu verziju. Možeš nastaviti raditi — samo ne zatvaraj aplikaciju.'
    : (p.poruka || '');
  _updId('upd-note').style.display = ['instalacija', 'dozvola'].includes(p.faza) ? '' : 'none';

  let btns = '';
  if (['provjera', 'preuzimanje', 'ponovo'].includes(p.faza)) {
    btns = _updDugme('dng', 'ic-zatvori', 'Otkaži', '_updOtkazi()');
  } else if (p.faza === 'instalacija') {
    btns = _updDugme('', '', 'Zatvori', '_updZatvori()') + _updDugme('pri', 'ic-ponovi', 'Instaliraj ponovo', '_updPonovo()');
  } else if (p.faza === 'dozvola') {
    btns = _updDugme('', '', 'Zatvori', '_updZatvori()') + _updDugme('pri', 'ic-naprijed', 'Nastavi', '_updPonovo()');
  } else if (p.faza === 'najnovija') {
    btns = _updDugme('pri', 'ic-potvrdi', 'U redu', '_updZatvori()');
  } else {
    btns = _updDugme('', '', 'Zatvori', '_updZatvori()') + _updDugme('pri', 'ic-ponovi', 'Pokušaj ponovo', '_updPonovo()');
  }
  _updId('upd-btns').innerHTML = btns;
}

// ─── PROVJERA NAJNOVIJE VERZIJE (posebno bitno za APK) ───────────────────────
// APK servira ZAMRZNUTE assets iz appassets.androidplatform.net — service worker
// auto-update tu ne pomaže (nema svježeg index.html), pa korisnik može mjesecima
// raditi na staroj verziji bez ikakvog znaka. Ovdje se dohvati verzija sa žive
// GitHub Pages objave i, ako je novija, prikaže se nenametljiv baner. GitHub
// Pages šalje Access-Control-Allow-Origin:* pa cross-origin fetch iz APK radi.
// GitHub Pages čuva naziv projekta u URL-u sa velikim slovima. Mala slova
// vraćaju 404, pa APK/web nisu mogli pouzdano provjeriti novu verziju.
const _LIVE_BASE = 'https://pogonboskrupa.github.io/US-SUME/';

function _verCmp(a, b) {
  const pa = String(a).split('.').map(n => parseInt(n, 10) || 0);
  const pb = String(b).split('.').map(n => parseInt(n, 10) || 0);
  for (let i = 0; i < Math.max(pa.length, pb.length); i++) {
    const d = (pa[i] || 0) - (pb[i] || 0);
    if (d) return d > 0 ? 1 : -1;
  }
  return 0;
}

async function _checkLatestVersion() {
  try {
    const isAPK = location.hostname === 'appassets.androidplatform.net';
    let latest;
    if (isAPK) {
      const r = await _fetchT('https://api.github.com/repos/pogonboskrupa/US-SUME/releases?per_page=1', 10000, {cache:'no-store'});
      if(!r.ok)return;
      const release = (await r.json())?.[0];
      if(!release || release.draft || !release.assets?.some(a => /\.apk$/i.test(a.name) && a.state === 'uploaded'))return;
      latest = String(release.tag_name || '').replace(/^v/,'');
      if(!/^\d+\.\d+\.\d+$/.test(latest))return;
    } else {
      const r = await _fetchT('./sw.js?_v=' + Date.now(), 10000, { cache: 'no-store' });
      if (!r.ok) return;
      const m = (await r.text()).match(/APP_VERSION\s*=\s*['"]([\d.]+)['"]/);
      if (!m) return;
      latest = m[1];
    }
    const local = APP_VER.replace(/^v/, '');
    if (_verCmp(latest, local) <= 0) return;               // već na najnovijoj (ili novijoj lokalnoj)
    if (localStorage.getItem('tvlake_ver_dismissed') === latest) return; // korisnik odbio baš ovu verziju
    _showVersionBanner(latest, isAPK);
  } catch(e) { /* offline / CORS / bilo šta — tiho preskoči */ }
}

function _showVersionBanner(latest, isAPK) {
  _updateNotice(latest);
}

// Toast ne smije prekriti traku snimanja ni otvoren donji list (v1.9.0) —
// "T1.1 sačuvana…" je stajao preko liste "Šta dalje" i preko statistike.
// v2.9.8: ni donju traku Karte ni prozorčiće iznad nje — "Offline pristup"
// je pri pokretanju stajao preko dugmadi Tragovi/Izmjeri i "Snimi trag".
function _toastDno() {
  let dno = 70;
  const vis = window.innerHeight || 0;
  for (const id of ['rec-banner', 'sto-dalje-sheet', 'krak-izbor', 'lager-dlg', 'trag-ured', 'action-bar', 'rec-bar', 'ab-loc-popup', 'ab-izmjeri-menu']) {
    const el = document.getElementById(id);
    if (!el || getComputedStyle(el).display === 'none') continue;
    const r = el.getBoundingClientRect();
    if (r.height && r.bottom >= vis - 160) dno = Math.max(dno, vis - r.top + 10);
  }
  return Math.min(dno, Math.max(70, vis - 120));
}
function showToast(msg) {
  let t = document.getElementById('toast-msg');
  if (!t) {
    t = document.createElement('div');
    t.id = 'toast-msg';
    t.style.cssText = `position:fixed;bottom:70px;left:50%;transform:translateX(-50%);
      background:#fff;border:none;border-radius:22px;
      padding:8px 20px;font-size:13px;font-weight:600;color:#1e293b;z-index:9000;pointer-events:none;
      box-shadow:0 4px 16px rgba(0,0,0,0.12),0 0 0 0.5px rgba(0,0,0,0.06);
      transition:opacity 0.4s;`;
    document.body.appendChild(t);
  }
  t.textContent = msg;
  try { t.style.bottom = _toastDno() + 'px'; } catch(e) {}
  t.style.opacity = '1';
  clearTimeout(t._to);
  // Dok je vidljiv, toast prati ono što se otvori ispod njega (npr. popup
  // lokacije otvoren sekundu poslije "Offline pristup") — inače ga prekrije.
  clearInterval(t._pr);
  t._pr = setInterval(() => { try { t.style.bottom = _toastDno() + 'px'; } catch(e) {} }, 300);
  t._to = setTimeout(() => { t.style.opacity = '0'; clearInterval(t._pr); }, 2500);
}

// ─── Custom dialog system (replaces all native alert/confirm/prompt) ─────────
let _dlgResolve = null;
let _dlgMode = null; // 'alert' | 'confirm' | 'prompt' | 'actions'

function _dlg({ title = '', msg = '', mode = 'alert', inputVal = '', inputType = 'text', inputMode = 'text', okLabel = 'OK', cancelLabel = 'Odustani', danger = false, actions = [], vlakaKeyboard = false } = {}) {
  return new Promise(resolve => {
    _dlgResolve = resolve;
    _dlgMode = mode;
    const ov  = document.getElementById('dlg-overlay');
    const sh  = document.getElementById('dlg-sheet');
    const tl  = document.getElementById('dlg-title');
    const ms  = document.getElementById('dlg-msg');
    const iw  = document.getElementById('dlg-input-wrap');
    const inp = document.getElementById('dlg-input');
    const ok  = document.getElementById('dlg-ok');
    const ca  = document.getElementById('dlg-cancel');
    const al  = document.getElementById('dlg-actions-list');
    const bt  = document.getElementById('dlg-btns');

    tl.textContent = title;
    ms.textContent = msg;
    ms.style.display = msg ? '' : 'none';
    iw.style.display = mode === 'prompt' ? 'block' : 'none';
    bt.style.display = mode === 'actions' ? 'none' : '';
    al.style.display = mode === 'actions' ? 'flex' : 'none';
    ca.style.display = (mode === 'alert' || mode === 'actions') ? 'none' : '';
    ok.textContent   = okLabel;
    ca.textContent   = cancelLabel;
    ok.className     = 'dlg-btn-ok' + (danger ? ' danger' : '');
    sh.style.borderTop = danger ? '3px solid #ef4444' : 'none';

    if(typeof VlakaKeyboard!=='undefined')VlakaKeyboard.unmount(document.getElementById('dlg-vlaka-keyboard'));
    sh.classList.toggle('dlg-vlaka', mode === 'prompt' && vlakaKeyboard);
    let keyboardHost = document.getElementById('dlg-vlaka-keyboard');
    if (!keyboardHost) { keyboardHost = document.createElement('div'); keyboardHost.id = 'dlg-vlaka-keyboard'; iw.after(keyboardHost); }
    if (mode === 'prompt') {
      inp.type      = inputType;
      inp.inputMode = inputMode;
      inp.value     = inputVal;
      if(vlakaKeyboard && typeof VlakaKeyboard!=='undefined')VlakaKeyboard.mount(inp,keyboardHost);
    }
    if (mode === 'actions') {
      al.innerHTML = actions.map((a, i) =>
        `<button class="dlg-action-btn${a.danger ? ' danger' : ''}" onclick="_dlgAction(${i})">${a.label}</button>`
      ).join('') + `<button class="dlg-btn-cancel" style="width:100%;margin-top:4px;" onclick="_dlgDismiss()">Odustani</button>`;
    }

    sh._dlgEpoch = (sh._dlgEpoch || 0) + 1;
    const dialogEpoch = sh._dlgEpoch;
    ov.classList.add('show');
    requestAnimationFrame(() => sh.classList.add('show'));
    if (mode === 'prompt') {
      // Focus synchronously within the user-gesture stack (iOS/Android require this
      // to show the virtual keyboard — setTimeout breaks the gesture chain)
      inp.focus();
      try { inp.select(); } catch(e) {}
      // Retry after the sheet animation in case focus was lost to the overlay
      setTimeout(() => { if(sh._dlgEpoch !== dialogEpoch || !_dlgResolve || _dlgMode !== mode || !sh.classList.contains('show') || document.activeElement === inp) return; inp.focus(); try { inp.select(); } catch(e) {} }, 280);
    }
  });
}

function _dlgAction(i) {
  _dlgClose();
  const r = _dlgResolve;
  _dlgResolve = null;
  if (r) r(i);
}

function _dlgCommit() {
  const inp = document.getElementById('dlg-input');
  const val = _dlgMode === 'prompt' ? inp.value : (_dlgMode === 'confirm' ? true : undefined);
  _dlgClose();
  const r = _dlgResolve; _dlgResolve = null;
  if (r) r(val);
}

function _dlgDismiss() {
  const val = _dlgMode === 'prompt' ? null : (_dlgMode === 'confirm' ? false : undefined);
  _dlgClose();
  const r = _dlgResolve; _dlgResolve = null;
  if (r) r(val);
}

// v3.119.1: #dlg-overlay je preko CIJELOG ekrana (z-index 999900) i hvata SVAKI
// dodir dok ima klasu 'show' — namjerno, da klik ne "procuri" na ono ispod
// dijaloga. Overlay display:none/block NIJE animatable, pa se sklanjao golim
// setTimeout(...,270) DOK sheet (dlg-sheet) klizi dole svojom CSS tranzicijom.
// Problem: ako WebView baš u tom prozoru bude pauziran (dolazni poziv, prelazak
// na drugu app, gašenje ekrana), taj tajmer zna kasniti ili se (rijetko, na
// starijim WebView verzijama) izgubiti — a overlay ostane TRAJNO 'show', hvata
// svaki dodir na cijeloj aplikaciji, dok ispod izgleda naizgled normalno
// (rgba(0,0,0,0.3) zatamnjenje se lako ne primijeti na jakom terenskom suncu).
// Rezultat izgleda TAČNO kao "nijedno dugme ne reaguje, ni :active boja" —
// bez ijedne JS greške u konzoli, jer JS strana i dalje savršeno radi, samo
// klik nikad ne stigne do dugmeta.
//
// Popravka: sklanjanje se sad veže na STVARAN kraj tranzicije (transitionend),
// ne na nagađanu vrijednost od 270ms — sa timeout-om od 400ms kao REZERVOM za
// slučaj da transitionend nikad ne opali (npr. reducirano kretanje u
// pristupačnosti postavkama isključuje CSS tranzicije pa event ne postoji).
// `done` brani od dvostrukog poziva ako oba puta okinu.
function _dlgClose() {
  const sh = document.getElementById('dlg-sheet');
  const ov = document.getElementById('dlg-overlay');
  document.getElementById('dlg-input')?.blur?.();
  if(typeof VlakaKeyboard!=='undefined')VlakaKeyboard.unmount(document.getElementById('dlg-vlaka-keyboard'));
  const epoch = sh._dlgEpoch;
  sh.classList.remove('show');
  let done = false;
  const finish = () => {
    if (done) return;
    done = true;
    if(sh._dlgEpoch === epoch && !sh.classList.contains('show'))ov.classList.remove('show');
    sh.removeEventListener('transitionend', finish);
  };
  sh.addEventListener('transitionend', finish);
  setTimeout(finish, 400);
}

// Samoisscjeljenje za OSIROTJELI #dlg-overlay (v3.119.1), pozvano iz
// visibilitychange('visible') — vidi opširnu napomenu uz _dlgClose. Ako je
// dijalog VEĆ zatvoren (_dlgResolve je null, niko ne čeka odgovor) a overlay
// je i dalje 'show', to je siguran znak da su transitionend I 400ms rezerva
// OBOJE izgubljeni dok je app bio u pozadini — overlay je preko cijelog
// ekrana i hvata SVAKI dodir, pa se sklanja odmah čim se app vrati u prvi
// plan, ne čekajući da korisnik shvati da mora restartovati aplikaciju.
// NE dira overlay ako je _dlgResolve i dalje postavljen — to znači da
// korisnik ima OTVOREN dijalog na koji legitimno treba odgovoriti (npr.
// otvorio dijalog pa prebacio app, vraća se da odgovori).
// Tastatura i fokusirano polje (v1.7.3). U APK-u MainActivity smanji WebView za
// visinu tastature (IME inset), u browseru to radi interactive-widget u viewport
// meta — pa donji listovi sami stanu iznad tastature. Ovo je treći sloj: polje
// u dugom obrascu/listu koje je i dalje ispod ruba (npr. pri dnu skrolabilnog
// modala) se pomjeri u vidljivo tek kad se viewport stvarno smanjio.
function _tastaturaPoljeVidljivo(el) {
  if (!el || !el.getBoundingClientRect) return false;
  const r = el.getBoundingClientRect();
  const h = (window.visualViewport && window.visualViewport.height) || window.innerHeight;
  return r.top >= 0 && r.bottom <= h - 8;
}
function _tastaturaJeUnos(el) {
  if (!el || !el.tagName) return false;
  const t = el.tagName;
  if (t === 'TEXTAREA' || el.isContentEditable) return true;
  if (t !== 'INPUT') return false;
  return !['checkbox', 'radio', 'range', 'button', 'submit', 'color', 'file', 'hidden'].includes((el.type || '').toLowerCase());
}
function _tastaturaDoPolja() {
  const el = document.activeElement;
  if (!_tastaturaJeUnos(el) || _tastaturaPoljeVidljivo(el)) return;
  try { el.scrollIntoView({ block: 'center', behavior: 'smooth' }); } catch (e) { try { el.scrollIntoView(); } catch (e2) {} }
}
(function () {
  let t = null;
  const kasnije = () => { clearTimeout(t); t = setTimeout(_tastaturaDoPolja, 320); };
  document.addEventListener('focusin', e => { if (_tastaturaJeUnos(e.target)) kasnije(); });
  window.addEventListener('resize', kasnije);
  if (window.visualViewport) window.visualViewport.addEventListener('resize', kasnije);
})();

function _dlgHealOrphanedOverlay() {
  if (_dlgResolve) return false;
  const ov = document.getElementById('dlg-overlay');
  if (!ov || !ov.classList.contains('show')) return false;
  ov.classList.remove('show');
  return true;
}

async function _dlgConfirm(msg, { title = 'Potvrdi', danger = false, okLabel } = {}) {
  return _dlg({ title, msg, mode: 'confirm', danger, okLabel: okLabel || (danger ? 'Obriši' : 'Potvrdi') });
}

async function _dlgPrompt(msg, defaultVal = '', { title = 'Unos', inputType = 'text', inputMode = 'text', okLabel = 'OK', vlakaKeyboard = false } = {}) {
  return _dlg({ title, msg, mode: 'prompt', inputVal: defaultVal, inputType, inputMode, okLabel, vlakaKeyboard });
}

async function _dlgActions(title, actionList) {
  return _dlg({ title, mode: 'actions', actions: actionList });
}

// Enter key submits prompt/confirm dialogs
document.addEventListener('keydown', e => {
  if (!document.getElementById('dlg-sheet')?.classList.contains('show')) return;
  if (e.key === 'Enter' && _dlgMode !== 'actions') { e.preventDefault(); _dlgCommit(); }
  if (e.key === 'Escape') { e.preventDefault(); _dlgDismiss(); }
});

// === KML IZ SUPABASE STORAGE — automatsko učitavanje ===
let graniceOdjeli = []; // [{ name, bounds }] — za print/offline dropdown

// Izvuci placemark bounds iz KML dokumenta u graniceOdjeli[]
function _extractGraniceOdjeli(doc) {
  doc.querySelectorAll('Placemark').forEach(pm => {
    const name = pm.querySelector('name')?.textContent?.trim() || '';
    if (!name || graniceOdjeli.find(o => o.name === name)) return;
    const allPts = [];
    let ring = null; // najveći outer ring (za shape matching)
    // Pokušaj outerBoundaryIs za Polygon
    const outerC = pm.querySelector('Polygon outerBoundaryIs coordinates, outerBoundaryIs coordinates');
    if (outerC) {
      ring = pcs(outerC.textContent);
      ring.forEach(pt => allPts.push(pt));
      // Dodaj i innerBoundaryIs ako postoji
      pm.querySelectorAll('innerBoundaryIs coordinates').forEach(c => pcs(c.textContent).forEach(pt => allPts.push(pt)));
    } else {
      // Fallback: sve coordinates
      pm.querySelectorAll('coordinates').forEach(c => {
        const pts = pcs(c.textContent);
        pts.forEach(pt => allPts.push(pt));
        if (!ring || pts.length > ring.length) ring = pts;
      });
    }
    if (allPts.length > 0) graniceOdjeli.push({ name, bounds: L.latLngBounds(allPts), ring: ring || null });
  });
  graniceOdjeli.sort((a, b) => a.name.localeCompare(b.name, 'bs'));
  _refreshProjektOdjelHighlight();
}

// ── GeoJSON odjeli ────────────────────────────────────────────────────────────
const _GEOJSON_LS_KEY = 'tvlake_geojson_odjeli';
let _geojsonLayer = null;
let _geojsonVisible = localStorage.getItem('tvlake_granice_visible') !== '0';
let _geojsonOpacity = parseFloat(localStorage.getItem('tvlake_granice_opacity') || '1');
let _projektOdjelLayer = null;  // highlight polygon aktivnog projekta

function _findGraniceMatch(name, gj) {
  const list = _odjeliForGj(gj);
  return _findOdjelInList(list, name);
}

function _hideProjektOdjelHighlight() {
  if (_projektOdjelLayer) { try { map.removeLayer(_projektOdjelLayer); } catch(e) {} _projektOdjelLayer = null; }
}

function _showProjektOdjelHighlight(odjelName, gj) {
  _hideProjektOdjelHighlight();
  if(typeof ProjectTerrain!=='undefined'&&ProjectTerrain.dataFor()?.ring)return;
  const match = _findGraniceMatch(odjelName, gj);
  if (!match?.ring) return;
  _projektOdjelLayer = L.polygon(match.ring, {
    color: '#f97316', weight: 2.5, opacity: 0.85,
    fillColor: '#f97316', fillOpacity: 0.07,
    dashArray: '7,5', pane: 'putevi'
  }).addTo(map);
  _projektOdjelLayer.bindTooltip('📂 ' + match.name, { sticky: true, className: 'leaflet-tooltip' });
}

function _refreshProjektOdjelHighlight() {
  if (!_aktivniProjektId) return;
  const p = _projekti.find(x => x.id === _aktivniProjektId);
  if (p?.odjel) _showProjektOdjelHighlight(p.odjel, p.gj);
}

function _gjPropName(props) {
  // Auto-detect which property contains the odjel name
  for (const k of ['naziv','Naziv','NAZIV','name','Name','NAME','odjel','Odjel','ODJEL','id','ID','šifra','SIFRA']) {
    if (props[k] != null && String(props[k]).trim()) return String(props[k]).trim();
  }
  // Fallback: first string property
  for (const v of Object.values(props || {})) {
    if (typeof v === 'string' && v.trim()) return v.trim();
  }
  return '';
}

function _gjExtractRing(geom) {
  if (!geom) return null;
  let coords = null;
  if (geom.type === 'Polygon') {
    coords = geom.coordinates[0];
  } else if (geom.type === 'MultiPolygon') {
    let maxLen = 0;
    geom.coordinates.forEach(poly => { if (poly[0].length > maxLen) { maxLen = poly[0].length; coords = poly[0]; } });
  }
  if (!coords) return null;
  return coords.map(([lon, lat]) => [lat, lon]);
}

function _applyGeoJSONOdjeli(data) {
  if (!data?.features?.length) return 0;
  if (_geojsonLayer) { try { map.removeLayer(_geojsonLayer); } catch(e) {} _geojsonLayer = null; }

  let added = 0;
  // D1-F: O(1) dedup preko Set-a umjesto O(n) .find() po feature-u (kvadratno za
  // fajlove s hiljadama odjela — mogao je vidljivo zaglaviti glavnu nit pri učitavanju).
  const existingNames = new Set(graniceOdjeli.map(o => o.name));
  data.features.forEach(f => {
    if (!f.geometry) return;
    const name = _gjPropName(f.properties || {});
    if (!name) return;
    const ring = _gjExtractRing(f.geometry);
    if (!ring || ring.length < 3) return;
    if (!existingNames.has(name)) {
      graniceOdjeli.push({ name, bounds: L.latLngBounds(ring), ring, _fromGeojson: true });
      existingNames.add(name);
      added++;
    }
  });
  graniceOdjeli.sort((a, b) => a.name.localeCompare(b.name, 'bs'));

  _geojsonLayer = L.geoJSON(data, {
    style: { color: '#38bdf8', weight: 1.5, opacity: _geojsonOpacity, fillColor: '#38bdf8', fillOpacity: _geojsonOpacity * 0.04, dashArray: '4,4' },
    onEachFeature(f, layer) {
      const name = _gjPropName(f.properties || {});
      // D1-F (sigurnosni): escape — GeoJSON dolazi iz uvezenog fajla, isti XSS
      // sink kao KML <name> koji smo ranije popravili (bindTooltip = innerHTML).
      if (name) layer.bindTooltip(_escHtml(name), { sticky: true, className: 'leaflet-tooltip' });
    }
  });
  if (_geojsonVisible) _geojsonLayer.addTo(map);
  _refreshProjektOdjelHighlight();
  return added;
}

function loadGeoJSONOdjeli(file) {
  if (!file) return;
  const reader = new FileReader();
  reader.onload = e => {
    try {
      const data = JSON.parse(e.target.result);
      // Remove previously loaded geojson entries from graniceOdjeli
      graniceOdjeli = graniceOdjeli.filter(o => !o._fromGeojson);
      const added = _applyGeoJSONOdjeli(data);
      // Persist (cap at 4 MB to avoid localStorage overflow)
      try {
        if (e.target.result.length < 4 * 1024 * 1024) {
          localStorage.setItem(_GEOJSON_LS_KEY, e.target.result);
        } else {
          // Store compact rings only
          const compact = { _compact: true, odjeli: graniceOdjeli.filter(o => o._fromGeojson).map(o => ({ name: o.name, ring: o.ring })) };
          localStorage.setItem(_GEOJSON_LS_KEY, JSON.stringify(compact));
        }
      } catch(ex) {}
      _geojsonOdjeliUpdUI(data.features?.length || 0, added);
      // Osvježi layer sheet — pojavi se "Topo + Granice" dugme
      const grRow = document.getElementById('ls-granice-row');
      if (grRow && _geojsonLayer) grRow.style.display = 'block';
      showToast('GeoJSON učitan: ' + added + ' novih odjela');
    } catch(ex) {
      showToast('❌ GeoJSON greška: ' + ex.message);
    }
  };
  reader.readAsText(file);
}

function _geojsonOdjeliClear() {
  if (_geojsonLayer) { try { map.removeLayer(_geojsonLayer); } catch(e) {} _geojsonLayer = null; }
  graniceOdjeli = graniceOdjeli.filter(o => !o._fromGeojson);
  try { localStorage.removeItem(_GEOJSON_LS_KEY); } catch(e) {}
  _geojsonOdjeliUpdUI(0, 0);
  showToast('GeoJSON odjeli uklonjeni');
}

function _geojsonToggleVis(val) {
  _geojsonVisible = (val !== undefined) ? !!val : !_geojsonVisible;
  if (_geojsonLayer) {
    if (_geojsonVisible) _geojsonLayer.addTo(map); else map.removeLayer(_geojsonLayer);
  }
  try { localStorage.setItem('tvlake_granice_visible', _geojsonVisible ? '1' : '0'); } catch(e) {}
  _geojsonOdjeliUpdUI();
  _lsRenderGranice();
}

function _geojsonSetOpacity(val) {
  _geojsonOpacity = parseFloat(val);
  if (_geojsonLayer) _geojsonLayer.setStyle({ opacity: _geojsonOpacity, fillOpacity: _geojsonOpacity * 0.04 });
  try { localStorage.setItem('tvlake_granice_opacity', String(_geojsonOpacity)); } catch(e) {}
}

function _lsRenderGranice() {
  if(typeof window!=='undefined'&&window.GithubLayers){window.GithubLayers.render();return;}
  const cb = document.getElementById('granice-toggle');
  if (cb) cb.checked = _geojsonVisible;
  const slider = document.getElementById('ls-granice-opacity');
  if (slider) slider.value = _geojsonOpacity;
}

function _geojsonOdjeliUpdUI(total, added) {
  const el = document.getElementById('geojson-odjeli-info');
  if (!el) return;
  const cnt = graniceOdjeli.filter(o => o._fromGeojson).length;
  if (cnt === 0) {
    el.innerHTML = '<span style="color:#475569;">Nije učitan GeoJSON fajl.</span>';
    return;
  }
  el.innerHTML = `
    <span style="color:#4ade80;">${cnt} odjela učitano</span>
    <button onclick="_geojsonToggleVis()" style="margin-left:8px;background:#1e293b;border:1px solid #334155;color:#94a3b8;border-radius:5px;padding:2px 8px;font-size:10px;cursor:pointer;">
      ${_geojsonVisible ? '<svg class="ic"><use href="#ic-prikazi"/></svg> Vidljivo' : '<svg class="ic"><use href="#ic-sakrij"/></svg> Skriveno'}
    </button>
    <button onclick="_geojsonOdjeliClear()" style="margin-left:4px;background:#2d0a0a;border:1px solid #7f1d1d;color:#f87171;border-radius:5px;padding:2px 8px;font-size:10px;cursor:pointer;">
      <svg class="ic"><use href="#ic-zatvori"/></svg> Ukloni
    </button>`;
}

function geojsonOdjeliRestore() {
  try {
    const raw = localStorage.getItem(_GEOJSON_LS_KEY);
    if (!raw) return;
    const data = JSON.parse(raw);
    if (data._compact) {
      // Restore from compact rings (fajlovi ≥4MB) — ring podaci su dovoljni da se
      // rekonstruiše i VIZUELNI sloj, ne samo graniceOdjeli pretraga/highlight
      // (D1-D: prije ovog fix-a je plavi overlay/„Topo + Granice" dugme nestajao
      // nakon reload-a baš za najveće/najčešće kadastarske fajlove).
      const existingNames = new Set(graniceOdjeli.map(g => g.name));  // D1-F: O(1) dedup
      data.odjeli.forEach(o => {
        if (o.name && o.ring?.length >= 3 && !existingNames.has(o.name)) {
          graniceOdjeli.push({ name: o.name, bounds: L.latLngBounds(o.ring), ring: o.ring, _fromGeojson: true });
          existingNames.add(o.name);
        }
      });
      graniceOdjeli.sort((a, b) => a.name.localeCompare(b.name, 'bs'));
      _refreshProjektOdjelHighlight();
      _geojsonOdjeliUpdUI();

      if (_geojsonLayer) { try { map.removeLayer(_geojsonLayer); } catch(e) {} _geojsonLayer = null; }
      const polys = data.odjeli
        .filter(o => o.ring?.length >= 3)
        .map(o => L.polygon(o.ring, {
          color: '#38bdf8', weight: 1.5, opacity: _geojsonOpacity,
          fillColor: '#38bdf8', fillOpacity: _geojsonOpacity * 0.04, dashArray: '4,4'
        }).bindTooltip(_escHtml(o.name), { sticky: true, className: 'leaflet-tooltip' }));
      if (polys.length) {
        _geojsonLayer = L.featureGroup(polys);
        if (_geojsonVisible) _geojsonLayer.addTo(map);
      }
      const grRow = document.getElementById('ls-granice-row');
      if (grRow && _geojsonLayer) grRow.style.display = 'block';
    } else {
      _applyGeoJSONOdjeli(data);
      _geojsonOdjeliUpdUI();
    }
  } catch(e) {}
}


// ── Proj4 definicije za Bosanske koordinatne sisteme ─────────────────────────
proj4.defs('EPSG:31276', '+proj=tmerc +lat_0=0 +lon_0=18 +k=0.9999 +x_0=6500000 +y_0=0 +ellps=bessel +towgs84=682,-203,480,0,0,0,0 +units=m +no_defs');
proj4.defs('EPSG:31275', '+proj=tmerc +lat_0=0 +lon_0=15 +k=0.9999 +x_0=5500000 +y_0=0 +ellps=bessel +towgs84=682,-203,480,0,0,0,0 +units=m +no_defs');
proj4.defs('EPSG:3908',  '+proj=tmerc +lat_0=0 +lon_0=18 +k=0.9999 +x_0=6500000 +y_0=0 +ellps=bessel +towgs84=682,-203,480,0,0,0,0 +units=m +no_defs');
// MGI 1901 Balkans Zone 6 i Zone 5 (alias)
proj4.defs('MGI_Z6', proj4.defs('EPSG:31276'));
proj4.defs('MGI_Z5', proj4.defs('EPSG:31275'));

// ── PRJ → proj4 string parser ─────────────────────────────────────────────────
function _prjToProj4(prjText) {
  if (!prjText) return null;
  // Ako je već WGS84
  if (/WGS.?84|EPSG.*4326/i.test(prjText)) return null; // null = već WGS84, nema potrebe
  if (/Zone_6|6500000|31276|3908/i.test(prjText)) return 'EPSG:31276';
  if (/Zone_5|5500000|31275/i.test(prjText)) return 'EPSG:31275';
  return null; // nepoznat → pretpostavi WGS84
}

// ═══ TEMATSKA KARTA (.gpkg) — bojenje odjela/odsjeka po atributima ═══════════
// Korisnik učita master_odsjeci.gpkg s uređaja; numeričke kolone postaju teme
// (automatski kvantili, 5 klasa); klik na poligon daje karticu s atributima.
const _TEM_REG_KEY   = 'tvlake_tem_reg_v1';      // registar učitanih karata (bez geometrije)
const _TEM_IDB_PFX   = 'tematska_gpkg_';          // IDB ključ po karti: prefiks + id
const _TEM_IDB_KEY   = 'tematska_gpkg_v1';        // legacy (v3.11.0 single-map) — migrira se
const _TEM_NAME_KEY  = 'tvlake_tem_name';         // legacy
const _TEM_THEME_KEY = 'tvlake_tem_theme';        // legacy
/* @izdvojeno static/js/app/tematska-karta.js */
// ── Rekurzivno listanje Supabase bucketa (root + svi podfolderi) ──────────────
async function _listBucketAll(bucketName, path = '') {
  const { data, error } = await sb.storage.from(bucketName).list(path, { limit: 500 });
  if (error || !data) return [];
  const results = [];
  for (const item of data) {
    const fullPath = path ? `${path}/${item.name}` : item.name;
    if (!item.id && !item.metadata) {
      // To je folder — rekurzivno
      const sub = await _listBucketAll(bucketName, fullPath);
      results.push(...sub);
    } else {
      results.push({ name: item.name, path: fullPath, folder: path });
    }
  }
  return results;
}

// ── URL za fajl u bucketu ────────────────────────────────────────────────────
function _bucketFileUrl(bucketName, filePath) {
  const parts = filePath.split('/').map(encodeURIComponent).join('/');
  return `${SUPA_URL}/storage/v1/object/public/${encodeURIComponent(bucketName)}/${parts}`;
}

// ── KML/SHP offline cache (IndexedDB) ─────────────────────────────────────────
const _KMLC_DB    = 'tvlake-kml-cache-v1';
const _KMLC_STORE = 'files';
let   _kmlcDB   = null;
let   _kmlcKeys = new Set(); // all keys currently stored in IDB

async function _kmlcOpen() {
  if (_kmlcDB) return _kmlcDB;
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(_KMLC_DB, 1);
    req.onupgradeneeded = e => e.target.result.createObjectStore(_KMLC_STORE);
    req.onsuccess = e => { _kmlcDB = e.target.result; resolve(_kmlcDB); };
    req.onerror   = e => reject(e.target.error);
  });
}

async function _kmlcSave(key, data) {
  try {
    const db = await _kmlcOpen();
    await new Promise((resolve, reject) => {
      const tx = db.transaction(_KMLC_STORE, 'readwrite');
      tx.objectStore(_KMLC_STORE).put(data, key);
      tx.onabort = () => reject(tx.error || new Error('Čuvanje prekinuto'));
      tx.oncomplete = resolve;
      tx.onerror    = e => reject(e.target.error);
    });
    _kmlcKeys.add(key);
    return true;
  } catch(e) { console.warn('_kmlcSave err', key, e); return false; }
}

async function _kmlcGet(key) {
  try {
    const db = await _kmlcOpen();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(_KMLC_STORE, 'readonly');
      const req = tx.objectStore(_KMLC_STORE).get(key);
      req.onsuccess = e => resolve(e.target.result ?? null);
      req.onerror   = e => reject(e.target.error);
    });
  } catch { return null; }
}

async function _kmlcDelete(key) {
  try {
    const db = await _kmlcOpen();
    await new Promise((resolve, reject) => {
      const tx = db.transaction(_KMLC_STORE, 'readwrite');
      tx.objectStore(_KMLC_STORE).delete(key);
      tx.oncomplete = resolve;
      tx.onerror    = e => reject(e.target.error);
    });
    _kmlcKeys.delete(key);
  } catch(e) { console.warn('_kmlcDelete err', key, e); }
}

async function _kmlcInit() {
  try {
    const db = await _kmlcOpen();
    const keys = await new Promise((resolve, reject) => {
      const tx = db.transaction(_KMLC_STORE, 'readonly');
      const req = tx.objectStore(_KMLC_STORE).getAllKeys();
      req.onsuccess = e => resolve(e.target.result);
      req.onerror   = e => reject(e.target.error);
    });
    keys.forEach(k => _kmlcKeys.add(k));
  } catch(e) { console.warn('_kmlcInit err', e); }
}

// Download all files in a group to IDB
async function _kmlcDownloadGroup(items) {
  let saved = 0;
  for (const {k} of items) {
    const slash = k._key.indexOf('/');
    const bucketName = k._key.slice(0, slash);
    const filePath   = k._key.slice(slash + 1);
    const isBin = /\.(shp|dbf)$/i.test(filePath);
    const type  = isBin ? 'arraybuffer' : 'text';
    try {
      const r = await _fetchT(_bucketFileUrl(bucketName, filePath), 15000, { headers: { apikey: SUPA_KEY } });
      if (!r.ok) continue;
      const data = isBin ? await r.arrayBuffer() : await r.text();
      await _kmlcSave('file:' + k._key, data);
      saved++;
      // For SHP also cache companion .dbf and .prj
      if (/\.shp$/i.test(filePath)) {
        const base = filePath.replace(/\.shp$/i, '');
        for (const ext of ['.dbf', '.prj']) {
          const cKey = 'file:' + bucketName + '/' + base + ext;
          if (_kmlcKeys.has(cKey)) continue;
          try {
            const r2 = await _fetchT(_bucketFileUrl(bucketName, base + ext), 15000, { headers: { apikey: SUPA_KEY } });
            if (!r2.ok) continue;
            const d2 = ext === '.prj' ? await r2.text() : await r2.arrayBuffer();
            await _kmlcSave(cKey, d2);
          } catch {}
        }
      }
    } catch(e) { console.warn('_kmlcDownloadGroup fetch err', k._key, e); }
  }
  return saved;
}

// Delete cached files for a group from IDB
async function _kmlcDeleteGroup(items) {
  for (const {k} of items) {
    await _kmlcDelete('file:' + k._key);
    if (/\.shp$/i.test(k._key)) {
      const base = k._key.replace(/\.shp$/i, '');
      for (const ext of ['.dbf', '.prj']) await _kmlcDelete('file:' + base + ext);
    }
  }
}

// Samo već preuzeti server fajlovi: obnovi iz IDB bez listinga i mrežnih poziva.
async function _serverKmlRestore() {
  if (_serverKmlRestore._pending) return _serverKmlRestore._pending;
  const owner=sbUser?.id;
  const work=(async()=>{
    for(const cacheKey of [..._kmlcKeys]) {
      if(sbUser?.id!==owner)return;
      if(typeof cacheKey!=='string'||!cacheKey.startsWith('file:')||! /\.(kml|shp)$/i.test(cacheKey))continue;
      const key=cacheKey.slice(5),slash=key.indexOf('/');if(slash<1)continue;
      const bucket=key.slice(0,slash),path=key.slice(slash+1);
      if(kmlLs.some(k=>k._key===key&&k.grp))continue;
      const placeholder=kmlLs.find(k=>k._key===key&&!k.grp);
      if(placeholder)kmlLs.splice(kmlLs.indexOf(placeholder),1);
      const file={path,name:path.split('/').pop(),folder:path.includes('/')?path.slice(0,path.lastIndexOf('/')):''};
      try {
        if(/\.shp$/i.test(path))await _loadOneShp(bucket,file,placeholder?._srvOpts||{color:'#22c55e'},false,null,true);
        else await _loadOneKml(bucket,file,placeholder?._srvOpts||{color:'#22c55e'},false,true);
      } catch(e) { console.warn('Server fajl: lokalna obnova nije uspjela',key,e); }
      if(sbUser?.id===owner&&!kmlLs.some(k=>k._key===key)&&placeholder)kmlLs.push(placeholder);
    }
    if(sbUser?.id===owner){if(typeof rndKml==='function')rndKml();_rndOznakePanel();}
  })();
  _serverKmlRestore._pending=work;
  try { await work; } finally { _serverKmlRestore._pending=null; }
}

// ── OPT-IN server fajlovi ────────────────────────────────────────────────────
// Registruj dostupan server fajl BEZ preuzimanja/rendera — placeholder u panelu.
function _registerServerPlaceholder(bucketName, file, opts, extractOdjeli) {
  const key = bucketName + '/' + file.path;
  if (kmlLs.find(k => k._key === key)) return; // dedup (ili već skinut)
  const label = file.folder ? `${file.folder.split('/').pop()}/${file.name}` : file.name;
  const col = (opts && (opts.color || opts.col)) || '#22c55e';
  kmlLs.push({ name: label, _key: key, _bucket: bucketName, _folder: file.folder || '',
    grp: null, _downloaded: false, _srvOpts: opts || {}, _srvExtract: !!extractOdjeli,
    col, dash: (opts && (opts.dashArray || opts.dash)) || '', weight: (opts && opts.weight) || 2,
    opacity: (opts && opts.opacity) ?? 0.9, vis: false,
    fill: false, fillCol: col, fillPattern: 'solid', fillOpacity: 0.35,
    tag: '', _loadedAt: Date.now() });
}

// _key nizovi se prosljeđuju kroz onclick kao base64(JSON) — izbjegava lomljenje HTML
// atributa navodnicima iz putanja fajlova. Prima i sirov niz (interni pozivi).
function _b64keys(arr) { return btoa(unescape(encodeURIComponent(JSON.stringify(arr)))); }
function _srvDecodeKeys(arg) {
  if (Array.isArray(arg)) return arg;
  try { return JSON.parse(decodeURIComponent(escape(atob(arg)))); }
  catch { try { return JSON.parse(arg); } catch { return []; } }
}

// Preuzmi (za offline) + učitaj na kartu jedan ili više server fajlova po _key.
async function _srvDownload(keysArg) {
  const keys = _srvDecodeKeys(keysArg);
  if (!keys.length) return;
  showToast('⬇ Preuzimam fajlove za offline...');
  let saved = 0;
  for (const key of keys) {
    const idx = kmlLs.findIndex(k => k._key === key);
    if (idx < 0) continue;
    const entry = kmlLs[idx];
    if (entry._downloaded) continue;
    const slash = key.indexOf('/');
    const bucketName = key.slice(0, slash);
    const filePath   = key.slice(slash + 1);
    const fileObj = { path: filePath, name: filePath.split('/').pop(), folder: entry._folder || '' };
    const opts = entry._srvOpts || {};
    const extract = entry._srvExtract;
    // Ukloni placeholder pa pusti _loadOne* da fetch-uje (→ IDB keš), parsira i renderuje.
    kmlLs.splice(idx, 1);
    try {
      if (/\.shp$/i.test(filePath)) await _loadOneShp(bucketName, fileObj, opts, extract, null);
      else                          await _loadOneKml(bucketName, fileObj, opts, extract);
    } catch(e) { console.warn('_srvDownload load err', key, e); }
    const nk = kmlLs.find(k => k._key === key);
    if (nk) {
      nk._downloaded = true; nk.vis = true;
      if (nk.grp && !map.hasLayer(nk.grp)) nk.grp.addTo(map);
      // ukloni eventualni raniji vis:false override
      try {
        const um = JSON.parse(localStorage.getItem(_KML_USER_STYLES_KEY) || '{}');
        if (um[key]) { um[key].vis = true; localStorage.setItem(_KML_USER_STYLES_KEY, JSON.stringify(um)); }
      } catch {}
      saved++;
    } else {
      // Fetch pao (offline/greška) — vrati placeholder da ostane u listi
      _registerServerPlaceholder(bucketName, fileObj, opts, extract);
    }
  }
  showToast(saved ? `✅ ${saved} fajl${saved === 1 ? '' : 'a'} sačuvano offline` : '⚠ Preuzimanje nije uspjelo — provjeri vezu');
  rndKml(); _rndOznakePanel();
}

// Obriši offline kopiju + skloni s karte; ostaje kao placeholder za ponovno skidanje.
async function _srvDelete(keysArg) {
  const keys = _srvDecodeKeys(keysArg);
  if (!keys.length) return;
  for (const key of keys) {
    await _kmlcDelete('file:' + key);
    if (/\.shp$/i.test(key)) {
      const base = key.replace(/\.shp$/i, '');
      for (const ext of ['.dbf', '.prj']) await _kmlcDelete('file:' + base + ext);
    }
    const idx = kmlLs.findIndex(k => k._key === key);
    if (idx >= 0) {
      const e = kmlLs[idx];
      if (e.grp) { try { map.removeLayer(e.grp); } catch(_) {} }
      // Konvertuj nazad u placeholder (ostaje listan, ne renderuje se dok se ne skine)
      e.grp = null; e._downloaded = false; e.vis = false;
      e._srvOpts = e._srvOpts || {};
    }
    _kmlPersistHidden(key);
  }
  showToast('🗑 Offline kopija obrisana — fajl uklonjen s karte');
  rndKml(); _rndOznakePanel();
}

// ── Fetch helper ──────────────────────────────────────────────────────────────
async function _fetchBucketFile(bucketName, filePath, type = 'text', cacheOnly = false) {
  if (cacheOnly) return _kmlcGet('file:' + bucketName + '/' + filePath);
  const cacheKey = 'file:' + bucketName + '/' + filePath;
  try {
    const r = await _fetchT(_bucketFileUrl(bucketName, filePath), 15000, { headers: { 'apikey': SUPA_KEY } });
    if (!r.ok) throw new Error('HTTP ' + r.status);
    const data = type === 'arraybuffer' ? await r.arrayBuffer() : await r.text();
    _kmlcSave(cacheKey, data); // fire-and-forget
    return data;
  } catch {
    if (_kmlcKeys.has(cacheKey)) return _kmlcGet(cacheKey);
    return null;
  }
}

// ── Učitaj jedan KML fajl ────────────────────────────────────────────────────
async function _loadOneKml(bucketName, file, opts, extractOdjeli, cacheOnly=false) {
  const owner=sbUser?.id;
  const key = bucketName + '/' + file.path;
  if (kmlLs.find(k => k._key === key)) return null; // dedup
  const txt = await _fetchBucketFile(bucketName, file.path, 'text',cacheOnly);
  if (sbUser?.id!==owner || (cacheOnly && !_kmlcKeys.has('file:'+key))) return null;
  if (!txt) { console.warn('KML fetch fail:', file.path); return null; }
  const doc = new DOMParser().parseFromString(txt, 'text/xml');
  if (extractOdjeli) _extractGraniceOdjeli(doc);
  const saved = loadKmlStyleFor(key, {});
  const finalOpts = { ...opts, ...saved };
  const grp = pkmlStyled(doc, finalOpts);
  grp.addTo(map);
  const label = file.folder ? `${file.folder.split('/').pop()}/${file.name}` : file.name;
  const _fc = finalOpts.col || finalOpts.color;
  kmlLs.push({ name: label, _key: key, _bucket: bucketName, _folder: file.folder || '', grp,
    col: _fc, dash: finalOpts.dashArray || finalOpts.dash || '',
    weight: finalOpts.weight || 2, opacity: finalOpts.opacity ?? 0.9,
    vis: finalOpts.vis !== false,
    fill: finalOpts.fill===true, fillCol: finalOpts.fillCol||_fc, fillPattern: finalOpts.fillPattern||'solid', fillOpacity: finalOpts.fillOpacity??0.35,
    onlyPolygon: finalOpts.onlyPolygon===true, tag: finalOpts.tag||'', _loadedAt: Date.now(), _downloaded: true });
  applyKmlStyle(kmlLs.length-1);
  // Apply visibility
  if (finalOpts.vis === false) map.removeLayer(grp);
  return grp;
}

// ── Učitaj jedan SHP fajl (+ .dbf + .prj ako postoje) ───────────────────────
async function _loadOneShp(bucketName, file, opts, extractOdjeli, existingPaths, cacheOnly=false) {
  const owner=sbUser?.id;
  if (typeof shapefile === 'undefined') { console.warn('shapefile.js nije učitan'); return null; }
  const key = bucketName + '/' + file.path;
  if (kmlLs.find(k => k._key === key)) return null; // dedup

  const basePath = file.path.replace(/\.shp$/i, '');
  // Companion .dbf/.prj — traži samo ako postoje u listingu (izbjegni 400 greške).
  // Provjera neosjetljiva na velika/mala slova jer ekstenzije variraju (.PRJ, .Dbf...)
  const _companion = (ext) => {
    if (!existingPaths) return basePath + ext; // bez listinga — pokušaj svejedno
    const lo = (basePath + ext).toLowerCase();
    for (const p of existingPaths) { if (p.toLowerCase() === lo) return p; }
    return null;
  };
  const dbfPath = _companion('.dbf');
  const prjPath = _companion('.prj');
  const [shpBuf, dbfBuf, prjTxt] = await Promise.all([
    _fetchBucketFile(bucketName, file.path, 'arraybuffer',cacheOnly),
    dbfPath ? _fetchBucketFile(bucketName, dbfPath, 'arraybuffer',cacheOnly) : Promise.resolve(null),
    prjPath ? _fetchBucketFile(bucketName, prjPath, 'text',cacheOnly) : Promise.resolve(null),
  ]);
  if(sbUser?.id!==owner || (cacheOnly && !_kmlcKeys.has('file:'+key))) return null;
  if (!shpBuf) { console.warn('SHP fetch fail:', file.path); return null; }

  // Odredi projekciju iz .prj
  let fromCrs = _prjToProj4(prjTxt);

  let geojson;
  try {
    geojson = await shapefile.read(shpBuf, dbfBuf || undefined);
  } catch(e) { console.warn('SHP parse error:', file.name, e.message); return null; }

  if(sbUser?.id!==owner || (cacheOnly && !_kmlcKeys.has('file:'+key))) return null;

  // Fallback: ako nema .prj a koordinate su očito projecirane (metri, van
  // lat/lon opsega), pretpostavi MGI Zone 6 (najčešći CRS za BiH katastar).
  if (!fromCrs && !prjTxt) {
    const sample = _firstCoord(geojson.features?.[0]?.geometry);
    if (sample && (Math.abs(sample[0]) > 180 || Math.abs(sample[1]) > 90)) {
      fromCrs = 'EPSG:31276';
      console.info('SHP bez .prj —', file.name, '→ pretpostavljen MGI Zone 6 (EPSG:31276)');
    }
  }

  // Reprojekcija koordinata ako nije WGS84
  if (fromCrs) {
    geojson.features.forEach(f => {
      _reprojectGeometry(f.geometry, fromCrs);
    });
  }

  // Ime featurea iz .dbf atributa (pokušaj česta polja)
  const NAME_FIELDS = ['ODJEL', 'OznakaOdj', 'Odjel', 'ODSJEK', 'Odsjek', 'NAZIV', 'Naziv', 'NAME', 'Name', 'Oznaka', 'Broj', 'ID', 'OBJECTID'];

  const savedShp = loadKmlStyleFor(key, {});
  const finalOptsShp = { ...opts, ...savedShp };
  // Build Leaflet style from merged options
  const shpStyle = {
    color: finalOptsShp.col || finalOptsShp.color || (opts.col || opts.color),
    weight: finalOptsShp.weight || opts.weight || 2,
    opacity: finalOptsShp.opacity ?? opts.opacity ?? 0.9,
  };
  if (finalOptsShp.dash || finalOptsShp.dashArray) shpStyle.dashArray = finalOptsShp.dash || finalOptsShp.dashArray;

  const grp = L.featureGroup();
  geojson.features.forEach(f => {
    const nm = NAME_FIELDS.map(k => f.properties?.[k]).find(v => v != null) ?? '';
    const styleOpts = { ...shpStyle };
    try {
      const layer = L.geoJSON(f, {
        style: () => styleOpts,
        pointToLayer: (_, ll) => L.circleMarker(ll, { radius: 4, ...styleOpts }),
      });
      if (nm) layer.bindTooltip(_escHtml(String(nm)), { sticky: true, opacity: 0.9 });
      // Isti info-popup kao za KML: SHP je u istoj listi "Granice" i korisnik s
      // razlogom očekuje da se i on može kliknuti. Atributi iz .dbf-a idu u
      // _kmlExtData pa se prikažu kao tabela u popupu.
      layer.eachLayer(child => {
        const gt = f.geometry?.type || '';
        child._kmlIsPolygon = /Polygon/.test(gt);
        child._kmlIsPoint   = /Point/.test(gt);
        child._kmlName    = nm ? String(nm) : '';
        child._kmlDesc    = '';
        child._kmlExtData = f.properties || {};
        _bindKmlPopup(child);
      });
      layer.addTo(grp);
      // Permanentna labela na centru poligona
      if (nm && f.geometry && (f.geometry.type === 'Polygon' || f.geometry.type === 'MultiPolygon')) {
        try {
          const center = layer.getBounds().getCenter();
          _kmlLabelMarker([center.lat, center.lng], String(nm)).addTo(grp);
        } catch {}
      }

      // Ekstrakcija bounds za odjele
      if (extractOdjeli && nm) {
        const nmStr = String(nm);
        if (!graniceOdjeli.find(o => o.name === nmStr)) {
          try {
            const b = layer.getBounds();
            if (b.isValid()) graniceOdjeli.push({ name: nmStr, bounds: b });
          } catch {}
        }
      }
    } catch {}
  });
  if (extractOdjeli) graniceOdjeli.sort((a,b) => a.name.localeCompare(b.name, 'bs'));

  if (finalOptsShp.vis === false) map.removeLayer(grp);
  else grp.addTo(map);
  const label = file.folder ? `${file.folder.split('/').pop()}/${file.name}` : file.name;
  kmlLs.push({ name: label, _key: key, _bucket: bucketName, _folder: file.folder || '', grp,
    col: shpStyle.color, dash: shpStyle.dashArray || '',
    weight: shpStyle.weight, opacity: shpStyle.opacity,
    vis: finalOptsShp.vis !== false, fill: finalOptsShp.fill===true,fillCol:finalOptsShp.fillCol||shpStyle.color,fillPattern:finalOptsShp.fillPattern||'solid',fillOpacity:finalOptsShp.fillOpacity??0.35,tag:finalOptsShp.tag||'',_downloaded: true });
  applyKmlStyle(kmlLs.length-1);
  return grp;
}

// ── Reprojekcija geometrije in-place (GeoJSON coords) ────────────────────────
// Prva [x,y] koordinata iz geometrije (za detekciju projekcije)
function _firstCoord(geom) {
  if (!geom) return null;
  let c = geom.coordinates;
  if (!c && geom.geometries) c = geom.geometries[0]?.coordinates;
  while (Array.isArray(c) && Array.isArray(c[0])) c = c[0];
  return (Array.isArray(c) && typeof c[0] === 'number') ? c : null;
}

function _reprojectGeometry(geom, fromCrs) {
  if (!geom) return;
  const conv = c => proj4(fromCrs, 'WGS84', c); // [x,y] → [lon,lat]
  const reprCoords = arr => {
    if (!Array.isArray(arr)) return arr;
    if (typeof arr[0] === 'number') return conv(arr);
    return arr.map(reprCoords);
  };
  if (geom.coordinates) geom.coordinates = reprCoords(geom.coordinates);
  if (geom.geometries)  geom.geometries.forEach(g => _reprojectGeometry(g, fromCrs));
}


// Poziva se iz sbInitData() nakon prijave
// Bucketi (Granice odjela, ODJELI_ODSJECI, odsjeci SQLite) su namjerno obrisani
// sa Supabase Storage-a — ne pokušavaj ih više učitati (svaki neuspjeli fetch
// i dalje troši egress). Cijeli "Odsjeci" podsistem (_loadOdsjeciSQLite,
// _odsjeciPanelHtml i srodne funkcije) i autoLoadStorageBucket() su zbog toga
// bili potpuno mrtav kod (v1.5.8) — obrisani, ne samo neaktivni.
async function autoLoadAllKmlBuckets() {}

// =====================================================================
// ═══ DOZNAKA STABALA ═══
// =====================================================================

const DOZ_TYPES = {
  unsuitable_felling: { label:'Nepogodno za sječu', emoji:'🚫', color:'#E63946', desc:'Kamen, nagib, vlažno tlo' },
  cleaning:           { label:'Čišćenje podmlatka', emoji:'🌿', color:'#52B788', desc:'Potrebno čišćenje šiblja' },
  protection:         { label:'Zaštitna zona',      emoji:'🛡',  color:'#3B8BD4', desc:'Vodotok, zaštitno stanište' },
  seed_trees:         { label:'Stabla sjemenjaci',  emoji:'🌰', color:'#FF9F1C', desc:'Odabrana stabla — NE sjeći!' },
  priority_felling:   { label:'Prioritet doznake',  emoji:'⭐', color:'#FFBE0B', desc:'Ova ploha se doznauje prva' },
  done:               { label:'Završeno',            emoji:'✅', color:'#8D99AE', desc:'Doznaka završena' },
  custom:             { label:'Ostalo',              emoji:'📍', color:'#9B5DE5', desc:'Korisnička napomena' }
};

const DOZ_ENG_COLORS = ['#E63946','#3B8BD4','#52B788','#FF9F1C','#9B5DE5','#00B4D8','#FFB703','#FB5607','#8D99AE','#A0C4FF'];

let _dozOdjeli   = [];
let _dozSelId    = null;
let _dozLoadGen  = 0;  // D4-D: generation token — spriječi stariji odgovor da prepiše novije odabrani odjel
let _dozMembers  = [];
let _dozMarkings = [];
let _dozTracks   = [];
var _dozFitId = null;   // odjel na koji je karta već centrirana (vidi dozRenderMapLayers)
let _dozDrawType = null;
let _dozDrawPts  = [];
let _dozDrawLayer= null;
let _dozBoundaryLayer = null;

// ─── Kreiranje novog odjela — stanje ─────────────
let _dozCreateFeatures = []; // [{gj, odjel, odsjek, gazKlasa, geometry}]
let _dozCreateGj       = '';
let _dozCreateOdjel    = '';
let _dozCreateBoundary = null; // GeoJSON Polygon/MultiPolygon
let _dozCreateAreaHa   = null;
let _dozNewOdjelDrawGj    = '';
let _dozNewOdjelDrawOdjel = '';
let _dozKmlSelMode     = false;
let _dozKmlSelLayers   = [];
let _dozKmlSelSavedGj    = '';
let _dozKmlSelSavedOdjel = '';
let _dozTracksLayer   = null;
let _dozMarkingsLayer = null;
let _dozMarkingLayerById = {};
let _dozBandsLayer    = null;
let _dozActiveChannel = null;
let _dozGpsOn    = false;
let _dozGpsWatchId = null;
let _dozTrackRefreshTimer = null;
let _dozGpsTrackLayer = null;
let _dozGpsPts   = [];
let _dozInitDone = false;
let _dozPendingSavePolygon = null;

// ─── Init ────────────────────────────────────────────────────────
function dozInit() {
  if (!_dozInitDone) {
    dozInitTypePicker();
    _dozInitDone = true;
  }
  const savedSel = _OL.load(_OL.DOZ_SEL_ID);
  if (savedSel) _dozSelId = savedSel;
  dozLoadOdjeli();
}

function dozInitTypePicker() {
  const grid = document.getElementById('doz-type-grid');
  if (!grid) return;
  grid.innerHTML = Object.entries(DOZ_TYPES).map(([k, t]) => `
    <button class="doz-type-btn" style="border-color:${t.color};color:${t.color};"
            onclick="dozStartDraw('${k}')">
      ${t.emoji} ${t.label}
      <small>${t.desc}</small>
    </button>`).join('');
}

// ─── Load Odjeli ─────────────────────────────────────────────────
function _dozVratiNeposlane(rows) {
  const out = [...(rows || [])];
  for (const op of _OL.loadQueue()) {
    if (op.type !== 'insert_doz_project' || (op._uid && op._uid !== sbUser?.id)) continue;
    const { _tempId, ...payload } = op.payload || {};
    const id = payload.id || _tempId;
    if (!id || payload.created_by !== sbUser?.id || out.some(o => o.id === id)) continue;
    out.unshift({ ...payload, id, _pendingSync:true });
  }
  return out;
}

async function dozLoadOdjeli() {
  const owner=sbUser?.id, generation=(dozLoadOdjeli._gen||0)+1;dozLoadOdjeli._gen=generation;
  const valid=()=>sbUser?.id===owner && dozLoadOdjeli._gen===generation;
  const lista = document.getElementById('doz-odjeli-list');
  if (!sbUser) { if (lista) lista.innerHTML = '<div class="doz-empty" style="color:#fbbf24;">Prijavite se za pristup</div>'; return; }
  // v1.8.9 OFFLINE-FIRST: keš se prikaže ODMAH, mreža ga samo zamijeni kad
  // stigne. Ranije je lista stajala na "Učitavam..." dok mrežni poziv ne padne
  // (na mrtvoj vezi do 15 s), iako su odjeli bili uredno na uređaju.
  const kes = _dozVratiNeposlane(_OL.load(_OL.DOZ_ODJELI));
  const imaKes = Array.isArray(kes) && kes.length > 0;
  if (imaKes) {
    _dozOdjeli = kes;
    dozRenderOdjeli();
    _dozRenderOverview();
  } else if (lista) {
    lista.innerHTML = '<div class="doz-empty">Učitavam...</div>';
  }
  if (!_mrezaProbaj()) {
    if (!imaKes && lista) lista.innerHTML = '<div class="doz-empty" style="color:#fbbf24;">Nema veze — odjeli će se učitati kad se pojavi signal.</div>';
    return;
  }
  try {
    const { data: clanstva, error: eClan } = await sb.from('doz_project_members')
      .select('project_id').eq('user_id', sbUser.id).eq('is_active', true);
    // Supabase mrežnu grešku VRAĆA, ne baca: bez ove provjere prazno članstvo
    // (pad na slaboj vezi) bi iz liste i keša izbacilo sve odjele kolega.
    if(!valid())return false;
    if (eClan) throw eClan;
    const memberIds = (clanstva || []).map(c => c.project_id);
    let q = sb.from('doz_projects').select('*').order('created_at', { ascending: false });
    q = memberIds.length
      ? q.or(`created_by.eq.${sbUser.id},id.in.(${memberIds.join(',')})`)
      : q.eq('created_by', sbUser.id);
    const { data, error } = await q;
    if(!valid())return false;
    if (error) throw error;
    const pending = _dozVratiNeposlane(_OL.load(_OL.DOZ_ODJELI)).filter(o => o._pendingSync && o.created_by === sbUser.id);
    _dozOdjeli = [...pending.filter(o => !(data || []).some(d => d.id === o.id)), ...(data || [])];
    if(_OL.save(_OL.DOZ_ODJELI, _dozOdjeli)===false)throw Error('Odjeli nisu sačuvani na telefonu');
    dozRenderOdjeli();
    _dozRenderOverview();
    return true;
  } catch(e) {
    if(!valid())return false;
    if (imaKes) {
      if (_isNetworkErr(e)) showToast('📴 Doznaka odjeli iz keša (offline)');
      return;
    }
    if (!lista) return;
    lista.innerHTML = _isNetworkErr(e)
      ? '<div class="doz-empty" style="color:#fbbf24;">Nema veze — odjeli će se učitati kad se pojavi signal.</div>'
      : `<div class="doz-empty" style="color:#f87171;">Greška: ${_escHtml(e.message || String(e))}<br><small>Provjerite da li su Supabase tabele kreirane.</small></div>`;
  }
}

// ─── Vidljivost odjela na karti (localStorage, klijentska preferencija) ─────
// Isti obrazac kao _getHiddenProjektIds za vlake — više doznaka odjela može
// biti prikazano na karti istovremeno (overview granice), svaki se pojedinačno
// pali/gasi bez brisanja podataka.
const _DOZ_HIDDEN_KEY = 'tvlake_doz_hidden_odjeli';
function _getDozHiddenIds() {
  try { return new Set(JSON.parse(localStorage.getItem(_DOZ_HIDDEN_KEY) || '[]')); }
  catch { return new Set(); }
}
function _setDozHidden(id, hidden) {
  const set = _getDozHiddenIds();
  if (hidden) set.add(id); else set.delete(id);
  localStorage.setItem(_DOZ_HIDDEN_KEY, JSON.stringify([...set]));
}
function toggleDozOdjelVisible(id, ev) {
  if (ev) ev.stopPropagation();
  const hidden = _getDozHiddenIds();
  _setDozHidden(id, !hidden.has(id));
  dozRenderOdjeli();
  _dozRenderOverview();
}

// ─── Stil granice odjela (boja/jačina ispune/obrub) — pamti zadnje postavljeno ──
const _DOZ_STYLE_KEY = 'tvlake_doz_boundary_style';
function _getDozBoundaryStyle() {
  try {
    const s = JSON.parse(localStorage.getItem(_DOZ_STYLE_KEY) || 'null');
    if (s && s.col) return s;
  } catch(e) {}
  return { col: '#4ade80', op: 0.05, wt: 3, dash: true };
}
function _setDozBoundaryStyle(style) {
  try { localStorage.setItem(_DOZ_STYLE_KEY, JSON.stringify(style)); } catch(e) {}
}
// Postavi kontrole (boja/slider/checkbox) na zadnje sačuvane vrijednosti — poziva
// se pri otvaranju detalja odjela, da UI odmah pokazuje ono što je stvarno primijenjeno.
function _dozRestoreBoundaryStyleUI() {
  const s = _getDozBoundaryStyle();
  const colEl  = document.getElementById('doz-fill-col');
  const opEl   = document.getElementById('doz-fill-opacity');
  const wtEl   = document.getElementById('doz-border-weight');
  const dashEl = document.getElementById('doz-border-dash');
  if (colEl)  colEl.value = s.col;
  if (opEl)   opEl.value  = Math.round(s.op * 100);
  if (wtEl)   wtEl.value  = s.wt;
  if (dashEl) dashEl.checked = s.dash;
  const opLbl = document.getElementById('doz-fill-opacity-lbl');
  const wtLbl = document.getElementById('doz-border-weight-lbl');
  if (opLbl) opLbl.textContent = Math.round(s.op * 100) + '%';
  if (wtLbl) wtLbl.textContent = s.wt;
  const sw = document.getElementById('doz-fill-swatch');
  if (sw) { sw.style.background = `rgba(${_hexToRgbCsv(s.col)},${Math.max(s.op, 0.15)})`; sw.style.borderColor = s.col; }
}

function dozRenderOdjeli() {
  const el = document.getElementById('doz-odjeli-list');
  if (!_dozOdjeli.length) {
    const sz0 = document.getElementById('doz-odjeli-sazetak'); if (sz0) sz0.innerHTML = '';
    el.innerHTML = '<div class="doz-empty">Nema odjela. Kreiraj prvi sa "+ Novi".</div>'; return;
  }
  const hidden = _getDozHiddenIds();
  // Aktivni prvi, pa pauzirani, pa završeni — unutar grupe redoslijed kao sa
  // servera (najnoviji prvi). Sortira se KOPIJA: _dozOdjeli redoslijed nosi i
  // boju granice u overview sloju (DOZ_ENG_COLORS[i]), ne smije se pomjeriti.
  const _red = { active: 0, paused: 1, completed: 2 };
  const prikaz = _dozOdjeli.slice().sort((a, b) => (_red[a.status || 'active'] ?? 3) - (_red[b.status || 'active'] ?? 3));
  const sz = document.getElementById('doz-odjeli-sazetak');
  let filt = typeof _dozListaFilterGet === 'function' ? _dozListaFilterGet() : '';
  if (sz) {
    const n = st => _dozOdjeli.filter(o => (o.status || 'active') === st).length;
    const ha = _dozOdjeli.reduce((s, o) => s + (parseFloat(o.known_area_ha) || 0), 0);
    // Brojači su i filter: dodir prikaže samo taj status, ponovni dodir (ili
    // "sve") vraća sve. Filter koji više nema šta prikazati se sam gasi.
    if (filt && !n(filt)) filt = _dozListaFilterSet('');
    const chip = (st, cls, txt) => `<button type="button" class="doz-filt ${cls}${filt === st ? ' on' : ''}" aria-pressed="${filt === st}" onclick="_dozListaFilterSet('${filt === st ? '' : st}');dozRenderOdjeli()">${txt}</button>`;
    sz.innerHTML = chip('', 'sve', `<b>${_dozOdjeli.length}</b> ${_dozOdjeli.length === 1 ? 'odjel' : 'odjela'}`) +
      (n('active') ? chip('active', 'a', `● ${n('active')} aktivno`) : '') +
      (n('paused') ? chip('paused', 'p', `● ${n('paused')} pauza`) : '') +
      (n('completed') ? chip('completed', 'c', `● ${n('completed')} završeno`) : '') +
      (ha > 0 ? `<span style="margin-left:auto;">${fmtHa(ha)}</span>` : '');
  }
  const query=(document.getElementById('doz-search')?.value||'').trim().toLocaleLowerCase('bs');
  const results=prikaz.filter(o=>(!filt||(o.status||'active')===filt)&&(!query||String(o.name||'').toLocaleLowerCase('bs').includes(query)));
  el.innerHTML = results.map(o => {
    const status = o.status || 'active';
    const label  = status === 'active' ? 'Aktivno' : status === 'completed' ? 'Završeno' : 'Pauza';
    const isHidden = hidden.has(o.id);
    return `<div class="doz-odjel-card st-${status}${_dozSelId===o.id?' selected':''}" onclick="dozSelectOdjel('${o.id}')">
      <div style="display:flex;align-items:center;gap:8px;">
        <div class="doz-odjel-name" style="flex:1;min-width:0;">${_escHtml(o.name)}</div>
        <button class="doz-odjel-oko${isHidden ? ' skriven' : ''}" onclick="toggleDozOdjelVisible('${o.id}',event)" title="${isHidden ? 'Prikaži na karti' : 'Sakrij sa karte'}">${isHidden ? '<svg class="ic"><use href="#ic-sakrij"/></svg>' : '<svg class="ic"><use href="#ic-prikazi"/></svg>'}</button>
      </div>
      <div class="doz-odjel-meta">
        ${o.known_area_ha ? `<span>📐 ${fmtHa(o.known_area_ha)}</span>` : ''}
        <span class="doz-status-chip ${status}">${label}</span>
        <span>${fmtDateShort(o.created_at)}</span>
        ${o._pendingSync ? '<span style="font-size:10px;color:#f59e0b;margin-left:4px;">⏳ čeka sync</span>' : ''}
      </div>
    </div>`;
  }).join('')||'<div class="doz-empty">Nema odjela za uneseni naziv.</div>';
}
// var (ne let): dozRenderOdjeli zna biti pozvan pri pokretanju prije nego
// izvršavanje stigne do ove linije — let bi tada bacio (TDZ).
var _dozListaFilter;
function _dozListaFilterGet() {
  if (_dozListaFilter === undefined) { try { _dozListaFilter = localStorage.getItem('tvlake_doz_filter') || ''; } catch (e) { _dozListaFilter = ''; } }
  return ['active', 'paused', 'completed'].includes(_dozListaFilter) ? _dozListaFilter : '';
}
function _dozListaFilterSet(v) {
  _dozListaFilter = ['active', 'paused', 'completed'].includes(v) ? v : '';
  try { localStorage.setItem('tvlake_doz_filter', _dozListaFilter); } catch (e) {}
  return _dozListaFilter;
}

// Overview sloj — granice SVIH (ne-skrivenih) odjela istovremeno na karti, dok
// je otvorena lista (bez detaljnog prikaza). Klik na granicu otvara taj odjel.
let _dozOverviewLayer = null;
function _dozClearOverview() {
  if (_dozOverviewLayer) { try { map.removeLayer(_dozOverviewLayer); } catch(e) {} _dozOverviewLayer = null; }
}
function _dozRenderOverview() {
  _dozClearOverview();
  if (!window.map || _dozSelId) return;  // detaljni prikaz otvoren — overview se ne crta preko njega
  const hidden = _getDozHiddenIds();
  const grp = L.layerGroup();
  let any = false;
  _dozOdjeli.forEach((o, i) => {
    if (hidden.has(o.id) || !o.boundary_geojson) return;
    try {
      const gj = typeof o.boundary_geojson === 'string' ? JSON.parse(o.boundary_geojson) : o.boundary_geojson;
      const col = DOZ_ENG_COLORS[i % DOZ_ENG_COLORS.length];
      const lyr = L.geoJSON(gj, { style: { color: col, weight: 2.5, fillColor: col, fillOpacity: 0.06, dashArray: '6,4' } });
      lyr.bindTooltip(_escHtml(o.name), { sticky: true, opacity: 0.9 });
      lyr.on('click', () => dozSelectOdjel(o.id));
      grp.addLayer(lyr);
      any = true;
    } catch(e) {}
  });
  if (any) { grp.addTo(map); _dozOverviewLayer = grp; }
}

// ─── Per-project realtime subscription ───────────────────────────
function _dozSubProject(projectId) {
  if (_dozActiveChannel) { sb.removeChannel(_dozActiveChannel); _dozActiveChannel = null; }
  if (!projectId || !_mrezaProbaj(true)) return;
  _dozActiveChannel = sb.channel('doz-proj-' + projectId + '-' + Date.now())
    .on('postgres_changes', {
      event: 'INSERT', schema: 'public', table: 'doz_area_markings',
      filter: 'project_id=eq.' + projectId
    }, payload => {
      const by = payload.new?.user_id || payload.new?.created_by;
      if (by && by !== sbUser?.id) {
        showToast('🌲 ' + (_notifKolegaName ? _notifKolegaName(by) : 'Kolega') + ' je dodao/la oznaku');
        dozLoadLayers(projectId).then(() => dozRenderDetail());
      }
    })
    .on('postgres_changes', {
      event: '*', schema: 'public', table: 'doz_area_markings',
      filter: 'project_id=eq.' + projectId
    }, payload => {
      if (payload.eventType === 'INSERT') return;
      const by = payload.new?.created_by || payload.old?.created_by;
      if (by && by !== sbUser?.id) dozLoadLayers(projectId).then(() => dozRenderDetail());
    })
    .on('postgres_changes', {
      event: 'INSERT', schema: 'public', table: 'doz_track_points',
      filter: 'project_id=eq.' + projectId
    }, payload => {
      const r = payload.new;
      const by = r?.user_id;
      if (by && by !== sbUser?.id) {
        // Tačka kolege ide DIREKTNO u _dozTracks (realtime nosi cijeli red) —
        // ranije je svaka nova tačka nakon 5 s ponovo preuzimala SVE tačke
        // odjela sa servera (hiljade redova, na slaboj vezi sporo i skupo).
        // Puni reload i dalje radi catch-up pri ponovnom spajanju.
        if (r.project_id === _dozSelId && r.latitude != null) _dozTracks.push(r);
        clearTimeout(_dozTrackRefreshTimer);
        _dozTrackRefreshTimer = setTimeout(() => _dozOsvjeziTragove(projectId), 2000);
      }
    })
    .subscribe(status => {
      // Catch-up po (re)joinu: realtime NE reproducira događaje propuštene dok je
      // socket bio pao — povuci svježe pojaseve/oznake kolega čim ima konekcije.
      if (status === 'SUBSCRIBED') _dozSchedCatchup(1200);
    });
}

// Ponovo iscrtaj tragove/pojaseve/statistiku iz onoga što je već u memoriji
// (bez mreže). Karta se NE centrira ponovo (_dozFitId).
function _dozOsvjeziTragove(projectId) {
  if (!projectId || projectId !== _dozSelId) return;
  try { dozRenderMapLayers(); } catch(e) {}
  try { dozRenderDetail(); } catch(e) {}
  try { _dozCacheLayers(projectId); } catch(e) {}
}
// Vlastito snimanje: pojasevi/statistika se osvježe najviše jednom u 15 s —
// računica pojaseva je skupa i ne smije ići na svaku GPS tačku (vrući put).
let _dozLiveRacunTs = 0;
function _dozLiveRacunMozda() {
  const now = Date.now();
  if (now - _dozLiveRacunTs < 15000) return;
  _dozLiveRacunTs = now;
  setTimeout(() => _dozOsvjeziTragove(_dozSelId), 0);
}

// Throttled reload doznaka slojeva otvorenog odjela (pandan _schedKolegeFullSync za vlake)
let _dozCatchupTimer = null;
function _dozSchedCatchup(delay = 1200) {
  if (!_dozSelId) return;
  clearTimeout(_dozCatchupTimer);
  _dozCatchupTimer = setTimeout(() => {
    _dozCatchupTimer = null;
    if (!_dozSelId || !_mrezaProbaj()) return;
    dozLoadLayers(_dozSelId).then(() => { try { dozRenderDetail(); } catch(e) {} }).catch(() => {});
  }, delay);
}

// Samoizlječenje per-projekat doznaka kanala: sbStartRealtime ga NE obnavlja
// (nije u _sbRemoveRtChannels), pa poslije pada socketa može ostati mrtav.
function _dozEnsureChannel() {
  if (!_dozSelId || !_mrezaProbaj(true)) return;
  try {
    if (!_dozActiveChannel || !['joined', 'joining'].includes(_dozActiveChannel.state)) _dozSubProject(_dozSelId);
  } catch(e) {}
}

// ─── Select Odjel ────────────────────────────────────────────────
async function dozSelectOdjel(id) {
  if ((_dozGpsOn || (_dozGpsStopping && _dozGpsUserId)) && id !== _dozGpsProjId) {
    showToast('Prvo završi GPS snimanje u otvorenom odjelu');
    dozOpenGPSControls();
    return false;
  }
  const odjel = _dozOdjeli.find(o => o.id === id),owner=sbUser?.id;
  if(!odjel)return;
  const selection=(dozSelectOdjel._generation||0)+1;dozSelectOdjel._generation=selection;
  if(_dozVlakeVisible)dozToggleVlake();
  _dozSelId = id;
  if(typeof DoznakaPlan!=='undefined')DoznakaPlan.sync().catch(()=>{});
  _dozFitId = null;   // novo otvaranje (i istog odjela) → centriraj ponovo
  _OL.save(_OL.DOZ_SEL_ID, id);
  _dozClearOverview();
  dozTreesClear();
  dozRenderOdjeli();
  _dozSubProject(id);
  document.getElementById('doz-panel-list').style.display   = 'none';
  document.getElementById('doz-panel-detail').style.display = 'flex';
  _dozRestoreBoundaryStyleUI();
  _dozRestoreTreesStyleUI();
  document.getElementById('doz-detail-name').textContent = odjel.name;
  document.getElementById('doz-detail-area').textContent =
    odjel.known_area_ha ? fmtHa(odjel.known_area_ha) : '';
  // Šifru za teren smije napraviti samo vlasnik doznake (isto pravilo kao na serveru).
  const _dozShareBtn = document.getElementById('doz-share-code-btn');
  if (_dozShareBtn) _dozShareBtn.style.display = (odjel.created_by && odjel.created_by === sbUser?.id) ? '' : 'none';
  const removeButton=document.getElementById('doz-project-remove');
  if(removeButton)removeButton.innerHTML='<svg class="ic"><use href="#ic-obrisi"/></svg> '+(odjel.created_by===owner?'Obriši odjel':'Ukloni sa mog spiska');
  _dozQrRenderReceived();
  _dozRenderStatusRow();
  await dozLoadLayers(id, { odmahIzKesa: true });
  if(sbUser?.id!==owner||_dozSelId!==id||dozSelectOdjel._generation!==selection)return;
  _dozAutoLinkVlake(odjel);
  _dozTreesRestoreForOdjel(id);
  dozRenderDetail();
  if (typeof _tabContext === 'function') _tabContext();
}

function _dozAutoLinkVlake(odjel) {
  _dozLinkedProjektId = null;
  if (!odjel?.name || !_projekti?.length) return;
  const norm=v=>String(v||'').trim().toLocaleLowerCase('bs').replace(/\s+/g,' ');
  const parts=String(odjel.name).split('·'),number=norm(parts.at(-1)),gj=norm(odjel.gj||(parts.length>1?parts.slice(0,-1).join('·'):''));
  const matches=_projekti.filter(p=>norm(p.odjel)===number&&(!gj||norm(p.gj)===gj));
  if(matches.length===1){_dozLinkedProjektId=matches[0].id;_dozShowLinkedVlake();}
}

function _dozShowLinkedVlake() {
  if (!_dozLinkedProjektId) return;
  _dozVlakeIdxs = [];
  vlake.forEach((v, i) => {
    if (v.projektId === _dozLinkedProjektId && v.pts.length >= 2) {
      _dozVlakeIdxs.push(i);
      [v.poly, v.labelMk, v.lagerMk, ...(v.extraLabels || [])].filter(Boolean).forEach(l => {
        try { if (!map.hasLayer(l)) map.addLayer(l); } catch(e) {}
      });
    }
  });
  if (_dozVlakeIdxs.length) {
    _dozVlakeVisible = true;
    const btn = document.getElementById('doz-vlake-toggle');
    if (btn) btn.innerHTML = '<svg class="ic"><use href="#ic-sakrij"/></svg> Sakrij';
    document.getElementById('doz-buf-section').style.display = 'block';
  }
  if (typeof _dozTreePts !== 'undefined' && _dozTreePts.length) dozTreesAnalyze();
}

async function dozLoadLayers(projectId, opts) {
  if (!projectId || projectId !== _dozSelId) return false;
  const owner=sbUser?.id;
  const valid=()=>sbUser?.id===owner && projectId===_dozSelId && myGen===_dozLoadGen;
  const cacheKey = pid => pid; // per-project cache suffix
  const myGen = ++_dozLoadGen;  // D4-D: spriječi da stariji (spori) odgovor prepiše novije odabrani odjel
  // v1.7.4 OFFLINE-FIRST: pri OTVARANJU odjela odmah prikaži keš, pa ga mreža
  // zamijeni kad stigne. Ranije se keš čitao tek kad mrežni poziv PADNE — a na
  // mrtvoj vezi (navigator.onLine laže, OS-S4) to je do 15 s praznog detalja:
  // prazna statistika, "Nema članova", nijedna zona. Uz to su do tada na ekranu
  // stajali slojevi PRETHODNO otvorenog odjela. Samo pri otvaranju — kod
  // osvježavanja (realtime, catch-up) bi vraćanje na stariji keš treptalo.
  let izKesa = false;
  if (opts && opts.odmahIzKesa) {
    const c0 = _dozLoadCachedLayers(projectId);
    _dozMembers = c0 ? c0.members : []; _dozMarkings = c0 ? c0.markings : []; _dozTracks = c0 ? c0.tracks : [];
    izKesa = !!c0;
    try { dozRenderMapLayers(); } catch(e) {}
    try { dozRenderDetail(); } catch(e) {}
  }
  try {
    const [mRes, mkRes, trRes] = await Promise.all([
      _dozReadList(()=>sb.from('doz_project_members').select('*').eq('project_id', projectId).eq('is_active', true),owner),
      _dozReadList(()=>sb.from('doz_area_markings').select('*').eq('project_id', projectId).eq('is_visible', true),owner),
      _dozUcitajTacke(projectId)
    ]);
    if (!valid()) return false;  // novije selektovan drugi odjel u međuvremenu — odbaci
    // v1.8.9: Supabase mrežnu grešku VRAĆA kao {error}, ne baca. Bez ove provjere
    // pad na mrtvoj/slaboj vezi je dao prazne nizove koji su se ODMAH upisali u
    // offline keš odjela (_dozCacheLayers ispod) — sljedeće otvaranje bez signala
    // pokazalo bi odjel bez zona, članova i tragova.
    const greska = mRes.error || mkRes.error || trRes.error;
    if (greska) throw greska;
    const prosli = _dozLoadCachedLayers(projectId);
    let members = mRes.data || [];

    if (members.length) {
      const ids = [...new Set(members.map(m => m.user_id).filter(Boolean))];
      const { data: kData } = await sb.from('korisnici').select('id,ime,prezime,boja').in('id', ids);
      if (!valid()) return false;
      const kMap = Object.fromEntries((kData || []).map(k => [k.id, k]));
      // Imena kolega iz prošlog keša ako ovaj poziv padne — inače bi keš ostao bez imena.
      const kPrije = Object.fromEntries(((prosli && prosli.members) || [])
        .filter(m => m._korisnik).map(m => [m.user_id, m._korisnik]));
      members = members.map(m => ({ ...m, _korisnik: kMap[m.user_id] || kPrije[m.user_id] || null }));
    }
    // Keširaj za offline
    if(!valid())return false;
    _dozMembers=members;_dozMarkings=_dozPrimijeniRed(mkRes.data||[],projectId);_dozTracks=trRes.data||[];
    if(_dozCacheLayers(projectId)===false)throw Error('Slojevi nisu sačuvani na telefonu');
    if(typeof _serverDozReceived==='function')_serverDozReceived(projectId,mkRes.data||[],trRes.data||[],members,owner);
  } catch(e) {
    if (!valid()) return false;
    console.error('dozLoadLayers', e);
    const c = _dozLoadCachedLayers(projectId);
    if (c) {
      _dozMembers = c.members; _dozMarkings = c.markings; _dozTracks = c.tracks;
      showToast('📴 Doznaka slojevi iz keša');
    } else if (!izKesa) {
      _dozMembers = []; _dozMarkings = []; _dozTracks = [];
    }
    dozRenderMapLayers();
    if(opts?.strict)throw e;
    return false;
  }
  if (!valid()) return false;
  dozRenderMapLayers();
  return true;
}

// Sve GPS tačke odjela, stranicu po stranicu. Supabase (PostgREST max-rows)
// vraća NAJVIŠE 1000 redova po upitu — odjel sa više projektanata to pređe za
// par sati snimanja, a upit je sortiran od najstarije, pa su se odsijecale baš
// NAJNOVIJE tačke (današnji trag nije bio na karti, pređena površina manja) i
// takav skraćen skup se upisivao u offline keš. Pomak raste za broj stvarno
// vraćenih redova, pa radi i kad je server podešen na manji max-rows od 1000.
async function _dozReadList(query,owner) {
  try {return {data:await _vlakePreuzmiStranice(query,owner),error:null};}
  catch(error){return {data:null,error};}
}
const _DOZ_TACKE_STRANA = 1000;
async function _dozUcitajTacke(projectId) {
  const sve = [], owner=sbUser?.id;
  for (let od = 0, strana = 0; strana < 500; strana++) {
    const { data, error } = await sb.from('doz_track_points')
      .select('user_id,latitude,longitude,altitude,speed,recorded_at').eq('project_id', projectId)
      .order('recorded_at', { ascending: true }).order('user_id', { ascending:true }).order('latitude', {ascending:true}).order('longitude', {ascending:true})
      .range(od, od + _DOZ_TACKE_STRANA - 1);
    if(sbUser?.id!==owner)return {data:null,error:{code:'OWNER_CHANGED',message:'Promijenjen nalog'}};
    if (error) return { data: null, error };
    if (!data || !data.length) return {data:sve,error:null};
    for (const r of data) sve.push(r);
    od += data.length;
  }
  return {data:null,error:{code:'PAGE_LIMIT',message:'Preuzimanje nije potpuno; prethodni podaci su sačuvani'}};
}

// Zone koje još čekaju u redu za sync moraju ostati vidljive i kad server vrati
// listu bez njih (slaba veza: čitanje prođe, upis još nije). Isto tako zona
// obrisana offline ne smije "vaskrsnuti" dok brisanje ne stigne na server.
function _dozPrimijeniRed(markings, projectId) {
  let q = [];
  try { q = (_OL.loadQueue() || []).filter(o=>!o._uid || o._uid===sbUser?.id); } catch(e) {}
  const brisu = new Set(q.filter(o => o.type === 'delete_doz_marking').map(o => o.payload && o.payload.id));
  const naServeru = new Set(markings.map(m => m.id));
  const cekaju = q
    .filter(o => o.type === 'insert_doz_marking' && o.payload && o.payload.project_id === projectId
      && !(o.payload.id && naServeru.has(o.payload.id)))
    .map(o => ({ ...o.payload, id: o._localId || o.payload.id }));
  return [...cekaju, ...markings].filter(m => !brisu.has(m.id));
}

// Upis zone sa klijentskim ID-jem: odgovor izgubljen na slaboj vezi → ponovljeni
// upis iz reda dobije 23505: čitanjem se potvrđuje isti sadržaj. Legacy ID
// se izostavlja samo kad greška jasno upućuje na njega, ne na drugu kolonu.
async function _dozUpisiZonu(payload) {
  let r = await _serverInsertPotvrdjeno('doz_area_markings', payload);
  const badId=payload.id && (!/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(payload.id) ||
    /invalid input syntax for type (?:integer|bigint|smallint)/i.test(r.error?.message||'') && String(r.error?.message).includes(String(payload.id)));
  if (r.error?.code === '22P02' && badId) {
    const { id, ...bezId } = payload;
    r = await _serverInsertPotvrdjeno('doz_area_markings', bezId);
  }
  return r;
}

// Konflikt ID-ja ili odgovor bez greške nisu dovoljni: potvrdi vlasnika,
// ciljani projekat i sadržaj prije uklanjanja trajne lokalne kopije iz reda.
function _serverPodaciJednaki(expected, actual, key='') {
  if(expected===undefined)return true;
  if(expected && typeof expected==='object'){
    if(typeof actual==='string'){try{actual=JSON.parse(actual);}catch(e){return false;}}
    if(!actual || typeof actual!=='object' || Array.isArray(expected)!==Array.isArray(actual))return false;
    if(Array.isArray(expected)&&expected.length!==actual.length)return false;
    return Object.keys(expected).every(k=>_serverPodaciJednaki(expected[k],actual[k],k));
  }
  if(expected===actual)return true;
  return /_at$/.test(key) && typeof expected==='string' && typeof actual==='string' &&
    Number.isFinite(Date.parse(expected)) && Date.parse(expected)===Date.parse(actual);
}
async function _serverInsertPotvrdjeno(table, payload) {
  const owner=sbUser?.id;
  let r=await sb.from(table).insert(payload).select('*').single();
  if(sbUser?.id!==owner)return {data:null,error:{code:'OWNER_CHANGED',message:'Promijenjen nalog'}};
  if(r.error?.code==='23505' && payload.id){
    r=await sb.from(table).select('*').eq('id',payload.id).maybeSingle();
    if(sbUser?.id!==owner)return {data:null,error:{code:'OWNER_CHANGED',message:'Promijenjen nalog'}};
  }
  if(r.error)return r;
  if(!r.data?.id || !_serverPodaciJednaki(payload,r.data))return {data:null,error:{code:'NO_CONFIRMATION',message:'Server nije potvrdio ciljani zapis i njegov sadržaj; izmjena ostaje za slanje'}};
  return r;
}

function _dozCacheKey(projectId) {
  return (sbUser?.id || '_') + ':' + projectId;
}

function _dozCacheLayers(projectId) {
  try {
    const all = _OL.load(_OL.DOZ_MEMBERS) || {};
    const ck = _dozCacheKey(projectId);
    all[ck] = { members: _dozMembers, markings: _dozMarkings, tracks: _dozTracks, ts: Date.now() };
    const keys = Object.keys(all);
    if (keys.length > 5) {
      keys.sort((a, b) => (all[a].ts || 0) - (all[b].ts || 0));
      keys.slice(0, keys.length - 5).forEach(k => delete all[k]);
    }
    return _OL.save(_OL.DOZ_MEMBERS, all)!==false;
  } catch(e) {return false;}
}

function _dozLoadCachedLayers(projectId) {
  const all = _OL.load(_OL.DOZ_MEMBERS);
  return all?.[_dozCacheKey(projectId)] || null;
}

// ─── Render Map Layers ────────────────────────────────────────────
function dozRenderMapLayers() {
  [_dozBoundaryLayer, _dozTracksLayer, _dozMarkingsLayer, _dozBandsLayer].forEach(l => { if (l) map.removeLayer(l); });
  const odjel = _dozOdjeli.find(o => o.id === _dozSelId);
  if (!odjel) return;

  // Boundary — clickable
  if (odjel.boundary_geojson) {
    try {
      const gj = typeof odjel.boundary_geojson === 'string' ? JSON.parse(odjel.boundary_geojson) : odjel.boundary_geojson;
      const bst = _getDozBoundaryStyle();
      _dozBoundaryLayer = L.geoJSON(gj, {
        style:{ color:bst.col, weight:bst.wt, fillColor:bst.col, fillOpacity:bst.op, dashArray: bst.dash ? '6,4' : null },
        interactive: true
      }).addTo(map);
      _dozBoundaryLayer.on('click', () => _dozShowBoundaryPopup(odjel));
      // Karta se centrira SAMO pri otvaranju odjela. Ranije je svako
      // osvježavanje (trag kolege stiže realtime-om, ~svakih 5 s dok snima)
      // vraćalo kartu na granicu odjela, usred gledanja nekog drugog dijela.
      if (_dozFitId !== odjel.id && _dozBoundaryLayer.getLayers().length) {
        map.fitBounds(_dozBoundaryLayer.getBounds(), { padding:[30,30] });
        _dozFitId = odjel.id;
      }
    } catch(e) {}
  }

  // Bands (pojasevi) — rendered below tracks
  _dozBandsLayer = L.layerGroup().addTo(map);
  _dozRenderBands(odjel);

  // Tracks grouped by user
  _dozTracksLayer = L.layerGroup().addTo(map);
  // Serverske + moje neposlane tačke, dedup po vremenu (ms), sortirano.
  const byUser = _dozTragoviPoKorisniku();
  const mIdx = {};
  _dozMembers.forEach((m, i) => { mIdx[m.user_id] = i; });
  const GAP_MS = 5 * 60 * 1000; // 5 min pauza → nova sesija
  Object.entries(byUser).forEach(([uid, pts]) => {
    if (pts.length < 2) return;
    const col = DOZ_ENG_COLORS[(mIdx[uid] ?? 0) % DOZ_ENG_COLORS.length];
    const segments = [[]];
    pts.forEach((p, i) => {
      if (i > 0) {
        const dt = _dozTackaMs(p) - _dozTackaMs(pts[i-1]);
        if (dt > GAP_MS) segments.push([]);
      }
      segments[segments.length - 1].push([p.latitude, p.longitude]);
    });
    segments.forEach(seg => {
      if (seg.length >= 2) L.polyline(seg, { color: col, weight: 3, opacity: 0.85 }).addTo(_dozTracksLayer);
    });
  });

  // Area markings
  _dozMarkingsLayer = L.layerGroup().addTo(map);
  _dozMarkingLayerById = {};
  _dozMarkings.forEach(m => {
    try {
      const gj = typeof m.boundary_geojson === 'string' ? JSON.parse(m.boundary_geojson) : m.boundary_geojson;
      const t = DOZ_TYPES[m.marking_type] || DOZ_TYPES.custom;
      const lyr = L.geoJSON(gj, { style:{ color:t.color, weight:2, fillColor:t.color, fillOpacity:0.2 } })
        .bindPopup(`<div style="min-width:160px;">
          <b style="font-size:13px;">${t.emoji} ${_escHtml(m.label || t.label)}</b>
          ${m.note ? `<br><span style="color:#888;font-size:11px;">${_escHtml(m.note)}</span>` : ''}
          <br><span style="color:#64748b;font-size:11px;">${m.area_ha ? fmtHa(m.area_ha) : ''}</span>
          <br><button onclick="dozDeleteMarking('${m.id}')" style="margin-top:6px;background:#2d0a0a;color:#f87171;border:1px solid #7f1d1d;border-radius:4px;padding:2px 8px;cursor:pointer;font-size:11px;"><svg class="ic"><use href="#ic-obrisi"/></svg> Briši</button>
        </div>`)
        .addTo(_dozMarkingsLayer);
      _dozMarkingLayerById[m.id] = lyr;
    } catch(e) {}
  });
}

// ─── Pojasevi (Bands) — GPS track–based area assignment ─────────
let _DOZ_BAND_OUTER_M = 20;

function _dozGetBoundaryGeoJSON(odjel) {
  if (!odjel?.boundary_geojson) return null;
  try {
    const gj = typeof odjel.boundary_geojson === 'string' ? JSON.parse(odjel.boundary_geojson) : odjel.boundary_geojson;
    if (gj.type === 'Polygon') return turf.polygon(gj.coordinates);
    if (gj.type === 'MultiPolygon') return turf.multiPolygon(gj.coordinates);
    if (gj.type === 'Feature') return gj;
    if (gj.type === 'FeatureCollection' && gj.features?.length) return gj.features[0];
  } catch(e) {}
  return null;
}

// ─── Tragovi projektanata — JEDAN izvor za prikaz i sve računice (v1.7.5) ───
// Ranije je svaka funkcija (karta, pojasevi, dužine, statistika) sama grupisala
// _dozTracks i sama radila dedup, i to po TEKSTU vremena ('user|recorded_at').
// Server vraća '...+00:00', telefon piše '...Z' — ista tačka iz lokalnog bafera
// i sa servera nije bila prepoznata kao ista. Sad: vrijeme se svodi na ms, a
// pored serverskih tačaka ulaze i MOJE još neposlane (offline bafer), da se
// vlastiti trag vidi i računa i prije sinkronizacije.
function _dozTackaMs(p) { const t = Date.parse(p && p.recorded_at); return isFinite(t) ? t : NaN; }
function _dozTragoviPoKorisniku() {
  const byUser = {};
  const seen = new Set();
  const dodaj = p => {
    if (!p || p.latitude == null || p.longitude == null || !p.user_id) return;
    const ms = _dozTackaMs(p);
    const sig = p.user_id + '|' + (isFinite(ms) ? ms : p.recorded_at);
    if (seen.has(sig)) return;
    seen.add(sig);
    (byUser[p.user_id] = byUser[p.user_id] || []).push(p);
  };
  (_dozTracks || []).forEach(dodaj);
  try {
    (typeof FieldStore !== 'undefined' && FieldStore.ready ? FieldStore.view(sbUser?.id) : JSON.parse(localStorage.getItem(_DOZ_TRACK_BUF_KEY) || '[]'))
      .filter(p => p && p.project_id === _dozSelId).forEach(dodaj);
  } catch(e) {}
  // Redoslijed po VREMENU, ne po dolasku — tačke kolege stižu realtime-om, a
  // offline snimljene kasnije i sa starijim vremenom; bez sortiranja bi linija
  // skakala naprijed-nazad i pojas bi se računao nad pogrešnom geometrijom.
  Object.values(byUser).forEach(a => a.sort((x, y) => (_dozTackaMs(x) || 0) - (_dozTackaMs(y) || 0)));
  return byUser;
}
function _dozLocalStatusRender() {
  const el=document.getElementById('doz-local-status'),owner=sbUser?.id,id=_dozSelId;
  if(!el || !id || !owner)return;
  let points=0,loading=typeof FieldStore!=='undefined' && !FieldStore.ready;
  try{points=(typeof FieldStore!=='undefined' && FieldStore.ready ? FieldStore.view(owner) : JSON.parse(localStorage.getItem(_DOZ_TRACK_BUF_KEY)||'[]')).filter(p=>p.user_id===owner&&p.project_id===id).length;}catch(e){}
  const edits=_OL.loadQueue().filter(o=>(!o._uid||o._uid===owner)&&
    (o.payload?.project_id===id || ['insert_doz_project','upsert_doz_status'].includes(o.type)&&o.payload?.id===id)).length;
  el.innerHTML='<div><b>GPS dnevnik · ovaj odjel</b><span>'+ (loading?'Učitavanje lokalnog dnevnika…':points+' GPS tačaka čeka slanje')+
    (edits?' · '+edits+' izmjena odjela / zona':'')+'</span><small>Snimanje radi bez interneta. Podatke šalješ kad imaš vezu.</small></div><button onclick="openSyncQueuePanel()">Pošalji i primi</button>';
  if(loading && !_dozLocalStatusRender.loading){
    _dozLocalStatusRender.loading=true;
    FieldStore.init().then(()=>{if(sbUser?.id===owner&&_dozSelId===id)_dozLocalStatusRender();})
      .catch(()=>{if(sbUser?.id===owner&&_dozSelId===id)el.querySelector('span').textContent='GPS dnevnik nije učitan — provjeri memoriju telefona';})
      .finally(()=>{_dozLocalStatusRender.loading=false;});
  }
}

// Potpis stanja tragova — kad se ne promijeni, skupa geometrija se ne računa ponovo.
function _dozTragoviPotpis(byUser) {
  return Object.keys(byUser).sort().map(u => {
    // Isti broj tačaka/zadnji datum ne znači istu geometriju. Potpis obuhvata
    // i korigovane koordinate te unutrašnje prekide između GPS segmenata.
    const a = byUser[u];
    return u + ':' + JSON.stringify(a.map(p => [p.latitude,p.longitude,_dozTackaMs(p)]));
  }).join(',');
}
let _dozUTMemo = { k: null, v: null };
let _dozBandsMemo = { k: null, v: null };

function _dozBuildUserTracks() {
  const byUser = _dozTragoviPoKorisniku();
  const memoK = (_dozSelId || '') + '#' + _dozTragoviPotpis(byUser);
  if (_dozUTMemo.k === memoK) return _dozUTMemo.v;
  const GAP_MS = 5 * 60 * 1000;

  const allLines = [];
  Object.entries(byUser).forEach(([uid, pts]) => {
    if (pts.length < 2) return;
    const segments = [{points:[],startedAt:null,endedAt:null}];
    pts.forEach((p, i) => {
      if (i > 0) {
        const dt = _dozTackaMs(p) - _dozTackaMs(pts[i - 1]);
        if (dt > GAP_MS) segments.push({points:[],startedAt:null,endedAt:null});
      }
      const seg=segments[segments.length-1];seg.points.push([p.longitude,p.latitude]);
      if(!seg.startedAt)seg.startedAt=p.recorded_at;seg.endedAt=p.recorded_at;
    });
    segments.forEach(seg => {
      if (seg.points.length >= 2) allLines.push({uid,line:turf.lineString(seg.points),startedAt:seg.startedAt,endedAt:seg.endedAt});
    });
  });

  // GPS tragovi ostaju cjeloviti. Preklop površina obrađuje geometrijska unija;
  // blizina koleginog pojasa nije razlog za brisanje tačaka vlastitog traga.
  _dozUTMemo = { k: memoK, v: allLines };
  return allLines;
}

function _dozComputeBands(odjel) {
  const bndFeat = _dozGetBoundaryGeoJSON(odjel);
  if (!bndFeat) return [];
  const userTracks = _dozBuildUserTracks();
  if (!userTracks.length) return [];
  // Ista računica se traži 2–3 puta po osvježavanju (karta, statistika, popup
  // granice) — memo po stanju tragova + vanjskom rubu + odjelu.
  const bk = (odjel.id || '') + '|' + JSON.stringify(bndFeat.geometry) + '|' + _DOZ_BAND_OUTER_M + '|' + _dozUTMemo.k;
  if (_dozBandsMemo.k === bk) return _dozBandsMemo.v;
  const joined=typeof DozBands!=='undefined'?DozBands.build(userTracks,bndFeat,_DOZ_BAND_OUTER_M,turf):null;
  if(joined){_dozBandsMemo={k:bk,v:joined};return joined;}

  const uidSet = [...new Set(userTracks.map(t => t.uid))];
  const bands = [];
  const boxes=new Map(userTracks.map(t=>[t,turf.bbox(t.line)]));

  uidSet.forEach(uid => {
    const myTracks = userTracks.filter(t => t.uid === uid);
    const otherTracks = userTracks.filter(t => t.uid !== uid);

    myTracks.forEach(mt => {
      try {
        let bufDist = _DOZ_BAND_OUTER_M;
        if (otherTracks.length > 0) {
          let minDist = Infinity;
          const sampled=turf.along(mt.line,turf.length(mt.line)/2),[lon,lat]=sampled.geometry.coordinates;
          const marginLat=2*bufDist/111320,marginLon=marginLat/Math.max(.1,Math.cos(lat*Math.PI/180));
          otherTracks.forEach(ot => {
            const b=boxes.get(ot);
            // Daleki trag ne može suziti pojas. Preskoči skupu pretragu njegovih tačaka.
            if(lon<b[0]-marginLon||lon>b[2]+marginLon||lat<b[1]-marginLat||lat>b[3]+marginLat)return;
            const nearest = turf.nearestPointOnLine(ot.line, sampled);
            if (nearest.properties.dist < minDist) minDist = nearest.properties.dist;
          });
          const halfDist = (minDist * 1000) / 2;
          if (halfDist > 1 && halfDist < bufDist) bufDist = halfDist;
        }
        const buf = turf.buffer(mt.line, bufDist, { units: 'meters', steps: 4 });
        if (!buf) return;
        const clipped = turf.intersect(buf, bndFeat);
        if (clipped) {
          const areaHa = turf.area(clipped) / 10000;
          bands.push({ uid, polygon: clipped, areaHa, startedAt:mt.startedAt, endedAt:mt.endedAt });
        }
      } catch(e) {}
    });
  });
  _dozBandsMemo = { k: bk, v: bands };
  return bands;
}

// Pređena (pokrivena) površina — SPOJENA geometrija, ne zbir pojaseva.
// Pojas se pravi po SEGMENTU traga: projektant koji prođe isti dio dvaput ima
// dva pojasa preko istog tla, a pojasevi dvojice projektanata se preklapaju
// (bafer se prilagođava samo po sredini traga). Zbir je tu površinu brojao
// dvaput i pokrivenost je mogla preći 100 %. Isto pravilo kao "ukupno je
// spojena geometrija" kod traka starosti (v3.113.1).
let _dozPokrMemo = { k: null, v: null };
function _dozPokrivenost(odjel) {
  const bands = _dozComputeBands(odjel);
  if (_dozPokrMemo.k === _dozBandsMemo.k && _dozPokrMemo.v && bands === _dozBandsMemo.v) return _dozPokrMemo.v;
  const spoji = (a, b) => { if (!a) return b; if (!b) return a; try { return turf.union(a, b) || a; } catch(e) { return a; } };
  const poUid = {};
  bands.forEach(b => { poUid[b.uid] = spoji(poUid[b.uid], b.polygon); });
  const poKorisniku = {};
  let sve = null;
  Object.entries(poUid).forEach(([uid, g]) => {
    poKorisniku[uid] = g ? turf.area(g) / 10000 : 0;
    sve = spoji(sve, g);
  });
  const ukupnoHa = sve ? turf.area(sve) / 10000 : 0;
  const zbir = Object.values(poKorisniku).reduce((s, v) => s + v, 0);
  const v = { poKorisniku, ukupnoHa, preklopHa: Math.max(0, zbir - ukupnoHa) };
  _dozPokrMemo = { k: _dozBandsMemo.k, v };
  return v;
}

function _dozImeClana(uid) {
  const member = _dozMembers.find(m => m.user_id === uid);
  const k = member && member._korisnik;
  return (k && `${k.ime || ''} ${k.prezime || ''}`.trim()) || 'Projektant';
}

function _dozRenderBands(odjel) {
  if (!_dozBandsLayer) return;
  const bands = _dozComputeBands(odjel);
  if (!bands.length) return;
  const mIdx = {};
  _dozMembers.forEach((m, i) => { mIdx[m.user_id] = i; });
  const dates=new Intl.DateTimeFormat('bs-BA',{timeZone:'Europe/Sarajevo',dateStyle:'short'}),times=new Intl.DateTimeFormat('bs-BA',{timeZone:'Europe/Sarajevo',timeStyle:'short'});

  bands.forEach(b => {
    const col = DOZ_ENG_COLORS[(mIdx[b.uid] ?? 0) % DOZ_ENG_COLORS.length];
    const name = _escHtml(_dozImeClana(b.uid));
    const start=new Date(b.startedAt),end=new Date(b.endedAt),work=Number.isFinite(start.getTime())?dates.format(start)+' · '+times.format(start)+(Number.isFinite(end.getTime())?'–'+times.format(end):''):'—';
    const lyr = L.geoJSON(b.polygon, {
      style: { color: col, weight: 1.5, fillColor: col, fillOpacity: 0.18 },
      interactive: true
    }).addTo(_dozBandsLayer);
    lyr.bindPopup(`<div style="min-width:150px;font-size:12px;color:#1e293b;">
      <div style="display:flex;align-items:center;gap:6px;margin-bottom:4px;">
        <span style="width:10px;height:10px;border-radius:50%;background:${col};flex-shrink:0;"></span>
        <b style="color:#000;">${name}</b>
      </div>
      <div style="color:#475569;">Procjena površine pojasa: <b style="color:#000;">${b.areaHa.toFixed(2)} ha</b></div>
      <div style="color:#475569;">${b.joined?'Zajednička granica sa susjednim pojasom':'Procjena iz GPS bafera'}</div>
      <div style="color:#475569;">Rad na pojasu: <b style="color:#000;">${_escHtml(work)}</b></div>
    </div>`, { maxWidth: 220 });
  });
}

function _dozShowBoundaryPopup(odjel) {
  const bands = _dozComputeBands(odjel);
  const mIdx = {};
  _dozMembers.forEach((m, i) => { mIdx[m.user_id] = i; });

  let totalArea = 0;
  try {
    const bndFeat = _dozGetBoundaryGeoJSON(odjel);
    if (bndFeat) totalArea = turf.area(bndFeat) / 10000;
  } catch(e) {}

  const pokr = _dozPokrivenost(odjel);
  const byUser = pokr.poKorisniku;

  let rows = '';
  Object.entries(byUser).forEach(([uid, ha]) => {
    const col = DOZ_ENG_COLORS[(mIdx[uid] ?? 0) % DOZ_ENG_COLORS.length];
    const name = _escHtml(_dozImeClana(uid));
    rows += `<tr><td style="padding:2px 6px;"><span style="display:inline-block;width:10px;height:10px;border-radius:50%;background:${col};margin-right:4px;vertical-align:middle;"></span>${name}</td><td style="padding:2px 6px;text-align:right;font-family:monospace;font-weight:700;">${ha.toFixed(2)} ha</td></tr>`;
  });

  const coveredHa = pokr.ukupnoHa;
  const pct = totalArea > 0 ? Math.min(100, (coveredHa / totalArea) * 100).toFixed(0) : '—';

  const html = `<div style="min-width:200px;font-size:12px;color:#1e293b;">
    <b style="font-size:14px;color:#000;">${_escHtml(odjel.name || 'Odjel')}</b>
    <div style="color:#475569;margin:4px 0;">Ukupna površina: <b style="color:#000;">${totalArea.toFixed(2)} ha</b></div>
    ${rows ? `<div style="margin-top:6px;border-top:1px solid #ddd;padding-top:4px;">
      <div style="font-weight:700;margin-bottom:3px;color:#000;">Pojasevi projektanata:</div>
      <table style="width:100%;border-collapse:collapse;">${rows}</table>
      <div style="color:#475569;margin-top:4px;">Procjena pokrivenosti: <b style="color:#000;">${coveredHa.toFixed(2)} ha</b> (${pct}%)</div>
      ${pokr.preklopHa >= 0.01 ? `<div style="color:#b45309;margin-top:2px;">Preklapanje pojaseva: <b>${pokr.preklopHa.toFixed(2)} ha</b></div>` : ''}
      <div style="color:#64748b;margin-top:6px;font-size:11px;">Tlocrtna površina iz GPS bafera; nije potvrda doznake svakog stabla.</div>
    </div>` : '<div style="color:#64748b;margin-top:6px;">Nema GPS tragova — pojasevi nisu formirani</div>'}
  </div>`;

  const bounds = _dozBoundaryLayer?.getBounds();
  if (bounds) {
    L.popup({ maxWidth: 300 }).setLatLng(bounds.getCenter()).setContent(html).openOn(map);
  }
}

function dozFillStyleChange() {
  const col = document.getElementById('doz-fill-col')?.value || '#4ade80';
  const op = parseInt(document.getElementById('doz-fill-opacity')?.value || 5) / 100;
  const wt = parseInt(document.getElementById('doz-border-weight')?.value || 2);
  const dash = document.getElementById('doz-border-dash')?.checked;
  document.getElementById('doz-fill-opacity-lbl').textContent = Math.round(op * 100) + '%';
  document.getElementById('doz-border-weight-lbl').textContent = wt;
  const sw = document.getElementById('doz-fill-swatch');
  if (sw) { sw.style.background = `rgba(${_hexToRgbCsv(col)},${Math.max(op, 0.15)})`; sw.style.borderColor = col; }
  if (_dozBoundaryLayer) {
    _dozBoundaryLayer.setStyle({ color: col, weight: wt, fillColor: col, fillOpacity: op, dashArray: dash ? '6,4' : null });
  }
  _setDozBoundaryStyle({ col, op, wt, dash });
}

function dozBandOuterChange() {
  _DOZ_BAND_OUTER_M = parseInt(document.getElementById('doz-band-outer')?.value || 20);
  dozRefreshBands();
}

function dozRefreshBands() {
  const odjel = _dozOdjeli.find(o => o.id === _dozSelId);
  if (!odjel) return;
  if (_dozBandsLayer) { map.removeLayer(_dozBandsLayer); }
  _dozBandsLayer = L.layerGroup().addTo(map);
  _dozRenderBands(odjel);
}

let _dozCrossWarnEnabled = true;
function dozCrossWarnToggle() {
  _dozCrossWarnEnabled = document.getElementById('doz-cross-warn')?.checked ?? true;
}

// ─── Doznaka — Vlake prikaz i buffer ────────────────────────────
let _dozVlakeVisible = false;
let _dozVlakeIdxs = [];
let _dozBufLayers = [];
let _dozBufDeadLayers = [];
let _dozBufRadius = 40;
let _dozLinkedProjektId = null;

function _dozFindVlakeInBoundary(odjel) {
  const bndFeat = _dozGetBoundaryGeoJSON(odjel);
  if (!bndFeat) return [];
  const idxs = [];
  vlake.forEach((v, i) => {
    if (v.pts.length < 2) return;
    for (let k = 0; k < v.pts.length; k++) {
      const pt = turf.point([v.pts[k].lo, v.pts[k].la]);
      if (turf.booleanPointInPolygon(pt, bndFeat)) { idxs.push(i); return; }
    }
  });
  return idxs;
}

function dozToggleVlake() {
  _dozVlakeVisible = !_dozVlakeVisible;
  const btn = document.getElementById('doz-vlake-toggle');
  const bufSec = document.getElementById('doz-buf-section');

  if (!_dozVlakeVisible) {
    btn.innerHTML = '<svg class="ic"><use href="#ic-prikazi"/></svg> Prikaži';
    bufSec.style.display = 'none';
    _dozVlakeIdxs.forEach(i => {
      const v = vlake[i]; if (!v) return;
      [v.poly, v.labelMk, v.lagerMk, ...(v.extraLabels||[])].filter(Boolean).forEach(l => {
        try { if (map.hasLayer(l)) map.removeLayer(l); } catch(e) {}
      });
    });
    _dozVlakeIdxs = [];
    dozClearBuf();
    _dozRenderVlakeList();
    return;
  }

  if (_dozLinkedProjektId) {
    _dozShowLinkedVlake();
  } else {
    const odjel = _dozOdjeli.find(o => o.id === _dozSelId);
    if (odjel) _dozVlakeIdxs = _dozFindVlakeInBoundary(odjel);
    _dozVlakeIdxs.forEach(i => {
      const v = vlake[i];
      [v.poly, v.labelMk, v.lagerMk, ...(v.extraLabels||[])].filter(Boolean).forEach(l => {
        try { if (!map.hasLayer(l)) map.addLayer(l); } catch(e) {}
      });
    });
  }

  btn.innerHTML = '<svg class="ic"><use href="#ic-sakrij"/></svg> Sakrij';
  if (_dozVlakeIdxs.length) bufSec.style.display = 'block';
  _dozRenderVlakeList();
}

function _dozRenderLinkDropdown() {
  const sel = document.getElementById('doz-link-projekt');
  const status = document.getElementById('doz-link-status');
  if (!sel) return;
  let opts = '<option value="">— Poveži s vlake projektom —</option>';
  (_projekti || []).forEach(p => {
    const label = `${p.gj || ''} · ${p.odjel || ''}`.trim() || p.id.slice(0, 8);
    const nVlake = vlake.filter(v => v.projektId === p.id).length;
    opts += `<option value="${p.id}" ${p.id === _dozLinkedProjektId ? 'selected' : ''}>${_escHtml(label)} (${nVlake} vlaka)</option>`;
  });
  sel.innerHTML = opts;
  if (status) {
    if (_dozLinkedProjektId) {
      const p = _projekti.find(x => x.id === _dozLinkedProjektId);
      const nv = vlake.filter(v => v.projektId === _dozLinkedProjektId).length;
      status.innerHTML = `✔ Povezano: <b>${p?.odjel || '?'}</b> — ${nv} vlaka na mapi`;
    } else {
      status.textContent = '';
    }
  }
  _dozRenderVlakeList();
}

function _dozRenderVlakeList() {
  const list = document.getElementById('doz-vlake-list');
  if (!list) return;
  if (!_dozVlakeIdxs.length) {
    list.innerHTML = '<div class="doz-empty">Nema vlaka</div>';
    return;
  }
  let html = '<div style="max-height:140px;overflow-y:auto;">';
  _dozVlakeIdxs.forEach(i => {
    const v = vlake[i];
    const len = calcL(v.pts);
    const lenStr = len >= 1000 ? (len / 1000).toFixed(2) + ' km' : Math.round(len) + ' m';
    html += `<div style="display:flex;align-items:center;gap:6px;padding:3px 0;font-size:11px;border-bottom:1px solid #1e293b;">
      <span style="width:8px;height:8px;border-radius:50%;background:${v.color};flex-shrink:0;"></span>
      <span style="color:#e2e8f0;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${v.nm}</span>
      <span style="color:#64748b;font-family:monospace;flex-shrink:0;">${lenStr}</span>
      <button onclick="_dozRenameVlaka(${i})" title="Preimenuj" style="background:none;border:none;color:#64748b;font-size:12px;cursor:pointer;padding:2px 4px;flex-shrink:0;line-height:1;"><svg class="ic"><use href="#ic-crtaj"/></svg></button>
    </div>`;
  });
  html += '</div>';
  list.innerHTML = html;
}

// Preimenuj vlaku/krak direktno iz Doznaka panela — bez potrebe da korisnik prebacuje
// aktivni projekat na taj vlake projekat da bi mu se ta vlaka pojavila u tabu "Vlake".
async function _dozRenameVlaka(i) {
  const v = vlake[i], owner=sbUser?.id;
  if (!v) return;
  // _dlgPrompt (HTML dijalog), NE native prompt() — WebView bi za native prompt()
  // prikazao "The page at appassets.androidplatform.net says:" (vidi onJsAlert/
  // onJsConfirm override u MainActivity.java; onJsPrompt namjerno NIJE override-ovan).
  const nn = await _dlgPrompt('Novi naziv vlake/kraka:', v.nm, { title: 'Preimenuj vlaku', vlakaKeyboard: true });
  if (!nn || !nn.trim() || nn.trim() === v.nm) return;
  if (sbUser?.id!==owner || vlake[i]!==v || !await renameVlaka(i, nn.trim())) return;
  _dozRenderVlakeList();
  if (_dozTreePts.length) dozTreesAnalyze();
}

function dozLinkProjektChange() {
  const sel = document.getElementById('doz-link-projekt');
  const newId = sel?.value || null;
  if (_dozVlakeVisible && _dozLinkedProjektId !== newId) {
    _dozVlakeIdxs.forEach(i => {
      const v = vlake[i]; if (!v) return;
      [v.poly, v.labelMk, v.lagerMk, ...(v.extraLabels || [])].filter(Boolean).forEach(l => {
        try { if (map.hasLayer(l)) map.removeLayer(l); } catch(e) {}
      });
    });
    _dozVlakeIdxs = [];
    dozClearBuf();
  }
  _dozLinkedProjektId = newId;
  if (newId) {
    _dozShowLinkedVlake();
    _dozRenderVlakeList();
    const status = document.getElementById('doz-link-status');
    const p = _projekti.find(x => x.id === newId);
    const nv = vlake.filter(v => v.projektId === newId).length;
    if (status) status.innerHTML = `✔ Povezano: <b>${p?.odjel || '?'}</b> — ${nv} vlaka na mapi`;
  } else {
    _dozVlakeVisible = false;
    const btn = document.getElementById('doz-vlake-toggle');
    if (btn) btn.innerHTML = '<svg class="ic"><use href="#ic-prikazi"/></svg> Prikaži';
    document.getElementById('doz-buf-section').style.display = 'none';
    document.getElementById('doz-link-status').textContent = '';
    document.getElementById('doz-vlake-list').innerHTML = '<div class="doz-empty">Nema vlaka</div>';
  }
}

// ─── Učitaj vlake/krakove iz KML-a — pune, uređivane vlake (identično crtanju/snimanju) ──
function dozVlakeLoadKml(ev) {
  const file = ev.target.files[0];
  ev.target.value = '';
  if (!file) return;
  if (!_dozLinkedProjektId) {
    showToast('⚠ Prvo poveži odjel sa vlake projektom (padajući meni iznad)');
    return;
  }
  const projectId=_dozLinkedProjektId,odjelId=_dozSelId,owner=sbUser?.id;
  const r = new FileReader();
  r.onload = e => {
    if(sbUser?.id!==owner||_dozSelId!==odjelId||_dozLinkedProjektId!==projectId){showToast('Uvoz otkazan jer se odjel ili projekat promijenio');return;}
    try {
      const doc = new DOMParser().parseFromString(e.target.result, 'text/xml');
      const newIdxs = [];
      // Dedup po imenu unutar projekta: server ima unique(korisnik, projekt, nm),
      // pa bi dupli import (isti KML 2x, ili ime koje već postoji) na flush-u
      // UPDATE-ovao TUĐI red i obje lokalne vlake bi dobile ISTI sbId — kasniji
      // edit/brisanje jedne tiho pregazi/obriše drugu. Preskačemo duplikate.
      const existingNames = new Set(
        vlake.filter(v => v.projektId === _dozLinkedProjektId).map(v => v.nm));
      // br/fallback-ime po BROJU VLAKA U OVOM PROJEKTU, ne po globalnom vlake.length —
      // inače uvoz u projekat sa 3 vlake dobije npr. "Vlaka 15" (globalni indeks svih
      // projekata) umjesto "Vlaka 4", što zbunjuje numeraciju unutar projekta.
      let projCount = existingNames.size;
      let skipped = 0;
      doc.querySelectorAll('Placemark').forEach(pm => {
        const lsEl = pm.querySelector('LineString coordinates');
        if (!lsEl) return; // preskoči tačke (stabla) i poligone — ovo je uvoz vlaka/kraka
        const cs = pcs(lsEl.textContent);
        if (cs.length < 2) return;
        const pts = cs.map(c => ({ la: c[0], lo: c[1], al: 0 }));
        const nm = pm.querySelector('name')?.textContent?.trim() || `Vlaka ${projCount + 1}`;
        if (existingNames.has(nm)) { skipped++; return; }
        existingNames.add(nm);
        projCount++;
        const col = PAL[vlake.length % PAL.length];
        const poly = L.polyline(pts.map(p => [p.la, p.lo]), { color: col, weight: 3 }).addTo(map);
        // Identičan oblik objekta kao ručno crtanje/snimanje (vidi _routeToVlaka) —
        // ista polja znače isti tretman svuda (rename, brisanje, buffer, sync, štampanje...).
        vlake.push({
          nm, br: projCount, kr: 0, strana: null, color: col, lager: '', pts, poly, wpts: [],
          sbId: null, projektId: _dozLinkedProjektId,
          projektantIme: typeof getIme === 'function' ? getIme() : '',
          labelMk: null, lagerMk: null, extraLabels: [], updatedAt: new Date().toISOString()
        });
        newIdxs.push(vlake.length - 1);
      });
      if (!newIdxs.length) {
        showToast(skipped
          ? `⚠ Sve vlake iz KML-a (${skipped}) već postoje u projektu — ništa nije uvezeno`
          : '⚠ KML nema linija (LineString) — provjeri da li je fajl sa vlakama');
        return;
      }
      newIdxs.forEach(i => updateVlakaLabel(i));
      rndList();
      newIdxs.forEach(i => sbFlushVlaka(i));  // isti sync kao svaka nova/izmijenjena vlaka
      try {
        const b = L.featureGroup(newIdxs.map(i => vlake[i].poly)).getBounds();
        if (b.isValid()) map.fitBounds(b, { padding: [30, 30] });
      } catch(e) {}
      // Osvježi listu vlaka odjela (uključi nove), pokaži buffer sekciju i re-analiziraj
      // stabla ako su učitana (_dozShowLinkedVlake to već radi preko postojeće petlje).
      _dozShowLinkedVlake();
      const status = document.getElementById('doz-link-status');
      const p = _projekti.find(x => x.id === _dozLinkedProjektId);
      if (status) status.innerHTML = `✔ Povezano: <b>${p?.odjel || '?'}</b> — ${vlake.filter(v => v.projektId === _dozLinkedProjektId).length} vlaka na mapi`;
      showToast(`✅ Učitano ${newIdxs.length} vlaka/kraka iz KML-a${skipped ? ` (${skipped} preskočeno — već postoje)` : ''} — preimenuj po potrebi u tabu "Vlake"`);
    } catch(x) { showToast('⚠ Greška KML: ' + x.message); }
  };
  r.readAsText(file);
}

function dozBufChange() { _bufIzbor(document.getElementById('doz-buf-sel')); }

function dozDrawBuf() {
  dozClearBuf();
  if (!_dozVlakeIdxs.length) return;
  const polys = [];
  _dozVlakeIdxs.forEach(i => {
    const v = vlake[i];
    if (v.pts.length < 2) return;
    try {
      const coords = v.pts.map(p => [p.lo, p.la]);
      const line = turf.lineString(coords);
      const buf = turf.buffer(line, _dozBufRadius, { units: 'meters', steps: 8 });
      if (!buf) return;
      polys.push({ gj: buf, v });
      const lyr = L.geoJSON(buf, {
        style: { color: v.color, weight: 1.5, opacity: 0.8, fillColor: v.color, fillOpacity: 0.18 },
        interactive: false
      }).addTo(map);
      lyr.bindTooltip(`Buffer ${v.nm} ±${_dozBufRadius}m`, { sticky: true, opacity: 0.85 });
      _dozBufLayers.push(lyr);
    } catch(e) {}
  });
  for (let i = 0; i < polys.length; i++) {
    for (let j = i + 1; j < polys.length; j++) {
      try {
        const inter = turf.intersect(polys[i].gj, polys[j].gj);
        if (!inter) continue;
        const lyr = L.geoJSON(inter, {
          style: { color: '#ef4444', weight: 2, opacity: 1, fillColor: '#ef4444', fillOpacity: 0.55, dashArray: '4,3' },
          interactive: false
        }).addTo(map);
        lyr.bindTooltip(_escHtml(`⚠ Mrtva zona: ${polys[i].v.nm} ∩ ${polys[j].v.nm}`), { sticky: true, opacity: 0.95 });
        _dozBufDeadLayers.push(lyr);
      } catch(e) {}
    }
  }
  const el = document.getElementById('doz-buf-status');
  const dead = _dozBufDeadLayers.length;
  el.textContent = dead > 0
    ? `${_dozBufLayers.length} buffer(a). ⚠ ${dead} mrtva zona!`
    : `${_dozBufLayers.length} buffer(a). Nema preklapanja.`;
  el.style.display = 'block';
}

function dozClearBuf() {
  _dozBufLayers.forEach(l => map.removeLayer(l));
  _dozBufDeadLayers.forEach(l => map.removeLayer(l));
  _dozBufLayers = []; _dozBufDeadLayers = [];
  const el = document.getElementById('doz-buf-status');
  if (el) el.style.display = 'none';
}

// ─── Stabla van dohvata vitla (KML uvoz + analiza dosega) ────────────────────
// Ista logika kao "Buffer zona vlaka" (dozDrawBuf) — svaka vlaka se buffer-uje
// za _dozBufRadius (m), a stablo je "u dosegu" ako upada u BILO KOJI od tih
// buffera (union nije potreban, dovoljno je .some() preko svih poligona).
let _dozTreePts   = [];  // [{lat, lon, name, desc, ext, inReach}]
let _dozTreesLayer = null;

function dozTreesLoadKml(ev) {
  const file = ev.target.files[0];
  ev.target.value = '';
  if (!file) return;
  const odjelId=_dozSelId,owner=sbUser?.id;
  if(!odjelId||!owner){showToast('Prvo odaberi odjel');return;}
  const r = new FileReader();
  r.onload = e => {
    if(sbUser?.id!==owner||_dozSelId!==odjelId){showToast('Uvoz otkazan jer se odjel promijenio');return;}
    try {
      const doc = new DOMParser().parseFromString(e.target.result, 'text/xml');
      const pts = [];
      doc.querySelectorAll('Placemark').forEach(pm => {
        const coordsEl = pm.querySelector('Point coordinates');
        if (!coordsEl) return; // preskoči linije/poligone — ova sekcija je za pojedinačna stabla
        const raw = (coordsEl.textContent || '').trim().split(',');
        const lon = parseFloat(raw[0]), lat = parseFloat(raw[1]);
        if (!isFinite(lat) || !isFinite(lon)) return;
        pts.push({
          lat, lon,
          name: pm.querySelector('name')?.textContent?.trim() || '',
          desc: pm.querySelector('description')?.textContent?.trim() || '',
          ext: _parseKmlExtData(pm),
          inReach: true
        });
      });
      if (!pts.length) { showToast('⚠ KML nema tačaka (Point) — provjeri da li je fajl sa stablima'); return; }
      _dozTreePts = pts;
      dozTreesAnalyze();
      // Karta se ne pomjera sama — ako su stabla van trenutnog vidnog polja, korisnik
      // vidi "ništa" iako su markeri stvarno nacrtani. Uvijek centriraj na njih.
      if (_dozTreesLayer) {
        try {
          const b = _dozTreesLayer.getBounds();
          if (b.isValid()) map.fitBounds(b, { padding: [30, 30] });
        } catch(e) {}
      }
      showToast(`✅ Učitano ${pts.length} stabala iz KML-a`);
    } catch(x) { showToast('⚠ Greška KML: ' + x.message); }
  };
  r.readAsText(file);
}

function dozTreesAnalyze() {
  if (!_dozTreePts.length) return;
  const odjel = _dozOdjeli.find(o => o.id === _dozSelId);
  // UVIJEK svjež lookup nad vlake[] — _dozVlakeIdxs je samo UI-keš za prikaz liste
  // u sekciji "Vlake" i ažurira se JEDINO kad se eksplicitno pozove
  // _dozShowLinkedVlake(). Ako bismo ga koristili direktno ovdje (kao ranije),
  // "Osvježi analizu" bi promašio SVAKU vlaku dodanu poslije prvog otvaranja liste
  // — bez obzira da li je novododana (KML uvoz), novonacrtana (ručno crtanje, koje
  // ne prolazi kroz stopRec) ili novosnimljena. Direktan filter po projektId je
  // jeftin (par stotina vlaka najviše) i garantovano svjež.
  const idxs = _dozLinkedProjektId
    ? vlake.map((v, i) => v.projektId === _dozLinkedProjektId ? i : -1).filter(i => i >= 0)
    : (odjel ? _dozFindVlakeInBoundary(odjel) : []);
  // VAŽNO: stabla se učitavaju i prikazuju NEZAVISNO od toga da li vlake već postoje —
  // ako ih još nema, sva stabla su (ispravno) "van dosega" dok se prva vlaka ne snimi;
  // čim se vlaka pojavi/promijeni (stopRec, dodavanje/uklanjanje krakova, promjena
  // buffer radijusa, povezivanje projekta), dozTreesAnalyze() se zove ponovo i stabla
  // koja upadnu u novi pojas postaju zelena — bez ponovnog učitavanja KML-a.
  const radius = _dozBufRadius || 40;
  const polys = [];
  idxs.forEach(i => {
    const v = vlake[i];
    if (!v || v.pts.length < 2) return;
    try {
      const line = turf.lineString(v.pts.map(p => [p.lo, p.la]));
      const buf = turf.buffer(line, radius, { units: 'meters', steps: 8 });
      if (buf) polys.push(buf);
    } catch(e) {}
  });
  let inCount = 0, outCount = 0;
  _dozTreePts.forEach(t => {
    const pt = turf.point([t.lon, t.lat]);
    t.inReach = polys.length > 0 && polys.some(p => { try { return turf.booleanPointInPolygon(pt, p); } catch(e) { return false; } });
    if (t.inReach) inCount++; else outCount++;
  });
  _dozRenderTreeMarkers();
  _dozRenderTreesSummary(inCount, outCount, radius * 2, !polys.length);
  _dozTreesSaveCache();
}

// ─── Trajno pamćenje učitanih stabala po odjelu (localStorage) ───────────────
// Bez ovoga se _dozTreePts brisao svaki put kad se izađe iz detalja odjela
// (dozBackToList/dozSelectOdjel) — korisnik je morao iznova učitavati isti KML.
const _DOZ_TREES_DATA_KEY = 'tvlake_doz_trees_data';
function _dozTreesSaveCache() {
  if (!_dozSelId) return;
  try {
    const all = JSON.parse(localStorage.getItem(_DOZ_TREES_DATA_KEY) || '{}');
    if (_dozTreePts.length) {
      all[_dozSelId] = _dozTreePts.map(t => ({ lat: t.lat, lon: t.lon, name: t.name, desc: t.desc, ext: t.ext }));
    } else {
      delete all[_dozSelId];
    }
    localStorage.setItem(_DOZ_TREES_DATA_KEY, JSON.stringify(all));
  } catch(e) {}
}
function _dozTreesLoadCache(odjelId) {
  try {
    const all = JSON.parse(localStorage.getItem(_DOZ_TREES_DATA_KEY) || '{}');
    return all[odjelId] || null;
  } catch(e) { return null; }
}
// Poziva se pri otvaranju detalja odjela — učita ranije snimljena stabla (ako ih ima)
// bez traženja od korisnika da ponovo bira KML fajl.
function _dozTreesRestoreForOdjel(odjelId) {
  const cached = _dozTreesLoadCache(odjelId);
  if (cached && cached.length) {
    _dozTreePts = cached;
    dozTreesAnalyze();
  }
}

// ─── Stil tačaka stabala (boja/providnost) — pamti zadnje postavljeno ────────
const _DOZ_TREES_STYLE_KEY = 'tvlake_doz_trees_style';
function _getDozTreesStyle() {
  try {
    const s = JSON.parse(localStorage.getItem(_DOZ_TREES_STYLE_KEY) || 'null');
    if (s && s.inCol) return s;
  } catch(e) {}
  return { inCol: '#4ade80', outCol: '#ef4444', opacity: 0.95 };
}
function _setDozTreesStyle(style) {
  try { localStorage.setItem(_DOZ_TREES_STYLE_KEY, JSON.stringify(style)); } catch(e) {}
}
// Postavi kontrole (color picker/slider) na zadnje sačuvane vrijednosti — poziva se
// pri otvaranju detalja odjela, isti obrazac kao _dozRestoreBoundaryStyleUI.
function _dozRestoreTreesStyleUI() {
  const s = _getDozTreesStyle();
  const inEl  = document.getElementById('doz-trees-in-col');
  const outEl = document.getElementById('doz-trees-out-col');
  const opEl  = document.getElementById('doz-trees-opacity');
  if (inEl)  inEl.value  = s.inCol;
  if (outEl) outEl.value = s.outCol;
  if (opEl)  opEl.value  = Math.round(s.opacity * 100);
  const opLbl = document.getElementById('doz-trees-opacity-lbl');
  if (opLbl) opLbl.textContent = Math.round(s.opacity * 100) + '%';
  const inSw  = document.getElementById('doz-trees-in-swatch');
  const outSw = document.getElementById('doz-trees-out-swatch');
  if (inSw)  { inSw.style.background  = `rgba(${_hexToRgbCsv(s.inCol)},${s.opacity})`;  inSw.style.borderColor  = s.inCol; }
  if (outSw) { outSw.style.background = `rgba(${_hexToRgbCsv(s.outCol)},${s.opacity})`; outSw.style.borderColor = s.outCol; }
}
function dozTreesStyleChange() {
  const inCol   = document.getElementById('doz-trees-in-col')?.value || '#4ade80';
  const outCol  = document.getElementById('doz-trees-out-col')?.value || '#ef4444';
  const opacity = parseInt(document.getElementById('doz-trees-opacity')?.value || 95) / 100;
  const opLbl = document.getElementById('doz-trees-opacity-lbl');
  if (opLbl) opLbl.textContent = Math.round(opacity * 100) + '%';
  const inSw  = document.getElementById('doz-trees-in-swatch');
  const outSw = document.getElementById('doz-trees-out-swatch');
  if (inSw)  { inSw.style.background  = `rgba(${_hexToRgbCsv(inCol)},${opacity})`;  inSw.style.borderColor  = inCol; }
  if (outSw) { outSw.style.background = `rgba(${_hexToRgbCsv(outCol)},${opacity})`; outSw.style.borderColor = outCol; }
  _setDozTreesStyle({ inCol, outCol, opacity });
  if (_dozTreesLayer) _dozRenderTreeMarkers();  // samo redraw — analiza (in/out) se ne mijenja
}

function _dozRenderTreeMarkers() {
  if (_dozTreesLayer) { try { map.removeLayer(_dozTreesLayer); } catch(e) {} }
  _dozTreesLayer = L.layerGroup().addTo(map);
  const st = _getDozTreesStyle();
  _dozTreePts.forEach(t => {
    const col = t.inReach ? st.inCol : st.outCol;
    const m = L.circleMarker([t.lat, t.lon], {
      radius: t.inReach ? 4 : 6, color: '#fff', weight: 1, fillColor: col, fillOpacity: st.opacity
    });
    const extRows = Object.entries(t.ext || {}).map(([k, v]) =>
      `<div><b>${_escHtml(k)}:</b> ${_escHtml(v)}</div>`).join('');
    m.bindPopup(`<div style="min-width:160px;font-size:12px;color:#1e293b;">
      <b>${_escHtml(t.name || 'Stablo')}</b>
      <div style="margin:4px 0;font-weight:600;color:${t.inReach ? '#16a34a' : '#dc2626'};">
        ${t.inReach ? '✓ U dosegu vitla' : '⚠ VAN dosega vitla'}
      </div>
      ${t.desc ? `<div style="margin-bottom:4px;">${_escHtml(t.desc)}</div>` : ''}
      ${extRows}
    </div>`);
    m.addTo(_dozTreesLayer);
  });
}

function _dozRenderTreesSummary(inCount, outCount, totalWidthM, noVlakeYet) {
  const el = document.getElementById('doz-trees-summary');
  if (!el) return;
  const total = inCount + outCount;
  el.innerHTML = `
    ${noVlakeYet ? `<div style="font-size:10.5px;color:#fbbf24;background:#3a2a0a;border:1px solid #78350f;border-radius:6px;padding:6px 8px;margin:8px 0 0;">⚠ Još nema snimljene vlake u ovom odjelu — sva stabla su prikazana kao "van dosega". Čim se vlaka snimi, stabla u pojasu automatski postaju zelena.</div>` : ''}
    <div style="display:flex;gap:6px;margin:8px 0;">
      <div style="flex:1;background:#0f172a;border:1px solid #1e3a5f;border-radius:6px;padding:8px 4px;text-align:center;">
        <div style="font-size:18px;font-weight:700;color:#e2e8f0;">${total}</div>
        <div style="font-size:9.5px;color:#64748b;">Ukupno stabala</div>
      </div>
      <div style="flex:1;background:#0f172a;border:1px solid #7f1d1d;border-radius:6px;padding:8px 4px;text-align:center;">
        <div style="font-size:18px;font-weight:700;color:#ef4444;">${outCount}</div>
        <div style="font-size:9.5px;color:#64748b;">Van dosega (${totalWidthM}m)</div>
      </div>
      <div style="flex:1;background:#0f172a;border:1px solid #14532d;border-radius:6px;padding:8px 4px;text-align:center;">
        <div style="font-size:18px;font-weight:700;color:#4ade80;">${inCount}</div>
        <div style="font-size:9.5px;color:#64748b;">U dosegu</div>
      </div>
    </div>
    <button class="btn b" style="width:100%;font-size:11px;padding:6px;margin-bottom:6px;" onclick="dozTreesAnalyze()"><svg class="ic"><use href="#ic-osvjezi"/></svg> Osvježi analizu</button>
    <button class="btn b" style="width:100%;font-size:11px;padding:6px;margin-bottom:6px;" onclick="dozTreesExportOut()">⬇ Izvezi listu van dosega (KML)</button>
    <button class="btn gr" style="width:100%;font-size:11px;padding:6px;" onclick="dozTreesRemoveSaved()"><svg class="ic"><use href="#ic-zatvori"/></svg> Ukloni stabla sa karte</button>
  `;
}

// Čisti samo prikaz (mapa/panel) — koristi se interno pri prelasku na drugi odjel,
// NE dira sačuvani keš (stabla ostaju zapamćena za odjel iz kojeg se izlazi).
function dozTreesClear() {
  if (_dozTreesLayer) { try { map.removeLayer(_dozTreesLayer); } catch(e) {} _dozTreesLayer = null; }
  _dozTreePts = [];
  const el = document.getElementById('doz-trees-summary');
  if (el) el.innerHTML = '';
}

// Eksplicitno dugme "Ukloni stabla sa karte" — korisnik stvarno želi da ih se
// riješi, pa se i sačuvani keš za ovaj odjel briše (inače bi se vratila pri
// sljedećem otvaranju odjela).
function dozTreesRemoveSaved() {
  dozTreesClear();
  _dozTreesSaveCache();  // _dozTreePts je sad prazan → ovo briše zapis za _dozSelId
}

function dozTreesExportOut() {
  const out = _dozTreePts.filter(t => !t.inReach);
  if (!out.length) { showToast('Nema stabala van dosega'); return; }
  const odjel = _dozOdjeli.find(o => o.id === _dozSelId);
  const placemarks = out.map(t => `  <Placemark>
    <name>${_escXml(t.name || 'Stablo')}</name>
    <description>${_escXml(t.desc || '')}</description>
    <Point><coordinates>${t.lon},${t.lat},0</coordinates></Point>
  </Placemark>`).join('\n');
  const kml = `<?xml version="1.0" encoding="UTF-8"?>
<kml xmlns="http://www.opengis.net/kml/2.2"><Document>
<name>Van dosega vitla - ${_escXml(odjel?.name || '')}</name>
${placemarks}
</Document></kml>`;
  const a = document.createElement('a');
  a.href = URL.createObjectURL(new Blob([kml], { type: 'application/vnd.google-earth.kml+xml' }));
  a.download = `van_dosega_${(odjel?.name || 'odjel').replace(/[^a-zA-Z0-9_\-]/g, '_')}.kml`;
  a.click();
  setTimeout(() => URL.revokeObjectURL(a.href), 4000);
}

// ─── Status odjela (Aktivno / Pauza / Završeno) ──────────────────
const _DOZ_STATUSES = [
  { key: 'active',    label: 'Aktivno',  color: '#4ade80' },
  { key: 'paused',    label: 'Pauza',    color: '#fbbf24' },
  { key: 'completed', label: 'Završeno', color: '#60a5fa' }
];

function _dozRenderStatusRow() {
  const el = document.getElementById('doz-status-row');
  if (!el) return;
  const odjel = _dozOdjeli.find(o => o.id === _dozSelId);
  if (!odjel) { el.innerHTML = ''; return; }
  const cur = odjel.status || 'active';
  const canEdit = odjel.created_by === sbUser?.id;
  el.innerHTML = _DOZ_STATUSES.map(s => {
    const on = s.key === cur;
    return `<button aria-pressed="${on}" ${canEdit ? '' : 'disabled'} onclick="dozSetStatus('${s.key}')" style="flex:1;padding:5px 4px;font-size:11px;font-weight:600;border-radius:6px;cursor:${canEdit ? 'pointer' : 'default'};
      background:${on ? s.color + '22' : 'rgba(15,23,42,0.7)'};
      border:1px solid ${on ? s.color : '#1e293b'};
      color:${on ? s.color : '#475569'};">${s.label}</button>`;
  }).join('') + (canEdit ? '' : '<span style="flex-basis:100%;font-size:11px;color:var(--field-muted,#94a3b8);padding-top:5px">Status odjela mijenja njegov kreator. Svoje pojaseve možeš snimati i poslati.</span>');
}

async function dozSetStatus(status) {
  if(!['active','paused','completed'].includes(status)||!sbUser?.id)return;
  const odjel=_dozOdjeli.find(o=>o.id===_dozSelId);
  if(!odjel||(odjel.status||'active')===status)return;
  if(odjel.created_by!==sbUser.id){showToast('Status odjela može mijenjati samo njegov kreator');return;}
  const changes=[{id:odjel.id,status}];
  if(status==='active')for(const other of _dozOdjeli)if(other.id!==odjel.id&&other.status==='active'&&other.created_by===sbUser.id)changes.push({id:other.id,status:'paused'});
  try{
    const ids=new Set(changes.map(c=>c.id)),uid=sbUser.id;
    const q=_OL.loadQueue(true).filter(op=>!(op.type==='upsert_doz_status'&&op._uid===uid&&ids.has(op.payload?.id)));
    for(const payload of changes)q.push({type:'upsert_doz_status',payload,_uid:uid,_qid:_genUUID(),ts:Date.now()});
    localStorage.setItem(_OL.QUEUE,JSON.stringify(q));
  }catch(e){showToast('⚠ Status nije sačuvan — prethodni izbor ostaje');return;}
  for(const change of changes){const target=_dozOdjeli.find(o=>o.id===change.id);if(target)target.status=change.status;}
  _OL.save(_OL.DOZ_ODJELI,_dozOdjeli);
  _dozRenderStatusRow();dozRenderOdjeli();
  if(typeof _updSyncBadge==='function')_updSyncBadge();
  showToast('Status sačuvan — pošalji kroz Meni → Server'+(changes.length>1?' · tvoji ostali aktivni odjeli pauzirani':''));
}

// Zoom na zonu sa liste u panelu
function dozZoomMarking(id) {
  const lyr = _dozMarkingLayerById[id];
  if (!lyr) return;
  try {
    const b = lyr.getBounds();
    if (b.isValid()) { map.fitBounds(b, { padding: [50, 50] }); lyr.openPopup(); }
  } catch(e) {}
}

// ─── Render Detail Panel ─────────────────────────────────────────

// Dužina GPS traga po korisniku (sa 5-min gap segmentacijom, kao na mapi)
function _dozTrackLenByUser(byUserIn) {
  const GAP_MS = 5 * 60 * 1000;
  const byUser = byUserIn || _dozTragoviPoKorisniku();
  const lens = {};
  Object.entries(byUser).forEach(([uid, pts]) => {
    let len = 0;
    for (let i = 1; i < pts.length; i++) {
      const dt = _dozTackaMs(pts[i]) - _dozTackaMs(pts[i-1]);
      if (dt > GAP_MS) continue; // pauza — ne spajaj segmente
      len += dst(pts[i-1].latitude, pts[i-1].longitude, pts[i].latitude, pts[i].longitude);
    }
    lens[uid] = len;
  });
  return lens;
}

function dozGoSection(key) {
  document.getElementById('doz-section-'+key)?.scrollIntoView({block:'start',behavior:'smooth'});
}
// Traka pregleda ispod zaglavlja: odgovor na prvo pitanje pri otvaranju odjela
// ("koliko je urađeno") bez skrolanja do statistike. Brojevi dolaze iz ISTE
// računice kao statistika (_dozPokrivenost), pa se dva mjesta ne mogu razići.
function _dozPregledRender(d) {
  const el = document.getElementById('doz-pregled');
  if (!el) return;
  if (!d || !(d.bndHa > 0)) { el.hidden = true; el.innerHTML = ''; return; }
  const pct = Math.max(0, Math.min(100, d.bandPct || 0));
  el.hidden = false;
  el.innerHTML = `<div class="dpg-top"><b>${pct}%</b><span>pokriveno pojasevima<small>${fmtHa(d.bandHa)} od ${fmtHa(d.bndHa)} unutar granice</small></span></div>
    <div class="dpg-bar" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct}"><i style="width:${pct}%"></i></div>
    <div class="dpg-meta"><span>${d.nZona} ${d.nZona === 1 ? 'zona' : (d.nZona % 10 >= 2 && d.nZona % 10 <= 4 && (d.nZona % 100 < 12 || d.nZona % 100 > 14)) ? 'zone' : 'zona'}</span><span>👣 ${fmtL(d.trag)}</span>${d.preklopHa >= 0.01 ? `<span class="w">preklop ${fmtHa(d.preklopHa)}</span>` : ''}</div>`;
}
// Postavke prikaza (pojasevi, stil) su rijetke — sklopljene, izbor se pamti.
const _DOZ_POSTAVKE_KEY = 'tvlake_doz_postavke_otvoreno';
function _dozPostavkeToggle(el) {
  try { localStorage.setItem(_DOZ_POSTAVKE_KEY, el.open ? '1' : '0'); } catch (e) {}
}
function _dozPostavkeRestore() {
  const el = document.getElementById('doz-postavke');
  if (!el) return;
  let o = false; try { o = localStorage.getItem(_DOZ_POSTAVKE_KEY) === '1'; } catch (e) {}
  if (el.open !== o) el.open = o;
}
function dozRenderDetail() {
  _dozPostavkeRestore();
  if(typeof DoznakaPlan!=='undefined')DoznakaPlan.sync().catch(()=>{});
  if(typeof _dozLocalStatusRender==='function')_dozLocalStatusRender();
  // ── Statistika ──
  const odjel = _dozOdjeli.find(o => o.id === _dozSelId);
  const context=document.getElementById('doz-context');
  // Ime odjela već stoji u zaglavlju (i u gornjoj traci) — ovdje bi bio treći put.
  if(context&&odjel){const myName=typeof getIme==='function'?getIme():'Projektant';context.textContent=myName+(odjel._pendingSync?' · odjel čeka slanje':'')+' · šalješ kroz Meni → Server';}
  const statsEl = document.getElementById('doz-stats-box');
  if (statsEl && odjel) {
    const totalHa = parseFloat(odjel.known_area_ha) || 0;
    let bndHa = 0;
    try { const bf = _dozGetBoundaryGeoJSON(odjel); if (bf) bndHa = turf.area(bf) / 10000; } catch(e) {}
    const markedHa = _dozMarkings.reduce((s, m) => s + (parseFloat(m.area_ha) || 0), 0);
    const pokr = _dozPokrivenost(odjel);
    const bandHa = pokr.ukupnoHa;
    const bandPct = bndHa > 0 ? Math.min(100, Math.round(bandHa / bndHa * 100)) : 0;
    const byUserT = _dozTragoviPoKorisniku();
    const totalTrackLen = Object.values(_dozTrackLenByUser(byUserT)).reduce((s, v) => s + v, 0);
    const nPts = Object.values(byUserT).reduce((s, a) => s + a.length, 0);
    const created = odjel.created_at ? fmtDateShort(odjel.created_at) : '—';
    const kpi = (val, lbl, col) => `<div class="pm-kpi"><div class="pm-kpi-val" style="font-size:14px;${col ? 'color:' + col + ';' : ''}">${val}</div><div class="pm-kpi-lbl">${lbl}</div></div>`;
    statsEl.innerHTML = `
      <div class="pm-kpi-grid" style="grid-template-columns:repeat(3,1fr);">
        ${kpi(fmtHa(totalHa || bndHa), 'Površina')}
        ${kpi(fmtHa(bandHa), 'Pojasevi', '#4ade80')}
        ${kpi(_dozMarkings.length, 'Zone' + (markedHa > 0 ? ' · ' + fmtHa(markedHa) : ''))}
        ${kpi(_dozMembers.length, 'Projektanti')}
        ${kpi(fmtL(totalTrackLen), 'GPS trag')}
        ${kpi(nPts, 'GPS tačaka')}
      </div>
      <div class="doz-kreiran">Kreiran ${created}</div>`;
    _dozPregledRender({ bndHa, bandHa, bandPct, preklopHa: pokr.preklopHa, nZona: _dozMarkings.length, trag: totalTrackLen });
  } else _dozPregledRender(null);

  // Members — sa dužinom pređenog GPS traga i pokrivenom površinom
  const trackLens = _dozTrackLenByUser();
  const pokrClan = odjel ? _dozPokrivenost(odjel).poKorisniku : {};
  const ml = document.getElementById('doz-members-list');
  ml.innerHTML = _dozMembers.length
    ? _dozMembers.map((m, i) => {
        const k = m._korisnik;
        const name = k ? (`${k.ime||''} ${k.prezime||''}`.trim() || `Projektant ${i+1}`) : `Projektant ${i+1}`;
        const color = k?.boja || DOZ_ENG_COLORS[i % DOZ_ENG_COLORS.length];
        const tl = trackLens[m.user_id];
        return `<div class="doz-member-row">
          <div class="doz-member-dot" style="background:${color};"></div>
          <div class="doz-member-name">${_escHtml(name)}
            ${m.role === 'manager' ? '<span style="color:#fbbf24;font-size:10px;"> ★</span>' : ''}
          </div>
          ${tl > 0 ? `<span class="doz-member-len">👣 ${fmtL(tl)}</span>` : ''}
          ${pokrClan[m.user_id] > 0 ? `<span class="doz-member-len" style="color:#4ade80;">▦ ${fmtHa(pokrClan[m.user_id])}</span>` : ''}
        </div>`;
      }).join('')
    : '<div class="doz-empty">Nema članova</div>';

  // Vlake link dropdown
  _dozRenderLinkDropdown();

  // Markings summary (chips po tipu)
  const counts = {};
  _dozMarkings.forEach(m => { counts[m.marking_type] = (counts[m.marking_type] || 0) + 1; });
  const ms = document.getElementById('doz-markings-summary');
  const chips = Object.entries(DOZ_TYPES)
    .filter(([k]) => counts[k])
    .map(([k, t]) => `<div class="doz-marking-chip" style="border-color:${t.color};color:${t.color};">${t.emoji} ${counts[k]}</div>`)
    .join('');
  ms.innerHTML = chips || '<span class="doz-empty">Nema označenih zona</span>';
  document.getElementById('doz-markings-count').textContent = _dozMarkings.length;

  // Ukupna obilježena površina vs. površina odjela
  const areaEl = document.getElementById('doz-marked-area');
  if (areaEl) {
    const totHa = _dozMarkings.reduce((s, m) => s + (parseFloat(m.area_ha) || 0), 0);
    if (totHa > 0) {
      const odjel = _dozOdjeli.find(o => o.id === _dozSelId);
      const knownHa = parseFloat(odjel?.known_area_ha) || 0;
      const pct = knownHa > 0 ? ` (${Math.min(100, Math.round(totHa / knownHa * 100))}% odjela)` : '';
      areaEl.innerHTML = `Ukupno obilježeno: <b style="color:#4ade80;">${totHa.toFixed(2)} ha</b>${pct}`;
    } else areaEl.innerHTML = '';
  }

  // Lista zona — klik zoomira na zonu na mapi
  const zl = document.getElementById('doz-zones-list');
  if (zl) {
    zl.innerHTML = _dozMarkings.map(m => {
      const t = DOZ_TYPES[m.marking_type] || DOZ_TYPES.custom;
      const isLocal = String(m.id).startsWith('local_');
      const meta = [
        m.area_ha ? parseFloat(m.area_ha).toFixed(2) + ' ha' : '',
        m.created_at ? fmtDateShort(m.created_at) : '',
        isLocal ? '⏳ čeka sync' : ''
      ].filter(Boolean).join(' · ');
      return `<div class="doz-zone-row" onclick="dozZoomMarking('${m.id}')">
        <span class="doz-zone-emoji">${t.emoji}</span>
        <div class="doz-zone-info">
          <div class="doz-zone-name" style="color:${t.color};">${_escHtml(m.label || t.label)}</div>
          <div class="doz-zone-meta">${meta}</div>
        </div>
        <button class="doz-zone-del" onclick="event.stopPropagation();dozDeleteMarking('${m.id}')" title="Obriši zonu"><svg class="ic"><use href="#ic-obrisi"/></svg></button>
      </div>`;
    }).join('');
  }
}

// ─── GPS Tracking ─────────────────────────────────────────────────
function dozToggleGPS() {
  _dozGpsOn ? dozOpenGPSControls() : dozStartGPS();
}

// Kontrole su samo prikaz postojećeg GPS dnevnika. Sklanjanje ne prekida watch.
let _dozGpsControlsTimer = null, _dozGpsControlsFocus = null;
let _dozGpsControlsAccuracy = null, _dozGpsControlsAccuracyTs = 0;
let _dozGpsControlsBusy = false;
function dozOpenGPSControls() {
  const modal = document.getElementById('doz-gps-modal');
  if (!_dozGpsOn || !modal) return;
  if (modal.hidden) _dozGpsControlsFocus = document.activeElement;
  modal.hidden = false;
  document.body.classList.add('doz-gps-controls-on');
  if (typeof switchTab === 'function' && _activeTab !== 'karta') switchTab('karta');
  if (typeof _abVisinaSync === 'function') _abVisinaSync();
  if (typeof _recBarSync === 'function') _recBarSync();
  _dozGpsControlsSync();
  if (!_dozGpsControlsTimer) _dozGpsControlsTimer = setInterval(_dozGpsControlsSync, 1000);
  document.getElementById('doz-gps-modal-pause')?.focus({preventScroll:true});
}
function dozCloseGPSControls(showMap) {
  const modal = document.getElementById('doz-gps-modal');
  if (modal) modal.hidden = true;
  document.body.classList.remove('doz-gps-controls-on');
  if (typeof _abVisinaSync === 'function') _abVisinaSync();
  if (_dozGpsControlsTimer) clearInterval(_dozGpsControlsTimer);
  _dozGpsControlsTimer = null;
  if (typeof _recBarSync === 'function') _recBarSync();
  if (showMap && typeof switchTab === 'function') switchTab('karta');
  else if (_dozGpsControlsFocus?.isConnected && _dozGpsControlsFocus.getClientRects().length) _dozGpsControlsFocus.focus({preventScroll:true});
  _dozGpsControlsFocus = null;
}
function dozGPSControlsKey(e) {
  if(e.key==='Escape') { e.preventDefault(); e.stopPropagation(); dozCloseGPSControls(); return; }
}
function _dozGpsControlsSync(acc) {
  if (acc !== undefined) {
    _dozGpsControlsAccuracy = Number.isFinite(acc) ? acc : null;
    _dozGpsControlsAccuracyTs = Date.now();
  }
  const modal = document.getElementById('doz-gps-modal');
  if (!modal || modal.hidden || document.hidden) return;
  if (!_dozGpsOn) { dozCloseGPSControls(); return; }
  const put = (id, value) => { const el=document.getElementById(id); if(el) el.textContent=value; };
  const project = _dozOdjeli.find(p=>p.id===_dozGpsProjId);
  put('doz-gps-modal-project', project?.name || 'Odjel doznake');
  put('doz-gps-modal-user', typeof getIme==='function' ? getIme() : 'Projektant');
  const busy=_dozGpsControlsBusy || _dozGpsStopping;
  put('doz-gps-modal-state', busy ? 'Spremam završetak…' : _dozGpsPaused ? 'Snimanje pauzirano' : 'Snimanje aktivno');
  modal.classList.toggle('is-paused', _dozGpsPaused);
  put('doz-gps-modal-length', fmtL(_dozGpsLen));
  const pauseMs=_dozGpsPausedTime+(_dozGpsPaused && _dozGpsPauseStart ? Date.now()-_dozGpsPauseStart : 0);
  const seconds=Math.max(0,Math.floor((Date.now()-_dozGpsStartTs-pauseMs)/1000));
  put('doz-gps-modal-time', [Math.floor(seconds/3600),Math.floor(seconds/60)%60,seconds%60].map(n=>String(n).padStart(2,'0')).join(':'));
  put('doz-gps-modal-points', _dozGpsPts.length);
  const fresh=Date.now()-_dozGpsControlsAccuracyTs < 15000;
  const accuracy=fresh ? _dozGpsControlsAccuracy : null;
  put('doz-gps-modal-signal', accuracy===null ? 'Čekam GPS signal' : accuracy>20 ? 'Slab signal · ±'+Math.round(accuracy)+' m' : 'GPS preciznost · ±'+Math.round(accuracy)+' m');
  put('doz-gps-modal-note', _dozGpsPaused ? 'Kretanje tokom pauze ne dodaje se u trag. Pritisni Nastavi za nastavak doznake.' : 'Trag se čuva na telefonu. Podatke šalješ kroz Pošalji na server.');
  const pause=document.getElementById('doz-gps-modal-pause'),stop=document.getElementById('doz-gps-modal-stop');
  if(pause) { pause.textContent=_dozGpsPaused ? '▶ Nastavi' : '⏸ Pauza'; pause.disabled=busy; }
  if(stop) stop.disabled=busy;
}
async function dozFinishGPSControls() {
  if (!_dozGpsOn || _dozGpsControlsBusy || _dozGpsStopping) return;
  _dozGpsControlsBusy=true;
  _dozGpsControlsSync();
  try { await dozStopGPS(); }
  catch(e) { console.warn('Završetak GPS doznake',e); showToast('⚠ Završetak nije potvrđen — ponovi ili izvezi trag'); }
  finally { _dozGpsControlsBusy=false; _dozGpsControlsSync(); }
}

let _dozGpsSent = 0, _dozGpsBuffered = 0, _dozGpsLen = 0, _dozGpsStartTs = 0;
let _dozGpsPaused = false, _dozGpsPausedTime = 0, _dozGpsPauseStart = 0;
let _dozGpsMaxSpd = 0, _dozGpsSpdSum = 0, _dozGpsSpdCnt = 0;
let _dozGpsElevData = [];
let _dozGpsFullPts = [];
let _dozGpsExportContext = null;
// Timestamp zadnjeg uspješno obrađenog fiksa (uključujući filtrirane).
// Ne napreduje kad trajni upis padne — koristi ga _drainNativeGpsBuffer
// da pri replay-u native bafera preskoči tačke koje su VEĆ obrađene uživo.
// Bez ovoga bi svaki povratak u app ponovo poslao (dupli insert u
// doz_track_points!) sve tačke prikupljene dok je app bio u prvom planu, jer
// GpsService puni bafer kontinuirano cijelo vrijeme snimanja, ne samo dok je
// app u pozadini.
let _dozLastLiveFixTs = 0;

function dozPauseGPS() {
  if (!_dozGpsOn || _dozGpsStopping || (typeof _dozGpsControlsBusy !== 'undefined' && _dozGpsControlsBusy)) return;
  _dozGpsPaused = !_dozGpsPaused;
  if (_dozGpsPaused) _pauziOtvoriProzor(_dozPauseWin); else _pauziZatvoriProzor(_dozPauseWin);
  const btn = document.getElementById('doz-gps-pause');
  const st = document.getElementById('doz-gps-status');
  if (_dozGpsPaused) {
    _dozGpsPauseStart = Date.now();
    if (btn) { btn.textContent = '▶'; btn.style.background = '#052e16'; btn.style.borderColor = '#166534'; btn.style.color = '#4ade80'; }
    if (st) { st.textContent = '⏸ Pauza'; st.style.color = '#fbbf24'; }
  } else {
    _dozGpsPausedTime += Date.now() - _dozGpsPauseStart;
    _dozGpsPauseStart = 0;
    if (btn) { btn.textContent = '⏸'; btn.style.background = '#422006'; btn.style.borderColor = '#92400e'; btn.style.color = '#fbbf24'; }
    if (st) { st.textContent = '● Snimanje aktivno'; st.style.color = '#4ade80'; }
  }
  _dozGpsControlsSync();
  if (typeof _recBarUpdate === 'function') _recBarUpdate();
}

function _dozUpdGpsStats(acc) {
  if (typeof _fieldStatusUpdate==='function') _fieldStatusUpdate.accuracyDoz=acc;
  if (document.hidden) return;
  // IDB/native dopuna može donijeti više tačaka prije sljedećeg frame-a.
  // Spremanje ostaje po tački, a ekran crta samo najnovije potvrđeno stanje.
  if (typeof requestAnimationFrame === 'function' && !_dozUpdGpsStats._drawing) {
    _dozUpdGpsStats._accuracy = acc;
    if (!_dozUpdGpsStats._frame) _dozUpdGpsStats._frame = requestAnimationFrame(() => {
      _dozUpdGpsStats._frame = 0;
      _dozUpdGpsStats._drawing = true;
      try { _dozUpdGpsStats(_dozUpdGpsStats._accuracy); }
      finally { _dozUpdGpsStats._drawing = false; }
    });
    return;
  }
  if (typeof _dozGpsControlsSync === 'function') _dozGpsControlsSync(acc);
  const el = document.getElementById('doz-gps-stats');
  if (!el) return;
  el.style.display = 'block';
  const totalMs = Date.now() - _dozGpsStartTs;
  const pauseMs = _dozGpsPausedTime + (_dozGpsPaused && _dozGpsPauseStart ? Date.now() - _dozGpsPauseStart : 0);
  const moveMs = Math.max(totalMs - pauseMs, 1);
  const totalMins = Math.floor(totalMs / 60000);
  const moveMins = Math.floor(moveMs / 60000);
  const avgSpd = moveMs > 0 ? (_dozGpsLen / (moveMs / 1000)) : 0;
  const avgKmh = (avgSpd * 3.6).toFixed(1);
  const maxKmh = (_dozGpsMaxSpd * 3.6).toFixed(1);
  const accStr = acc != null
    ? (acc > 20 ? `<span style="color:#fbbf24;">±${Math.round(acc)}m čekam signal</span>` : `±${Math.round(acc)}m`)
    : '<span style="color:#fbbf24;">čekam signal…</span>';
  const elevGain = _dozCalcElevGain();
  el.innerHTML =
    `Trag: <b>${fmtL(_dozGpsLen)}</b> · ${_dozGpsPts.length} tač. · ${accStr}<br>` +
    `⏱ ${moveMins} min pokret / ${totalMins} min ukupno` +
    (_dozGpsPaused ? ' · <b style="color:#fbbf24;">PAUZA</b>' : '') + `<br>` +
    `🏃 Prosj: <b>${avgKmh}</b> · Max: <b>${maxKmh}</b> km/h` +
    (elevGain.gain > 0 ? `<br>⛰ +${Math.round(elevGain.gain)}m / -${Math.round(elevGain.loss)}m` : '') +
    (_dozGpsBuffered > 0 ? `<br><span style="color:#fbbf24;">📴 ${_dozGpsBuffered} čeka sync</span>` : '');
  _dozDrawElevProfile();
}

function _dozCalcElevGain() {
  const data = _dozGpsElevData;
  let memo = _dozCalcElevGain._memo;
  if (!memo || memo.data !== data || memo.n > data.length) {
    memo = { data, n:0, gain:0, loss:0 };
    _dozCalcElevGain._memo = memo;
  }
  for (let i = Math.max(1, memo.n); i < data.length; i++) {
    const diff = _dozGpsElevData[i] - _dozGpsElevData[i - 1];
    if (diff > 1) memo.gain += diff;
    else if (diff < -1) memo.loss -= diff;
  }
  memo.n = data.length;
  return { gain:memo.gain, loss:memo.loss };
}

function _dozDrawElevProfile() {
  if (document.hidden) return;
  const canvas = document.getElementById('doz-elev-canvas');
  if (!canvas || _dozGpsElevData.length < 2 || !canvas.getClientRects().length) return;
  document.getElementById('doz-gps-elev').style.display = 'block';
  const ctx = canvas.getContext('2d');
  const w = canvas.width, h = canvas.height;
  ctx.clearRect(0, 0, w, h);
  const data = _dozGpsElevData;
  let mn = Infinity, mx = -Infinity;
  data.forEach(v => { if (v < mn) mn = v; if (v > mx) mx = v; });
  const range = Math.max(mx - mn, 10);
  const step = w / (data.length - 1);
  ctx.beginPath();
  ctx.moveTo(0, h);
  data.forEach((v, i) => {
    const x = i * step;
    const y = h - ((v - mn) / range) * (h - 10) - 5;
    ctx.lineTo(x, y);
  });
  ctx.lineTo(w, h);
  ctx.closePath();
  const grad = ctx.createLinearGradient(0, 0, 0, h);
  grad.addColorStop(0, 'rgba(74,222,128,0.4)');
  grad.addColorStop(1, 'rgba(74,222,128,0.05)');
  ctx.fillStyle = grad;
  ctx.fill();
  ctx.beginPath();
  data.forEach((v, i) => {
    const x = i * step;
    const y = h - ((v - mn) / range) * (h - 10) - 5;
    i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
  });
  ctx.strokeStyle = '#4ade80';
  ctx.lineWidth = 1.5;
  ctx.stroke();
  ctx.fillStyle = '#94a3b8';
  ctx.font = '9px sans-serif';
  ctx.fillText(`${Math.round(mx)}m`, 3, 12);
  ctx.fillText(`${Math.round(mn)}m`, 3, h - 3);
}

function _dozExportPoints() {
  if(_dozGpsExportContext?.projectId===_dozSelId&&_dozGpsExportContext?.userId===sbUser?.id&&_dozGpsFullPts.length)return _dozGpsFullPts.slice();
  return (_dozTragoviPoKorisniku()[sbUser?.id]||[]).map(p=>({lat:p.latitude,lon:p.longitude,ele:p.altitude,time:p.recorded_at,spd:p.speed}));
}
function dozExportGPX() {
  const pts=_dozExportPoints();
  if (!pts.length) { showToast('Nema tačaka za export'); return; }
  const odjel = _dozOdjeli.find(o => o.id === _dozSelId);
  const name = odjel?.name || 'Doznaka';
  let gpx = `<?xml version="1.0" encoding="UTF-8"?>\n<gpx version="1.1" creator="DENDRO MAP" xmlns="http://www.topografix.com/GPX/1/1">\n<trk><name>${_escXml(name)}</name><trkseg>\n`;
  pts.forEach((p,i) => {
    if(i>0&&Date.parse(p.time)-Date.parse(pts[i-1].time)>5*60*1000)gpx+='</trkseg><trkseg>\n';
    // Prazan <time></time> je neispravan GPX — tačka oporavljena iz snimka
    // nema poznato vrijeme, pa se element izostavlja umjesto da se piše prazan.
    gpx += `<trkpt lat="${p.lat}" lon="${p.lon}"><ele>${p.ele || 0}</ele>${p.time ? `<time>${p.time}</time>` : ''}</trkpt>\n`;
  });
  gpx += `</trkseg></trk>\n</gpx>`;
  const blob = new Blob([gpx], { type: 'application/gpx+xml' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = `${name.replace(/[^a-zA-Z0-9]/g, '_')}_${new Date().toISOString().slice(0, 10)}.gpx`;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  setTimeout(()=>URL.revokeObjectURL(url),4000);
  showToast('📥 GPX exportovan');
}

// ═══════════════════════════════════════════════════════════════════════════
// === DIJELJENJE POJASA PREKO QR KODA (potpuno offline, bez servera) ═════════
// ═══════════════════════════════════════════════════════════════════════════
// Zašto QR a ne Bluetooth: app je Android WebView (WebViewAssetLoader), a Web
// Bluetooth API tu praktično ne radi (nema nativne podrške bez custom native
// mosta), i namijenjen je za GATT periferije, ne za phone-to-phone prijenos
// proizvoljnih podataka. Kamera je već dostupna svuda, QR generisanje/čitanje
// je čisto klijentski (nula mreže potrebno na bilo kojoj strani) i radi
// pouzdano čak i kad NIJEDAN od dva telefona nema signal — najbrža i
// najpouzdanija opcija za ovaj kontekst.
const _DOZ_QR_KEY = 'tvlake_doz_qr_received';
let _qrLibsLoaded = false;

function _loadQrLibs() {
  if (_qrLibsLoaded && window.qrcode && window.jsQR) return Promise.resolve();
  return new Promise((resolve, reject) => {
    let remaining = 2, failed = false;
    function done(err) {
      if (err) failed = true;
      if (--remaining === 0) {
        if (failed || !window.qrcode || !window.jsQR) reject(new Error('QR biblioteke nisu učitane'));
        else { _qrLibsLoaded = true; resolve(); }
      }
    }
    const s1 = document.createElement('script'); s1.src = 'static/libs/qrcode-gen.js';
    s1.onload = () => done(null); s1.onerror = () => done(1); document.head.appendChild(s1);
    const s2 = document.createElement('script'); s2.src = 'static/libs/jsQR.js';
    s2.onload = () => done(null); s2.onerror = () => done(1); document.head.appendChild(s2);
  });
}

// ─── SLANJE (generiši QR) ────────────────────────────────────────────────
async function dozShareQR() {
  // Preferiraj tek završeni GPS pojas (lakši — samo lat/lng); ako ga nema,
  // ponudi moj posljednji sinhronizovani pojas za ovaj odjel (isti fallback
  // obrazac kao dozExportGPX).
  const raw = _dozExportPoints().map(p=>[p.lat,p.lon]);
  if (!raw.length) { showToast('Nema snimljenog pojasa za slanje'); return; }

  const odjel = _dozOdjeli.find(o => o.id === _dozSelId);
  const ime = sbProfile ? (sbProfile.ime + ' ' + sbProfile.prezime) : 'Projektant';
  const boja = sbProfile?.boja || '#38bdf8';

  // Adaptivna simplifikacija — cilj je da payload stane u JEDAN QR kod (pouzdano
  // skeniranje kamerom na terenu je bitnije od savršene preciznosti linije;
  // pojas je uglavnom prava linija pa i agresivna tolerancija ne kvari oblik).
  let tol = 3, payload, json;
  do {
    const simp = _rdpSimplify(raw.map(([la, lo]) => ({ la, lo })), tol);
    payload = {
      v: 1, t: 'pojas',
      odjel: odjel?.name || '', gj: odjel?.gj || '',
      ime, boja, ts: Date.now(),
      pts: simp.map(p => [Math.round(p.la * 1e6) / 1e6, Math.round(p.lo * 1e6) / 1e6])
    };
    json = JSON.stringify(payload);
    tol += 4;
  } while (json.length > 1800 && tol < 60 && payload.pts.length > 2);

  try {
    await _loadQrLibs();
  } catch (e) {
    showToast('⚠ QR biblioteke nisu dostupne (provjeri static/libs fajlove)');
    return;
  }
  _dozShowQrModal(json, payload, raw.length);
}

function _dozShowQrModal(json, payload, rawPtCount) {
  const box = document.getElementById('doz-qr-show-canvas');
  const info = document.getElementById('doz-qr-show-info');
  box.innerHTML = '';
  try {
    const qr = qrcode(0, 'M');
    qr.addData(json);
    qr.make();
    box.innerHTML = qr.createSvgTag(5, 8);
  } catch (e) {
    box.innerHTML = '<div style="color:#dc2626;font-size:12px;">⚠ Pojas je prevelik za QR — skrati snimanje ili pošalji u dva dijela.</div>';
    console.error('QR generate', e);
  }
  info.innerHTML = `${_escHtml(payload.odjel || 'Bez odjela')} · ${payload.pts.length} tačaka${rawPtCount > payload.pts.length ? ` (pojednostavljeno sa ${rawPtCount})` : ''} · ${_escHtml(payload.ime)}`;
  document.getElementById('doz-qr-show-modal').style.display = 'flex';
}
function closeDozQrShow() {
  document.getElementById('doz-qr-show-modal').style.display = 'none';
}

// ─── PRIJEM (skeniraj QR preko kamere) ───────────────────────────────────
let _dozQrStream = null;
let _dozQrScanning = false;
let _dozQrGeneration = 0, _dozQrFrame = null, _dozQrOwner = null, _dozQrProject = null;

async function dozScanQR() {
  closeDozQrScan();
  const generation=++_dozQrGeneration, owner=sbUser?.id, projectId=_dozSelId;
  const valid=()=>generation===_dozQrGeneration && sbUser?.id===owner && _dozSelId===projectId;
  try {
    await _loadQrLibs();
  } catch (e) {
    if(!valid())return;
    showToast('⚠ QR biblioteke nisu dostupne (provjeri static/libs fajlove)');
    return;
  }
  if(!valid())return;
  const video = document.getElementById('doz-qr-video');
  const statusEl = document.getElementById('doz-qr-scan-status');
  statusEl.textContent = 'Usmjeri kameru na QR kod...';
  document.getElementById('doz-qr-scan-modal').style.display = 'flex';
  try {
    const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
    if(!valid()){stream.getTracks().forEach(t=>t.stop());return;}
    _dozQrStream = stream;_dozQrOwner=owner;_dozQrProject=projectId;
  } catch (e) {
    if(!valid())return;
    closeDozQrScan();
    showToast('⚠ Nema pristupa kameri (provjeri dozvolu u postavkama)');
    return;
  }
  video.srcObject = _dozQrStream;
  await video.play().catch(() => {});
  if(!valid()){if(generation===_dozQrGeneration)closeDozQrScan();return;}
  _dozQrScanning = true;
  _dozQrScanTick();
}

function _dozQrScanTick() {
  if (!_dozQrScanning) return;
  if(sbUser?.id!==_dozQrOwner || _dozSelId!==_dozQrProject){closeDozQrScan();return;}
  const video = document.getElementById('doz-qr-video');
  if (video.readyState === video.HAVE_ENOUGH_DATA) {
    if (!_dozQrScanTick._canvas) {
      _dozQrScanTick._canvas = document.createElement('canvas');
      _dozQrScanTick._ctx = _dozQrScanTick._canvas.getContext('2d', { willReadFrequently: true });
    }
    const canvas = _dozQrScanTick._canvas, ctx = _dozQrScanTick._ctx;
    canvas.width = video.videoWidth; canvas.height = video.videoHeight;
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    try {
      const img = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const code = jsQR(img.data, img.width, img.height);
      if (code && code.data) { _dozQrHandleScanned(code.data); return; }
    } catch (e) {}
  }
  _dozQrFrame=requestAnimationFrame(_dozQrScanTick);
}

function closeDozQrScan() {
  ++_dozQrGeneration;
  _dozQrScanning = false;
  if(_dozQrFrame!==null)cancelAnimationFrame(_dozQrFrame);
  _dozQrFrame=null;_dozQrOwner=null;_dozQrProject=null;
  if (_dozQrStream) { _dozQrStream.getTracks().forEach(t => t.stop()); _dozQrStream = null; }
  const video=document.getElementById('doz-qr-video');
  if(video){video.pause();video.srcObject=null;}
  document.getElementById('doz-qr-scan-modal').style.display = 'none';
}

function _dozQrHandleScanned(text) {
  closeDozQrScan();
  let payload;
  try { payload = JSON.parse(text); } catch (e) { showToast('⚠ Ovo nije validan pojas-QR'); return; }
  if (!payload || payload.t !== 'pojas' || !Array.isArray(payload.pts) || payload.pts.length < 2) {
    showToast('⚠ Ovo nije validan pojas-QR'); return;
  }
  if(payload.pts.length>10000||payload.pts.some(p=>!Array.isArray(p)||p.length<2||!Number.isFinite(p[0])||!Number.isFinite(p[1])||Math.abs(p[0])>90||Math.abs(p[1])>180)){showToast('⚠ QR sadrži neispravne koordinate');return;}
  const entry = {
    id: 'qr_' + Date.now(),
    odjel: payload.odjel || '', gj: payload.gj || '',
    ime: payload.ime || 'Kolega', boja: payload.boja || '#38bdf8',
    ts: payload.ts || Date.now(), receivedAt: new Date().toISOString(),
    pts: payload.pts
  };
  const arr = _dozQrLoad();
  arr.unshift(entry);
  if(!_dozQrSave(arr)){showToast('⚠ Pojas nije sačuvan. Oslobodi memoriju pa ponovo skeniraj QR.');return;}
  _dozQrDraw(entry);
  _dozQrRenderReceived();
  const b = L.latLngBounds(entry.pts.map(p => [p[0], p[1]]));
  if (b.isValid()) { switchTab('karta'); map.fitBounds(b, { padding: [30, 30] }); }
  showToast(`✅ Primljen pojas: ${entry.ime}${entry.odjel ? ' (' + entry.odjel + ')' : ''}`);
}

// ─── Prikaz/upravljanje primljenim pojasevima (localStorage, per-uređaj) ──
let _dozQrLayers = {};
function _dozQrLoad() { try {const value=JSON.parse(localStorage.getItem(_DOZ_QR_KEY)||'[]');return Array.isArray(value)?value:[];} catch { return []; } }
// v1.6.0: neuspjeh se više ne guta. QR dijeljenje je NAMJERNO potpuno offline i
// peer-to-peer (ni pošiljalac ni primalac ne trebaju internet) — što znači da
// primljeni pojas NE POSTOJI nigdje drugdje: ako ovaj upis tiho padne, jedini
// način da se vrati je da kolega ponovo pokaže QR kod, a on je do tada obično
// već otišao. Nenadoknadivo isto kao snimljen trag (v1.4.7).
function _dozQrSave(arr) {
  return _localSetKriticno(_DOZ_QR_KEY, JSON.stringify(arr), 'Primljeni pojas (QR)');
}

function _dozQrDraw(entry) {
  if (_dozQrLayers[entry.id]) { try { map.removeLayer(_dozQrLayers[entry.id]); } catch(e) {} }
  const latlngs = entry.pts.map(p => [p[0], p[1]]);
  const pl = L.polyline(latlngs, { color: entry.boja, weight: 4, opacity: 0.85, dashArray: '3,7', pane: 'tragMsrLines' });
  pl.bindTooltip(_escHtml(`📥 ${entry.ime}${entry.odjel ? ' — ' + entry.odjel : ''}`), { sticky: true, opacity: 0.9 });
  pl.addTo(map);
  _dozQrLayers[entry.id] = pl;
}
function _dozQrRestore() {
  try { _dozQrLoad().forEach(e => _dozQrDraw(e)); _dozQrRenderReceived(); } catch(e) {}
}
function _dozQrRemove(id) {
  if(!_dozQrSave(_dozQrLoad().filter(e=>e.id!==id)))return;
  if (_dozQrLayers[id]) { try { map.removeLayer(_dozQrLayers[id]); } catch(e) {} delete _dozQrLayers[id]; }
  _dozQrRenderReceived();
}
function _dozQrZoom(id) {
  const e = _dozQrLoad().find(x => x.id === id);
  if (!e) return;
  const b = L.latLngBounds(e.pts.map(p => [p[0], p[1]]));
  if (b.isValid()) { switchTab('karta'); map.fitBounds(b, { padding: [30, 30] }); }
}
function _dozQrRenderReceived() {
  const el = document.getElementById('doz-qr-received-list');
  if (!el) return;
  const arr = _dozQrLoad();
  if (!arr.length) { el.innerHTML = ''; return; }
  el.innerHTML = arr.map(e => `<div style="display:flex;align-items:center;gap:8px;background:#0f172a;border:1px solid #1e3a5f;border-radius:10px;padding:7px 9px;margin-top:6px;border-left:3px solid ${e.boja};">
    <div style="flex:1;min-width:0;cursor:pointer;" onclick="_dozQrZoom('${e.id}')">
      <div style="font-size:12px;font-weight:600;color:#e2e8f0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">📥 ${_escHtml(e.ime)}${e.odjel ? ' · ' + _escHtml(e.odjel) : ''}</div>
      <div style="font-size:10px;color:#64748b;">${fmtDateShort(e.receivedAt)} · ${e.pts.length} tač.</div>
    </div>
    <button onclick="_dozQrRemove('${e.id}')" style="background:none;border:none;color:#f87171;font-size:15px;cursor:pointer;padding:2px 6px;"><svg class="ic"><use href="#ic-zatvori"/></svg></button>
  </div>`).join('');
}

let _dozGpsPoly = null;        // perzistentna polilinija (inkrementalno crtanje)
let _dozGpsProjId = null;      // uhvaćen na startu — ne mijenja se tokom snimanja
let _dozGpsUserId = null;
let _dozGpsSessionId = null;
let _dozGpsStopping = false;
const _DOZ_GPS_MIN_DIST = 3;   // metara — minimalni razmak između tačaka (filtrira GPS šum)

function dozStartGPS() {
  if (_dozGpsOn) return;        // već snima — spriječi dupli watch (memory leak)
  if (!_dozSelId || !sbUser) { showToast('Odaberi odjel i prijavi se'); return; }
  if (!navigator.geolocation) { showToast('GPS nije dostupan'); return; }
  _gpsStabilizeGate(_dozStartGPSBegin);   // ne kreni dok signal ne prestane lutati
}

async function _dozStartGPSBegin() {
  const startingUid=sbUser?.id,startingProject=_dozSelId;
  if (typeof FieldStore !== 'undefined') {
    try {
      await FieldStore.init();
      const unfinished=await FieldStore.live(sbUser?.id);
      if (unfinished || localStorage.getItem(_DOZ_LIVE_KEY)) {
        if (recOn || _tragOn) { showToast('⚠ Prvo završi aktivno snimanje pa oporavi prethodni pojas'); return; }
        await _crashCheck();
        if (_dozGpsOn || await FieldStore.live(sbUser?.id)) return;
      }
    } catch(e) { showToast('⚠ GPS dnevnik nije provjeren — prethodni podaci ostaju sačuvani'); return; }
  }
  if (_dozGpsOn || !startingUid || sbUser?.id!==startingUid || _dozSelId!==startingProject) return;
  if (_dozGpsWatchId !== null) { navigator.geolocation.clearWatch(_dozGpsWatchId); _dozGpsWatchId = null; }
  _dozGpsOn = true;
  _dozGpsPts = [];
  _dozGpsSent = 0; _dozGpsBuffered = 0; _dozGpsLen = 0; _dozGpsStartTs = Date.now();
  _dozGpsProjId = _dozSelId; _dozGpsUserId = sbUser.id;
  _dozGpsExportContext={projectId:_dozGpsProjId,userId:_dozGpsUserId};
  _dozGpsSessionId = _genUUID(); _dozGpsStopping = false;
  _dozGpsPaused = false; _dozGpsPausedTime = 0; _dozGpsPauseStart = 0;
  _pauziResetuj(_dozPauseWin);   // zaostala pauza prethodne sesije ne smije suditi novim tačkama
  // Sesija postoji od prvog trenutka, ne tek od prve tačke koju WebView primi —
  // inače ubijen proces prije prvog fiksa nema šta oporaviti iz native bafera.
  // Čeka se (await): sjeme poslije prve tačke bi vratilo vrijeme sesije unazad.
  try {
    if (typeof FieldStore !== 'undefined') await FieldStore.seedSession({ id: _dozGpsSessionId, uid: _dozGpsUserId,
      projId: _dozGpsProjId, len: 0, ts: Date.now() }, []);
    else localStorage.setItem(_DOZ_LIVE_KEY, JSON.stringify({ projId: _dozGpsProjId, pts: [], len: 0, ts: Date.now() }));
  } catch(e) { console.warn('Doznaka početni snimak', e); }
  _dozGpsMaxSpd = 0; _dozGpsSpdSum = 0; _dozGpsSpdCnt = 0;
  _dozGpsElevData = []; _dozGpsFullPts = [];
  _dozLastLiveFixTs = 0;
  // Zastavica "već sam javio da lokalni upis pada" vrijedi PO SNIMANJU. Bez
  // reseta bi drugo snimanje poslije pune kvote prošlo bez ijednog upozorenja
  // da mu crash-zaštita uopšte ne radi.
  _dozLiveUpisPao = false;
  if (_dozGpsTrackLayer) map.removeLayer(_dozGpsTrackLayer);
  _dozGpsTrackLayer = L.layerGroup().addTo(map);
  _dozGpsPoly = null;
  const btn = document.getElementById('doz-gps-btn');
  if (btn) { btn.textContent = '📍 Kontrole snimanja'; btn.style.background='#052e16'; btn.style.color='#4ade80'; btn.style.borderColor='#166534'; }
  const pauseBtn = document.getElementById('doz-gps-pause');
  if (pauseBtn) { pauseBtn.style.display = ''; pauseBtn.textContent = '⏸'; pauseBtn.style.background='#422006'; pauseBtn.style.borderColor='#92400e'; pauseBtn.style.color='#fbbf24'; }
  const gpsStatus=document.getElementById('doz-gps-status');
  if(gpsStatus) { gpsStatus.style.display='block'; gpsStatus.textContent='● Snimanje aktivno'; gpsStatus.style.color='#4ade80'; }
  document.getElementById('doz-gps-export').style.display = 'none';
  document.getElementById('doz-gps-elev').style.display = 'none';
  _dozUpdGpsStats(null);
  _bgRecStart('pojas doznake');  // wake lock + foreground service — snima i u pozadini
  // Doznaka koristi VLASTITI watch (druga tabela/filtriranje). Glavni GPS je bio uključen
  // samo privremeno radi stabilizacije — ako prije nije bio aktivan, ugasi ga da ne teku
  // dva paralelna watch-a. (Ako je korisnik i inače imao GPS marker uključen, ostaje.)
  if (!_gpsStabWasOn) stopGPS();

  _dozGpsWatchId = navigator.geolocation.watchPosition(async function dozLive(pos) {
    if (_drainNativeGpsBuffer._busy) { _drainLiveQ.push({ fn: dozLive, arg: pos }); return; }
    // Native dopuna smije preskočiti fix tek poslije uspješnog trajnog upisa.
    const fixTs = pos.timestamp || Date.now();
    if (_dozGpsStopping) return;
    if (!_dozGpsOn || !_dozGpsProjId || !_dozGpsUserId) return;
    const { latitude:lat, longitude:lng, altitude:alt, accuracy:acc, speed } = pos.coords;
    // Vidi napomenu uz isti obrazac u grani oporavka (_crashCheck): baceni
    // izuzetak iz _dozProcessGpsPoint je signal za native replay, ne razlog da
    // uživo watch callback ostane sa neuhvaćenim odbijanjem obećanja.
    try { await _dozProcessGpsPoint(lat, lng, alt, acc, speed, fixTs); _dozLastLiveFixTs = fixTs; }
    catch(e) { console.warn('Doznaka GPS tačka', e); _dozUpdGpsStats(acc); }
  }, err => { console.warn('Doznaka GPS', err); _dozUpdGpsStats(null); },
  { enableHighAccuracy:true, maximumAge:3000, timeout:15000 });
  dozOpenGPSControls();
  if (typeof _recBarSync === 'function') _recBarSync();
}

// Obrada jedne GPS tačke za pojas doznake — dijeljeno između uživo
// watchPosition callbacka (bez tsMs, koristi trenutno vrijeme kao ranije) i
// _drainNativeGpsBuffer replay-a (sa tsMs = stvarno historijsko vrijeme
// fiksa, da recorded_at u bazi ostane tačan umjesto "sad" za tačku snimljenu
// prije nekoliko minuta dok je app bio zatvoren).
async function _dozProcessGpsPoint(lat, lng, alt, acc, speed, tsMs, bypassPauzu) {
  const capturedUser=_dozGpsUserId,capturedProject=_dozGpsProjId;
  const capturedSession=typeof _dozGpsSessionId==='undefined'?null:_dozGpsSessionId;
  // Watch i native replay mogu se preklopiti dok IDB radi. Obradi ih redom.
  const previous = _dozProcessGpsPoint._tail || Promise.resolve();
  let release;
  _dozProcessGpsPoint._tail = new Promise(resolve => { release=resolve; });
  await previous;
  try {
  if (_dozProcessGpsPoint._retry) {
    await _dozProcessGpsPoint._retry();
    _dozProcessGpsPoint._retry = null;
  }
  const commit = async () => {
  if (_dozGpsUserId!==capturedUser || _dozGpsProjId!==capturedProject) return;
  if (typeof _dozGpsSessionId!=='undefined' && _dozGpsSessionId!==capturedSession) return;
  if (!_dozGpsOn || !_dozGpsProjId || !_dozGpsUserId) return;
  if(!Number.isFinite(lat)||!Number.isFinite(lng)||Math.abs(lat)>90||Math.abs(lng)>180||!Number.isFinite(acc)||acc<0)return;
  if(tsMs!=null&&(!Number.isFinite(tsMs)||tsMs<=0))return;
  if (acc > 20) { _dozUpdGpsStats(acc); return; }
  if (_dozGpsPaused && !bypassPauzu) { _dozUpdGpsStats(acc); return; }
  const prev = _dozGpsPts[_dozGpsPts.length - 1];
  let d = 0;
  if (prev) {
    d = dst(prev[0], prev[1], lat, lng);
    if (d < _DOZ_GPS_MIN_DIST) { _dozUpdGpsStats(acc); return; }
  }
  const spdMs = (speed != null && speed >= 0) ? speed : 0;
  const isoTs = new Date(tsMs || Date.now()).toISOString();
  const _dozPt = {
    project_id:_dozGpsProjId, user_id:_dozGpsUserId,
    latitude:lat, longitude:lng, altitude:alt || null, accuracy:acc,
    speed:speed || null, recorded_at:isoTs
  };
  if (!await _dozBufferTrackPoint(_dozPt,{count:_dozGpsPts.length+1,len:_dozGpsLen+d})) {
    _dozProcessGpsPoint._retry = commit;
    throw new Error('GPS tačka nije trajno sačuvana');
  }
  if (_dozGpsUserId!==_dozPt.user_id || _dozGpsProjId!==_dozPt.project_id ||
    (typeof sbUser!=='undefined' && sbUser?.id!==_dozPt.user_id)) return;
  _dozGpsLen += d;
  if (spdMs > _dozGpsMaxSpd) _dozGpsMaxSpd = spdMs;
  _dozGpsSpdSum += spdMs; _dozGpsSpdCnt++;
  if (alt != null) _dozGpsElevData.push(alt);
  _dozGpsFullPts.push({ lat, lon: lng, ele: alt || 0, time: isoTs, spd: spdMs });
  if (prev) {
    const kmh = spdMs * 3.6;
    const col = kmh < 1 ? '#60a5fa' : kmh < 3 ? '#4ade80' : kmh < 6 ? '#fbbf24' : '#ef4444';
    _dozGpsDodajSegment(_dozGpsTrackLayer, prev, [lat, lng], col);
  }
  _dozGpsPts.push([lat, lng]);
  _dozSaveLivePts();
  _dozGpsBuffered++;
  // Tačka je već trajno u baferu. Slanje pokreće samo Meni → Server.
  _dozUpdGpsStats(acc);
  _dozCheckBandCross(lat, lng);
  if (_dozGpsProjId === _dozSelId) _dozLiveRacunMozda();
  };
  await commit();
  } finally { release(); }
}

// Ista boja ide u jednu liniju, ali najviše 128 segmenata po liniji: Leaflet
// pri addLatLng ponovo projektuje sve tačke te linije. Time i dug snimak ima
// ograničen posao po fiksu, bez SVG elementa za svaka dva susjedna fiksa.
function _dozGpsDodajSegment(group, prev, pt, color) {
  if (!group) return;
  if (!group._gpsRenderer) {
    group._gpsRenderer = L.canvas({ padding:0.3 });
    if (typeof group.on === 'function') group.on('remove', () => {
      if (group._gpsRenderer._map) group._gpsRenderer._map.removeLayer(group._gpsRenderer);
    });
  }
  let seg = group._gpsSegment;
  if (!seg || seg.color !== color || seg.n >= 128) {
    seg = { color, n:1, pts:[prev,pt], line:L.polyline([prev, pt], {
      color, weight:3, opacity:0.9, interactive:false, renderer:group._gpsRenderer
    }).addTo(group) };
    group._gpsSegment = seg;
    if (group._gpsRenderer._container) group._gpsRenderer._container.style.pointerEvents = 'none';
  } else {
    seg.pts.push(pt); seg.n++;
    // Native replay može donijeti stotine fikseva u jednom prolazu. Geometrija
    // se osvježi jednom po frame-u umjesto projekcije cijelog segmenta po fiksu.
    if (typeof requestAnimationFrame === 'function') {
      if (!seg.frame) seg.frame = requestAnimationFrame(() => { seg.frame=0; seg.line.setLatLngs(seg.pts); });
    } else seg.line.addLatLng(pt);
  }
}

// ─── Upozorenje kad projektant uđe u tuđi pojas ─────────────────
let _dozCrossWarnTs = 0;
let _dozCrossMarker = null;
let _dozCrossCount = 0;

function _dozCheckBandCross(lat, lng) {
  if (!_dozGpsOn || !_dozGpsUserId || !_dozCrossWarnEnabled) return;
  const now = Date.now();
  if (now - _dozCrossWarnTs < 15000) return;
  // Provjera najviše svakih 5 s — gradnja tragova je O(n²) (nearestPointOnLine
  // po tački), a ova funkcija se zove na SVAKU GPS tačku.
  if (now - (_dozCheckBandCross._t || 0) < 5000) return;
  _dozCheckBandCross._t = now;

  const userTracks = _dozBuildUserTracks();
  const otherTracks = userTracks.filter(t => t.uid !== _dozGpsUserId);
  if (!otherTracks.length) return;

  const myTracks = userTracks.filter(t => t.uid === _dozGpsUserId);
  const pt = turf.point([lng, lat]);

  let myDist = Infinity;
  myTracks.forEach(t => {
    const n = turf.nearestPointOnLine(t.line, pt);
    if (n.properties.dist < myDist) myDist = n.properties.dist;
  });

  let closestOther = null;
  let otherDist = Infinity;
  otherTracks.forEach(t => {
    const n = turf.nearestPointOnLine(t.line, pt);
    if (n.properties.dist < otherDist) {
      otherDist = n.properties.dist;
      closestOther = t;
    }
  });

  if (otherDist < myDist && otherDist < 0.025) {
    _dozCrossCount++;
    if (_dozCrossCount >= 3) {
      _dozCrossWarnTs = now;
      const mIdx = {};
      _dozMembers.forEach((m, i) => { mIdx[m.user_id] = i; });
      const name = _escHtml(_dozImeClana(closestOther.uid));
      const col = DOZ_ENG_COLORS[(mIdx[closestOther.uid] ?? 0) % DOZ_ENG_COLORS.length];
      showToast(`⚠ Prelazite u pojas: ${name}`);
      if (_dozCrossMarker) map.removeLayer(_dozCrossMarker);
      _dozCrossMarker = L.circleMarker([lat, lng], {
        radius: 10, color: '#ef4444', fillColor: '#ef4444', fillOpacity: 0.4, weight: 2
      }).addTo(_dozGpsTrackLayer || map);
      _dozCrossMarker.bindTooltip(`⚠ Prelaz u pojas: ${name}`, { permanent: false, opacity: 0.9 });
      setTimeout(() => { if (_dozCrossMarker) { try { map.removeLayer(_dozCrossMarker); } catch(e) {} _dozCrossMarker = null; } }, 30000);
      _dozCrossCount = 0;
    }
  } else {
    _dozCrossCount = 0;
  }
}

// RPC zaključava jednu logičku GPS tačku na serveru. Kompatibilni fallback
// koristi postojeće kolone (id u staroj šemi može biti bigserial, ne UUID).
// Slanje doznaka GPS tačaka u SERIJAMA (v1.9.2). Ranije je svaka tačka bila
// svoj zahtjev (uz RPC, a bez njega DVA — provjera + upis), a poslije svake se
// CIJELI bafer parsirao i prepisivao. Dan doznake bez signala (hiljade tačaka)
// je tako na slaboj vezi značio sat vremena zahtjeva, a sve novo u redu (vlaka
// sačuvana u međuvremenu) čekalo je iza toga. Sad: jedna provjera postojećih u
// vremenskom prozoru serije + jedan upis onih kojih nema. Idempotentno isto kao
// RPC (tačka = vlasnik + odjel + vrijeme + koordinate), a ne traži migraciju.
const _DOZ_KOMAD = 100;
function _dozTackaKljuc(t, la, lo) { return Date.parse(t) + '|' + Number(la) + '|' + Number(lo); }
async function _dozPosaljiKomad(komad) {
  const ms = komad.map(p => Date.parse(p.recorded_at)).filter(Number.isFinite);
  if (!ms.length) return { ok: [], error: { code: '22023', message: 'Neispravno vrijeme GPS tačke' } };
  const ima = await sb.from('doz_track_points').select('recorded_at,latitude,longitude')
    .eq('user_id', komad[0].user_id).eq('project_id', komad[0].project_id)
    .gte('recorded_at', new Date(Math.min(...ms)).toISOString())
    .lte('recorded_at', new Date(Math.max(...ms)).toISOString())
    .limit(5000);
  if (ima.error) return { ok: [], error: ima.error };
  // PostgREST vraća najviše 1000 redova (max-rows). Širok prozor (npr. stara
  // zaglavljena tačka od prije par dana u istoj seriji) bi dao nepotpunu
  // provjeru → duplikate. Takva serija ide pojedinačno (vidi pozivaoca).
  if ((ima.data || []).length >= 1000) return { ok: [], error: { code: 'KOMAD_SIROK', message: 'preširok prozor serije' } };
  const postoji = new Set((ima.data || []).map(r => _dozTackaKljuc(r.recorded_at, r.latitude, r.longitude)));
  const unique=new Map();
  for(const {_qid,...p} of komad){const key=_dozTackaKljuc(p.recorded_at,p.latitude,p.longitude);if(!postoji.has(key))unique.set(key,p);}
  const nove=[...unique.values()];
  if (nove.length) {
    const { data, error } = await sb.from('doz_track_points').insert(nove).select('recorded_at,latitude,longitude');
    if (error) return { ok: [], error };
    for(const p of data||[])postoji.add(_dozTackaKljuc(p.recorded_at,p.latitude,p.longitude));
  }
  const ok=komad.filter(p=>postoji.has(_dozTackaKljuc(p.recorded_at,p.latitude,p.longitude))).map(p=>p._qid);
  return { ok, error: ok.length===komad.length ? null : {code:'NO_CONFIRMATION',message:'Server nije potvrdio sve GPS tačke; nepotvrđene tačke ostaju na telefonu'} };
}
async function _dozPosaljiPojedinacno(komad) {
  const ok = [];let firstError=null;
  for (const pt of komad) {
    const { _qid, ...payload } = pt;
    const { error } = await _sendDozTrackPoint(payload);
    if (error) {
      if (_isNetworkErr(error) || _isAuthErr(error) || _serverPrivremeno(error)) return { ok, error };
      firstError=firstError||error;
      continue;   // FK/RLS greška ostaje sačuvana, bez gubitka GPS tačke
    }
    ok.push(_qid);
  }
  return { ok, error: firstError };
}

async function _sendDozTrackPoint(payload) {
  const result = await sb.rpc('codex_save_gps_point', { p:payload });
  if (result.error && result.error.code !== 'PGRST202') return result;
  const lookup = await sb.from('doz_track_points').select('recorded_at,latitude,longitude')
    .eq('user_id', payload.user_id).eq('project_id', payload.project_id)
    .eq('recorded_at', payload.recorded_at).eq('latitude', payload.latitude)
    .eq('longitude', payload.longitude).limit(1);
  if (lookup.error) return lookup;
  const key=_dozTackaKljuc(payload.recorded_at,payload.latitude,payload.longitude);
  const confirmed=data=>(data||[]).some(p=>_dozTackaKljuc(p.recorded_at,p.latitude,p.longitude)===key);
  if (confirmed(lookup.data)) return { error:null };
  if(result.error?.code==='PGRST202'){
    const inserted=await sb.from('doz_track_points').insert(payload).select('recorded_at,latitude,longitude');
    if(inserted.error)return inserted;
    if(confirmed(inserted.data))return {error:null};
  }
  return {error:{code:'NO_CONFIRMATION',message:'Server nije potvrdio GPS tačku; ostaje za ponovni pokušaj'}};
}

// Spremi GPS tačku u offline buffer (poziva se i pri mrežnoj i pri DB/RLS grešci).
// Sinhrono (bez await) → atomarno u single-thread JS, ne može se ispreplitati.
async function _dozBufferTrackPoint(pt,stats) {
  try {
    if (!pt._qid) pt._qid = _genUUID();
    if (typeof FieldStore !== 'undefined') {
      await FieldStore.append(pt,{id:_dozGpsSessionId,uid:pt.user_id,projId:pt.project_id,...stats});
      _dozLiveUpisPao = false;
      return true;
    }
    const buf = JSON.parse(localStorage.getItem(_DOZ_TRACK_BUF_KEY) || '[]');
    if (!pt._qid) pt._qid = _genUUID();
    buf.push(pt);
    localStorage.setItem(_DOZ_TRACK_BUF_KEY, JSON.stringify(buf));
    return true;
  } catch(e) { _dozLiveUpisPao = true; showToast('⚠ GPS tačka nije sačuvana — provjeri memoriju'); return false; }
}

// Spasi live trag lokalno — ako Android ubije WebView u backgroundu, ne gubimo liniju
const _DOZ_LIVE_KEY = 'tvlake_doz_live';
// Javi se JEDNOM po snimanju, ne na svaku GPS tačku — ova funkcija se zove na
// svaki fiks, pa bi toast po tački bio neupotrebljiv usred rada.
let _dozLiveUpisPao = false;
function _dozSaveLivePts() {
  if (!(_dozGpsOn && _dozGpsPts.length)) return true;
  // Session i puna tačka su već u istoj IDB transakciji. Bez ponovne kopije.
  if (typeof FieldStore !== 'undefined') return !_dozLiveUpisPao;
  const tekst = JSON.stringify({ projId:_dozGpsProjId, pts:_dozGpsPts, len:_dozGpsLen, ts:Date.now() });
  try {
    localStorage.setItem(_DOZ_LIVE_KEY, tekst);
    _dozLiveUpisPao = false;   // oporavilo se — sljedeći kvar se smije opet javiti
    return true;
  } catch(e) {
    // Ovo je CRASH-ZAŠTITA snimanja doznake (vidi komentar iznad ključa). Tiho
    // progutan neuspjeh znači da pri sljedećem ubistvu WebView-a — koje OEM
    // battery manager radi redovno — nestane cijeli snimljeni pojas, a da
    // korisnik nikad nije saznao da zaštite nema.
    if (_dozLiveUpisPao) return false;
    _dozLiveUpisPao = true;
    _localSetKriticno(_DOZ_LIVE_KEY, tekst, 'Zaštita snimanja doznake');
    return false;
  }
}

async function dozStopGPS() {
  if (!_dozGpsOn) return;
  if (typeof FieldStore !== 'undefined') {
    if (_dozGpsStopping) return;
    _dozGpsStopping = true;
    try {
      await (_dozProcessGpsPoint._tail || Promise.resolve());
      if (_dozProcessGpsPoint._retry) { await _dozProcessGpsPoint._retry(); _dozProcessGpsPoint._retry=null; }
      await FieldStore.finish(_dozGpsSessionId,_dozGpsUserId);
    } catch(e) { _dozGpsStopping=false; showToast('⚠ Završetak nije sačuvan — ponovi ili izvezi snimak'); return; }
  }
  if (_dozGpsWatchId !== null) { navigator.geolocation.clearWatch(_dozGpsWatchId); _dozGpsWatchId = null; }
  const wasOn = _dozGpsOn;
  _dozGpsOn = false;
  _dozGpsProjId = null; _dozGpsUserId = null;
  _dozGpsPaused = false; _dozGpsPausedTime = 0; _dozGpsPauseStart = 0;
  _pauziZavrsi(_dozPauseWin);    // stop usred pauze bi inače ostavio vječno otvoren interval
  if (typeof dozCloseGPSControls === 'function') dozCloseGPSControls();
  _bgRecStopIfIdle();  // otpusti pozadinski servis/lock ako ništa drugo ne snima
  try { localStorage.removeItem(_DOZ_LIVE_KEY); } catch {}
  const btn = document.getElementById('doz-gps-btn');
  if (btn) { btn.innerHTML = '<svg class="ic"><use href="#ic-pozicija"/></svg> Počni GPS'; btn.style.background=''; btn.style.color=''; btn.style.borderColor=''; }
  const pauseBtn = document.getElementById('doz-gps-pause');
  if (pauseBtn) pauseBtn.style.display = 'none';
  document.getElementById('doz-gps-status').style.display = 'none';
  if (wasOn && _dozGpsFullPts.length >= 2) {
    document.getElementById('doz-gps-export').style.display = 'block';
  }
  if (wasOn && _dozGpsPts.length >= 2) {
    showToast(`📍 Snimljeno ${fmtL(_dozGpsLen)} (${_dozGpsPts.length} tačaka)`);
    if (_dozGpsTrackLayer) { try { map.removeLayer(_dozGpsTrackLayer); } catch(e) {} _dozGpsTrackLayer = null; }
    if (_dozSelId) dozLoadLayers(_dozSelId).then(() => dozRenderDetail());
  }
}

// ─── Draw Polygon ─────────────────────────────────────────────────
function dozShowTypePicker() {
  document.getElementById('doz-type-picker').style.display = 'flex';
}
function dozHideTypePicker() {
  document.getElementById('doz-type-picker').style.display = 'none';
}

function dozStartDraw(type) {
  dozHideTypePicker();
  // switchTab MORA doći PRIJE postavljanja stanja crtanja: izlazak s doznaka taba
  // poziva dozCancelDraw() (čišćenje napuštenog crtanja) koji bi inače odmah obrisao
  // upravo postavljeni _dozDrawType/_dozDrawPts — crtanje mrtvo od 1d00a42 (13.06.).
  switchTab('karta');
  _dozDrawType = type;
  _dozDrawPts  = [];
  _dozDrawEnabled = false;
  _dozDragLastPt = null;
  const t = DOZ_TYPES[type];
  setTimeout(() => {
    document.getElementById('doz-draw-banner').style.display = 'flex';
    window.DoznakaBoundary?.invalidate();
    document.getElementById('doz-draw-type-label').textContent = `${t.emoji} ${t.label}`;
    document.getElementById('doz-draw-count').textContent = '0 tačaka';
    document.getElementById('map').style.cursor = '';
    const dtb = document.getElementById('doz-draw-toggle');
    if (dtb) { dtb.classList.remove('on'); const _ci = document.getElementById('doz-draw-check'); if (_ci) _ci.textContent = '☐'; }
    if (_dozDrawLayer) { map.removeLayer(_dozDrawLayer); _dozDrawLayer = null; }
    document.getElementById('action-bar').style.display = 'none';
    document.getElementById('tab-bar').style.display = 'none';
    document.getElementById('map-center-dot').style.display = '';
    map.invalidateSize();
    showToast(`${t.emoji} Čekiraj "Crtaj" pa pomjeraj mapu — ili dodaj tačke ručno`);
  }, 50);
}

function dozAddDrawPoint(latlng) {
  _dozDrawPts.push({ lat: latlng.lat, lng: latlng.lng });
  _dozRedrawPreview();
  document.getElementById('doz-draw-count').textContent = `${_dozDrawPts.length} tačaka`;
}

function _dozRedrawPreview() {
  window.DoznakaBoundary?.invalidate();
  if (_dozDrawLayer) map.removeLayer(_dozDrawLayer);
  _dozDrawLayer = L.layerGroup().addTo(map);
  const isBoundary = _dozDrawType === '__boundary__';
  const t = isBoundary ? { color: '#38bdf8' } : (DOZ_TYPES[_dozDrawType] || DOZ_TYPES.custom);
  _dozDrawPts.forEach(pt => {
    L.circleMarker([pt.lat, pt.lng], { radius:5, color:t.color, fillColor:t.color, fillOpacity:0.9, weight:2 }).addTo(_dozDrawLayer);
  });
  if (_dozDrawPts.length >= 2) {
    const ring = _dozDrawPts.map(p => [p.lat, p.lng]).concat([[_dozDrawPts[0].lat, _dozDrawPts[0].lng]]);
    L.polyline(ring, { color:t.color, weight: isBoundary ? 2.5 : 2, dashArray: isBoundary ? '8,5' : '5,4' }).addTo(_dozDrawLayer);
  }
  if (_dozDrawPts.length >= 3) {
    L.polygon(_dozDrawPts.map(p => [p.lat, p.lng]), { color:t.color, fillColor:t.color, fillOpacity:0.12, weight:1 }).addTo(_dozDrawLayer);
  }
}

function dozUndoDrawPt() {
  if (!_dozDrawPts.length) return;
  if (_dozDrawEnabled) dozToggleDrawMode();
  _dozDrawPts.pop();
  _dozRedrawPreview();
  document.getElementById('doz-draw-count').textContent = `${_dozDrawPts.length} tačaka`;
  if (_dozDrawPts.length > 0) {
    const last = _dozDrawPts[_dozDrawPts.length - 1];
    map.panTo([last.lat, last.lng], { animate: true, duration: 0.3 });
    _dozDragLastPt = { lat: last.lat, lng: last.lng };
  } else {
    _dozDragLastPt = null;
  }
}

function dozCancelDraw() {
  const wasBoundary = _dozDrawType === '__boundary__';
  _dozDrawType = null; _dozDrawPts = [];
  window.GithubLayers?.sync();
  _dozDrawCleanup();
  if (_dozDrawLayer) { map.removeLayer(_dozDrawLayer); _dozDrawLayer = null; }
  document.getElementById('doz-draw-banner').style.display = 'none';
  document.getElementById('map').style.cursor = '';
  document.getElementById('tab-bar').style.display = 'flex';
  document.getElementById('action-bar').style.display = '';
  if (wasBoundary) {
    _dozCreateBoundary = _dozNewBoundaryPrevious?.boundary || null;
    _dozCreateAreaHa = _dozNewBoundaryPrevious?.area ?? null;
    _dozNewBoundaryPrevious = null;
    dozShowCreateOdjel(true);
  }
}

function dozFinishDraw() {
  if (_dozDrawPts.length < 3) { showToast('Trebaju najmanje 3 tačke'); return; }
  const coords = _dozDrawPts.map(p => [p.lng, p.lat]);
  coords.push(coords[0]);


  if (_dozDrawType === '__boundary__') {
    _dozNewBoundaryPrevious = null;
    _dozCreateBoundary = { type:'Polygon', coordinates:[coords] };
    _dozCreateAreaHa   = _dozCalcArea(_dozDrawPts) / 10000;
    _dozDrawType = null; _dozDrawPts = [];
    window.GithubLayers?.sync();
    _dozDrawCleanup();
    if (_dozDrawLayer) { map.removeLayer(_dozDrawLayer); _dozDrawLayer = null; }
    document.getElementById('doz-draw-banner').style.display = 'none';
    document.getElementById('map').style.cursor = '';
    document.getElementById('tab-bar').style.display = 'flex';
    document.getElementById('action-bar').style.display = '';
    dozShowCreateOdjel(true);
    return;
  }

  _dozPendingSavePolygon = { type:'Polygon', coordinates:[coords] };
  const areaHa = _dozCalcArea(_dozDrawPts) / 10000;
  const t = DOZ_TYPES[_dozDrawType];
  document.getElementById('doz-save-title').textContent = `${t.emoji} Sačuvaj — ${t.label}`;
  document.getElementById('doz-save-label').value = '';
  document.getElementById('doz-save-note').value  = '';
  document.getElementById('doz-save-area').textContent = `Površina: ~${fmtHa(areaHa)}`;
  document.getElementById('doz-save-modal').style.display = 'flex';
}

function dozCancelSave() {
  document.getElementById('doz-save-modal').style.display = 'none';
  _dozPendingSavePolygon = null;
  dozCancelDraw();
}

let _dozSaveInFlight = false;
async function dozConfirmSave() {
  if (!_dozPendingSavePolygon || _dozSaveInFlight) return;  // D4-F: spriječi dupli tap = dupla markica
  _dozSaveInFlight = true;
  try {
  const label  = document.getElementById('doz-save-label').value.trim() || null;
  const note   = document.getElementById('doz-save-note').value.trim()  || null;
  // Računaj iz spremljene geometrije (_dozPendingSavePolygon), ne iz mutable _dozDrawPts
  const areaHa = _dozCalcGeomAreaHa(_dozPendingSavePolygon);
  const markingPayload = {
    id: _genUUID(),
    project_id: _dozSelId, created_by: sbUser.id,
    marking_type: _dozDrawType, label, note,
    boundary_geojson: _dozPendingSavePolygon,
    area_ha: areaHa, is_visible: true
  };
  try {
    // Bez veze se ne čeka mrežni poziv (na mrtvoj vezi do 15 s sa otvorenim
    // modalom) — zona ide lokalno i u red odmah.
    if (!_serverSlanjeDozvoljeno() || !_mrezaProbaj()) throw new Error('offline');
    const { error } = await _dozUpisiZonu(markingPayload);
    if (error) throw error;
    document.getElementById('doz-save-modal').style.display = 'none';
    _dozPendingSavePolygon = null;
    dozCancelDraw();
    showToast('✅ Zona sačuvana!');
    await dozLoadLayers(_dozSelId);
    dozRenderDetail();
  } catch(e) {
    // D4-B: pamti privremeni ID i uz payload u redu čekanja da kasnije brisanje
    // (prije nego se ovaj insert sinhronizuje) može ispravno pronaći/otkazati red.
    const localId = 'local_' + Date.now();
    if (!_OL.enqueue({ type: 'insert_doz_marking', payload: markingPayload, _localId: localId })) {
      showToast('⚠ Zona nije sačuvana u redu za slanje — oslobodi memoriju i pokušaj ponovo');
      return; // ostavi geometriju i modal otvorene za ponovni pokušaj/izvoz
    }
    // Dodaj u lokalni keš da se prikaže i offline
    _dozMarkings.unshift({ ...markingPayload, id: localId });
    _dozCacheLayers(_dozSelId);
    dozRenderMapLayers();
    dozRenderDetail();
    document.getElementById('doz-save-modal').style.display = 'none';
    _dozPendingSavePolygon = null;
    dozCancelDraw();
    showToast('💾 Zona sačuvana — kolegama ide kad je pošalješ (Meni → Server)');
  }
  } catch(e) {
    // v1.6.0: vanjski try je imao SAMO `finally` (reset zastavice), bez catch-a.
    // Unutrašnji try/catch hvata mrežni neuspjeh i sprema u red čekanja, ali sve
    // što pukne PRIJE njega — npr. `sbUser.id` kad sesija u međuvremenu nestane,
    // ili nedostajuće polje u DOM-u — izletjelo bi nečujno: modal ostane otvoren,
    // dugme "Sačuvaj" izgleda mrtvo (sljedeći tap samo ponovi isti pad), a
    // #tab-bar i #action-bar OSTAJU SAKRIVENI jer dozCancelDraw() nikad ne
    // stigne da se izvrši — korisnik ostane bez navigacije i bez objašnjenja.
    showToast('⚠ Zona nije sačuvana: ' + (e?.message || e));
    try { document.getElementById('doz-save-modal').style.display = 'none'; } catch(e2) {}
    // Isti ishod kao dozCancelSave: poligon se odbacuje (da zaostao
    // _dozPendingSavePolygon ne bi kasnije ušao u tuđi upis), a UI se vraća u
    // ispravno stanje. Uzrok je najčešće trajan do ponovne prijave, pa je
    // čist ekran korisniji od modala koji se ne da spasiti.
    _dozPendingSavePolygon = null;
    dozCancelDraw();   // vraća #tab-bar/#action-bar i čisti stanje crtanja
  } finally {
    _dozSaveInFlight = false;
  }
}

function _dozCalcArea(pts) {
  return _dozCalcGeomAreaHa({type:'Polygon',coordinates:[pts.map(p=>[p.lng,p.lat])]})*10000;
}

// ─── Delete Marking ────────────────────────────────────────────────
async function dozDeleteMarking(id) {
  const projectId=_dozSelId,owner=sbUser?.id;
  if (!await _dlgConfirm('Obriši obilježenu zonu?', { danger: true })) return;
  if(!owner||sbUser?.id!==owner||_dozSelId!==projectId)return;
  // D4-B: markica kreirana offline (još nema pravi server ID) — insert nikad nije stigao
  // na server, pa "brisanje" mora otkazati red čekanja umjesto da gađa nepostojeći ID.
  if (String(id).startsWith('local_')) {
    let q;try{q=_OL.loadQueue(true);}catch(e){showToast('⚠ Red za slanje nije čitljiv — zona nije uklonjena');return;}
    const queued = q.find(o => o.type === 'insert_doz_marking' && o._localId === id && (!o._uid||o._uid===owner));
    const hasQueued = !!queued;
    if (hasQueued) {
      try{localStorage.setItem(_OL.QUEUE, JSON.stringify(q.filter(o => !(o.type === 'insert_doz_marking' && o._localId === id && (!o._uid||o._uid===owner)))));}
      catch(e){showToast('⚠ Brisanje nije sačuvano — zona ostaje dostupna');return;}
      // Upis je već krenuo (možda stigao uz izgubljen odgovor) — zona ima
      // klijentski UUID, pa se briše tačno ona; nema je na serveru = čisto.
      if (queued._pokusano && queued.payload?.id &&
          !_OL.enqueue({ type: 'delete_doz_marking', payload: { id: queued.payload.id, project_id: projectId } })) {
        showToast('⚠ Brisanje nije sačuvano u redu — zona ostaje dostupna'); return;
      }
    }
    _dozMarkings = _dozMarkings.filter(m => m.id !== id);
    // Keš mora pratiti — inače se zona vrati pri sljedećem otvaranju bez signala.
    _dozCacheLayers(_dozSelId);
    dozRenderMapLayers();
    dozRenderDetail();
    showToast(hasQueued ? '🗑 Zona uklonjena (nikad nije stigla na server)' : '🗑 Zona uklonjena lokalno');
    return;
  }
  try {
    if (!_serverSlanjeDozvoljeno() || !_mrezaProbaj()) throw new Error('offline');
    const { error } = await sb.from('doz_area_markings').update({ is_visible: false }).eq('id', id).eq('project_id',projectId);
    if (error) throw error;
    showToast('🗑 Zona obrisana');
    if(sbUser?.id!==owner||_dozSelId!==projectId)return;
    await dozLoadLayers(projectId);
    if(sbUser?.id===owner&&_dozSelId===projectId)dozRenderDetail();
  } catch(e) {
    if(sbUser?.id!==owner)return;
    if(!_OL.enqueue({ type: 'delete_doz_marking', payload: { id,project_id:projectId } })){showToast('⚠ Brisanje nije sačuvano u redu — zona ostaje dostupna');return;}
    if(_dozSelId!==projectId)return;
    // Ranije je zona ostajala na karti i u kešu, pa je izgledalo da brisanje
    // nije uspjelo (i drugi tap je stavljao isto brisanje ponovo u red).
    _dozMarkings = _dozMarkings.filter(m => m.id !== id);
    _dozCacheLayers(_dozSelId);
    dozRenderMapLayers();
    dozRenderDetail();
    showToast('🗑 Zona uklonjena — kolegama nestaje kad pošalješ (Meni → Server)');
  }
}

// Član napušta doznaku; nikad se ne poziva brisanje projekta/zona/GPS podataka.
async function dozNapustiOdjel(projectId) {
  if(dozNapustiOdjel.busy)return;
  const owner=sbUser?.id,odjel=_dozOdjeli.find(o=>o.id===projectId);
  if(!owner||!odjel||odjel.created_by===owner||isReadOnly())return;
  if(_dozGpsOn||(_dozGpsStopping&&_dozGpsUserId)){showToast('Prvo završi GPS snimanje');return;}
  if(!_mrezaProbaj()){showToast('Uklanjanje članstva traži internet');return;}
  try {
    if(typeof FieldStore!=='undefined')await FieldStore.init();
    if(sbUser?.id!==owner||_dozSelId!==projectId)return;
    const points=typeof FieldStore!=='undefined'?FieldStore.view(owner):JSON.parse(localStorage.getItem(_DOZ_TRACK_BUF_KEY)||'[]');
    const pending=points.some(p=>p.user_id===owner&&p.project_id===projectId)||_OL.loadQueue(true).some(o=>(!o._uid||o._uid===owner)&&(o.payload?.project_id===projectId||o.type==='upsert_doz_status'&&o.payload?.id===projectId));
    if(pending){showToast('Prvo pošalji neposlane pojaseve i izmjene: Pošalji i primi');return;}
    if(!await _dlgConfirm('Ukloniti doznaku „'+odjel.name+'” sa tvog spiska? Pojasevi, zone i projekat ostaju kolegi i ostalim projektantima. Za povratak te vlasnik treba ponovo dodati.',{danger:true}))return;
    if(sbUser?.id!==owner||_dozSelId!==projectId||dozNapustiOdjel.busy)return;
    if(_dozGpsOn||(_dozGpsStopping&&_dozGpsUserId)||_serverSaljem){showToast('Prvo završi snimanje/slanje');return;}
    dozNapustiOdjel.busy=true;
    await _napustiClanPotvrdjeno('doz_project_members','project_id','user_id',projectId,owner);
    if(sbUser?.id!==owner)return;
    dozLoadOdjeli._gen=(dozLoadOdjeli._gen||0)+1;
    _dozOdjeli=_dozOdjeli.filter(o=>o.id!==projectId);_OL.save(_OL.DOZ_ODJELI,_dozOdjeli);
    if(_dozSelId===projectId)await dozBackToList();
    dozRenderOdjeli();_dozRenderOverview();await dozLoadOdjeli();
    if(sbUser?.id===owner)showToast('Doznaka uklonjena sa tvog spiska. Podaci tima su sačuvani.');
  }catch(e){if(sbUser?.id===owner)showToast('Uklanjanje nije uspjelo: '+e.message);}
  finally{dozNapustiOdjel.busy=false;}
}

// ─── Delete Odjel ──────────────────────────────────────────────────
async function dozDeleteOdjel() {
  if(dozDeleteOdjel.busy)return;
  const projectId=_dozSelId,owner=sbUser?.id;
  if(_dozGpsOn||(_dozGpsStopping&&_dozGpsUserId)){showToast('Prvo završi GPS snimanje');return;}
  const odjel = _dozOdjeli.find(o => o.id === _dozSelId);
  if (!odjel) return;
  if(odjel.created_by!==owner)return dozNapustiOdjel(projectId);
  // Samo kreator ili manager smije brisati — briše podatke cijelog tima
  const myRole = _dozMembers.find(m => m.user_id === sbUser?.id)?.role;
  const canDelete = odjel.created_by === sbUser?.id || myRole === 'manager';
  if (!canDelete) { showToast('Samo kreator/manager može obrisati odjel'); return; }
  // Brisanje cijelog tima traži vezu i jednu serversku transakciju.
  if (!_mrezaProbaj()) { showToast('📴 Brisanje odjela traži vezu — pokušaj kad bude signala'); return; }
  try{
    if(typeof FieldStore!=='undefined')await FieldStore.init();
    if(sbUser?.id!==owner || _dozSelId!==projectId)return;
    const points=typeof FieldStore!=='undefined' ? FieldStore.view(owner) : JSON.parse(localStorage.getItem(_DOZ_TRACK_BUF_KEY)||'[]');
    const pending=points.some(p=>p.user_id===owner&&p.project_id===projectId) || _OL.loadQueue(true).some(o=>(!o._uid||o._uid===owner)&&
      (o.payload?.project_id===projectId || ['insert_doz_project','upsert_doz_status'].includes(o.type)&&o.payload?.id===projectId));
    if(pending){showToast('Odjel ima neposlane podatke. Prvo koristi Pošalji i primi; brisanje nije započeto.');return;}
  }catch(e){showToast('Lokalni podaci nisu provjereni — brisanje nije započeto');return;}
  if (!await _dlgConfirm(`Obriši odjel "${odjel.name}"? Ovo nepovratno briše GPS tragove, zone i članstva za CIJELI tim.`, { danger: true })) return;
  if(sbUser?.id!==owner||_dozSelId!==projectId)return;
  if(dozDeleteOdjel.busy)return;
  dozDeleteOdjel.busy=true;
  try {
    // Jedna serverska transakcija: prekid/nepotvrđen odgovor čuva lokalni prikaz.
    const {data,error}=await sb.rpc('codex_delete_doz_project',{pid:projectId});
    if(sbUser?.id!==owner)return;
    if(error){
      if(error.code==='PGRST202')throw Error('Sigurno brisanje odjela još nije omogućeno na serveru. Administrator treba omogućiti sigurno brisanje odjela; nijedan podatak nije obrisan.');
      throw error;
    }
    if(data?.deleted!==true || data?.project_id!==projectId)throw Error('Server nije potvrdio brisanje odjela; lokalna kopija je sačuvana');
    showToast('🗑 Odjel obrisan');
    if(_dozSelId===projectId)await dozBackToList();
    await dozLoadOdjeli();
  } catch(e) { if(sbUser?.id===owner)showToast('Greška: ' + e.message); }
  finally{dozDeleteOdjel.busy=false;}
}

// ─── Create Odjel ─────────────────────────────────────────────────
function dozShowCreateOdjel(restore) {
  document.getElementById('doz-create-modal').style.display = 'flex';
  document.getElementById('doz-create-error').textContent = '';

  if (restore) {
    // Spasi sve prije nego render funkcije resetuju state
    const savedGj    = _dozNewOdjelDrawGj;
    const savedOdjel = _dozNewOdjelDrawOdjel;
    const savedAreaHa  = _dozCreateAreaHa;
    const savedBnd     = _dozCreateBoundary;

    _dozCreateRenderGjField(); // interno resetuje GJ/odjel — namjerno

    // Vrati sačuvane vrijednosti
    _dozCreateGj       = savedGj;
    _dozCreateOdjel    = savedOdjel;
    _dozCreateAreaHa   = savedAreaHa;
    _dozCreateBoundary = savedBnd;

    const gjEl    = document.getElementById('doz-create-gj');
    const odjelEl = document.getElementById('doz-create-odjel');
    if (gjEl)    gjEl.value    = savedGj;
    if (odjelEl) odjelEl.value = savedOdjel;

    if (savedBnd) {
      document.getElementById('doz-create-no-poly').style.display = 'none';
      document.getElementById('doz-create-poly-ok').style.display = 'block';
      document.getElementById('doz-create-poly-area').textContent =
        fmtHa(savedAreaHa);
    } else {
      document.getElementById('doz-create-poly-ok').style.display = 'none';
      document.getElementById('doz-create-no-poly').style.display = savedOdjel ? 'block' : 'none';
    }
    return;
  }

  // Svježi start
  _dozCreateFeatures = [];
  _dozCreateGj       = '';
  _dozCreateOdjel    = '';
  _dozCreateBoundary = null;
  _dozCreateAreaHa   = null;
  const st = document.getElementById('doz-gjson-status');
  st.textContent = 'Nije učitan GeoJSON fajl';
  st.style.color = '#475569';
  document.getElementById('doz-create-no-poly').style.display = 'none';
  document.getElementById('doz-create-poly-ok').style.display = 'none';
  _dozCreateRenderGjField();
}

function dozCloseCreateOdjel() {
  document.getElementById('doz-create-modal').style.display = 'none';
}

function dozCreateLoadGeojson(file) {
  if (!file) return;
  const reader = new FileReader();
  reader.onload = e => {
    try {
      const data = JSON.parse(e.target.result);
      if (!data.features?.length) { showToast('Fajl nema features'); return; }
      _dozCreateFeatures = data.features
        .filter(f => f.geometry)
        .map(f => ({
          gj:       (f.properties?.GJ      || f.properties?.gj      || '').trim(),
          odjel:    String(f.properties?.ODJEL   || f.properties?.odjel   || '').trim(),
          odsjek:   String(f.properties?.ODSJEK  || f.properties?.odsjek  || '').trim(),
          gazKlasa: String(f.properties?.Gaz_Klasa_ || f.properties?.GAZ_KLASA || '').trim(),
          geometry: f.geometry
        }))
        .filter(f => f.gj && f.odjel);
      const gjCount = new Set(_dozCreateFeatures.map(f => f.gj)).size;
      const st = document.getElementById('doz-gjson-status');
      st.textContent = `${_dozCreateFeatures.length} odsjeka · ${gjCount} GJ učitano`;
      st.style.color = '#4ade80';
      _dozCreateRenderGjField();
      showToast(`✅ GeoJSON: ${_dozCreateFeatures.length} odsjeka`);
    } catch(ex) { showToast('❌ GeoJSON greška: ' + ex.message); }
  };
  reader.readAsText(file);
}

function _dozCreateRenderGjField() {
  const wrap = document.getElementById('doz-create-gj-wrap');
  const gjSet = [...new Set(_dozCreateFeatures.map(f => f.gj))].sort();
  if (gjSet.length > 0) {
    wrap.innerHTML = `<select class="pinput" id="doz-create-gj" onchange="_dozCreateOnGjChange()">
      <option value="">— odaberi GJ —</option>
      ${gjSet.map(g => `<option value="${_escHtml(g)}">${_escHtml(g)}</option>`).join('')}
    </select>`;
  } else {
    wrap.innerHTML = `<input class="pinput" id="doz-create-gj" placeholder="npr. RISOVAC KRUPA" style="text-transform:uppercase" oninput="_dozCreateOnGjChange()">`;
  }
  _dozCreateGj = '';
  _dozCreateRenderOdjelField();
}

function _dozCreateOnGjChange() {
  _dozCreateGj     = (document.getElementById('doz-create-gj')?.value || '').trim();
  if(_dozCreateFeatures.length)_dozCreateOdjel='';
  else _dozCreateOdjel=(document.getElementById('doz-create-odjel')?.value||'').trim();
  if(_dozCreateFeatures.length){_dozCreateBoundary=null;_dozCreateAreaHa=null;}
  document.getElementById('doz-create-poly-ok').style.display = _dozCreateBoundary?'block':'none';
  if(_dozCreateFeatures.length)_dozCreateRenderOdjelField();
}

function _dozCreateRenderOdjelField() {
  const wrap = document.getElementById('doz-create-odjel-wrap');
  const odjeli = [...new Set(
    _dozCreateFeatures.filter(f => !_dozCreateGj || f.gj === _dozCreateGj).map(f => f.odjel)
  )].sort((a, b) => (parseInt(a)||0) - (parseInt(b)||0));
  if (odjeli.length > 0) {
    wrap.innerHTML = `<select class="pinput" id="doz-create-odjel" onchange="_dozCreateOnOdjelChange()">
      <option value="">— odaberi odjel —</option>
      ${odjeli.map(o => `<option value="${_escHtml(o)}">${_escHtml(o)}</option>`).join('')}
    </select>`;
  } else {
    wrap.innerHTML = `<input class="pinput" id="doz-create-odjel" placeholder="npr. 78" oninput="_dozCreateOnOdjelChange()">`;
  }
  _dozCreateOdjel = '';
  _dozCreateOnOdjelChange();
}

function _dozCreateOnOdjelChange() {
  _dozCreateOdjel = (document.getElementById('doz-create-odjel')?.value || '').trim();
  document.getElementById('doz-create-error').textContent = '';
  const noPoly = document.getElementById('doz-create-no-poly');
  const polyOk = document.getElementById('doz-create-poly-ok');

  if (!_dozCreateOdjel) {
    noPoly.style.display = 'none'; polyOk.style.display = 'none';
    return;
  }

  // Pokuša naći poligon iz učitanog GeoJSON-a (isključi Gaz_Klasa_ s '8000')
  const odsjeci = _dozCreateFeatures.filter(f =>
    (!_dozCreateGj || f.gj === _dozCreateGj) &&
    f.odjel === _dozCreateOdjel &&
    !f.gazKlasa.includes('8000')
  );

  if (odsjeci.length > 0) {
    _dozCreateBoundary = _dozMergeOdsjeci(odsjeci);
    _dozCreateAreaHa   = _dozCalcGeomAreaHa(_dozCreateBoundary);
    polyOk.style.display = 'block';
    document.getElementById('doz-create-poly-area').textContent = fmtHa(_dozCreateAreaHa);
    noPoly.style.display = 'none';
  } else if (_dozCreateBoundary) {
    // Granica ucrtana ručno
    polyOk.style.display = 'block'; noPoly.style.display = 'none';
  } else {
    noPoly.style.display = 'block'; polyOk.style.display = 'none';
  }
}

function _dozMergeOdsjeci(odsjeci) {
  if (odsjeci.length === 1) return odsjeci[0].geometry;
  const polys = [];
  for (const f of odsjeci) {
    const g = f.geometry;
    if (g.type === 'Polygon')      polys.push(g.coordinates);
    else if (g.type === 'MultiPolygon') g.coordinates.forEach(p => polys.push(p));
  }
  return polys.length === 1
    ? { type: 'Polygon', coordinates: polys[0] }
    : { type: 'MultiPolygon', coordinates: polys };
}

function _dozCalcGeomAreaHa(geom) {
  if (!geom) return 0;
  if(geom.type==='Feature')return _dozCalcGeomAreaHa(geom.geometry);
  const ringArea=ring=>{
    if(!Array.isArray(ring)||ring.length<3)return 0;
    const R=6371000,cos=Math.cos(ring[0][1]*Math.PI/180),origin=ring[0];
    let area=0;
    for(let i=0;i<ring.length;i++){
      const a=ring[i],b=ring[(i+1)%ring.length];
      const x1=(a[0]-origin[0])*Math.PI/180*R*cos,y1=(a[1]-origin[1])*Math.PI/180*R;
      const x2=(b[0]-origin[0])*Math.PI/180*R*cos,y2=(b[1]-origin[1])*Math.PI/180*R;
      area+=x1*y2-x2*y1;
    }
    return Math.abs(area)/20000;
  };
  const polygon=rings=>Math.max(0,ringArea(rings[0])-rings.slice(1).reduce((sum,ring)=>sum+ringArea(ring),0));
  if(geom.type==='Polygon')return polygon(geom.coordinates);
  if(geom.type==='MultiPolygon')return geom.coordinates.reduce((sum,rings)=>sum+polygon(rings),0);
  return 0;
}

let _dozNewBoundaryPrevious = null;
let _dozDrawEnabled = true;
const DOZ_DRAG_MIN_M = 8;
let _dozDragLastPt = null;

function dozStartNewBoundaryDraw() {
  _dozNewBoundaryPrevious = { boundary: _dozCreateBoundary, area: _dozCreateAreaHa };
  _dozNewOdjelDrawGj    = _dozCreateGj;
  _dozNewOdjelDrawOdjel = _dozCreateOdjel;
  dozCloseCreateOdjel();
  // switchTab PRIJE stanja crtanja — isti razlog kao u dozStartDraw: doznaka-izlazni
  // dozCancelDraw() bi obrisao _dozDrawType='__boundary__' I _dozCreateBoundary,
  // pa čak i ponovo otvorio create modal preko karte.
  switchTab('karta');
  _dozDrawType = '__boundary__';
  window.GithubLayers?.sync();
  _dozDrawPts  = [];
  _dozDrawEnabled = false;
  _dozDragLastPt = null;
  setTimeout(() => {
    document.getElementById('doz-draw-banner').style.display = 'flex';
    window.DoznakaBoundary?.invalidate();
    document.getElementById('doz-draw-type-label').textContent = `📐 Granica — odjel ${_dozNewOdjelDrawOdjel || 'novi projekat'}`;
    document.getElementById('doz-draw-count').textContent = '0 tačaka';
    const dtb = document.getElementById('doz-draw-toggle');
    if (dtb) { dtb.classList.remove('on'); const _ci = document.getElementById('doz-draw-check'); if (_ci) _ci.textContent = '☐'; }
    document.getElementById('map').style.cursor = '';
    if (_dozDrawLayer) { map.removeLayer(_dozDrawLayer); _dozDrawLayer = null; }
    document.getElementById('action-bar').style.display = 'none';
    document.getElementById('tab-bar').style.display = 'none';
    document.getElementById('map-center-dot').style.display = '';
    map.invalidateSize();
    showToast('📐 Čekiraj "Crtaj" pa pomjeraj mapu — ili dodaj tačke ručno');
  }, 50);
}

function dozStartKmlSel() { return DoznakaProjectBoundary.start(); }

function dozCancelKmlSel() { return DoznakaProjectBoundary.cancel(); }

function _dozKmlSelToggle(layer) { return DoznakaProjectBoundary.toggle(layer); }

function _dozKmlSelUpdateInfo() { return DoznakaProjectBoundary.update(); }

function _dozKmlLayerToGeoJSON(layer) {
  if (typeof layer.toGeoJSON === 'function') return layer.toGeoJSON();
  if (layer.getLatLngs) {
    const rings = layer.getLatLngs();
    const toCoords = ring => (Array.isArray(ring[0]) ? ring : [ring]).map(r =>
      (Array.isArray(r) ? r : [r]).map(p => [p.lng ?? p[1], p.lat ?? p[0]])
    );
    const coords = toCoords(rings);
    return { type: 'Feature', geometry: { type: 'Polygon', coordinates: coords } };
  }
  return null;
}

function dozConfirmKmlSel() { return DoznakaProjectBoundary.confirm(); }

function dozToggleDrawMode() {
  _dozDrawEnabled = !_dozDrawEnabled;
  const btn = document.getElementById('doz-draw-toggle');
  const ico = document.getElementById('doz-draw-check');
  btn.classList.toggle('on', _dozDrawEnabled);
  if (ico) ico.textContent = _dozDrawEnabled ? '☑' : '☐';
  if (_dozDrawEnabled) {
    _dozDragLastPt = null;
    map.on('move', _onDozDragMove);
    document.getElementById('main').classList.add('drawing-active');
    document.getElementById('main').classList.add('draw-drag-on');
  } else {
    map.off('move', _onDozDragMove);
    document.getElementById('main').classList.remove('drawing-active');
    document.getElementById('main').classList.remove('draw-drag-on');
  }
}

function _onDozDragMove() {
  if (!_dozDrawEnabled || _dozDrawType === null) return;
  const c = map.getCenter();
  if (_dozDragLastPt) {
    const d = dst(_dozDragLastPt.lat, _dozDragLastPt.lng, c.lat, c.lng);
    if (d < DOZ_DRAG_MIN_M) return;
  }
  _dozDragLastPt = { lat: c.lat, lng: c.lng };
  dozAddDrawPoint(c);
}

function _dozDrawCleanup() {
  window.DoznakaBoundary?.invalidate();
  map.off('move', _onDozDragMove);
  _dozDrawEnabled = false;
  _dozDragLastPt = null;
  document.getElementById('main').classList.remove('drawing-active');
  document.getElementById('main').classList.remove('draw-drag-on');
  _mcdRestoreVisibility();
}

function dozAddPointAtCenter() {
  const c = map.getCenter();
  dozAddDrawPoint(c);
  showToast(`📍 Tačka dodana (${_dozDrawPts.length})`);
}

async function dozSaveOdjel() {
  const gj    = (document.getElementById('doz-create-gj')?.value    || '').trim().toUpperCase();
  const odjel = (document.getElementById('doz-create-odjel')?.value || '').trim();
  const err   = document.getElementById('doz-create-error');
  if (!gj)    { err.textContent = 'Unesite GJ'; return; }
  if (!odjel) { err.textContent = 'Unesite odjel'; return; }
  if (!_dozCreateBoundary) { err.textContent = 'Ucrtaj granicu ili izaberi jedan ili više poligona iz sloja'; return; }
  err.textContent = '';

  const payload = {
    name: `${gj} · ${odjel}`,
    description: null,
    created_by: sbUser.id,
    boundary_geojson: _dozCreateBoundary,
    known_area_ha: _dozCreateAreaHa || null,
    status: 'active'
  };

  const id = _genUUID();
  payload.id = id;
  const novi = { ...payload, created_at: new Date().toISOString(), _pendingSync: true };
  if (!_OL.enqueue({ type: 'insert_doz_project', payload: { ...payload, _tempId: id } })) {
    err.textContent = 'Lokalni upis nije uspio. Odjel nije sačuvan; pokušaj ponovo.';
    return;
  }
  _dozOdjeli.unshift(novi);
  _OL.save(_OL.DOZ_ODJELI, _dozOdjeli);
  dozCloseCreateOdjel(); dozRenderOdjeli(); _dozRenderOverview();
  showToast('📋 Odjel sačuvan — automatsko slanje na server');
  _autoPosaljiNoveProjekte();

}

// ─── Add Member (šumarija lista) ──────────────────────────────────
async function dozAddMember() {
  const projectId=_dozSelId,owner=sbUser?.id;
  if (!await _projektServerSpreman('doznaka',projectId,owner) || sbUser?.id !== owner || _dozSelId !== projectId) return;
  try {
    const { data: me, error: eMe } = await sb.from('korisnici').select('sumarija').eq('id', sbUser.id).single();
    // Mrežna greška nije "nisi registrovan u šumariji" — ranije je poruka lagala.
    if (eMe && _isNetworkErr(eMe)) throw eMe;
    if (!me?.sumarija) { showToast('Nisi registrovan u šumariji'); return; }
    const { data: users, error: eUsers } = await sb.from('korisnici')
      // `*` — je_vodeci postoji tek nakon migracije 20260727 (vidi sbLoadKolege)
      .select('*').eq('sumarija', me.sumarija).neq('id', sbUser.id).order('prezime');
    if (eUsers) throw eUsers;
    if (!users?.length) { showToast('Nema projektanata u šumariji'); return; }
    const vecClanovi = new Set(_dozMembers.map(m => m.user_id));
    const dostupni = users.filter(u => !vecClanovi.has(u.id));
    if (!dostupni.length) { showToast('Svi projektanti su već dodani'); return; }
    if(sbUser?.id!==owner||_dozSelId!==projectId)return;
    _dozShowMemberPicker(dostupni);
  } catch(e) { showToast('Greška: ' + e.message); }
}

function _dozShowMemberPicker(users) {
  const existing = document.getElementById('doz-member-picker');
  if (existing) existing.remove();
  const rows = users.map(u => {
    const initials = ((u.ime||'')[0]||(u.prezime||'')[0]||'?').toUpperCase() +
                     ((u.prezime||'')[1]||'').toUpperCase();
    const color = u.boja || DOZ_ENG_COLORS[0];
    return `<div style="display:flex;align-items:center;gap:9px;padding:7px 0;border-bottom:1px solid #1e293b;">
      <div style="width:30px;height:30px;border-radius:50%;background:${color}22;border:1px solid ${color};
        display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;color:${color};flex-shrink:0;">${_escHtml(initials)}</div>
      <div style="flex:1;font-size:13px;color:#e2e8f0;">${_escHtml(u.ime||'')} ${_escHtml(u.prezime||'')}</div>
      <button onclick="_dozPickMember('${u.id}')" style="background:#166534;border:1px solid #4ade80;color:#4ade80;border-radius:7px;padding:5px 12px;font-size:12px;cursor:pointer;white-space:nowrap;">Dodaj</button>
    </div>`;
  }).join('');
  const modal = document.createElement('div');
  modal.id = 'doz-member-picker';
  modal.dataset.projectId=_dozSelId;modal.dataset.owner=sbUser?.id||'';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.75);display:flex;align-items:flex-end;justify-content:center;z-index:2000;padding:0 0 0 0;';
  modal.innerHTML = `<div style="background:#16213e;border:1px solid #1e3a5f;border-radius:14px 14px 0 0;padding:16px;width:100%;max-width:400px;max-height:70vh;max-height:70dvh;overflow-y:auto;">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;">
      <div style="font-size:14px;font-weight:700;color:#e2e8f0;">Dodaj projektanta</div>
      <button onclick="document.getElementById('doz-member-picker').remove()" style="background:none;border:none;color:#64748b;font-size:20px;cursor:pointer;padding:0 4px;"><svg class="ic"><use href="#ic-zatvori"/></svg></button>
    </div>
    <div style="font-size:11px;color:#475569;margin-bottom:10px;">Projektanti iz iste šumarije</div>
    ${rows}
  </div>`;
  modal.onclick = e => { if (e.target === modal) modal.remove(); };
  document.body.appendChild(modal);
}

async function _dozPickMember(userId) {
  const picker=document.getElementById('doz-member-picker'),projectId=picker?.dataset.projectId,owner=picker?.dataset.owner;
  picker?.remove();
  if(!projectId||sbUser?.id!==owner||_dozSelId!==projectId)return;
  if (_dozPickMember._busy) return;
  _dozPickMember._busy = true;
  try {
    if (!await _projektServerSpreman('doznaka',projectId,owner) || sbUser?.id !== owner || _dozSelId !== projectId) return;
    const { error } = await sb.from('doz_project_members').insert({
      project_id: projectId, user_id: userId, role:'engineer',
      track_color: DOZ_ENG_COLORS[_dozMembers.length % DOZ_ENG_COLORS.length],
      order_index: _dozMembers.length, is_active: true
    });
    if (error) { if (error.code==='23505') { showToast('Projektant je već član'); return; } throw error; }
    if(sbUser?.id!==owner||_dozSelId!==projectId)return;
    showToast('✅ Projektant dodan');
    await dozLoadLayers(projectId);
    if(sbUser?.id===owner&&_dozSelId===projectId)dozRenderDetail();
  } catch(e) { if (sbUser?.id === owner) showToast('Greška: ' + e.message); }
  finally { _dozPickMember._busy = false; }
}

// ─── Back to List ─────────────────────────────────────────────────
async function dozBackToList() {
  const owner=sbUser?.id, projectId=_dozSelId;
  if(_dozGpsOn){
    await dozStopGPS();
    if(_dozGpsOn){dozOpenGPSControls();return false;}
  }
  if(sbUser?.id!==owner || _dozSelId!==projectId)return false;
  closeDozQrScan();
  ++_dozLoadGen;
  _dozSelId = null;
  if(typeof DoznakaPlan!=='undefined')DoznakaPlan.reset();
  _OL.save(_OL.DOZ_SEL_ID, null);
  _dozSubProject(null);
  dozCancelDraw();
  if (_dozVlakeVisible) dozToggleVlake();   // toggle sam gasi flag i skida slojeve
  dozClearBuf();
  dozTreesClear();
  [_dozBoundaryLayer, _dozTracksLayer, _dozMarkingsLayer, _dozBandsLayer, _dozGpsTrackLayer].forEach(l => { if (l) map.removeLayer(l); });
  _dozBoundaryLayer = _dozTracksLayer = _dozMarkingsLayer = _dozBandsLayer = _dozGpsTrackLayer = null;
  document.getElementById('doz-panel-list').style.display   = 'flex';
  document.getElementById('doz-panel-detail').style.display = 'none';
  dozRenderOdjeli();
  _dozRenderOverview();
  return true;
}

// ─── HELP MODAL ───────────────────────────────────────────────────────────────
function showHelp() {
  const v=document.getElementById('help-app-version');if(v)v.textContent='DENDRO MAP · '+APP_VER;
  document.getElementById('help-modal').classList.add('open');
}
function closeHelp() {
  document.getElementById('help-modal').classList.remove('open');
}
let _helpTab = 'gen';
function helpTab(id, btn) {
  _helpTab = id;
  document.querySelectorAll('.help-tab').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  document.getElementById('help-body').scrollTop = 0;
  ['gen','vlake','doznaka','simboli'].forEach(t => {
    document.getElementById('help-pane-' + t).style.display = (t === id) ? '' : 'none';
  });
}
function toggleHelpSec(hdr) {
  const arrow = hdr.querySelector('.h-arrow');
  const body  = hdr.nextElementSibling;
  const open  = body.classList.toggle('open');
  hdr.setAttribute('aria-expanded', String(open));
  if (open) arrow.classList.add('open'); else arrow.classList.remove('open');
}

// === ANDROID APK DOWNLOAD BRIDGE ===
// WebView ne podržava <a download>.click() za blob: URL-ove.
// Interceptujemo klik i šaljemo podatke Android-u preko JavascriptInterface.
if (typeof AndroidDownload !== 'undefined') {
  (function() {
    const origClick = HTMLAnchorElement.prototype.click;
    HTMLAnchorElement.prototype.click = function() {
      if (this.download && this.href && this.href.startsWith('blob:')) {
        const filename = this.download || 'download';
        fetch(this.href).then(r => r.blob()).then(blob => {
          const reader = new FileReader();
          reader.onload = () => AndroidDownload.save(filename, reader.result);
          reader.readAsDataURL(blob);
        }).catch(() => origClick.call(this));
        return;
      }
      origClick.call(this);
    };
  })();
}


